/** Two-tone fill: a light fill + darker contour derived from one base hue. `mix`
 *  clamps the amount, so the defaults (0.7 toward white / 0.35 toward black) are safe. */
const WHITE = "#ffffff";
const BLACK = "#000000";
function twoToneFill(base: string, tint: number | undefined): string {
  return mix(base, WHITE, tint ?? 0.7);
}
function twoToneContour(base: string, shade: number | undefined): string {
  return mix(base, BLACK, shade ?? 0.35);
}

/**
 * Per-series confidence/data ellipses for an XY scatter — a covariance ellipse
 * around each series' plotted points (computed in pixel space, so non-uniform
 * axis scaling can't distort it). `data` mode = the points' spread; `mean` mode =
 * the confidence ellipse of the group mean (÷√n). Series with <3 points are skipped.
 */
function buildEllipses(plot: Plot, series: SeriesScene[]): EllipseSceneItem[] {
  const conf = plot.ellipse?.level ?? 0.95;
  const mode = plot.ellipse?.mode ?? "data";
  const k = plot.ellipse?.k ?? 2;
  const fillOpacity = plot.ellipse?.fillOpacity ?? 0.12;
  const borderWidth = plot.ellipse?.borderWidth ?? 1.5;
  const out: EllipseSceneItem[] = [];
  for (const s of series) {
    const pts = s.marks.map((m) => ({ x: m.cx, y: m.cy }));
    const n = Math.max(1, pts.length);
    // The covariance ellipse's semi-axis = nSigma · SD-along-axis, so each mode is
    // just a choice of nSigma: χ² scale for a confidence region, k for SD/SEM, ÷√n
    // for the two "of the mean" variants.
    const base = mode === "sd" || mode === "sem" ? k : chiSquareScale(conf);
    const nSigma = mode === "mean" || mode === "sem" ? base / Math.sqrt(n) : base;
    const e = covarianceEllipse(pts, nSigma);
    if (e) out.push({ id: s.id, ...e, color: s.color, fillOpacity, borderWidth });
  }
  return out;
}

export interface BuildPlotSceneOptions {
  width?: number;
  height?: number;
  xScale?: ScaleType;
  yScale?: ScaleType;
  /** Series palette (defaults to colourblind-safe Okabe-Ito). */
  palette?: readonly string[];
  /** Text width in px. `family` = the CSS font stack the text is drawn in; `buildPlotScene` passes the graph's own tick font
   *  so a Georgia label is measured in Georgia (measuring in another font lets wider numbers collide). */
  measure?: (text: string, fontPx: number, family?: string | null) => number;
  /** Override the auto data extent to a visible window (axis pan/zoom). */
  xDomain?: [number, number] | undefined;
  yDomain?: [number, number] | undefined;
  /** Fill the render box even for normally aspect-locked kinds (pie/radar/3-D): use
   *  independent rx/ry (elliptical) instead of centring a circle. Set only by the panel
   *  composer's uniform-sizing re-render — standalone charts leave this undefined (circle). */
  stretch?: boolean | undefined;
  /** The smallest a size-fitted text may be drawn, in the scene's px (default 8). The kinds that shrink their names to
   *  fill a small box (radar, chord, rose, 3-D scatter) stop here. A figure panel drawn at scale k passes 8 / k, so the
   *  text still reaches 8 px on screen; text fitted to 8 and then drawn at 0.7 would be 5.6 px. */
  minTextPx?: number | undefined;
  /** INTERNAL. How many times the significance-bracket headroom retry has already widened this
   *  figure's value axis. Bounds the loop; a caller must never pass it, because a non-zero value
   *  suppresses the one thing that makes room for a bracket stack. */
  bracketRetries?: number | undefined;
  /** INTERNAL. The top band (px) an outside-top legend has already been given, by the extra
   *  build pass at the choke point that adds it to the plot's top padding. Set on that second
   *  pass only, so it does not reserve again; a caller must never pass it. */
  topLegendBand?: number | undefined;
  /** INTERNAL. The room (px) a vertical-axis title at another angle was given by the extra build pass at
   *  the choke point, added to the plot's left / top padding. Set on that second pass only; a caller must
   *  never pass it. See `resolveAxisExtras` ▸ Title direction. */
  yTitleRoom?: { left: number; top: number; above?: boolean | undefined } | undefined;
  /** INTERNAL. The histogram builds its bars from a synthetic column table whose rows are the
   *  bins (real categories), so it must keep the row-as-category layout and must not pool per column
   *  the way a user's simple-column bar does. A caller must never set this on a real plot. */
  barRowsAreCategories?: boolean | undefined;
  /** INTERNAL. Extra data values the value axis must also cover, joined to the autoscale
   *  before it is rounded to nice ticks — the histogram passes the peak of a distribution curve
   *  it was asked to draw, so the curve is never clamped flat along the plot top. A user-pinned
   *  axis max still wins (applyRange). A caller must never set this on a real plot. */
  extraYValues?: readonly number[] | undefined;
  /** Resolve another datasheet by id, for `plot.overlays` (series borrowed from other tables).
   *  The live pane, export and panels pass the project's tables; a caller
   *  without a project (gallery cards, fixtures, tests) passes none and overlays are left out. */
  tables?: ((id: NodeId) => DataTable | undefined) | undefined;
  /** Resolve a user-built colour ramp by id, for a `custom:<id>` `GradRamp` (the project's
   *  `gradients` + anything the user library contributed). The live pane, export and panels
   *  pass the project's registry; a caller without one (gallery cards, fixtures, tests)
   *  passes none — built-in ramps still resolve, and a custom reference falls back to viridis
   *  with a warning in the scene. Mirrors the `tables` contract above. */
  gradients?: ((id: string) => Gradient | undefined) | undefined;
}

interface RawPoint {
  rowId: NodeId;
  rowNumber: number;
  dx: number;
  /** Plotted Y — the dataset mean (or geometric mean for geoSd). */
  dy: number;
  /** Error-bar reach in data space (low ≤ dy ≤ high); only used when hasError. */
  low: number;
  high: number;
  hasError: boolean;
  /** Replicate count for the row (tooltip + n=1 suppression). */
  n: number;
  /** Symmetric X-error magnitude (± in data space) for the shared X-error subcolumn; absent = none. */
  xErr?: number;
}

/** Default CI level for plotted error bars (95%). */
const ERROR_CONF = 0.95;

/** Resolve a series' fill paint (solid / pattern / gradient / metallic / special) from its style. */
function resolveFill(style: SeriesStyle | undefined, baseFill: string): FillSpec {
  const type = style?.fillType ?? "solid";
  if (type === "twotone") return { type: "solid", color: twoToneFill(baseFill, style?.twoToneTint) };
  if (type === "pattern") {
    const bg = style?.patternBg && style.patternBg !== "none" ? style.patternBg : null;
    const scale = Math.min(4, Math.max(0.4, style?.patternScale ?? 1));
    return { type: "pattern", pattern: style?.pattern ?? "hatch", color: style?.patternColor ?? baseFill, bg, scale };
  }
  if (type === "gradient") {
    return { type: "gradient", from: baseFill, to: style?.gradientTo ?? baseFill, angle: style?.gradientAngle ?? 90 };
  }
  if (type === "metallic") return { type: "metallic", kind: style?.metallic ?? "silver" };
  if (type === "special") return { type: "special", kind: specialKindOf(style?.special) };
  return { type: "solid", color: baseFill };
}

/**
 * Value-graduated fill: shade each mark by a value mapped through a ramp/colormap
 * (e.g. low concentration → light, high → dark). `entries` pairs each mark with
 * its mapping value; normalised across the set, then `rampColor` paints it. No-op
 * unless the style requests `fillType: "graduated"`.
 */
function paintGraduated(
  entries: { mark: MarkScene; v: number }[],
  style: SeriesStyle | undefined,
  baseColor: string,
  domain: number[] | undefined,
  ramps: RampResolver,
): void {
  if (style?.fillType !== "graduated" || entries.length === 0) return;
  const ramp = style.gradRamp ?? "lightness";
  const reversed = style.gradReversed ?? false;
  const to = style.gradTo ?? "#1a1a1a";
  const finite = (domain ?? entries.map((e) => e.v)).filter((v) => Number.isFinite(v));
  let lo = style.gradMin ?? (finite.length ? Math.min(...finite) : 0);
  let hi = style.gradMax ?? (finite.length ? Math.max(...finite) : 1);
  if (!(hi > lo)) hi = lo + 1; // degenerate (single value) → uniform ramp start
  const opacityRamp = ramp === "transparency" || ramp === "lightness-transparency";
  const paint = ramps.ramp(ramp, baseColor, to, reversed, {
    midpointValue: style.gradMidpoint, gamma: style.gradGamma, steps: style.gradSteps,
    space: style.gradSpace, lo, hi, values: finite,
  });
  for (const { mark, v } of entries) {
    const t = Number.isFinite(v) ? (v - lo) / (hi - lo) : 0;
    const p = paint(t);
    mark.fill = p.color;
    // The two built-in "transparency" ramps vary alpha; so can a custom gradient's stop alpha
    // or opacity curve. A built-in colormap always returns 1, so this stays a no-op for them.
    if (opacityRamp || p.opacity !== 1) mark.fillOpacity = p.opacity;
  }
}

/**
 * Apply per-point style overrides ("Format this point" — highlighting). For each
 * series mark whose `${seriesId}:${rowId}` has an override, layer its colour (and
 * per-point fill-opacity) on top of the series paint. Runs at the choke point over
 * every chart kind; a no-op when `plot.pointStyles` is empty.
 */
// Per-mark override keys that change the fill shape (pattern/gradient/metallic/
// special) — when any is present a per-mark FillSpec is resolved (bars only set
// these). Plain colour/opacity overrides keep the lightweight path below.
const FILL_SHAPE_KEYS: (keyof SeriesStyle)[] = ["fillType", "twoToneTint", "twoToneShade", "pattern", "patternScale", "patternColor", "patternBg", "gradientTo", "gradientAngle", "metallic", "special"];
/**
 * Focus — draw the chosen series in their own colours and everything else in grey.
 *
 * The figure that says "this group is the point, the rest is context". The common alternative is hiding the other series, which throws the
 * evidence away: a reader cannot tell whether a missing curve was flat, absent, or never
 * measured. Greying keeps every curve on the page and says only which one the figure is about.
 *
 * Nothing changes until a series is focused. With no series carrying `focus` this is a
 * no-op, so an existing figure is untouched and switching the last focus off restores the plot
 * exactly — that is the one click that undoes it.
 *
 * Runs after `paintPointStyles`, so it greys a per-point "Format this point" colour too.
 * That is the right order: the purpose is that a background series recedes, and a
 * highlighted point inside one would defeat it. The focused series keep every per-point colour
 * they were given.
 */
const FOCUS_GREY = "#9aa0a6";
/** How far a de-emphasised colour is pulled towards the grey. 0.85 leaves a whisper of the
 *  original hue — enough that two background curves crossing are still separable, not enough
 *  to compete with the focused ones. A flat identical grey would make overlapping background
 *  series read as one line. */
const FOCUS_MIX = 0.85;

function applyFocus(plot: Plot, scene: PlotScene): void {
  const styles = plot.seriesStyles;
  if (!styles) return;
  const focused = new Set(Object.entries(styles).filter(([, v]) => v?.focus).map(([id]) => id));
  if (focused.size === 0) return;
  const g = (c: string): string => mix(c, FOCUS_GREY, FOCUS_MIX);
  /**
   * Every colour channel the series has, enumerated from `SeriesScene` rather than guessed.
   * Greying only `color`, the fill and the line is not enough: a marker paints from the
   * series' own `symbolFillColor` / `symbolOutline` and the legend swatch copies the marker, so
   * both would stay in full colour. Half-grey is worse than not greying at all: it reads as a bug.
   */
  const dim = (ser: SeriesScene): void => {
    if (ser.color != null) ser.color = g(ser.color);
    if (ser.lineColor != null) ser.lineColor = g(ser.lineColor);
    if (ser.symbolOutline != null) ser.symbolOutline = g(ser.symbolOutline);
    if (ser.symbolFillColor != null) ser.symbolFillColor = g(ser.symbolFillColor);
    if (ser.pointColor != null) ser.pointColor = g(ser.pointColor);
    if (ser.pointLabelColor != null) ser.pointLabelColor = g(ser.pointLabelColor);
    if (ser.errorColor != null) ser.errorColor = g(ser.errorColor);
    if (ser.fillColor != null) ser.fillColor = g(ser.fillColor);
    if (ser.borderColor != null) ser.borderColor = g(ser.borderColor);
    if (ser.whiskerColor != null) ser.whiskerColor = g(ser.whiskerColor);
    if (ser.medianColor != null) ser.medianColor = g(ser.medianColor);
    if (ser.bandColor != null) ser.bandColor = g(ser.bandColor);
    if (ser.bandEdgeColor != null) ser.bandEdgeColor = g(ser.bandEdgeColor);
    for (const b of ser.levelBands ?? []) b.color = g(b.color);
    // The resolved fill descriptor — a pattern, a gradient or a spectrum carries its own
    // colours and would otherwise stay vivid under a greyed `fillColor`.
    const fs = ser.fillSpec;
    if (fs.type === "solid") ser.fillSpec = { ...fs, color: g(fs.color) };
    else if (fs.type === "pattern") ser.fillSpec = { ...fs, color: g(fs.color), bg: fs.bg == null ? fs.bg : g(fs.bg) };
    else if (fs.type === "gradient") ser.fillSpec = { ...fs, from: g(fs.from), to: g(fs.to) };
    else if (fs.type === "axisGradient") ser.fillSpec = { ...fs, stops: fs.stops.map((st) => ({ ...st, color: g(st.color) })) };
    // "metallic" and "special" name a canned paint rather than carrying colours, so they cannot
    // be greyed here. Reported below rather than left as a silent full-colour patch.
    for (const m of ser.marks) {
      if (m.fill != null) m.fill = g(m.fill);
      if (m.symbolOutline != null) m.symbolOutline = g(m.symbolOutline);
      if (m.symbolFillColor != null) m.symbolFillColor = g(m.symbolFillColor);
      if (m.borderColor != null) m.borderColor = g(m.borderColor);
    }
  };

  /**
   * A focus on a series this chart does not draw would grey everything and highlight nothing —
   * a plot gone uniformly flat with no clue why. This is reachable in normal use: ROC,
   * survival and Bland-Altman key their series by synthetic ids (`roc-0`, `surv-0`), so a focus
   * set on a column and then a switch of chart type leaves the flag pointing at a series that no
   * longer exists.
   *
   * Nothing is dimmed in that case — the chart is drawn in its own colours — and the scene says
   * which focus could not be honoured.
   */
  const live = scene.series.filter((ser) => focused.has(ser.id));
  if (scene.series.length > 0 && live.length === 0) {
    scene.warnings.push(
      "The series set to be in focus are not on this chart, so nothing is highlighted and nothing is greyed. This usually means the chart type changed after the focus was set — focus a series from the list to use it again.",
    );
    return;
  }

  let dimmed = 0;
  const cannotGrey: string[] = [];
  for (const ser of scene.series) {
    if (focused.has(ser.id)) continue;
    dimmed++;
    if (ser.fillSpec.type === "metallic" || ser.fillSpec.type === "special") cannotGrey.push(ser.name);
    dim(ser);
  }
  // The key must agree with the drawing. A legend row still painted in the series' original
  // colour keys a colour that is no longer anywhere on the chart.
  for (const row of scene.legend) {
    if (row.select?.as === "series" && !focused.has(row.select.id)) row.color = g(row.color);
  }
  for (const row of scene.legendLayout.directEntries ?? []) {
    if (row.select?.as === "series" && !focused.has(row.select.id)) row.color = g(row.color);
  }
  /**
   * A focus that changes nothing is a dead setting. Everything focused means nothing is greyed,
   * and the user is looking at an unchanged plot wondering why the control did nothing.
   */
  if (dimmed === 0) {
    scene.warnings.push(
      "Every series on this chart is focused, so nothing is greyed out. Focus fewer series to push the rest into the background.",
    );
  }
  if (cannotGrey.length > 0) {
    scene.warnings.push(
      `${cannotGrey.join(", ")} ${cannotGrey.length === 1 ? "keeps its" : "keep their"} metallic or textured fill when greyed out — that fill is a fixed paint, not a colour, so it cannot be muted. Give ${cannotGrey.length === 1 ? "it" : "them"} a plain fill to push ${cannotGrey.length === 1 ? "it" : "them"} into the background.`,
    );
  }
}

function paintPointStyles(plot: Plot, scene: PlotScene): void {
  const overrides = plot.pointStyles;
  if (!overrides || Object.keys(overrides).length === 0) return;
  for (const series of scene.series) {
    const sStyle = plot.seriesStyles?.[series.id];
    for (const mark of series.marks) {
      const o = overrides[`${series.id}:${mark.rowId}`];
      if (!o) continue;
      // What the builder already decided for this one mark, read before any override lands.
      const builtSolid = mark.symbolFill === "solid";
      const c = o.color ?? o.fillColor; // points use `color`, bars/box/violin use `fillColor`
      if (c !== undefined) mark.fill = c;
      // A point-colour override must also recolour an open / clear marker, whose visible
      // colour is its outline (not the fill); an explicit `symbolOutline` below still wins.
      if (o.color !== undefined) mark.symbolOutline = o.color;
      if (o.fillOpacity !== undefined) mark.fillOpacity = o.fillOpacity;
      // A single bar can carry its own fill shape + contour. Merge the series style
      // with the override and re-resolve the fill spec for this one mark.
      if (FILL_SHAPE_KEYS.some((k) => o[k] !== undefined)) {
        const merged = { ...(sStyle ?? {}), ...o } as SeriesStyle;
        const base = merged.fillColor ?? series.fillColor;
        mark.fillSpec = resolveFill(merged, base);
        // Two-tone derives the contour too (a darker shade of this bar's base hue),
        // unless the override pins an explicit contour colour.
        if (merged.fillType === "twotone" && o.borderColor === undefined) mark.borderColor = twoToneContour(base, merged.twoToneShade);
      }
      if (o.borderColor !== undefined) mark.borderColor = o.borderColor;
      if (o.borderWidth !== undefined) mark.borderWidth = o.borderWidth;
      // Per-bar value label: override text + drag nudge.
      if (o.valueText !== undefined) mark.valueText = o.valueText;
      if (o.valueDx !== undefined) mark.valueDx = o.valueDx;
      if (o.valueDy !== undefined) mark.valueDy = o.valueDy;
      // Per-point symbol overrides (XY / scatter marks): shape / size / fill / opacity / outline.
      if (o.pointColor !== undefined) mark.pointColor = o.pointColor;
      if (o.symbol !== undefined) mark.symbol = o.symbol;
      if (o.symbolSize !== undefined) mark.symbolSize = o.symbolSize;
      if (o.symbolFill !== undefined) mark.symbolFill = o.symbolFill;
      if (o.symbolOpacity !== undefined) mark.symbolOpacity = o.symbolOpacity;
      if (o.symbolOutline !== undefined) mark.symbolOutline = o.symbolOutline;
      if (o.symbolFillColor !== undefined) mark.symbolFillColor = o.symbolFillColor;
      // Per-point two-tone marker: derive the open interior + darker outline from this
      // point's base hue (its colour override, else the series colour), unless pinned.
      //
      // Note: keyed on the effective fill mode, not on `o.symbolFill` alone. Two-tone is the
      // house default, so it usually comes from the series and a per-point recolour never
      // restates it. Keying on the override alone would skip this block, leaving the series'
      // tint as the interior while the new colour above becomes the outline: a mismatched
      // marker that reads as "changing the colour does nothing" in two-tone while working in
      // every other fill mode.
      //
      // A mark the builder drew solid stays solid unless this point asks for two-tone. A
      // colour-from-a-column binding (ternary, funnel, xy...) paints each dot a solid disc of its
      // data colour on purpose; falling through to the series' two-tone would repaint the one
      // formatted dot pale with a dark edge while its neighbours stay solid — even when only its
      // size changed.
      if ((o.symbolFill ?? (builtSolid ? "solid" : sStyle?.symbolFill)) === "twotone") {
        /*
         * `mark.fill` before `series.color`. A volcano's marks carry their significance-zone
         * hue, not the series colour, and re-deriving from the series would mean that formatting
         * one point — changing anything at all, even its size — silently drops that point out of
         * its zone while its neighbours keep theirs. The zone hue is the entire message of a
         * volcano; an empty override `{}` is enough to reach this branch.
         *
         * The chain reads as it should: this point's own colour, then whatever the point is
         * actually drawn in, then the series'.
         */
        // `pointColor` first: it is what a clicked dot's Colour writes (column scatter, estimation, a bar series'
        // points). Without it in this chain, a recoloured dot's interior and edge are worked out from the series
        // colour, and since the renderer draws exactly these for a dot with its own colour, the colour would never
        // reach the page.
        const base = o.pointColor ?? o.color ?? o.fillColor ?? mark.fill ?? series.color;
        mark.symbolFill = "open";
        if (o.symbolFillColor === undefined) mark.symbolFillColor = twoToneFill(base, o.twoToneTint ?? sStyle?.twoToneTint);
        // `twoToneEdge` is the "Custom edge colour" pin — offered on the per-point panel too,
        // and in the Inspector's POINT_KEYS, so it lands in `pointStyles`. Reading only
        // `twoToneShade` here would make that control inert and discard a series-level pin the
        // moment any per-point override exists. Same precedence as the series path.
        if (o.symbolOutline === undefined)
          mark.symbolOutline = o.twoToneEdge ?? sStyle?.twoToneEdge ?? twoToneContour(base, o.twoToneShade ?? sStyle?.twoToneShade);
      }
    }
  }
}

// --- data-driven per-point formatting (colour / symbol / label from a column) ------
// "Plot symbol from a column" / bubble colour-mapping. Resolved at the choke
// point over xy / area / bubble marks (each = one table row), before paintPointStyles
// so a manual "Format this point" override still wins over the column binding.

/** Kinds whose marks are one-per-row markers → data-driven per-point formatting applies.
 *  The Inspector offers the Colour / Symbol by data rows from this same list (one list, never two). */
export const DATA_DRIVEN_KINDS: ReadonlySet<string> = new Set<string>(["xy", "area", "bubble", "funnel", "ternary",
  // swimmer: event glyphs are one-per-row marks, and the Start dataset's categorical
  // colour binding paints the bars (resolved in its builder with these same helpers)
  "swimmer"]);

/** The id of a waffle's combined small groups (`plot.waffleMaxGroups`): its cells, legend row,
 *  selection and `seriesStyles` key. Not a table row, so it can never collide with one. */
export const WAFFLE_OTHER_ID = "__waffle_other__";
/** The combined group's colour until the user picks one: a neutral grey, so it reads as the rest. */
export const WAFFLE_OTHER_COLOR = "#9e9e9e";
/**
 * Shapes an icon-array waffle (`plot.waffleIcons`) gives its categories, in category order.
 * Filled shapes only (plus/cross are stroked glyphs and read as thin lines inside a cell), and
 * the first four are unmistakable at a glance: round · pointed · flat-sided · rotated. The
 * Inspector shows the same default, so it reads this list too.
 */
export const WAFFLE_ICON_CYCLE: readonly SymbolShape[] = ["circle", "triangle", "square", "diamond", "star", "triangle-down", "hexagon", "octagon", "pentagon"];

/** Distinct-value → symbol cycle for `symbolFromColumn` (14 shapes, then repeats). The ten common
 *  marker shapes come first, so a chart with up to ten categories uses only those; ring ·
 *  squircle · oval · waffle follow. */
const DD_SYMBOL_CYCLE: SymbolShape[] = ["circle", "square", "triangle", "diamond", "triangle-down", "star", "hexagon", "pentagon", "plus", "cross", "ring", "squircle", "oval", "waffle"];

/** A cell's category key: trimmed text, or null when blank (blank rows keep the series style). */
function ddCellKey(cell: CellValue | undefined): string | null {
  if (cell === null || cell === undefined) return null;
  const s = String(cell).trim();
  return s.length ? s : null;
}

/**
 * The datasets a user has not hidden.
 *
 * Filters at the source. `seriesStyles[id].hidden` is written by the Inspector's series
 * visibility list on every chart kind. The builders outside the XY path read their datasets
 * through this helper so the checkbox takes effect there too: bar, box, violin, scatter,
 * raincloud, floating bar, estimation, forest, Bland-Altman, pyramid, the three PCA kinds,
 * scree, dendrogram, before-after, ridgeline, survival and ROC.
 *
 * Filtering the datasets rather than the finished scene keeps the result consistent: the
 * series, the legend entries and the axis domain are all derived from this list. Post-filtering
 * `scene.series` would leave a legend entry for a series that is no longer drawn and an axis
 * still scaled to its values.
 *
 * Note: `buildPlotSceneInner` (xy/area/bubble) deliberately does not use this: it keeps hidden
 * series in the computation so they still feed the spread band and the average line, and drops
 * them at the drawing step instead.
 */
function visibleDatasets(table: DataTable, plot: Plot): ReturnType<typeof tableDatasets> {
  return tableDatasets(table).filter((d) => !plot.seriesStyles?.[d.id]?.hidden);
}

/** Distinct non-blank values of a column, in first-appearance (row) order. */
function ddCategories(table: DataTable, colId: NodeId): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const row of table.rows) {
    const k = ddCellKey(row.cells[colId]);
    if (k !== null && !seen.has(k)) {
      seen.add(k);
      out.push(k);
    }
  }
  return out;
}

/** Does a column read as numeric (≥80% of non-blank cells parse to finite numbers)? */
function ddLooksNumeric(table: DataTable, colId: NodeId): boolean {
  let numeric = 0;
  let total = 0;
  for (const row of table.rows) {
    const k = ddCellKey(row.cells[colId]);
    if (k === null) continue;
    total++;
    if (Number.isFinite(Number(k))) numeric++;
  }
  return total > 0 && numeric / total >= 0.8;
}

/** Resolve whether a colour column maps continuously (a ramp) or by category (a palette). Exported so the gallery's
 *  Colour ramp control writes a ramp only where one is drawn (`GalleryPane.withRamp`). */
export function ddColorMode(st: SeriesStyle, table: DataTable, colId: NodeId): "continuous" | "category" {
  const m = st.colorFromMode ?? "auto";
  if (m === "continuous" || m === "category") return m;
  const col = table.columns.find((c) => c.id === colId);
  if (col && (col.type === "text" || col.type === "categorical")) return "category";
  return ddLooksNumeric(table, colId) ? "continuous" : "category";
}

/** Min/max of a numeric column's finite values (the continuous-ramp domain). */
/** Every finite value in a column — what quantile classes need (the range is not enough). */
function ddValues(table: DataTable, colId: NodeId): number[] {
  const out: number[] = [];
  for (const row of table.rows) {
    const v = toNumber(row.cells[colId]);
    if (Number.isFinite(v)) out.push(v);
  }
  return out;
}

function ddDomain(table: DataTable, colId: NodeId): [number, number] {
  let lo = Infinity;
  let hi = -Infinity;
  for (const row of table.rows) {
    const v = toNumber(row.cells[colId]);
    if (Number.isFinite(v)) {
      if (v < lo) lo = v;
      if (v > hi) hi = v;
    }
  }
  return lo <= hi ? [lo, hi] : [0, 1];
}

/** Compact numeric format for point labels / continuous-legend ticks (trims zeros). */
function ddFmt(v: number): string {
  if (!Number.isFinite(v)) return "";
  return String(Number(v.toPrecision(4)));
}

/** The text for a data-driven point label (mode ≠ "none"). */
function ddPointLabel(
  mode: "x" | "y" | "col",
  st: SeriesStyle,
  row: { cells: Record<NodeId, CellValue> } | undefined,
  mark: MarkScene,
): string {
  if (mode === "x") return ddFmt(mark.dx);
  if (mode === "y") return ddFmt(mark.dy);
  const col = st.pointLabelColumn;
  const cell = col && row ? row.cells[col] : undefined;
  if (cell === null || cell === undefined) return "";
  return typeof cell === "number" ? ddFmt(cell) : String(cell);
}

/**
 * Apply data-driven colour / symbol / label bindings to each xy/area/bubble series'
 * marks from a table column's per-row value. A no-op without bindings; runs before
 * `paintPointStyles` so an explicit per-point override still wins.
 */
/** Force a mark to read as a solid disc of its data colour `c` — fill, outline, and (crucially)
 *  the symbol fill mode, so a per-point colour beats a two-tone / open marker (which would otherwise
 *  tint every point from the series colour and hide the value). */
function paintMarkColour(mark: MarkScene, c: string): void {
  mark.fill = c;
  mark.symbolOutline = c;
  mark.symbolFill = "solid";
  mark.symbolFillColor = c;
}

/**
 * The data, as boxes a label must not sit on: every mark as a disc, and every connecting line
 * as a chain along its own marks (a label placed on a series' line reads as if it belonged to
 * the line rather than to a point).
 *
 * Shared by both label passes below — the point labels and the direct series labels place
 * against exactly the same picture, so they can never disagree about where the ink is.
 */
/**
 * The guide lines of a figure as label obstacles - a volcano's thresholds, a y = x identity, an origin cross-hair,
 * a user's reference line. Shared by the point-label and direct-label passes, so a series name is not printed
 * across a line (for example a series name over an LOD line).
 * With `captions`, each line's own caption box too, so a name does not land on the line's label.
 */
export function guideLineObstacles(scene: PlotScene, captions?: { measure: (t: string, px: number) => number }): LabelRect[] {
  const out: LabelRect[] = [];
  for (const a2 of scene.annotations) {
    if ((a2.kind === "line" || a2.kind === "segment") && a2.x1 != null && a2.y1 != null && a2.x2 != null && a2.y2 != null) {
      out.push(...segmentObstacles(a2.x1, a2.y1, a2.x2, a2.y2, Math.max(3, (a2.width ?? 1) * 2)));
      if (captions && a2.label && a2.labelX != null && a2.labelY != null) {
        const px = a2.fontSize ?? scene.fonts.legend.size;
        const w = captions.measure(a2.label, px);
        const x = a2.labelX + (a2.labelOffset?.dx ?? 0);
        const y = a2.labelY + (a2.labelOffset?.dy ?? 0);
        const x1 = a2.labelAnchor === "end" ? x - w : a2.labelAnchor === "middle" ? x - w / 2 : x;
        out.push({ x1, y1: y - px, x2: x1 + w, y2: y + px * 0.25 });
      }
    }
  }
  return out;
}

/** Text ink that reads on a fill: near-black on a light colour, white on a dark one. Shared by every label drawn on
 *  a coloured shape (heatmap and correlation cells, treemap tiles, pie slices); `fallback` for a colour it cannot read. */
export function contrastInk(hex: string, fallback = "#111"): string {
  const m = /^#?([\da-f]{6})$/i.exec(hex);
  if (!m) return fallback;
  const n = parseInt(m[1]!, 16);
  const lum = (0.299 * ((n >> 16) & 255) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) / 255;
  return lum > 0.6 ? "#111" : "#fff";
}

/**
 * The user's text notes as label obstacles. A note sits where the user put it; a point label placed without seeing it
 * can land on it.
 * Shared by the point-label and direct-label passes. The box is the note's ink: measured width, capitals and ascenders
 * up to 0.75 of the size above the baseline, descenders 0.25 below. A full font size above would over-reach: a label a
 * few pixels clear of the note would count as touching it and be moved off its own dot. A turned note takes the upright
 * box that holds it.
 */
export function textNoteObstacles(scene: PlotScene, measure: (t: string, px: number) => number): LabelRect[] {
  const out: LabelRect[] = [];
  for (const a of scene.annotations) {
    if (a.kind !== "text" || !a.label || a.labelX == null || a.labelY == null) continue;
    const px = a.fontSize ?? scene.fonts.legend.size;
    const w = measure(a.label, px);
    const x1 = a.labelAnchor === "end" ? a.labelX - w : a.labelAnchor === "middle" ? a.labelX - w / 2 : a.labelX;
    const box = { x1, y1: a.labelY - px * 0.75, x2: x1 + w, y2: a.labelY + px * 0.25 };
    if (!a.rotation) { out.push(box); continue; }
    const t = (a.rotation * Math.PI) / 180;
    const c = Math.cos(t), s = Math.sin(t);
    const turned = [[box.x1, box.y1], [box.x2, box.y1], [box.x1, box.y2], [box.x2, box.y2]].map(([x, y]) => {
      const dx = x! - a.labelX!, dy = y! - a.labelY!;
      return [a.labelX! + dx * c - dy * s, a.labelY! + dx * s + dy * c] as const;
    });
    out.push({
      x1: Math.min(...turned.map((q) => q[0])), y1: Math.min(...turned.map((q) => q[1])),
      x2: Math.max(...turned.map((q) => q[0])), y2: Math.max(...turned.map((q) => q[1])),
    });
  }
  return out;
}

function markObstacles(scene: PlotScene): LabelRect[] {
  const obstacles: LabelRect[] = [];
  for (const s of scene.series) {
    for (const m of s.marks) {
      // A bar is drawn as its rectangle, and its dots as a swarm at `swarmDotRadius` — not as one marker
      // of the full symbol size at (cx, cy). That disc would stand for ink that is not drawn (far larger than
      // the small swarm dots) and move a label such as a zone name off a spot that touches nothing.
      if (m.bar) obstacles.push({ x1: m.bar.x, y1: m.bar.y, x2: m.bar.x + m.bar.w, y2: m.bar.y + m.bar.h });
      if (m.points) {
        const pr = swarmDotRadius(s.symbolSize) + 1;
        for (const p of m.points) obstacles.push(discObstacle(p.cx, p.cy, pr));
      }
      if (m.bar || m.points) continue;
      const r = Math.max(2, (m.symbolSize ?? s.symbolSize ?? 4)) + 1;
      obstacles.push(discObstacle(m.cx, m.cy, r));
    }
    if (s.linePath && s.marks.length > 1) {
      for (let i = 1; i < s.marks.length; i++) {
        obstacles.push(...segmentObstacles(s.marks[i - 1]!.cx, s.marks[i - 1]!.cy, s.marks[i]!.cx, s.marks[i]!.cy, 3));
      }
    }
  }
  return obstacles;
}

/**
 * The placement rule for point labels. A gene name on a volcano or a value beside a scatter
 * dot drawn at a fixed offset — always the same side, whatever is already there — lands, with
 * more than a handful of labelled points, on other labels, on neighbouring dots and on the
 * connecting line. This pass places each label clear of those instead.
 *
 * Runs at the choke point, after every builder has produced its marks, so one pass covers
 * every kind that draws them (xy · area · bubble · volcano).
 *
 * The user's own drag (`valueDx`/`valueDy`) is left untouched: the renderer adds it on top of
 * the placement, so a label the user moved stays exactly where they put it.
 */
function placePointLabels(scene: PlotScene, measure: (t: string, px: number) => number): void {
  const labelled: { series: SeriesScene; mark: MarkScene }[] = [];
  for (const s of scene.series) for (const m of s.marks) if (m.pointLabel) labelled.push({ series: s, mark: m });
  if (labelled.length === 0) return;

  const obstacles = markObstacles(scene);
  // The guide lines — a volcano's fold-change and significance thresholds, a y = x identity,
  // an origin cross-hair. They are chrome exactly like an axis, and a gene name printed across
  // one is the same defect as a label on a dot (e.g. a gene name on the +1 threshold).
  obstacles.push(...guideLineObstacles(scene));
  obstacles.push(...textNoteObstacles(scene, measure));
  const legendBox = insideLegendBox(
    scene.legendLayout, scene.legend, scene.plot.x, scene.plot.y, scene.plot.width, scene.plot.height,
    scene.fonts.legend.size, measure,
  );
  if (legendBox) obstacles.push(legendBox);

  const fontPx = labelled[0]!.series.pointLabelSize ?? scene.fonts.valueLabel.size;
  const placed = placeLabelsClear(
    labelled.map(({ series, mark }) => ({
      id: `${series.id}:${mark.rowId}`,
      text: mark.valueText != null && mark.valueText !== "" ? mark.valueText : (mark.pointLabel ?? ""),
      anchorX: mark.cx,
      anchorY: mark.cy,
    })),
    {
      fontPx,
      measure,
      bounds: { x1: scene.plot.x, y1: scene.plot.y, x2: scene.plot.x + scene.plot.width, y2: scene.plot.y + scene.plot.height },
      obstacles,
    },
  );
  let crowded = 0;
  for (const { series, mark } of labelled) {
    const p = placed.get(`${series.id}:${mark.rowId}`);
    if (!p) continue;
    mark.pointLabelDx = p.x - mark.cx;
    mark.pointLabelDy = p.y - mark.cy;
    mark.pointLabelAnchor = p.anchor;
    // A leader only where the move was big enough to make the pairing a guess.
    const r = Math.max(2, mark.symbolSize ?? series.symbolSize ?? 4);
    const text = mark.valueText != null && mark.valueText !== "" ? mark.valueText : (mark.pointLabel ?? "");
    const lead = leaderFor(mark.cx, mark.cy, placedBox(p, text, fontPx, measure), r, r + fontPx * 2);
    if (lead) mark.pointLabelLeader = lead;
    if (p.crowded) crowded++;
  }
  if (crowded > 0) {
    scene.warnings.push(`${crowded} point label${crowded === 1 ? "" : "s"} could not be placed clear of the marks — there are more labels than room at this size. Widen the figure, label fewer points, or drag the ones you need.`);
  }
}

/**
 * Zone names clear of the data. A shaded zone's caption ("Response", "Progression") is put at a fixed
 * spot — the top of its zone — without looking at what is drawn there. On a horizontal waterfall that
 * spot is the top patient's bar, so the caption would be printed across it.
 *
 * A caption whose spot is already clear stays exactly where it was. One that lands on a bar, a mark, a
 * line or the legend moves to the nearest clear spot inside its own zone, by the rule point labels
 * follow (`placeLabelsClear`). When no spot is clear it keeps the least-bad one and the scene says so —
 * never dropped.
 */
function placeBandCaptions(scene: PlotScene, measure: (t: string, px: number) => number): void {
  const bands = scene.annotations.filter((a) =>
    a.kind === "band" && a.label && a.labelX != null && a.labelY != null && a.x1 != null && a.y1 != null && a.x2 != null && a.y2 != null);
  if (bands.length === 0) return;
  const obstacles = markObstacles(scene);
  const legendBox = insideLegendBox(
    scene.legendLayout, scene.legend, scene.plot.x, scene.plot.y, scene.plot.width, scene.plot.height,
    scene.fonts.legend.size, measure,
  );
  if (legendBox) obstacles.push(legendBox);
  const PAD = 3;
  const hits = (b: LabelRect): boolean => obstacles.some((o) => b.x1 < o.x2 + PAD && o.x1 < b.x2 + PAD && b.y1 < o.y2 + PAD && o.y1 < b.y2 + PAD);
  // The caption is drawn on a baseline; the placer works on the middle of the glyphs, about 0.3 of the font higher.
  const MID = 0.3;
  const spotOf = (a: AnnotationScene) => {
    const font = a.fontSize ?? scene.fonts.legend.size;
    const w = placedBox({ x: 0, y: 0, anchor: "start" }, a.label!, font, measure).x2;
    const x = a.labelAnchor === "start" ? a.labelX! : a.labelAnchor === "end" ? a.labelX! - w : a.labelX! - w / 2;
    const y = a.labelY! - font * MID;
    return { font, w, x, y, box: placedBox({ x, y, anchor: "start" }, a.label!, font, measure) };
  };
  const blocked = bands.filter((a) => {
    const { box } = spotOf(a);
    if (hits(box)) return true;
    obstacles.push(box); // a caption that stays is something a moved one must clear
    return false;
  });
  const crowded: string[] = [];
  const pr = { x1: scene.plot.x, y1: scene.plot.y, x2: scene.plot.x + scene.plot.width, y2: scene.plot.y + scene.plot.height };
  // The zone's span along one axis, widened to hold the caption and kept on the plot.
  const span = (lo: number, hi: number, size: number, min: number, max: number): [number, number] => {
    let a = Math.max(min, lo);
    let b = Math.min(max, hi);
    if (b - a < size) {
      const mid = (a + b) / 2;
      a = Math.max(min, Math.min(mid - size / 2, max - size));
      b = Math.min(max, a + size);
    }
    return [a, b];
  };
  for (const a of blocked) {
    const { font, w, x, y } = spotOf(a);
    const [bx1, bx2] = span(Math.min(a.x1!, a.x2!), Math.max(a.x1!, a.x2!), w, pr.x1, pr.x2);
    const [by1, by2] = span(Math.min(a.y1!, a.y2!), Math.max(a.y1!, a.y2!), font * 1.2, pr.y1, pr.y2);
    const placed = placeLabelsClear(
      [{ id: a.id, text: a.label!, anchorX: Math.max(bx1, Math.min(x, bx2 - w)), anchorY: Math.max(by1 + font * 0.6, Math.min(y, by2 - font * 0.6)), prefer: "right" }],
      { fontPx: font, measure, bounds: { x1: bx1, y1: by1, x2: bx2, y2: by2 }, obstacles, pad: PAD },
    ).get(a.id);
    if (!placed) continue;
    a.labelX = placed.x;
    a.labelY = placed.y + font * MID;
    a.labelAnchor = placed.anchor;
    obstacles.push(placedBox(placed, a.label!, font, measure));
    if (placed.crowded) crowded.push(a.label!);
  }
  if (crowded.length) {
    scene.warnings.push(
      `The zone label${crowded.length === 1 ? "" : "s"} ${crowded.map((l) => `"${l}"`).join(", ")} could not be placed clear of the data inside ${crowded.length === 1 ? "its zone" : "their zones"}. `
      + "Make the figure larger, or show the zone names in a zone key (Annotations ▸ Zone key).",
    );
  }
}

/**
 * Direct labels — the series named on the drawing instead of in a legend (`legend.position` =
 * "direct").
 *
 * A legend costs the reader a lookup: find the colour, carry it back to the line. A name beside
 * the line itself costs nothing, which is why journals prefer it — and why this is offered in
 * the same Position control that decides where a legend sits, not as a second feature. Choosing
 * it means there is no legend block at all.
 *
 * Runs at the choke point, after the point labels, so it places against real pixels and sees
 * their boxes as obstacles.
 *
 * Refused with a warning, never dropped: a legend row that does not name a series with marks has
 * nothing to sit beside (a volcano's rows are zones over one series; a pie's slices live
 * outside the series layer). Those get a scene warning naming them, and the Inspector hides the
 * option on kinds where none of the rows qualify.
 */
/**
 * Kinds that do not take direct labels, and why.
 *
 * A direct label replaces a legend for series drawn as a line or a cloud of points: there is a
 * curve to name and clear paper beside its end. Two families fail that:
 *
 *  • **Groups already named on the category axis** — box, violin, column scatter, raincloud,
 *    floating bar, ridgeline. Their legend rows are the axis ticks, which is why their legend
 *    is built off by default (the redundancy argument in `groupLegend`). On a box-and-whisker
 *    chart, "Control" would be printed beside the tick that says "Control": the same word twice.
 *  • **Series drawn as blocks that fill the plot** — bar, histogram, pyramid, swimmer. There is
 *    no clear paper beside a bar. On a three-group grouped bar, both names come back `crowded`,
 *    printed across the bars. A bar's identity comes from its axis tick, not from a name
 *    floating over the ink.
 *
 * Refused with a warning rather than silently: the Inspector hides the option on these kinds, so the
 * setting can only arrive from a saved project or a copied look — exactly when a silent no-op
 * would never be noticed.
 */
const DIRECT_LABEL_REDUNDANT = new Set([
  "box", "violin", "scatter", "raincloud", "floatingbar", "ridgeline",
  "bar", "histogram", "pyramid", "swimmer",
]);

/**
 * A series' leader lines take its own look (`SeriesStyle.leaderShow / leaderColor / leaderWidth`):
 * the name's leader and every value label's. Show off removes them; a series with none of the three is left
 * as its builder drew it.
 */
function applyLeaderStyle(scene: PlotScene, plot: Plot): void {
  for (const s of scene.series) {
    const st = plot.seriesStyles?.[s.id];
    if (!st || (st.leaderShow === undefined && st.leaderColor === undefined && st.leaderWidth === undefined)) continue;
    const hide = st.leaderShow === false;
    const look = { ...(st.leaderColor !== undefined ? { color: st.leaderColor } : {}), ...(st.leaderWidth !== undefined ? { width: st.leaderWidth } : {}) };
    if (s.directLabel?.leader) {
      if (hide) delete s.directLabel.leader;
      else Object.assign(s.directLabel.leader, look);
    }
    for (const m of s.marks) {
      if (!m.pointLabelLeader) continue;
      if (hide) delete m.pointLabelLeader;
      else Object.assign(m.pointLabelLeader, look);
    }
  }
}

function placeDirectLabels(scene: PlotScene, plot: Plot, measure: (t: string, px: number) => number): void {
  const entries = scene.legendLayout.directEntries;
  if (!entries || entries.length === 0) return;
  if (DIRECT_LABEL_REDUNDANT.has(scene.kind)) {
    scene.warnings.push(
      "Direct labels are not drawn on this chart: its series are bars or blocks named by the category axis, so a name on the chart would repeat the axis or be printed over the data. Choose a legend position instead, or switch the legend off.",
    );
    return;
  }

  const byId = new Map(scene.series.map((s) => [s.id, s]));
  /**
   * The point a name sits beside: the end of the series — its last mark along x, and failing
   * that the last point of its drawn line.
   *
   * The line fallback is required. A survival curve and an ROC curve are `linePath` with
   * zero marks, and so is a ridgeline's ridge, so a marks-only rule would refuse direct labels
   * on exactly the kinds where naming the curve at its end is the whole point. The path always ends on an absolute coordinate pair (the builders emit M/L/C), so
   * the last two numbers in it are that end.
   */
  const subject = (s: SeriesScene): { x: number; y: number; r: number } | undefined => {
    let best: MarkScene | undefined;
    for (const m of s.marks) if (!best || m.cx > best.cx) best = m;
    if (best) return { x: best.cx, y: best.cy, r: Math.max(2, best.symbolSize ?? s.symbolSize ?? 4) };
    const nums = s.linePath ? s.linePath.match(/-?\d+(?:\.\d+)?/g) : null;
    if (!nums || nums.length < 2) return undefined;
    return { x: Number(nums[nums.length - 2]), y: Number(nums[nums.length - 1]), r: Math.max(2, s.lineWidth) };
  };

  /**
   * Two rows cannot name one series. A ternary's legend keys its four composition columns
   * (Sand · Loam · Silt · Clay) and all four point at the same single point series, so each name
   * would overwrite the last: the chart would draw one of them, arbitrarily chosen, in the first
   * row's colour, attached to a differently-coloured point, repeating an edge title already on the
   * axis — with no warning, because every row does resolve to a series.
   *
   * A direct label names a series. When rows share one, none of them is that series' name, so
   * the whole group is refused together and reported.
   */
  const perSeries = new Map<NodeId, LegendEntry[]>();
  const named: { entry: LegendEntry; series: SeriesScene; at: { x: number; y: number; r: number } }[] = [];
  const refused: string[] = [];
  for (const e of entries) {
    if (e.select?.as !== "series") { refused.push(e.label); continue; }
    perSeries.set(e.select.id, [...(perSeries.get(e.select.id) ?? []), e]);
  }
  for (const [id, rows] of perSeries) {
    const ser = byId.get(id);
    const at = ser ? subject(ser) : undefined;
    if (!ser || !at || rows.length > 1) { refused.push(...rows.map((r) => r.label)); continue; }
    named.push({ entry: rows[0]!, series: ser, at });
  }
  if (refused.length > 0) {
    scene.warnings.push(
      `Direct labels name one series each, so ${refused.length === 1 ? "this key is" : "these keys are"} still without a name on the chart: ${refused.join(", ")}. ${refused.length === 1 ? "It names" : "They name"} something the chart does not draw as its own series — several keys for one set of points, or a slice, zone or node. Choose another legend position to key ${refused.length === 1 ? "it" : "them"}.`,
    );
  }
  if (named.length === 0) return;

  const fontPx = scene.fonts.legend.size;
  const bounds = { x1: scene.plot.x, y1: scene.plot.y, x2: scene.plot.x + scene.plot.width, y2: scene.plot.y + scene.plot.height };
  const obstacles = markObstacles(scene);
  obstacles.push(...guideLineObstacles(scene, { measure }));
  obstacles.push(...textNoteObstacles(scene, measure));
  // The point labels already placed above — a series name printed over one would undo that pass.
  for (const s of scene.series) {
    for (const m of s.marks) {
      if (!m.pointLabel || m.pointLabelDx == null || m.pointLabelDy == null) continue;
      const t = m.valueText != null && m.valueText !== "" ? m.valueText : m.pointLabel;
      const w = measure(t, s.pointLabelSize ?? scene.fonts.valueLabel.size) * 1.15;
      const x = m.cx + m.pointLabelDx + (m.valueDx ?? 0);
      const y = m.cy + m.pointLabelDy + (m.valueDy ?? 0);
      const h = (s.pointLabelSize ?? scene.fonts.valueLabel.size) * 0.6;
      obstacles.push({ x1: m.pointLabelAnchor === "end" ? x - w : x, y1: y - h, x2: m.pointLabelAnchor === "end" ? x : x + w, y2: y + h });
    }
  }

  /**
   * The user's drag is deliberately not applied here: `directLabelOffset` is added
   * by the renderer on top of this placement, exactly as `valueDx/valueDy` ride on top of the
   * point labels' `pointLabelDx/Dy`. So a drag stays a nudge relative to wherever the rule put
   * the name — the label keeps following its own series when the data changes, instead of being
   * pinned to a pixel that stops meaning anything.
   *
   * Note: the other names still have to clear it. A label moved into another label's spot
   * would otherwise be printed through, so once the drags are known this places the untouched
   * names again with the dragged boxes added as obstacles — a second pass that only runs on a
   * figure where something was actually dragged.
   */
  /**
   * Top-most first, not longest-first.
   *
   * The placer's own contract is "hardest first", and every other caller passes the longest
   * label first for that reason. Direct labels are the exception: with two curves ending 10 px
   * apart and names of the same length, the first one placed takes the spot above, so the lower
   * curve's name can end up above the upper curve's — crossed, with only a leader line tying
   * them back.
   *
   * Placing in the subjects' own vertical order makes the names read in the same order as the
   * curves, which is the whole point of naming them on the drawing. Ties break on the longer
   * name, as the placer's own hardest-first order would.
   */
  const order = [...named].sort((a, b) => a.at.y - b.at.y || measure(b.entry.label, fontPx) - measure(a.entry.label, fontPx));
  const place = (list: typeof order, obs: LabelRect[]): Map<string, PlacedLabel> =>
    placeLabelsClear(
      list.map((n) => ({ id: n.series.id, text: n.entry.label, anchorX: n.at.x, anchorY: n.at.y })),
      { fontPx, measure, bounds, obstacles: obs },
    );
  let placed = place(order, obstacles);
  const dragged = order.filter((n) => plot.seriesStyles?.[n.series.id]?.directLabelOffset);
  if (dragged.length > 0 && dragged.length < order.length) {
    const withDrags = [...obstacles];
    for (const n of dragged) {
      const p = placed.get(n.series.id);
      const off = plot.seriesStyles![n.series.id]!.directLabelOffset!;
      if (!p) continue;
      const b = placedBox(p, n.entry.label, fontPx, measure);
      withDrags.push({ x1: b.x1 + off.dx, y1: b.y1 + off.dy, x2: b.x2 + off.dx, y2: b.y2 + off.dy });
    }
    const again = place(order.filter((n) => !dragged.includes(n)), withDrags);
    placed = new Map([...placed, ...again]);
  }
  let crowded = 0;
  for (const n of order) {
    const p = placed.get(n.series.id);
    if (!p) continue;
    const lead = leaderFor(n.at.x, n.at.y, placedBox(p, n.entry.label, fontPx, measure), n.at.r, n.at.r + fontPx * 2);
    const off = plot.seriesStyles?.[n.series.id]?.directLabelOffset;
    n.series.directLabel = { text: n.entry.label, x: p.x, y: p.y, anchor: p.anchor, ...(lead ? { leader: lead } : {}), ...(off ? { offset: off } : {}) };
    if (p.crowded) crowded++;
  }
  if (crowded > 0) {
    scene.warnings.push(
      `${crowded} direct label${crowded === 1 ? "" : "s"} could not be placed clear of the data — there is not room beside every line at this size. Widen the figure, shorten the series names, drag the ones you need, or use a legend instead.`,
    );
  }
}

function paintDataDriven(table: DataTable, plot: Plot, scene: PlotScene, ramps: RampResolver, palette: readonly string[]): void {
  const kind = plot.kind ?? "xy";
  const ddColour = DATA_DRIVEN_KINDS.has(kind); // colour/symbol binding (would clash with volcano's zone hue)
  // Point labels also apply to volcano (gene names on significant points) — but not the
  // colour/symbol column binding, which would override the up/down/ns zone encoding.
  if (!ddColour && kind !== "volcano") return;
  const styles = plot.seriesStyles;
  if (!styles) return;
  const rowById = new Map(table.rows.map((r) => [r.id, r]));
  for (const series of scene.series) {
    const st = styles[series.id];
    if (!st) continue;
    // Colour from a column — a continuous ramp or a per-category palette. Set both the
    // fill (solid markers show `color` as the fill) and the outline (open/clear markers
    // show `outline` as the visible colour), so the point reads as its data colour in
    // every fill mode — an explicit per-point override (paintPointStyles) still wins.
    if (ddColour && st.colorFromColumn) {
      const col = st.colorFromColumn;
      if (ddColorMode(st, table, col) === "continuous") {
        const [lo, hi] = ddDomain(table, col);
        const span = hi > lo ? hi - lo : 1;
        const ramp = st.colorFromRamp ?? "viridis";
        const rev = st.colorFromReversed ?? false;
        const paint = ramps.ramp(ramp, series.color, "#1a1a1a", rev, {
          midpointValue: st.colorFromMidpoint, gamma: st.colorFromGamma, steps: st.colorFromSteps,
          space: st.colorFromSpace, lo, hi, values: ddValues(table, col),
        });
        for (const mark of series.marks) {
          const v = toNumber(rowById.get(mark.rowId)?.cells[col]);
          if (!Number.isFinite(v)) continue;
          const c = paint((v - lo) / span).color;
          paintMarkColour(mark, c);
        }
      } else {
        const cats = ddCategories(table, col);
        for (const mark of series.marks) {
          const k = ddCellKey(rowById.get(mark.rowId)?.cells[col]);
          if (k === null) continue;
          // The graph's palette, not the default one — and the same index the legend uses.
          const c = palette[cats.indexOf(k) % palette.length]!;
          paintMarkColour(mark, c);
        }
      }
    }
    // Symbol from a column — distinct values cycle the shape set.
    if (ddColour && st.symbolFromColumn) {
      const col = st.symbolFromColumn;
      const cats = ddCategories(table, col);
      for (const mark of series.marks) {
        const k = ddCellKey(rowById.get(mark.rowId)?.cells[col]);
        if (k === null) continue;
        mark.symbol = DD_SYMBOL_CYCLE[cats.indexOf(k) % DD_SYMBOL_CYCLE.length]!;
      }
    }
    // Point labels — a small text beside each marker from a chosen value/column.
    const mode = st.pointLabels ?? "none";
    if (mode !== "none") {
      series.pointLabelColor = st.pointLabelColor ?? series.color;
      if (st.pointLabelSize !== undefined) series.pointLabelSize = st.pointLabelSize;
      for (const mark of series.marks) mark.pointLabel = ddPointLabel(mode, st, rowById.get(mark.rowId), mark);
    }
    paintHighlight(table, st, series, rowById, scene.warnings);
  }
}

/** The chart types drawn by the continuous XY builder, where a column of names is not a series (`xyFamilyDatasets`). */
export const XY_FAMILY_KINDS: ReadonlySet<string> = new Set(["xy", "area", "bubble", "volcano"]);

/** The datasets an XY / area / bubble / volcano chart draws as series: every dataset but a column of names. One
 *  definition for the builder and for the Series list, so a list row always names a series the chart draws. */
export function xyFamilyDatasets(table: DataTable): ReturnType<typeof tableDatasets> {
  return tableDatasets(table).filter((d) => !isNameColumn(table, d));
}

/**
 * A dataset that is a column of names: it has filled cells and not one of them is a number. A blank column is not one
 * (it is data still to be typed in) — and a single number among the names makes it data, so nothing is hidden by guesswork.
 */
export function isNameColumn(table: DataTable, d: { id: NodeId; replicates: NodeId[] }): boolean {
  const ids = d.replicates.length ? d.replicates : [d.id];
  let filled = 0;
  for (const row of table.rows) {
    for (const id of ids) {
      const v = row.cells[id];
      if (v === null || v === undefined || String(v).trim() === "") continue;
      if (Number.isFinite(toNumber(v))) return false;
      filled++;
    }
  }
  return filled > 0;
}

/** The highlight colour when none is chosen: apart from the Okabe-Ito palette and a volcano's red / blue. */
export const HIGHLIGHT_DEFAULT = "#d81b60";

/**
 * The column a series' highlight names are searched in: the chosen one, else its Label column, else the table's first
 * column holding text (most cells non-numeric) — where names such as gene IDs live. Undefined when the table has none.
 */
export function highlightColumnOf(st: SeriesStyle, table: DataTable): NodeId | undefined {
  if (st.highlightColumn && table.columns.some((c) => c.id === st.highlightColumn)) return st.highlightColumn;
  if (st.pointLabelColumn && table.columns.some((c) => c.id === st.pointLabelColumn)) return st.pointLabelColumn;
  return table.columns.find((c) => {
    const cells = table.rows.map((r) => r.cells[c.id]).filter((v) => v !== null && v !== undefined && String(v).trim() !== "");
    return cells.length > 0 && cells.filter((v) => typeof v !== "number" && !Number.isFinite(Number(v))).length * 2 > cells.length;
  })?.id;
}

/**
 * Find & highlight (`SeriesStyle.highlightNames`). Every point whose row carries one of the names in
 * the search column is painted the highlight colour, labelled with its name through the ordinary point-label drawing
 * (placed clear of the data, draggable, editable), and moved to the end of the series so it is drawn on top. Names not
 * found are listed in the warning line, never dropped silently.
 */
function paintHighlight(
  table: DataTable,
  st: SeriesStyle,
  series: PlotScene["series"][number],
  rowById: Map<NodeId, { cells: Record<NodeId, CellValue> }>,
  warnings: string[],
): void {
  const names = (st.highlightNames ?? []).map((n) => n.trim()).filter((n) => n !== "");
  if (names.length === 0) return;
  const col = highlightColumnOf(st, table);
  if (!col) {
    warnings.push(`Highlight on “${series.name}”: the table has no column of names to search — choose one under “In column”.`);
    return;
  }
  const want = new Set(names.map((n) => n.toLowerCase()));
  const found = new Set<string>();
  const colour = st.highlightColor ?? HIGHLIGHT_DEFAULT;
  const label = st.highlightLabels !== false;
  const hit: MarkScene[] = [];
  const rest: MarkScene[] = [];
  for (const mark of series.marks) {
    const cell = rowById.get(mark.rowId)?.cells[col];
    const text = cell === null || cell === undefined ? "" : String(cell).trim();
    if (text !== "" && want.has(text.toLowerCase())) {
      found.add(text.toLowerCase());
      paintMarkColour(mark, colour);
      if (label) mark.pointLabel = text;
      hit.push(mark);
    } else {
      rest.push(mark);
    }
  }
  if (hit.length > 0) {
    series.marks = [...rest, ...hit];
    // With no other point labels on, the found names are written in the highlight colour.
    if (label && (st.pointLabels ?? "none") === "none") {
      series.pointLabelColor = st.pointLabelColor ?? colour;
      if (st.pointLabelSize !== undefined) series.pointLabelSize = st.pointLabelSize;
    }
  }
  const missing = [...new Map(names.map((n) => [n.toLowerCase(), n])).entries()].filter(([k]) => !found.has(k)).map(([, n]) => n);
  if (missing.length > 0) {
    const colName = table.columns.find((c) => c.id === col)?.name ?? "the column";
    const shown = missing.slice(0, 10).join(", ") + (missing.length > 10 ? ` and ${missing.length - 10} more` : "");
    warnings.push(`Highlight: ${missing.length} name${missing.length === 1 ? "" : "s"} not found in “${colName}”: ${shown}.`);
  }
}

/**
 * Build the data-driven category / binned legend for a plot, or null when no series
 * binds a colour/symbol column. Replaces the per-series legend so a single scatter
 * coloured by a variable still gets a (≥2-entry, shown-by-default) legend.
 */
function dataDrivenLegend(plot: Plot, datasets: { id: NodeId; name: string }[], table: DataTable, palette: readonly string[]): LegendEntry[] | null {
  if (!DATA_DRIVEN_KINDS.has(plot.kind ?? "xy")) return null;
  const styles = plot.seriesStyles;
  if (!styles) return null;
  for (let di = 0; di < datasets.length; di++) {
    const st = styles[datasets[di]!.id];
    if (!st) continue;
    const base = st.color ?? palette[di % palette.length]!;
    // A colour binding drives the legend when present.
    if (st.colorFromColumn) {
      const col = st.colorFromColumn;
      // Continuous colour → a proper colour-scale bar (`scene.colorbar`), not a legend.
      if (ddColorMode(st, table, col) === "continuous") return null;
      const cats = ddCategories(table, col);
      if (cats.length === 0) return null;
      const withSym = st.symbolFromColumn === col;
      // Every row carries an explicit click target — the bound series (its panel owns the
      // binding); the legend guard refuses rows that fall back to label-text matching.
      return cats.map((c, i) => ({
        label: c,
        color: palette[i % palette.length]!,
        select: { as: "series" as const, id: datasets[di]!.id },
        dataDriven: true,
        ...(withSym ? { symbol: DD_SYMBOL_CYCLE[i % DD_SYMBOL_CYCLE.length]! } : {}),
      }));
    }
    // A symbol-only binding → entries keep the series colour, vary the shape.
    if (st.symbolFromColumn) {
      const cats = ddCategories(table, st.symbolFromColumn);
      if (cats.length === 0) return null;
      return cats.map((c, i) => ({ label: c, color: base, symbol: DD_SYMBOL_CYCLE[i % DD_SYMBOL_CYCLE.length]!, select: { as: "series" as const, id: datasets[di]!.id } }));
    }
  }
  return null;
}

/** Continuous colour-by-column info for the colour-scale bar: the first series that
 *  maps a numeric column via a ramp. Null when none, categorical, or a degenerate
 *  (single-value) domain. */
function continuousColorInfo(
  plot: Plot,
  datasets: { id: NodeId; name: string }[],
  table: DataTable,
  palette: readonly string[],
): { ramp: NonNullable<SeriesStyle["colorFromRamp"]>; rev: boolean; base: string; lo: number; hi: number; title: string; shape: RampShape } | null {
  if (!DATA_DRIVEN_KINDS.has(plot.kind ?? "xy")) return null;
  const styles = plot.seriesStyles;
  if (!styles) return null;
  for (let di = 0; di < datasets.length; di++) {
    const st = styles[datasets[di]!.id];
    if (st?.colorFromColumn && ddColorMode(st, table, st.colorFromColumn) === "continuous") {
      const [lo, hi] = ddDomain(table, st.colorFromColumn);
      if (!(hi > lo)) return null; // all values equal → no meaningful bar
      const col = table.columns.find((c) => c.id === st.colorFromColumn);
      return {
        ramp: st.colorFromRamp ?? "viridis",
        rev: st.colorFromReversed ?? false,
        base: st.color ?? palette[di % palette.length]!,
        lo,
        hi,
        title: col?.name ?? "",
        // The key must be shaped like the marks it explains: same midpoint, gamma, steps, space.
        shape: {
          midpointValue: st.colorFromMidpoint, gamma: st.colorFromGamma, steps: st.colorFromSteps,
          space: st.colorFromSpace, lo, hi,
        },
      };
    }
  }
  return null;
}

/** The value a graduated fill maps a mark to (bar height / X position / order). */
function gradValue(map: GradMap | undefined, mark: MarkScene, index: number): number {
  const m = map ?? "value";
  return m === "value" ? mark.dy : m === "x" ? mark.dx : index;
}

/** Resolve the shared error-bar + fill/contour style fields (with defaults). */
function seriesExtras(
  style: SeriesStyle | undefined,
  color: string,
  lineWidth: number,
  symbolSize: number,
  fillOpacityDefault: number,
): Pick<
  SeriesScene,
  "errorColor" | "errorWidth" | "errorCapWidth" | "fillColor" | "fillOpacity" | "borderColor" | "fillSpec"
> {
  // Two-tone: the base hue (the Fill colour, or the series colour) drives both the
  // light fill and the darker contour, so changing the hue re-derives the pair.
  const twoTone = style?.fillType === "twotone";
  const base = style?.fillColor ?? color;
  const fillColor = twoTone ? twoToneFill(base, style?.twoToneTint) : base;
  return {
    errorColor: style?.errorColor ?? color,
    errorWidth: style?.errorWidth ?? Math.max(1.2, lineWidth * 0.7),
    errorCapWidth: style?.errorCapWidth ?? Math.max(3, symbolSize * 0.9),
    fillColor,
    fillOpacity: style?.fillOpacity ?? (twoTone ? 1 : fillOpacityDefault),
    // Two-tone derives the contour (darker shade of the base); otherwise the contour
    // defaults to match the fill (invisible until deliberately set, and changing the
    // fill doesn't leave a stale-coloured border).
    borderColor: twoTone ? twoToneContour(base, style?.twoToneShade) : (style?.borderColor ?? fillColor),
    fillSpec: twoTone ? { type: "solid", color: fillColor } : resolveFill(style, fillColor),
  };
}

/**
 * A bar's swarm points are a mark of their own, not a restatement of the bar.
 *
 * Every property the two share can link them by accident: the error-bar caps following the
 * marker size, the points' outline following the bar's contour, the bar's fill outranking the
 * point's colour, the two-tone tint/shade sliders moving both at once. These two helpers
 * are the single place that decides what the points inherit, so a shared property
 * cannot quietly re-link them somewhere else in the builder.
 *
 * `linkPointsToBar` decides which way they resolve, and it is on unless explicitly set to
 * `false`: a dot drawn over its own bar reads as part of that bar,
 * so the matching look is the default and diverging is the deliberate act. Untick it and each
 * mark goes back to its own colour and its own two-tone sliders — which is what having
 * separate controls is for.
 */
function pointBaseOf(style: SeriesStyle | undefined, color: string): string {
  if (style?.linkPointsToBar !== false) return style?.fillColor ?? color;
  return style.color ?? style.fillColor ?? color;
}

/** The style `resolveSymbol` should see for a bar's swarm points. */
function pointStyleOf(style: SeriesStyle | undefined): SeriesStyle | undefined {
  if (!style || style.linkPointsToBar !== false) return style; // linked → the bar's own values
  // Unlinked: the points' own two-tone sliders, not the bar's. Undefined here means "the
  // marker default", never "fall through to the bar" — falling through would make the two
  // sliders move together.
  return { ...style, twoToneTint: style.symbolTwoToneTint, twoToneShade: style.symbolTwoToneShade };
}

/** Resolve a series' symbol fill mode / opacity / outline (with back-compat from `filled`). */
function resolveSymbol(
  style: SeriesStyle | undefined,
  color: string,
): Pick<SeriesScene, "filled" | "symbolFill" | "symbolOpacity" | "symbolOutline" | "symbolFillColor" | "pointColor"> {
  // The swarm's own colour (raincloud rain / column-scatter dots). Undefined leaves the
  // renderer on the series colour, so a chart that never sets it is untouched.
  const pointColor = style?.pointColor;
  const requested = style?.symbolFill ?? ((style?.filled ?? true) ? "solid" : "open");
  const op = style?.symbolOpacity ?? 1;
  // Two-tone open marker: derive a light interior + darker outline from one base hue
  // (the series colour), so it re-tints with the colour — like the bar two-tone fill.
  // Resolves to a plain "open" marker, which the renderer already draws.
  if (requested === "twotone") {
    return {
      symbolFill: "open",
      filled: false,
      symbolOpacity: Math.min(1, Math.max(0, op)),
      // Edge derives from the hue unless the user set a custom two-tone edge colour.
      symbolOutline: style?.twoToneEdge ?? twoToneContour(color, style?.twoToneShade),
      symbolFillColor: twoToneFill(color, style?.twoToneTint),
      ...(pointColor ? { pointColor } : {}),
    };
  }
  const symbolFill: SeriesScene["symbolFill"] = requested;
  return {
    symbolFill,
    filled: symbolFill === "solid",
    symbolOpacity: Math.min(1, Math.max(0, op)),
    symbolOutline: style?.symbolOutline ?? color,
    ...(style?.symbolFillColor ? { symbolFillColor: style.symbolFillColor } : {}),
    ...(pointColor ? { pointColor } : {}),
  };
}

/**
 * The marker intent (fill mode + two-tone params + size) a plot carries — a style preset
 * stamps `symbolFill`/`symbolSize` onto the source-table series, but analysis-derived kinds
 * (PCA, scree, before-after, radar) key their points by synthetic ids (`pca-g0`, `scree`, a
 * row id, a radar dataset) the preset never wrote to, so a raw `plot.seriesStyles[synthId]`
 * lookup would miss it and the builder would fall back to its own constant. This reads the
 * intent from wherever it was set so those kinds inherit it.
 *
 * Note: `symbolSize` is included, but colour and width are not. Colour is per-series by
 * nature (a PCA group's hue must not become every group's hue), and each builder owns width
 * per series; marker size, by contrast, is one uniform number for a figure. Without it, each
 * of these kinds would use its own constant — 4.5 on scree and PCA scores, 4 on loadings,
 * 3 on a biplot and on before-after — so one marker size set for a whole set of graphs would
 * be ignored by these kinds.
 */
function plotMarkerDefault(
  plot: Plot,
): Pick<SeriesStyle, "symbolFill" | "twoToneTint" | "twoToneShade" | "twoToneEdge" | "symbolSize"> {
  const out: Pick<SeriesStyle, "symbolFill" | "twoToneTint" | "twoToneShade" | "twoToneEdge" | "symbolSize"> = {};
  for (const s of Object.values(plot.seriesStyles ?? {})) {
    if (out.symbolFill === undefined && s?.symbolFill) {
      out.symbolFill = s.symbolFill;
      out.twoToneTint = s.twoToneTint;
      out.twoToneShade = s.twoToneShade;
      out.twoToneEdge = s.twoToneEdge;
    }
    if (out.symbolSize === undefined && s?.symbolSize !== undefined) out.symbolSize = s.symbolSize;
    if (out.symbolFill !== undefined && out.symbolSize !== undefined) break;
  }
  return out;
}

/** A synthesized-series style with the plot's marker intent filled in underneath (the
 *  per-series style still wins — click a PCA group on the canvas and its own size/fill
 *  outranks the inherited one). Returns the style unchanged when there is nothing to
 *  inherit, so non-preset plots and explicit per-series choices are untouched. */
function effectiveMarkerStyle(plot: Plot, style: SeriesStyle | undefined): SeriesStyle | undefined {
  const def = plotMarkerDefault(plot);
  if (def.symbolFill === undefined && def.symbolSize === undefined) return style;
  return { ...def, ...(style ?? {}) };
}

/**
 * Margin an axis needs when [[AxisSpec.hidden]] is set: none of its tick marks, tick-number
 * labels or title are drawn, so that space is given back to the plot instead of being left
 * as an empty gutter. The user's explicit plot padding still applies; this is the small
 * hair on top so the data rect doesn't sit flush against the edge — the same 4px the
 * existing "axis has no title" fallback uses.
 *
 * Without this, hiding an axis would clear its labels but leave the margin exactly as it was
 * (the plot rect identical hidden vs shown), so a multi-panel figure that suppresses repeated
 * inner labels needs it to actually tighten up.
 */
const HIDDEN_AXIS_MARGIN = 4;

/**
 * Text metrics — how tall a run of text actually is, relative to its font size.
 *
 * A rendered text box is about 1.35× its font size, so a margin that reserves only `fontSize`
 * px for a line of text is short by ~35%. At the default 15px title that is ~5px and
 * invisible; at a poster-sized 26px it is ~9px, which is exactly when the axis title starts
 * sitting on the tick numbers or running off the canvas.
 *
 * `TEXT_ASCENT` + `TEXT_DESCENT` are also what `titleAnchorOf` uses to place the title, so the
 * space reserved and the space used are derived from one model instead of two.
 */
// Measured: an SVG <text> in the app's own font stack (`system-ui` first) rendered at 10…38px, with its getBBox()
// read back. The ratios are identical at every size and for digits, words and parenthesised
// strings alike — ascent 1.077, descent 0.269, box 1.346 em. That box is the font's own
// ascent plus descent, so it differs by font: Arial (the default preset's font on Windows) boxes
// at 1.12 em, see `NUMBER_LINE`. The margins reserve this roomier band for every font. Smaller ratios (such as
// 0.80 / 0.55) would place the X-axis title several pixels too high, onto the tick numbers.
const TEXT_ASCENT = 1.08;
const TEXT_DESCENT = 0.27;
const TEXT_BAND = TEXT_ASCENT + TEXT_DESCENT;

/**
 * Default node-label size for network graphs (px). Deliberately not the tick font: at the
 * tick default (20px) a label like "CXCL10" is ~72px wide — wider than the gap between many
 * nodes — so the labels swamp the diagram even when no two label boxes strictly intersect.
 * Overridable per graph via `NetworkStyle.labelSize`.
 */
const NETWORK_LABEL_SIZE = 12;

/** Vertical space one line of `size`px text needs, plus its gap to whatever it sits beside. */
function textBand(size: number, gap: number): number {
  return Math.ceil(TEXT_BAND * size) + gap;
}

const DEFAULTS = {
  width: 580,
  height: 380,
  // Publication-leaning defaults — axis numbers, titles, and legend are sized so
  // figures read well at print size. The margin math
  // below and the renderer both use these (via scene.fonts) so they stay in sync.
  tickFont: 13,
  titleFont: 15,
  legendFont: 13,
  headingFont: 18,
  subtitleFont: 13,
  tickLen: 5,
  marginTop: 16,
  marginRight: 18,
};

/**
 * Effective figure width/height honouring an explicit axis length (the "axis
 * length" = the plotting-rectangle size in px). When `xAxisLength`/`yAxisLength`
 * is set, the figure size becomes (axis length + margins) so the plot area is
 * exactly that length; otherwise the figure size is unchanged (plot =
 * figure − margins). Called once per axis-bearing builder, after its margins are
 * known, so every chart kind honours axis length consistently.
 */
/** Per-side extra plot-area padding (px) added on top of the auto-derived
 *  margins (Plot.plotPad). Each side defaults to 0 (auto margins only). */
function plotPadOf(plot: Plot): { t: number; r: number; b: number; l: number } {
  const p = plot.plotPad ?? {};
  return { t: p.top ?? 0, r: p.right ?? 0, b: p.bottom ?? 0, l: p.left ?? 0 };
}

function effectiveWidth(plot: Plot, width: number, marginLeft: number, marginRight: number): number {
  return plot.xAxisLength != null ? marginLeft + Math.max(40, plot.xAxisLength) + marginRight : width;
}
function effectiveHeight(plot: Plot, height: number, marginTop: number, marginBottom: number): number {
  return plot.yAxisLength != null ? marginTop + Math.max(40, plot.yAxisLength) + marginBottom : height;
}

/** Resolve the graph-title heading + subtitle a plot displays (Format → Title).
 *  Title defaults to the plot name; hidden → both blank. */
function resolveHeading(plot: Plot): { title: string; subtitle: string } {
  const show = plot.showTitle ?? true;
  if (!show) return { title: "", subtitle: "" };
  return { title: plot.title ?? plot.name, subtitle: plot.subtitle ?? "" };
}

/** Extra top margin (px) the title/subtitle band needs above the plot rect. */
/** Stacked height of a text block, counting `\n` lines (1.2em line spacing). */
function blockHeight(text: string, size: number): number {
  const lines = text.split("\n").length;
  return size * (1 + (lines - 1) * 1.2);
}

function headingPad(heading: { title: string; subtitle: string }, titleSize: number, subSize: number): number {
  if (!heading.title && !heading.subtitle) return 0;
  return (
    (heading.title ? blockHeight(heading.title, titleSize) + 6 : 0) +
    (heading.subtitle ? blockHeight(heading.subtitle, subSize) + 4 : 0) +
    4
  );
}

/** Resolve an axis's line colour + thickness + tick style (frame line + tick marks). */
function axisLine(spec: AxisSpec | undefined): { lineColor: string | null; lineWidth: number; tickWidth?: number; tickLen?: number; hideTicks?: boolean } {
  // tickWidth defaults to the axis line thickness (the renderer falls back to lineWidth),
  // so thickening the axis thickens its ticks too unless tickWidth is set separately.
  return {
    lineColor: spec?.lineColor ?? null,
    lineWidth: spec?.lineWidth ?? 1.25,
    ...(spec?.tickWidth != null ? { tickWidth: spec.tickWidth } : {}),
    ...(spec?.tickLen != null ? { tickLen: spec.tickLen } : {}),
    ...(spec?.hideTicks ? { hideTicks: true } : {}),
  };
}

/** Merge a FontSpec override over an element's default size/weight. */
function resolveFont(spec: FontSpec | undefined, defaultSize: number, defaultWeight = 400): ResolvedFont {
  return {
    size: spec?.size != null && spec.size > 0 ? spec.size : defaultSize,
    family: spec?.family ?? null,
    weight: spec?.bold === true ? 700 : spec?.bold === false ? 400 : defaultWeight,
    italic: spec?.italic ?? false,
    color: spec?.color ?? null,
  };
}

/** The dash a drawn line annotation is stroked with - one rule for the drawing and for its legend key. A reference
 *  line (hline / vline) is dashed unless set; a segment / arrow is solid unless set. */
function annotationLineDash(a: NonNullable<Plot["annotations"]>[number]): string | undefined {
  const width = a.width ?? 1.5;
  if (a.kind === "segment" || a.kind === "arrow") return a.dash && a.dash !== "solid" ? dashArray(a.dash, width) ?? undefined : undefined;
  return dashArray(a.dash ?? "dashed", width) ?? undefined;
}

/** A legend row's words when the listed line has no caption of its own. */
const LINE_ROW_NAME: Record<string, string> = { hline: "Horizontal line", vline: "Vertical line", segment: "Line", arrow: "Arrow" };

/**
 * The rows for the drawn lines the user listed in the legend (`Annotation.inLegend`): the line's own
 * colour, dash and width are the key - the same values it is drawn with - and its caption is the words. A row whose
 * line is not drawn after all (off the axis, refused by this chart) is dropped at the choke point (`dockLegendLines`).
 */
function legendLineRows(plot: Plot): LegendEntry[] {
  return (plot.annotations ?? [])
    .filter((a) => a.inLegend && canJoinLegend(a.kind))
    .map((a) => {
      const dash = annotationLineDash(a);
      return {
        label: a.label?.trim() || (LINE_ROW_NAME[a.kind] ?? "Line"),
        color: a.color ?? "var(--ink)",
        marker: false,
        lineWidth: a.width ?? 1.5,
        ...(dash ? { dash } : {}),
        select: { as: "annotation" as const, id: a.id },
      };
    });
}

/** How a fitted curve is drawn - colour, thickness, dash - from `plot.fitStyle` over the fit's own colour. One rule
 *  for the curve (`buildFit`) and for its legend key (`fitLegendRows`). */
function fitCurveLook(plot: Plot, pf: NonNullable<Plot["fit"]>, fallbackColor: string): { color: string; width: number; dash: string | null } {
  const fs = plot.fitStyle ?? {};
  const width = fs.width ?? 2.4;
  return { color: fs.color ?? pf.color ?? fallbackColor, width, dash: fs.dash ? dashArray(fs.dash, width) : null };
}

/** The rows for the fitted curves when `fitStyle.inLegend` is on: each curve's look (`fitCurveLook`, with the same
 *  palette colour `buildFit` falls back to) as the key, the fit's label as the words. A hidden curve lists nothing. */
function fitLegendRows(plot: Plot, palette: readonly string[]): LegendEntry[] {
  const fs = plot.fitStyle ?? {};
  if (!fs.inLegend || fs.show === false) return [];
  const row = (pf: NonNullable<Plot["fit"]>, fallback: string, id: string): LegendEntry => {
    const look = fitCurveLook(plot, pf, fallback);
    return {
      label: pf.label?.trim() || "Fitted curve",
      color: look.color,
      marker: false,
      lineWidth: look.width,
      ...(look.dash ? { dash: look.dash } : {}),
      select: { as: "fit", id },
    };
  };
  const out: LegendEntry[] = [];
  if (plot.fit && plot.fit.points.length > 0) out.push(row(plot.fit, seriesColor(1, palette), "fit"));
  (plot.fits ?? []).forEach((pf, i) => { if (pf.points.length > 0) out.push(row(pf, seriesColor(i, palette), String(i))); });
  return out;
}

/**
 * Lines in the legend, at the choke point. A drawn line that has its row in the legend loses its caption on the
 * plot - the row replaces it (the zone key does the same for a band). A row whose line was not drawn (off the axis,
 * refused by this chart) or whose curve is not drawn is dropped: a key must name something on the chart.
 */
function dockLegendLines(scene: PlotScene): void {
  if (!scene.legend.some((e) => e.select?.as === "annotation" || e.select?.as === "fit")) return;
  const drawn = new Map(scene.annotations.map((a) => [a.id, a] as const));
  scene.legend = scene.legend.filter((e) =>
    e.select?.as === "annotation" ? drawn.has(e.select.id) : e.select?.as === "fit" ? (e.select.id === "fit" ? !!scene.fit : (scene.fits?.length ?? 0) > 0) : true,
  );
  for (const e of scene.legend) {
    if (e.select?.as !== "annotation") continue;
    const a = drawn.get(e.select.id);
    if (a) delete a.label;
  }
}

/** Resolve the legend: which entries to show, its placement, and how much
 *  outside-right margin it reserves (0 unless it's the outside column). */
function resolveLegend(
  plot: Plot,
  entries: LegendEntry[],
  measure: (text: string, fontPx: number) => number,
  legendSize: number,
  /** Figure width, when the caller knows it — enables the outside-right cap below. */
  figureWidth?: number,
): { entries: LegendEntry[]; layout: LegendLayout; outsideRightWidth: number } {
  const spec = plot.legend ?? {};
  const position = spec.position ?? "right";
  // Drawn lines the user listed in the legend join its rows here - the one choke point every legend passes. Not
  // with direct labels: there is no block to join, so the line keeps its caption. A listed line shows the legend
  // under "auto" even on a chart with no series rows (a box plot, a histogram): asking for the row is asking for the
  // block - one row would otherwise stay hidden and the tick box would do nothing. "Hide legend" still hides it.
  const listedLines = position !== "direct" ? legendLineRows(plot) : [];
  entries = [...entries, ...listedLines];
  // A row the user renamed on the graph (`Plot.legendLabels`, keyed by the label as built) takes its new words
  // here, before the rows are measured and wrapped - so the reserved width fits what is drawn. `labelKey` keeps the
  // built label for the next rename. Every legend passes this point, so every kind honours it.
  const renamed = plot.legendLabels;
  if (renamed) entries = entries.map((e) => (renamed[e.label] != null && renamed[e.label] !== e.label ? { ...e, label: renamed[e.label]!, labelKey: e.label } : e));
  const listed = listedLines.length > 0 || entries.some((e) => e.select?.as === "fit");
  const show = (spec.show ?? (entries.length >= 2 || listed)) && position !== "none";
  /**
   * Direct labels. Not a place for the legend — the other answer to the question the legend
   * asks. The block is not drawn (`shown` stays empty, so every `scene.legend.length > 0`
   * check in the renderer and the panel assembler's shared legend go quiet, and
   * no outside-right margin is reserved); the rows ride on the layout instead, and the pass at
   * the choke point turns each into a name beside its own series.
   */
  const direct = position === "direct" && show;
  // Each series row carries its series' configured marker radius, so the swatch matches the
  // data point size (set point size to 6 → the legend symbol is 6). One source: the reservation
  // below and the renderer both read `symbolSize`, so they can never drift.
  // A synthesised series (PCA groups `pca-g0`, `scree`) has no style entry of its own; its builder
  // draws it at the plot's marker size (`plotMarkerDefault`). Reading only its own style would
  // reserve a 4 px dot for a 6.5 px one, so the label would start on the dot (triplot, biplot,
  // scree). A series that has a style entry reads that entry.
  const markerFallback = plotMarkerDefault(plot).symbolSize;
  const sized: LegendEntry[] = entries.map((e) => {
    // A "bar" swatch row keys the bar, not a marker: its block is sized by the legend font, so
    // it must not inherit the series' symbolSize (that is the swarm-dot radius; inheriting it
    // would draw an oversized key).
    if (e.swatch === "bar") return e;
    const own = e.select?.as === "series" ? plot.seriesStyles?.[e.select.id] : undefined;
    const sz = e.select?.as === "series" ? (own ? own.symbolSize : markerFallback) : undefined;
    return sz != null ? { ...e, symbolSize: sz } : e;
  });
  // Loose rows: a row pulled out of the block (`Plot.legendLoose`, keyed by its label as
  // built) is handed over on its own with its place; the block closes the gap. Decided after `show`, so pulling one
  // row out of a two-row legend keeps the other row's block. A listed line's row keeps its own rule (dragged out, the
  // line leaves the legend), so it is never loose.
  const looseAt = plot.legendLoose;
  const looseIdx = new Set<number>();
  const loose = show && !direct && looseAt
    ? sized.flatMap((e, index) => {
        const at = looseAt[e.labelKey ?? e.label];
        if (!at || e.select?.as === "annotation" || e.select?.as === "fit") return [];
        looseIdx.add(index);
        return [{ entry: e, index, x: at.x, y: at.y }];
      })
    : [];
  const shown = show && !direct ? sized.filter((_e, i) => !looseIdx.has(i)) : [];
  const gap = spec.gap ?? 12;
  const inset = spec.inset ?? 8;
  // The swatch column. Its width and the marker both derive from the legend font (13px gives
  // an 18px column and a 4px marker) and then from `symbolScale`, so raising the legend font
  // grows the symbol together with the text.
  const symbolScale = Math.max(0.4, Math.min(3, spec.symbolScale ?? 1));
  // Reserve the column for the line stub — which grows to show past a big dot (the renderer's
  // rule; a large point must not cover the whole line) — plus room for a data-driven marker.
  // Mirrors the renderer exactly so the reservation and the drawing never drift.
  const dotBases = sized.filter((e) => !e.symbol && e.marker !== false && e.swatch !== "bar").map((e) => e.symbolSize ?? 4);
  const maxDotBase = dotBases.length ? Math.max(4, ...dotBases) : 4;
  const stubW = Math.max(12 * (legendSize / 13) * symbolScale, 3 * maxDotBase * symbolScale);
  const markerBases = sized.filter((e) => e.symbol).map((e) => e.symbolSize ?? 4);
  const maxMarkerBase = markerBases.length ? Math.max(4, ...markerBases) : 4;
  // The label starts a fixed gap past what the swatch draws — the line stub (whose middle carries the
  // dot, and which is ≥ 3 dot radii, so it always reaches past the dot's edge), or a data-driven marker
  // drawn at a third of the column. The gap is the font's (half the default stub: 6 px at 13 px), never
  // the dot's: a gap proportional to the stub (`1.5 × stub`) would push a big dot's label 2 radii away,
  // leaving anywhere from 6 to 21 px of empty space. Measured from the dot's edge, the gap stays the
  // same at any dot size.
  const textGap = 6 * (legendSize / 13) * symbolScale;
  // A pie wedge / waffle square key (`keyShape`) is 1.25 em wide — the renderer's bar-block height — and its label
  // keeps the same fixed gap past its edge (without this width it would sit 2 px from a waffle square).
  const shapedKeyW = sized.some((e) => e.keyShape) ? 1.25 * legendSize * symbolScale + textGap : 0;
  const swatchWidth = Math.max(8, stubW + textGap, 1.5 * (maxMarkerBase * symbolScale + textGap), shapedKeyW);
  const layout: LegendLayout = {
    position,
    // An outside-top legend is a row by definition (the band above the plot is wide and
    // shallow); the user's orientation applies everywhere else.
    orientation: position === "top" ? "horizontal" : spec.orientation ?? "vertical",
    border: spec.border ?? false,
    background: spec.background ?? false,
    gap,
    inset,
    symbolScale,
    swatchWidth,
    // The frame / paper / padding, passed through only when the user set one. Absent means the
    // renderer uses its built-in constant — see the note on `LegendSpec.borderColor`.
    ...(spec.borderColor != null ? { borderColor: spec.borderColor } : {}),
    ...(spec.borderWidth != null ? { borderWidth: spec.borderWidth } : {}),
    ...(spec.borderRadius != null ? { borderRadius: spec.borderRadius } : {}),
    ...(spec.backgroundColor != null ? { backgroundColor: spec.backgroundColor } : {}),
    ...(spec.padding != null ? { padding: spec.padding } : {}),
    ...(spec.barKey === "point" ? { barKey: "point" as const } : {}),
    ...(direct ? { directEntries: sized } : {}),
    ...(loose.length ? { looseEntries: loose } : {}),
  };
  // Note: `shown.length` matters, not just `show`. A kind that resolves no entries (a heatmap, a
  // dendrogram) would otherwise get ~28 px of right margin the moment anything sets
  // `legend.show` — the graph ribbon's Legend tickbox does, on every kind — so the plot would
  // shrink with nothing drawn in the space. Reserve room only for a legend that exists.
  // Note: `swatchWidth`, not a fixed constant: the reservation and the drawing have to move
  // together. Widen the symbol without widening this and the legend overflows the margin the
  // layout carved for it.
  /**
   * An outside-right legend label is never truncated. Cutting a ROC curve's "Biomarker (AUC 0.860)"
   * to "Biomarker (AU…" would lose the AUC, which is the entire point of a ROC legend. The column
   * takes the width of its longest label; a label wider than a third of the figure is broken at its
   * spaces onto more lines instead (below). Builder tests guard this.
   *
   * A legend label is information, not decoration. A cramped plot is legible; a truncated
   * number is wrong. The row labels on a paired dot are a different case — they repeat what
   * the rows already show — and that builder caps its own, with a warning.
   */
  const chrome = gap + swatchWidth + (spec.padding != null ? spec.padding * 2 : 10);
  const widestLabel = (rows: readonly LegendEntry[]): number => Math.max(0, ...rows.flatMap((e) => (e.lines ?? [e.label]).map((l) => measure(l, legendSize))));
  let out = shown;
  let wantedRight = show && shown.length > 0 && position === "right" ? chrome + widestLabel(shown) : 0;
  /**
   * This function keeps an outside-right legend on the right, whatever its size, and with no clashes. It does not move it
   * inside the plot's bottom-right corner when it takes more than a third of the width, because there it would sit on the data.
   *
   * A label too long for a third of the width is not cut — "Biomarker (AUC 0.860, 95% CI 0.790–0.930)" cut short throws
   * away the number the legend exists to report. It is broken at its spaces onto more lines (`wrapLegendLabel`); a single
   * word longer than the room stays whole.
   */
  if (figureWidth !== undefined && layout.orientation === "vertical" && wantedRight > figureWidth * 0.33) {
    // Never narrower than the longest single word: that word sets the column's width anyway (a word is never cut), so
    // breaking a shorter label under it ("Firmicutes" / "A" beside "Verrucomicrobia") would save nothing.
    const longestWord = Math.max(0, ...shown.flatMap((e) => e.label.split(/\s+/)).map((w) => measure(w, legendSize)));
    const room = Math.max(figureWidth * 0.33 - chrome, longestWord);
    out = shown.map((e) => {
      const lines = wrapLegendLabel(e.label, room, (t) => measure(t, legendSize));
      return lines.length > 1 ? { ...e, lines } : e;
    });
    wantedRight = chrome + widestLabel(out);
  }
  return { entries: out, layout, outsideRightWidth: wantedRight };
}

/** A hidden legend layout (no entries) — for chart kinds that don't legend. */
const NO_LEGEND: LegendLayout = { position: "none", orientation: "vertical", border: false, background: false, gap: 12, inset: 8, symbolScale: 1, swatchWidth: 18 };

/**
 * A legend for a kind whose groups are already named on the category axis — box, violin, scatter,
 * raincloud, floating bar, ridgeline.
 *
 * The Inspector offers the whole Legend section on these kinds, so "Show → Always" must draw
 * something. The entries exist (one per group, in the colour that group is drawn in), so they
 * are built and the user decides whether to show them.
 *
 * **Default off, not `entries.length >= 2`.** The usual auto rule would put a legend on every
 * saved box plot — a saved figure must not change when the user has not asked for a legend.
 * It appears only when the user explicitly asks for it, which matches the redundancy argument
 * (it repeats the tick labels).
 */
function groupLegend(
  plot: Plot,
  datasets: { id: NodeId; name: string }[],
  palette: readonly string[] | undefined,
  measure: (text: string, fontPx: number) => number,
  legendSize: number,
  figureWidth?: number,
): { entries: LegendEntry[]; layout: LegendLayout; outsideRightWidth: number } {
  // A listed line (`Annotation.inLegend`) is a legend the user asked for: under "auto" the block shows with that
  // row alone - the group rows stay off, since they were not asked for.
  const listsLines = (plot.annotations ?? []).some((a) => a.inLegend && canJoinLegend(a.kind));
  const onlyLines = plot.legend?.show === undefined && listsLines;
  const legPlot: Plot = { ...plot, legend: { ...plot.legend, show: plot.legend?.show ?? (onlyLines ? undefined : false) } };
  const entries = onlyLines ? [] : datasets.map((ds, i) => ({
    label: ds.name,
    color: plot.seriesStyles?.[ds.id]?.color ?? seriesColor(i, palette),
    select: { as: "series" as const, id: ds.id },
  }));
  return resolveLegend(legPlot, entries, measure, legendSize, figureWidth);
}

/**
 * Value-axis headroom for significance markers (auto-placed and user-dragged).
 *
 * Value domains are built from the data alone, so a stack of brackets sitting above the
 * maximum would fall outside the axis and be dropped — the user asks for brackets and gets
 * none, or gets the low ones only. Reserve a stable count-based ladder above the data for
 * every significance bracket (see body), and fold explicit heights in on top so a bracket
 * parked above the ladder is never clipped.
 *
 * Gated on `role === "significance"`, so a hand-made bracket (`role` unset) keeps its
 * exact domain. Note: a saved figure whose significance bracket sits below the ladder
 * gains that ladder of headroom (the bracket sits a little lower), so that user brackets
 * do not reshape the axis and a re-drag slides 1:1 instead of pinning; a bracket already
 * above the ladder is unchanged.
 */
function significanceHeadroom(plot: Plot, dataValues: readonly number[] = []): number[] {
  const hs: number[] = [];
  let sigN = 0;
  for (const a of plot.annotations ?? []) {
    if (a.kind !== "bracket" || a.role !== "significance") continue;
    sigN += 1;
    if (typeof a.bracketY === "number" && Number.isFinite(a.bracketY)) hs.push(a.bracketY);
  }
  // Reserve a stable ladder of room above the data for every significance bracket — whether
  // auto-placed (no height of its own) or explicitly positioned by a drag. The reservation is
  // count-based, so it does not track the dragged height, and that is what makes a re-drag feel
  // right: folding only each explicit bracket's exact height into the domain would pin it —
  // raising the bracket would grow the domain in lockstep (domain ≈ bracketY·1.04 → constant
  // fraction → the pixel never moves). With a fixed
  // reservation, an explicit bracket slides 1:1 within it. The exact heights are still folded in
  // (`hs.push` above) only so a bracket parked above the reservation is never clipped — never to
  // drive the domain while it sits below it. One rung per bracket, matching the auto-placer's
  // 6% + 8.5% ladder, capped so a long list of comparisons cannot flatten the data to a stripe.
  if (sigN > 0 && dataValues.length > 0) {
    const finite = dataValues.filter((v) => Number.isFinite(v));
    if (finite.length > 0) {
      const hi = Math.max(...finite);
      const lo = Math.min(...finite);
      const span = hi - lo || Math.abs(hi) || 1;
      hs.push(hi + span * Math.min(0.34, 0.06 + 0.085 * (Math.min(sigN, 4) - 1) + 0.06));
    }
  }
  if (hs.length === 0) return [];
  // Include the topmost bracket and a little above it: the label sits above the bar, so a
  // domain that merely reaches the top bracket clips its stars — or rounds the bracket
  // itself half a pixel outside the axis and drops it.
  const hi = Math.max(...hs);
  const lo = Math.min(...hs);
  const pad = Math.max(Math.abs(hi - lo) * 0.25, Math.abs(hi) * 0.04, 1e-9);
  return [...hs, hi + pad];
}

/**
 * The stroke path of one significance bracket, in the shape the user chose.
 *
 * Written once in an axis-neutral frame — "along" runs down the category axis, "value"
 * down the value axis — so the transposed form is a coordinate swap rather than a second
 * copy of the geometry. `dir` is which way the end-ticks turn back toward the data:
 * down (+1) on an ordinary chart, left (−1) when the value axis is X.
 *
 * Caution: `shape: "bracket"` with `tick: 6` must keep emitting a byte-identical path —
 * `value-axis.test.ts` checks bracket orientation against built pixels, and every saved
 * figure re-renders through here.
 */
function bracketPath(
  a1: number,
  a2: number,
  v: number,
  tick: number,
  shape: BracketShape,
  transposed: boolean,
  /** Per-leg tick lengths when the legs reach down to their own bars;
   *  undefined = both legs `tick` long (the default look). */
  legs?: { t1: number; t2: number } | undefined,
): string {
  const dir = transposed ? -1 : 1;
  const P = (along: number, value: number): string => (transposed ? `${value},${along}` : `${along},${value}`);
  const t = Math.max(0, tick);
  // A zero-length tick is a plain bar, so both routes to that look agree.
  if (shape === "line" || t === 0) return `M${P(a1, v)} L${P(a2, v)}`;
  const s = a2 >= a1 ? 1 : -1;
  const span = Math.abs(a2 - a1);
  const t1 = Math.max(t, legs?.t1 ?? t);
  const t2 = Math.max(t, legs?.t2 ?? t);
  if (shape === "brace") {
    // A curly brace: two shoulders turning back to the data, meeting at a peak that
    // points at the label. `q` is the shoulder radius, capped so a narrow bracket
    // (adjacent categories) degrades to a small brace instead of self-crossing.
    const q = Math.min(8, span / 4, t);
    const mid = (a1 + a2) / 2;
    const peak = v - (dir * t) / 2;
    return (
      `M${P(a1, v + dir * t)} Q${P(a1, v)} ${P(a1 + s * q, v)}`
      + ` L${P(mid - s * q, v)} Q${P(mid, v)} ${P(mid, peak)}`
      + ` Q${P(mid, v)} ${P(mid + s * q, v)}`
      + ` L${P(a2 - s * q, v)} Q${P(a2, v)} ${P(a2, v + dir * t)}`
    );
  }
  if (shape === "rounded") {
    const r = Math.min(4, span / 2, t);
    return (
      `M${P(a1, v + dir * t1)} L${P(a1, v + dir * r)} Q${P(a1, v)} ${P(a1 + s * r, v)}`
      + ` L${P(a2 - s * r, v)} Q${P(a2, v)} ${P(a2, v + dir * r)} L${P(a2, v + dir * t2)}`
    );
  }
  return `M${P(a1, v + dir * t1)} L${P(a1, v)} L${P(a2, v)} L${P(a2, v + dir * t2)}`;
}

/**
 * Kinds with no axes an annotation could anchor to. Returning an empty list is right; doing
 * it silently is not — the user placed the object and it would simply vanish. Say so instead.
 */
function refuseAnnotations(plot: Plot, what: string, warnings: string[]): AnnotationScene[] {
  const n = (plot.annotations ?? []).length;
  if (n > 0) {
    warnings.push(`${n === 1 ? "An annotation is" : `${n} annotations are`} not drawn: ${what} has no axes to place them on.`);
  }
  return [];
}

/**
 * Kinds with a real plot rect but no continuous value axis: text, boxes, ellipses, arrows,
 * callouts, images and bands are all positioned as fractions of that rect, so they place
 * fine. Reference lines and brackets need an axis value and are reported by the guard
 * inside `buildAnnotations` rather than disappearing.
 */
function fractionalAnnotations(
  plot: Plot,
  rect: { x: number; y: number; width: number; height: number },
  warnings: string[],
): AnnotationScene[] {
  return buildAnnotations(plot, rect, { x: null, y: () => undefined, bracketX: () => undefined }, false, warnings);
}

/**
 * Resolve figure-level annotations (objects on the assembler canvas) to
 * scene geometry. These store canvas px, not plot fractions — resolving against the unit
 * rect makes the shared fractional math a pure passthrough (px·1 = px), so the figure canvas
 * reuses the one annotation resolver instead of growing a parallel one. Axis-locked kinds
 * (reference lines, brackets, bands) have no axis on a canvas and are refused into
 * `warnings`, never silently dropped.
 */
export function resolveFigureAnnotations(annotations: Annotation[], warnings: string[]): AnnotationScene[] {
  // A power-of-two rect, with the px pre-divided in: px/2^20 · 2^20 is exact in floats, so
  // stored px come back untouched. Resolving at a huge rect (rather than the unit rect)
  // matters for one kind — "text" clamps its fraction to [0,1] to stay reachable on a plot,
  // which at a unit rect would clamp every px coordinate to 1.
  const BIG = 1 << 20;
  const scale = (a: Annotation): Annotation => ({
    ...a,
    ...(a.x != null ? { x: a.x / BIG } : {}),
    ...(a.y != null ? { y: a.y / BIG } : {}),
    ...(a.x2 != null ? { x2: a.x2 / BIG } : {}),
    ...(a.y2 != null ? { y2: a.y2 / BIG } : {}),
    ...(a.w != null ? { w: a.w / BIG } : {}),
    ...(a.h != null ? { h: a.h / BIG } : {}),
  });
  const holder: Plot = { id: "__figure__", name: "", annotations: annotations.map(scale) } as Plot;
  return fractionalAnnotations(holder, { x: 0, y: 0, width: BIG, height: BIG }, warnings);
}

/**
 * A text / callout's text box: its wrapped lines, their alignment inside the box and the box
 * (background + border) behind them. Undefined when none of those settings is set, so a plain text draws with no
 * box. A callout's border takes its arrow's width and dash - the two are one outline.
 */
function annotationTextBox(a: Annotation, label: string, fontSize: number, x: number, y: number, wrapPx: number | undefined): AnnotationScene["textBox"] {
  const boxed = a.fill != null || a.borderColor != null;
  if (!boxed && a.align == null && wrapPx == null && a.padding == null && a.radius == null) return undefined;
  const t = layoutTextBox(label, { fontSize, align: a.align, wrapPx, padding: a.padding, radius: a.radius }, x, y);
  const bw = a.width ?? 1;
  const box = boxed
    ? {
        ...t.box,
        fill: a.fill ?? null,
        fillOpacity: a.fillOpacity ?? 1,
        stroke: a.borderColor ?? null,
        strokeWidth: a.borderColor ? bw : 0,
        dash: a.borderColor && a.dash && a.dash !== "solid" ? dashArray(a.dash, bw) : null,
      }
    : undefined;
  return { lines: t.lines, x: t.x, anchor: t.anchor, ...(box ? { box } : {}) };
}

/**
 * Resolve the plot's annotations to pixel-space geometry (the annotation layer).
 * Reference lines map their axis value through the scale and span the plot; a line
 * whose value falls outside the visible range (or off a log axis) is dropped.
 * `mapX` null = a categorical X axis (vertical reference lines don't apply).
 */
function buildAnnotations(
  plot: Plot,
  rect: { x: number; y: number; width: number; height: number },
  maps: {
    /** Continuous X → pixel (vertical reference lines); null on a categorical axis. */
    x: ((v: number) => number | undefined) | null;
    /** Data Y → pixel (horizontal lines + bracket heights). */
    y: (v: number) => number | undefined;
    /** Bracket endpoint X → pixel (data x on XY; category centre on bar/box). */
    bracketX: (v: number) => number | undefined;
    /** Cell endpoint → pixel: the centre of one sub-bar (1-based `series`) inside category
     *  `cat` — the within-group comparison. Provided only by builders
     *  with side-by-side bars in a category (the grouped bar, either orientation); absent
     *  everywhere else, and a bracket naming a series there is refused with a warning. */
    bracketCellX?: ((cat: number, series: number) => number | undefined) | undefined;
    /** Value-axis pixel of the farthest ink (bar end · error-bar tip · swarm point) at an
     *  endpoint — the whole category, or one sub-bar when `series` is given. Lets a bracket's
     *  legs reach down to each bar (`significance.legs === "reach"`). Provided by the bar
     *  builders only; elsewhere the option is refused with a warning. */
    bracketTop?: ((cat: number, series: number | undefined) => number | undefined) | undefined;
    /** X shows names, though `x` places things by category position (estimation: brackets and reference lines stand on
     *  a group). A point cannot be pinned to an X value there - there is none - so `anchorX` is refused. */
    namesOnX?: true | undefined;
  },
  /**
   * Transposed layout (horizontal bars): the value axis is X and categories band
   * down Y. A value reference line (hline or vline — X is the only continuous
   * axis) becomes a vertical line at the value; a bracket spans categories along
   * Y at a value-height on X. `maps.x` = value→X, `maps.bracketX` = category→Y.
   */
  transposed = false,
  /**
   * Out-param: why an annotation the user placed did not draw.
   *
   * A dropped annotation would be a silent no-op — the same defect class `strict.ts` exists to
   * prevent, one layer down. Every `continue` below records a reason here instead, and the
   * scene surfaces it.
   */
  warnings?: string[],
): AnnotationScene[] {
  const { x: mapX, y: mapY, bracketX, bracketCellX, bracketTop, namesOnX } = maps;
  /**
   * Legs that reach the bars: an option that runs each bracket's legs down to the bars
   * beneath it, however low they are. With `significance.legs === "reach"` each leg runs from the bracket bar down
   * to `LEG_GAP` px above the ink under its own end — never shorter than the normal tick.
   * Brace and plain-line shapes have no straight legs to lengthen and keep their look.
   */
  // Per bracket (`bracketLegs`), else the plot-wide default — exactly how the shape resolves.
  const reachLegsOf = (a: { bracketLegs?: "equal" | "reach" | undefined }): boolean => (a.bracketLegs ?? plot.significance?.legs) === "reach";
  const LEG_GAP = 4;
  let reachRefused = false;
  const legsFor = (
    a: { bracketLegs?: "equal" | "reach" | undefined },
    v: number,
    dir: 1 | -1,
    tick: number,
    end1: { cat: number; series?: number | undefined; ff: boolean },
    end2: { cat: number; series?: number | undefined; ff: boolean },
  ): { t1: number; t2: number } | undefined => {
    if (!reachLegsOf(a)) return undefined;
    if (!bracketTop) { reachRefused = true; return undefined; }
    const leg = (e: { cat: number; series?: number | undefined; ff: boolean }): number => {
      if (e.ff) return tick; // a freeform (dragged) end stands on nothing — keep the tick
      const ink = bracketTop(e.cat, e.series);
      if (ink == null || !Number.isFinite(ink)) return tick;
      // Distance from the bar to just short of the ink, along the value axis, in the leg's direction.
      return Math.max(tick, dir * (ink - v) - LEG_GAP);
    };
    return { t1: leg(end1), t2: leg(end2) };
  };
  /**
   * One bracket endpoint → pixel along the category axis. A `series` refinement targets the
   * sub-bar's centre (within-group comparison); without one, the whole-category centre as
   * always. Returns a reason string instead of a position when the endpoint cannot exist
   * here, so the refusal is said in the scene's warnings rather than silently dropped.
   */
  const bracketEndPx = (cat: number | undefined, series: number | undefined): number | { reason: string } | undefined => {
    if (cat == null) return undefined;
    if (series == null) return bracketX(cat);
    if (!bracketCellX) {
      return { reason: "a bracket endpoint names a bar inside a category, but this chart has no side-by-side bars there — only the grouped bar layout does" };
    }
    return bracketCellX(cat, series);
  };
  const out: AnnotationScene[] = [];
  // A text box's size when the text sets none: the legend font the renderer falls back to.
  const textBoxFont = (): number => resolveFonts(plot).legend.size;
  // Data anchors: a point pinned to axis values goes through the same value->pixel maps a reference line uses
  // (on horizontal bars the value axis is X, as for the transposed hline). An axis that cannot take a value keeps the
  // plot position; a value off the axis is drawn at the plot's edge (never dropped - that would hide the user's text);
  // both say so. Never `locked`: an anchored point still drags (the renderer writes the dragged spot back as values).
  const anchorNotes = new Set<string>();
  const anchorPoint = (a: Annotation, px: number, py: number): { x: number; y: number; anchored?: "x" | "y" | "xy"; across?: true } => {
    let x = px, y = py, gx = false, gy = false;
    const edge = (v: number, lo: number, hi: number): number => {
      if (v < lo - 0.5 || v > hi + 0.5) anchorNotes.add("An annotation pinned to a data value lies outside the axis range; it is drawn at the plot's edge.");
      return Math.min(hi, Math.max(lo, v));
    };
    if (a.anchorX != null) {
      const v = transposed || !mapX || namesOnX ? undefined : mapX(a.anchorX);
      if (v == null || !Number.isFinite(v)) anchorNotes.add("An annotation pinned to an X value stays at its plot position: this chart's X axis does not take values.");
      else { x = edge(v, left, right); gx = true; }
    }
    if (a.anchorY != null) {
      const v = transposed ? mapX?.(a.anchorY) : mapY(a.anchorY);
      if (v == null || !Number.isFinite(v)) anchorNotes.add("An annotation pinned to a Y value stays at its plot position: this chart cannot place that value.");
      else if (transposed) { x = edge(v, left, right); gy = true; }
      else { y = edge(v, top, bot); gy = true; }
    }
    const anchored = gx && gy ? "xy" : gx ? "x" : gy ? "y" : undefined;
    return { x, y, ...(anchored ? { anchored } : {}), ...(gy && transposed ? { across: true as const } : {}) };
  };
  /** Record a drop, de-duplicated by reason so N off-range lines say it once. */
  const dropReasons = new Map<string, number>();
  const dropAnn = (reason: string): void => {
    dropReasons.set(reason, (dropReasons.get(reason) ?? 0) + 1);
  };
  const top = rect.y;
  const bot = rect.y + rect.height;
  const left = rect.x;
  const right = rect.x + rect.width;
  // Plot-wide significance formatting: a bracket with a stored p renders its label
  // from that p (live), and inherits the plot's bracket colour/width as defaults.
  const sig = plot.significance;
  // Precedence: a label the user typed wins, then the live p, then the stored label.
  // The override is what makes a p-carrying bracket renameable at all — without it the
  // typed text would be stored and silently ignored here; `annotation-census.test.tsx`
  // checks it by rebuilding the scene and reading the label back.
  const bracketLabel = (a: {
    p?: number | undefined;
    label?: string | undefined;
    labelOverride?: string | undefined;
    showSymbol?: boolean | undefined;
    showP?: boolean | undefined;
  }): string | undefined => {
    if (a.labelOverride != null && a.labelOverride !== "") return a.labelOverride;
    if (a.p == null) return a.label;
    // Per-bracket label parts: the clicked bracket's own tickboxes —
    // significance signs and/or the numeric p — compose the text. Both unset = the
    // plot-wide display verbatim, so every saved figure keeps the text it had.
    if (a.showSymbol != null || a.showP != null) {
      const parts: string[] = [];
      if (a.showSymbol ?? true) {
        parts.push(formatSignificance(a.p, "stars", sig?.decimals, sig?.exactP, { thresholds: sig?.thresholds, nsSymbol: sig?.nsSymbol }));
      }
      if (a.showP ?? false) {
        parts.push(formatSignificance(a.p, "numeric", sig?.decimals, sig?.exactP, { thresholds: sig?.thresholds, nsSymbol: sig?.nsSymbol }));
      }
      return parts.filter((t) => t !== "").join(" ");
    }
    // Options named explicitly rather than passed as one blob: the test that checks every
    // style field is read by a builder searches builder sources for each field, and a field
    // hidden behind a helper would look unread to it. Naming them here also documents which
    // parts of the style the drawing honours.
    return formatSignificance(a.p, sig?.display, sig?.decimals, sig?.exactP, {
      thresholds: sig?.thresholds,
      nsSymbol: sig?.nsSymbol,
    });
  };
  /**
   * `hideNs` (default true): a comparison that clears no rung is dropped entirely, not just
   * left unlabelled — a bracket with no text says nothing and still costs vertical space.
   * Decided from the p against the ladder, never from the rendered string, so a user whose
   * ns symbol happens to be "*" (or who typed "ns" as a real label) is unaffected.
   *
   * A typed label always survives: overriding the text is the user saying "draw this one",
   * and it is how a deliberate "n.s." is shown.
   */
  const bracketHidden = (a: { p?: number | undefined; labelOverride?: string | undefined }): boolean =>
    (sig?.hideNs ?? true)
    && a.p != null
    && (a.labelOverride == null || a.labelOverride === "")
    && !resolveThresholds(sig?.thresholds, sig?.display ?? "stars").some((t) => a.p! < t.p);
  const bracketColor = (a: { color?: string | undefined }): string | null => a.color ?? sig?.color ?? null;
  const bracketWidth = (a: { width?: number | undefined }): number => a.width ?? sig?.width ?? 1.5;
  // Shape / end-tick length: per-bracket first, then the plot-wide `shape` and `tick`.
  const bracketShapeOf = (a: { bracketShape?: BracketShape | undefined }): BracketShape =>
    a.bracketShape ?? sig?.shape ?? "bracket";
  const bracketTick = (): number => (typeof sig?.tick === "number" && Number.isFinite(sig.tick) ? Math.max(0, sig.tick) : 6);
  /** Free lateral offset along the category axis, px. Fraction of the plot's extent, so it
   *  survives a figure resize the way every other fractional annotation does. */
  const bracketShiftPx = (a: { bracketShift?: number | undefined }, extent: number): number =>
    typeof a.bracketShift === "number" && Number.isFinite(a.bracketShift) ? a.bracketShift * extent : 0;
  /** Symbol size above the bar: this bracket's own, then the plot-wide `labelSize`,
   *  then the renderer's legend size. Named here rather than passed as a blob — this is
   *  the line that decides which parts of the style the drawing honours. */
  const bracketLabelSize = (a: { size?: number | undefined }): number | undefined => {
    const n = a.size ?? sig?.labelSize;
    return typeof n === "number" && Number.isFinite(n) && n > 0 ? n : undefined;
  };
  /** Symbol colour: the bracket's own unless `labelColor` splits the two (black stars
   *  over a grey bracket is a common house style). */
  const bracketLabelColor = (a: { color?: string | undefined }): string | null => sig?.labelColor ?? bracketColor(a);
  /**
   * Default heights for brackets carrying no `bracketY` — a stagger, not one shared line.
   *
   * Without a stagger every unplaced bracket would land on the same default (6% down from the
   * top of the plot), so three of them would draw on top of each other and read as one broken
   * mark. The auto-placer stacks only the ones it creates, so hand-added brackets are staggered
   * here.
   *
   * Widest span on top: a wide bracket crossing under a narrow one reads as a mistake,
   * and this is the layout every figure with stacked comparisons uses. Ties keep document
   * order, so the result is stable across rebuilds.
   */
  const autoLevel = new Map<string, number>();
  {
    const span = (a: { from?: number | undefined; to?: number | undefined }): number => Math.abs((a.to ?? 0) - (a.from ?? 0));
    (plot.annotations ?? [])
      .map((a, i) => ({ a, i }))
      .filter(({ a }) => a.kind === "bracket" && a.bracketY == null && !bracketHidden(a))
      .sort((p, q) => span(q.a) - span(p.a) || p.i - q.i)
      .forEach(({ a }, k) => autoLevel.set(a.id, k));
  }
  /** Fraction of the plot to sit in from the value-axis's high end, for level `k`.
   *  Clamped so a long stack walks toward the data instead of off the axis. */
  const autoBracketInset = (id: string): number => Math.min(0.45, 0.06 + 0.07 * (autoLevel.get(id) ?? 0));
  for (const a of plot.annotations ?? []) {
    const width = a.width ?? 1.5;
    const dash = dashArray(a.dash ?? "dashed", width);
    const color = a.color ?? null;
    if (transposed && (a.kind === "hline" || a.kind === "vline")) {
      // Both reference-line kinds mark a value; on horizontal bars that draws
      // vertically at the value position on X.
      if (a.value == null || !mapX) { dropAnn("a reference line needs a continuous X axis, which this chart does not have"); continue; }
      const px = mapX(a.value);
      if (px == null || px < left - 0.5 || px > right + 0.5) { dropAnn("a reference line sits outside the axis range"); continue; }
      out.push({
        id: a.id,
        kind: "line",
        x1: px,
        y1: top,
        x2: px,
        y2: bot,
        color,
        dash,
        width,
        ...(a.label ? { label: a.label, labelX: px + 4, labelY: top + 12, labelAnchor: "start" as const } : {}),
      });
    } else if (transposed && a.kind === "bracket") {
      if (bracketHidden(a)) continue; // hideNs: drop the whole element, not just its text
      if (a.from == null || a.to == null) { dropAnn("a bracket needs both endpoints set"); continue; }
      const shift = bracketShiftPx(a, rect.height); // the category axis is Y here
      // Freeform ends: a dragged handle stores its end as a plot-rect
      // fraction in x/x2; an end never dragged keeps standing on its group.
      const f1 = a.freeform && a.x != null ? rect.y + a.x * rect.height : undefined;
      const f2 = a.freeform && a.x2 != null ? rect.y + a.x2 * rect.height : undefined;
      const e1 = f1 ?? bracketEndPx(a.from, a.fromSeries); // category (or sub-bar) centre → Y
      const e2 = f2 ?? bracketEndPx(a.to, a.toSeries);
      if (typeof e1 === "object" || typeof e2 === "object") { dropAnn((typeof e1 === "object" ? e1 : (e2 as { reason: string })).reason); continue; }
      const cy1 = e1 ?? null;
      const cy2 = e2 ?? null;
      if (cy1 == null || cy2 == null) { dropAnn("a bracket endpoint is not a category on this chart"); continue; }
      const ay1 = cy1 + shift;
      const ay2 = cy2 + shift;
      // Value-height on X: the given value, else a staggered default near the high (right) end.
      const xPos = a.bracketY != null ? mapY(a.bracketY) : right - rect.width * autoBracketInset(a.id);
      if (xPos == null || xPos < left - 0.5 || xPos > right + 0.5) { dropAnn("a bracket height sits outside the value axis"); continue; }
      const shape = bracketShapeOf(a);
      const legsT = legsFor(a, xPos, -1, bracketTick(), { cat: a.from, series: a.fromSeries, ff: f1 != null }, { cat: a.to, series: a.toSeries, ff: f2 != null });
      const path = bracketPath(ay1, ay2, xPos, bracketTick(), shape, true, legsT);
      const legEndsT = legsT && (shape === "bracket" || shape === "rounded") ? { v1: xPos - legsT.t1, v2: xPos - legsT.t2 } : undefined;
      const lbl = bracketLabel(a);
      const lblSize = bracketLabelSize(a);
      out.push({
        id: a.id,
        kind: "bracket",
        path,
        // The two end-tick bases, reported alongside the path: the renderer needs real
        // endpoints to draw the magnetic home guide and to place the delete handle on a
        // bracket with no label (without them it would fall back to 0,0, off the canvas).
        x1: xPos,
        y1: ay1,
        x2: xPos,
        y2: ay2,
        color: bracketColor(a),
        ...(shape === "rounded" ? { round: true } : {}),
        ...(shift ? { shift } : {}),
        ...(a.bracketY == null ? { autoY: true } : {}),
        ...(a.bracketY != null && a.plannedY ? { plannedY: true } : {}),
        ...(a.freeform ? { freeform: true } : {}),
        ...(legEndsT ? { legEnds: legEndsT } : {}),
        dash: null,
        width: bracketWidth(a),
        ...(lbl
          ? {
              label: lbl,
              labelX: xPos + 4,
              labelY: (ay1 + ay2) / 2,
              labelAnchor: "start" as const,
              ...(lblSize ? { fontSize: lblSize } : {}),
              ...(sig?.labelColor ? { labelColor: bracketLabelColor(a) } : {}),
            }
          : {}),
      });
    } else if (a.kind === "hline") {
      if (a.value == null) { dropAnn("a reference line needs a value"); continue; }
      const py = mapY(a.value);
      if (py == null || py < top - 0.5 || py > bot + 0.5) { dropAnn("a reference line sits outside the axis range"); continue; }
      out.push({
        id: a.id,
        kind: "line",
        x1: left,
        y1: py,
        x2: right,
        y2: py,
        color,
        dash,
        width,
        // The caption drags on its own (`refLineLabelOffsets`), because a reference line's
        // readout lands on top of the data it describes and the line itself must not move.
        // Bland-Altman gets this by pushing its own scene annotation; every other reference
        // line comes through here.
        // Only a registered reference line gets the caption drag. `moveRefLineLabel` writes
        // `refLineLabelOffsets`, which is keyed by reference-line id, so offering it on a user's
        // own hline would advertise a move the document has to refuse. A user line is not
        // locked: the whole annotation drags.
        ...(a.label
          ? { label: a.label, labelX: right - 4, labelY: py - 4, labelAnchor: "end" as const,
              ...(isReferenceLine(a.id) ? { labelOffset: plot.refLineLabelOffsets?.[a.id] ?? { dx: 0, dy: 0 } } : {}) }
          : {}),
      });
    } else if (a.kind === "vline") {
      if (a.value == null || !mapX) { dropAnn("a reference line needs a continuous X axis, which this chart does not have"); continue; }
      const px = mapX(a.value);
      if (px == null || px < left - 0.5 || px > right + 0.5) { dropAnn("a reference line sits outside the axis range"); continue; }
      out.push({
        id: a.id,
        kind: "line",
        x1: px,
        y1: top,
        x2: px,
        y2: bot,
        color,
        dash,
        width,
        ...(a.label ? { label: a.label, labelX: px + 4, labelY: top + 12, labelAnchor: "start" as const } : {}),
      });
    } else if (transposed && (a.kind === "vband" || a.kind === "hband") && a.bandLo != null && a.bandHi != null) {
      // A data-anchored band marks a value range, and on a transposed chart the value axis
      // is X — so both kinds draw as a vertical band there, the same swap rule hline/vline
      // follow above. (The generic path would feed the value→X pixels into y1/y2, so a
      // threshold zone on a horizontal bar would land as a meaningless horizontal stripe.
      // Fractional bands are placement, not values, and take the generic path.)
      if (!mapX) { dropAnn("a data-valued band needs a continuous value axis, which this chart does not have"); continue; }
      const lo = Math.min(a.bandLo, a.bandHi);
      const hi = Math.max(a.bandLo, a.bandHi);
      const pLo = mapX(lo), pHi = mapX(hi);
      if (pLo == null || pHi == null) { dropAnn("a data-valued band's range is off the axis"); continue; }
      const bx1 = Math.max(left, Math.min(right, Math.min(pLo, pHi)));
      const bx2 = Math.max(left, Math.min(right, Math.max(pLo, pHi)));
      if (bx2 - bx1 < 0.5) { dropAnn("a data-valued band sits entirely outside the axis range"); continue; }
      out.push({
        id: a.id,
        kind: "band",
        x1: bx1, y1: top, x2: bx2, y2: bot,
        color: a.color ?? null,
        fill: a.fill ?? a.color ?? "#888888",
        fillOpacity: a.fillOpacity ?? 0.14,
        dash: null,
        width: a.width ?? 0,
        locked: true, // value-anchored: edited by value, never dragged (same as the generic branch)
        ...(a.label ? { label: a.label, labelX: (bx1 + bx2) / 2, labelY: top + 12, labelAnchor: "middle" as const } : {}),
      });
    } else if (a.kind === "vband" || a.kind === "hband") {
      // Shaded region behind the plot. Two anchoring modes:
      //  · fractional (default): vband = X range [x, x+w] × full height; hband = Y range
      //    [y, y+h] × full width — fractions keep it placed on figure resize.
      //  · data-anchored (bandLo/bandHi set): the band spans an axis-value range, mapped
      //    through the same value→pixel scale a reference line uses (mapX/mapY), so it tracks
      //    the axis and clips to it. Axis-locked (see `locked` below): edited by value, not
      //    dragged. A vband needs a continuous X — like a vline, it refuses otherwise.
      const fill = a.fill ?? a.color ?? "#888888";
      const fillOpacity = a.fillOpacity ?? 0.14;
      const dataAnchored = a.bandLo != null && a.bandHi != null;
      let x1: number, x2: number, y1: number, y2: number;
      if (dataAnchored) {
        const lo = Math.min(a.bandLo!, a.bandHi!);
        const hi = Math.max(a.bandLo!, a.bandHi!);
        if (a.kind === "vband") {
          if (!mapX) { dropAnn("a data-valued vertical band needs a continuous X axis, which this chart does not have"); continue; }
          const pLo = mapX(lo), pHi = mapX(hi);
          if (pLo == null || pHi == null) { dropAnn("a data-valued band's range is off the axis"); continue; }
          x1 = Math.max(left, Math.min(right, Math.min(pLo, pHi)));
          x2 = Math.max(left, Math.min(right, Math.max(pLo, pHi)));
          y1 = top;
          y2 = bot;
          // Clipping collapsed the span → the whole zone sits beyond the X axis. Say so rather
          // than drawing a hairline (the generic "zero size" message below would misdescribe it).
          if (x2 - x1 < 0.5) { dropAnn("a data-valued band sits entirely outside the axis range"); continue; }
        } else {
          const pLo = mapY(lo), pHi = mapY(hi);
          if (pLo == null || pHi == null) { dropAnn("a data-valued band's range is off the axis"); continue; }
          y1 = Math.max(top, Math.min(bot, Math.min(pLo, pHi)));
          y2 = Math.max(top, Math.min(bot, Math.max(pLo, pHi)));
          x1 = left;
          x2 = right;
          if (y2 - y1 < 0.5) { dropAnn("a data-valued band sits entirely outside the axis range"); continue; }
        }
      } else if (a.kind === "vband") {
        const fx = Math.min(1, Math.max(0, a.x ?? 0.4));
        const fw = Math.min(1 - fx, Math.max(0, a.w ?? 0.2));
        x1 = left + fx * rect.width;
        x2 = left + (fx + fw) * rect.width;
        y1 = top;
        y2 = bot;
      } else {
        const fy = Math.min(1, Math.max(0, a.y ?? 0.4));
        const fh = Math.min(1 - fy, Math.max(0, a.h ?? 0.2));
        y1 = top + fy * rect.height;
        y2 = top + (fy + fh) * rect.height;
        x1 = left;
        x2 = right;
      }
      if (x2 <= x1 || y2 <= y1) { dropAnn("a shape has zero or negative size"); continue; }
      const lbl = a.label;
      out.push({
        id: a.id,
        kind: "band",
        x1, y1, x2, y2,
        color: a.color ?? null,
        fill,
        fillOpacity,
        dash: null,
        width: a.width ?? 0,
        // A data-anchored band's geometry is the axis value — the renderer must not offer a
        // move/resize handle (like a reference line or a PCA loading arrow). A user lock is
        // applied to every kind by the pass at the end of this loop; this covers the value case.
        ...(dataAnchored ? { locked: true } : {}),
        // A vband spans the full height → its label sits just inside the plot top. An hband
        // spans a Y range → the label sits just inside its own top edge, or two stacked
        // zones would both print at the plot top and overtype each other (e.g. a waterfall's
        // Response/Progression zones).
        ...(lbl ? { label: lbl, labelX: (x1 + x2) / 2, labelY: (a.kind === "hband" ? Math.min(y1, y2) : top) + 12, labelAnchor: "middle" as const } : {}),
      });
    } else if (a.kind === "text") {
      if (!a.label) { dropAnn("a text annotation has no text"); continue; }
      const fx = Math.min(1, Math.max(0, a.x ?? 0.5));
      const fy = Math.min(1, Math.max(0, a.y ?? 0.12));
      const at = anchorPoint(a, left + fx * rect.width, top + fy * rect.height);
      const textBox = annotationTextBox(a, a.label, a.size ?? textBoxFont(), at.x, at.y, a.w != null ? a.w * rect.width : undefined);
      out.push({
        id: a.id,
        kind: "text",
        color,
        dash: null,
        width: 0,
        label: a.label,
        labelX: at.x,
        labelY: at.y,
        labelAnchor: "middle" as const,
        ...(at.anchored ? { anchored: at.anchored } : {}),
        ...(at.across ? { anchorAcross: true } : {}),
        ...(a.size ? { fontSize: a.size } : {}),
        ...(a.fontFamily ? { fontFamily: a.fontFamily } : {}),
        ...(a.bold ? { bold: true } : {}),
        ...(a.italic ? { italic: true } : {}),
        ...(a.rotation ? { rotation: a.rotation } : {}),
        ...(textBox ? { textBox } : {}),
      });
    } else if (a.kind === "bracket") {
      if (bracketHidden(a)) continue; // hideNs: drop the whole element, not just its text
      if (a.from == null || a.to == null) { dropAnn("a bracket needs both endpoints set"); continue; }
      const shift = bracketShiftPx(a, rect.width); // the category axis is X here
      // Freeform ends: a dragged handle stores its end as a plot-rect
      // fraction in x/x2; an end never dragged keeps standing on its group.
      const ff1 = a.freeform && a.x != null ? rect.x + a.x * rect.width : undefined;
      const ff2 = a.freeform && a.x2 != null ? rect.x + a.x2 * rect.width : undefined;
      const ex1 = ff1 ?? bracketEndPx(a.from, a.fromSeries); // category (or sub-bar) centre → X
      const ex2 = ff2 ?? bracketEndPx(a.to, a.toSeries);
      if (typeof ex1 === "object" || typeof ex2 === "object") { dropAnn((typeof ex1 === "object" ? ex1 : (ex2 as { reason: string })).reason); continue; }
      const cx1 = ex1;
      const cx2 = ex2;
      if (cx1 == null || cx2 == null) { dropAnn("a bracket endpoint is not a category on this chart"); continue; }
      const bx1 = cx1 + shift;
      const bx2 = cx2 + shift;
      // Bar height: the given Y value, else a staggered default band near the top of the plot.
      const yTop = a.bracketY != null ? mapY(a.bracketY) : top + rect.height * autoBracketInset(a.id);
      if (yTop == null || yTop < top - 0.5 || yTop > bot + 0.5) { dropAnn("a bracket height sits outside the value axis — raise the axis maximum, or lower the bracket"); continue; }
      const shape = bracketShapeOf(a);
      const legsV = legsFor(a, yTop, 1, bracketTick(), { cat: a.from, series: a.fromSeries, ff: ff1 != null }, { cat: a.to, series: a.toSeries, ff: ff2 != null });
      const path = bracketPath(bx1, bx2, yTop, bracketTick(), shape, false, legsV);
      const legEndsV = legsV && (shape === "bracket" || shape === "rounded") ? { v1: yTop + legsV.t1, v2: yTop + legsV.t2 } : undefined;
      const lbl = bracketLabel(a);
      const lblSize = bracketLabelSize(a);
      out.push({
        id: a.id,
        kind: "bracket",
        path,
        // See the transposed branch: real endpoints for the home guide + delete handle.
        x1: bx1,
        y1: yTop,
        x2: bx2,
        y2: yTop,
        color: bracketColor(a),
        ...(shape === "rounded" ? { round: true } : {}),
        ...(shift ? { shift } : {}),
        ...(a.bracketY == null ? { autoY: true } : {}),
        ...(a.bracketY != null && a.plannedY ? { plannedY: true } : {}),
        ...(a.freeform ? { freeform: true } : {}),
        ...(legEndsV ? { legEnds: legEndsV } : {}),
        dash: null,
        width: bracketWidth(a),
        ...(lbl
          ? {
              label: lbl,
              labelX: (bx1 + bx2) / 2,
              // A brace peaks half a tick above the bar, so its symbol has to clear that
              // or the two overlap — the one shape where the label is not 4px up.
              labelY: yTop - 4 - (shape === "brace" ? bracketTick() / 2 : 0),
              labelAnchor: "middle" as const,
              ...(lblSize ? { fontSize: lblSize } : {}),
              ...(sig?.labelColor ? { labelColor: bracketLabelColor(a) } : {}),
            }
          : {}),
      });
    } else if (a.kind === "rect" || a.kind === "ellipse" || a.kind === "highlight") {
      // Plot-space box (fractional top-left + size) → pixel corners. Resize-safe.
      // A "highlight" is a rect with a bold coloured outline + a faint same-colour
      // tint by default (a highlighter over a region); it renders as a rect scene.
      const isHi = a.kind === "highlight";
      const boxColor = isHi ? a.color ?? "#dc2626" : color;
      const boxWidth = isHi ? a.width ?? 2.5 : width;
      const boxFill = isHi ? a.fill ?? boxColor : a.fill ?? null;
      const boxFillOpacity = isHi ? a.fillOpacity ?? 0.08 : a.fillOpacity ?? 1;
      const fx = a.x ?? 0.32;
      const fy = a.y ?? 0.3;
      const fw = a.w ?? 0.26;
      const fh = a.h ?? 0.2;
      const rx1 = left + fx * rect.width;
      const ry1 = top + fy * rect.height;
      const rx2 = left + (fx + fw) * rect.width;
      const ry2 = top + (fy + fh) * rect.height;
      out.push({
        id: a.id,
        kind: a.kind === "highlight" ? "rect" : a.kind,
        x1: rx1,
        y1: ry1,
        x2: rx2,
        y2: ry2,
        color: boxColor,
        fill: boxFill,
        fillOpacity: boxFillOpacity,
        ...(a.rotation ? { rotation: a.rotation } : {}),
        dash: a.dash && a.dash !== "solid" ? dashArray(a.dash, boxWidth) : null,
        width: boxWidth,
        ...(a.label
          ? {
              label: a.label,
              labelX: (rx1 + rx2) / 2,
              labelY: (ry1 + ry2) / 2 + (a.size ?? 13) * 0.34,
              labelAnchor: "middle" as const,
              ...(a.size ? { fontSize: a.size } : {}),
            }
          : {}),
      });
    } else if (a.kind === "image") {
      // Embedded image in a fractional plot-space box (top-left + size) → pixel
      // corners, mirroring rect. `href` carries the bytes; `fillOpacity` = image
      // opacity; `color`/`width` = an optional border. Resize-safe.
      const fx = a.x ?? 0.32;
      const fy = a.y ?? 0.3;
      const fw = a.w ?? 0.26;
      const fh = a.h ?? 0.2;
      const rx1 = left + fx * rect.width;
      const ry1 = top + fy * rect.height;
      const rx2 = left + (fx + fw) * rect.width;
      const ry2 = top + (fy + fh) * rect.height;
      out.push({
        id: a.id,
        kind: "image",
        href: a.href ?? "",
        x1: rx1,
        y1: ry1,
        x2: rx2,
        y2: ry2,
        color, // optional border colour (null → no border)
        fillOpacity: a.fillOpacity ?? 1,
        ...(a.rotation ? { rotation: a.rotation } : {}),
        dash: a.dash && a.dash !== "solid" ? dashArray(a.dash, width) : null,
        // A border is only drawn when the user gives it a colour; default = none.
        width: a.color ? width : 0,
      });
    } else if (a.kind === "arrow" || a.kind === "segment") {
      // Plot-space line from (x,y) to (x2,y2), fractional. Resize-safe.
      const ax1 = left + (a.x ?? 0.3) * rect.width;
      const ay1 = top + (a.y ?? 0.5) * rect.height;
      const end = anchorPoint(a, left + (a.x2 ?? 0.6) * rect.width, top + (a.y2 ?? 0.5) * rect.height);
      const ax2 = end.x;
      const ay2 = end.y;
      out.push({
        id: a.id,
        kind: a.kind,
        ...(end.anchored ? { anchored: end.anchored } : {}),
        ...(end.across ? { anchorAcross: true } : {}),
        x1: ax1,
        y1: ay1,
        x2: ax2,
        y2: ay2,
        color,
        arrowHead: a.arrowHead ?? (a.kind === "arrow" ? "end" : "none"),
        dash: annotationLineDash(a) ?? null,
        width,
        ...(a.label
          ? {
              label: a.label,
              labelX: (ax1 + ax2) / 2,
              labelY: (ay1 + ay2) / 2 - 5,
              labelAnchor: "middle" as const,
              ...(a.size ? { fontSize: a.size } : {}),
            }
          : {}),
      });
    } else if (a.kind === "callout") {
      // A text label at (x,y) with an arrow pointing to a target (x2,y2). Resize-safe.
      const tx = left + (a.x ?? 0.2) * rect.width;
      const ty = top + (a.y ?? 0.2) * rect.height;
      const tip = anchorPoint(a, left + (a.x2 ?? 0.5) * rect.width, top + (a.y2 ?? 0.5) * rect.height);
      const gx = tip.x;
      const gy = tip.y;
      const textBox = a.label ? annotationTextBox(a, a.label, a.size ?? textBoxFont(), tx, ty, a.w != null ? a.w * rect.width : undefined) : undefined;
      out.push({
        id: a.id,
        kind: "callout",
        ...(tip.anchored ? { anchored: tip.anchored } : {}),
        ...(tip.across ? { anchorAcross: true } : {}),
        x1: tx,
        y1: ty,
        x2: gx,
        y2: gy,
        color,
        fill: a.fill ?? null,
        fillOpacity: a.fillOpacity ?? 1,
        arrowHead: a.arrowHead ?? "end",
        dash: a.dash && a.dash !== "solid" ? dashArray(a.dash, width) : null,
        width,
        label: a.label ?? "",
        labelX: tx,
        labelY: ty,
        labelAnchor: "middle" as const,
        ...(a.size ? { fontSize: a.size } : {}),
        ...(textBox ? { textBox } : {}),
      });
    }
  }
  // A locked annotation can't be dragged (the document layer refuses the move), so the
  // renderer must not offer the affordance. Carried at this single choke point rather than
  // on every per-kind push above.
  const lockedIds = new Set((plot.annotations ?? []).filter((a) => a.locked).map((a) => a.id));
  if (lockedIds.size) for (const s of out) if (lockedIds.has(s.id)) s.locked = true;
  // A line the user drew carries its caption where it was dragged (`Annotation.labelOffset`) - the words
  // move, the line does not. Emitted only once moved, so an untouched graph carries no offset. A reference line
  // the builder owns keeps its own offsets (`refLineLabelOffsets`, above).
  const captionOffsets = new Map((plot.annotations ?? []).filter((a) => a.labelOffset && canJoinLegend(a.kind) && !isReferenceLine(a.id)).map((a) => [a.id, a.labelOffset!] as const));
  if (captionOffsets.size) for (const s of out) { const o = captionOffsets.get(s.id); if (o && s.label) s.labelOffset = o; }
  // A band / reference-line caption takes its annotation's own `size` (clicking a band or
  // line label opens its size). Applied here, once, so every branch above - including the swapped bands and
  // lines of a transposed chart - carries it; an unset size keeps the legend-font fallback the renderer uses.
  const captionSize = new Map((plot.annotations ?? []).filter((a) => a.size != null && (a.kind === "hline" || a.kind === "vline" || a.kind === "hband" || a.kind === "vband")).map((a) => [a.id, a.size as number]));
  if (captionSize.size) for (const s of out) { const z = captionSize.get(s.id); if (z != null && s.label && s.fontSize == null) s.fontSize = z; }
  for (const note of anchorNotes) warnings?.push(note);
  for (const [reason, n] of dropReasons) {
    warnings?.push(n > 1 ? `${n} annotations were not drawn: ${reason}.` : `An annotation was not drawn: ${reason}.`);
  }
  if (reachRefused) warnings?.push("Bracket legs that reach the bars are drawn on bar charts only — this chart keeps equal legs.");
  return out;
}

/** Resolve every figure text element's typography (defaults ⊕ Plot.fonts overrides). */
function resolveFonts(plot: Plot): SceneFonts {
  const f = (el: FontElement): FontSpec | undefined => plot.fonts?.[el];
  const axisBase = f("axisTitle");
  const tickBase = f("tick");
  return {
    tick: resolveFont(tickBase, DEFAULTS.tickFont),
    // Per-axis tick fonts, exactly like the per-axis title fonts below: the axis's own
    // `tickFont` overrides the shared one field-by-field, so a category axis can carry
    // larger names than the value axis carries numbers.
    xTick: resolveFont(mergeFontSpec(tickBase, plot.xAxis?.tickFont), DEFAULTS.tickFont),
    yTick: resolveFont(mergeFontSpec(tickBase, plot.yAxis?.tickFont), DEFAULTS.tickFont),
    y2Tick: resolveFont(mergeFontSpec(tickBase, plot.y2Axis?.tickFont), DEFAULTS.tickFont),
    y3Tick: resolveFont(mergeFontSpec(tickBase, plot.y3Axis?.tickFont), DEFAULTS.tickFont),
    axisTitle: resolveFont(axisBase, DEFAULTS.titleFont),
    // Per-axis title fonts: the axis's own `titleFont` overrides the shared axis-title font field-by-field (so every
    // axis can differ independently). One rule for the drawing and the Axis tab's boxes: `axisTitleFontSpec`.
    xAxisTitle: resolveFont(axisTitleFontSpec(plot, "x"), DEFAULTS.titleFont),
    yAxisTitle: resolveFont(axisTitleFontSpec(plot, "y"), DEFAULTS.titleFont),
    // Y2/Y3: written only when the axis has a title font of its own; otherwise absent, and every reader uses the
    // main value axis title font.
    ...(plot.y2Axis?.titleFont ? { y2AxisTitle: resolveFont(axisTitleFontSpec(plot, "y2"), DEFAULTS.titleFont) } : {}),
    ...(plot.y3Axis?.titleFont ? { y3AxisTitle: resolveFont(axisTitleFontSpec(plot, "y3"), DEFAULTS.titleFont) } : {}),
    legend: resolveFont(f("legend"), DEFAULTS.legendFont),
    title: resolveFont(f("title"), DEFAULTS.headingFont, 600),
    subtitle: resolveFont(f("subtitle"), DEFAULTS.subtitleFont),
    sliceLabel: resolveFont(f("sliceLabel"), DEFAULTS.legendFont, 500),
    // The lollipop and the paired dot letter their value labels bold by design. The 700 is the
    // resolved font's default weight here, not a constant in the renderer, so the "Bold" box in
    // the value-label font lightens them, and a graph that never set a weight keeps bold labels.
    valueLabel: resolveFont(f("valueLabel"), DEFAULTS.tickFont, plot.kind === "lollipop" || plot.kind === "paireddot" ? 700 : 600),
  };
}

/**
 * Field-by-field override of a base font by an axis-specific one: each set field
 * of `over` wins, the rest inherit `base` (so `{ size: 22 }` enlarges only the
 * size, keeping the shared family/weight). `??` preserves explicit `false`.
 */
/**
 * The title font an axis draws with, before defaults: the axis's own `titleFont` over the chart-wide axis-title font,
 * field by field. The second and third value axes (Y2 — the top X2 of a horizontal chart — and Y3) sit over the main
 * Y title font first, so a graph that never gave them a font of their own draws their titles in
 * the main Y title font. Used by the builder and by the Axis tab's font boxes, so both agree.
 */
export function axisTitleFontSpec(plot: Pick<Plot, "fonts" | "xAxis" | "yAxis" | "y2Axis" | "y3Axis">, axis: "x" | "y" | "y2" | "y3"): FontSpec | undefined {
  const shared = plot.fonts?.axisTitle;
  if (axis === "x") return mergeFontSpec(shared, plot.xAxis?.titleFont);
  const mainY = mergeFontSpec(shared, plot.yAxis?.titleFont);
  if (axis === "y") return mainY;
  return mergeFontSpec(mainY, (axis === "y2" ? plot.y2Axis : plot.y3Axis)?.titleFont);
}

export function mergeFontSpec(base: FontSpec | undefined, over: FontSpec | undefined): FontSpec | undefined {
  if (!over) return base;
  if (!base) return over;
  return {
    family: over.family ?? base.family,
    size: over.size ?? base.size,
    bold: over.bold ?? base.bold,
    italic: over.italic ?? base.italic,
    color: over.color ?? base.color,
  };
}

/** Coerce a cell to a plottable number; null/blank is missing, not 0. */
function toNumber(cell: CellValue | undefined): number {
  if (cell === null || cell === undefined) return NaN;
  if (typeof cell === "number") return cell;
  const trimmed = cell.trim();
  return trimmed === "" ? NaN : Number(trimmed);
}

/** True when a dataset is entered as pre-computed summary values (any error column):
 *  SD/SEM(+N), %CV, a single ± error value, explicit lower/upper limits, a range
 *  (min/max), an IQR (q1/q3), a geometric SD factor, or a 95% CI half-width. */
function isSummaryDataset(ds: Dataset): boolean {
  return (
    ds.sd !== undefined ||
    ds.sem !== undefined ||
    ds.cv !== undefined ||
    ds.errLow !== undefined ||
    ds.errHigh !== undefined ||
    ds.min !== undefined ||
    ds.max !== undefined ||
    ds.q1 !== undefined ||
    ds.q3 !== undefined ||
    ds.geoSd !== undefined ||
    ds.ci !== undefined
  );
}

/** User-facing names for the error-bar types (scene warnings). */
const ERR_LABEL: Record<string, string> = {
  sd: "Mean ± SD",
  sem: "Mean ± SEM",
  ci95: "Mean ± 95% CI",
  range: "Mean + range",
  geoSd: "geometric SD",
  iqr: "Median + IQR",
  asymmetric: "the entered limits",
};

/** Default error-bar type for a dataset: asymmetric-entry → the stored limits, a
 *  spread-carrying dataset → SD, a plain single-value series → none. A summary dataset
 *  that can't produce SD (e.g. SEM entered without N) would draw a blank under the "sd"
 *  default, so it falls back to the statistic it can draw — SD stays the default
 *  everywhere it is drawable, so no saved graph that already shows error bars changes. */
function defaultErrorType(ds: Dataset, hasSpread: boolean): ErrorBarType {
  if (!hasSpread) return "none";
  if (ds.errLow !== undefined || ds.errHigh !== undefined) return "asymmetric";
  if (isSummaryDataset(ds) && !drawableErrorTypes(ds).includes("sd")) return naturalErrorType(ds);
  return "sd";
}

/**
 * The effective error-bar type to draw and warn on, given the saved choice. The as-entered
 * formats (± value / lower–upper limits / pre-computed 95% CI) draw their interval exactly as
 * entered for any interval type, so a saved type they can't name — e.g. an "sd" saved on a
 * limits entry, which the type menu does not offer there — is repaired to the entry's natural
 * type. The drawn geometry is identical (`asymmetricErrorPoint` ignores the type name); this only
 * corrects the label and stops a false "no error bars drawn" warning while the interval is in
 * fact drawn. Everything else is returned unchanged: raw replicates, `none`, a
 * drawable choice, or a derived summary that genuinely can't compute the type (that one still
 * draws nothing and is warned about) — so this never changes whether anything is drawn.
 */
function resolveErrorType(ds: Dataset, type: ErrorBarType): ErrorBarType {
  if (type === "none") return type;
  const asEntered = ds.ci !== undefined || ds.errLow !== undefined || ds.errHigh !== undefined;
  if (asEntered && !drawableErrorTypes(ds).includes(type)) return naturalErrorType(ds);
  return type;
}

/**
 * A warning rather than a silent blank: a summary-entered dataset can only draw the intervals its
 * stored columns determine. When the chosen `type` isn't one of them, push a scene warning
 * that says why — an empty error bar reads as "no error", a different claim. No-op for raw
 * replicates, `type: "none"`, or a drawable choice.
 */
function warnUndrawableError(ds: Dataset, type: ErrorBarType, summaryMode: boolean, warnings: string[]): void {
  if (!summaryMode || type === "none") return;
  const drawable = drawableErrorTypes(ds);
  if (drawable.includes(type)) return;
  const alt = drawable.map((t) => ERR_LABEL[t] ?? t);
  warnings.push(
    `“${ds.name}” was entered as pre-computed summary values, so “${ERR_LABEL[type] ?? type}” can’t be computed from it` +
      `${alt.length ? ` (it can draw: ${alt.join(", ")})` : ""}. No error bars drawn — add an N column, or enter raw replicates.`,
  );
}

/**
 * The plotted point (centre + error reach) for a summary-entered dataset at one row,
 * honouring its data-entry format. The pre-computed centre+spread formats (range, IQR,
 * geometric, plus the SD/SEM ones) build the same `ReplicateSummary` the raw-replicate
 * path fills and draw through the same `errorPoint` — no parallel maths — with the lead
 * cell as the centre (mean, or the median for IQR, or the geometric mean for geo-SD).
 * The absolute-endpoint formats (limits / ± value / 95% CI half-width) reuse
 * `asymmetricErrorPoint`. Formats that can't derive the requested `type` (e.g. 95% CI
 * without N) return no error reach (never a wrong bar).
 */
function summaryPointForRow(ds: Dataset, row: Row, type: ErrorBarType): ErrorPoint {
  const num = (id: string | undefined): number => (id ? toNumber(row.cells[id]) : NaN);
  const center = num(ds.replicates[0]);
  // "None" = the marker at the entered centre, no reach — uniform across every format
  // (errorPoint's own centre-picking is keyed to the interval type, which is absent here).
  if (type === "none") return { center, low: center, high: center, hasError: false, n: NaN };
  const blank: ReplicateSummary = { n: NaN, mean: NaN, sd: NaN, sem: NaN, min: NaN, max: NaN, geoMean: NaN, geoSdFactor: NaN, median: NaN, q1: NaN, q3: NaN };
  // Pre-computed range / IQR / geometric → the canonical errorPoint spine.
  if (ds.q1 !== undefined || ds.q3 !== undefined) return errorPoint({ ...blank, median: center, q1: num(ds.q1), q3: num(ds.q3) }, type, ERROR_CONF);
  if (ds.min !== undefined || ds.max !== undefined) return errorPoint({ ...blank, mean: center, min: num(ds.min), max: num(ds.max) }, type, ERROR_CONF);
  if (ds.geoSd !== undefined) return errorPoint({ ...blank, geoMean: center, geoSdFactor: num(ds.geoSd) }, type, ERROR_CONF);
  // Pre-computed 95% CI half-width: symmetric about the mean, drawn as entered.
  if (ds.ci !== undefined) {
    const c = num(ds.ci);
    return asymmetricErrorPoint(center, center - c, center + c, type);
  }
  if (ds.errLow !== undefined || ds.errHigh !== undefined) {
    const both = ds.errLow !== undefined && ds.errHigh !== undefined;
    const hi = num(ds.errHigh);
    const lo = num(ds.errLow);
    // Explicit limits are absolute endpoints; a single ± value is a symmetric offset.
    const low = both ? lo : center - hi;
    const high = both ? hi : center + hi;
    return asymmetricErrorPoint(center, low, high, type);
  }
  if (ds.cv !== undefined) {
    const cv = num(ds.cv);
    const sd = Number.isFinite(cv) ? (Math.abs(center) * cv) / 100 : NaN;
    return summaryErrorPoint(center, sd, num(ds.n), false, type, ERROR_CONF);
  }
  const error = num(ds.sem ?? ds.sd);
  return summaryErrorPoint(center, error, num(ds.n), ds.sem !== undefined, type, ERROR_CONF);
}

function estimateWidth(text: string, fontPx: number): number {
  return text.length * fontPx * 0.6;
}

/** SVG dash-array for a line dash pattern (scaled by line width), or null for solid. */
function dashArray(dash: LineDash, width: number): string | null {
  const w = Math.max(1, width);
  const n = (x: number) => (x * w).toFixed(1);
  if (dash === "dashed") return `${n(6)},${n(4)}`;
  if (dash === "longdash") return `${n(11)},${n(5)}`;
  if (dash === "dotted") return `${n(1)},${n(3)}`;
  if (dash === "dashdot") return `${n(6)},${n(3)},${n(1)},${n(3)}`;
  return null;
}

/** d3 curve factory for a connect mode (cardinal uses the tension/smoothness param). */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function curveFor(connect: ConnectMode, tension: number): any {
  switch (connect) {
    case "step":
      return curveStep;
    case "stepBefore":
      return curveStepBefore;
    case "stepAfter":
      return curveStepAfter;
    case "smooth":
      return curveMonotoneX;
    case "cardinal":
      return curveCardinal.tension(tension);
    case "catmullRom":
      return curveCatmullRom;
    case "basis":
      return curveBasis;
    case "natural":
      return curveNatural;
    default:
      return curveLinear;
  }
}

/**
 * De-conflict network node labels, in place.
 *
 * A force layout puts nodes wherever the physics lands them, so labels hang off neighbouring
 * nodes and land on each other — worse as the font grows, since the label box grows but the
 * layout does not. Neither shrinking (the labels are names, not numbers) nor moving far (the label
 * must stay attached to its node) is available, so the remaining option is to draw fewer.
 *
 * That is also the standard convention rather than a compromise: published network figures label a
 * fraction of their nodes: the unlabelled ones are texture, the
 * labelled ones are the argument. So keep labels by degree, most-connected first: the hubs are the
 * argument. A dropped label keeps its text in `suppressedLabel`, never losing the node's identity.
 *
 * A label is also flipped to the node's other side when that side is free — cheaper than
 * dropping it, and it is what a person would do by hand.
 */
function deconflictNodeLabels(
  nodes: NetworkNode[],
  edges: readonly NetworkEdge[],
  legendBox: LabelRect | null,
  fontPx: number,
  measure: (text: string, fontPx: number) => number,
  canvas: { w: number; h: number; top?: number | undefined },
  /** More boxes a name must stay off - the value colour bar, which a node name could otherwise be drawn across. */
  extraObstacles: readonly LabelRect[] = [],
): void {
  /**
   * The placement rule, on a network. Every node, every edge (sampled along its curve) and the
   * legend is an obstacle, and the label may go anywhere around its node. Checking only two
   * candidate spots (right or left of the node) against other labels alone would let a name sit
   * squarely on an edge or on another node's dot, and would drop the name without ever looking
   * above or below.
   *
   * Note: dropping is kept as the last resort, unlike the ordination's labels. A hairball has more
   * names than places, and `suppressedLabel` is this codebase's contract for "the identity is
   * not lost, the drawing just cannot carry it" — the same one axis ticks use. A name is dropped
   * only when no spot around it is clear.
   */
  const obstacles: LabelRect[] = [];
  for (const n of nodes) obstacles.push(discObstacle(n.cx, n.cy, n.r + 1));
  for (const e of edges) {
    obstacles.push(...(e.cx != null && e.cy != null
      ? curveObstacles(e.x1, e.y1, e.cx, e.cy, e.x2, e.y2, Math.max(3, e.width * 2))
      : segmentObstacles(e.x1, e.y1, e.x2, e.y2, Math.max(3, e.width * 2))));
  }
  if (legendBox) obstacles.push(legendBox);
  obstacles.push(...extraObstacles);

  // Hubs first; ties broken by id so the result never depends on input order.
  const order = nodes
    .filter((n) => n.label !== "")
    .sort((a, b) => b.degree - a.degree || (a.id < b.id ? -1 : 1));
  if (order.length === 0) return;

  const placed = placeLabelsClear(
    order.map((n) => ({ id: n.id, text: n.label, anchorX: n.cx, anchorY: n.cy })),
    {
      fontPx,
      measure,
      // The whole canvas, inset a little: a network has no axes to keep off, only the edge
      // of the paper.
      // …below the heading, when the builder says where that ends: otherwise enlarged node labels
      // can sit on the title.
      bounds: { x1: 2, y1: canvas.top ?? 2, x2: canvas.w - 2, y2: canvas.h - 2 },
      obstacles,
    },
  );
  for (const n of order) {
    const p = placed.get(n.id);
    if (!p || p.crowded) {
      n.suppressedLabel = n.label;
      n.label = "";
      continue;
    }
    n.labelAnchor = p.anchor;
    n.labelDx = p.x - n.cx;
    n.labelDy = p.y - n.cy;
    const lead = leaderFor(n.cx, n.cy, placedBox(p, n.label, fontPx, measure), n.r, n.r + fontPx * 2);
    if (lead) n.labelLeader = lead;
  }
}

/**
 * Nudge colliding text annotations apart vertically, in place.
 *
 * For labels tied to a direction rather than a slot — PCA loading vectors are the case here —
 * dropping is the wrong answer: each one names a variable, and losing it loses the reading of
 * that axis. But they can move a little, because the eye tracks the arrow to its label, so a
 * label a line or two off its tip is still unambiguous. Two near-parallel loadings put their
 * tips in nearly the same place, which is the only situation that collides.
 *
 * Walks in the given order (callers pass most-important first), keeping each label where it is
 * if free, else trying successively larger offsets alternating up/down. Gives up rather than
 * shoving a label off the canvas — a label left overlapping is recoverable by the user; one
 * pushed out of the figure is not. Returns the ids it could not place.
 */
/**
 * The legend's box when it sits inside the plot, so a label can be kept off it.
 *
 * The scene carries the legend's placement and entries, not its rectangle — the renderer
 * derives that. This mirrors the renderer's own geometry closely enough to steer a label
 * away; an outside ("right") legend needs none, because it is beyond the plot rect a label is
 * already confined to.
 */
function insideLegendBox(
  layout: LegendLayout,
  entries: readonly LegendEntry[],
  plotX: number,
  plotY: number,
  plotW: number,
  plotH: number,
  fontPx: number,
  measure: (t: string, px: number) => number,
): LabelRect | null {
  if (entries.length === 0 || layout.position === "none" || layout.position === "right" || layout.position === "top") return null;
  const line = fontPx * 1.45;
  const swatch = layout.swatchWidth ?? fontPx * 1.6;
  const inset = layout.inset ?? 8;
  const w = swatch + Math.max(0, ...entries.map((e) => measure(e.label, fontPx))) + 10;
  const h = layout.orientation === "horizontal" ? line + 6 : entries.length * line + 6;
  const left = layout.position.endsWith("left");
  const top = layout.position.startsWith("top");
  const x1 = left ? plotX + inset : plotX + plotW - inset - w;
  const y1 = top ? plotY + inset : plotY + plotH - inset - h;
  return { x1, y1, x2: x1 + w, y2: y1 + h };
}

/**
 * The box an outside-right legend draws, as the renderer places it: at the plot's right edge + its gap (+ any `outsidePad`),
 * 8 px below the plot's top, one row per entry (taller for a label broken onto lines), `legendBoxWidth` wide. Generous by a
 * few px on every side - it is an obstacle for labels, and a label that grazes the legend has still clashed.
 */
function outsideRightLegendBox(layout: LegendLayout, entries: readonly LegendEntry[], plotRight: number, plotY: number, fontPx: number): LabelRect | null {
  if (entries.length === 0 || layout.position !== "right") return null;
  const sym = Math.max(4, ...entries.map((e) => e.symbolSize ?? 4)) * (layout.symbolScale ?? 1);
  const rowH = Math.max(fontPx + 6, 2 * sym + 6, entries.some((e) => e.swatch === "bar") ? 1.25 * fontPx * (layout.symbolScale ?? 1) + 6 : 0);
  const rows = layout.orientation === "horizontal" ? rowH : entries.reduce((h, e) => h + rowH + Math.max(0, (e.lines?.length ?? 1) - 1) * fontPx * 1.2, 0);
  const x1 = plotRight + (layout.gap ?? 12) + (layout.outsidePad ?? 0) - 4;
  const w = layout.orientation === "horizontal" ? entries.reduce((s, e) => s + (layout.swatchWidth ?? 18) + legendLabelText(e).length * fontPx * 0.6 + 14, 0) : legendBoxWidth(layout, entries.map(legendLabelText), fontPx);
  return { x1, y1: plotY, x2: x1 + w + 8, y2: plotY + 8 + rows + 2 * (layout.padding ?? 6) + 4 };
}

function nudgeApartVertically(
  labels: { id: string; text: string; x: number; y: number; anchor: "start" | "middle" | "end" }[],
  fontPx: number,
  measure: (text: string, fontPx: number) => number,
  canvas: { w: number; h: number },
): { moved: Map<string, number>; unplaced: string[] } {
  const SAFETY = 1.15; // `measure` under-reads non-Latin text — see deconflictNodeLabels
  const step = TEXT_BAND * fontPx;
  const half = step * 0.5;
  const moved = new Map<string, number>();
  const unplaced: string[] = [];
  const placed: { x1: number; y1: number; x2: number; y2: number }[] = [];
  const boxAt = (l: (typeof labels)[number], y: number) => {
    const w = measure(l.text, fontPx) * SAFETY;
    const x1 = l.anchor === "end" ? l.x - w : l.anchor === "middle" ? l.x - w / 2 : l.x;
    return { x1, y1: y - half, x2: x1 + w, y2: y + half };
  };
  const free = (b: { x1: number; y1: number; x2: number; y2: number }): boolean =>
    b.y1 >= 0 && b.y2 <= canvas.h && !placed.some((p) => b.x1 < p.x2 + 2 && p.x1 < b.x2 + 2 && b.y1 < p.y2 + 2 && p.y1 < b.y2 + 2);

  for (const l of labels) {
    let done = false;
    // 0, −1, +1, −2, +2 … : prefer staying put, then the smallest move that works.
    for (let k = 0; k <= 4 && !done; k++) {
      for (const dir of k === 0 ? [0] : [-1, 1]) {
        const dy = dir * k * step;
        const b = boxAt(l, l.y + dy);
        if (!free(b)) continue;
        placed.push(b);
        if (dy !== 0) moved.set(l.id, dy);
        done = true;
        break;
      }
    }
    if (!done) unplaced.push(l.id);
  }
  return { moved, unplaced };
}

/**
 * The vertical counterpart of `deOverlapX`, for stacked category labels — and it resolves the
 * collision differently on purpose.
 *
 * Horizontally, labels collide because one is long, so shrinking the font barely helps and
 * dropping the odd label is the right trade. Vertically they collide only because the rows are
 * close together, which the font size fixes directly — and dropping is much worse here, since
 * on a category axis every row is a named entity and a blanked label leaves the reader no
 * handle on that row at all. So: shrink to fit first, and only thin the labels if even the
 * minimum readable size cannot fit (hundreds of rows in a short figure).
 *
 * Returns the font to draw with and, when thinning was unavoidable, which row indices keep a
 * label. `keep` is `null` when every row keeps one.
 */
function fitStackedLabels(
  count: number,
  bandHeight: number,
  requested: number,
): { font: number; keep: Set<number> | null } {
  const MIN_READABLE = 7; // below this the label is decoration, not information
  const GAP = 2; // breathing room between adjacent labels
  if (count <= 1 || !Number.isFinite(bandHeight) || bandHeight <= 0) return { font: requested, keep: null };
  const fits = (f: number): boolean => TEXT_BAND * f + GAP <= bandHeight;
  if (fits(requested)) return { font: requested, keep: null };
  const shrunk = Math.floor((bandHeight - GAP) / TEXT_BAND);
  if (shrunk >= MIN_READABLE) return { font: shrunk, keep: null };
  // Too tight even at the floor: keep every k-th label, the densest that still clears.
  const step = Math.max(2, Math.ceil((TEXT_BAND * MIN_READABLE + GAP) / bandHeight));
  const keep = new Set<number>();
  for (let i = 0; i < count; i += step) keep.add(i);
  return { font: MIN_READABLE, keep };
}

/**
 * Blank the labels of major ticks that would collide horizontally with the last
 * kept label (the tick mark stays). Walks left→right; measures each label and
 * drops it if its left edge would overlap the previous kept label's right edge
 * (+pad), so no two labels clash on dense/long-label axes.
 */
function deOverlapX(
  ticks: AxisTick[],
  measure: (text: string, fontPx: number) => number,
  fontPx: number,
): AxisTick[] {
  const PAD = 6;
  let lastRight = -Infinity;
  return ticks.map((t) => {
    if (t.minor || !t.label) return t;
    const half = measure(t.label, fontPx) / 2;
    // Collides → drop the label, but keep the text so the tick's identity survives:
    // category grouping runs off it, and a purely visual de-overlap must not be able
    // to silently merge two groups into one.
    if (t.pos - half < lastRight + PAD) return { ...t, label: "", suppressedLabel: t.label };
    lastRight = t.pos + half;
    return t;
  });
}

/**
 * Shorten `text` until it fits `maxPx`, ending in an ellipsis. Returns "" when even a single
 * character plus the ellipsis will not fit — a label that cannot be read is worse than absent,
 * because it lands on its neighbour.
 *
 * Used wherever a label is placed in a slot whose size the data controls (a treemap cell, a
 * paired-dot section band): those are the places where a label would otherwise overflow onto
 * whatever is next to it.
 */
function truncateToWidth(
  text: string,
  fontPx: number,
  maxPx: number,
  measure: (t: string, px: number) => number,
): string {
  if (text === "" || maxPx <= 0) return "";
  if (measure(text, fontPx) <= maxPx) return text;
  const ELLIPSIS = "…";
  for (let n = text.length - 1; n >= 1; n--) {
    const candidate = text.slice(0, n).trimEnd() + ELLIPSIS;
    if (measure(candidate, fontPx) <= maxPx) return candidate;
  }
  return "";
}

function extent(values: readonly number[]): [number, number] {
  let min = Infinity;
  let max = -Infinity;
  for (const v of values) {
    if (v < min) min = v;
    if (v > max) max = v;
  }
  if (!Number.isFinite(min) || !Number.isFinite(max)) return [0, 1];
  return [min, max];
}

/** A log scale (any base) — drops non-positive data and snaps to powers. */
function isLog(type: ScaleType): boolean {
  return type === "log10" || type === "log2" || type === "ln";
}

/** The tick-format subset of an AxisSpec (number format, decimals, prefix/suffix). */
function tickFormat(spec: AxisSpec | undefined): TickFormat {
  return {
    format: spec?.format,
    decimals: spec?.decimals,
    prefix: spec?.prefix,
    suffix: spec?.suffix,
    thousands: spec?.thousands,
    decimalSep: spec?.decimalSep,
  };
}

/**
 * Apply an AxisSpec's manual range over an auto-fit domain: pin either end the
 * user set (a manual range); the other end keeps auto-fit. Returns the
 * domain ascending (low ≤ high) — direction is handled separately by `reversed`.
 */
function applyRange(spec: AxisSpec | undefined, auto: [number, number]): [number, number] {
  let lo = spec?.min ?? auto[0];
  let hi = spec?.max ?? auto[1];
  if (lo > hi) [lo, hi] = [hi, lo];
  return [lo, hi];
}

/**
 * Apply a pan/zoom window on top of an axis spec's manual range.
 *
 * Every builder that supports scroll-to-zoom needs the same four values, and getting any of them
 * wrong fails silently:
 *  - `data`   the domain to draw: the window when there is one, else the spec's own range.
 *  - `manual` pass as `exact` to `buildScale` — a window (like a manual range) must be drawn
 *             exactly, with no nice()/pad, or the edges drift from where the gesture put them.
 *  - `home`   the rest state ignoring the window. `PlotScene.auto` must be this. The renderer
 *             soft-locks back to it and compares against it to know the chart is zoomed, so an
 *             `auto` that echoes the current domain silently disables both.
 *  - `homeManual` the `exact` flag for rebuilding `home` — the spec's manual range only, since
 *             the window is precisely what home leaves out.
 */
function windowed(
  spec: AxisSpec,
  autoDom: [number, number],
  win: [number, number] | undefined,
): { data: [number, number]; home: [number, number]; manual: boolean; homeManual: boolean } {
  const homeManual = spec.min != null || spec.max != null;
  const home = applyRange(spec, autoDom);
  return { data: win ?? home, home, manual: homeManual || win != null, homeManual };
}

/**
 * One builder-made reference line, resolved: its own override, then the all-lines setting,
 * then the line's built-in look.
 *
 * The Bland-Altman limits, the PCA origin cross and the ROC diagonal are all editable the
 * way an axis is (thickness, colour, dash type), each on its own, so the bias line and its
 * limits can differ.
 *
 * Note: the dash is converted after the width is resolved, so the pattern scales with the line.
 * Converting first would leave a hairline dash on a 6px line.
 *
 * `fallback.dash` is the line's built-in dash, and it comes in two shapes on purpose: a
 * `LineDash` for lines whose pattern tracks the width (converted with `dashArray(…, width)`),
 * and a raw SVG string for lines with a fixed pattern like `"5 3"` (so an untouched chart
 * stays byte-identical — a Bland-Altman bias is solid while its limits are dashed, and that
 * distinction is the point).
 */
const LINE_DASHES = new Set<string>(["solid", "dashed", "dotted", "dashdot", "longdash"]);

function resolveRefLine(
  plot: Plot,
  id: string,
  fallback: { color?: string | undefined; dash: LineDash | string | null; width: number },
): { color: string | null; dash: string | null; width: number; show: boolean } {
  const all = plot.refLine;
  const own = plot.refLineStyles?.[id];
  const width = own?.width ?? all?.width ?? fallback.width;
  // An explicit choice wins even when it is "solid" — which means no dash, not "unset".
  const dashChoice = own?.dash ?? all?.dash;
  const fb = fallback.dash;
  const dash =
    dashChoice ? dashArray(dashChoice, width)
    : typeof fb === "string" && LINE_DASHES.has(fb) ? dashArray(fb as LineDash, width)
    : (fb as string | null);
  return {
    color: own?.color ?? all?.color ?? fallback.color ?? null,
    dash,
    width,
    show: all?.show !== false && !plot.refLineHidden?.[id],
  };
}

/** Append a volcano's dashed threshold guides (±fold-change verticals + a p-value
 *  horizontal) as ordinary reference-line annotations. Each carries its own style, so the
 *  fold-change pair and the significance line can differ. */
function volcanoGuides(plot: Plot): Plot {
  const fc = plot.volcano?.fcThreshold ?? 1;
  const p = plot.volcano?.pThreshold ?? 1.301;
  // Note: these three go through the model annotation path, whose `dash` is a `LineDash` and not
  // an SVG string — so resolve the choice here rather than reusing `resolveRefLine`, which
  // returns the converted pattern for the lines that are pushed straight to the scene.
  const styleOf = (id: string): { color: string; width: number; dash: LineDash } | null => {
    const own = plot.refLineStyles?.[id];
    const all = plot.refLine;
    if (all?.show === false || plot.refLineHidden?.[id]) return null;
    return {
      color: own?.color ?? all?.color ?? "#9aa0aa",
      width: own?.width ?? all?.width ?? 1,
      dash: own?.dash ?? all?.dash ?? "dashed",
    };
  };
  const extra: NonNullable<Plot["annotations"]> = [];
  const fcPos = styleOf("vc-fc-pos");
  if (fcPos) extra.push({ id: "vc-fc-pos", kind: "vline", value: fc, ...fcPos });
  const fcNeg = styleOf("vc-fc-neg");
  if (fcNeg) extra.push({ id: "vc-fc-neg", kind: "vline", value: -fc, ...fcNeg });
  const pLine = styleOf("vc-p");
  if (pLine) extra.push({ id: "vc-p", kind: "hline", value: p, ...pLine });
  if (extra.length === 0) return plot;
  return { ...plot, annotations: [...(plot.annotations ?? []), ...extra] };
}

/** A Manhattan plot's two significance guides, as labelled horizontal reference lines at −log10
 *  of the genome-wide (5×10⁻⁸) and suggestive (1×10⁻⁵) P-value thresholds. Each is a registered
 *  reference line (`manhattan-genomewide` / `manhattan-suggestive`) so it clicks to the
 *  reference-line panel and carries its own colour/dash. */
function manhattanThresholdLines(plot: Plot): NonNullable<Plot["annotations"]> {
  const styleOf = (id: string, fallbackColor: string): { color: string; width: number; dash: LineDash } | null => {
    const own = plot.refLineStyles?.[id];
    const all = plot.refLine;
    if (all?.show === false || plot.refLineHidden?.[id]) return null;
    return {
      color: own?.color ?? all?.color ?? fallbackColor,
      width: own?.width ?? all?.width ?? 1,
      dash: own?.dash ?? all?.dash ?? "dashed",
    };
  };
  const out: NonNullable<Plot["annotations"]> = [];
  const gwP = plot.manhattan?.genomeWideP ?? 5e-8;
  if ((plot.manhattan?.genomeWideLine ?? true) && gwP > 0 && gwP <= 1) {
    const s = styleOf("manhattan-genomewide", "#e03131");
    if (s) out.push({ id: "manhattan-genomewide", kind: "hline", value: -Math.log10(gwP),
      label: plot.refLineLabels?.["manhattan-genomewide"] ?? "Genome-wide",
      // Locked: the line sits at a computed threshold, so dragging it would assert something
      // the data does not say, and the builder would put it back on the
      // next rebuild anyway. Without this the enclosing group would advertise `cursor: move` and
      // then refuse every drag.
      // The caption is a different matter and still moves: `buildAnnotations` gives every
      // registered reference line a `labelOffset`, so the readout can be pulled off the points
      // it describes, exactly as with Bland-Altman's bias line.
      locked: true, ...s });
  }
  const sugP = plot.manhattan?.suggestiveP ?? 1e-5;
  if ((plot.manhattan?.suggestiveLine ?? true) && sugP > 0 && sugP <= 1) {
    const s = styleOf("manhattan-suggestive", "#f08c00");
    if (s) out.push({ id: "manhattan-suggestive", kind: "hline", value: -Math.log10(sugP),
      label: plot.refLineLabels?.["manhattan-suggestive"] ?? "Suggestive",
      // Locked: the line sits at a computed threshold, so dragging it would assert something
      // the data does not say, and the builder would put it back on the
      // next rebuild anyway. Without this the enclosing group would advertise `cursor: move` and
      // then refuse every drag.
      // The caption is a different matter and still moves: `buildAnnotations` gives every
      // registered reference line a `labelOffset`, so the readout can be pulled off the points
      // it describes, exactly as with Bland-Altman's bias line.
      locked: true, ...s });
  }
  return out;
}

/** Map a data value to a pixel on a resolved axis, using its domain/range/type (linear or log).
 *  On an axis with cuts every visible stretch carries its own pixel span (`ax.segments`), so a value in a
 *  stretch maps through that stretch. Null means the axis has no pixel for the value: a categorical (band)
 *  axis, a value inside a cut, or an out-of-domain value on a log axis — the caller skips it and says why.
 *  Values in a visible stretch of a cut axis do map, so custom ticks and shaded bands still draw when a cut
 *  exists.
 */
function axisPixel(ax: AxisScene, value: number): number | null {
  if (ax.band) return null;
  if (ax.segments?.length) {
    for (const s of ax.segments) {
      const lo = Math.min(s.from, s.to);
      const hi = Math.max(s.from, s.to);
      if (value < lo || value > hi) continue;
      if (ax.type !== "linear") {
        if (value <= 0 || lo <= 0 || hi <= 0 || lo === hi) return null;
        return s.p0 + ((Math.log(value) - Math.log(lo)) / (Math.log(hi) - Math.log(lo))) * (s.p1 - s.p0);
      }
      return lo === hi ? s.p0 : s.p0 + ((value - lo) / (hi - lo)) * (s.p1 - s.p0);
    }
    return null; // the value sits inside a cut: the axis has no pixel for it
  }
  // A cut axis whose builder does not pass its stretches has no pixel for any value: refuse.
  if (ax.breakMarks && ax.breakMarks.length) return null;
  const [d0, d1] = ax.domain;
  const [p0, p1] = ax.range;
  if (ax.type !== "linear") {
    if (value <= 0 || d0 <= 0 || d1 <= 0 || d0 === d1) return null;
    const t = (Math.log(value) - Math.log(d0)) / (Math.log(d1) - Math.log(d0));
    return p0 + t * (p1 - p0);
  }
  if (d1 === d0) return null;
  return p0 + ((value - d0) / (d1 - d0)) * (p1 - p0);
}

/** True when the axis has cuts and `value` falls inside one of them (within the domain, but on no visible
 *  stretch) — the one reason `axisPixel` refuses a finite value on a linear cut axis, and the one case that
 *  must be said out loud rather than dropped. */
function insideCut(ax: AxisScene, value: number): boolean {
  if (!ax.segments?.length) return false;
  const d0 = Math.min(ax.domain[0], ax.domain[1]);
  const d1 = Math.max(ax.domain[0], ax.domain[1]);
  if (value < d0 || value > d1) return false;
  return !ax.segments.some((s) => value >= Math.min(s.from, s.to) && value <= Math.max(s.from, s.to));
}

/** How far a tick label reaches along its axis as drawn, from the placement the renderer uses. */
function labelExtentAlongAxis(
  ax: AxisScene,
  tick: AxisTick,
  font: number,
  orient: "x" | "y",
  measure: (text: string, fontPx: number) => number,
): { lo: number; hi: number } {
  const w = measure(tick.label, font) * 1.1; // measure under-reads
  const rot = ax.tickRotation ?? 0;
  const box = orient === "x"
    ? xTickLabelPlacement(tick.pos, 0, font, 0, rot, w).box
    : yTickLabelPlacement(tick.pos, 0, font, 0, rot, w).box;
  return orient === "x" ? { lo: box.x1, hi: box.x2 } : { lo: box.y1, hi: box.y2 };
}

/**
 * How close two numbers up an axis may sit, in font sizes, before they count as on each other. The browser boxes
 * a line of digits in Arial (the default preset's font on Windows) at 1.10-1.12 of its font size (22 px at 20,
 * 33.5 px at 30, measured): Arial's own ascent plus descent, tighter than the 1.35 em band (`TEXT_BAND`) the
 * margins reserve for any font. Boxes that merely
 * touch still read cleanly (the digits' ink is ~0.72 of the font), and the UpSet card's 20 px numbers at a 22 px
 * pitch are exactly that, so they must not thin. 1.07 = an overlap of a pixel or two and no less.
 */
const NUMBER_LINE = 1.07;

/**
 * Numbers along an axis never sit on each other. The tick ladder is chosen from the data (`TARGET_TICKS`), never
 * from the axis's length in pixels, so a short axis or a large tick font packs the same ladder tighter until
 * the numbers stack: a short Y axis in large type, or close values such as "0.4" and "0.6" running together
 * along a forest plot's X. `deOverlapX` covers the bottom axis of the builders that call it; this function
 * covers vertical axes as well.
 *
 * Keep every k-th number - the smallest k that clears - so the ones left still step evenly, and keep zero
 * among them when the axis has one. Only the text goes (remembered in `suppressedLabel`, as the other
 * crowded-axis rules do): the tick mark and its gridline stay.
 *
 * Numeric axes with level labels only. Category names are fitted, never thinned (`fitStackedLabels`); turned
 * labels have their own rules. A tick the user added is never thinned.
 *
 * Returns how many labels it blanked.
 */
export function thinCrowdedNumbers(
  ax: AxisScene,
  font: number,
  orient: "x" | "y",
  measure: (text: string, fontPx: number) => number,
  keepAlways: ReadonlySet<AxisTick> = new Set(),
): number {
  if (ax.hidden || ax.band || ax.tickRotation) return 0;
  const shown = ax.ticks
    .filter((t) => !t.minor && t.label !== "" && !keepAlways.has(t))
    .sort((a, b) => a.value - b.value);
  if (shown.length < 3) return 0;
  // Up a vertical axis the numbers are judged by the line of digits as drawn (the browser boxes 30 px Arial numbers at
  // 33-34 px), not by the roomier band the margins reserve: judged by that band, 30 px numbers a clear 38 px
  // apart would be thinned too. Along a horizontal axis it is the label's width, as `labelExtentAlongAxis` reads it.
  const half = (NUMBER_LINE * font) / 2;
  const ext = shown.map((t) => (orient === "y" ? { lo: t.pos - half, hi: t.pos + half } : labelExtentAlongAxis(ax, t, font, orient, measure)));
  const clear = (idx: number[]): boolean => {
    const e = idx.map((i) => ext[i]!).sort((a, b) => a.lo - b.lo);
    for (let i = 1; i < e.length; i++) if (e[i]!.lo < e[i - 1]!.hi) return false;
    return true;
  };
  const all = shown.map((_, i) => i);
  if (clear(all)) return 0;
  const zero = shown.findIndex((t) => Math.abs(t.value) < 1e-12);
  for (let k = 2; k <= shown.length; k++) {
    const phase = zero >= 0 ? zero % k : 0;
    const kept = all.filter((i) => i % k === phase);
    if (!clear(kept)) continue;
    const keep = new Set(kept);
    let blanked = 0;
    shown.forEach((t, i) => {
      if (keep.has(i)) return;
      t.suppressedLabel = t.suppressedLabel ?? t.label;
      t.label = "";
      blanked++;
    });
    return blanked;
  }
  return 0;
}

/**
 * A custom tick's label wins over the automatic label it would sit on: the user asked for that text, at that
 * value. Custom ticks are pushed in after the automatic labels have been spaced out (`deOverlapX`), so without
 * this step nothing compares the two and both are drawn on top of each other ("week 20" over "20").
 *
 * The automatic tick keeps its mark and its gridline; only its text goes, remembered in `suppressedLabel` as
 * the crowded-axis rules do - dropping the whole tick would take away a gridline nobody asked to lose.
 */
function hideLabelsUnderCustomTicks(
  ax: AxisScene,
  custom: ReadonlySet<AxisTick>,
  font: number,
  orient: "x" | "y",
  measure: (text: string, fontPx: number) => number,
): void {
  const shownCustom = ax.ticks.filter((t) => custom.has(t) && !t.minor && t.label !== "");
  if (shownCustom.length === 0) return;
  const PAD = 2;
  const taken = shownCustom.map((t) => labelExtentAlongAxis(ax, t, font, orient, measure));
  for (const t of ax.ticks) {
    if (t.minor || t.label === "" || custom.has(t)) continue;
    const e = labelExtentAlongAxis(ax, t, font, orient, measure);
    if (taken.some((b) => e.lo < b.hi + PAD && b.lo < e.hi + PAD)) {
      t.suppressedLabel = t.suppressedLabel ?? t.label;
      t.label = "";
    }
  }
}

/**
 * Resolve category groups on one banded axis into the four redundant channels.
 *
 * Membership is matched by category label (never by row index), so a filtered or
 * reordered chart cannot silently mis-assign a group — an unmatched category just
 * renders ungrouped. Runs are contiguous in visual order, so a group whose
 * categories are scattered across the axis correctly yields several blocks rather
 * than one block swallowing the categories in between.
 *
 * Returns the extra space (px) the group names need outside the plot; the caller
 * grows the scene box by it. Everything else is drawn inside the existing rect,
 * so the other three channels never disturb layout.
 */
function resolveCategoryGroups(
  scene: PlotScene,
  ax: AxisScene,
  cfg: CategoryGroupSpec,
  table: DataTable,
  orient: "x" | "y",
  palette: readonly string[],
  measure: (text: string, fontPx: number) => number,
  out: CategoryGroupScene[],
): number {
  if (!ax.band || ax.hidden) return 0;
  // Label → group name. An explicit map wins; otherwise read the group column
  // against the X (category-label) column, which is what the tick labels show.
  let groupOf: (label: string) => string | undefined;
  // Declared order = the order the groups appear in the data. Palette colours are
  // assigned from this, not from left-to-right on the axis, so sorting the chart
  // cannot silently recolour every group — the colour means the group, and a group's
  // identity does not change because its bars moved.
  const declared: string[] = [];
  const note = (g: string): void => {
    if (!declared.includes(g)) declared.push(g);
  };
  if (cfg.map && Object.keys(cfg.map).length) {
    const m = cfg.map;
    for (const g of Object.values(m)) if (g && g.trim() !== "") note(g.trim());
    groupOf = (label) => {
      const g = m[label];
      return g && g.trim() !== "" ? g.trim() : undefined;
    };
  } else if (cfg.column) {
    const xCol = xColumn(table);
    const byLabel = new Map<string, string>();
    for (const row of table.rows) {
      const label = String(row.cells[xCol?.id ?? ""] ?? "").trim();
      const g = String(row.cells[cfg.column] ?? "").trim();
      if (label !== "" && g !== "" && !byLabel.has(label)) {
        byLabel.set(label, g);
        note(g);
      }
    }
    groupOf = (label) => byLabel.get(label);
  } else {
    return 0;
  }

  // Ticks in visual order along the axis (pos ascending: left→right / top→bottom).
  // `suppressedLabel` keeps de-overlapped categories in the run detection — dropping
  // them would let a crowded axis silently merge two groups into one wrong block.
  // The same list the Inspector's By-hand editor shows one box per name for (`categoryTicks`).
  const nameOfTick = tickCategoryName;
  const ticks = categoryTicks(ax);
  if (ticks.length === 0) return 0;

  const showLabelColor = cfg.labelColor ?? true;
  const showSeparators = cfg.separators ?? true;
  const showNames = cfg.names ?? true;
  const showTint = cfg.tint ?? false;

  // Group colour: explicit, else the palette by declared (data) order. A group not
  // in the declared list falls to the end rather than colliding on index 0.
  if (!ticks.some((t) => groupOf(nameOfTick(t)))) return 0;
  const colorOf = (g: string): string => {
    const i = declared.indexOf(g);
    return cfg.colors?.[g] ?? seriesColor(i < 0 ? declared.length : i, palette);
  };

  const { x: plotX, y: plotY, width: plotW, height: plotH } = scene.plot;
  const lo0 = orient === "x" ? plotX : plotY;
  const hi0 = orient === "x" ? plotX + plotW : plotY + plotH;
  const posOf = (i: number): number => ticks[i]!.pos;
  // Boundary between two adjacent categories = the midpoint of their tick positions,
  // which is band-width agnostic (works for any builder's band layout).
  const edgeBefore = (i: number): number => (i === 0 ? lo0 : (posOf(i - 1) + posOf(i)) / 2);
  const edgeAfter = (i: number): number => (i === ticks.length - 1 ? hi0 : (posOf(i) + posOf(i + 1)) / 2);

  let anyName = false;
  const named: CategoryGroupScene[] = [];
  // A vertical category axis writes its names down the right edge, past everything already in the
  // right margin (see `outsideRightReserve`).
  const rightNameX = plotX + plotW + 12 + outsideRightReserve(scene);
  let i = 0;
  let firstRun = true;
  while (i < ticks.length) {
    const g = groupOf(nameOfTick(ticks[i]!));
    if (!g) {
      i += 1;
      continue;
    }
    let j = i;
    while (j + 1 < ticks.length && groupOf(nameOfTick(ticks[j + 1]!)) === g) j += 1;
    const color = colorOf(g);
    const lo = edgeBefore(i);
    const hi = edgeAfter(j);
    if (showLabelColor) for (let k = i; k <= j; k++) ticks[k]!.color = color;

    const item: CategoryGroupScene = { label: g, color, axis: orient };
    if (showTint) {
      const opacity = cfg.tintOpacity ?? 0.06;
      item.tint = orient === "x"
        ? { x: lo, y: plotY, w: hi - lo, h: plotH, opacity }
        : { x: plotX, y: lo, w: plotW, h: hi - lo, opacity };
    }
    // No separator before the first run — there is nothing on the other side of it.
    if (showSeparators && !firstRun) {
      const dash = cfg.separatorDash ?? "4 3";
      item.separator = orient === "x"
        ? { x1: lo, y1: plotY, x2: lo, y2: plotY + plotH, dash }
        : { x1: plotX, y1: lo, x2: plotX + plotW, y2: lo, dash };
    }
    if (showNames) {
      anyName = true;
      const off = cfg.nameOffsets?.[g];
      const mid = (lo + hi) / 2;
      const nameFont = scene.fonts.legend.size;
      // Placed outside the plot, past anything already reserved out there: a
      // vertical category axis writes down the right edge (clear of an outside
      // legend), a horizontal one writes beneath its tick labels. The X-axis
      // title is anchored to the tick labels (`titleAnchorOf`), which steps it
      // below this row; the height returned here is what makes room for both.
      const flatNameY = plotY + plotH + (ax.tickLen ?? 5) + (scene.axisGaps?.xTick ?? 6) + scene.fonts.tick.size + nameFont + 4;
      const anchor = orient === "y"
        ? { x: rightNameX, y: mid, angle: 90 }
        : {
            x: mid,
            // Rotated labels hang down by their length: the names go below the lowest one, not across them.
            y: ax.tickRotation ? Math.max(flatNameY, xTickLabelsExtent(scene, ax, measure).bottom + nameFont + 4) : flatNameY,
            angle: 0,
          };
      item.name = {
        ...anchor,
        ...(off?.dx != null ? { dx: off.dx } : {}),
        ...(off?.dy != null ? { dy: off.dy } : {}),
      };
    }
    out.push(item);
    if (item.name) named.push(item);
    firstRun = false;
    i = j + 1;
  }

  // A name longer than its group reaches into the next group's name (e.g. two long group names down the right
  // edge of a short plot). Slide neighbours apart by the least that clears them
  // (`spreadAlong`); the name is the user's text, so it is never shortened or dropped. A name the user has
  // dragged is theirs and stays out of it. When the names cannot fit the figure at all, say so.
  const free = named.filter((g) => g.name!.dx == null && g.name!.dy == null);
  if (free.length > 1) {
    const nameFont = scene.fonts.legend.size;
    const along = (g: CategoryGroupScene): number => (orient === "y" ? g.name!.y : g.name!.x);
    const spread = spreadAlong(
      free.map((g) => ({ center: along(g), length: measure(g.label, nameFont) * 1.1 })), // measure under-reads
      2,
      (orient === "y" ? scene.height : scene.width) - 2,
      nameFont * 0.5,
    );
    if (spread) {
      free.forEach((g, k) => {
        if (orient === "y") g.name!.y = spread[k]!;
        else g.name!.x = spread[k]!;
      });
    } else {
      scene.warnings.push(`The group names are together longer than the ${orient === "y" ? "height" : "width"} of the figure, so they overlap. Shorten them, enlarge the figure, or turn the names off.`);
    }
  }

  if (!anyName) return 0;
  const band = scene.fonts.legend.size + 14;
  if (orient !== "y") return band;
  // Names down the right edge sit past the whole right-margin stack, which can reach further than
  // the fixed band alone allows. Grow the canvas far enough to keep their glyphs on it (a name
  // turned 90° extends about 0.8 of the font to the right of its anchor).
  return Math.max(band, rightNameX + scene.fonts.legend.size * 0.8 + 4 - scene.width);
}

/**
 * Width (px) already occupied to the right of the plot, so a group name written down that edge
 * clears it: whatever a builder stacks before the legend (`outsidePad` — a Y2 axis, the paired dot's
 * section labels), then an outside-right legend as the renderer draws it (`legendBoxWidth`).
 *
 * Re-estimating the legend with the builder's text measure and a fixed 18px symbol column, or
 * ignoring `outsidePad`, underestimates the drawn box, and the names would run through the legend
 * and a Y2 title (e.g. on a horizontal stacked-bars chart).
 */
function outsideRightReserve(scene: PlotScene): number {
  const L = scene.legendLayout;
  const before = L.outsidePad ?? 0;
  if (L.position !== "right" || scene.legend.length === 0) return before;
  return before + (L.gap ?? 12) + legendBoxWidth(L, scene.legend.map(legendLabelText), scene.fonts.legend.size);
}

/**
 * How far down (and right) the X tick labels reach as drawn (`xTickLabelPlacement`), and how much
 * further down that is than a row of horizontal labels (`drop`) — the only row any builder's bottom
 * margin makes room for. A horizontal label ends a descent below its baseline; a rotated one hangs
 * down by its length. The group names, the title, the outer group row and the at-risk table are all
 * placed from this.
 */
function xTickLabelsExtent(scene: PlotScene, ax: AxisScene, measure: (text: string, fontPx: number) => number): { bottom: number; right: number; drop: number } {
  const font = scene.fonts.xTick.size;
  const gap = scene.axisGaps?.xTick ?? 6;
  const axisY = scene.plot.y + scene.plot.height;
  const flat = axisY + font + gap + font * TEXT_DESCENT;
  const rot = ax.tickRotation ?? 0;
  let bottom = flat;
  let right = -Infinity;
  if (rot) {
    for (const t of ax.ticks) {
      if (t.minor || t.label === "") continue;
      const b = xTickLabelPlacement(t.pos, axisY, font, gap, rot, measure(t.label, font) * 1.1).box; // measure under-reads
      bottom = Math.max(bottom, b.y2);
      right = Math.max(right, b.x2);
    }
  }
  return { bottom, right, drop: bottom - flat };
}

/**
 * How far left the Y tick labels reach as drawn (`yTickLabelPlacement`). A horizontal label reaches its own
 * width; a turned one reaches its real outline, which for a short label slanted at −45° is further than its
 * flat width (placing by the flat width would put the Y title on a turned tick label).
 */
function yTickLabelsLeft(scene: PlotScene, ax: AxisScene, measure: (text: string, fontPx: number) => number): number {
  const font = scene.fonts.yTick.size;
  const gap = scene.axisGaps?.yTick ?? 8;
  const shown = ax.ticks.filter((t) => !t.minor && t.label !== "");
  const rot = ax.tickRotation ?? 0;
  if (!rot) return scene.plot.x - gap - (shown.length ? Math.max(...shown.map((t) => measure(t.label, font))) : 0);
  let left = scene.plot.x - gap;
  for (const t of shown) left = Math.min(left, yTickLabelPlacement(t.pos, scene.plot.x, font, gap, rot, measure(t.label, font) * 1.1).box.x1); // measure under-reads
  return left;
}

/**
 * The room the Y tick labels need left of the axis — what every builder sizes its left margin from. A flat
 * label needs its width; a turned one needs its real reach (`yTickLabelPlacement`), which for a short label is
 * more than its flat width. Sized by the flat width alone, a large font would push the Y title onto a turned
 * label against the canvas edge — the margin, not the title, would be too small.
 */
/**
 * The width a value axis's labels need beside it. `spec` is the axis the ticks came from: its rotation, and its
 * custom ticks. A label typed on a custom tick gets its room; sized from the automatic labels alone, a longer
 * custom label would run off the canvas and be blanked with a warning. Every builder sizes its value axes through here, so one change reaches all of them;
 * `custom-tick-room.test.ts` holds each gallery card to it.
 */
function yTickLabelsWidth(ticks: readonly AxisTick[], fontPx: number, measure: (text: string, fontPx: number) => number, spec: AxisSpec | undefined): number {
  const rotation = spec?.tickRotation;
  const majors = ticks.filter((t) => !t.minor);
  const labels = [...majors.map((t) => t.label), ...customTickLabels(spec, majors)];
  const flat = Math.max(0, ...labels.map((l) => measure(l, fontPx)));
  // Never less than the flat width. A number turned 90° needs only its line height, and taking that alone
  // would shrink the margin: the plot would widen, and on a 1:1 chart such as the ordination biplot the Y range
  // would change so a top tick could disappear. Turning a label is not a reason for the axis to show different values.
  return Math.max(flat, turnedYLabelsReach(labels, fontPx, measure, rotation));
}

/**
 * The labels an axis's custom ticks will show, for sizing: the typed label, else the value formatted as the axis
 * formats it. Only ticks that can land on the axis count - one beyond the automatic ticks by more than a step is
 * dropped by `perAxis` and must not reserve room for text that is never drawn.
 */
function customTickLabels(spec: AxisSpec | undefined, majors: readonly AxisTick[]): string[] {
  const extra = spec?.extraTicks;
  if (!extra?.length) return [];
  const values = majors.map((t) => t.value).filter(Number.isFinite);
  const lo = values.length ? Math.min(...values) : -Infinity;
  const hi = values.length ? Math.max(...values) : Infinity;
  const step = values.length > 1 ? (hi - lo) / (values.length - 1) : Infinity;
  const fmt = tickFormat(spec);
  return extra
    .filter((t) => Number.isFinite(t.value) && t.value >= lo - step && t.value <= hi + step)
    .map((t) => (t.label && t.label.length ? t.label : makeTickLabel(t.value, "linear", fmt)));
}

/**
 * How far turned Y labels reach left of the label gap (`yTickLabelPlacement`); 0 for flat labels. The category
 * builders size their left margin from the names' flat width and take the larger of the two, so a flat chart
 * keeps exactly its margin and a turned name (e.g. "P07" at 45° on a horizontal waterfall) does not reach
 * past it into the title.
 */
function turnedYLabelsReach(labels: readonly string[], fontPx: number, measure: (text: string, fontPx: number) => number, rotation: number | undefined): number {
  if (!rotation) return 0;
  return Math.max(0, ...labels.filter((l) => l !== "").map((l) => -yTickLabelPlacement(0, 0, fontPx, 0, rotation, measure(l, fontPx) * 1.1).box.x1)); // measure under-reads
}

/**
 * Turned category names longer than the room between them are drawn level, and the scene says why (a
 * warning). At 90° a name needs its whole length along the axis, so many long names on a short axis would
 * pile on each other and the end ones would run off the figure. Names are data, so none is hidden; a
 * number axis is left alone (numbers are short).
 */
function levelCrowdedYNames(scene: PlotScene, ax: AxisScene, measure: (text: string, fontPx: number) => number): void {
  const rot = ax.tickRotation ?? 0;
  if (!rot || !ax.band) return;
  const PAD = 2;
  const font = scene.fonts.yTick.size;
  const gap = scene.axisGaps?.yTick ?? 8;
  const slantCos = Math.abs(Math.cos((rot * Math.PI) / 180));
  // A zero-length label turned 90° is exactly as wide as a line of text is thick.
  const line = yTickLabelPlacement(0, 0, font, 0, 90, 0).box;
  const thickness = line.x2 - line.x1;
  const shown = ax.ticks.filter((t) => !t.minor && t.label !== "").sort((p, q) => p.pos - q.pos);
  const boxOf = (t: AxisTick) => yTickLabelPlacement(t.pos, scene.plot.x, font, gap, rot, measure(t.label, font) * 1.1).box; // measure under-reads
  let crowded = shown.some((t) => { const b = boxOf(t); return b.y1 < 0 || b.y2 > scene.height; });
  for (let i = 1; i < shown.length && !crowded; i++) {
    const p = boxOf(shown[i - 1]!);
    const q = boxOf(shown[i]!);
    const apart = q.y1 >= p.y2 + PAD || p.y1 >= q.y2 + PAD || (shown[i]!.pos - shown[i - 1]!.pos) * slantCos >= thickness + PAD;
    if (!apart) crowded = true;
  }
  if (!crowded) return;
  delete ax.tickRotation;
  scene.warnings.push(
    `The ${ax.title ? `"${ax.title}" ` : ""}names are drawn level: turned ${rot}° they are longer than the room between them. `
    + "Pick a smaller angle, or make the figure taller.",
  );
}

/**
 * Re-space the X labels for their rotation. Builders hide labels that would collide horizontally
 * (`deOverlapX`) — the wrong test for turned text: a label turned 90° needs its line height along the
 * axis, not its length. Without this, a name hidden on a crowded axis would stay hidden however far it
 * was turned.
 *
 * A label hidden for room (blank, its text kept in `suppressedLabel`) is brought back, and hidden again
 * only if its drawn outline (`xTickLabelPlacement`) would touch the last label kept before it: clear when
 * the two outlines do not share any horizontal span, or when the gap across the slant holds a line of
 * text. A shortened name keeps its full name in `suppressedLabel` either way — groups match on it.
 */
function respaceRotatedXLabels(scene: PlotScene, ax: AxisScene, measure: (text: string, fontPx: number) => number): void {
  const rot = ax.tickRotation ?? 0;
  if (!rot) return;
  const PAD = 2;
  const font = scene.fonts.xTick.size;
  const gap = scene.axisGaps?.xTick ?? 6;
  const axisY = scene.plot.y + scene.plot.height;
  const slant = Math.abs(Math.sin((rot * Math.PI) / 180));
  // A zero-length label turned 90° is exactly as wide as a line of text is thick.
  const line = xTickLabelPlacement(0, 0, font, 0, 90, 0).box;
  const thickness = line.x2 - line.x1;
  let last: { pos: number; right: number } | null = null;
  for (const t of ax.ticks.filter((k) => !k.minor).sort((a, b) => a.pos - b.pos)) {
    const text = t.label !== "" ? t.label : t.suppressedLabel;
    if (!text) continue;
    const box = xTickLabelPlacement(t.pos, axisY, font, gap, rot, measure(text, font) * 1.1).box; // measure under-reads
    const clear = !last || box.x1 >= last.right + PAD || (t.pos - last.pos) * slant >= thickness + PAD;
    if (clear) {
      if (t.label === "") {
        t.label = text;
        delete t.suppressedLabel;
      }
      last = { pos: t.pos, right: box.x2 };
    } else if (t.label !== "") {
      t.suppressedLabel = t.suppressedLabel ?? t.label;
      t.label = "";
    }
  }
}

/**
 * Resolve the axis-engine extras — custom ticks + gridlines, shaded bands,
 * tick-label rotation, and category groups — into the scene at the single choke
 * point, so every chart kind gets them without threading through each builder.
 * Extras land on the axis the user sees (the value spec follows dataAxisOf for a
 * transposed chart).
 */
/**
 * No category name is hidden while a smaller size fits (for example after Match Fonts enlarges a bar chart's names).
 * A builder blanks a flat X name that would touch its neighbour (`deOverlapX`, its text kept in
 * `suppressedLabel`). Before any is left blank, the axis's names are tried smaller - never below `floor` px - and when
 * every name fits they are all shown at that size (the scene's X tick font, which the renderer draws them in). The graph
 * keeps its size. Only when even `floor` px collides are the names left blanked. Says so when that size was set.
 */
function fitCrowdedXNames(scene: PlotScene, ax: AxisScene, measure: (text: string, fontPx: number) => number, floor: number, asked: boolean): void {
  const blanked = ax.ticks.filter((t) => !t.minor && t.label === "" && !!t.suppressedLabel);
  if (blanked.length === 0) return;
  const size0 = scene.fonts.xTick.size;
  if (size0 <= floor) return;
  const names = ax.ticks
    .filter((t) => !t.minor && (t.label !== "" || !!t.suppressedLabel))
    .map((t) => ({ t, text: t.label !== "" ? t.label : t.suppressedLabel! }))
    .sort((a, b) => a.t.pos - b.t.pos);
  const PAD = 6; // deOverlapX's gap
  const fits = (px: number): boolean => {
    let last = -Infinity;
    for (const { t, text } of names) {
      const half = measure(text, px) / 2;
      if (t.pos - half < last + PAD) return false;
      last = t.pos + half;
    }
    return true;
  };
  if (!fits(floor)) return;
  let lo = floor;
  let hi = size0;
  for (let i = 0; i < 14; i++) { const mid = (lo + hi) / 2; if (fits(mid)) lo = mid; else hi = mid; }
  const px = Math.floor(lo * 10) / 10;
  for (const t of blanked) { t.label = t.suppressedLabel!; delete t.suppressedLabel; }
  scene.fonts = { ...scene.fonts, xTick: { ...scene.fonts.xTick, size: px } };
  if (asked) scene.warnings.push(`Category names are drawn at ${px}px, not the ${size0}px asked for: at full size they collided. A wider figure will honour it.`);
}

function resolveAxisExtras(
  scene: PlotScene,
  plot: Plot,
  table: DataTable,
  palette: readonly string[],
  measure: (text: string, fontPx: number) => number,
  room: { given?: { left: number; top: number; above?: boolean | undefined } | undefined; topLegendBand?: number | undefined; minTextPx?: number | undefined } = {},
): { left: number; top: number; above: boolean } {
  const trans = isTransposedPlot(plot);
  const specX = trans ? plot.yAxis : plot.xAxis;
  const specY = trans ? plot.xAxis : plot.yAxis;
  /**
   * Anchor an axis title to its own tick labels rather than to the canvas edge.
   *
   * Mirrors exactly where the renderer draws those labels, walks out past their real extent
   * (including rotation, which turns a long label into a tall one), then leaves `titleGap`.
   * The result is a constant clearance at every font size — the title can neither collide with
   * the numbers nor drift out into whitespace, as two independent formulas would allow.
   */
  const titleAnchorOf = (ax: AxisScene, orient: "x" | "y", titleSize: number, titleGap: number): number | undefined => {
    if (ax.hidden || !ax.title) return undefined;
    // Note: each extent reads the tick font of its own axis: a category axis may carry larger names than the
    // value axis carries numbers, and the title has to clear whichever it sits beside.
    if (orient === "x") {
      // Below the labels as drawn (`xTickLabelsExtent`): a descent under a horizontal label, the whole
      // length of a rotated one.
      let y = xTickLabelsExtent(scene, ax, measure).bottom + titleGap + titleSize * TEXT_ASCENT; // gap measured to the glyph top
      // Category-group names are written in their own row beneath these labels. The title goes
      // below that row, not on it: anchored to the labels alone, one group spanning the whole axis
      // would draw its name straight across the title.
      const nameRow = groups.filter((g) => g.axis === "x" && g.name).map((g) => g.name!.y);
      if (nameRow.length) {
        y = Math.max(y, Math.max(...nameRow) + scene.fonts.legend.size * TEXT_DESCENT + titleGap + titleSize * TEXT_ASCENT);
      }
      // Clamp to the canvas rather than growing it: the figure size is the user's, and silently
      // enlarging it changes what they export. (Growing would also break the invariant that
      // per-side padding insets the plot rect without resizing the figure.) The `textBand` term
      // in each builder's marginBottom is what reserves the room, so this clamp should not bind;
      // if it ever does, the adjustment belongs in that builder's margin, not here. `growBottom` is the
      // group-name row's own height, added to the canvas once both axes resolve — so it counts.
      return Math.min(y, scene.height + growBottom - titleSize * TEXT_DESCENT - 2);
    }
    // Left of the Y labels as drawn (`yTickLabelsLeft`): the widest flat label, or a turned label's real reach.
    const labelsLeft = yTickLabelsLeft(scene, ax, measure);
    // A −90° title's glyphs sit to the left of its anchor, so step past them by the descent.
    const x = labelsLeft - titleGap - titleSize * TEXT_DESCENT;
    // Never off the left edge. Unlike the bottom, the canvas cannot grow leftward without
    // moving the already-positioned plot rect, so this one clamps; the margin term above
    // (textBand) is what keeps the clamp from ever binding in practice.
    return Math.max(x, titleSize * TEXT_ASCENT);
  };

  const bands: NonNullable<PlotScene["axisBands"]> = [];
  /** The ticks the user added (`extraTicks`), by identity: their labels win, and a label of theirs that cannot
   *  be drawn is reported in a warning rather than dropped silently. */
  const customTicks = new Set<AxisTick>();
  const bars: NonNullable<PlotScene["scaleBars"]> = [];
  const groups: CategoryGroupScene[] = [];
  // Extra space the group names need outside the plot, per direction. Applied to
  // the scene box after both axes resolve (the plot rect itself never moves).
  let growRight = 0;
  let growBottom = 0;
  const perAxis = (ax: AxisScene, spec: AxisSpec | undefined, orient: "x" | "y"): void => {
    if (!spec) return;
    // Corner scale bar — a short segment of `length` data units, sized from the axis
    // scale (computed before any hide-clear, which doesn't touch domain/range).
    const sb = spec.scaleBar;
    if (sb && sb.length > 0 && ax.breakMarks?.length) {
      // A cut compresses the axis, so `length` data units are no fixed number of pixels: a bar drawn
      // from this scale would claim a length it does not measure. Refused with a warning, never silently.
      scene.warnings.push(`The scale bar is not drawn while the ${orient === "x" ? "X" : "Y"} axis has a cut: the cut compresses the axis, so the bar would not measure the length it states. Remove the cut, or the scale bar.`);
    } else if (sb && sb.length > 0) {
      const v0 = Math.min(ax.domain[0], ax.domain[1]);
      const p0 = axisPixel(ax, v0);
      const p1 = axisPixel(ax, v0 + sb.length);
      if (p0 != null && p1 != null) {
        const lenPx = Math.abs(p1 - p0);
        const color = (typeof ax.lineColor === "string" ? ax.lineColor : null) ?? "#333333";
        const label = sb.label ?? `${sb.length}${spec.suffix ?? ""}`;
        const inset = 8;
        if (orient === "x") {
          const y = scene.plot.y + scene.plot.height - inset;
          const x = scene.plot.x + inset;
          bars.push({ x1: x, y1: y, x2: x + lenPx, y2: y, label, labelX: x + lenPx / 2, labelY: y + 13, color, vertical: false });
        } else {
          const x = scene.plot.x + inset;
          const yb = scene.plot.y + scene.plot.height - inset;
          bars.push({ x1: x, y1: yb, x2: x, y2: yb - lenPx, label, labelX: x + 6, labelY: yb - lenPx / 2, color, vertical: true });
        }
      }
    }
    // Hidden axis — drop its ticks (and thus gridlines) + title; keep the data mapping.
    if (spec.hidden) {
      ax.hidden = true;
      ax.ticks = [];
      ax.title = "";
      return;
    }
    if (spec.tickRotation) ax.tickRotation = spec.tickRotation;
    const fmt = tickFormat(spec);
    const lo = Math.min(ax.range[0], ax.range[1]) - 0.5;
    const hi = Math.max(ax.range[0], ax.range[1]) + 0.5;
    const added: AxisTick[] = [];
    for (const t of spec.extraTicks ?? []) {
      if (!Number.isFinite(t.value)) continue;
      const pos = axisPixel(ax, t.value);
      if (pos == null || pos < lo || pos > hi) {
        // Never a silent drop: a tick the cut swallowed has nowhere to go, and the scene says so.
        if (pos == null && insideCut(ax, t.value)) {
          scene.warnings.push(`The tick at ${t.value} is inside the ${orient === "x" ? "X" : "Y"} axis's cut, so there is nowhere to draw it. Move the tick, or move the cut.`);
        }
        continue;
      }
      const tick: AxisTick = { value: t.value, pos, label: t.label && t.label.length ? t.label : makeTickLabel(t.value, ax.type, fmt), minor: false };
      ax.ticks.push(tick);
      added.push(tick);
      customTicks.add(tick);
    }
    if (added.length) {
      // The tick font of this axis (a second axis carries its own), so the comparison is the drawn one.
      const tickFont = ax === scene.y2 ? scene.fonts.y2Tick : ax === scene.y3 ? scene.fonts.y3Tick
        : orient === "x" ? scene.fonts.xTick : scene.fonts.yTick;
      hideLabelsUnderCustomTicks(ax, new Set(added), tickFont.size, orient, measure);
    }
    for (const b of spec.bands ?? []) {
      const color = b.color ?? "#3b82f6";
      const opacity = b.opacity ?? 0.12;
      const lo0 = Math.min(b.from, b.to);
      const hi0 = Math.max(b.from, b.to);
      // A band that spans a cut is drawn in pieces, one per visible stretch: bridging the gap would
      // paint over the cut and imply the data it removed (the ridgeline splits its fills at cuts for the same
      // reason). A band inside one stretch is one piece.
      const spans: Array<[number, number]> = [];
      if (ax.segments?.length) {
        for (const s of ax.segments) {
          const from = Math.max(lo0, Math.min(s.from, s.to));
          const to = Math.min(hi0, Math.max(s.from, s.to));
          if (to > from) spans.push([from, to]);
        }
        if (spans.length === 0) {
          const d0 = Math.min(ax.domain[0], ax.domain[1]);
          const d1 = Math.max(ax.domain[0], ax.domain[1]);
          // Inside the domain but on no visible stretch = the cut swallowed it, and a warning says so.
          // Entirely outside the domain is a different matter and stays silent.
          if (hi0 >= d0 && lo0 <= d1) {
            scene.warnings.push(`The band from ${b.from} to ${b.to} is inside the ${orient === "x" ? "X" : "Y"} axis's cut, so there is nothing to shade. Move the band, or move the cut.`);
          }
          continue;
        }
      } else {
        spans.push([lo0, hi0]);
      }
      spans.forEach(([from, to], i) => {
        const p0 = axisPixel(ax, from);
        const p1 = axisPixel(ax, to);
        if (p0 == null || p1 == null) return;
        const a = Math.min(p0, p1);
        const z = Math.max(p0, p1);
        // The name belongs to the band, not to each piece: it is written once, on the first.
        const label = i === 0 ? b.label : undefined;
        bands.push(
          orient === "x"
            ? { x: a, y: scene.plot.y, w: z - a, h: scene.plot.height, color, opacity, label, labelX: a + 3, labelY: scene.plot.y + 12 }
            : { x: scene.plot.x, y: a, w: scene.plot.width, h: z - a, color, opacity, label, labelX: scene.plot.x + 4, labelY: a + 12 },
        );
      });
    }
    if (ax === scene.x && ax.tickRotation) respaceRotatedXLabels(scene, ax, measure);
    // Not a histogram: its X names are number ranges ("175–200"), and showing every other one - the thinning numbers get -
    // reads better than all of them at 8 px.
    if (ax === scene.x && !ax.tickRotation && ax.band && plot.kind !== "histogram") fitCrowdedXNames(scene, ax, measure, room.minTextPx ?? 8, specX?.tickFont?.size !== undefined);
    if (ax === scene.y && ax.tickRotation) levelCrowdedYNames(scene, ax, measure);
    if (spec.categoryGroups) {
      const grow = resolveCategoryGroups(scene, ax, spec.categoryGroups, table, orient, palette, measure, groups);
      if (orient === "y") growRight = Math.max(growRight, grow);
      else growBottom = Math.max(growBottom, grow);
    }
  };
  perAxis(scene.x, specX, "x");
  perAxis(scene.y, specY, "y");
  // A top second axis (a horizontal bar chart) runs left to right: its bands, scale bar and extra
  // ticks are laid out along X like the bottom axis's, not down the plot like a right axis's.
  if (scene.y2 && plot.y2Axis) perAxis(scene.y2, plot.y2Axis, scene.y2.side === "top" ? "x" : "y");
  if (scene.y3 && plot.y3Axis) perAxis(scene.y3, plot.y3Axis, "y");
  // Numbers that would sit on each other are thinned here - after the user's own ticks are in, and before the
  // titles and the corner rule measure the labels that are left (`thinCrowdedNumbers`).
  thinCrowdedNumbers(scene.x, scene.fonts.xTick.size, "x", measure, customTicks);
  thinCrowdedNumbers(scene.y, scene.fonts.yTick.size, "y", measure, customTicks);
  if (scene.y2) thinCrowdedNumbers(scene.y2, scene.fonts.y2Tick.size, scene.y2.side === "top" ? "x" : "y", measure, customTicks);
  if (scene.y3) thinCrowdedNumbers(scene.y3, scene.fonts.y3Tick.size, "y", measure, customTicks);
  // Rotated X labels hang down by their length, and no builder's bottom margin makes room for that —
  // each is sized for one row of horizontal labels. Grow the canvas by the difference, away from the
  // plot, as the group-name row does, and move down what a builder placed beneath the labels.
  // Without this a −45° / −90° label would run off the bottom of the figure and under its own axis title.
  let labelDrop = 0;
  let labelGrowRight = 0;
  if (!scene.x.hidden && scene.x.tickRotation) {
    const ext = xTickLabelsExtent(scene, scene.x, measure);
    labelDrop = ext.drop;
    labelGrowRight = Math.max(0, ext.right + 2 - scene.width);
    growBottom += labelDrop;
    growRight = Math.max(growRight, labelGrowRight);
    for (const g of scene.barGroupLabels ?? []) g.y += labelDrop;
    if (scene.atRisk) scene.atRisk.top += labelDrop;
  }
  // A turned label on the top second axis leans left or right of its tick; at the last tick it can pass the figure's
  // right edge. Grow the canvas away from the plot, as for the bottom axis.
  if (scene.y2?.side === "top" && !scene.y2.hidden && scene.y2.tickRotation) {
    const font = scene.fonts.y2Tick.size;
    const rot = scene.y2.tickRotation;
    let right = -Infinity;
    for (const t of scene.y2.ticks) {
      if (t.minor || t.label === "") continue;
      right = Math.max(right, xTickLabelPlacement(t.pos, scene.plot.y, font, scene.axisGaps?.xTick ?? 6, rot, measure(t.label, font) * 1.1, "top").box.x2); // measure under-reads
    }
    growRight = Math.max(growRight, right + 2 - scene.width);
  }
  // Title placement runs after the per-axis pass, so it sees the final tick set (custom ticks
  // added, de-overlapped labels blanked, a hidden axis cleared).
  const xTitleAt = titleAnchorOf(scene.x, "x", scene.fonts.xAxisTitle.size, specX?.titleGap ?? 6);
  // A matrix heatmap draws its row names in its own layer, not as Y ticks, so the tick-label anchor
  // cannot see them; its builder places the row title in the strip it reserved (see buildHeatmapScene).
  const heatmapMatrix = scene.kind === "heatmap" && !!scene.heatmap && !scene.heatmap.pointMode;
  const yTitleAt = heatmapMatrix ? undefined : titleAnchorOf(scene.y, "y", scene.fonts.yAxisTitle.size, specY?.titleGap ?? 6);
  if (xTitleAt != null) scene.x.titlePos = xTitleAt;
  if (yTitleAt != null) scene.y.titlePos = yTitleAt;
  /**
   * A title runs its length along its axis — down the figure for the rotated Y title. Centring
   * a long one on the plot rect therefore pushes its ends past the canvas. Slide it to stay
   * on canvas; only shrink when it cannot fit at any position, and never below legibility.
   */
  const fitTitle = (ax: AxisScene, size: number, extent: number, plotStart: number, plotLen: number): void => {
    if (ax.hidden || !ax.title) return;
    // `measure` under-reads by a few per cent, so a title that only just passes the fit check
    // can still be drawn clipped at both ends. Treat titles as slightly wider than measured — over-shrinking by a couple of
    // points is invisible; a clipped title is not.
    const MEASURE_SLACK = 1.1;
    const len = measure(ax.title, size) * MEASURE_SLACK;
    const avail = extent - 4;
    if (len > avail) {
      // Too long at any position → shrink to fit, with a floor so it stays readable.
      ax.titleFont = Math.max(8, Math.floor((size * avail) / len));
    }
    const finalLen = Math.min(len, avail);
    const centre = plotStart + plotLen / 2;
    const clamped = Math.min(Math.max(centre, finalLen / 2 + 2), extent - finalLen / 2 - 2);
    if (Math.abs(clamped - centre) > 0.5) ax.titleCenter = clamped;
  };
  fitTitle(scene.x, scene.fonts.xAxisTitle.size, scene.width, scene.plot.x, scene.plot.width);
  // A title turned another way is fitted by Title direction below; this measures one running down the figure.
  if (!requestedTurn(specY, "left")) fitTitle(scene.y, scene.fonts.yAxisTitle.size, scene.height, scene.plot.y, scene.plot.height);
  /**
   * Title direction (Axis tab), for every chart kind: a vertical
   * axis's title written level (or at any angle, with magnets at every 45°), beside the axis or level above it.
   * A default turned title is untouched (`requestedTurn` is undefined), so an unchanged graph builds the
   * same scene. Left: the room comes from a second build with the shortfall added to the plot's left / top
   * padding, which every builder reads (the outside-top legend's pattern). Right: the builders size the band
   * (`rightTitleBand`), so whatever is stacked further right has already moved; the title is only placed here.
   * Never a silent drop: a title that cannot be turned as asked stays turned and says why.
   */
  const titleRoom = { left: 0, top: 0, above: false };
  const tickHalf = scene.fonts.yTick.size * 0.6;
  const turnTitle = (ax: AxisScene | undefined, spec: AxisSpec | undefined, side: TitleSide, size: number, name: string): void => {
    if (!ax || ax.hidden || !ax.title) return;
    const want = requestedTurn(spec, side);
    if (!want) return;
    if (want.aboveRefused) {
      scene.warnings.push(`The ${name} title goes above its axis only when it is level (0°). At ${want.angle}° it stays beside the axis.`);
    }
    const gap = spec?.titleGap ?? 6;
    // The edge of the space beside the axis, read off where the builder put the turned title: a left title's
    // glyphs end `descent` right of its anchor, a right title's begin 0.3 em left of it.
    const edge = side === "left"
      ? (ax.titlePos != null ? ax.titlePos + titleDescent(scene.fonts.yAxisTitle.size) : undefined)
      : (ax.titleX != null ? ax.titleX - size * 0.3 : undefined);
    if (edge == null) {
      scene.warnings.push(`This chart places its own ${name} title, so Title direction is not applied to it.`);
      return;
    }
    let placed: TurnedTitlePlacement | undefined;
    // A level left title that found no room beside the axis goes above it (the third build, below).
    const movedAbove = side === "left" && want.angle === 0 && !want.above && room.given?.above === true;
    if (movedAbove) {
      scene.warnings.push(`There is no room beside the axis for the level ${name} title, so it is written above the axis. A wider figure or a shorter title keeps it beside.`);
    }
    if (want.above || movedAbove) {
      const labelsEdge = side === "left" ? yTickLabelsLeft(scene, ax, measure) : edge - gap;
      if (room.given == null) titleRoom.top = Math.max(titleRoom.top, aboveBand(size, gap) + tickHalf);
      // The band this title was given is the last part of the plot's top padding, which every builder puts
      // straight under the heading (`headingPad(…) + pad.t`); whatever a chart draws over its plot — a heatmap's
      // column names and tree, a top second axis, an outside-top legend — sits below it, anchored to the plot.
      // So the title goes at the top of that band, never on those. (First build: a guess; it is built again.)
      const given = room.given?.top ?? 0;
      const baseline = given > 0
        ? headingPad(resolveHeading(plot), scene.fonts.title.size, scene.fonts.subtitle.size)
          + Math.max(0, (plot.plotPad?.top ?? 0) - (room.topLegendBand ?? 0) - given)
          + size * TEXT_ASCENT + 2
        : scene.plot.y - (room.topLegendBand ?? 0) - tickHalf - gap - titleDescent(size);
      placed = placeAbove(side, titleLength(ax.title, size, measure), labelsEdge, baseline, scene.width);
      if (!placed) {
        scene.warnings.push(`The ${name} title is wider than the figure, so it cannot be written above the axis. It is drawn turned.`);
        return;
      }
    } else {
      const lay = besideLayout(ax.title, want.angle, size, measure, scene.width);
      if (lay.tooWide) {
        scene.warnings.push(`The ${name} title is too long to write at ${want.angle}° beside the axis without squeezing the plot, so it is drawn turned. Shorten it, or write it level above the axis.`);
        return;
      }
      placed = placeBeside(side, want.angle, lay.lines, lay.len, size, edge, ax.titleCenter ?? scene.plot.y + scene.plot.height / 2, scene);
      if (placed.overflowLeft > 1) {
        if (room.given != null) {
          if (side === "left" && want.angle === 0) {
            // The builder could not give the room (its margins are capped): ask for a build with the title above.
            titleRoom.above = true;
            titleRoom.top = Math.max(titleRoom.top, aboveBand(size, gap) + tickHalf);
            return;
          }
          scene.warnings.push(`This chart could not make room for the ${name} title at ${want.angle}°, so it is drawn turned.`);
          return;
        }
        titleRoom.left = Math.max(titleRoom.left, placed.overflowLeft);
      }
      growRight = Math.max(growRight, placed.overflowRight);
    }
    ax.titleTurn = placed.turn;
  };
  turnTitle(scene.y, specY, "left", scene.y.titleFont ?? scene.fonts.yAxisTitle.size, "Y-axis");
  if (scene.y2 && scene.y2.side !== "top") turnTitle(scene.y2, plot.y2Axis, "right", (scene.fonts.y2AxisTitle ?? scene.fonts.yAxisTitle).size, "Y2-axis");
  if (scene.y3) turnTitle(scene.y3, plot.y3Axis, "right", (scene.fonts.y3AxisTitle ?? scene.fonts.yAxisTitle).size, "Y3-axis");
  // An axis drawn across the figure keeps its title along it. A direction saved on one (a chart flipped after
  // it was set) is said, not dropped in silence.
  const across: Array<[AxisSpec | undefined, string, boolean]> = [
    [specX, "X-axis", !!scene.x.title && !scene.x.hidden],
    [plot.y2Axis, "X2-axis", scene.y2?.side === "top" && !!scene.y2.title && !scene.y2.hidden],
  ];
  for (const [s, name, drawn] of across) {
    if (drawn && (s?.titleAngle != null || s?.titleAbove === true)) {
      scene.warnings.push(`Title direction applies to axes that run up the figure; the ${name} title runs along its axis.`);
    }
  }
  /**
   * The two axes meet at the plot's bottom-left corner, where the X axis's leftmost label and
   * the Y axis's lowest label are drawn by independent code that has never known about the
   * other. At normal font sizes they miss each other; enlarge the text and they collide.
   *
   * Drop the Y label, not the X one: it is the axis minimum, the least informative tick on the
   * scale (very often 0, and always inferable from the ones above it), whereas the X label
   * identifies a category or value with no such redundancy. Identity is preserved in
   * `suppressedLabel`, so nothing reading a tick loses the corner value.
   *
   * Note: numeric Y axes only. On a band axis the labels are category names — nothing about
   * "Group C" is inferable from the rows above it, so dropping it loses data, not redundancy
   * (on a ridgeline it would silently delete the bottom group). Crowded band labels
   * are handled by shrinking to fit instead — see `fitStackedLabels`.
   */
  if (!scene.x.hidden && !scene.y.hidden) {
    // Per-axis: the X labels are measured with the X tick font, the Y labels below with the
    // Y one. Measuring both with one size is how a larger category label slips past the
    // overlap check and lands on top of its neighbour.
    const tickFont = scene.fonts.xTick.size;
    const xAxisY = scene.plot.y + scene.plot.height;
    const xGap = scene.axisGaps?.xTick ?? 6;
    const xRot = scene.x.tickRotation ?? 0;
    // The X label's outline as drawn — a rotated label's is nothing like a horizontal one's.
    const xBoxOf = (t: AxisTick, w: number) => xTickLabelPlacement(t.pos, xAxisY, tickFont, xGap, xRot, w).box;
    const yGap = scene.axisGaps?.yTick ?? 8;
    const yRot = scene.y.tickRotation ?? 0;
    // The Y label's outline as drawn (`yTickLabelPlacement`). Note: a flat Y label is boxed with the font each rule
    // passes in (the edge rule measures with the X tick font); a turned one uses the Y tick font.
    const yBoxOf = (t: AxisTick, w: number, flatFont: number) =>
      yTickLabelPlacement(t.pos, scene.plot.x, yRot ? scene.fonts.yTick.size : flatFont, yGap, yRot, w).box;
    const xBoxes = scene.x.ticks
      .filter((t) => !t.minor && t.label !== "")
      .map((t) => xBoxOf(t, measure(t.label, tickFont) * 1.1)); // measure under-reads — see fitTitle
    // Corner rule — numeric Y only (a band label is a category name; see above).
    if (!scene.y.band) {
      // The Y labels are measured with the Y axis's own font (and its own half-band), or a
      // mismatched pair silently mis-detects the corner overlap.
      const yFont = scene.fonts.yTick.size;
      for (const t of scene.y.ticks) {
        if (t.minor || t.label === "") continue;
        const w = measure(t.label, yFont) * 1.1;
        const b = yBoxOf(t, w, yFont);
        if (xBoxes.some((o) => b.x1 < o.x2 + 2 && o.x1 < b.x2 + 2 && b.y1 < o.y2 + 2 && o.y1 < b.y2 + 2)) {
          t.suppressedLabel = t.label;
          t.label = "";
        }
      }
    }
    // The same corner on the right: a right-hand axis's lowest number meets the last X label (e.g. "Other" over
    // a Pareto's cumulative "0" at tick font 30). The same trade - the axis minimum yields.
    if (scene.y2 && scene.y2.side !== "top" && !scene.y2.hidden && !scene.y2.band) {
      const y2Font = scene.fonts.y2Tick.size;
      const y2Rot = scene.y2.tickRotation ?? 0;
      for (const t of scene.y2.ticks) {
        if (t.minor || t.label === "") continue;
        const b = yTickLabelPlacement(t.pos, scene.plot.x + scene.plot.width, y2Font, yGap, y2Rot, measure(t.label, y2Font) * 1.1, "right").box;
        // A real overlap only - no 2 px halo as on the left. At the house font the Pareto's "Other" ends 3 px short
        // of the "0", so both are drawn, and the rule for enlarged type must not take that "0" away.
        if (xBoxes.some((o) => b.x1 < o.x2 && o.x1 < b.x2 && b.y1 < o.y2 && o.y1 < b.y2)) {
          t.suppressedLabel = t.label;
          t.label = "";
        }
      }
    }
    /**
     * An end tick label is centred on its tick, so half of it hangs past the axis end — and the
     * outermost one can hang out of a margin sized for a smaller font, past the canvas edge.
     * Blank a label that cannot be drawn on the canvas: clipped text is worse
     * than absent text, since it reads as a rendering fault rather than a spacing choice, and
     * the value stays recoverable via `suppressedLabel`.
     *
     * Guarded to a minority of an axis's labels. If most of them escape, the margin itself is
     * wrong and silently emptying the axis would hide that, so the labels are left in view.
     */
    const trimEscaping = (ax: AxisScene, boxOf: (t: AxisTick, w: number) => { x1: number; x2: number; y1: number; y2: number }): void => {
      const shown = ax.ticks.filter((t) => !t.minor && t.label !== "");
      const escaping = shown.filter((t) => {
        const b = boxOf(t, measure(t.label, tickFont) * 1.1);
        // The canvas grows below / right for rotated labels once both axes resolve (end of this function).
        return b.x1 < -1 || b.x2 > scene.width + labelGrowRight + 1 || b.y1 < -1 || b.y2 > scene.height + labelDrop + 1;
      });
      if (escaping.length === 0 || escaping.length > shown.length / 2) return;
      for (const t of escaping) {
        // A label the user typed must not vanish without a warning. The margin is measured from the
        // automatic labels, before any custom tick exists, so a wider custom one cannot be drawn on the canvas;
        // reserving room for it here would narrow the plot of every saved graph that carries one. So the
        // warning says which label, and why.
        if (customTicks.has(t)) {
          scene.warnings.push(`The tick labelled "${t.label}" is wider than the room beside the axis, so it is not drawn. A shorter label will fit.`);
        }
        t.suppressedLabel = t.label;
        t.label = "";
      }
    };
    // Same restriction on both axes: only numeric ones. A category name that will not fit is made to
    // fit by the layout; it is never deleted. Unguarded, the Y call would delete, on a horizontal box /
    // violin / column scatter / floating bar, a long group name ("High dose") that a too-small left
    // margin pushed off the canvas; the name is kept, and
    // `band-axis-labels-fit.test.ts` holds every category axis to fitting instead.
    if (!scene.x.band) trimEscaping(scene.x, xBoxOf);
    if (!scene.y.band) trimEscaping(scene.y, (t, w) => yBoxOf(t, w, tickFont));
  }
  if (bands.length) scene.axisBands = bands;
  if (bars.length) scene.scaleBars = bars;
  if (groups.length) scene.categoryGroups = groups;
  // Reserve the group-name band by growing the canvas away from the plot, the same
  // way the footer / significance-caption bands do. The plot rect is untouched, so
  // nothing already laid out shifts.
  scene.width += growRight;
  scene.height += growBottom;
  return titleRoom;
}

/**
 * SeriesStyle fields that are a series' own identity, never inherited by a new sibling: its
 * colours (a new series takes the next palette colour), which axis it sits on,
 * whether it is hidden, its error-bar type (data-dependent — resolved per dataset by
 * `resolveErrorType`), and per-series value-label text / drag offsets.
 */
const SERIES_IDENTITY_FIELDS: ReadonlySet<keyof SeriesStyle> = new Set<keyof SeriesStyle>([
  "color", "pointColor", "lineColor", "symbolFillColor", "symbolOutline", "errorColor", "fillColor",
  "bandColor", "bandEdgeColor", "patternColor", "patternBg", "twoToneEdge", "gradTo",
  "axis", "hidden", "errorBars", "valueText", "valueDx", "valueDy",
]);

/**
 * A new series wears the graph's look. Without this, a third treatment added to an XY plot
 * would draw completely out of style with the other two: the existing series draw 8-px open
 * two-tone markers on 2-px lines, the new one a 4-px solid dot with a 1.5-px border.
 *
 * Why: a graph's look is stamped per series into `plot.seriesStyles` when the graph is made
 * (`applyKindHouseDefaults` writes the kind's `series` block, and the preset its marker fill /
 * widths, to every dataset that exists at that moment). A dataset added later — "+ Column",
 * typing into a spare column, a paste — has no entry and falls to the builder's bare fallback,
 * because the default applied at creation.
 *
 * At the one choke point every builder passes through, a dataset with no `seriesStyles`
 * entry inherits every field the graph's styled siblings unanimously share, minus the identity
 * fields above. Runs on the plot handed to the builders and writes nothing back to the
 * document — the inherited look is a derived default, exactly like a palette colour.
 *
 * Note: two or more styled siblings, agreeing. That is what distinguishes a graph-wide stamp
 * (the house look written to every series at creation — the look a new series should take)
 * from a per-series edit (the user hid the box on series A only, or drew one series as a line
 * over the bars). With a single styled series the two are indistinguishable, and spreading it
 * would undo the user's "only this one" (e.g. `violinShowBox:false` on A alone would strip
 * B's box too). So one styled sibling inherits nothing; two that disagree on a field inherit
 * nothing for that field. A bare new graph (no styles) is returned untouched.
 */
function inheritSeriesLook(table: DataTable, plot: Plot): Plot {
  const styles = plot.seriesStyles ?? {};
  const datasets = tableDatasets(table);
  /**
   * A key set to `undefined` is not a style. Every control that clears a field writes the
   * field back as `undefined`, and the document merges deltas with a spread — so clearing the
   * only setting a series had leaves `{ thatField: undefined }` behind, an object with one key
   * and no style in it. Counting keys would make that series read as styled, which would stamp
   * the kind's house defaults onto all of its unstyled siblings and quietly change the graph.
   *
   * Example: on a bare graph, focusing a series and then un-focusing it would leave every other
   * series with the kind's default markers, a wider legend swatch and a narrower plot, so the
   * plot would not return to its previous state. Any control that clears a field to `undefined`
   * can do the same, so it is handled here rather than per control.
   */
  const isStyled = (s: SeriesStyle | undefined): boolean => !!s && Object.values(s).some((v) => v !== undefined);
  const styled = datasets.map((d) => styles[d.id]).filter((s): s is SeriesStyle => isStyled(s));
  const missing = datasets.filter((d) => !isStyled(styles[d.id]));
  if (styled.length === 0 || missing.length === 0) return plot; // a bare graph, or nothing new: untouched
  // Layer 1 — the kind's house `series` block: the graph-type default that `applyKindHouseDefaults`
  // stamps on every series at creation (XY: 8-px markers; volcano: 0.85 opacity). Unambiguous —
  // it can never be a per-series edit — so it is safe even when only one sibling is styled.
  const house = KIND_HOUSE_DEFAULTS[plot.kind ?? "xy"]?.series;
  const shared: SeriesStyle = { ...(house ?? {}) };
  // Layer 2 — the stamped look shared by ≥2 styled siblings (see the note above): every field
  // present on all of them with one identical value, minus the identity fields.
  // Small-multiple pies take it from one styled pie: the pies share one legend, which describes the slice categories —
  // a pie drawn in another look makes that legend wrong for it (e.g. a dataset added to a two-tone pie would come out
  // solid, and the legend would match 1 pie of 3). Only where each dataset is a pie (a parts-of-whole
  // sheet with several value columns — `multiWhole` in the pie builder); on a one-row sheet each dataset is a slice and
  // keeps its own look. Identity fields (colours …) and that pie's own label choices (`sliceLabel…`) never copy.
  const pieWholes = (plot.kind ?? "xy") === "pie" && table.kind === "partsofwhole" && datasets.length > 1;
  if (styled.length >= 2 || (pieWholes && styled.length >= 1)) {
    const first = styled[0]!;
    for (const key of Object.keys(first) as (keyof SeriesStyle)[]) {
      if (SERIES_IDENTITY_FIELDS.has(key)) continue;
      if (pieWholes && styled.length === 1 && key.startsWith("sliceLabel")) continue;
      const v = first[key];
      if (v === undefined) continue;
      const vs = JSON.stringify(v);
      if (styled.every((s) => JSON.stringify(s[key]) === vs)) (shared as Record<string, unknown>)[key] = v;
    }
  }
  if (Object.keys(shared).length === 0) return plot;
  const next: Record<string, SeriesStyle> = { ...styles };
  for (const d of missing) next[d.id] = { ...shared };
  return { ...plot, seriesStyles: next };
}

/**
 * Edge labels fit inside the figure (the design choice is "fit inside", not "the drawing grows"): the first or
 * last name on the bottom axis must not stick out past the figure's left or right edge (e.g. a long first
 * category name on a Pareto chart). Growing the drawing to show such a label would make the figure bigger
 * than the size set.
 *
 * Measured here, once, for every chart kind: where each visible bottom-axis label is drawn (`xTickLabelPlacement`, the
 * renderer's own placement, tilted labels included) and how far past either edge the outermost reach. When one does,
 * the chart is rebuilt with that much more plot margin on that side (`plotPad`, the margin every axis chart honours),
 * so the plot narrows and the figure keeps its size. Narrowing moves the labels, so up to three rounds. A chart whose
 * labels already fit is returned as built — untouched.
 */
export function buildPlotScene(
  rawTable: DataTable,
  plot: Plot,
  options: BuildPlotSceneOptions = {},
): PlotScene {
  // Every width is measured in the font the graph draws its text in (its tick font): measured in the app font, a Georgia
  // label reads ~10% narrow and the collision checks would let widened numbers overlap.
  const family = resolveFonts(plot).tick.family;
  if (family && options.measure) { const base = options.measure; options = { ...options, measure: (t, px) => base(t, px, family) }; }
  let scene = buildPlotSceneOnce(rawTable, plot, options);
  const measure = options.measure ?? estimateWidth;
  let extraL = 0;
  let extraR = 0;
  for (let round = 0; round < 3; round++) {
    const over = edgeLabelOverflow(scene, measure);
    if (over.left <= 0.5 && over.right <= 0.5) break;
    extraL += over.left > 0.5 ? Math.ceil(over.left) + 1 : 0;
    extraR += over.right > 0.5 ? Math.ceil(over.right) + 1 : 0;
    const pad = plot.plotPad ?? {};
    const refit = buildPlotSceneOnce(rawTable, { ...plot, plotPad: { ...pad, left: (pad.left ?? 0) + extraL, right: (pad.right ?? 0) + extraR } }, options);
    // A chart that ignores the plot margin (pie, radar, 3-D …) cannot be fitted this way: keep what it drew.
    if (refit.plot.width >= scene.plot.width) break;
    scene = refit;
  }
  return scene;
}

/** How far (px) the drawn bottom-axis labels reach past the figure's left and right edges; 0 = inside. */
export function edgeLabelOverflow(scene: PlotScene, measure: (text: string, fontPx: number) => number): { left: number; right: number } {
  const ax = scene.x;
  if (!ax || ax.hidden || !ax.ticks?.length) return { left: 0, right: 0 };
  const font = scene.fonts.xTick.size;
  const gap = scene.axisGaps?.xTick ?? 6;
  const axisY = scene.plot.y + scene.plot.height;
  let lo = Infinity;
  let hi = -Infinity;
  for (const t of ax.ticks) {
    if (t.minor || !t.label) continue;
    const box = xTickLabelPlacement(t.pos, axisY, font, gap, ax.tickRotation ?? 0, measure(t.label, font)).box;
    lo = Math.min(lo, box.x1);
    hi = Math.max(hi, box.x2);
  }
  if (!Number.isFinite(lo)) return { left: 0, right: 0 };
  return { left: Math.max(0, -lo), right: Math.max(0, hi - scene.width) };
}

function buildPlotSceneOnce(
  rawTable: DataTable,
  plot: Plot,
  options: BuildPlotSceneOptions = {},
): PlotScene {
  // Note: excluded values are masked to null once, here, before any builder touches the data.
  // Every per-kind builder below reads `row.cells[...]` directly without consulting the
  // exclusion map, so without this an excluded point would still be drawn, joined by the line
  // and counted in the mean. Masking at the entry covers all of them, including any builder
  // added later. No-op (same object) when nothing is excluded.
  const localTable = applyExclusions(rawTable);
  // Series from other datasheets (`plot.overlays`): joined into the table
  // here, before any builder runs, so a foreign column is an ordinary series to everything
  // downstream. Needs the caller's table lookup; without one the overlays are left out.
  const joined = resolveOverlays(localTable, plot, options.tables);
  const table = joined.table;
  // Volcano draws dashed guide lines at its fold-change + p thresholds (added as
  // standard reference-line annotations so they reuse the annotation renderer).
  const effPlot = inheritSeriesLook(table, plot.kind === "volcano" ? volcanoGuides(plot) : plot);
  const scene = buildPlotSceneInner(table, effPlot, options);
  /**
   * The outside-top legend makes its own room — here, once, for every chart kind.
   *
   * `legend.position = "top"` puts the key in a row between the title and the plot, and unlike
   * an inside corner that row needs real space. The "right" column reserves its margin inside
   * `resolveLegend` because every builder adds `outsideRightWidth` to its right margin; the top
   * band cannot go the same way — each builder computes its own top padding, and many of them
   * resolve their legend after it. So the band is added where every builder already reads it:
   * the plot's own top padding (`plotPad.top`, via `plotPadOf`). One build to learn the entries
   * and the plot width, then a second with the band folded into the padding. Same pattern as
   * the significance-bracket retry above: an extra build only for a figure that asked for it.
   *
   * The wrap (which entries share a row) is decided here, with the builder's text measure, and
   * handed to the renderer as `topRows` — the renderer estimates widths differently, and two
   * wraps that disagree by one row would put the legend on the title or on the plot.
   *
   * …but a band must not take over the plot, the outside-right rule again (a third of the figure):
   * many long names wrap into a stack that leaves no drawing. Past that the legend moves
   * inside (bottom-right), losing nothing — same rows, same text, no reservation.
   */
  if (scene.legendLayout.position === "top" && scene.legend.length > 0) {
    const measure = options.measure ?? estimateWidth;
    const metrics = legendRowMetrics(scene, measure);
    const rows = wrapLegendRows(metrics.itemWidths, LEGEND_ITEM_GAP, scene.plot.width);
    const band = topLegendBand(rows.length, metrics);
    if (options.topLegendBand == null) {
      if (band > scene.height * 0.33) {
        scene.legendLayout = { ...scene.legendLayout, position: "bottomright", orientation: plot.legend?.orientation ?? "vertical" };
      } else {
        const padded: Plot = { ...plot, plotPad: { ...(plot.plotPad ?? {}), top: (plot.plotPad?.top ?? 0) + band } };
        return buildPlotScene(rawTable, padded, { ...options, topLegendBand: band });
      }
    } else {
      scene.legendLayout = { ...scene.legendLayout, topRows: rows };
    }
  }
  // Equal aspect asked for on a kind whose two axes are not one plane (a category count against
  // a measurement, a genome position against a p-value): refuse with a warning. The control is
  // hidden on these kinds, so the flag can only arrive from a saved project or a copied look — and
  // a silently ignored setting would be a dead control.
  if (effPlot.equalAspect === true && !EQUAL_ASPECT_KINDS.has(effPlot.kind ?? "xy")) {
    scene.warnings.push(
      "Equal aspect (1:1 scale) needs two continuous value axes on one plane, so it is not applied to this chart type.",
    );
  }
  if (joined.foreign.size > 0) {
    for (const s of scene.series) {
      const src = joined.foreign.get(s.id);
      if (src) s.from = src;
    }
  }
  if (joined.warnings.length) scene.warnings.push(...joined.warnings);
  // Data-driven per-point formatting (colour / symbol / label from a column) — resolved
  // before the manual overrides so a "Format this point" edit still wins over a binding.
  // The resolver reports a missing gradient straight into the scene's own warnings.
  paintDataDriven(table, plot, scene, makeRampResolver(options.gradients, scene.warnings), options.palette ?? OKABE_ITO);
  // Per-point style overrides ("Format this point" — highlighting). Applied at the
  // single choke point after graduated fills, so an explicit point colour wins.
  paintPointStyles(plot, scene);
  // …then push every unfocused series into the background, if the user chose any. After the
  // per-point styles on purpose: a highlighted point inside a background series would defeat it.
  // Loose legend rows take the same key passes as the block's rows - focus greying and the key that looks like its
  // mark - so a row pulled out of the block keys exactly what it keyed inside it. In for the passes, out again after.
  const looseRows = (scene.legendLayout.looseEntries ?? []).map((l) => l.entry);
  if (looseRows.length) scene.legend = [...scene.legend, ...looseRows];
  applyFocus(plot, scene);
  // Every legend key takes the look of the mark it names — its line, its dot, the dot's fill, edge and size (legendKeys.ts).
  matchKeysToMarks(scene);
  if (looseRows.length) scene.legend = scene.legend.filter((e) => !looseRows.includes(e));
  // Group dots side by side at the size they are drawn (beeswarm.ts) — before label / bracket placement reads them.
  spreadSwarms(scene);
  // Names on vertical reference lines that would print on each other step down a line (lineCaptions.ts).
  staggerLineCaptions(scene, options.measure ?? estimateWidth);
  // …then keep every point label clear of the marks, the line, the legend and each other.
  // After the per-point styles, because a "Format this point" size change moves the obstacle.
  placePointLabels(scene, options.measure ?? estimateWidth);
  // …then the series names, when the legend was replaced by direct labels. After the point
  // labels, because their boxes are obstacles a series name must clear.
  placeDirectLabels(scene, plot, options.measure ?? estimateWidth);
  // …then each series' own leader look (show / colour / width), on every leader the two passes drew.
  applyLeaderStyle(scene, plot);
  // …then the zone names, clear of the bars and marks those two passes placed against.
  placeBandCaptions(scene, options.measure ?? estimateWidth);
  sizeSignificanceLabels(scene);
  // Lift auto-placed significance brackets clear of the data / each other / the frame.
  // Here, not in the builders: this is the first point at which the marks carry real
  // pixels, and one pass at the choke point covers every chart kind.
  const { shortfallPx, clamped: clampedBrackets } = placeAutoBrackets(scene);
  /*
   * The graph makes its own room. If the stack came up short, widen the value axis and build
   * again. Costs an extra build only for a figure that has significance brackets and could not fit
   * them; every other figure is untouched.
   *
   * Iterates, because one calculated step is not enough. The shortfall is
   * measured in pixels and the fix is applied in data units, and the two are not related by a
   * constant: widening the domain moves the data down, but the placer then re-derives the whole
   * stack against the new positions and can want more (e.g. scree can need +25% where the
   * first shortfall implies +8%). So it re-measures after each step and stops as soon as the stack
   * fits, which also keeps the result minimal: the axis grows to the first size that
   * works, not to a padded guess.
   *
   * Note: `bracketRetries` bounds it at four. An infinite build loop in a renderer is a hang, not a
   * wrong pixel.
   */
  const retries = options.bracketRetries ?? 0;
  // The value axis's own spec, through dataAxisOf. A horizontal bar / box / violin / column scatter
  // draws its values along X but keeps their range in `plot.yAxis`; reading `plot.xAxis` there (the
  // category spec) would widen a setting the drawing never reads: every retry would rebuild the same
  // figure and the brackets would still end at the "no room" clamp.
  const valueKey = dataAxisOf(plot, scene.valueAxis === "x" ? "x" : "y") === "x" ? "xAxis" : "yAxis";
  const valueSpec = plot[valueKey] ?? {};
  // A zoom window pins the drawn domain, so widening the axis max cannot make room — the
  // retry below is skipped, and `auto` is taken from a real un-windowed build instead
  // (further down), so the home the detent resets to is the home a reset would rebuild.
  const windowed = options.xDomain != null || options.yDomain != null;
  // Only a window the builder honours on the value axis pins that axis. A window on the other axis (an XY graph
  // zoomed along X), or one this kind ignores altogether (an X window left in the view of a bar chart), leaves
  // the value axis free - and skipping the retry for those would draw the brackets with no room made for them
  // (e.g. a bar chart's Y at [0, 80] with an X window against [0, 86] without one; see zoomable.test.ts).
  const valueVisual = scene.valueAxis === "x" ? "x" : "y";
  const valueWindowed = (scene.zoomable ?? []).some(
    (z) => z.visual === valueVisual && (z.key === "x" ? options.xDomain : options.yDomain) != null,
  );
  if (shortfallPx > 0 && retries < 4 && !valueWindowed) {
    const onX = scene.valueAxis === "x";
    const ax = onX ? scene.x : scene.y;
    const spec = valueSpec;
    if (!(spec.reversed ?? false)) {
      // Note: `spec.max` on the first pass only. On a retry the max set by this loop is now in
      // `spec`, so passing it as "the user pinned it" would refuse every step after the first.
      const max = widenForBrackets(ax, shortfallPx, retries === 0 ? spec.max : undefined);
      if (max != null && max > (spec.max ?? -Infinity)) {
        // A series on the right-hand axis (a bars + line composite) scales to its own domain,
        // so widening the left axis alone leaves that line's ink exactly where it was — at the
        // plot top, under the bracket stack. Grow Y2 by the same pixel shortfall so the whole
        // drawing moves down together. A user-pinned Y2 max still wins.
        // The second axis grows with the value axis it runs beside: the right axis on a vertical
        // chart, the top axis (`side: "top"`) on a horizontal bar chart.
        const y2Spec = plot.y2Axis ?? {};
        const y2Beside = !!scene.y2 && (onX ? scene.y2.side === "top" : scene.y2.side !== "top");
        const max2 = y2Beside && !(y2Spec.reversed ?? false)
          ? widenForBrackets(scene.y2!, shortfallPx, retries === 0 ? y2Spec.max : undefined)
          : null;
        const widened = {
          ...plot,
          [valueKey]: { ...spec, max },
          ...(max2 != null && max2 > (y2Spec.max ?? -Infinity) ? { y2Axis: { ...y2Spec, max: max2 } } : {}),
        } as Plot;
        return buildPlotScene(rawTable, widened, { ...options, bracketRetries: retries + 1 });
      }
    }
  }
  /**
   * Past the retry decision, the reason no more room is coming is known — and the warning has
   * to state the true one. A pinned axis is only one cause; on paired-dot nothing is pinned
   * and the axis may already have been widened four times.
   *
   * "Clear the axis maximum" is advice only when a maximum is set; with none, it would point
   * the user at a setting that has nothing to clear.
   */
  /*
   * A height-less bracket (`bracketY == null` — the shape a hand-added blank bracket has) can
   * make the home domain wider than the data through the retry above, and a windowed build
   * skips that retry — so its `auto`, derived from the data alone, would report a home the
   * un-zoomed rebuild does not produce (e.g. [0, 80] vs [0, 96.3]).
   * Build the home once, without the window, and read the true `auto` off it. Brackets with
   * an explicit height never need this: they fold into the domain through
   * significanceHeadroom() identically with and without a window.
   *
   * Cost: one extra build (with its own bounded retries) per windowed rebuild, only for a
   * figure that carries height-less brackets and is currently zoomed — roughly what the
   * skipped in-window retry would spend. Recursion terminates because the probe itself
   * carries no window.
   */
  /*
   * Equal aspect needs the same probe, for the same reason. With it on, the two axes are
   * coupled: the drawn Y follows whatever window X is showing. So in a windowed build neither
   * axis sits at its home extent, and the margins differ too (different tick labels → a
   * different plot rectangle → a different 1:1 answer). No arithmetic on the windowed build can
   * recover the home; only a build without the window can, and that is what this does.
   */
  const homeNeedsOwnBuild =
    // A planned height reaches the retry too, since planned ladders lift clear of the ink: e.g. a bar chart's
    // home is [0, 86] while its zoomed build would report [0, 80], so a reset would aim at the wrong home.
    (plot.annotations ?? []).some((a) => a.kind === "bracket" && (a.bracketY == null || a.plannedY === true)) ||
    (effPlot.equalAspect === true && EQUAL_ASPECT_KINDS.has(effPlot.kind ?? "xy"));
  if (windowed && homeNeedsOwnBuild) {
    const { xDomain: _x, yDomain: _y, bracketRetries: _r, ...homeOptions } = options;
    scene.auto = buildPlotScene(rawTable, plot, homeOptions).auto;
  }
  if (clampedBrackets > 0) {
    const userPinned = retries === 0 && valueSpec.max != null;
    const many = clampedBrackets === 1 ? "A significance bracket" : `${clampedBrackets} significance brackets`;
    scene.warnings.push(
      userPinned
        ? `${many} could not be placed clear of the data and of each other — this graph's value axis is pinned, `
          + "so there is no room above the tallest value. Clear the axis maximum to let the graph make room, "
          + "or drag the brackets where you want them."
        : `${many} could not be placed clear of the data and of each other. The graph already widened its value `
          + "axis as far as it can; there is not enough room across the plot for the whole stack. "
          + "Make the figure larger, use fewer brackets, or drag them where you want them.",
    );
  }
  // Figure (paper) background — resolved once at the single choke point so every
  // chart kind honours it. "transparent"/undefined → null (no backing rect).
  scene.background = plot.background && plot.background !== "transparent" ? plot.background : null;
  // Decorative backdrop (opt-in, default none) — resolved at the same choke point so every
  // chart kind honours it and there is only one place that decides the figure's backing.
  scene.backdrop = buildBackdrop(plot.backdrop, scene.width, scene.height);
  if (plot.titleOffset) scene.titleOffset = plot.titleOffset;
  if (plot.subtitleOffset) scene.subtitleOffset = plot.subtitleOffset;
  if (plot.legendOffset) scene.legendOffset = plot.legendOffset;
  if (plot.colorbarOffset) scene.colorbarOffset = plot.colorbarOffset;
  // Per-axis title drag offsets (free placement of the axis-title text). Sourced from
  // the data axis spec (like the title text / scale / line — see dataAxisOf) so a
  // flipped chart's offset stays welded to its title: a transposed chart's visual X
  // reads plot.yAxis's offset, and its visual Y reads plot.xAxis's.
  const offX = isTransposedPlot(plot) ? plot.yAxis : plot.xAxis;
  const offY = isTransposedPlot(plot) ? plot.xAxis : plot.yAxis;
  if (offX?.titleOffset) scene.x.titleOffset = offX.titleOffset;
  if (offY?.titleOffset) scene.y.titleOffset = offY.titleOffset;
  // Y2 / Y3 are data axes wherever they are drawn (right of a vertical chart, top of a horizontal one),
  // so no flip mapping. Written only when set, so a figure nobody dragged carries no offsets.
  if (scene.y2 && plot.y2Axis?.titleOffset) scene.y2.titleOffset = plot.y2Axis.titleOffset;
  if (scene.y3 && plot.y3Axis?.titleOffset) scene.y3.titleOffset = plot.y3Axis.titleOffset;
  if (plot.titleAlign && plot.titleAlign !== "center") scene.titleAlign = plot.titleAlign;
  // Resolved axis spacing (label↔axis, title↔labels) — the renderer offsets by these.
  scene.axisGaps = {
    xTick: plot.xAxis?.tickLabelGap ?? 6,
    xTitle: plot.xAxis?.titleGap ?? 6,
    yTick: plot.yAxis?.tickLabelGap ?? 8,
    yTitle: plot.yAxis?.titleGap ?? 6,
  };
  // Axis-engine extras (custom ticks + shaded bands + tick rotation + category
  // groups) resolved once at this choke point so every chart kind honours them
  // without per-builder threading.
  // Never an empty frame without a warning. A sheet that holds data but a kind that placed nothing
  // and reported nothing (Chart ▸ Type on a shape the builder cannot read) is reported here, once,
  // for every kind. An empty sheet stays quiet: nothing was asked.
  if (scene.warnings.length === 0 && !sceneHasInk(scene) && table.rows.some((r) => Object.values(r.cells).some((v) => v != null && String(v).trim() !== ""))) {
    scene.warnings.push(`Nothing to draw: this chart found no columns it can read on this datasheet. Check the datasheet format, or pick a chart made for it (New graph… lists them).`);
  }
  const titleRoom = resolveAxisExtras(scene, plot, table, options.palette ?? OKABE_ITO, options.measure ?? estimateWidth, { given: options.yTitleRoom, topLegendBand: options.topLegendBand, minTextPx: options.minTextPx });
  // Title direction: a Y title turned another way that needs more room than the builder reserved gets it from
  // one more build, the shortfall folded into the plot's own padding — as the outside-top legend does above.
  if (options.yTitleRoom == null && (titleRoom.left > 0 || titleRoom.top > 0)) {
    const pp = plot.plotPad ?? {};
    const given = { left: Math.ceil(titleRoom.left), top: Math.ceil(titleRoom.top) };
    const padded: Plot = { ...plot, plotPad: { ...pp, left: (pp.left ?? 0) + given.left, top: (pp.top ?? 0) + given.top } };
    return buildPlotScene(rawTable, padded, { ...options, yTitleRoom: given });
  }
  // …and when even that room could not be given (a builder that caps its margins), a level title goes above the
  // axis instead: one last build, the left room taken back and the band above the plot added.
  if (options.yTitleRoom != null && !options.yTitleRoom.above && titleRoom.above) {
    const pp = plot.plotPad ?? {};
    const was = options.yTitleRoom;
    const given = { left: 0, top: Math.ceil(titleRoom.top), above: true };
    const padded: Plot = { ...plot, plotPad: { ...pp, left: (pp.left ?? 0) - was.left, top: (pp.top ?? 0) - was.top + given.top } };
    return buildPlotScene(rawTable, padded, { ...options, yTitleRoom: given });
  }
  // Significance threshold legend — appended in a reserved band below the figure
  // (so it never collides with the X-axis title), at the single choke point.
  const caption = significanceLegend(plot, scene.annotations);
  if (caption) {
    const sigStyle = plot.significance;
    const capSize =
      typeof sigStyle?.legendSize === "number" && Number.isFinite(sigStyle.legendSize) && sigStyle.legendSize > 0
        ? sigStyle.legendSize
        : scene.fonts.legend.size;
    scene.significanceCaption = caption;
    scene.significanceCaptionStyle = {
      size: capSize,
      ...(sigStyle?.legendFontFamily ? { family: sigStyle.legendFontFamily } : {}),
      ...(sigStyle?.legendBold ? { bold: true } : {}),
      ...(sigStyle?.legendItalic ? { italic: true } : {}),
      ...(sigStyle?.legendColor ? { color: sigStyle.legendColor } : {}),
      ...(sigStyle?.legendOffset ? { offset: sigStyle.legendOffset } : {}),
    };
    // The band grows with the caption's own size — a 20px key in a 13px band overlaps
    // the axis title, which is exactly the collision this reserved band exists to avoid.
    scene.height += capSize + 10;
  }
  // Zone key — a legend for the shaded zone bands, overlaid in a plot corner. Built at this
  // choke point because it reads the final band scene annotations (their resolved fill + label).
  buildZoneKey(scene, plot, options.measure ?? estimateWidth);
  // Lines in the legend - read off the final scene: only it says which lines were drawn and which rows are shown.
  dockLegendLines(scene);
  // Footer / source mark — a reserved band below everything else (so it never
  // collides with the X-axis title or the significance legend).
  const fl = plot.footer?.left?.trim();
  const fr = plot.footer?.right?.trim();
  if (fl || fr) {
    scene.footer = { ...(fl ? { left: fl } : {}), ...(fr ? { right: fr } : {}) };
    scene.height += Math.round(scene.fonts.legend.size * 0.9) + 12;
  }
  return scene;
}

/** Zone-key layout constants — shared with the renderer (PlotFigure) so the drawn frame fits the
 *  rows the builder measured. Change here and the renderer follows via the same import. */
export const ZONE_KEY_PAD = 7;   // inner padding (px)
export const ZONE_KEY_GAP = 6;   // swatch → label gap (px)
export const ZONE_KEY_INSET = 10; // distance from the plot corner (px)
/** One key row's height as a multiple of the legend font size. */
export const ZONE_KEY_ROW = 1.5;

/**
 * Build the zone key — a small legend for the shaded zone bands, overlaid in a plot corner
 * (`Plot.zoneLegend`). One row per band that carries a label: its resolved fill swatch + its
 * caption. Since the key carries the caption, the in-band caption is dropped so it is not
 * drawn twice (the zone text lives only in the key).
 *
 * Reads the final `band` scene annotations (their resolved fill + label), so it must run at the
 * post-build choke point, after `buildAnnotations` has placed and coloured every band.
 */
function buildZoneKey(scene: PlotScene, plot: Plot, measure: (t: string, s: number) => number): void {
  const pos = plot.zoneLegend;
  if (!pos || pos === "off") return;
  const labelled = scene.annotations.filter((a) => a.kind === "band" && (a.label ?? "").trim() !== "");
  if (labelled.length === 0) return; // nothing to key — no band carries a label
  const entries = labelled.map((a) => ({ label: a.label!, color: (a.fill ?? "#888888") as string }));
  const size = scene.fonts.legend.size;
  const swatch = size;
  const rowH = Math.round(size * ZONE_KEY_ROW);
  const labelW = Math.max(0, ...entries.map((e) => measure(e.label, size)));
  const w = Math.round(ZONE_KEY_PAD * 2 + swatch + ZONE_KEY_GAP + labelW);
  const h = ZONE_KEY_PAD * 2 + entries.length * rowH;
  const r = scene.plot;
  const left = pos === "topleft" || pos === "bottomleft";
  const topSide = pos === "topleft" || pos === "topright";
  const x = left ? r.x + ZONE_KEY_INSET : r.x + r.width - ZONE_KEY_INSET - w;
  const y = topSide ? r.y + ZONE_KEY_INSET : r.y + r.height - ZONE_KEY_INSET - h;
  scene.zoneLegend = { x, y, w, h, entries };
  // The key carries each zone's label, so the in-band caption is dropped and not drawn twice.
  for (const a of labelled) { delete a.label; delete a.labelX; delete a.labelY; delete a.labelAnchor; }
}

/**
 * Collision-free initial placement for auto-placed significance brackets.
 *
 * A default height taken as a fraction of the plot rect is pure geometry, blind to where
 * the data actually is, so a bracket over a tall bar would draw straight through it. This pass
 * runs at the choke point, where the scene is fully built and the marks carry real pixels,
 * and lifts each auto bracket clear of:
 *   • every data mark under its span (bar tops, box whiskers + outliers, violin outlines,
 *     scatter dots, error-bar caps, the plotted points themselves),
 *   • the brackets already placed beneath it (label included, so stars never touch a rail),
 *   • the plot frame, and with it the axis and the title, which live outside that rect.
 *
 * Only brackets the user did not position are touched (`autoY`) — a typed or dragged height
 * is a decision, and this pass never overrules one. It is an initial layout, not a running
 * constraint: drag a bracket anywhere afterwards and it stays there.
 *
 * When the data fills the plot to the ceiling there is genuinely nowhere to go: the bracket
 * is clamped inside the frame and the scene says so, rather than silently drawing over the
 * bars or escaping off the canvas.
 */
function placeAutoBrackets(scene: PlotScene): { shortfallPx: number; clamped: number } {
  const auto = (scene.annotations ?? []).filter((a) => a.kind === "bracket" && a.autoY && a.path);
  // Planned-height brackets (the significance planner's data-unit ladder) get their own
  // clear-of-ink pass below — a scene carrying only those must not bail out here.
  const planned = (scene.annotations ?? []).filter((a) => a.kind === "bracket" && a.plannedY && !a.autoY && a.path);
  if (auto.length === 0 && planned.length === 0) return { shortfallPx: 0, clamped: 0 };
  const rect = scene.plot;
  // The value axis is the one a bracket's height lives on; `sign` is the direction away
  // from the data (up = -1 on an ordinary chart, right = +1 when the value axis is X).
  const onX = scene.valueAxis === "x";
  const sign = onX ? 1 : -1;
  /** Value coordinate of a point (the axis a bracket's height is measured on). */
  const val = (x: number, y: number): number => (onX ? x : y);
  /** Category coordinate of a point (the axis a bracket spans). */
  const cat = (x: number, y: number): number => (onX ? y : x);
  /** Is `a` further from the data than `b`? */
  const beyond = (a: number, b: number): boolean => (sign > 0 ? a > b : a < b);
  const outerMost = (xs: number[]): number | null =>
    xs.length === 0 ? null : xs.reduce((m, v) => (beyond(v, m) ? v : m));

  // ── every occupied point in the plot, as (category, value) pairs ──────────────────
  // Sampling points rather than boxes keeps this one rule across every chart kind: a bar
  // contributes its top corners, a box its whisker end and outliers, a violin its outline.
  const obst: { c: number; v: number }[] = [];
  const push = (x: number, y: number): void => {
    if (Number.isFinite(x) && Number.isFinite(y)) obst.push({ c: cat(x, y), v: val(x, y) });
  };
  for (const s of scene.series ?? []) {
    // Note: a point is a disc, not its centre — the same rule the leg-reach ink (`inkTop`)
    // follows. Measured from the centre, a house-sized dot (radius 14) would take 14 of
    // GAP_DATA's 18px and the rail would read as resting on the top swarm dot. Only the
    // value-axis edge matters: the rail is placed along that axis, so each disc obstacle is
    // pushed at its away-from-data edge.
    const discR = Math.max(0, s.symbolSize ?? 4);
    const pushDisc = (x: number, y: number): void => (onX ? push(x + sign * discR, y) : push(x, y + sign * discR));
    for (const m of s.marks ?? []) {
      // A mark with bar/box/violin geometry contributes that exact geometry below; its
      // centre is not a drawn disc. A bare mark is the marker itself — a disc.
      if (m.bar || m.box || m.violin) push(m.cx, m.cy);
      else pushDisc(m.cx, m.cy);
      if (m.bar) {
        // Both corners and the centre: a wide bar must block a bracket that only clips its edge.
        push(m.bar.x, m.bar.y);
        push(m.bar.x + m.bar.w, m.bar.y);
        push(m.bar.x + m.bar.w / 2, m.bar.y);
        push(m.bar.x, m.bar.y + m.bar.h);
        push(m.bar.x + m.bar.w, m.bar.y + m.bar.h);
      }
      if (m.box) {
        // `x`/`w` are the box's category extent; the quartiles are value pixels. On a
        // transposed chart the builder has already swapped them, so read them as such.
        const c1 = m.box.x;
        const c2 = m.box.x + m.box.w;
        for (const v of [m.box.q1, m.box.q3, m.box.whiskerLow, m.box.whiskerHigh, ...(m.box.outliers ?? [])]) {
          for (const c of [c1, (c1 + c2) / 2, c2]) obst.push({ c, v });
        }
      }
      if (m.violin?.path) {
        // The silhouette is the outline — parse its coordinate pairs rather than guessing
        // a half-height from the KDE, which would under-cover a long tail.
        for (const pair of m.violin.path.matchAll(/(-?\d+(?:\.\d+)?)[ ,](-?\d+(?:\.\d+)?)/g)) {
          push(Number(pair[1]), Number(pair[2]));
        }
      }
      for (const p of m.points ?? []) pushDisc(p.cx, p.cy);
      // Error-bar caps reach past the mark they belong to — the classic thing a bracket
      // clears the bar for and then lands on anyway.
      if (m.errHighCy != null) push(m.cx, m.errHighCy);
      if (m.errLowCy != null) push(m.cx, m.errLowCy);
      if (m.errHighCx != null) push(m.errHighCx, m.cy);
      if (m.errLowCx != null) push(m.errLowCx, m.cy);
    }
  }
  // Dot layers outside `scene.series` — lollipop heads and paired-dot markers draw from
  // their own scene geometry, so the placer must read them here or it would ignore them
  // (the brackets would sit at the stagger fraction whatever the dot size). Same disc rule as
  // the marks above: the value-axis edge, not the centre. With these included, a
  // lollipop/paired-dot bracket gets the same hugging placement as every series kind.
  const pushDot = (cx: number, cy: number, r: number): void =>
    onX ? push(cx + sign * Math.max(0, r), cy) : push(cx, cy + sign * Math.max(0, r));
  for (const row of scene.lollipop?.rows ?? []) {
    for (const d of row.dots) {
      pushDot(d.cx, d.cy, d.size ?? scene.lollipop!.dotSize);
      // The mean±error whisker reaches past the dot along the value axis.
      if (d.error) {
        for (const vpx of [d.error.lowPx, d.error.highPx]) push(onX ? vpx : d.cx, onX ? d.cy : vpx);
      }
    }
  }
  for (const row of scene.paireddot?.rows ?? []) {
    for (const m of row.marks) pushDot(m.cx, m.cy, m.size ?? scene.paireddot!.dotSize);
  }

  /** Font size of a bracket's symbol — what it needs above the bar to stay clear. */
  const labelSize = (a: AnnotationScene): number => (a.label ? a.fontSize ?? scene.fonts.legend.size : 0);
  // Breathing room, in px. `GAP_DATA` is generous (10 reads as crowded) — an error-bar cap is a
  // thin line, so a bracket a few pixels above one looks like it is resting on it.
  const GAP_DATA = 18; // bracket line → nearest data pixel
  const GAP_STACK = 10; // bracket line → the label of the bracket below it
  const EDGE = 3; // symbol → the plot frame
  /** How much of the font size a symbol's ink really occupies above the baseline. A star or an
   *  asterisk stands about four-fifths of an em tall; the rest of the em is leading, which the
   *  next rung has no reason to reserve. */
  const LABEL_INK = 0.78;
  /** Daylight between one rung's symbol and the rail above it: proportional to the symbol, so a
   *  ladder of 10 px stars is tight and one of 30 px stars is not cramped (the space
   *  stays minimal and adjusts to the font size). Never less than 2 px, so a tiny
   *  font still shows a gap. */
  const rungGap = (fs: number): number => Math.max(2, fs * 0.1);

  // Narrowest span first: a wide bracket has to clear the narrow ones nested under it, so
  // it must be placed after them. Ties keep the order the scene already holds.
  const ordered = auto
    .map((a, i) => ({ a, i, c1: Math.min(cat(a.x1 ?? 0, a.y1 ?? 0), cat(a.x2 ?? 0, a.y2 ?? 0)), c2: Math.max(cat(a.x1 ?? 0, a.y1 ?? 0), cat(a.x2 ?? 0, a.y2 ?? 0)) }))
    .sort((p, q) => p.c2 - p.c1 - (q.c2 - q.c1) || p.i - q.i);

  // Each placed bracket records the outer edge it occupies (the far side of its symbol,
  // not its rail), so the next one clears the drawn ink rather than an estimate of it.
  const placed: { c1: number; c2: number; edge: number }[] = [];
  let clamped = 0;
  let shortfallPx = 0;
  for (const { a, c1, c2 } of ordered) {
    const here = val(a.x1 ?? 0, a.y1 ?? 0);
    const fs = labelSize(a);
    // What must be cleared under this span: the data, plus every bracket already placed
    // whose span overlaps this one (its symbol, not just its rail).
    const dataV = outerMost(obst.filter((o) => o.c >= c1 - 1 && o.c <= c2 + 1).map((o) => o.v));
    const stackV = outerMost(
      placed.filter((p) => p.c2 >= c1 - 1 && p.c1 <= c2 + 1).map((p) => p.edge + sign * GAP_STACK),
    );
    // The rail only needs `GAP_DATA` of daylight over the data — the symbol sits on the
    // far side of the rail, away from it, so it costs nothing here. It costs frame room,
    // which is what `limit` below is for. (Counting it here too would reserve ~2× the space
    // needed and push ordinary figures into the "no room" clamp.)
    let want = here;
    if (dataV != null) want = dataV + sign * GAP_DATA;
    if (stackV != null && beyond(stackV, want)) want = stackV;
    // Never leave the frame — the axis and the title live outside this rect, so staying
    // inside clears them by construction. The limit is where the symbol would land, not
    // the rail: measured from the geometry the builder actually emitted, so a brace (whose
    // label rides higher than a plain bracket's) is accounted for without a special case.
    const lift = a.label && a.labelX != null && a.labelY != null
      ? Math.abs(val(a.labelX, a.labelY) - here)
      : 0;
    const reach = a.label ? lift + (onX ? fs * 0.62 * a.label.length : fs) : 0;
    const limit = onX ? rect.x + rect.width - EDGE - reach : rect.y + EDGE + reach;
    // How much room this bracket asked for and did not get. The caller uses the largest such
    // shortfall to widen the value axis and build once more, so the stack gets the space it
    // needs instead of the figure telling the user to go and make it themselves.
    if (beyond(want, limit)) { shortfallPx = Math.max(shortfallPx, Math.abs(want - limit)); want = limit; }
    // Each bracket sits just above the tallest thing it spans — the conventional nested
    // look, and the only way a stack fits: parking every bracket at a fixed fraction of
    // the plot spends the headroom the ones above it need. Where a span has no data under
    // it at all (`dataV == null`) the staggered fraction remains the fallback.
    const final = dataV == null ? here : want;
    // Did the clamp cost the intended clearance? Hitting the frame is not itself
    // a failure — a figure with modest headroom lands there and still clears everything.
    // It is a failure when the result cannot clear the data, or the brackets below it:
    // that means the figure has no room for this stack, which the user has to know.
    if ((dataV != null && beyond(dataV + sign * GAP_DATA, final)) || (stackV != null && beyond(stackV, final))) {
      clamped += 1;
    }
    if (final !== here) {
      const d = final - here;
      const dx = onX ? d : 0;
      const dy = onX ? 0 : d;
      a.path = shiftPathBy(a.path!, dx, dy);
      if (a.x1 != null) a.x1 += dx;
      if (a.x2 != null) a.x2 += dx;
      if (a.y1 != null) a.y1 += dy;
      if (a.y2 != null) a.y2 += dy;
      if (a.labelX != null) a.labelX += dx;
      if (a.labelY != null) a.labelY += dy;
      // Legs that reach the bars are anchored to the ink, not to the rail: put their ends back
      // (the shift moved every point of the path); the rail only ever moves away from the data, so the legs only get longer.
      if (a.legEnds) a.path = pinLegEnds(a.path, a.legEnds, onX);
    }
    // `reach` is measured from the rail, so the outer edge is the rail plus it — which is
    // the top of the symbol on an ordinary chart, and its right-hand end on a transposed one.
    placed.push({ c1, c2, edge: val(a.x1 ?? 0, a.y1 ?? 0) + sign * reach });
  }

  // ── Planned ladders: heights the significance planner computed, in data units ─────────
  // The planner cannot see pixel ink — a house-sized data point's disc extends ~14px above
  // the top value, so a planned rung can land inside the dots at the top of a group. Lift the
  // whole planned set together — one uniform shift, so shared rungs stay shared and
  // staircase spacing survives — by the smallest delta that clears every rung's own span.
  // Only overlap is rescued (a small gap, not GAP_DATA): the planner's own data-unit gap
  // is the intended look, and every analysis figure keeps its spacing. A hand
  // height never carries `plannedY` (dragging clears it — moveAnnotation), so the
  // "a height the user set is never moved" rule stands untouched.
  if (planned.length > 0) {
    const GAP_PLANNED = 6;
    /** The value-coordinate of a path's data-most drawn pixel (the leg tips). */
    const dataMostOfPath = (path: string): number | null => {
      let low: number | null = null;
      for (const m of path.matchAll(/(-?\d+(?:\.\d+)?)[ ,](-?\d+(?:\.\d+)?)/g)) {
        const v = val(Number(m[1]), Number(m[2]));
        if (low == null || beyond(low, v)) low = v; // keep the least-beyond (closest to data)
      }
      return low;
    };
    let delta = 0;
    for (const a of planned) {
      const c1 = Math.min(cat(a.x1 ?? 0, a.y1 ?? 0), cat(a.x2 ?? 0, a.y2 ?? 0));
      const c2 = Math.max(cat(a.x1 ?? 0, a.y1 ?? 0), cat(a.x2 ?? 0, a.y2 ?? 0));
      const dataV = outerMost(obst.filter((o) => o.c >= c1 - 1 && o.c <= c2 + 1).map((o) => o.v));
      // The bracket's collision surface: its whole drawn body for plain legs (rail + tick
      // tips) — but for reach legs (`legEnds`) only the rail: those tips hug the ink at
      // LEG_GAP by design, and reading them as a collision would lift
      // every reach-legged figure on every build.
      const low = a.legEnds ? val(a.x1 ?? 0, a.y1 ?? 0) : dataMostOfPath(a.path!);
      if (dataV == null || low == null) continue;
      const edge = dataV + sign * GAP_PLANNED;
      if (!beyond(low, edge)) delta = Math.max(delta, Math.abs(low - edge));
    }
    if (delta > 0) {
      // Never lift a symbol out of the frame: cap the shift at what the tightest planned
      // bracket can take, and report the ones a capped shift leaves colliding.
      let allowed = delta;
      for (const a of planned) {
        const here = val(a.x1 ?? 0, a.y1 ?? 0);
        const fs = labelSize(a);
        const lift = a.label && a.labelX != null && a.labelY != null ? Math.abs(val(a.labelX, a.labelY) - here) : 0;
        const reach = a.label ? lift + (onX ? fs * 0.62 * a.label.length : fs) : 0;
        const limit = onX ? rect.x + rect.width - EDGE - reach : rect.y + EDGE + reach;
        // Room left in the away-from-data direction before this rail's symbol hits the frame.
        allowed = Math.min(allowed, Math.max(0, sign * (limit - here)));
      }
      if (allowed < delta) clamped += 1;
      const d = sign * Math.min(delta, allowed);
      const dx = onX ? d : 0;
      const dy = onX ? 0 : d;
      for (const a of planned) {
        a.path = shiftPathBy(a.path!, dx, dy);
        if (a.x1 != null) a.x1 += dx;
        if (a.x2 != null) a.x2 += dx;
        if (a.y1 != null) a.y1 += dy;
        if (a.y2 != null) a.y2 += dy;
        if (a.labelX != null) a.labelX += dx;
        if (a.labelY != null) a.labelY += dy;
        if (a.legEnds) a.path = pinLegEnds(a.path, a.legEnds, onX);
      }
    }
    // …then spread the rungs, because the planner spaces them in data units and cannot see how
    // tall a symbol is: its step is a fraction of the data span, so on a figure whose stars are
    // large (or whose data span is small) the rung above lands inside the symbol below it
    // (e.g. three rungs 12 px apart carrying 33 px stars: every label crossed by the rail above).
    //
    // Only a rung that would collide is moved, and rungs move as a whole, so a ladder that
    // already fits is untouched and shared rungs stay level. A shortfall is reported like any
    // other, so the axis grows to hold the taller ladder instead of the top rung being clamped.
    const rungs = new Map<number, AnnotationScene[]>();
    for (const a of planned) {
      const key = Math.round(val(a.x1 ?? 0, a.y1 ?? 0) * 10) / 10;
      (rungs.get(key) ?? rungs.set(key, []).get(key)!).push(a);
    }
    // Nearest the data first: each rung clears everything already placed under it.
    const order = [...rungs.entries()].sort((p, q) => (sign > 0 ? p[0] - q[0] : q[0] - p[0]));
    const spread: { c1: number; c2: number; edge: number }[] = [];
    for (const [, members] of order) {
      const spans = members.map((a) => ({
        a,
        c1: Math.min(cat(a.x1 ?? 0, a.y1 ?? 0), cat(a.x2 ?? 0, a.y2 ?? 0)),
        c2: Math.max(cat(a.x1 ?? 0, a.y1 ?? 0), cat(a.x2 ?? 0, a.y2 ?? 0)),
      }));
      let shift = 0;
      for (const { a, c1, c2 } of spans) {
        // A bracket's legs hang toward the data below its rail, so the rail is not its lowest
        // ink: the stars of the rung below can touch the leg tips of the rung above while the
        // rails themselves are clear. Reach legs (`legEnds`) are
        // long by design and hug the bars, so those count from the rail, as in the lift above.
        const here = (a.legEnds ? null : dataMostOfPath(a.path!)) ?? val(a.x1 ?? 0, a.y1 ?? 0);
        const under = outerMost(spread.filter((p) => p.c2 >= c1 - 1 && p.c1 <= c2 + 1).map((p) => p.edge + sign * rungGap(labelSize(a))));
        if (under != null && beyond(under, here)) shift = Math.max(shift, Math.abs(under - here));
      }
      if (shift > 0) {
        for (const { a } of spans) {
          const d = sign * shift;
          const dx = onX ? d : 0;
          const dy = onX ? 0 : d;
          a.path = shiftPathBy(a.path!, dx, dy);
          if (a.x1 != null) a.x1 += dx;
          if (a.x2 != null) a.x2 += dx;
          if (a.y1 != null) a.y1 += dy;
          if (a.y2 != null) a.y2 += dy;
          if (a.labelX != null) a.labelX += dx;
          if (a.labelY != null) a.labelY += dy;
          if (a.legEnds) a.path = pinLegEnds(a.path, a.legEnds, onX);
        }
      }
      for (const { a, c1, c2 } of spans) {
        const here = val(a.x1 ?? 0, a.y1 ?? 0);
        const fs = labelSize(a);
        const lift = a.label && a.labelX != null && a.labelY != null ? Math.abs(val(a.labelX, a.labelY) - here) : 0;
        // The frame clamp keeps the conservative full-em reach; the rung above only has to
        // clear the ink (see `LABEL_INK`), so the ladder stays tight without leaving the plot.
        const reach = a.label ? lift + (onX ? fs * 0.62 * a.label.length : fs) : 0;
        const limit = onX ? rect.x + rect.width - EDGE - reach : rect.y + EDGE + reach;
        // `limit` already holds the label's reach (frame edge + EDGE + reach), so it is the rail that is set against
        // it - as the auto-placed pass above does (`beyond(want, limit)`). Adding the reach to `here` as well would count
        // the label twice: any rung within two label-heights of the frame would be reported short, and a bar chart
        // would extend its axis past its last numbered tick for room it already has.
        if (beyond(here, limit)) shortfallPx = Math.max(shortfallPx, Math.abs(here - limit));
        const ink = a.label ? lift + (onX ? fs * 0.62 * a.label.length : fs * LABEL_INK) : 0;
        spread.push({ c1, c2, edge: here + sign * ink });
      }
    }
  }
  // The warning is not written here. This runs before the caller decides whether it can widen
  // the axis and try again, so it cannot know why the room never came. A pinned axis is only one
  // reason: on a paired dot nothing is pinned, the axis is widened, and the stack can still not
  // fit because many long category labels leave the plot narrow. A user told to "clear the axis
  // maximum" would go looking for a maximum that was never set. The caller knows the real
  // reason; it writes the sentence.
  return { shortfallPx, clamped };
}

/**
 * Widen the value axis so an auto-placed significance stack fits, and say by how much.
 *
 * Why this exists. `significanceHeadroom()` reserves room for a bracket stack, but it is wired
 * into one builder family only — box/violin/scatter/raincloud. Without this step every other chart
 * reserves nothing, so the placer would push the brackets into the data, clamp them at the frame and
 * ask the user to raise the axis maximum by hand — often with only two or three brackets, and on
 * scree and volcano with a single one. The graph must make the space for those brackets, and make
 * it cleanly so it does not spoil the design.
 *
 * Threading the reservation through every builder would repeat the same logic in each of them and let
 * the copies drift apart. This does it once,
 * at the choke point, from the pixels the placer actually measured — so it is exact rather than an
 * estimate, and a chart that already fits is not touched at all.
 *
 * The extra room is exactly the shortfall the stack asked for, in
 * pixels, converted through this axis's own scale. Nothing is padded "just in case": a figure with
 * one bracket gains one bracket's worth of headroom, and the data keeps every pixel it had.
 *
 * Returns the new max, or null to leave the figure alone:
 *  - the user pinned the axis maximum → theirs wins, and the caller's warning says so;
 *  - the shortfall is a large fraction of the plot → refuse rather than flatten the data to a
 *    stripe, which is the failure mode `significanceHeadroom`'s own 34% cap exists to avoid.
 *
 * A reversed axis is never passed in: "away from the data" is its other end, so the caller skips
 * the widening there.
 */
function widenForBrackets(ax: AxisScene, shortfallPx: number, pinnedMax: number | undefined): number | null {
  if (!(shortfallPx > 0) || pinnedMax !== undefined) return null;
  const [d0, d1] = ax.domain;
  const span = Math.abs(ax.range[1] - ax.range[0]);
  if (!(span > 0) || !Number.isFinite(d0) || !Number.isFinite(d1) || d1 <= d0) return null;
  // Refuse to squeeze the data into less than two thirds of the panel.
  const frac = shortfallPx / span;
  if (!(frac > 0) || frac > 0.34) return null;
  // Grow the domain so the same data occupies `span - shortfallPx` pixels: the drawing keeps its
  // proportions and the new room appears above it, rather than everything being rescaled.
  const grow = span / (span - shortfallPx);
  /*
   * And it must survive `nice()`. The axis rounds its domain to sensible tick values, so a
   * request for 1% more is rounded straight back to the existing maximum and the retry
   * achieves nothing (a request for +1.1% can be rounded away on every retry, where +10% fits
   * at once). So the step is floored at half a major
   * tick, the smallest increment the axis cannot round away.
   *
   * This is the only place the result is not exactly the measured shortfall, and it is a floor,
   * not padding: a chart that needs more than half a tick gets exactly what it needs.
   */
  const majors = ax.ticks.filter((t) => !t.minor).map((t) => t.value);
  const tick = majors.length >= 2 ? Math.abs(majors[1]! - majors[0]!) : 0;
  if (isLog(ax.type) && d0 > 0) {
    const l0 = Math.log10(d0);
    return 10 ** (l0 + (Math.log10(d1) - l0) * grow);
  }
  const wanted = d0 + (d1 - d0) * grow;
  return Math.max(wanted, d1 + tick * 0.2);
}

/** Translate every coordinate pair of a generated path. Ours are all absolute M/L/Q
 *  commands over `x,y` pairs, so offsetting each pair moves the whole shape. */
/** Re-pin a bracket's two leg ends (the path's first and last points) to absolute value-axis
 *  pixels after the rail moved — see `AnnotationScene.legEnds`. */
function pinLegEnds(d: string, ends: { v1: number; v2: number }, onX: boolean): string {
  const pts = [...d.matchAll(/(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/g)];
  if (pts.length < 2) return d;
  const first = pts[0]!;
  const last = pts[pts.length - 1]!;
  const rep = (m: RegExpMatchArray, v: number): string => (onX ? `${v},${m[2]}` : `${m[1]},${v}`);
  // Replace the last occurrence first so the first match's index stays valid.
  let out = d.slice(0, last.index!) + rep(last, ends.v2) + d.slice(last.index! + last[0].length);
  out = out.slice(0, first.index!) + rep(first, ends.v1) + out.slice(first.index! + first[0].length);
  return out;
}

function shiftPathBy(d: string, dx: number, dy: number): string {
  return d.replace(/(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/g, (_m, x: string, y: string) => `${Number(x) + dx},${Number(y) + dy}`);
}

/**
 * Build the significance-threshold legend string from a plot's brackets: the
 * canonical star→cut-point mapping, restricted to the tiers actually reached by
 * the brackets' p-values. Only for the `stars` display (numeric/threshold show
 * the p inline). Returns undefined when off / no qualifying brackets.
 */
/**
 * The default size of a significance symbol (★ / ** / p = …) above a bracket.
 *
 * Multiplier over the legend font, not a fixed px, so it follows the preset like everything else.
 * 1.4 because a star or asterisk is optically small — thin strokes, with ink about four-fifths of an em
 * tall — and the legend font is usually smaller than the tick labels (12 px against 20 px in the default
 * preset). At the legend size itself, the annotation that should read first would be among the smallest
 * text on the graph.
 */
export const SIGNIFICANCE_LABEL_SCALE = 1.4;

/**
 * Give every significance-bracket label with no explicit size its default size, in one pass at
 * the choke point (so it holds for every kind that draws brackets and runs before `placeAutoBrackets`,
 * which stacks by measured label height and makes room for it). A size the user set — per
 * bracket (`size`) or plot-wide (`significance.labelSize`) — already arrived as `fontSize`
 * from the builder and is left exactly as it is; only the unsized default changes.
 */
function sizeSignificanceLabels(scene: PlotScene): void {
  const size = Math.round(scene.fonts.legend.size * SIGNIFICANCE_LABEL_SCALE);
  for (const a of scene.annotations) {
    if (a.kind === "bracket" && a.label && a.fontSize == null) a.fontSize = size;
  }
}

function significanceLegend(plot: Plot, drawn: AnnotationScene[]): string | undefined {
  const sig = plot.significance;
  if (!sig?.legend) return undefined;
  /**
   * Only brackets that reached the drawing count. Reading `plot.annotations` directly would
   * produce a key on a kind that accepts a bracket and then drops it (every axis-less chart —
   * `fractionalAnnotations` refuses them with "a bracket endpoint is not a category on this
   * chart"). And since the band is reserved at this choke point for every kind
   * (`scene.height += …` below) while only the main figure path draws the caption, on
   * pie, treemap, heatmap, corrmatrix, alluvial, network, radar, parallel and scatter3d,
   * switching the key on would make the figure 22px taller and draw nothing in the space.
   *
   * Matching by id against the resolved annotations handles both, including for kinds added
   * later: a kind that cannot place brackets gets no key, with no list to update. Same rule as
   * everywhere else here — "it was accepted" is not "it reached the drawing".
   */
  const drawnBrackets = new Set(drawn.filter((a) => a.kind === "bracket").map((a) => a.id));
  // A custom ladder is symbolic whatever the display says, so gate on "not numeric"
  // rather than "is stars" — otherwise a user’s own symbols never get a key.
  const display = sig.display ?? "stars";
  if (display === "numeric") return undefined;
  const ladder = resolveThresholds(sig.thresholds, display);
  const used = new Set<string>();
  for (const a of plot.annotations ?? []) {
    if (a.kind === "bracket" && drawnBrackets.has(a.id) && typeof a.p === "number" && Number.isFinite(a.p)) {
      // The rung the p actually reached — read through the same resolver the label uses,
      // so a bracket whose text was overridden still contributes its statistical tier.
      const rung = ladder.find((t) => a.p! < t.p);
      if (rung) used.add(rung.symbol);
    }
  }
  const parts = ladder
    .filter((t) => used.has(t.symbol))
    .sort((a, b) => b.p - a.p) // loosest first — "* p<0.05; ** p<0.01 …"
    // A symbol that already spells its cut-off is its own key: the `threshold` display
    // (and the "Cut-offs" symbol family) print "p<0.05", and glossing that would produce
    // "p<0.05 p<0.05" — a key that explains a thing with itself.
    .map((t) => (/p\s*[<≤]/i.test(t.symbol) ? t.symbol : `${t.symbol} p<${t.p}`));
  // Each entry is a separate fact. Spaces alone run them together into one string at a
  // glance, so the default punctuates them; the separator itself is a setting because
  // house styles differ (";", ",", "  ·  ", or a plain run of spaces).
  const sep = sig.legendSeparator ?? "; ";
  return parts.length ? parts.join(sep) : undefined;
}

/**
 * An image panel: a picture occupying the whole scene.
 *
 * Deliberately data-free — it never reads the table, so a project can hold a micrograph,
 * blot or schematic beside its graphs without inventing data for it. The axes are stubs
 * (hidden, unit domain) because [[PlotScene]] requires them; nothing reads them.
 *
 * The picture fills the plot rect, which is the whole scene minus any explicit plotPad and
 * the heading band, so an image panel lines up with its sibling graphs' outer footprint.
 */
function buildImageScene(plot: Plot, options: BuildPlotSceneOptions = {}): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const measure = options.measure ?? ((t: string, size: number) => t.length * size * 0.6);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotRect = {
    x: pad.l,
    y: topPad,
    width: Math.max(1, width - pad.l - pad.r),
    height: Math.max(1, height - topPad - pad.b),
  };
  const stub = (): AxisScene => ({ type: "linear", domain: [0, 1], range: [0, 1], ticks: [], title: "", hidden: true });
  void measure;
  return {
    width,
    height,
    plot: plotRect,
    x: stub(),
    y: stub(),
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: [],
    legendLayout: NO_LEGEND,
    annotations: [], // an image panel is deliberately data-free; the Inspector does not offer annotations on it
    fonts,
    kind: "image",
    title: heading.title,
    subtitle: heading.subtitle,
    // Required by PlotScene but meaningless without axes — no grid, no frame, no labels.
    grid: { show: false, color: null, width: 0, dash: null, minor: false },
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    axisLabels: { x: "", y: "" },
    warnings: plot.image?.src ? [] : ["This image panel has no picture yet."],
    image: {
      src: plot.image?.src ?? "",
      // "contain" never crops or stretches — see the warning on Plot.image.
      fit: plot.image?.fit ?? "contain",
      ...(plot.image?.alt ? { alt: plot.image.alt } : {}),
      ...(plot.image?.rotate ? { rotate: plot.image.rotate } : {}),
      ...(plot.image?.crop ? { crop: plot.image.crop } : {}),
      ...(plot.image?.naturalWidth ? { naturalWidth: plot.image.naturalWidth } : {}),
      ...(plot.image?.naturalHeight ? { naturalHeight: plot.image.naturalHeight } : {}),
    },
  };
}

/**
 * Equal aspect — one data unit draws the same number of pixels on X as on Y.
 *
 * The knob is `plot.equalAspect`. What it changes is a domain, never the plot box: one axis is
 * re-ranged about its own centre until the two scales match (`planEqualAspect`), then rebuilt as
 * an exact range — `nice()` would round the change straight back off. Re-sizing the box instead
 * would fight the figure layout, the panel grid and the axis-length control.
 *
 * `xFixed` / `yFixed` = the user has said what that axis shows: a hand-typed min/max, or the
 * pan/zoom window they are looking through. At rest neither is fixed and the tighter axis only
 * ever grows, so no point is cropped. While the user is zoomed, the windowed axis is fixed and
 * the other one follows it — growing or shrinking — because a 1:1 map that stops being 1:1 on
 * zooming in is the distortion this option exists to remove.
 *
 * Three refusals, each reported in `warnings` rather than dropped:
 *   • a log / probit axis has no constant units-per-pixel to equalise;
 *   • nor does an axis with breaks — its pixel scale changes at every cut;
 *   • and when both axes are pinned there is nothing left to move.
 */
function applyEqualAspect(args: {
  on: boolean;
  xType: ScaleType;
  yType: ScaleType;
  xb: BuiltScale;
  yb: BuiltScale;
  xRange: [number, number];
  yRange: [number, number];
  /** The user pinned this axis — a hand-typed range, or the pan/zoom window in force. */
  xFixed: boolean;
  yFixed: boolean;
  gridDensity: number;
  xFmt?: TickFormat | undefined;
  yFmt?: TickFormat | undefined;
  xSpacing?: TickSpacing | undefined;
  ySpacing?: TickSpacing | undefined;
  warnings: string[];
}): { xb: BuiltScale; yb: BuiltScale } {
  const { xb, yb } = args;
  if (!args.on) return { xb, yb };
  if (args.xType !== "linear" || args.yType !== "linear") {
    args.warnings.push(
      "Equal aspect needs two linear axes: a log or probability scale has no constant number of units per pixel to match.",
    );
    return { xb, yb };
  }
  if (args.xSpacing?.breaks?.length || args.ySpacing?.breaks?.length) {
    args.warnings.push(
      "Equal aspect was not applied: an axis with breaks (cuts) changes its pixel scale at every cut, so there is no single scale to share.",
    );
    return { xb, yb };
  }
  const xPx = Math.abs(args.xRange[1] - args.xRange[0]);
  const yPx = Math.abs(args.yRange[1] - args.yRange[0]);
  const plan = planEqualAspect(
    { domain: xb.domain, px: xPx, fixed: args.xFixed },
    { domain: yb.domain, px: yPx, fixed: args.yFixed },
  );
  if (plan.kind === "blocked") {
    args.warnings.push(plan.reason);
    return { xb, yb };
  }
  if (plan.kind === "already") return { xb, yb };
  return plan.axis === "x"
    ? { xb: buildScale("linear", plan.domain, args.xRange, args.gridDensity, true, args.xFmt, args.xSpacing), yb }
    : { xb, yb: buildScale("linear", plan.domain, args.yRange, args.gridDensity, true, args.yFmt, args.ySpacing) };
}

function buildPlotSceneInner(
  table: DataTable,
  plot: Plot,
  options: BuildPlotSceneOptions = {},
): PlotScene {
  // An image panel is a picture, not a chart: no data mapping, no axes, no legend. It is
  // dispatched first precisely because it must not touch the table at all.
  if (plot.kind === "image") return buildImageScene(plot, options);
  // Survival (Kaplan-Meier) charts plot analysis-supplied step curves (time vs
  // survival), not table columns — their own continuous-XY builder.
  if (plot.kind === "survival") return buildSurvivalScene(table, plot, options);
  // ROC curves (from a ROC analysis) plot sensitivity vs 1−specificity on the unit square.
  if (plot.kind === "roc") return buildRocScene(table, plot, options);
  // GWAS QQ: observed vs expected −log10(p) on a square, a y = x line + the inflation λ.
  if (plot.kind === "qq") return buildQQScene(table, plot, options);
  // GWAS Manhattan: −log10(p) along the genome (chromosomes end to end), a scatter with a
  // chromosome-ruler X axis, alternating per-chromosome colour, and threshold reference lines.
  if (plot.kind === "manhattan") return buildManhattanScene(table, plot, options);
  // Categorical charts (bar/box/violin/scatter/before-after/pie/heatmap) use a
  // band X axis (or no axes) — separate builders. XY + area share the continuous path.
  const kind0 = plot.kind ?? "xy";
  if (kind0 !== "xy" && kind0 !== "area" && kind0 !== "bubble" && kind0 !== "volcano") return buildCategoricalScene(table, plot, options);
  const isArea = kind0 === "area";
  const isBubble = kind0 === "bubble";
  // An error ribbon follows a curve, so it belongs to the two kinds that draw one. A volcano
  // and a bubble chart are point clouds: joining their error reaches left-to-right would draw
  // a shape that means nothing. The control is hidden there and the builder warns.
  const bandKinds = kind0 === "xy" || kind0 === "area";
  // Volcano: X = log2 fold-change, Y = −log10 p. Each point is coloured by which
  // significance zone it falls in: up-regulated (right wing) = green, down-regulated
  // (left wing) = red, not-significant (centre) = grey.
  const isVolcano = kind0 === "volcano";
  const vcFc = plot.volcano?.fcThreshold ?? 1;
  const vcP = plot.volcano?.pThreshold ?? 1.301; // −log10(0.05)
  // Significance-zone colours are editable (Inspector → Volcano); fall back to the
  // classic up=green / down=red / ns=grey palette.
  const vcUp = plot.volcano?.upColor ?? "#1a9850";
  const vcDown = plot.volcano?.downColor ?? "#d62728";
  const vcNs = plot.volcano?.nsColor ?? "#b3b6bd";
  const volcanoColor = (dx: number, dy: number): string =>
    Math.abs(dx) >= vcFc && dy >= vcP ? (dx > 0 ? vcUp : vcDown) : vcNs;

  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);

  const xCol = xColumn(table);
  const xErrCol = xErrorColumn(table);
  // A column of names (gene IDs, sample names) is not a series: it has no value to place, so drawn as one it would
  // show nothing and still take a legend row with a dot. It stays in the table for the point labels and Find &
  // highlight that read it.
  const allDatasets = xyFamilyDatasets(table);
  // Bubble: 1st Y dataset = vertical position, 2nd = each point's size. Only the
  // position series is drawn; its marks are sized from the size column (4–22 px).
  const sizeDs = isBubble && allDatasets.length >= 2 ? allDatasets[1] : undefined;
  const datasets = sizeDs ? allDatasets.slice(0, 1) : allDatasets;
  const sizeByRow = new Map<NodeId, number>();
  if (sizeDs) {
    for (const row of table.rows) {
      const v = toNumber(row.cells[sizeDs.replicates[0] ?? sizeDs.id]);
      if (Number.isFinite(v)) sizeByRow.set(row.id, v);
    }
  }
  const sizeExt = sizeByRow.size ? extent([...sizeByRow.values()]) : ([0, 1] as [number, number]);
  const minR = plot.bubble?.minRadius ?? 4;
  const maxR = plot.bubble?.maxRadius ?? 22;
  const radiusForValue = (v: number): number => {
    if (sizeExt[1] === sizeExt[0]) return (minR + maxR) / 2;
    // Area-proportional: the bubble area (not its radius) tracks the value linearly, so
    // equal value-increments map to equal area-increments — the perceptually accurate
    // encoding (a "2× value" bubble reads as 2× the ink, not 4×). Interpolate in area
    // space between the min/max radii: r = √(minR² + t·(maxR² − minR²)).
    const t = (v - sizeExt[0]) / (sizeExt[1] - sizeExt[0]);
    return Math.sqrt(Math.max(0, minR * minR + t * (maxR * maxR - minR * minR)));
  };
  const radiusFor = (rowId: NodeId): number => {
    const v = sizeByRow.get(rowId);
    if (v === undefined) return (minR + maxR) / 2;
    return radiusForValue(v);
  };
  // Bubble size-legend reference spheres: explicit values (user-chosen) or auto
  // (max · mid · min), each at its matching radius × the legend display scale.
  const showSizeLegend = isBubble && !!sizeDs && sizeByRow.size > 0 && (plot.bubble?.showSizeLegend ?? true);
  const sizeLegendScale = Math.max(0.3, Math.min(5, plot.bubble?.sizeLegendScale ?? 1));
  const bubbleRefItems: { radius: number; label: string }[] = (() => {
    if (!showSizeLegend) return [];
    const fmtSize = (v: number): string => String(Number(v.toFixed(Math.abs(v) >= 100 ? 0 : 2)));
    const lo = sizeExt[0];
    const hi = sizeExt[1];
    const explicit = plot.bubble?.sizeLegendValues?.filter((v) => Number.isFinite(v));
    const vals = explicit && explicit.length ? [...explicit].sort((a, b) => b - a) : lo === hi ? [lo] : [hi, (lo + hi) / 2, lo];
    return vals.map((v) => ({ radius: Math.max(1, radiusForValue(v) * sizeLegendScale), label: fmtSize(v) }));
  })();
  const bubbleLegendMaxR = bubbleRefItems.length ? Math.max(...bubbleRefItems.map((i) => i.radius)) : 0;
  if (isBubble && !sizeDs) warnings.push("Bubble chart needs a 2nd Y column for the bubble size.");
  const xLabel = xCol?.name ?? "X";

  // The error-bar type chosen for a dataset. Default SD when the dataset carries
  // spread (≥2 replicates or summary columns), asymmetric when it was entered with
  // explicit lower/upper limits, else none (a single value per point has no spread).
  const errorTypeFor = (ds: Dataset, hasSpread: boolean): ErrorBarType =>
    resolveErrorType(ds, plot.seriesStyles?.[ds.id]?.errorBars ?? defaultErrorType(ds, hasSpread));

  // Gather one plotted point per (dataset, row): the dataset mean + its error
  // reach. Replicate datasets summarize their side-by-side y columns; summary
  // datasets read pre-computed mean + error column(s) directly (all entry formats).
  const rawBySeries: RawPoint[][] = datasets.map((ds) => {
    const summaryMode = isSummaryDataset(ds);
    const hasSpread = summaryMode || ds.replicates.length >= 2;
    const type = errorTypeFor(ds, hasSpread);
    warnUndrawableError(ds, type, summaryMode, warnings);
    const points: RawPoint[] = [];
    if (!xCol) return points;
    table.rows.forEach((row, i) => {
      const dx = toNumber(row.cells[xCol.id]);
      if (!Number.isFinite(dx)) return;
      let ep;
      if (summaryMode) {
        ep = summaryPointForRow(ds, row, type);
      } else {
        const values = ds.replicates.map((id) => toNumber(row.cells[id]));
        ep = errorPoint(summarize(values), type, ERROR_CONF);
      }
      if (!Number.isFinite(ep.center)) return;
      const xe = xErrCol ? toNumber(row.cells[xErrCol.id]) : NaN;
      points.push({
        rowId: row.id,
        rowNumber: i + 1,
        dx,
        dy: ep.center,
        low: ep.low,
        high: ep.high,
        hasError: ep.hasError,
        n: ep.n,
        ...(Number.isFinite(xe) && xe > 0 ? { xErr: xe } : {}),
      });
    });
    return points;
  });

  // Bump chart (`plot.plotRanks`, line/xy only): replace each series' Y at a stage with its
  // rank among the series there (largest = rank 1). A one-click rankings-over-stages chart on
  // the ordinary line renderer — no new kind. `rankValues` (core) does the tie-aware per-stage
  // ranking; error reach is cleared (a rank has no spread). The Y axis becomes a reversed
  // integer "Rank" axis just below (via the synthetic ySpec).
  const rankAxis = !!plot.plotRanks && kind0 === "xy";
  let rankMax = 1;
  if (rankAxis) {
    const byRow = new Map<string, RawPoint[]>();
    rawBySeries.forEach((pts) => pts.forEach((p) => {
      const arr = byRow.get(p.rowId) ?? [];
      arr.push(p);
      byRow.set(p.rowId, arr);
    }));
    for (const pts of byRow.values()) {
      const ranks = rankValues(pts.map((p) => p.dy));
      pts.forEach((p, i) => {
        const r = ranks[i]!;
        p.dy = r; p.low = r; p.high = r; p.hasError = false;
      });
      rankMax = Math.max(rankMax, pts.length);
    }
  }

  const totalFinite = rawBySeries.reduce((n, s) => n + s.length, 0);
  if (table.rows.length > 0 && datasets.length > 0 && totalFinite === 0) {
    warnings.push("No finite data points to plot.");
  }

  // --- Per-axis settings: resolve scale type, manual range, reversed, number format.
  const xSpec: AxisSpec = plot.xAxis ?? {};
  // A bump chart's Y is a reversed integer rank axis (rank 1 at the top): synthesise the spec
  // so ticks land on whole ranks 1…N and a user title still wins. Its data mapping, clicking
  // (→ Axis panel) and title editing/dragging all come free from the ordinary Y-axis pipeline.
  const ySpec: AxisSpec = rankAxis
    ? { ...(plot.yAxis ?? {}), scale: "linear", reversed: true, min: 0.5, max: rankMax + 0.5, majorStep: 1, title: plot.yAxis?.title ?? "Rank" }
    : plot.yAxis ?? {};
  const xFmt = tickFormat(xSpec);
  // Date / elapsed-time X columns format their numeric ticks as ISO dates / h:mm:ss.
  xFmt.columnType = xCol?.type;
  const yFmt = tickFormat(ySpec);
  // A bump chart's X is the stage (round, season, year): whole steps only, unless the user set a
  // step — a nice-tick 0.5 would put "1.5, 2.5 …" on an integer axis. Applied
  // only when every stage value is an integer, so a fractional stage axis keeps its own ticks.
  const stagesAreIntegers = rankAxis && rawBySeries.every((pts) => pts.every((p) => Number.isInteger(p.dx)));
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep ?? (stagesAreIntegers ? 1 : undefined), minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const xRev = xSpec.reversed ?? false;
  const yRev = ySpec.reversed ?? false;

  // --- Second value axis (Y2): a right-hand axis fed by the series the user pinned
  // to it (SeriesStyle.axis === "y2"). Only drawn when ≥1 series is assigned. The
  // spread band + fit overlay stay on the primary (left) Y.
  const y2Spec: AxisSpec = plot.y2Axis ?? {};
  const y2Fmt = tickFormat(y2Spec);
  const y2Spacing: TickSpacing = { majorStep: y2Spec.majorStep, minorCount: y2Spec.minorCount, breaks: y2Spec.breaks };
  const y2Rev = y2Spec.reversed ?? false;
  const onY2 = (id: NodeId): boolean => plot.seriesStyles?.[id]?.axis === "y2";
  const y2Idx = datasets.map((d, i) => (onY2(d.id) ? i : -1)).filter((i) => i >= 0);
  const hasY2 = y2Idx.length > 0;
  const y2Type: ScaleType = y2Spec.scale ?? "linear";
  // --- Third value axis (Y3): stacks outside Y2 on the right; fed by series pinned via
  // SeriesStyle.axis === "y3". Mirrors the Y2 pipeline. ---
  const y3Spec: AxisSpec = plot.y3Axis ?? {};
  const y3Fmt = tickFormat(y3Spec);
  const y3Spacing: TickSpacing = { majorStep: y3Spec.majorStep, minorCount: y3Spec.minorCount, breaks: y3Spec.breaks };
  const y3Rev = y3Spec.reversed ?? false;
  const onY3 = (id: NodeId): boolean => plot.seriesStyles?.[id]?.axis === "y3";
  const y3Idx = datasets.map((d, i) => (onY3(d.id) ? i : -1)).filter((i) => i >= 0);
  const hasY3 = y3Idx.length > 0;
  const y3Type: ScaleType = y3Spec.scale ?? "linear";

  // Resolve scale types over all series (include error reach so bars autoscale
  // in), then drop points a log axis can't show.
  const allX = rawBySeries.flatMap((s) => s.map((p) => p.dx));
  const allY = rawBySeries.flatMap((s) =>
    s.flatMap((p) => (p.hasError ? [p.dy, p.low, p.high] : [p.dy])),
  );
  // Precedence: explicit option → AxisSpec → the plot-level xScale / yScale fallback → auto.
  let xType: ScaleType = options.xScale ?? xSpec.scale ?? plot.xScale ?? suggestScale(allX);
  let yType: ScaleType = options.yScale ?? ySpec.scale ?? plot.yScale ?? suggestScale(allY);
  // A date / elapsed X axis is inherently linear time — never let auto-scale pick log
  // off the large day/second storage numbers.
  if (xCol?.type === "date" || xCol?.type === "elapsed") xType = "linear";
  // Ranks are small whole numbers — a log Y would be meaningless (and can't hold the 0.5 pad).
  if (rankAxis) yType = "linear";
  // A volcano's axes are already log-transformed data (log2 fold-change, −log10 p),
  // so both axes are linear — never inherit a log scale from the previous chart kind
  // (and log2 FC is signed, so a log scale would drop the down-regulated half).
  if (isVolcano) {
    // Report it. Forcing linear here is right, but doing it silently would make the Axis tab's
    // scale control look broken on this kind. The reason is worth telling the user: both axes
    // already hold logged data.
    warnLogUnsupported(
      plot,
      "a volcano plot",
      warnings,
      "both axes already hold log-transformed data (log2 fold change, −log10 p), and log2 fold change is signed.",
    );
    xType = "linear";
    yType = "linear";
  }
  // A stream area centres its bands on the axis, so every y position is an offset that
  // crosses zero — a log value axis cannot draw that. Forced linear, said out loud.
  if (isArea && (plot.areaStack ?? "none") === "stream" && isLog(yType)) {
    warnLogUnsupported(plot, "a stream (centred) area", warnings, "the bands are centred on the axis, so their positions are offsets that cross zero.");
    yType = "linear";
  }

  const filterLog = (pts: RawPoint[]) =>
    pts.filter((p) => (!isLog(xType) || p.dx > 0) && (!isLog(yType) || p.dy > 0));

  let usableBySeries = rawBySeries.map(filterLog);
  const dropped = totalFinite - usableBySeries.reduce((n, s) => n + s.length, 0);
  if (dropped > 0) {
    warnings.push(`${dropped} point(s) dropped: not positive on a log scale.`);
  }
  // If a forced log axis killed all data, fall back to linear so something draws.
  if (usableBySeries.every((s) => s.length === 0) && totalFinite > 0) {
    xType = isLog(xType) ? "linear" : xType;
    yType = isLog(yType) ? "linear" : yType;
    usableBySeries = rawBySeries.map(filterLog);
  }

  // --- Area stacking (overlay / stacked / 100%). Align series by X and
  // accumulate, so each series sits on the running total below it. Percent mode
  // first totals every X column, then scales each contribution to 100%. The
  // result is a per-point {base, top} in data space; non-stacked keeps {0, dy}.
  const stackMode: AreaStack = isArea ? plot.areaStack ?? "none" : "none";
  const stacked = stackMode !== "none";
  const stackBySeries: Array<Array<{ base: number; top: number }>> = usableBySeries.map((s) =>
    s.map((p) => ({ base: 0, top: p.dy })),
  );
  if (stacked) {
    const totalByX = new Map<number, number>();
    if (stackMode === "percent") {
      for (const s of usableBySeries) for (const p of s) {
        totalByX.set(p.dx, (totalByX.get(p.dx) ?? 0) + Math.max(0, p.dy));
      }
    }
    const cum = new Map<number, number>();
    usableBySeries.forEach((s, si) => {
      s.forEach((p, pi) => {
        const val =
          stackMode === "percent"
            ? ((total) => (total > 0 ? (Math.max(0, p.dy) / total) * 100 : 0))(totalByX.get(p.dx) ?? 0)
            : p.dy;
        const base = cum.get(p.dx) ?? 0;
        const top = base + val;
        cum.set(p.dx, top);
        stackBySeries[si]![pi] = { base, top };
      });
    });
    // "stream" (streamgraph / ThemeRiver): the same cumulative stack, centred — every X
    // column shifts down by half its total, so the flow sits symmetric about the axis and
    // only band thickness carries the value. `cum` holds each column's final total here.
    if (stackMode === "stream") {
      usableBySeries.forEach((s, si) => {
        s.forEach((p, pi) => {
          const off = (cum.get(p.dx) ?? 0) / 2;
          const st = stackBySeries[si]![pi]!;
          stackBySeries[si]![pi] = { base: st.base - off, top: st.top - off };
        });
      });
    }
  }

  // --- Cross-series spread band: at each shared
  // X, summarise the spread across series (range / mean±SD / mean±SEM / IQR) into a
  // {low, high, mean} ribbon. Hidden series still feed it, so a few drawn curves can
  // sit inside the population band. Skipped when stacking (the two don't mix).
  const spreadSpec = plot.spread;
  const spreadMode: SpreadMode = !stacked ? spreadSpec?.mode ?? "none" : "none";
  const spreadK = spreadSpec?.k ?? 1;
  const bandPts: Array<{ dx: number; low: number; high: number; mean: number; median: number }> = [];
  if (spreadMode !== "none") {
    const byX = new Map<number, number[]>();
    for (const s of usableBySeries) for (const p of s) {
      (byX.get(p.dx) ?? byX.set(p.dx, []).get(p.dx)!).push(p.dy);
    }
    for (const dx of [...byX.keys()].sort((a, b) => a - b)) {
      const vals = byX.get(dx)!.filter(Number.isFinite).sort((a, b) => a - b);
      if (vals.length === 0) continue;
      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
      const median = quantileSorted(vals, 0.5);
      let low: number, high: number;
      if (spreadMode === "range") {
        low = vals[0]!; high = vals[vals.length - 1]!;
      } else if (spreadMode === "iqr") {
        low = quantileSorted(vals, 0.25); high = quantileSorted(vals, 0.75);
      } else {
        const variance = vals.length > 1 ? vals.reduce((a, b) => a + (b - mean) ** 2, 0) / (vals.length - 1) : 0;
        const sd = Math.sqrt(variance);
        const reach = spreadK * (spreadMode === "sem" ? sd / Math.sqrt(vals.length) : sd);
        low = mean - reach; high = mean + reach;
      }
      bandPts.push({ dx, low, high, mean, median });
    }
  }

  const usableX = usableBySeries.flatMap((s) =>
    s.flatMap((p) => {
      const xs = p.xErr !== undefined ? [p.dx, p.dx - p.xErr, p.dx + p.xErr] : [p.dx];
      return isLog(xType) ? xs.filter((v) => v > 0) : xs;
    }),
  );
  // Stacked area autoscales to the cumulative tops (+ a 0 baseline); otherwise the
  // raw point/error values (and any spread band) drive the Y domain.
  // The primary (left) Y domain ignores any series routed to the second axis — Y2
  // series autoscale the right axis independently (usableY2, below).
  const usableY = stacked
    ? // Stream bands live half below the axis, so their BASES set the domain floor; the
      // other stacked modes keep tops-only (bases ⊂ [0, top]) so saved graphs are unmoved.
      stackMode === "stream"
      ? [0, ...stackBySeries.flatMap((s) => s.flatMap((p) => [p.base, p.top]))]
      : [0, ...stackBySeries.flatMap((s) => s.map((p) => p.top))]
    : [
        ...usableBySeries.flatMap((s, si) =>
          y2Idx.includes(si) || y3Idx.includes(si)
            ? []
            : s.flatMap((p) => {
                const ys = p.hasError ? [p.dy, p.low, p.high] : [p.dy];
                return isLog(yType) ? ys.filter((v) => v > 0) : ys;
              }),
        ),
        ...bandPts.flatMap((b) => (isLog(yType) ? [b.low, b.high].filter((v) => v > 0) : [b.low, b.high])),
      ];
  // Auto-fit (nice) domain, then apply any manual min/max the user pinned. A
  // pan/zoom window (options.*Domain) overrides everything and is drawn exactly.
  const autoDomX = buildScale(xType, extent(usableX), [0, 1], plot.grid?.density ?? 6, false, xFmt).domain;
  const autoDomY = buildScale(yType, extent(usableY), [0, 1], plot.grid?.density ?? 6, false, yFmt).domain;
  const restX = applyRange(xSpec, autoDomX);
  const restY = applyRange(ySpec, autoDomY);
  const zoomX = options.xDomain != null;
  // A bump chart's Y is a fixed rank axis — it is not zoomable (see the scene's `zoomable`),
  // so a Y window is ignored and the pinned rank range (restY) always wins.
  const zoomY = !rankAxis && options.yDomain != null;
  const manualX = xSpec.min != null || xSpec.max != null;
  const manualY = ySpec.min != null || ySpec.max != null;
  const xData = options.xDomain ?? restX;
  const yData = rankAxis ? restY : (options.yDomain ?? restY);
  // `exact` keeps the bounds as-is (no nice()/power-snap) for a zoom window or a
  // manual range; the breathing-room pad is also skipped so the bounds are precise.
  const exactX = zoomX || manualX;
  const exactY = zoomY || manualY;

  // y-axis title: what the user typed, else the single dataset's name; blank when many
  // → the legend names them instead.
  //
  // Note: `ySpec.title` first. Without it a title the user typed would be drawn (the axis carries
  // it) but `marginLeft` below would reserve no band for it, so on a 2-series chart the placement
  // clamp would bind and the title land on top of the tick numbers. Every other builder reads the
  // spec first.
  // Note: the volcano's title is fixed ("−log₁₀ p", set on the axis below) whatever the sheet
  // holds, so the band must be reserved whatever the sheet holds: with a gene column beside
  // the two numbers the auto-label would be blank, no band would be reserved, and the title
  // would print over the tick numbers on a typical volcano sheet.
  const yLabel = ySpec.title ?? (isVolcano ? "−log₁₀ p" : datasets.length === 1 ? datasets[0]!.name : "");
  const seriesColorFor = (id: NodeId, i: number): string =>
    plot.seriesStyles?.[id]?.color ?? seriesColor(i, palette);
  // Hidden series drop out of the legend (they only feed the spread band/average).
  // A data-driven colour/symbol binding replaces the per-series legend with the
  // value→colour/shape mapping (so a single scatter coloured by a variable legends it).
  // A colour/symbol binding legends the values, and that is a legend worth having on any of
  // these kinds — including bubble, whose per-series row below is refused.
  const ddLegend = dataDrivenLegend(plot, datasets, table, palette);
  const rawLegend: LegendEntry[] =
    ddLegend ??
    // A bubble chart has no per-series legend. It resolves exactly one series — the 2nd Y
    // column becomes the size, not a second series — so the only row it could ever produce is
    // that series' name, which is character-for-character the Y axis title beside it (e.g. a
    // "Life expectancy" legend that only repeats the Y axis). Colour the points from a column and `ddLegend`
    // above gives a legend that says something; otherwise there is nothing to name.
    (isBubble
      ? []
      : // A volcano's points are coloured by significance zone, not by series — so a single-series
    // swatch (default palette colour) matches none of the marks. When the user explicitly enables
    // the legend, emit a zone legend (up/down/ns) instead; otherwise stay hidden so the default
    // plot geometry is unchanged.
    (isVolcano
      // The up/down/ns zone key is opt-in via Legend ▸ Show — off leaves the default plot geometry
      // unchanged. New volcanoes turn it on through KIND_HOUSE_DEFAULTS['volcano']
      // (presets.ts) so a freshly created / gallery volcano names its zones,
      // while a bare volcano with no legend set stays keyless — a builder test guards both.
      ? (plot.legend?.show === true
          ? [
              // Note: a zone is not a series — all three colour the one `-log10 p` series, so there
              // is no per-zone object to select. Their colours are `volcano.upColor` /
              // `downColor` / `nsColor`, and those controls live inside the **Chart type**
              // section (volcano has no section of its own). Selecting a "Volcano" section
              // would pin a section that does not exist and blank the whole panel.
              { label: "Up-regulated", color: vcUp, select: { as: "section" as const, id: "Chart type" } },
              { label: "Down-regulated", color: vcDown, select: { as: "section" as const, id: "Chart type" } },
              { label: "Not significant", color: vcNs, select: { as: "section" as const, id: "Chart type" } },
            ]
          : [])
      : datasets
          // An area's key should match the plotted fill (style.fillColor ?? series colour), not the
          // line/marker colour — else a distinct fillColor isn't reflected in the legend.
          .map((d, i) => ({ label: d.name, color: isArea ? (plot.seriesStyles?.[d.id]?.fillColor ?? seriesColorFor(d.id, i)) : seriesColorFor(d.id, i), hidden: plot.seriesStyles?.[d.id]?.hidden ?? false, id: d.id }))
          .filter((e) => !e.hidden)
          // The id travels rather than being re-derived from the label: an area/XY series
          // whose name happens to differ from its column's would otherwise be unclickable in
          // exactly the way ROC was.
          // An area drawn without point markers (a stream graph) shows only its fill: keyed as a block in that fill,
          // edgeless as the fill is drawn, not as a line stub that names only its top edge. Decided here, before the
          // legend is laid out, because a block row is sized differently from a line row.
          .map(({ label, color, id }) => ({ label, color, select: { as: "series" as const, id }, ...(isArea && plot.seriesStyles?.[id]?.symbol === "none" ? { swatch: "bar" as const, line: false, outline: "transparent" } : {}) }))));
  // Say the refusal out loud, but only to someone who asked for the legend — an untouched
  // bubble chart already draws none (one series, so "auto" hides it) and must stay quiet.
  if (isBubble && !ddLegend && plot.legend?.show === true) {
    warnings.push("A bubble chart draws one series, so a legend could only repeat the Y axis title. Colour the points from a column for a legend that names something.");
  }

  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const leg = resolveLegend(plot, [...rawLegend, ...fitLegendRows(plot, palette)], measure, fonts.legend.size, width);
  const legend = leg.entries;
  // Continuous colour-by-column → a colour-scale bar in the right margin (replaces the
  // per-series legend, which is suppressed above). Geometry is finalised after plot dims.
  const cbarInfo = continuousColorInfo(plot, datasets, table, palette);
  const CB_BAR_W = 14;
  const colorbarMargin = cbarInfo ? CB_BAR_W + 60 : 0; // bar + min/max labels + rotated title

  // Pass 1: probe scales (unit range) just to size the margins from tick labels.

  const yProbe = buildScale(yType, yData, [0, 1], gridDensity, exactY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.yTick.size, measure, plot.yAxis);

  // Y2 home domain (from only its series) + a probe to size the right margin.
  const usableY2 = y2Idx.flatMap((i) =>
    usableBySeries[i]!.flatMap((p) => {
      const ys = p.hasError ? [p.dy, p.low, p.high] : [p.dy];
      return isLog(y2Type) ? ys.filter((v) => v > 0) : ys;
    }),
  );
  const restY2 = hasY2 ? applyRange(y2Spec, buildScale(y2Type, extent(usableY2), [0, 1], gridDensity, false, y2Fmt).domain) : ([0, 1] as [number, number]);
  const manualY2 = y2Spec.min != null || y2Spec.max != null;
  const exactY2 = manualY2;
  const y2Probe = hasY2 ? buildScale(y2Type, restY2, [0, 1], gridDensity, exactY2, y2Fmt, y2Spacing) : null;
  const y2LabelWidth = y2Probe ? yTickLabelsWidth(y2Probe.ticks, fonts.y2Tick.size, measure, y2Spec) : 0;
  const y2Label = y2Spec.title ?? (y2Idx.length === 1 ? datasets[y2Idx[0]!]!.name : "");

  // Y3 home domain + probe (mirrors Y2), for the axis stacked outside Y2.
  const usableY3 = y3Idx.flatMap((i) =>
    usableBySeries[i]!.flatMap((p) => {
      const ys = p.hasError ? [p.dy, p.low, p.high] : [p.dy];
      return isLog(y3Type) ? ys.filter((v) => v > 0) : ys;
    }),
  );
  const restY3 = hasY3 ? applyRange(y3Spec, buildScale(y3Type, extent(usableY3), [0, 1], gridDensity, false, y3Fmt).domain) : ([0, 1] as [number, number]);
  const manualY3 = y3Spec.min != null || y3Spec.max != null;
  const exactY3 = manualY3;
  const y3Probe = hasY3 ? buildScale(y3Type, restY3, [0, 1], gridDensity, exactY3, y3Fmt, y3Spacing) : null;
  const y3LabelWidth = y3Probe ? yTickLabelsWidth(y3Probe.ticks, fonts.y3Tick.size, measure, y3Spec) : 0;
  const y3Label = y3Spec.title ?? (y3Idx.length === 1 ? datasets[y3Idx[0]!]!.name : "");

  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (yLabel ? textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6) : 4) + pad.l;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  const y2Margin = hasY2
    ? y2LabelWidth + DEFAULTS.tickLen + (plot.y2Axis?.tickLabelGap ?? 8) + (y2Label ? rightTitleBand(plot.y2Axis, y2Label, (fonts.y2AxisTitle ?? fonts.yAxisTitle).size, plot.y2Axis?.titleGap ?? 6, measure, width) : 4)
    : 0;
  // Y3 stacks a fixed gap outside Y2 (or the plot edge when no Y2): its labels + title
  // extend further right, so it adds a second right-margin band beyond Y2's.
  const Y3_GAP = 16;
  const y3Margin = hasY3
    ? Y3_GAP + y3LabelWidth + DEFAULTS.tickLen + (plot.y3Axis?.tickLabelGap ?? 8) + (y3Label ? rightTitleBand(plot.y3Axis, y3Label, (fonts.y3AxisTitle ?? fonts.yAxisTitle).size, plot.y3Axis?.titleGap ?? 6, measure, width) : 4)
    : 0;
  // Reserve room on the right for the bubble size legend. Same three-part measurement as the
  // PCA depth legend: the block is as wide as the wider of (spheres + value labels) and its
  // title, which here defaults to the size column's name and can be long ("Population").
  const bubbleTitle = plot.bubble?.sizeLegendTitle ?? sizeDs?.name ?? "";
  const bubbleMargin = showSizeLegend
    ? 16 + Math.max(
        bubbleLegendMaxR * 2 + 8 + Math.max(0, ...bubbleRefItems.map((i) => measure(i.label, fonts.legend.size))),
        measure(bubbleTitle, fonts.legend.size),
      ) + 10
    : 0;
  // Everything in the right margin is drawn from the plot's right edge, so each block must
  // know what sits before it. A legend placed at `plotRight + gap` regardless of what else
  // occupies that band would sit on the Y2 tick labels, on the colour bar, and on the size
  // legend.
  //
  // One order, stated once, with the room already reserved in marginRight:
  //   [plot] [Y2] [Y3] [colour bar] [size legend] [series legend]
  // Each block's offset is the sum of the ones before it.
  const sizeLegendInset = 16 + y2Margin + y3Margin + colorbarMargin;
  const legendPad = y2Margin + y3Margin + colorbarMargin + bubbleMargin;
  if (legendPad) leg.layout = { ...leg.layout, outsidePad: legendPad };
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r + y2Margin + y3Margin + bubbleMargin + colorbarMargin;

  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  // Colour-scale bar geometry: a thin vertical gradient just outside the plot (beyond any
  // Y2/Y3/bubble bands), spanning the plot height; 6 stops sampled from the ramp.
  let colorbar: PlotScene["colorbar"];
  if (cbarInfo) {
    // Order is [plot][Y2][Y3][colour bar][size legend] — the colour bar comes before the size
    // legend, so it must not add `bubbleMargin`: adding it would place the bar inside the size
    // legend's slot, and the two would overlap whenever a bubble chart has both.
    const barX = plotX + plotW + y2Margin + y3Margin + 14;
    // Through `barStops`, not six samples of the paint: a stepped ramp has to draw as a
    // staircase or the key blends across class edges the marks do not have.
    const stops = ramps.barStops(cbarInfo.ramp, cbarInfo.base, "#1a1a1a", cbarInfo.rev, cbarInfo.shape);
    colorbar = {
      bar: { x: barX, y: plotY, w: CB_BAR_W, h: plotH },
      stops,
      min: cbarInfo.lo,
      max: cbarInfo.hi,
      ...(cbarInfo.title ? { title: cbarInfo.title } : {}),
    };
  }

  // Breathing room: inset the data mapping by ~the largest marker so edge points
  // (e.g. the left-most / "zero" point) sit just inside the frame instead of on
  // the axis where the plot-area clip would truncate them. Only in the auto-fit
  // view — a zoom window keeps the exact full-width mapping so pan/zoom stays
  // precise.
  // A bubble's marks are sized by data (up to bubble.maxRadius, default 22, user-settable
  // to 60) — far larger than the 4px series symbolSize default — so the auto-fit inset must
  // reserve the bubble's max radius, else an edge bubble's outer ring overflows the plot rect.
  const bubbleR = plot.kind === "bubble" ? (plot.bubble?.maxRadius ?? 22) : 0;
  const maxSym = Math.max(4, bubbleR, ...datasets.map((d) => plot.seriesStyles?.[d.id]?.symbolSize ?? 4));
  const symPad = Math.ceil(maxSym * 1.4 + 2);
  const padX = exactX ? 0 : Math.min(plotW * 0.1, symPad);
  const padY = exactY ? 0 : Math.min(plotH * 0.1, symPad);

  // Pass 2: real pixel scales (y inverted), with the auto-fit inset applied.
  // A reversed axis flips the pixel range so the domain maps high→low on screen.
  const xRange: [number, number] = xRev ? [plotW - padX, padX] : [padX, plotW - padX];
  const yRange: [number, number] = yRev ? [padY, plotH - padY] : [plotH - padY, padY];
  const xbRaw = buildScale(xType, xData, xRange, gridDensity, exactX, xFmt, xSpacing);
  const ybRaw = buildScale(yType, yData, yRange, gridDensity, exactY, yFmt, ySpacing);
  // 1:1 scale (opt-in): widen whichever axis is packed too tightly so a data unit is the
  // same length on both. Runs on the final pixel ranges, so a zoom window is equalised too.
  const { xb, yb } = applyEqualAspect({
    on: plot.equalAspect === true,
    xType, yType, xb: xbRaw, yb: ybRaw, xRange, yRange,
    xFixed: exactX, yFixed: exactY,
    gridDensity, xFmt, yFmt, xSpacing, ySpacing, warnings,
  });
  // Y2 shares the plot height (same pixel range) but maps its own domain.
  const y2Range: [number, number] = y2Rev ? [padY, plotH - padY] : [plotH - padY, padY];
  const y2b = hasY2 ? buildScale(y2Type, restY2, y2Range, gridDensity, exactY2, y2Fmt, y2Spacing) : null;
  const mapY2 = (v: number): number | undefined => {
    if (!y2b || !Number.isFinite(v) || (isLog(y2Type) && v <= 0)) return undefined;
    return plotY + y2b.scale(v);
  };
  // Y3 — same plot height, its own domain (mirrors Y2).
  const y3Range: [number, number] = y3Rev ? [padY, plotH - padY] : [plotH - padY, padY];
  const y3b = hasY3 ? buildScale(y3Type, restY3, y3Range, gridDensity, exactY3, y3Fmt, y3Spacing) : null;
  const mapY3 = (v: number): number | undefined => {
    if (!y3b || !Number.isFinite(v) || (isLog(y3Type) && v <= 0)) return undefined;
    return plotY + y3b.scale(v);
  };

  // Domain reported to the renderer reads in screen order (value at the low-pixel
  // end first), so reversed axes flip it — keeps pan/zoom's domain↔pixel math right.
  const xDomainOut: [number, number] = xRev ? [xb.domain[1], xb.domain[0]] : xb.domain;
  const yDomainOut: [number, number] = yRev ? [yb.domain[1], yb.domain[0]] : yb.domain;

  // The natural "home" domain (the rest state ignoring any zoom window) — the
  // soft-lock target the renderer snaps back to. With a manual range, home = that
  // range; otherwise the auto-fit domain.
  const homeX = zoomX
    ? buildScale(xType, restX, [0, 1], gridDensity, manualX, xFmt).domain
    : xb.domain;
  const homeY = zoomY
    ? buildScale(yType, restY, [0, 1], gridDensity, manualY, yFmt).domain
    : yb.domain;
  const autoX: [number, number] = xRev ? [homeX[1], homeX[0]] : homeX;
  const autoY: [number, number] = yRev ? [homeY[1], homeY[0]] : homeY;

  // Map a data-space Y to a pixel Y, or undefined if a log axis can't show it
  // (e.g. a lower error end at/below zero) — the renderer omits that bar half.
  const mapY = (v: number): number | undefined => {
    if (!Number.isFinite(v) || (isLog(yType) && v <= 0)) return undefined;
    return plotY + yb.scale(v);
  };
  // Map a data-space X to a pixel X, or undefined if a log axis can't show it
  // (an X-error end at/below zero) — the renderer omits that horizontal cap.
  const mapX = (v: number): number | undefined => {
    if (!Number.isFinite(v) || (isLog(xType) && v <= 0)) return undefined;
    return plotX + xb.scale(v);
  };

  const series: SeriesScene[] = datasets.map((ds, i) => {
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(i, palette);
    // XY "Render as": `plotAs` is the coarse choice and beats
    // Connect / Shape — "points" drops the line, "line" drops the markers, "area" fills this
    // series down to the baseline (an ordinary xy plot; the whole-plot `area` kind is unchanged).
    const plotAsXY = kind0 === "xy" ? style?.plotAs : undefined;
    const renderArea = plotAsXY === "area" && !isLog(yType);
    if (plotAsXY === "area" && isLog(yType)) {
      warnings.push(`“${ds.name}” cannot be drawn as an area on a log Y axis — there is no zero baseline to fill down to. It is drawn as markers + line; use a linear Y axis for the fill.`);
    }
    const connect = isBubble || isVolcano || plotAsXY === "points" ? "none" : style?.connect ?? "straight";
    const lineWidth = style?.lineWidth ?? 2;
    const errorDir: ErrorBarDir = style?.errorDir ?? "both";
    // Route this series through its assigned value axis: the primary Y (left), or a
    // right axis when pinned via SeriesStyle.axis "y2"/"y3" and that scale exists.
    const seriesOnY3 = hasY3 && onY3(ds.id) && y3b != null;
    const seriesOnY2 = !seriesOnY3 && hasY2 && onY2(ds.id) && y2b != null;
    const yS = seriesOnY3 ? y3b! : seriesOnY2 ? y2b! : yb;
    const yScaleType = seriesOnY3 ? y3Type : seriesOnY2 ? y2Type : yType;
    const localMapY = seriesOnY3 ? mapY3 : seriesOnY2 ? mapY2 : mapY;
    // Per-series baseline pixel for the area fill: the configured baseline value
    // (default 0) for overlaid areas, the cumulative stack base for a stacked/percent
    // area (keyed per mark). Clamped into the plot rect.
    const baseVal = plot.areaBaseline ?? 0;
    const baseY = isLog(yScaleType)
      ? plotY + plotH
      : Math.min(plotY + plotH, Math.max(plotY, plotY + yS.scale(baseVal)));
    const areaBaseOf = new Map<MarkScene, number>();
    const marks: MarkScene[] = usableBySeries[i]!.map((p, pi) => {
      const st = stackBySeries[i]![pi]!;
      const mark: MarkScene = {
        rowId: p.rowId,
        rowNumber: p.rowNumber,
        dx: p.dx,
        dy: p.dy,
        cx: plotX + xb.scale(p.dx),
        cy: plotY + yS.scale(stacked ? st.top : p.dy),
        n: p.n,
      };
      areaBaseOf.set(mark, stacked ? plotY + yS.scale(st.base) : baseY);
      if (p.hasError) {
        const lo = localMapY(p.low);
        const hi = localMapY(p.high);
        if (lo !== undefined) mark.errLowCy = lo;
        if (hi !== undefined) mark.errHighCy = hi;
        mark.errLow = p.low;
        mark.errHigh = p.high;
      }
      // Shared X-error subcolumn → symmetric horizontal caps (coexist with Y error).
      if (p.xErr !== undefined) {
        const xlo = mapX(p.dx - p.xErr);
        const xhi = mapX(p.dx + p.xErr);
        if (xlo !== undefined) mark.errLowCx = xlo;
        if (xhi !== undefined) mark.errHighCx = xhi;
      }
      if (isBubble) mark.symbolSize = radiusFor(p.rowId);
      if (isVolcano) {
        const zone = volcanoColor(p.dx, p.dy);
        mark.fill = zone;
        // The whole point of a volcano is the significance colour, so it must stay
        // prominent. Two-tone is honoured — derived from this point's zone colour
        // (light interior + dark edge). Every other mode renders a solid zone fill,
        // so an open/flat-interior preset can't flatten every point to one grey.
        if (style?.symbolFill === "twotone") {
          mark.symbolFill = "open"; // two-tone renders as open + a light interior
          mark.symbolFillColor = twoToneFill(zone, style?.twoToneTint);
          mark.symbolOutline = twoToneContour(zone, style?.twoToneShade);
        } else {
          mark.symbolFill = "solid";
          mark.symbolOutline = "var(--bg)";
        }
      }
      return mark;
    });
    const ordered = [...marks].sort((a, b) => a.dx - b.dx);
    const lineCurve = curveFor(connect, style?.lineTension ?? 0.5);
    const linePath =
      connect === "none"
        ? ""
        : (d3line<MarkScene>().x((m) => m.cx).y((m) => m.cy).curve(lineCurve)(ordered) ?? "");
    // Area fill from the line down to its baseline — value-0 for overlaid areas,
    // the cumulative stack base (per mark) for a stacked/percent area.
    const areaPath =
      (isArea || renderArea) && ordered.length > 0
        ? d3area<MarkScene>().x((m) => m.cx).y0((m) => areaBaseOf.get(m) ?? baseY).y1((m) => m.cy).curve(lineCurve)(ordered) ?? ""
        : "";
    /**
     * The error interval as a ribbon: errors / SEM shown as a background
     * shade around the curve.
     *
     * It is the same interval the T-bars draw — `errLowCy`/`errHighCy`, already computed
     * above from the chosen error type — so this changes only how it is rendered and can
     * never make the graph claim something different. That is also why it needs no new
     * statistic: `errorDisplay` is presentation, `errorBars` is the science.
     *
     * Note: only points that have an interval join the ribbon, and it needs at least two of them
     * to be a shape at all. A series with one replicate per row gets no band, and the builder
     * says so rather than drawing a degenerate sliver.
     */
    // Note: `ribbonPts`, not `bandPts` — the outer scope already has a `bandPts`, and it is the
    // cross-series spread band (a different feature entirely). Shadowing it here would compile
    // but invite confusing the two.
    const ribbonPts = ordered.filter((m) => m.errLowCy !== undefined && m.errHighCy !== undefined);
    const errDisplay = style?.errorDisplay ?? "bars";
    const wantBand = bandKinds && (errDisplay === "band" || errDisplay === "both");
    const bandPath =
      wantBand && ribbonPts.length >= 2
        ? d3area<MarkScene>().x((m) => m.cx).y0((m) => m.errLowCy!).y1((m) => m.errHighCy!).curve(lineCurve)(ribbonPts) ?? ""
        : "";
    if (wantBand && ribbonPts.length < 2) {
      warnings.push(
        `“${ds.name}” cannot draw an error band — it needs at least two points carrying an error interval. Set Error bars → Type, and enter replicates (or a mean + SD/SEM) for at least two rows.`,
      );
    }
    if (!bandKinds && (style?.errorDisplay === "band" || style?.errorDisplay === "both")) {
      warnings.push("An error band follows a curve, so it is drawn on XY and area charts only — this chart shows the interval as error bars.");
    }
    return {
      id: ds.id,
      name: ds.name,
      color,
      // Linked (default) → the line follows the marker/series colour; unlinked → its own.
      lineColor: style?.linkLineColor === false ? (style?.lineColor ?? color) : color,
      linePath,
      ...(areaPath ? { areaPath } : {}),
      ...(bandPath
        ? {
            bandPath,
            bandOpacity: Math.max(0, Math.min(1, style?.bandOpacity ?? 0.18)),
            ...(style?.bandColor ? { bandColor: style.bandColor } : {}),
            ...(style?.bandEdgeWidth
              ? {
                  bandEdgeWidth: Math.max(0, Math.min(8, style.bandEdgeWidth)),
                  bandEdgeColor: style.bandEdgeColor ?? style.bandColor ?? color,
                  bandEdgeDash: dashArray(style.bandEdgeDash ?? "solid", Math.max(0.5, style.bandEdgeWidth)),
                }
              : {}),
          }
        : {}),
      // Note: only when the ribbon was actually drawn. Standing the bars down for a band that
      // could not be built (one point, no error type) would erase the interval altogether.
      ...(bandPath && errDisplay === "band" ? { showErrorBars: false } : {}),
      symbol: plotAsXY === "line" ? "none" : style?.symbol ?? "circle",
      symbolSize: style?.symbolSize ?? 4,
      // Volcano markers get their fill mode per point (above), derived from each
      // point's significance colour — so the series-level resolve is just a fallback.
      ...resolveSymbol(style, color),
      borderWidth: style?.borderWidth ?? 1.5,
      lineWidth,
      dash: dashArray(style?.lineDash ?? "solid", lineWidth),
      errorCaps: style?.errorCaps ?? true,
      errorDir,
      ...seriesExtras(style, color, lineWidth, style?.symbolSize ?? 4, isArea ? (stacked ? 0.85 : 0.22) : renderArea ? 0.22 : 1),
      marks,
    };
  })
    // Hidden series are computed (so they feed the spread band/average) but not drawn.
    .filter((s) => !plot.seriesStyles?.[s.id]?.hidden);

  // Spread-band ribbon + dotted mean line, mapped to pixel space. The ribbon traces
  // the high edge left→right then the low edge back (a closed area); the mean is a
  // separate dotted line that can carry a direct end label (e.g. "League avg").
  let spreadBand: PlotScene["spreadBand"];
  if (spreadMode !== "none" && bandPts.length >= 2) {
    const inDom = bandPts.filter((b) => !isLog(yType) || (b.low > 0 && b.high > 0));
    if (inDom.length >= 2) {
      const bandPath =
        d3area<{ dx: number; low: number; high: number }>()
          .x((b) => plotX + xb.scale(b.dx))
          .y0((b) => plotY + yb.scale(b.low))
          .y1((b) => plotY + yb.scale(b.high))
          .curve(curveLinear)(inDom) ?? "";
      const showMean = spreadSpec?.showMean ?? false;
      const meanColor = spreadSpec?.meanColor ?? "#7a7a85";
      // The centre line traces whichever statistic `spread.center` names: the mean (default)
      // or the median. The scene's mean* fields hold that centre line, whichever statistic
      // it shows.
      const centerOf = (b: { mean: number; median: number }): number => (spreadSpec?.center === "median" ? b.median : b.mean);
      const meanPath = showMean
        ? d3line<{ dx: number; mean: number; median: number }>()
            .x((b) => plotX + xb.scale(b.dx))
            .y((b) => plotY + yb.scale(centerOf(b)))
            .curve(curveLinear)(inDom) ?? ""
        : "";
      const last = inDom[inDom.length - 1]!;
      const meanLabel =
        showMean && spreadSpec?.meanLabel
          ? { text: spreadSpec.meanLabel, x: plotX + xb.scale(last.dx), y: plotY + yb.scale(centerOf(last)), color: meanColor }
          : undefined;
      if (bandPath) {
        spreadBand = {
          bandPath,
          color: spreadSpec?.color ?? "#9aa0aa",
          opacity: spreadSpec?.opacity ?? 0.15,
          ...(meanPath ? { meanPath, meanColor } : {}),
          ...(meanLabel ? { meanLabel } : {}),
        };
      }
    }
  }

  // Overlaid fitted curve(s) (from a curve-fit / regression / global-fit analysis),
  // mapped to pixel space. Points outside the (possibly log) domain or non-finite are
  // dropped. Shared by the single `fit` and the per-dataset global `fits`.
  // `own` = a per-series fit's dragged offsets (`plot.fitsOffsets[i]`, possibly empty); absent =
  // the single fit, which reads `plot.fitLabelOffset` / `plot.fitParams.offset`. A `fits[]` entry
  // never borrows the single fit's offsets, so dragging one label moves only that label.
  // Each built fit's curve in pixels, kept beside the scene (the scene carries only the SVG
  // path string) so the potency-label router below can keep a label off every curve.
  const fitPixels = new WeakMap<object, [number, number][]>();
  const buildFit = (pf: NonNullable<Plot["fit"]>, fallbackColor: string, own?: { label?: { dx: number; dy: number } | undefined; params?: { dx: number; dy: number } | undefined }): PlotScene["fit"] => {
    const labelOff = own ? own.label : plot.fitLabelOffset;
    const pts = pf.points.filter(
      ([fx, fy]) =>
        Number.isFinite(fx) && Number.isFinite(fy) && (!isLog(xType) || fx > 0) && (!isLog(yType) || fy > 0),
    );
    if (pts.length < 2) return undefined;
    const path =
      d3line<[number, number]>()
        .x((p) => plotX + xb.scale(p[0]))
        .y((p) => plotY + yb.scale(p[1]))
        .curve(curveLinear)(pts) ?? "";
    if (!path) return undefined;
    const pix = pts.map(([fx, fy]) => [plotX + xb.scale(fx), plotY + yb.scale(fy)] as [number, number]);
    // Filled-area path for a [x, yLow, yHigh] band, clipped to the (log) domain.
    const bandPath = (band: Array<[number, number, number]> | undefined): string | undefined => {
      if (!band || band.length < 2) return undefined;
      const b = band.filter(
        ([bx, bl, bh]) =>
          Number.isFinite(bx) && Number.isFinite(bl) && Number.isFinite(bh) &&
          (!isLog(xType) || bx > 0) && (!isLog(yType) || (bl > 0 && bh > 0)),
      );
      if (b.length < 2) return undefined;
      return (
        d3area<[number, number, number]>()
          .x((p) => plotX + xb.scale(p[0]))
          .y0((p) => plotY + yb.scale(p[1]))
          .y1((p) => plotY + yb.scale(p[2]))
          .curve(curveLinear)(b) ?? undefined
      );
    };
    // Potency crosshair (EC50/IC50): a vertical drop-line to the X-axis marks the
    // dose, a short segment to the Y-axis marks the response, plus a value label.
    // Only drawn when the dose sits within the plotted X range.
    // It is a reference line (registry id `fit-marker`), so it resolves like every other:
    // its own `refLineStyles` entry → the all-lines `refLine` → its default dashed look
    // (`"4 3"`, so an untouched graph is byte-identical). Hidden by either
    // `refLine.show:false` or `refLineHidden["fit-marker"]`.
    let marker: NonNullable<PlotScene["fit"]>["marker"];
    // The look: `plot.fitStyle` (colour · thickness · dashes · opacity · band fills · show),
    // every field defaulting to the standard look, so a graph with no
    // fitStyle draws the standard curve. `fitStyle.color` overrides the fit's own colour; the
    // bands and the marker follow the curve's colour unless given their own.
    const fs = plot.fitStyle ?? {};
    const { color, width, dash: curveDash } = fitCurveLook(plot, pf, fallbackColor);
    const rlOpts = resolveRefLine(plot, "fit-marker", { color, dash: "4 3", width: 1.5 });
    if (pf.marker && rlOpts.show) {
      const mx = pf.marker.x;
      const my = pf.marker.y;
      const okX = Number.isFinite(mx) && (!isLog(xType) || mx > 0);
      const okY = Number.isFinite(my) && (!isLog(yType) || my > 0);
      if (okX && okY) {
        const vx = plotX + xb.scale(mx);
        const cy = plotY + yb.scale(my);
        if (vx >= plotX - 0.5 && vx <= plotX + plotW + 0.5 && Number.isFinite(cy)) {
          // A label the user dragged keeps its default spot: its drag is stored relative to it.
          const flipLeft = !labelOff && vx + 5 + measure(pf.marker.label, plot.refLineLabelFonts?.["fit-marker"]?.size ?? fonts.tick.size) > plotX + plotW;
          marker = {
            vx,
            cy,
            baseY: plotY + plotH,
            // A drop-only marker (a Tm) has no response line: it starts where it ends.
            leftX: pf.marker.dropOnly ? vx : plotX,
            label: pf.marker.label,
            // Above-right of the crosshair - unless the label would cross the plot's right edge (into the legend): then it
            // hangs to the left of the crosshair, inside the plot (`flipLeft`).
            labelX: flipLeft ? vx - 5 : vx + 5,
            labelY: cy - 5,
            // Persisted free-drag offset so the potency/equation label can be moved off the
            // crosshair; the crosshair itself stays anchored to the dose/response.
            ...(labelOff ? { labelOffset: labelOff } : {}),
            // The label's own font (`refLineLabelFonts["fit-marker"]`: clicking it opens its size),
            // over the tick font, but not its colour: the label takes its curve's colour unless it has one of its own.
            // Written only when set; without it the label is drawn in the tick font, in the curve's colour.
            ...(plot.refLineLabelFonts?.["fit-marker"] ? { labelFont: { ...fonts.tick, color: null, ...Object.fromEntries(Object.entries(plot.refLineLabelFonts["fit-marker"]).filter(([, v]) => v !== undefined)) } as ResolvedFont } : {}),
            color: rlOpts.color ?? color,
            width: rlOpts.width,
            dash: rlOpts.dash,
            ...(flipLeft ? { labelAnchor: "end" as const } : {}),
          };
        }
      }
    }
    // Fitted-parameter block: a right-aligned stack in the plot's bottom-right, where fitted
    // parameters are usually printed. Inset from the axes so it
    // never sits on them, and freely draggable from there.
    let params: NonNullable<PlotScene["fit"]>["params"];
    const pOpts = plot.fitParams;
    if (pf.params && pf.params.length > 0 && pOpts?.show !== false) {
      const size = pOpts?.size ?? fonts.legend.size;
      const align = pOpts?.align ?? "right";
      const inset = 8;
      const off = own ? own.params : pOpts?.offset;
      // Per-line choices belong to the single fit (a per-series fit's block is drawn whole).
      // Each line is keyed by its statistic, or by position for a fit saved without keys.
      const lineOpts = own ? undefined : pOpts?.lines;
      const items: { key: string; text: string; offset?: { dx: number; dy: number } }[] = [];
      pf.params.forEach((fitted, k) => {
        const key = pf.paramKeys?.[k] ?? `#${k}`;
        const lo = lineOpts?.[key];
        // Default: the first six lines show, the rest wait in the Fit parameters list.
        if (!(lo?.show ?? k < 6)) return;
        const typed = lo?.text;
        // The user's text is kept through a re-fit, but a changed fitted value must be said out loud.
        if (typed !== undefined && lo?.fittedText !== undefined && lo.fittedText !== fitted) {
          warnings.push(`The fitted value of ${key} changed since its line was edited (now "${fitted}"). Your text is kept; Fit parameters > Reset puts the fitted value back.`);
        }
        items.push({ key, text: typed ?? fitted, ...(lo?.offset ? { offset: lo.offset } : {}) });
      });
      if (items.length > 0) {
        const baseX = align === "right" ? plotX + plotW - inset : plotX + inset;
        // Stack upward from the bottom edge so the last line clears the X axis.
        const baseY = plotY + plotH - inset - (items.length - 1) * size * 1.25;
        params = {
          lines: items.map((it) => it.text),
          items,
          together: own ? true : pOpts?.together === true,
          // The anchor stays unoffset and the drag delta rides alongside - same contract as
          // the potency label. Folding the offset in here would make each drag compound on
          // the last one instead of being absolute.
          x: baseX,
          y: baseY,
          size,
          anchor: align === "right" ? "end" : "start",
          ...(off ? { offset: off } : {}),
        };
      }
    }
    const ciPath = fs.ciShow === false ? undefined : bandPath(pf.confidenceBand);
    const piPath = fs.piShow === false ? undefined : bandPath(pf.predictionBand);
    const out: NonNullable<PlotScene["fit"]> = {
      path,
      ...(params ? { params } : {}),
      color,
      label: pf.label,
      showCurve: fs.show !== false,
      width,
      dash: curveDash,
      opacity: fs.opacity ?? 1,
      ciColor: fs.ciColor ?? color,
      ciOpacity: fs.ciOpacity ?? 0.18,
      piColor: fs.piColor ?? color,
      piOpacity: fs.piOpacity ?? 0.08,
      ...(ciPath ? { confidenceBandPath: ciPath } : {}),
      ...(piPath ? { predictionBandPath: piPath } : {}),
      ...(marker ? { marker } : {}),
    };
    fitPixels.set(out, pix);
    return out;
  };
  /**
   * Potency labels are routed when a figure has more than one. At a fixed offset above-right of
   * its crosshair, each "EC50 = …" of two fits with nearby potencies would print touching the
   * other. With two or more, every label the user has not dragged goes through the shared
   * placer — clear of both crosshairs, both curves, the data marks, the parameter blocks and each
   * other; a dragged label stays where it was put and is an obstacle to the rest. A single fit
   * keeps the fixed above-right spot.
   */
  const routePotencyLabels = (built: NonNullable<PlotScene["fit"]>[]): void => {
    const keyed = built.filter((f) => f.marker);
    if (keyed.length < 2) return;
    const fontPx = (plot.refLineLabelFonts?.["fit-marker"]?.size) ?? fonts.tick.size;
    const obstacles: LabelRect[] = [];
    for (const f of built) {
      const pix = fitPixels.get(f) ?? [];
      for (let k = 1; k < pix.length; k++) {
        obstacles.push(...segmentObstacles(pix[k - 1]![0], pix[k - 1]![1], pix[k]![0], pix[k]![1], Math.max(3, f.width * 2)));
      }
      const m = f.marker;
      if (m) obstacles.push(...segmentObstacles(m.vx, m.cy, m.vx, m.baseY, 3), ...segmentObstacles(m.leftX, m.cy, m.vx, m.cy, 3));
      if (f.params) {
        const p = f.params;
        const w = Math.max(0, ...p.lines.map((l) => measure(l, p.size)));
        const h = (p.lines.length - 1) * p.size * 1.25 + p.size;
        obstacles.push({ x1: p.anchor === "end" ? p.x - w : p.x, y1: p.y - p.size, x2: p.anchor === "end" ? p.x : p.x + w, y2: p.y - p.size + h + p.size * 0.3 });
      }
    }
    for (const s of series) for (const mk of s.marks) obstacles.push(discObstacle(mk.cx, mk.cy, (mk.symbolSize ?? s.symbolSize ?? 4) + 1));
    const free = keyed.filter((f) => !f.marker!.labelOffset);
    for (const f of keyed) {
      const m = f.marker!;
      if (m.labelOffset) obstacles.push(placedBox({ x: m.labelX + m.labelOffset.dx, y: m.labelY + m.labelOffset.dy - fontPx * 0.34, anchor: m.labelAnchor ?? "start" }, m.label, fontPx, measure));
    }
    const placed = placeLabelsClear(
      free.map((f, i) => ({ id: String(i), text: f.marker!.label, anchorX: f.marker!.vx, anchorY: f.marker!.cy })),
      { fontPx, measure, bounds: { x1: plotX, y1: plotY, x2: plotX + plotW, y2: plotY + plotH }, obstacles },
    );
    let crowded = 0;
    free.forEach((f, i) => {
      const p = placed.get(String(i));
      if (!p) return;
      // The placer speaks in the text's vertical centre; the label is drawn from its baseline.
      f.marker = { ...f.marker!, labelX: p.x, labelY: p.y + fontPx * 0.34, labelAnchor: p.anchor };
      if (p.crowded) crowded++;
    });
    // Note: worded differently from the bracket / point-label warnings ("could not be placed clear of…"),
    // which `bracket-headroom.test` picks out by that phrase.
    if (crowded > 0) warnings.push(`${crowded} potency label${crowded === 1 ? " has" : "s have"} no clear spot at this size — the curves, the parameter blocks and the other labels take the room. Drag ${crowded === 1 ? "it" : "them"} where you want, or widen the figure.`);
  };

  let fit: PlotScene["fit"];
  if (plot.fit && plot.fit.points.length > 0) {
    // The preset's palette, not the default one: a curve must wear the colour its points wear
    // (under Grayscale, the default palette would leave the curves Okabe-Ito blue and orange).
    // The single fit takes the second colour, to stand apart from one series.
    fit = buildFit(plot.fit, seriesColor(1, palette));
  }
  // Per-dataset global-fit curves: each defaults to its series colour (by index).
  let fits: PlotScene["fits"];
  if (plot.fits && plot.fits.length > 0) {
    const built = plot.fits
      .map((pf, i) => buildFit(pf, seriesColor(i, palette), plot.fitsOffsets?.[String(i)] ?? {}))
      .filter((f): f is NonNullable<PlotScene["fit"]> => !!f);
    // Every block anchors at the same bottom-right corner, so two would overprint: stack them
    // upward, each wholly above the one placed before it.
    let top: number | undefined;
    for (const f of built) {
      if (!f.params) continue;
      if (top !== undefined) {
        const h = (f.params.lines.length - 1) * f.params.size * 1.25 + f.params.size + 8;
        f.params = { ...f.params, y: top - h };
      }
      top = f.params.y;
    }
    routePotencyLabels(built);
    if (built.length > 0) fits = built;
  }

  const xAxis: AxisScene = {
    type: xType,
    domain: xDomainOut,
    range: [plotX, plotX + plotW],
    // Blank labels that would collide horizontally (keep the tick mark), so no two
    // labels clash. Uses the injected text measurer.
    ticks: deOverlapX(
      xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })),
      measure,
      fonts.tick.size,
    ),
    title: xSpec.title ?? (isVolcano ? "log₂ fold change" : xLabel),
    ...axisLine(xSpec),
    ...(xb.breakMarks?.length ? { breakMarks: xb.breakMarks.map((p) => plotX + p), breakStyle: xSpec.breakStyle ?? "slash", segments: (xb.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotX + xb.scale(s.from), p1: plotX + xb.scale(s.to) })) } : {}),
  };
  const yAxis: AxisScene = {
    type: yType,
    domain: yDomainOut,
    range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: ySpec.title ?? (isVolcano ? "−log₁₀ p" : yLabel),
    ...axisLine(ySpec),
    ...(yb.breakMarks?.length ? { breakMarks: yb.breakMarks.map((p) => plotY + p), breakStyle: ySpec.breakStyle ?? "slash", segments: (yb.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotY + yb.scale(s.from), p1: plotY + yb.scale(s.to) })) } : {}),
  };
  // Title baseline sits just outside the Y2 tick labels (axis line → ticks → gap →
  // labels → titleGap → title), mirroring the left axis's relationship to its own
  // labels. This keeps it clear of the figure edge (no truncation) and of any
  // right-side legend (which lives further out, in DEFAULTS.marginRight + legend).
  const y2LabelsEnd = plotX + plotW + DEFAULTS.tickLen + (plot.y2Axis?.tickLabelGap ?? 8) + y2LabelWidth;
  const y2TitleX = y2LabelsEnd + (plot.y2Axis?.titleGap ?? 6) + (fonts.y2AxisTitle ?? fonts.yAxisTitle).size * 0.3;
  const y2Axis: AxisScene | undefined = y2b
    ? {
        type: y2Type,
        domain: y2Rev ? [y2b.domain[1], y2b.domain[0]] : y2b.domain,
        range: [plotY + plotH, plotY],
        ticks: y2b.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
        title: y2Label,
        titleX: y2TitleX,
        ...axisLine(y2Spec),
        ...(y2b.breakMarks?.length ? { breakMarks: y2b.breakMarks.map((p) => plotY + p), breakStyle: y2Spec.breakStyle ?? "slash", segments: (y2b.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotY + y2b.scale(s.from), p1: plotY + y2b.scale(s.to) })) } : {}),
      }
    : undefined;
  // Y3 draws outside Y2: its line sits `Y3_GAP` beyond Y2's outer edge (the plot right
  // edge + y2Margin); its ticks/labels/title extend further right still.
  const y3AxisX = plotX + plotW + y2Margin + Y3_GAP;
  const y3LabelsEnd = y3AxisX + DEFAULTS.tickLen + (plot.y3Axis?.tickLabelGap ?? 8) + y3LabelWidth;
  const y3TitleX = y3LabelsEnd + (plot.y3Axis?.titleGap ?? 6) + (fonts.y3AxisTitle ?? fonts.yAxisTitle).size * 0.3;
  const y3Axis: AxisScene | undefined = y3b
    ? {
        type: y3Type,
        domain: y3Rev ? [y3b.domain[1], y3b.domain[0]] : y3b.domain,
        range: [plotY + plotH, plotY],
        ticks: y3b.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
        title: y3Label,
        titleX: y3TitleX,
        axisX: y3AxisX,
        ...axisLine(y3Spec),
        ...(y3b.breakMarks?.length ? { breakMarks: y3b.breakMarks.map((p) => plotY + p), breakStyle: y3Spec.breakStyle ?? "slash", segments: (y3b.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotY + y3b.scale(s.from), p1: plotY + y3b.scale(s.to) })) } : {}),
      }
    : undefined;

  const mapXann = (v: number): number | undefined =>
    Number.isFinite(v) && (!isLog(xType) || v > 0) ? plotX + xb.scale(v) : undefined;
  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: mapXann, y: mapY, bracketX: mapXann },
    undefined,
    warnings,
  );

  // Line of identity (y = x): a reference line (registry id `identity`), opt-in via
  // `plot.showIdentity`, drawn on the plain XY graph only. It runs in data space through the
  // separate x/y scales — not corner-to-corner — so it is a true y = x even when the axes have
  // different ranges, and it is clipped to the range overlap [max(xmin,ymin), min(xmax,ymax)];
  // outside that the diagonal has no meaning, so it is skipped (with a warning) rather than
  // drawn misleadingly. Style / hide come from `refLine` / `refLineStyles` like every other.
  if (plot.showIdentity && (plot.kind ?? "xy") === "xy") {
    const idRl = resolveRefLine(plot, "identity", { dash: "dashed", width: 1 });
    if (idRl.show) {
      const lo = Math.max(xb.domain[0], yb.domain[0]);
      const hi = Math.min(xb.domain[1], yb.domain[1]);
      // y = x is a straight segment only when both axes share a scale type (both linear or
      // both log); on a mixed log/linear pair it is a curve, so a 2-point line would mislead.
      const sameScale = isLog(xType) === isLog(yType);
      const logOk = !isLog(xType) || lo > 0; // a log axis needs a positive low end
      if (hi > lo && sameScale && logOk) {
        annotations.push({
          id: "identity", kind: "line",
          x1: plotX + xb.scale(lo), y1: plotY + yb.scale(lo),
          x2: plotX + xb.scale(hi), y2: plotY + yb.scale(hi),
          color: idRl.color, dash: idRl.dash, width: idRl.width,
          ...(plot.refLineLabels?.["identity"] ? { label: plot.refLineLabels["identity"], labelX: plotX + xb.scale(hi), labelY: plotY + yb.scale(hi) - 3, labelAnchor: "end", labelOffset: plot.refLineLabelOffsets?.["identity"] ?? { dx: 0, dy: 0 } } : {}),
          locked: true, deletable: false,
        });
      } else if (hi <= lo) {
        warnings.push("Line of identity not drawn: the X and Y ranges don't overlap.");
      } else if (!sameScale) {
        warnings.push("Line of identity not drawn: the X and Y axes use different scales (one log, one linear).");
      }
    }
  }

  const ellipses = plot.ellipse?.show ? buildEllipses(plot, series) : [];

  // Bubble size legend: reference spheres → value labels, vertical on the right.
  // Its marker paint mirrors the plotted bubbles so it matches the graph exactly.
  const bs = series[0];
  const bubbleLegend = showSizeLegend && sizeDs
    ? {
        title: bubbleTitle,
        marker: {
          // The shape too: a preset's shape cycle or a hand-picked symbol reaches the marks, so
          // the key's spheres must wear it as well or they key nothing.
          symbol: bs?.symbol ?? "circle",
          color: bs?.color ?? seriesColor(0, palette),
          symbolFill: bs?.symbolFill ?? "solid",
          symbolFillColor: bs?.symbolFillColor,
          symbolOutline: bs?.symbolOutline ?? bs?.color ?? seriesColor(0, palette),
          symbolOpacity: bs?.symbolOpacity ?? 1,
          borderWidth: bs?.borderWidth ?? 1.5,
        },
        ...(plot.colorbarOffset ? { offset: plot.colorbarOffset } : {}),
        inset: sizeLegendInset,
        items: bubbleRefItems,
      }
    : undefined;

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis,
    y: yAxis,
    ...(y2Axis ? { y2: y2Axis } : {}),
    ...(y3Axis ? { y3: y3Axis } : {}),
    auto: { x: autoX, y: autoY },
    // Both axes are continuous values read straight off `options.xDomain`/`yDomain` above —
    // visual and data axis coincide, nothing transposes here. The exception is a bump chart: its
    // Y is a pinned integer rank axis (a zoom window there is ignored), so only X is zoomable.
    zoomable: rankAxis ? [{ visual: "x", key: "x" }] : [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series,
    ...(fit ? { fit } : {}),
    ...(fits ? { fits } : {}),
    ...(colorbar ? { colorbar } : {}),
    ...(spreadBand ? { spreadBand } : {}),
    ...(ellipses.length ? { ellipses } : {}),
    ...(bubbleLegend ? { bubbleLegend } : {}),
    legend,
    legendLayout: leg.layout,
    annotations,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: isVolcano ? (xSpec.title ?? "log₂ fold change") : xLabel, y: isVolcano ? (ySpec.title ?? "−log₁₀ p") : (yLabel || "Value") },
    kind: isArea ? "area" : isBubble ? "bubble" : isVolcano ? "volcano" : "xy",
    fonts,
    warnings,
  };
}

/**
 * Survival (Kaplan-Meier) scene: each `plot.survival` curve becomes a step line
 * (time → survival fraction). Continuous time X axis, [0,1] survival Y axis. No
 * marks/error bars — lines only, with a legend (one entry per group).
 */
function buildSurvivalScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a survival curve", warnings);
  const curves = plot.survival ?? [];

  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);

  const allTimes = curves.flatMap((c) => c.times).filter((v) => Number.isFinite(v));
  const tMax = allTimes.length ? Math.max(...allTimes) : 1;
  const xAuto: [number, number] = [0, tMax > 0 ? tMax : 1];
  const yAuto: [number, number] = [0, 1];
  const xLabel = xColumn(table)?.name ?? "Time";
  // Cumulative-incidence view plots 1 − S (the event rate, ascending) instead of the
  // survival fraction (descending). Both lie in [0,1], so the axis domain/scale are
  // unchanged — only the plotted value (via `yv`) and the axis title flip.
  const asInc = plot.survivalCumulativeIncidence === true;
  const yLabel = asInc ? "Cumulative incidence" : "Survival";
  const yv = (s: number): number => (asInc ? 1 - s : s);
  if (curves.length === 0) warnings.push("No survival curves to plot. Run Analyze ▸ Survival on the datasheet to draw them.");

  // Honour the Ticks (interval / minor) + Numbering (format) + Range (min/max) + Reversed axis
  // controls — the survival axes are built here by hand, so without TickSpacing/format/range/
  // reversed passed through, those Inspector controls would do nothing (as on any bespoke builder).
  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const xFmt = tickFormat(xSpec);
  const yFmt = tickFormat(ySpec);
  const xRev = xSpec.reversed ?? false;
  const yRev = ySpec.reversed ?? false;
  const wx = windowed(xSpec, xAuto, options.xDomain);
  const wy = windowed(ySpec, yAuto, options.yDomain);
  const manualX = wx.manual;
  const manualY = wy.manual;
  const xData: [number, number] = wx.data;
  const yData: [number, number] = wy.data;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  // The swatch must track a per-curve colour override (the step line honours the same
  // `surv-i` style below), else recolouring a curve leaves a stale legend swatch. A curve
  // toggled off in the Inspector Series list (seriesStyles[surv-i].hidden) drops out.
  const survHidden = (i: number): boolean => plot.seriesStyles?.[`surv-${i}`]?.hidden === true;
  const rawLegend: LegendEntry[] = curves
    .map((c, i) => ({ label: c.label, color: plot.seriesStyles?.[`surv-${i}`]?.color ?? c.color ?? seriesColor(i, palette), marker: false, select: { as: "series" as const, id: `surv-${i}` } }))
    .filter((_, i) => !survHidden(i));
  const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);
  const legend = leg.entries;

  // Number-at-risk table under the X axis (grows the bottom margin so it never overlaps).
  const atRiskData = plot.survivalAtRisk;
  const showAtRisk = !!atRiskData && atRiskData.rows.length > 0 && (plot.survivalShowAtRisk ?? true);
  // The table's own font (clicking "Number at risk" opens its size); unset = the tick font.
  const atRiskFont: ResolvedFont = plot.survivalAtRiskFont
    ? { ...fonts.tick, ...Object.fromEntries(Object.entries(plot.survivalAtRiskFont).filter(([, v]) => v !== undefined)) }
    : fonts.tick;
  const atRiskRowH = atRiskFont.size + 7;
  const atRiskH = showAtRisk ? (atRiskData!.rows.length + 1) * atRiskRowH + 10 : 0;

  // The risk table's row labels sit at the figure's left edge and its first count column on the
  // axis origin, so the left margin must hold the widest label plus a count's half-width —
  // otherwise a long label (e.g. "Combination") runs under the first count.
  const atRiskLabelW = showAtRisk
    ? Math.max(0, ...atRiskData!.rows.map((r) => measure(r.label, atRiskFont.size))) + atRiskFont.size
    : 0;
  const marginLeft = Math.max(
    plot.yAxis?.hidden
      ? pad.l + HIDDEN_AXIS_MARGIN
      : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6)) + pad.l,
    atRiskLabelW ? pad.l + 2 + atRiskLabelW : 0,
  );
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN + atRiskH
    : fonts.tick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b + atRiskH;
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale("linear", xData, xRev ? [plotW, 0] : [0, plotW], gridDensity, manualX, xFmt, xSpacing);
  const yb = buildScale("linear", yData, yRev ? [0, plotH] : [plotH, 0], gridDensity, manualY, yFmt, ySpacing); // y inverted (reversed flips it)

  // Each KM curve is a selectable series (id `surv-i`) — step-line colour / width /
  // dash overrides apply (click a curve → edit it), so the line is not "dead".
  const series: SeriesScene[] = curves.map((c, i): SeriesScene => {
    const style = plot.seriesStyles?.[`surv-${i}`];
    const color = style?.color ?? c.color ?? seriesColor(i, palette);
    const lineWidth = style?.lineWidth ?? 2.4;
    const pts = c.times
      .map((t, k) => ({ t, s: c.surv[k] ?? NaN }))
      .filter((p) => Number.isFinite(p.t) && Number.isFinite(p.s))
      .sort((a, b) => a.t - b.t);
    const linePath =
      d3line<{ t: number; s: number }>()
        .x((p) => plotX + xb.scale(p.t))
        .y((p) => plotY + yb.scale(yv(p.s)))
        .curve(curveStepAfter)(pts) ?? "";
    // 95% CI band: a step area between the lower and upper Greenwood bounds.
    let bandPath = "";
    if (plot.survivalShowCI !== false && c.lower && c.upper && c.lower.length === c.times.length) {
      const bandPts = c.times
        .map((t, k) => ({ t, lo: c.lower![k] ?? NaN, hi: c.upper![k] ?? NaN }))
        .filter((p) => Number.isFinite(p.t) && Number.isFinite(p.lo) && Number.isFinite(p.hi))
        .sort((a, b) => a.t - b.t);
      bandPath =
        d3area<{ t: number; lo: number; hi: number }>()
          .x((p) => plotX + xb.scale(p.t))
          .y0((p) => plotY + yb.scale(yv(p.lo)))
          .y1((p) => plotY + yb.scale(yv(p.hi)))
          .curve(curveStepAfter)(bandPts) ?? "";
    }
    // Censoring ticks: a small mark on the step line at each censoring time (y = the
    // step survival level there).
    let censorTicks: { x: number; y: number }[] | undefined;
    if (plot.survivalShowCensor !== false && c.censor && c.censor.length) {
      const survAt = (tt: number): number => {
        let s = 1;
        for (const p of pts) { if (p.t <= tt) s = p.s; else break; }
        return s;
      };
      censorTicks = c.censor
        .filter((tt) => Number.isFinite(tt))
        .map((tt) => ({ x: plotX + xb.scale(tt), y: plotY + yb.scale(yv(survAt(tt))) }));
    }
    return {
      id: `surv-${i}`,
      name: c.label,
      color,
      linePath,
      ...(bandPath ? { bandPath, bandOpacity: Math.max(0, Math.min(1, plot.survivalCiOpacity ?? 0.15)) } : {}),
      ...(censorTicks && censorTicks.length ? { censorTicks } : {}),
      symbol: "circle",
      symbolSize: 0,
      ...resolveSymbol(undefined, color),
      borderWidth: 1.5,
      lineWidth,
      dash: dashArray(style?.lineDash ?? "solid", lineWidth),
      errorCaps: false,
      errorDir: "both",
      ...seriesExtras(undefined, color, lineWidth, 0, 1),
      marks: [],
    };
  })
    // A curve toggled off in the Inspector Series list is dropped (its CI band + censor
    // ticks go with it).
    .filter((_, i) => !survHidden(i));

  // Report the domain in screen order (value at the low-pixel end first); a reversed
  // axis flips it so the renderer's domain↔pixel math stays consistent.
  const xAxis: AxisScene = {
    type: "linear",
    domain: xRev ? [xb.domain[1], xb.domain[0]] : xb.domain,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, fonts.tick.size),
    title: plot.xAxis?.title ?? xLabel,
    ...axisLine(plot.xAxis),
  };
  const yAxis: AxisScene = {
    type: "linear",
    domain: yRev ? [yb.domain[1], yb.domain[0]] : yb.domain,
    range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: plot.yAxis?.title ?? yLabel,
    ...axisLine(plot.yAxis),
  };

  const mapXann = (v: number): number | undefined => (Number.isFinite(v) ? plotX + xb.scale(v) : undefined);
  const mapYann = (v: number): number | undefined => (Number.isFinite(v) ? plotY + yb.scale(v) : undefined);
  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: mapXann, y: mapYann, bracketX: mapXann },
    undefined,
    warnings,
  );

  // Number-at-risk table layout: counts centred under each time point (axis-aligned),
  // group labels at the far left, occupying the extra bottom margin reserved above.
  const atRisk = showAtRisk
    ? {
        rowH: atRiskRowH,
        // The heading's baseline: one ascent below the table's top edge, not a fixed 6 px — at a
        // 30 px tick font the heading's glyphs reach 26 px above their baseline and would meet
        // the X-axis title above. The table height reserves rowH per line,
        // and rowH ≥ the font, so the last row still lands inside the reserve.
        top: plotY + plotH + (marginBottom - atRiskH) + 4 + atRiskFont.size * TEXT_ASCENT * 0.85,
        // Written only when the graph carries its own table font.
        ...(plot.survivalAtRiskFont ? { font: atRiskFont } : {}),
        labelX: pad.l + 2,
        cols: atRiskData!.times.map((t) => plotX + xb.scale(t)),
        rows: atRiskData!.rows.map((r, i) => ({
          label: r.label,
          // follow the same colour resolution as the drawn curve + legend (seriesStyles override
          // first), so recolouring a KM curve in the Inspector also recolours its at-risk row.
          color: plot.seriesStyles?.[`surv-${i}`]?.color ?? curves[i]?.color ?? seriesColor(i, palette),
          seriesId: `surv-${i}`,
          atRisk: r.atRisk,
        })),
      }
    : undefined;

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis,
    y: yAxis,
    auto: {
      x: options.xDomain != null ? buildScale("linear", wx.home, [0, 1], gridDensity, wx.homeManual, xFmt, xSpacing).domain : xb.domain,
      y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain,
    },
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series,
    legend,
    legendLayout: leg.layout,
    annotations,
    atRisk,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: xLabel, y: yLabel },
    kind: "survival",
    fonts,
    warnings,
  };
}

function buildRocScene(_table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a ROC curve", warnings);
  const curves = plot.roc ?? [];
  if (curves.length === 0) warnings.push("No ROC curve to plot.");

  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);

  const xLabel = "1 − Specificity";
  const yLabel = "Sensitivity";
  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const xFmt = tickFormat(xSpec);
  const yFmt = tickFormat(ySpec);
  const xRev = xSpec.reversed ?? false;
  const yRev = ySpec.reversed ?? false;
  // Note: the ROC axes are the unit square, which is also the auto extent — zooming still means
  // something (the top-left corner is where the useful curves live); the window narrows it.
  const wx = windowed(xSpec, [0, 1], options.xDomain);
  const wy = windowed(ySpec, [0, 1], options.yDomain);
  const manualX = wx.manual;
  const manualY = wy.manual;
  const xData: [number, number] = wx.data;
  const yData: [number, number] = wy.data;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  // The legend carries the AUC per curve; the series keeps the plain label for selection.
  // So the row cannot be matched to its series by comparing the two strings: "Biomarker
  // (AUC 0.860)" never equals "Biomarker". The suffix is the point of this legend, so the row
  // carries its id instead. Caution: never "strip the parenthesis", which would break on the
  // next label that carries text.
  const rocHidden = (i: number): boolean => plot.seriesStyles?.[`roc-${i}`]?.hidden === true;
  // The AUC's CI is the headline number every ROC tool reports, so it rides in the legend
  // next to the point estimate when the analysis carried it — e.g. "AUC 0.860 (95% CI
  // 0.790–0.930)"; absent → the AUC alone.
  const aucLabel = (c: (typeof curves)[number]): string => {
    const auc = Number.isFinite(c.auc) ? c.auc.toFixed(3) : "—";
    if (c.aucLow != null && c.aucHigh != null && Number.isFinite(c.aucLow) && Number.isFinite(c.aucHigh)) {
      const pct = Math.round((c.aucConf ?? 0.95) * 100);
      return `${c.label} (AUC ${auc}, ${pct}% CI ${c.aucLow.toFixed(3)}–${c.aucHigh.toFixed(3)})`;
    }
    return `${c.label} (AUC ${auc})`;
  };
  const rawLegend: LegendEntry[] = curves
    .map((c, i) => ({
      label: aucLabel(c),
      color: plot.seriesStyles?.[`roc-${i}`]?.color ?? c.color ?? seriesColor(i, palette),
      marker: false, // an ROC curve is a line-only trace — no data-point dot in the swatch
      select: { as: "series" as const, id: `roc-${i}` },
    }))
    .filter((_, i) => !rocHidden(i));
  // Default the legend on even for a single curve — it carries the AUC (the headline
  // number). An explicit user `legend.show:false` still hides it.
  const legPlot: Plot = { ...plot, legend: { ...plot.legend, show: plot.legend?.show ?? true } };
  /**
   * `width` turns on the outside-right fallback in `resolveLegend`. ROC needs it most: its labels
   * carry the AUC ("Biomarker (AUC 0.860)"), so they are both the longest in the program and the
   * ones that must never be shortened, and at a narrow figure a reservation without the fallback
   * can leave 1px of plot. Every builder passes it — except the paired dot, which runs its own
   * stricter cap and says so at its own call site.
   */
  const leg = resolveLegend(legPlot, rawLegend, measure, fonts.legend.size, width);
  const legend = leg.entries;

  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6)) + pad.l;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale("linear", xData, xRev ? [plotW, 0] : [0, plotW], gridDensity, manualX, xFmt, xSpacing);
  const yb = buildScale("linear", yData, yRev ? [0, plotH] : [plotH, 0], gridDensity, manualY, yFmt, ySpacing);
  const line = (pts: { fpr: number; tpr: number }[], connect: ConnectMode = "straight"): string =>
    d3line<{ fpr: number; tpr: number }>().x((p) => plotX + xb.scale(p.fpr)).y((p) => plotY + yb.scale(p.tpr)).curve(curveFor(connect, 0.5))(pts) ?? "";

  const mkSeries = (id: string, name: string, color: string, lineWidth: number, dash: string | null, pts: { fpr: number; tpr: number }[], opts?: { connect?: ConnectMode | undefined; lineColor?: string | undefined }): SeriesScene => {
    const connect = opts?.connect ?? "straight";
    return {
      id, name, color,
      lineColor: opts?.lineColor ?? color,
      linePath: connect === "none" ? "" : line(pts, connect),
      symbol: "circle", symbolSize: 0,
      ...resolveSymbol(undefined, color),
      borderWidth: 1.5, lineWidth, dash,
      errorCaps: false, errorDir: "both",
      ...seriesExtras(undefined, color, lineWidth, 0, 1),
      marks: [],
    };
  };
  // The ROC curves first (so series[0] is a real, style-overridable curve), then the
  // dashed grey chance diagonal on top; the diagonal is not in the legend.
  const series: SeriesScene[] = curves
    .map((c, i) => {
      const style = plot.seriesStyles?.[`roc-${i}`];
      const color = style?.color ?? c.color ?? seriesColor(i, palette);
      const lineWidth = style?.lineWidth ?? 2.4;
      const lineColor = style?.linkLineColor === false ? (style?.lineColor ?? color) : color;
      const pts = c.points.filter((p) => Number.isFinite(p.fpr) && Number.isFinite(p.tpr)).sort((a, b) => a.fpr - b.fpr || a.tpr - b.tpr);
      return mkSeries(`roc-${i}`, c.label, color, lineWidth, dashArray(style?.lineDash ?? "solid", lineWidth), pts, { connect: style?.connect, lineColor });
    })
    // A curve toggled off in the Inspector Series list (seriesStyles[roc-i].hidden) is dropped.
    .filter((_, i) => !rocHidden(i));
  // The chance diagonal is a reference line that happens to be drawn as a series (it needs a
  // line path, and the series layer is what draws those). Its style therefore comes from
  // `refLineStyles["roc-diag"]`, not from `seriesStyles["roc-diag"]`, and clicking it opens the
  // reference-line panel. Both halves must agree: an ordinary Data panel would write every
  // edit to `seriesStyles`, which nothing reads for this line.
  const rocRl = resolveRefLine(plot, "roc-diag", { color: "#9aa0aa", dash: "dashed", width: 1 });
  if (rocRl.show) {
    series.push(mkSeries("roc-diag", "Chance", rocRl.color ?? "#9aa0aa", rocRl.width, rocRl.dash, [{ fpr: 0, tpr: 0 }, { fpr: 1, tpr: 1 }]));
  }

  const xAxis: AxisScene = {
    type: "linear",
    domain: xRev ? [xb.domain[1], xb.domain[0]] : xb.domain,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, fonts.tick.size),
    title: plot.xAxis?.title ?? xLabel,
    ...axisLine(plot.xAxis),
  };
  const yAxis: AxisScene = {
    type: "linear",
    domain: yRev ? [yb.domain[1], yb.domain[0]] : yb.domain,
    range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: plot.yAxis?.title ?? yLabel,
    ...axisLine(plot.yAxis),
  };
  const mapXann = (v: number): number | undefined => (Number.isFinite(v) ? plotX + xb.scale(v) : undefined);
  const mapYann = (v: number): number | undefined => (Number.isFinite(v) ? plotY + yb.scale(v) : undefined);
  const annotations = buildAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: mapXann, y: mapYann, bracketX: mapXann }, undefined, warnings);

  return {
    width, height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis, y: yAxis,
    auto: {
      x: options.xDomain != null ? buildScale("linear", wx.home, [0, 1], gridDensity, wx.homeManual, xFmt, xSpacing).domain : xb.domain,
      y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain,
    },
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series, legend, legendLayout: leg.layout, annotations,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: xLabel, y: yLabel },
    kind: "roc",
    fonts,
    warnings,
  };
}

/** Resolve the P-value column of a QQ plot: the explicit `qq.pColumn`, else a column named
 *  like a p-value, else the last numeric column (the association seed puts P last). */
function qqPColumn(table: DataTable, plot: Plot): Column | undefined {
  const cols = table.columns;
  if (plot.qq?.pColumn) { const c = cols.find((x) => x.id === plot.qq!.pColumn); if (c) return c; }
  const byName = cols.find((c) => /^\s*p(\s|[-_]?val|[-_]?value)?\s*$/i.test(c.name));
  if (byName) return byName;
  const numeric = cols.filter((c) => table.rows.some((r) => Number.isFinite(toNumber(r.cells[c.id]))));
  return numeric[numeric.length - 1];
}

/**
 * GWAS QQ plot (kind "qq"): a marker scatter of observed −log10(p) (Y) against the uniform-null
 * expectation (X), a y = x reference line, and the genomic inflation factor λ in the legend.
 * A drawing built on the shared marker + refline path (the ROC skeleton), with the ranking +
 * λ from core `gwasQQ` (independently cross-checked). Each dot keeps its source-row id, so a
 * point clicks to its marker's Data panel.
 */
function buildQQScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a QQ plot", warnings, "both axes already hold −log10 p-values.");
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const pCol = qqPColumn(table, plot);
  if (!pCol) warnings.push("A QQ plot needs a column of P-values.");
  // (rowId, rowNumber, p) triples, filtered to usable p, sorted by significance.
  const raw = pCol
    ? table.rows
        .map((r, i) => ({ rowId: r.id, rowNumber: i + 1, p: toNumber(r.cells[pCol.id]) }))
        .filter((d) => Number.isFinite(d.p) && d.p > 0 && d.p <= 1)
        .sort((a, b) => a.p - b.p)
    : [];
  const n = raw.length;
  // No usable p-values yet (a fresh seed, or a wrong column) → draw the frame + the y = x
  // line and wait; the empty scatter is self-evident. Only the structural "no column at all"
  // case warns above.
  const lambda = gwasQQ(raw.map((d) => d.p)).lambda;
  const pts = raw.map((d, i) => ({ ...d, expected: -Math.log10((i + 0.5) / n), observed: -Math.log10(d.p) }));
  const maxLog = pts.reduce((m, p) => Math.max(m, p.expected, p.observed), 1);

  const xLabel = "Expected −log₁₀(p)";
  const yLabel = "Observed −log₁₀(p)";
  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const xFmt = tickFormat(xSpec);
  const yFmt = tickFormat(ySpec);
  // A square domain from 0 to the largest −log10 on either axis, so the y = x line reads at 45°.
  const wx = windowed(xSpec, [0, maxLog], options.xDomain);
  const wy = windowed(ySpec, [0, maxLog], options.yDomain);
  const xData: [number, number] = wx.data;
  const yData: [number, number] = wy.data;

  const seriesId = "qq";
  // Honour a per-series look under either the synthetic "qq" id or the P column's own id, so a
  // whole-plot marker-size / colour apply (which writes to the data column) reaches the dots.
  const style = { ...(pCol ? plot.seriesStyles?.[pCol.id] : undefined), ...plot.seriesStyles?.[seriesId] };
  const color = style.color ?? seriesColor(0, palette);
  const symSize = style.symbolSize ?? 3;
  const showLambda = plot.qq?.showLambda ?? true;
  const legLabel = showLambda && Number.isFinite(lambda) ? `Markers (λ = ${lambda.toFixed(3)})` : "Markers";
  const rawLegend: LegendEntry[] = [{
    label: legLabel, color, symbolSize: symSize, marker: true,
    select: { as: "series" as const, id: seriesId },
  }];
  const legPlot: Plot = { ...plot, legend: { ...plot.legend, show: plot.legend?.show ?? showLambda } };
  const leg = resolveLegend(legPlot, rawLegend, measure, fonts.legend.size, width);
  const legend = leg.entries;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, wy.manual, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  const marginLeft = ySpec.hidden ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (ySpec.tickLabelGap ?? 8) + textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6) + pad.l;
  const marginBottom = xSpec.hidden ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (xSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + textBand(fonts.xAxisTitle.size, xSpec.titleGap ?? 6) + pad.b;
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale("linear", xData, [0, plotW], gridDensity, wx.manual, xFmt, xSpacing);
  const yb = buildScale("linear", yData, [plotH, 0], gridDensity, wy.manual, yFmt, ySpacing);

  const marks: MarkScene[] = pts.map((p) => ({
    rowId: p.rowId, rowNumber: p.rowNumber, dx: p.expected, dy: p.observed,
    cx: plotX + xb.scale(p.expected), cy: plotY + yb.scale(p.observed),
  }));
  const markerSeries: SeriesScene = {
    id: seriesId, name: "Markers", color,
    lineColor: color, linePath: "",
    symbol: style.symbol ?? "circle", symbolSize: symSize,
    ...resolveSymbol(style, color),
    borderWidth: style.borderWidth ?? 1, lineWidth: 0, dash: null,
    errorCaps: false, errorDir: "both",
    ...seriesExtras(style, color, 0, symSize, 1),
    marks,
  };
  const series: SeriesScene[] = [markerSeries];
  // The y = x null line, drawn as a series (it needs a line path); its style lives in
  // refLineStyles["qq-identity"] so clicking it opens the reference-line panel, not a Data one.
  const idRl = resolveRefLine(plot, "qq-identity", { color: "#9aa0aa", dash: "dashed", width: 1 });
  if ((plot.qq?.showIdentityLine ?? true) && idRl.show) {
    const p0 = { cx: plotX + xb.scale(0), cy: plotY + yb.scale(0) };
    const p1 = { cx: plotX + xb.scale(maxLog), cy: plotY + yb.scale(maxLog) };
    series.push({
      id: "qq-identity", name: "y = x", color: idRl.color ?? "#9aa0aa",
      lineColor: idRl.color ?? "#9aa0aa", linePath: `M${p0.cx},${p0.cy}L${p1.cx},${p1.cy}`,
      symbol: "circle", symbolSize: 0, ...resolveSymbol(undefined, idRl.color ?? "#9aa0aa"),
      borderWidth: 1, lineWidth: idRl.width, dash: idRl.dash,
      errorCaps: false, errorDir: "both",
      ...seriesExtras(undefined, idRl.color ?? "#9aa0aa", idRl.width, 0, 1),
      marks: [],
    });
  }

  const xAxis: AxisScene = {
    type: "linear", domain: xb.domain, range: [plotX, plotX + plotW],
    ticks: deOverlapX(xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, fonts.tick.size),
    title: xSpec.title ?? xLabel, ...axisLine(xSpec),
  };
  const yAxis: AxisScene = {
    type: "linear", domain: yb.domain, range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: ySpec.title ?? yLabel, ...axisLine(ySpec),
  };
  const mapXann = (v: number): number | undefined => (Number.isFinite(v) ? plotX + xb.scale(v) : undefined);
  const mapYann = (v: number): number | undefined => (Number.isFinite(v) ? plotY + yb.scale(v) : undefined);
  const annotations = buildAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: mapXann, y: mapYann, bracketX: mapXann }, undefined, warnings);

  return {
    width, height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis, y: yAxis,
    auto: { x: [0, maxLog], y: [0, maxLog] },
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series, legend, legendLayout: leg.layout, annotations,
    grid: {
      show: plot.grid?.show ?? true, color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle,
    axisLabels: { x: xLabel, y: yLabel },
    kind: "qq", fonts, warnings,
  };
}

/** Resolve the three Manhattan columns (P · Chromosome · Position). Each prefers an explicit
 *  `plot.manhattan.*Column`, then a name match, then the association seed's fixed position
 *  (Marker · Chromosome · Position · P-value). */
function manhattanColumns(table: DataTable, plot: Plot): {
  pCol?: Column | undefined; chrCol?: Column | undefined; posCol?: Column | undefined;
} {
  const cols = table.columns;
  const byId = (id?: NodeId): Column | undefined => (id ? cols.find((c) => c.id === id) : undefined);
  const numericCols = cols.filter((c) => table.rows.some((r) => Number.isFinite(toNumber(r.cells[c.id]))));
  const pCol = byId(plot.manhattan?.pColumn)
    ?? cols.find((c) => /^\s*p(\s|[-_]?val|[-_]?value)?\s*$/i.test(c.name))
    ?? numericCols[numericCols.length - 1]; // the association seed puts P last
  const chrCol = byId(plot.manhattan?.chrColumn)
    ?? cols.find((c) => /chrom|^\s*chr\s*$/i.test(c.name))
    ?? cols[1];
  const posCol = byId(plot.manhattan?.posColumn)
    ?? cols.find((c) => /position|^\s*pos\s*$|\bbp\b/i.test(c.name))
    ?? cols[2];
  return { pCol, chrCol, posCol };
}

/**
 * GWAS Manhattan plot (kind "manhattan"): a scatter of −log10(p) (Y) for every marker along the
 * genome (X). Chromosomes are laid end to end (core `manhattanLayout` — the genome ruler, one
 * tick per chromosome at its midpoint), points are coloured in two alternating shades per
 * chromosome, and genome-wide + suggestive significance lines cross the plot. Because a real GWAS
 * is 10⁵–10⁶ points, the dense sub-threshold cloud is thinned to the pixel grid (peaks above
 * `keepAbove` are kept whole) and the drawn-vs-entered count is said out loud in a warning.
 */
function buildManhattanScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a Manhattan plot", warnings, "the Y axis already holds −log10 p-values and the X axis is a genome ruler.");
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const { pCol, chrCol, posCol } = manhattanColumns(table, plot);
  if (!pCol) warnings.push("A Manhattan plot needs a column of P-values.");
  if (!chrCol) warnings.push("A Manhattan plot needs a Chromosome column.");
  if (!posCol) warnings.push("A Manhattan plot needs a Position (bp) column.");

  // (rowId, rowNumber, chr, pos, observed −log10 p) for every usable marker.
  const raw = (pCol && chrCol && posCol)
    ? table.rows
        .map((r, i) => ({
          rowId: r.id, rowNumber: i + 1,
          chr: String(r.cells[chrCol.id] ?? "").trim(),
          pos: toNumber(r.cells[posCol.id]),
          p: toNumber(r.cells[pCol.id]),
        }))
        .filter((d) => d.chr !== "" && Number.isFinite(d.pos) && Number.isFinite(d.p) && d.p > 0 && d.p <= 1)
    : [];
  const layout = manhattanLayout(raw.map((d) => ({ chr: d.chr, pos: d.pos })));
  const chrIndex = new Map(layout.chromosomes.map((c, i) => [c.name, i] as const));
  const pts = raw.map((d) => ({ ...d, gx: layout.posOf(d.chr, d.pos), observed: -Math.log10(d.p) }))
    .filter((d) => Number.isFinite(d.gx));

  // Y range must show the significance lines even when no point reaches them.
  const gwP = plot.manhattan?.genomeWideP ?? 5e-8;
  const sugP = plot.manhattan?.suggestiveP ?? 1e-5;
  const gwY = (plot.manhattan?.genomeWideLine ?? true) && gwP > 0 && gwP <= 1 ? -Math.log10(gwP) : 0;
  const sugY = (plot.manhattan?.suggestiveLine ?? true) && sugP > 0 && sugP <= 1 ? -Math.log10(sugP) : 0;
  const dataMaxY = pts.reduce((m, p) => Math.max(m, p.observed), 0);
  const maxY = Math.max(1, dataMaxY, gwY, sugY) * 1.06; // 6% headroom above the tallest thing
  const totalX = Math.max(1, layout.total);

  const xLabel = "Chromosome";
  const yLabel = "−log₁₀(p)";
  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yFmt = tickFormat(ySpec);
  const wx = windowed(xSpec, [0, totalX], options.xDomain);
  const wy = windowed(ySpec, [0, maxY], options.yDomain);
  const xData: [number, number] = wx.data;
  const yData: [number, number] = wy.data;

  const seriesId = "manhattan";
  // Honour a whole-plot marker look under either the synthetic "manhattan" id or the P column's
  // own id (a plot-wide size/shape apply writes to the data column), as every kind with a synthetic series id does.
  const style = { ...(pCol ? plot.seriesStyles?.[pCol.id] : undefined), ...plot.seriesStyles?.[seriesId] };
  const symSize = style.symbolSize ?? 2.5;
  // The two alternating chromosome tones default to the palette's first hue and a lighter tint of
  // it — the classic two-shade Manhattan look, but seeded from the palette so a style preset's
  // colours reach the ink, as on the rose and ternary charts.
  const baseHue = palette[0] ?? "#274060";
  const colorA = plot.manhattan?.colorA ?? baseHue; // even chromosomes — the palette hue
  const colorB = plot.manhattan?.colorB ?? mix(baseHue, "#ffffff", 0.55); // odd — a lighter tint
  const colorFor = (chr: string): string => ((chrIndex.get(chr) ?? 0) % 2 === 0 ? colorA : colorB);

  const rawLegend: LegendEntry[] = [];
  const legPlot: Plot = { ...plot, legend: { ...plot.legend, show: plot.legend?.show ?? false } };
  const leg = resolveLegend(legPlot, rawLegend, measure, fonts.legend.size, width);
  const legend = leg.entries;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, wy.manual, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  const marginLeft = ySpec.hidden ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (ySpec.tickLabelGap ?? 8) + textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6) + pad.l;
  const marginBottom = xSpec.hidden ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (xSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + textBand(fonts.xAxisTitle.size, xSpec.titleGap ?? 6) + pad.b;
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  // The genome X domain is exact [0, total] — no nice-rounding, or the chromosomes would fill only
  // the left of the plot with dead space to the right (the ruler ticks are chromosome midpoints,
  // not the auto numeric ticks, so nothing else needs the padded bounds).
  const xb = buildScale("linear", xData, [0, plotW], gridDensity, true, undefined, { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks });
  const yb = buildScale("linear", yData, [plotH, 0], gridDensity, wy.manual, yFmt, ySpacing);

  // Pixel coords for every marker, then decimate the sub-threshold cloud: keep every point at or
  // above `keepAbove`, and thin the rest to one representative per integer pixel (cx,cy) — so the
  // drawn count is capped by the pixel grid, not the input size, and the shape is preserved.
  const decimate = plot.manhattan?.decimate ?? true;
  const keepAbove = plot.manhattan?.keepAbove ?? 2;
  const placed = pts.map((p) => ({
    rowId: p.rowId, rowNumber: p.rowNumber, chr: p.chr, dx: p.gx, dy: p.observed,
    cx: plotX + xb.scale(p.gx), cy: plotY + yb.scale(p.observed),
  }));
  let drawn = placed;
  if (decimate) {
    const seen = new Set<number>();
    drawn = placed.filter((m) => {
      if (m.dy >= keepAbove) return true; // peaks are never thinned
      const key = Math.round(m.cx) * 100000 + Math.round(m.cy);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
    if (drawn.length < placed.length) {
      warnings.push(
        `Drew ${drawn.length} of ${placed.length} markers — the dense sub-threshold cloud was thinned to the pixel grid (markers at or above −log₁₀ p = ${keepAbove} are kept whole).`,
      );
    }
  }

  // Each mark carries its chromosome colour in every fill mode (fill + outline + two-tone
  // interior) — `paintMarkColour`, the data-driven rule. A bare `fill` only paints a solid
  // marker; under the house two-tone default every point would take the series tint and the
  // chromosome blocks would disappear.
  const marks: MarkScene[] = drawn.map((m) => {
    const mark: MarkScene = { rowId: m.rowId, rowNumber: m.rowNumber, dx: m.dx, dy: m.dy, cx: m.cx, cy: m.cy };
    paintMarkColour(mark, colorFor(m.chr));
    return mark;
  });
  const markerSeries: SeriesScene = {
    id: seriesId, name: "Markers", color: colorA,
    lineColor: colorA, linePath: "",
    symbol: style.symbol ?? "circle", symbolSize: symSize,
    ...resolveSymbol(style, colorA),
    borderWidth: style.borderWidth ?? 0, lineWidth: 0, dash: null,
    errorCaps: false, errorDir: "both",
    ...seriesExtras(style, colorA, 0, symSize, 1),
    marks,
  };
  const series: SeriesScene[] = [markerSeries];

  // Custom X ticks: one per chromosome at its span's midpoint (the genome ruler), never the
  // auto-derived numeric ticks of the cumulative-position axis.
  const chrTicks = layout.chromosomes.map((c) => ({
    value: c.mid, pos: plotX + xb.scale(c.mid), label: c.name, minor: false,
  }));
  const xAxis: AxisScene = {
    type: "linear", domain: xb.domain, range: [plotX, plotX + plotW],
    ticks: deOverlapX(chrTicks, measure, fonts.tick.size),
    title: xSpec.title ?? xLabel, ...axisLine(xSpec),
  };
  const yAxis: AxisScene = {
    type: "linear", domain: yb.domain, range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: ySpec.title ?? yLabel, ...axisLine(ySpec),
  };
  const mapXann = (v: number): number | undefined => (Number.isFinite(v) ? plotX + xb.scale(v) : undefined);
  const mapYann = (v: number): number | undefined => (Number.isFinite(v) ? plotY + yb.scale(v) : undefined);
  // The two significance guides ride in front of the user's own annotations.
  const guidedPlot: Plot = { ...plot, annotations: [...(plot.annotations ?? []), ...manhattanThresholdLines(plot)] };
  const annotations = buildAnnotations(guidedPlot, { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: mapXann, y: mapYann, bracketX: mapXann }, undefined, warnings);

  return {
    width, height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis, y: yAxis,
    auto: { x: [0, totalX], y: [0, maxY] },
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series, legend, legendLayout: leg.layout, annotations,
    grid: {
      show: plot.grid?.show ?? true, color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle,
    axisLabels: { x: xLabel, y: yLabel },
    kind: "manhattan", fonts, warnings,
  };
}

/** Pool all finite values of a dataset (replicate subcolumns × rows). */
function poolDatasetValues(table: DataTable, ds: Dataset): number[] {
  const out: number[] = [];
  for (const row of table.rows) {
    for (const colId of ds.replicates) {
      const v = toNumber(row.cells[colId]);
      if (Number.isFinite(v)) out.push(v);
    }
  }
  return out;
}

/** A dataset entered as pre-computed box statistics (median lead + Q1/Q3, optionally
 *  min/max). Box/violin draw a box straight from these instead of pooling raw values. */
function isBoxSummaryDataset(ds: Dataset): boolean {
  return isSummaryDataset(ds) && (ds.q1 !== undefined || ds.q3 !== undefined);
}

/** No box (n=0) — the box drawer skips it. Used for a group that can't define one. */
const EMPTY_BOX_SUMMARY: BoxSummary = { n: 0, min: NaN, q1: NaN, median: NaN, q3: NaN, max: NaN, whiskerLow: NaN, whiskerHigh: NaN, outliers: [] };

/**
 * Build a `BoxSummary` from a dataset's entered five-number summary (the lead cell is
 * the median; Q1/Q3 and, when present, min/max come from their role columns) — reusing
 * the very struct `boxStats` produces, so the box drawer is shared with raw data. One
 * box per group, read from the first row carrying a finite median (the box-values shape
 * is one row). Missing quartiles collapse to the median; missing min/max to the box edge.
 */
function summaryBoxSummary(table: DataTable, ds: Dataset): BoxSummary {
  const cell = (row: Row, id: string | undefined): number => (id ? toNumber(row.cells[id]) : NaN);
  for (const row of table.rows) {
    const median = cell(row, ds.replicates[0]);
    if (!Number.isFinite(median)) continue;
    const q1 = Number.isFinite(cell(row, ds.q1)) ? cell(row, ds.q1) : median;
    const q3 = Number.isFinite(cell(row, ds.q3)) ? cell(row, ds.q3) : median;
    const min = Number.isFinite(cell(row, ds.min)) ? cell(row, ds.min) : q1;
    const max = Number.isFinite(cell(row, ds.max)) ? cell(row, ds.max) : q3;
    return { n: 1, min, q1, median, q3, max, whiskerLow: min, whiskerHigh: max, outliers: [] };
  }
  return EMPTY_BOX_SUMMARY;
}

/** The mean of a dataset's finite replicate subcolumns in one row. A summary dataset's
 *  `replicates` is just its mean column (so this returns the entered mean); a raw replicate
 *  dataset returns the mean across its subcolumns. NaN when the row has no finite value.
 *  Use this instead of `row.cells[ds.id]` (the lead replicate only) wherever a single
 *  per-cell value is needed, so replicates 2..k aren't silently discarded. */
function rowDatasetMean(row: DataTable["rows"][number], ds: Dataset): number {
  const vals = ds.replicates.map((c) => toNumber(row.cells[c])).filter((v) => Number.isFinite(v));
  return vals.length ? vals.reduce((a, v) => a + v, 0) / vals.length : NaN;
}

/**
 * Build a violin silhouette: a Gaussian-KDE density mirrored about the band
 * centre `cx`, sampled across the dataset's own value range (clamped to the
 * data — no ballooning past the extremes). Returns a closed SVG path in pixel
 * space, scaled so the peak density reaches `maxHalf` from the centre. Returns
 * undefined for <2 points or flat data (no density) — the caller falls back to
 * the inner box alone.
 */
/**
 * A violin's half-width, px, at evenly spaced values from its lowest to its highest (`ys`, data units) — the density
 * estimate its outline is drawn from, scaled so the widest point is `maxHalf`. Undefined when there is no shape to draw
 * (fewer than two values, or all equal).
 */
function violinHalfWidths(values: ReadonlyArray<number>, maxHalf: number, yType: ScaleType, bwScale = 1): { ys: number[]; half: number[] } | undefined {
  let finite = values.filter((v) => Number.isFinite(v));
  if (isLog(yType)) finite = finite.filter((v) => v > 0);
  if (finite.length < 2) return undefined;
  const lo = Math.min(...finite);
  const hi = Math.max(...finite);
  if (!(hi > lo)) return undefined;
  const STEPS = 48;
  const ys = Array.from({ length: STEPS + 1 }, (_, i) => lo + ((hi - lo) * i) / STEPS);
  // Bandwidth multiplier (× Silverman): lower = spikier silhouette, higher = smoother.
  const base = silvermanBandwidth(finite);
  const bw = bwScale !== 1 && base > 0 ? base * bwScale : undefined;
  const dens = gaussianKde(finite, ys, bw);
  const maxD = Math.max(...dens);
  if (!(maxD > 0)) return undefined;
  return { ys, half: dens.map((d) => (d / maxD) * maxHalf) };
}

/** The violin's half-width, px, at value `v` (straight-line between the outline's own steps; 0 outside its range) —
 *  so the dots drawn inside a violin can be kept inside its outline. Undefined when the violin draws no shape. */
export function violinHalfAt(values: ReadonlyArray<number>, maxHalf: number, yType: ScaleType, bwScale = 1): ((v: number) => number) | undefined {
  const w = violinHalfWidths(values, maxHalf, yType, bwScale);
  if (!w) return undefined;
  const { ys, half } = w;
  const lo = ys[0]!;
  const step = ys[1]! - lo;
  return (v) => {
    const t = (v - lo) / step;
    if (!(t >= 0 && t <= ys.length - 1)) return 0;
    const k = Math.min(ys.length - 2, Math.floor(t));
    return half[k]! + (half[k + 1]! - half[k]!) * (t - k);
  };
}

function buildViolinPath(
  values: ReadonlyArray<number>,
  band: number,
  maxHalf: number,
  pv: (v: number) => number,
  yType: ScaleType,
  horizontal = false,
  bwScale = 1,
  oneSided: "left" | "right" | false = false,
): MarkScene["violin"] {
  const widths = violinHalfWidths(values, maxHalf, yType, bwScale);
  if (!widths) return undefined;
  const { ys, half } = widths;
  const STEPS = ys.length - 1;
  // `band` is the silhouette's centre on the cross axis (X when vertical, Y when
  // horizontal); `pv` maps a value to its position on the value axis.
  const pt = (cross: number, value: number): string =>
    horizontal ? `${value.toFixed(2)},${cross.toFixed(2)}` : `${cross.toFixed(2)},${value.toFixed(2)}`;
  // Full violin: one edge low→high, then the mirror edge high→low, closed.
  // One-sided (raincloud "cloud"): a single density edge + a flat edge at `band`.
  const pts: string[] = [];
  if (oneSided) {
    const sign = oneSided === "left" ? -1 : 1;
    for (let i = 0; i <= STEPS; i++) pts.push(pt(band + sign * half[i]!, pv(ys[i]!)));
    for (let i = STEPS; i >= 0; i--) pts.push(pt(band, pv(ys[i]!)));
  } else {
    for (let i = 0; i <= STEPS; i++) pts.push(pt(band + half[i]!, pv(ys[i]!)));
    for (let i = STEPS; i >= 0; i--) pts.push(pt(band - half[i]!, pv(ys[i]!)));
  }
  return { path: `M${pts.join("L")}Z`, cx: band, halfWidth: maxHalf };
}

/**
 * Lay out a column-scatter swarm: every replicate as a dot, deterministically
 * offset sideways so overlapping points spread into a density-width beeswarm.
 * Points are grouped into pixel-height rows; within a row the k points are
 * spaced symmetrically about `cx`, capped at ±`maxHalf` (denser rows → wider).
 * Pure + deterministic (no jitter RNG) so snapshots and exports are stable.
 */
/**
 * Composite overlay for a categorical (bar) series — bars + line / points / area. Shared by the
 * vertical and horizontal bar builders: each mark's (cx, cy) is already placed, `base` is the
 * value-0 pixel on the value axis, `horizontal` says which axis carries the value. A composite
 * series drops its rects (mark.bar) and gets: "line" → a path through its values; "points" →
 * its swarm (or one marker at the mean on summary data); "area" → a closed fill from the values
 * to the baseline plus the line along the edge. Stacked/percent layouts refuse points/area with
 * a warning (a segment has no value of its own to place); a one-category composite warns instead of
 * silently drawing nothing.
 */
function compositeOverlay(
  marks: MarkScene[],
  style: SeriesStyle | undefined,
  name: string,
  warnings: string[],
  stacked: boolean,
  base: number,
  horizontal: boolean,
  /** The plot's "Show values": on a series drawn as points the value rides on each dot as its
   *  point label (the bar rectangle the value label is normally placed against is deleted
   *  below). Without this the option would be accepted and silently draw nothing. */
  values?: { show: boolean; decimals?: number | undefined } | undefined,
): { overlayLine: string; areaPath: string } {
  const plotAs = style?.plotAs;
  const wants = plotAs === "line" || plotAs === "points" || plotAs === "area";
  if (!wants) return { overlayLine: "", areaPath: "" };
  if (stacked && plotAs !== "line") {
    warnings.push(`“${name}” cannot be drawn as ${plotAs} on a stacked chart — each segment sits on the one below, so it has no value of its own to place. It is drawn as bars.`);
    return { overlayLine: "", areaPath: "" };
  }
  for (const m of marks) delete m.bar;
  const ordered = marks.filter((m) => Number.isFinite(m.cy) && Number.isFinite(m.cx)).sort((a, b) => a.dx - b.dx);
  const curve = curveFor(style?.connect ?? "straight", style?.lineTension ?? 0.5);
  if (ordered.length < 2) {
    warnings.push(`“${name}” is set to draw as ${plotAs} over the bars, but that needs at least two categories — with one it draws nothing. Add a category, or set Render as back to Bars.`);
  }
  let overlayLine = "";
  let areaPath = "";
  if ((plotAs === "line" || plotAs === "area") && ordered.length >= 2) {
    overlayLine = d3line<MarkScene>().x((m) => m.cx).y((m) => m.cy).curve(curve)(ordered) ?? "";
  }
  if (plotAs === "area" && ordered.length >= 2) {
    areaPath = horizontal
      ? d3area<MarkScene>().x0(() => base).x1((m) => m.cx).y((m) => m.cy).curve(curve)(ordered) ?? ""
      : d3area<MarkScene>().x((m) => m.cx).y0(() => base).y1((m) => m.cy).curve(curve)(ordered) ?? "";
  }
  if (plotAs === "points") {
    // Keep the swarm the bar already carried; summary data gets one marker at the mean.
    for (const m of ordered) if (!m.points || m.points.length === 0) m.points = [{ cx: m.cx, cy: m.cy }];
    if (values?.show) {
      const fmt = (v: number): string => (values.decimals !== undefined ? v.toFixed(values.decimals) : String(+v.toFixed(2)));
      for (const m of ordered) if (Number.isFinite(m.dy)) m.pointLabel = fmt(m.dy);
    }
  }
  return { overlayLine, areaPath };
}

/** The Point spread control (`Plot.pointSpread`) as the swarm's spacing multiplier: 0.25–3, 1 when unset or not a number. */
export function pointSpreadOf(s: number | undefined): number {
  return s !== undefined && Number.isFinite(s) ? Math.min(3, Math.max(0.25, s)) : 1;
}

/** The spread one series draws: its own Point spread (Data tab, "whole graph" unticked), else the graph's. */
function seriesPointSpread(plot: Plot, style: SeriesStyle | undefined): number {
  return pointSpreadOf(style?.pointSpread ?? plot.pointSpread);
}

/**
 * A column scatter's swarm width as a fraction of its band (0.1-0.9): its Point spread x the 0.5 standard, so 1x draws
 * exactly what the default Width (`boxWidth` 0.5) draws. A series saved with the older "Width" slider (`boxWidth`) and
 * no `pointSpread` has that value read as it is, so a saved column scatter keeps its look.
 */
function scatterSwarmFraction(plot: Plot, style: SeriesStyle | undefined): number {
  const f = style?.pointSpread === undefined && style?.boxWidth !== undefined ? style.boxWidth : 0.5 * seriesPointSpread(plot, style);
  return Math.min(0.9, Math.max(0.1, f));
}

function swarmPoints(
  values: ReadonlyArray<number>,
  band: number,
  maxHalf: number,
  pv: (v: number) => number,
  yType: ScaleType,
  horizontal = false,
  /**
   * Spread multiplier for the preferred dot spacing — 1 = the default look exactly.
   *
   * Without this the Point spread control would have no effect on a column scatter. `maxHalf` does
   * follow it, but it only ever caps the spacing: `step = min(DOT, 2·maxHalf/(k−1))`,
   * and with a handful of replicates per 7px row the fixed DOT always wins, so a narrow and a wide
   * spread would draw the same swarm.
   *
   * The raincloud scales its spread against the 0.5 default of its Width (`spread =
   * clamp(boxWidth)/0.5`); the column scatter passes the same ratio here (`scatterSwarmFraction` / 0.5).
   * At the default it is exactly 1.
   */
  spread = 1,
  /** The group's own half-width at a value, px (a violin's outline, `violinHalfAt`): no dot sits further out. */
  halfAt?: (v: number) => number,
): { cx: number; cy: number }[] {
  let finite = values.filter((v) => Number.isFinite(v));
  if (isLog(yType)) finite = finite.filter((v) => v > 0);
  // `vpos` = the value-axis pixel (Y when vertical, X when horizontal); points are
  // grouped along that axis and spread sideways on the cross axis about `band`.
  const pts = finite.map((v) => ({ v, vpos: pv(v) })).sort((a, b) => a.vpos - b.vpos);
  const ROW = 7; // px row height for grouping overlapping points
  const DOT = 6 * spread; // preferred spacing between dots in the spread direction
  const out: { cx: number; cy: number }[] = [];
  let i = 0;
  while (i < pts.length) {
    let j = i;
    const v0 = pts[i]!.vpos;
    while (j < pts.length && pts[j]!.vpos - v0 < ROW) j++;
    const group = pts.slice(i, j);
    const k = group.length;
    const step = k > 1 ? Math.min(DOT, (2 * maxHalf) / (k - 1)) : 0;
    group.forEach((p, g) => {
      const cross = band + (g - (k - 1) / 2) * step;
      out.push(horizontal ? { cx: p.vpos, cy: cross } : { cx: cross, cy: p.vpos });
    });
    i = j;
  }
  SWARM_LAYOUT.set(out, {
    vpos: out.map((p) => (horizontal ? p.cx : p.cy)), band, maxHalf, horizontal, spread,
    // `out` is in the same (sorted) order as `pts`.
    ...(halfAt ? { halfWidths: pts.map((p) => halfAt(p.v)) } : {}),
  });
  return out;
}

/**
 * What each swarm was laid out from — its dots' value positions, its centre line, its sideways cap, its orientation and
 * spacing — keyed by the points array the mark carries. `spreadSwarms` re-places the dots once the scene knows how big
 * they are drawn; the builders call `swarmPoints` before any series has resolved its dot size.
 */
const SWARM_LAYOUT = new WeakMap<object, { vpos: number[]; band: number; maxHalf: number; horizontal: boolean; spread: number; halfWidths?: number[] }>();

/**
 * Group dots sit side by side (instead of on one vertical line, they are spread slightly
 * sideways). Every swarm — the dots over bars, a column scatter, a box / violin with its points, a raincloud's
 * rain — is re-placed with `beeswarmOffsets` at the radius the renderer draws (`ScatterGlyph`: a bar's own dot size,
 * else the series'), inside the cap its builder gave it. Run once at the choke point, before anything keeps labels or
 * brackets clear of the dots.
 */
function spreadSwarms(scene: PlotScene): void {
  for (const s of scene.series) {
    for (const m of s.marks) {
      const pts = m.points;
      const lay = pts ? SWARM_LAYOUT.get(pts) : undefined;
      if (!pts || !lay) continue;
      const r = swarmDotRadius((m.bar ? m.symbolSize : undefined) ?? s.symbolSize);
      // Inside a violin a wider Point spread keeps each dot's edge inside the outline at its own value (its centre at most
      // half-width − radius) — or at its standard 1× spot, if that is further out: where the violin is too narrow for a
      // dot, the standard layout already chose between touching the outline and overlapping a neighbour, and the
      // standard look never changes.
      const standard = lay.halfWidths && lay.spread !== 1 ? beeswarmOffsets(lay.vpos, r, lay.maxHalf) : undefined;
      const limits = standard && lay.halfWidths?.map((h, k) => Math.max(h - r, Math.abs(standard[k]!), 0));
      const off = beeswarmOffsets(lay.vpos, r, lay.maxHalf, lay.spread, 1, limits);
      m.points = pts.map((p, k) => (lay.horizontal ? { cx: p.cx, cy: lay.band + off[k]! } : { cx: lay.band + off[k]!, cy: p.cy }));
    }
  }
}

/**
 * Horizontal box/violin/column-scatter: the transpose of `buildDistributionScene`
 * — the value axis runs along X and the category bands stack down Y (the same
 * flip horizontal bars use). Glyph geometry is transposed: a box's quartile /
 * whisker / outlier fields hold X pixels and its `x/w` the Y band; a violin
 * silhouette mirrors about a horizontal band line; the scatter swarm spreads
 * vertically with a horizontal mean ± SD reach. Scene carries `distHorizontal`
 * so the renderer draws each glyph in its transposed form.
 */
/**
 * The drawn order of a box / violin / column-scatter chart's groups under `plot.barSort` ("asc" / "desc"): by the
 * centre each group draws — the median line of a box or violin, the chosen centre (mean or median) of a column scatter.
 * A group with no centre (no values) goes last. Ties keep table order. `order[drawn] = table position`,
 * `sortPos[table position] = drawn`; `sortPos` is null when nothing is sorted (other kinds, one group, "none").
 */
function distributionSortOrder(
  kind: PlotScene["kind"],
  plot: Plot,
  datasets: Dataset[],
  stats: ReturnType<typeof boxStats>[],
  summaries: ReturnType<typeof summarize>[],
  pooled: number[][],
): { order: number[]; sortPos: number[] | null } {
  const order = datasets.map((_, i) => i);
  const dir = kind === "box" || kind === "violin" || kind === "scatter" ? plot.barSort ?? "none" : "none";
  if (dir === "none" || datasets.length < 2) return { order, sortPos: null };
  const centre = datasets.map((ds, i) =>
    kind === "scatter"
      ? scatterCentreError(summaries[i]!, stats[i]!, plot.columnScatter, isSummaryDataset(ds) ? undefined : pooled[i]).center
      : stats[i]!.median,
  );
  const has = (i: number): boolean => Number.isFinite(centre[i]);
  order.sort((a, b) => {
    if (has(a) !== has(b)) return has(a) ? -1 : 1;
    if (!has(a)) return a - b;
    return (dir === "asc" ? centre[a]! - centre[b]! : centre[b]! - centre[a]!) || a - b;
  });
  const sortPos = new Array<number>(order.length);
  order.forEach((orig, pos) => { sortPos[orig] = pos; });
  return { order, sortPos };
}

/**
 * The notch (`SeriesStyle.boxNotch`): median ± 1.58·IQR/√n, an approximate 95% CI of the median (McGill, Tukey &
 * Larsen 1978), from the same quartiles the box is drawn with. Returns the pixel ends, or nothing — and says why when
 * the user asked for a notch that cannot be drawn: mean-centred whiskers draw no median box, and equal quartiles
 * leave nothing to notch. A notch reaching past the box is drawn as asked, with a warning (R does the same).
 */
function boxNotchOf(
  b: { n: number; q1: number; median: number; q3: number },
  on: boolean | undefined,
  whisker: BoxWhisker | undefined,
  pv: (v: number) => number,
  name: string,
  warnings: string[],
): { notch?: { low: number; high: number } } {
  if (!on || !(b.n > 0)) return {};
  if (whisker === "sd" || whisker === "sem" || whisker === "ci95") {
    warnings.push(`“${name}”: no notch — with the whiskers at the mean ± SD / SEM / CI the box shows the mean, not the median.`);
    return {};
  }
  const half = (1.58 * (b.q3 - b.q1)) / Math.sqrt(b.n);
  const low = pv(b.median - half);
  const high = pv(b.median + half);
  if (!(half > 0) || !Number.isFinite(low) || !Number.isFinite(high)) {
    warnings.push(`“${name}”: no notch — ${half > 0 ? "it reaches below zero on a log axis" : "its quartiles are equal, so there is no spread to notch"}.`);
    return {};
  }
  if (b.median - half < b.q1 || b.median + half > b.q3) {
    warnings.push(`“${name}”: its notch is taller than its box — too few values (or a very lopsided group) to pin down the median.`);
  }
  return { notch: { low, high } };
}

/** Column-scatter overlay geometry in data space: the central line (mean or median)
 *  and the error interval around it. SD / SEM / 95% CI (exact t) / range reuse the
 *  validated core `errorPoint`; IQR = q1..q3; none = centre only. The default
 *  is mean ± SD.
 *  `ciMedian` needs the group's raw values (`raw`); a summary-entered group passes none and
 *  gets no interval (the caller warns — see `medianCiWarnings`). */
function scatterCentreError(
  sm: ReturnType<typeof summarize>,
  b: ReturnType<typeof boxStats>,
  cfg: ColumnScatterStyle | undefined,
  raw: ReadonlyArray<number> | undefined,
): { center: number; low?: number; high?: number } {
  const center = cfg?.center === "median" ? b.median : sm.mean;
  const err = cfg?.error ?? "sd";
  if (err === "none") return { center };
  if (err === "ciMedian") {
    const ci = raw ? medianCI(raw) : undefined;
    return ci ? { center, low: ci.low, high: ci.high } : { center };
  }
  if (err === "iqr") {
    return Number.isFinite(b.q1) && Number.isFinite(b.q3) ? { center, low: b.q1, high: b.q3 } : { center };
  }
  const ep = errorPoint(sm, err, 0.95); // sd | sem | ci95 | range → validated core stats
  return ep.hasError ? { center, low: ep.low, high: ep.high } : { center };
}

/**
 * Small groups. The chart still draws; the warning says which group is
 * too small for what is drawn: a box below 5 values, a violin below 10, a 95% CI of the mean below 3 (column-scatter
 * Summary, or box / violin whiskers at mean ± 95% CI). The CI of the median has its own, stricter warning
 * (`medianCiWarnings`). Groups typed in as a summary have no values to count and are skipped; an empty group is left
 * to the "no data" warning.
 */
function smallGroupWarnings(kind: PlotScene["kind"], plot: Plot, datasets: Dataset[], pooled: number[][]): string[] {
  const BOX_MIN = 5;
  const VIOLIN_MIN = 10;
  const CI_MIN = 3;
  const meanCi = (kind === "scatter" && plot.columnScatter?.error === "ci95") || ((kind === "box" || kind === "violin") && plot.boxWhisker === "ci95");
  const out: string[] = [];
  datasets.forEach((ds, i) => {
    if (isSummaryDataset(ds)) return;
    const n = pooled[i]!.filter((v) => Number.isFinite(v)).length;
    if (n === 0) return;
    const has = `“${ds.name}” has ${n} value${n === 1 ? "" : "s"}`;
    // Say what is unreliable and that it is the drawing: "too few … to mean much" beside a significant result would
    // read as if the test were in doubt.
    const drawingOnly = "This concerns the drawing only; statistics on these values are not affected.";
    if (kind === "box" && n < BOX_MIN) out.push(`${has} — too few for a box plot's quartiles and whiskers to be reliable (${BOX_MIN} or more recommended). ${drawingOnly}`);
    if (kind === "violin" && n < VIOLIN_MIN) out.push(`${has} — too few for a violin's outline (its smoothed spread) to be reliable (${VIOLIN_MIN} or more recommended). ${drawingOnly}`);
    if (meanCi && n < CI_MIN) out.push(`${has} — too few for a 95% CI of the mean (${CI_MIN} or more needed).`);
  });
  return out;
}

/** Say which groups get no 95% CI of the median, and why (a summary entry has no raw values;
 *  fewer than 6 values cannot reach 95% coverage). Empty unless the CI of the median is chosen. */
function medianCiWarnings(datasets: Dataset[], pooled: number[][], cfg: ColumnScatterStyle | undefined): string[] {
  if (cfg?.error !== "ciMedian") return [];
  const out: string[] = [];
  datasets.forEach((ds, i) => {
    if (isSummaryDataset(ds)) {
      out.push(`“${ds.name}” is entered as a summary — a 95% CI of the median needs the raw values, so none is drawn for it.`);
      return;
    }
    const vals = pooled[i]!;
    if (medianCI(vals)) return;
    const n = vals.filter((v) => Number.isFinite(v)).length;
    out.push(`“${ds.name}” has ${n} value${n === 1 ? "" : "s"} — a 95% CI of the median needs at least 6, so none is drawn for it.`);
  });
  return out;
}

function buildDistributionSceneHorizontal(args: {
  table: DataTable;
  plot: Plot;
  datasets: Dataset[];
  stats: ReturnType<typeof boxStats>[];
  summaries: ReturnType<typeof summarize>[];
  pooled: number[][];
  kind: PlotScene["kind"];
  palette: readonly string[];
  measure: (text: string, fontPx: number) => number;
  width: number;
  height: number;
  fonts: SceneFonts;
  heading: { title: string; subtitle: string };
  yType: ScaleType;
  yData: [number, number];
  /** The value domain with any pan/zoom window removed — what `auto` must report. */
  homeData: [number, number];
  yRev: boolean;
  yFmt: TickFormat;
  ySpacing: TickSpacing;
  gridDensity: number;
  exactY: boolean;
  manualY: boolean;
  warnings: string[];
  /** Colour-ramp resolution for this scene (built-ins + the project's gradients). */
  ramps: RampResolver;
  /** The series drawn against the second axis — along the top here — with their values, the scale
   *  type and the default title. Decided by the caller so both orientations share them. */
  y2Ids: Set<NodeId>;
  y2Values: number[];
  y2Type: ScaleType;
  y2FallbackTitle: string;
  /** The plot with planned bracket heights released when a series is on the second axis. */
  annPlot: Plot;
  /** Sorted groups (`barSort`): each drawn group's table position, for its palette colour. */
  colorIndex: number[];
  /** Sorted groups: a bracket's 1-based group (table order) → its drawn position. */
  drawnGroup: (c: number) => number;
}): PlotScene {
  const {
    plot, datasets, stats, summaries, pooled, kind, palette, measure,
    heading, yType, yData, homeData, yRev, yFmt, ySpacing, gridDensity, exactY, manualY, warnings,
    ramps, y2Ids, y2Values, y2Type, y2FallbackTitle, annPlot, colorIndex, drawnGroup,
  } = args;
  // Transposed: bottom axis = value (yAxis), left band = category (xAxis). Swap the
  // title fonts so the rendered font follows its axis, in step with the data-routed
  // title text / scale / line (see dataAxisOf).
  const fonts = { ...args.fonts, xAxisTitle: args.fonts.yAxisTitle, yAxisTitle: args.fonts.xAxisTitle };
  let { width, height } = args;
  const pad = plotPadOf(plot);

  const n = datasets.length;
  const ySpec: AxisSpec = plot.yAxis ?? {};
  // Value axis = X; category labels sit on the left (one band per dataset on Y), drawn in the Y axis's
  // own tick font, so they are measured in it — the generic tick font would under-size the margin for larger names.
  const catLabelW = Math.max(0, ...datasets.map((ds) => measure(ds.name, fonts.yTick.size)), turnedYLabelsReach(datasets.map((ds) => ds.name), fonts.yTick.size, measure, plot.xAxis?.tickRotation));
  const valTitle = ySpec.title ?? (n === 1 ? datasets[0]!.name : "");
  const catTitle = plot.xAxis?.title ?? "";
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // Reserve the side title's band too, as the vertical builders and the horizontal bar do. Without it
  // the title would be clamped to the canvas edge on top of the names, and the longest name would run
  // off the canvas. On a transposed chart the category spec
  // (xAxis) owns this axis's label gap and title gap.
  const marginLeft = plot.xAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + (plot.xAxis?.tickLabelGap ?? 8) + (catTitle ? textBand(fonts.yAxisTitle.size, plot.xAxis?.titleGap ?? 6) : 4) + pad.l;
  // Value tick-labels / title sit on the bottom → spacing from the value spec (yAxis). The numbers are drawn with
  // the X tick font, so the band is sized from it — sizing from the shared font would put 30px numbers on the title below.
  const marginBottom = plot.yAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.yAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.yAxis?.titleGap ?? 6)) + pad.b;
  const leg = groupLegend(plot, datasets, palette, measure, fonts.legend.size, width);
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  // The second axis runs along the top here (as on a horizontal bar chart): its numbers and title
  // take a band above the plot, below any heading or top legend. Its title font is the value axis's.
  const y2Plan = y2Ids.size > 0
    ? planSecondAxis(plot.y2Axis ?? {}, y2Values, y2Type, gridDensity, measure, { tick: fonts.y2Tick.size, title: (fonts.y2AxisTitle ?? fonts.xAxisTitle).size }, y2FallbackTitle, "top")
    : null;
  const y2Top = y2Plan?.margin ?? 0;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad + y2Top;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad + y2Top, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - y2Top - marginBottom);

  const vb = buildScale(yType, yData, yRev ? [plotW, 0] : [0, plotW], gridDensity, exactY, yFmt, ySpacing);
  const valDomainOut: [number, number] = yRev ? [vb.domain[1], vb.domain[0]] : vb.domain;
  // The natural "home" domain — the rest state ignoring any pan/zoom window. `auto` must be
  // this and not an echo of the current domain: the renderer soft-locks back to it and reads it
  // to know whether the chart is zoomed. Echoing the window would make both reads meaningless —
  // the detent could never fire and drag-to-pan could never wake up.
  const homeB: [number, number] = homeData === yData
    ? vb.domain
    : buildScale(yType, homeData, [0, 1], gridDensity, manualY, yFmt, ySpacing).domain;
  const autoV: [number, number] = yRev ? [homeB[1], homeB[0]] : homeB;
  const pxMain = (v: number): number => plotX + vb.scale(v);
  const px = pxMain;
  const leftType = yType;
  // The top second axis: its own left-to-right scale over the same plot width.
  const y2Placed = y2Plan ? placeSecondAxis(y2Plan, { x: plotX, y: plotY, width: plotW, height: plotH }, (fonts.y2AxisTitle ?? fonts.xAxisTitle).size) : null;

  const bandH = n > 0 ? plotH / n : plotH;
  const allValues = pooled.flat();

  const series: SeriesScene[] = datasets.map((ds, i) => {
    // A series on the top second axis draws every glyph against it: these two shadow the main axis's
    // `px` / `yType` for the rest of this callback, so the box / violin / swarm code below is unchanged.
    const px = y2Placed && y2Ids.has(ds.id) ? y2Placed.px : pxMain;
    const yType: ScaleType = y2Placed && y2Ids.has(ds.id) ? y2Plan!.type : leftType;
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(colorIndex[i]!, palette);
    const boxH = bandH * Math.min(0.9, Math.max(0.1, style?.boxWidth ?? 0.5));
    const b = stats[i]!;
    const sm = summaries[i]!;
    const cyc = plotY + i * bandH + bandH / 2; // band centre on Y
    const marks: MarkScene[] = [];
    if (b.n > 0) {
      const mark: MarkScene = {
        rowId: ds.id,
        rowNumber: i + 1,
        dx: i + 1,
        dy: b.median,
        cx: px(b.median),
        cy: cyc,
        n: b.n,
        label: ds.name,
      };
      if (kind === "scatter") {
        const ce = scatterCentreError(sm, b, plot.columnScatter, isSummaryDataset(ds) ? undefined : pooled[i]);
        mark.dy = ce.center;
        mark.cx = px(ce.center);
        // Same Point spread as the vertical form, so a flipped column scatter keeps the control.
        const swarmH = bandH * scatterSwarmFraction(plot, style);
        mark.points = swarmPoints(pooled[i]!, cyc, swarmH / 2, px, yType, true, swarmH / (bandH * 0.5));
        if (ce.low !== undefined && ce.high !== undefined) {
          mark.errLow = ce.low;
          mark.errHigh = ce.high;
          mark.errLowCx = px(ce.low);
          mark.errHighCx = px(ce.high);
        }
      } else if (kind === "floatingbar") {
        // Horizontal floating bar: the box spans the chosen definition along X (min→max by
        // default, else percentiles or mean±SD/SEM/CI — from `whisker`), centre line in the band.
        const lineMode = plot.floatingBar?.line ?? "mean";
        const center = lineMode === "median" ? b.median : sm.mean;
        mark.dy = center;
        mark.cx = px(center);
        mark.box = {
          x: cyc - boxH / 2, w: boxH,
          q1: px(b.whiskerLow), q3: px(b.whiskerHigh),
          median: lineMode === "none" ? null : px(center),
          whiskerLow: px(b.whiskerLow), whiskerHigh: px(b.whiskerHigh), outliers: [],
        };
      } else {
        const showBox = kind !== "violin" || (style?.violinShowBox ?? true);
        const innerH = kind === "violin" ? boxH * (style?.violinBoxWidth ?? 0.34) : boxH;
        const overlayPoints = (kind === "box" || kind === "violin") && (plot.showBoxPoints ?? false);
        // x/w hold the Y band; the quartile/whisker/outlier fields hold X pixels.
        if (showBox) {
          mark.box = {
            x: cyc - innerH / 2,
            w: innerH,
            q1: px(b.q1),
            q3: px(b.q3),
            median: px(b.median),
            whiskerLow: px(b.whiskerLow),
            whiskerHigh: px(b.whiskerHigh),
            outliers: overlayPoints ? [] : b.outliers.map(px), // the point overlay already shows them
            ...(plot.showBoxMean ? { mean: px(sm.mean) } : {}),
            ...boxNotchOf(b, style?.boxNotch, plot.boxWhisker, px, ds.name, warnings),
          };
        } else if (plot.showBoxMean) {
          // Inner box hidden but "Show mean (+)" is on → a mean-only glyph (no box/whiskers/median).
          mark.box = { x: cyc - innerH / 2, w: innerH, q1: px(b.median), q3: px(b.median), median: null, whiskerLow: px(b.median), whiskerHigh: px(b.median), outliers: [], mean: px(sm.mean), meanOnly: true };
        }
        if (kind === "violin") {
          const v = buildViolinPath(pooled[i]!, cyc, boxH / 2, px, yType, true, style?.violinBandwidth ?? 1);
          if (v) mark.violin = v;
        }
        if (overlayPoints) mark.points = swarmPoints(pooled[i]!, cyc, boxH / 2, px, yType, true, seriesPointSpread(plot, style), kind === "violin" ? violinHalfAt(pooled[i]!, boxH / 2, yType, style?.violinBandwidth ?? 1) : undefined);
      }
      marks.push(mark);
    }
    return {
      id: ds.id,
      name: ds.name,
      color,
      linePath: "",
      symbol: style?.symbol ?? "circle",
      symbolSize: style?.symbolSize ?? 4,
      ...resolveSymbol(style, color),
      borderWidth: style?.borderWidth ?? 1.5,
      lineWidth: style?.lineWidth ?? 2,
      dash: null,
      errorCaps: true,
      errorDir: "both",
      whiskerSides: style?.whiskerSides ?? "both",
      whiskerColor: style?.whiskerColor ?? style?.borderColor ?? color,
      whiskerWidth: style?.whiskerWidth ?? style?.borderWidth ?? 1.5,
      // floatingbar has no whiskers (they collapse to the box min/max edges), so the
      // reused BoxGlyph must not draw cap ticks at those edges.
      whiskerCaps: kind === "floatingbar" ? false : (style?.whiskerCaps ?? true),
      whiskerCapWidth: style?.whiskerCapWidth ?? 0.28,
      medianColor: style?.medianColor ?? style?.borderColor ?? color,
      medianWidth: style?.medianWidth ?? (style?.borderWidth ?? 1.5) + 0.8,
      showOutliers: style?.showOutliers ?? true,
      outlierSize: style?.outlierSize ?? 2.4,
      ...seriesExtras(style, color, style?.lineWidth ?? 2, style?.symbolSize ?? 4, 0.18),
      marks,
    };
  });

  // Value-graduated fill across the datasets (one glyph each → normalise over all).
  if (datasets.some((ds) => plot.seriesStyles?.[ds.id]?.fillType === "graduated")) {
    const mapVal = (map: GradMap | undefined, i: number): number => {
      const m = map ?? "value";
      return m === "value" ? (stats[i]?.median ?? NaN) : m === "x" ? i + 1 : i;
    };
    datasets.forEach((ds, i) => {
      const style = plot.seriesStyles?.[ds.id];
      const mark = series[i]?.marks[0];
      if (style?.fillType !== "graduated" || !mark) return;
      const dom = datasets.map((_, j) => mapVal(style.gradMap, j));
      paintGraduated([{ mark, v: dom[i]! }], style, series[i]!.color, dom, ramps);
    });
  }

  const yticks: AxisTick[] = datasets.map((ds, i) => ({
    value: i + 1,
    pos: plotY + i * bandH + bandH / 2,
    label: ds.name,
    minor: false,
  }));
  const xticksV: AxisTick[] = vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos }));

  if (n > 0 && allValues.length === 0) warnings.push("No finite data points to plot.");

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    // Transposed: value spec (yAxis) → X-drawn value axis; category spec (xAxis) →
    // Y-drawn band — keeps flipped-graph edits on the axis the user sees (dataAxisOf).
    x: { type: yType, domain: valDomainOut, range: [plotX, plotX + plotW], ticks: xticksV, title: valTitle, ...axisLine(plot.yAxis) },
    y: { type: "linear", band: true, domain: [0, Math.max(1, n)], range: [plotY + plotH, plotY], ticks: yticks, title: plot.xAxis?.title ?? "", ...axisLine(plot.xAxis) },
    // The second value axis, drawn along the top (`side: "top"`) — present only with a series on it.
    ...(y2Placed ? { y2: y2Placed.axis } : {}),
    auto: { x: autoV, y: [0, Math.max(1, n)] },
    // Transposed: the values are drawn along X but the scale was built from `options.yDomain`
    // (the value spec is `plot.yAxis` whichever way a distribution chart faces). The category
    // band on Y has no numeric domain to zoom.
    zoomable: [{ visual: "x", key: "y" }],
    series,
    legend: leg.entries,
    legendLayout: leg.layout,
    // A horizontal box/violin draws annotations too: the Inspector offers the whole Add palette
    // here, and without this its buttons would create objects that never appear. Transposed
    // threading: the value axis runs along X
    // (`px`) and the categories band down Y, so `bracketX` maps a 1-based category to its
    // band centre, exactly mirroring the vertical builder.
    // With a series on the second axis, planned bracket heights are released (`annPlot`).
    annotations: buildAnnotations(
      annPlot,
      { x: plotX, y: plotY, width: plotW, height: plotH },
      {
        x: (v) => (Number.isFinite(v) ? px(v) : undefined),
        y: (v) => (Number.isFinite(v) ? px(v) : undefined),
        bracketX: (c) => {
          const d = drawnGroup(c);
          return d >= 1 && d <= n ? plotY + (d - 1) * bandH + bandH / 2 : undefined;
        },
      },
      true,
      warnings,
    ),
    valueAxis: "x" as const,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: valTitle || "Value", y: "Group" },
    kind,
    fonts,
    distHorizontal: true,
    warnings,
  };
}

/**
 * Box-and-whisker chart — one box per dataset (column-style), summarising
 * the dataset's pooled values. Categories = dataset names on a band X axis.
 * `violin` adds a KDE silhouette around a slimmed box; `scatter` replaces the
 * box with a density-swarm of every replicate plus a mean ± SD overlay.
 */
/** Inline seeded PRNG (mulberry32) so the estimation bootstrap is reproducible. */
function estimationRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Linear-interpolated percentile of an ascending-sorted array. */
function percentileSorted(sorted: readonly number[], p: number): number {
  if (sorted.length === 0) return NaN;
  const idx = p * (sorted.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  return lo === hi ? sorted[lo]! : sorted[lo]! + (idx - lo) * (sorted[hi]! - sorted[lo]!);
}

/**
 * Gardner-Altman estimation plot: two groups shown as raw swarm dots (control
 * = first dataset, test = second) beside a right-hand effect-size axis carrying the
 * mean difference with a bootstrap CI + the bootstrap distribution as a half-violin.
 * The effect axis is the value axis shifted so the control mean reads 0 (they share
 * one pixel scale), so effect e sits at value meanC+e and the effect point aligns
 * with the test mean. The bootstrap is seeded → the graph is reproducible.
 */
/**
 * Say so when a log scale was asked for and this chart kind cannot draw one.
 *
 * These four builders lay their value axis out with a bespoke linear scale and never read
 * `AxisSpec.scale` at all, so "Log10" in the Axis tab cannot change them, on either axis,
 * even with all-positive data. Unlike a data-dependent refusal such as box/scatter's
 * ("Log Y needs all-positive values"), nothing else would explain it: a control the user
 * turns on that changes nothing, with no message, is indistinguishable from a bug in
 * the app. So the refusal is stated as a warning.
 */
function warnLogUnsupported(plot: Plot, kindLabel: string, warnings: string[], reason?: string): void {
  const asked = [plot.xAxis?.scale, plot.yAxis?.scale, plot.yScale].some((v) => !!v && v !== "linear");
  if (asked) {
    warnings.push(
      reason
        ? `A log scale is not available on ${kindLabel} — ${reason}`
        : `A log scale is not available on ${kindLabel} — the value axis is drawn linear.`,
    );
  }
}

function buildEstimationScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "an estimation plot", warnings);
  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);

  const datasets = tableDatasets(table); // positional, not independent series — see note below
  // Not `visibleDatasets`. This builder reads datasets by position (control vs test,
  // method A vs B, left vs right), so dropping a hidden one renumbers the rest and the
  // chart silently compares a different pair. In Bland-Altman, for example, `styleId` is
  // `datasets[1].id`, so filtering would make the hidden lookup miss and bring the legend back.
  // Hiding a structural input is not "show less", it is "compute something else".
  const control = datasets[0] ? poolDatasetValues(table, datasets[0]) : [];
  const test = datasets[1] ? poolDatasetValues(table, datasets[1]) : [];
  if (datasets.length < 2 || control.length < 2 || test.length < 2) {
    warnings.push("Estimation plot needs two groups with ≥ 2 values each.");
  }
  const est = plot.estimation ?? {};
  const paired = est.paired ?? false;
  const B = Math.max(200, Math.min(10000, Math.floor(est.resamples ?? 2000)));
  const level = est.ciLevel ?? 0.95;
  const meanOf = (a: readonly number[]): number => (a.length ? a.reduce((s, v) => s + v, 0) / a.length : 0);
  const meanC = meanOf(control);
  const meanT = meanOf(test);
  // Paired = per-subject differences from row-aligned complete pairs. Pooling each column
  // independently (control/test) drops interior blanks per column, so blanks in different
  // rows would misalign the pairing (and unequal pooled counts would fall back to the
  // unpaired bootstrap). Pair the k-th replicate of each dataset row-by-row.
  const pairedD: number[] = [];
  if (paired && datasets[0] && datasets[1]) {
    const ra = datasets[0].replicates;
    const rb = datasets[1].replicates;
    for (const row of table.rows) {
      for (let k = 0; k < Math.min(ra.length, rb.length); k++) {
        const va = toNumber(row.cells[ra[k]!]);
        const vb = toNumber(row.cells[rb[k]!]);
        if (Number.isFinite(va) && Number.isFinite(vb)) pairedD.push(vb - va);
      }
    }
  }
  const usePaired = paired && pairedD.length >= 2;
  const obsDiff = usePaired ? meanOf(pairedD) : meanT - meanC;

  // Seeded bootstrap of the mean difference (paired = per-subject differences).
  const rng = estimationRng((est.seed ?? 20240704) >>> 0);
  const ri = (n: number): number => Math.min(n - 1, Math.floor(rng() * n));
  const diffs: number[] = [];
  if (usePaired) {
    const n = pairedD.length;
    for (let b = 0; b < B; b++) { let s = 0; for (let i = 0; i < n; i++) s += pairedD[ri(n)]!; diffs.push(s / n); }
  } else if (control.length >= 2 && test.length >= 2) {
    const nc = control.length;
    const nt = test.length;
    for (let b = 0; b < B; b++) {
      let sc = 0;
      let st = 0;
      for (let i = 0; i < nc; i++) sc += control[ri(nc)]!;
      for (let i = 0; i < nt; i++) st += test[ri(nt)]!;
      diffs.push(st / nt - sc / nc);
    }
  }
  const sortedDiffs = diffs.slice().sort((a, b) => a - b);
  const ciLo = diffs.length ? percentileSorted(sortedDiffs, (1 - level) / 2) : NaN;
  const ciHi = diffs.length ? percentileSorted(sortedDiffs, 1 - (1 - level) / 2) : NaN;

  const shift = (e: number): number => meanC + e; // effect value → primary value

  // Primary value domain: group values + shifted effect region (violin + CI + 0).
  const effShifted = diffs.map(shift);
  const domainValues: number[] = [...control, ...test];
  if (Number.isFinite(meanC)) domainValues.push(meanC);
  if (effShifted.length) domainValues.push(Math.min(...effShifted), Math.max(...effShifted));
  if (Number.isFinite(ciLo)) domainValues.push(shift(ciLo), shift(ciHi));
  if (domainValues.length === 0) domainValues.push(0, 1);

  const ySpec: AxisSpec = plot.yAxis ?? {};
  const yFmt = tickFormat(ySpec);
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yRev = ySpec.reversed ?? false;
  const autoYDom = buildScale("linear", extent(domainValues), [0, 1], gridDensity, false, yFmt).domain;
  const wy = windowed(ySpec, autoYDom, options.yDomain);
  const manualY = wy.manual;
  const yData = wy.data;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  const yLabel = ySpec.title ?? (datasets[0]?.name ?? "Value");

  // Right effect axis (its own ticks, on the shifted domain).
  const effDomain: [number, number] = [yData[0] - meanC, yData[1] - meanC];
  const y2Spec: AxisSpec = plot.y2Axis ?? {};
  const y2Fmt = tickFormat(y2Spec);
  const y2Probe = buildScale("linear", effDomain, [0, 1], gridDensity, false, y2Fmt);
  const y2LabelWidth = yTickLabelsWidth(y2Probe.ticks, fonts.tick.size, measure, y2Spec);

  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6)) + pad.l;
  const marginRight = DEFAULTS.tickLen + (y2Spec.tickLabelGap ?? 8) + y2LabelWidth + rightTitleBand(y2Spec, y2Spec.title ?? (paired ? "Paired difference" : "Difference"), (fonts.y2AxisTitle ?? fonts.yAxisTitle).size, y2Spec.titleGap ?? 6, measure, width) + DEFAULTS.marginRight + pad.r;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const yb = buildScale("linear", yData, yRev ? [0, plotH] : [plotH, 0], gridDensity, manualY, yFmt, ySpacing);
  const py = (v: number): number => plotY + yb.scale(v);
  const yDomainOut: [number, number] = yRev ? [yb.domain[1], yb.domain[0]] : yb.domain;

  const bands = 3;
  const bandW = plotW / bands;
  const cxOf = (i: number): number => plotX + (i + 0.5) * bandW;
  const half = bandW * 0.32;
  const sdOf = (a: readonly number[], m: number): number =>
    a.length >= 2 ? Math.sqrt(a.reduce((s, v) => s + (v - m) ** 2, 0) / (a.length - 1)) : 0;

  const mkSwarm = (vals: number[], m: number, i: number, id: NodeId, name: string): SeriesScene => {
    const style = plot.seriesStyles?.[id];
    const color = style?.color ?? seriesColor(i, palette);
    const cx = cxOf(i);
    const sd = sdOf(vals, m);
    const mark: MarkScene = {
      rowId: id, rowNumber: i + 1, dx: i + 1, dy: m, cx, cy: py(m), n: vals.length, label: name,
      points: swarmPoints(vals, cx, half, py, "linear", false, seriesPointSpread(plot, style)),
    };
    if (vals.length >= 2 && sd > 0) {
      mark.errLow = m - sd; mark.errHigh = m + sd; mark.errLowCy = py(m - sd); mark.errHighCy = py(m + sd);
    }
    return {
      id, name, color, linePath: "", symbol: style?.symbol ?? "circle", symbolSize: style?.symbolSize ?? 4,
      ...resolveSymbol(style, color), borderWidth: style?.borderWidth ?? 1.5, lineWidth: style?.lineWidth ?? 2,
      dash: null, errorCaps: true, errorDir: "both", ...seriesExtras(style, color, style?.lineWidth ?? 2, style?.symbolSize ?? 4, 1), marks: [mark],
    };
  };

  const series: SeriesScene[] = [];
  if (control.length && datasets[0]) series.push(mkSwarm(control, meanC, 0, datasets[0].id, datasets[0].name));
  if (test.length && datasets[1]) series.push(mkSwarm(test, meanT, 1, datasets[1].id, datasets[1].name));

  if (diffs.length) {
    const cx = cxOf(2);
    const style = plot.seriesStyles?.["est-diff"];
    const color = style?.color ?? seriesColor(2, palette);
    const marks: MarkScene[] = [];
    const violin = buildViolinPath(effShifted, cx, half, py, "linear", false, 1, "right");
    if (violin) marks.push({ rowId: "est-diff-dist", rowNumber: 3, dx: 3, dy: shift(obsDiff), cx, cy: py(shift(obsDiff)), n: diffs.length, label: "Difference", violin });
    marks.push({
      rowId: "est-diff", rowNumber: 3, dx: 3, dy: obsDiff, cx, cy: py(shift(obsDiff)), n: diffs.length, label: "Difference",
      points: [{ cx, cy: py(shift(obsDiff)) }],
      errLow: shift(ciLo), errHigh: shift(ciHi), errLowCy: py(shift(ciLo)), errHighCy: py(shift(ciHi)),
    });
    series.push({
      // `symbol` follows the panel's Shape dropdown (a hard-coded "circle" would make that
      // control do nothing). The estimate marker is an ordinary marker; there is no reason it
      // cannot be a square.
      id: "est-diff", name: "Difference", color, linePath: "", symbol: style?.symbol ?? "circle", symbolSize: style?.symbolSize ?? 6,
      ...resolveSymbol(style, color), borderWidth: style?.borderWidth ?? 1.5, lineWidth: 2, dash: null, errorCaps: true,
      errorDir: "both", ...seriesExtras(style, color, 2, 6, 1), marks,
    });
  }

  const bandLabels = [datasets[0]?.name ?? "Control", datasets[1]?.name ?? "Test", "Difference"];
  const xAxis: AxisScene = {
    type: "linear", domain: [0, bands], range: [plotX, plotX + plotW],
    // `deOverlapX` like every other categorical builder, so at a large font the last group name
    // cannot run into "Difference" (the delta panel's own band). A dropped label keeps its text
    // in `suppressedLabel`.
    ticks: deOverlapX(
      bandLabels.map((label, i) => ({ pos: cxOf(i), value: i, label, minor: false })),
      measure,
      fonts.tick.size,
    ),
    title: plot.xAxis?.title ?? "", ...axisLine(plot.xAxis),
  };
  const leg = resolveLegend(plot, [], measure, fonts.legend.size, width);
  const yAxis: AxisScene = {
    type: "linear", domain: yDomainOut, range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: ySpec.title ?? yLabel, ...axisLine(ySpec),
  };
  // The effect axis shares the primary pixel scale: its domain is the primary's
  // resolved domain minus the control mean, built exact (no re-nice-rounding) so
  // effect = 0 lands on the control-mean pixel and every effect tick aligns.
  const y2b = buildScale("linear", [yb.domain[0] - meanC, yb.domain[1] - meanC], yRev ? [0, plotH] : [plotH, 0], gridDensity, true, y2Fmt);
  const y2LabelsEnd = plotX + plotW + DEFAULTS.tickLen + (y2Spec.tickLabelGap ?? 8) + y2LabelWidth;
  const y2Axis: AxisScene = {
    type: "linear", domain: yRev ? [y2b.domain[1], y2b.domain[0]] : y2b.domain, range: [plotY + plotH, plotY],
    ticks: y2b.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: y2Spec.title ?? (paired ? "Paired difference" : "Difference"),
    titleX: y2LabelsEnd + (y2Spec.titleGap ?? 6) + (fonts.y2AxisTitle ?? fonts.yAxisTitle).size * 0.3,
    ...axisLine(y2Spec),
  };

  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    // Note: `(v - 0.5)`, not `v`: bracket endpoints are 1-based category indices, so they must
    // land on band centres like every other categorical builder. With `v / bands` a
    // bracket from group 1 would sit on the band's right edge — half a band off, and on a
    // two-group estimation plot that puts "group 1" at the plot midpoint.
    { x: (v) => plotX + ((v - 0.5) / bands) * plotW, y: (v) => py(v), bracketX: (v) => plotX + ((v - 0.5) / bands) * plotW, namesOnX: true },
    undefined,
    warnings,
  );
  const estZero = resolveRefLine(plot, "est-zero", { dash: "4 3", width: 1 });
  if (Number.isFinite(meanC) && estZero.show) {
    annotations.push({
      id: "est-zero", kind: "line", x1: cxOf(2) - bandW / 2, x2: Math.min(plotX + plotW, cxOf(2) + bandW * 0.62),
      y1: py(meanC), y2: py(meanC), color: estZero.color, dash: estZero.dash, width: estZero.width,
    });
  }

  return {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis, y: yAxis, y2: y2Axis,
    auto: { x: [0, bands], y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain },
    // The effect axis is the value axis; X bands the groups being compared.
    zoomable: [{ visual: "y", key: "y" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: "", y: yLabel }, kind: "estimation", fonts, warnings,
  };
}

/**
 * The right-hand (Y2) value axis of a category chart — one implementation, shared by the bar
 * builder and the box / violin / column-scatter builder. (The XY builder keeps its own Y2 + Y3.)
 *
 * Two steps, because the axis must be sized before the plot rectangle exists — its tick labels
 * and title are part of the right-margin stack — and scaled only once it does.
 */
export interface SecondAxisPlan {
  spec: AxisSpec;
  type: ScaleType;
  domain: [number, number];
  manual: boolean;
  format: TickFormat;
  spacing: TickSpacing;
  reversed: boolean;
  gridDensity: number;
  title: string;
  /** "right" on a vertical chart; "top" on a horizontal bar chart, whose values run left to right. */
  side: "right" | "top";
  /** Tick-number font size, px — a top axis stacks its numbers above the plot by this height. */
  tickFont: number;
  /** Widest major tick label, px — its real reach when turned (`yTickLabelsWidth`). */
  labelWidth: number;
  /** Tallest major tick label above a top axis, px: one line of text, or its real height when turned. */
  labelHeight: number;
  /** What the axis takes from its margin: the right margin (tick + widest label + a title band) or
   *  the top margin (tick + label height + a title band); a 4 px gap stands in for no title. */
  margin: number;
}

/** Size the second axis from the values drawn on it. `fallbackTitle` stands in when the spec has no title. */
export function planSecondAxis(
  spec: AxisSpec,
  values: readonly number[],
  type: ScaleType,
  gridDensity: number,
  measure: (text: string, px: number) => number,
  fonts: { tick: number; title: number },
  fallbackTitle = "",
  side: "right" | "top" = "right",
  /** The figure width — a right title turned another way is sized by `rightTitleBand`, which needs it. */
  canvasWidth: number = DEFAULTS.width,
): SecondAxisPlan {
  const format = tickFormat(spec);
  const spacing: TickSpacing = { majorStep: spec.majorStep, minorCount: spec.minorCount, breaks: spec.breaks };
  const manual = spec.min != null || spec.max != null;
  // Round the automatic range first, then apply a pinned min/max — the left axis's order. Applying
  // the pin to the raw extent would keep the other end raw: when brackets pin the maximum to make
  // room, the lowest value would become the axis bottom and its whisker cap vanish under the axis line.
  const domain = applyRange(spec, buildScale(type, extent(values.length ? [...values] : [0, 1]), [0, 1], gridDensity, false, format).domain);
  const probe = buildScale(type, domain, [0, 1], gridDensity, manual, format, spacing);
  // Note: turned labels need their real reach beside a right-hand axis and their real height above a top one; a
  // margin sized from the flat width and one line of text would leave no room for the turn.
  const labelWidth = yTickLabelsWidth(probe.ticks, fonts.tick, measure, spec);
  const labelHeight = spec.tickRotation
    ? Math.max(fonts.tick, ...probe.ticks.filter((t) => !t.minor && t.label !== "").map((t) => {
      const b = xTickLabelPlacement(0, 0, fonts.tick, 0, spec.tickRotation!, measure(t.label, fonts.tick) * 1.1, "top").box; // measure under-reads
      return b.y2 - b.y1;
    }))
    : fonts.tick;
  const title = spec.title ?? fallbackTitle;
  const titleRoom = !title ? 4 : side === "right" ? rightTitleBand(spec, title, fonts.title, spec.titleGap ?? 6, measure, canvasWidth) : textBand(fonts.title, spec.titleGap ?? 6);
  const margin = side === "top"
    ? labelHeight + (spec.tickLabelGap ?? 6) + DEFAULTS.tickLen + titleRoom
    : labelWidth + DEFAULTS.tickLen + (spec.tickLabelGap ?? 8) + titleRoom;
  return { spec, type, domain, manual, format, spacing, reversed: spec.reversed ?? false, gridDensity, title, side, tickFont: fonts.tick, labelWidth, labelHeight, margin };
}

/**
 * Build the second axis's pixel scale and its AxisScene once the plot rectangle is known — down
 * the right edge (`px` → absolute y), or along the top edge on a horizontal bar chart (`px` →
 * absolute x), mirroring the bottom axis: numbers above the ticks, the title's baseline above them.
 */
export function placeSecondAxis(
  plan: SecondAxisPlan,
  rect: { x: number; y: number; width: number; height: number },
  titleFontSize: number,
): { px: (value: number) => number; axis: AxisScene } {
  if (plan.side === "top") {
    const t = buildScale(plan.type, plan.domain, plan.reversed ? [rect.width, 0] : [0, rect.width], plan.gridDensity, plan.manual, plan.format, plan.spacing);
    const labelsTop = rect.y - DEFAULTS.tickLen - (plan.spec.tickLabelGap ?? 6) - plan.labelHeight;
    return {
      px: (value) => rect.x + t.scale(value),
      axis: {
        type: plan.type,
        domain: plan.reversed ? [t.domain[1], t.domain[0]] : t.domain,
        range: [rect.x, rect.x + rect.width],
        ticks: t.ticks.map((tk) => ({ ...tk, pos: rect.x + tk.pos })),
        title: plan.title,
        titlePos: labelsTop - (plan.spec.titleGap ?? 6),
        side: "top",
        ...axisLine(plan.spec),
      },
    };
  }
  const b = buildScale(plan.type, plan.domain, plan.reversed ? [0, rect.height] : [rect.height, 0], plan.gridDensity, plan.manual, plan.format, plan.spacing);
  const labelsEnd = rect.x + rect.width + DEFAULTS.tickLen + (plan.spec.tickLabelGap ?? 8) + plan.labelWidth;
  return {
    px: (value) => rect.y + b.scale(value),
    axis: {
      type: plan.type,
      domain: plan.reversed ? [b.domain[1], b.domain[0]] : b.domain,
      range: [rect.y + rect.height, rect.y],
      ticks: b.ticks.map((t) => ({ ...t, pos: rect.y + t.pos })),
      title: plan.title,
      titleX: labelsEnd + (plan.spec.titleGap ?? 6) + titleFontSize * 0.3,
      ...axisLine(plan.spec),
    },
  };
}

/**
 * A chart with a series on its right (Y2) axis ignores the significance planner's heights.
 *
 * "Add to graph" plans every bracket height from one range pooled over every group
 * (`planAnalysisMarkers`, analysis.ts), so with a group on Y2 that height is in the wrong axis's
 * units. Read against the left axis — and folded into its range by `significanceHeadroom` — it
 * would stretch the left axis back out and leave the bracket floating. Dropping every planned
 * height, on either axis, hands the bracket to the scene's auto-placer, which reads the pixels actually drawn on both axes. A height the user dragged or
 * typed carries no `plannedY` and is never touched.
 */
export function releasePlannedHeights(plot: Plot): Plot {
  const anns = plot.annotations;
  const isPlanned = (a: NonNullable<Plot["annotations"]>[number]): boolean => a.kind === "bracket" && a.plannedY === true && a.bracketY != null;
  if (!anns?.some(isPlanned)) return plot;
  return {
    ...plot,
    annotations: anns.map((a) => {
      if (!isPlanned(a)) return a;
      const released = { ...a };
      delete released.bracketY;
      delete released.plannedY;
      return released;
    }),
  };
}

function buildDistributionScene(
  table: DataTable,
  plot: Plot,
  options: BuildPlotSceneOptions,
  kind: PlotScene["kind"],
): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  let datasets = visibleDatasets(table, plot);
  // A floating bar's box spans this range (min→max by default; percentiles or mean±SD/SEM/CI
  // when the user picks a definition — the same BoxWhisker choice box plots use). A box/violin/
  // raincloud defaults to Tukey. One kind per call, so `stats` never mixes definitions.
  const whisker: BoxWhisker = plot.boxWhisker ?? (plot.kind === "floatingbar" ? "minmax" : "tukey");

  let pooled = datasets.map((ds) => poolDatasetValues(table, ds));
  const isBoxKind = kind === "box" || kind === "violin" || kind === "raincloud";
  // A dataset entered as box values draws its box from the entered five-number summary
  // (reusing the boxStats struct + drawer). A mean±error summary can't define a box, so on
  // box/violin it draws nothing (and warns) rather than a misleading box of its mean column.
  // Everything else computes its box from the pooled raw values.
  let stats = datasets.map((ds, i) => {
    if (isBoxSummaryDataset(ds)) return summaryBoxSummary(table, ds);
    if (isBoxKind && isSummaryDataset(ds)) return EMPTY_BOX_SUMMARY;
    return boxStats(pooled[i]!, whisker);
  });
  if (isBoxKind) {
    for (const ds of datasets) {
      if (isSummaryDataset(ds) && !isBoxSummaryDataset(ds)) {
        warnings.push(`“${ds.name}” is entered as a mean±error summary — a box/violin needs raw values or a Box-values (min · Q1 · median · Q3 · max) entry, so no box is drawn for it.`);
      }
    }
  }
  // Column scatter overlays a mean ± SD on the individual replicate dots.
  let summaries = pooled.map((vals) => summarize(vals));
  if (kind === "scatter") warnings.push(...medianCiWarnings(datasets, pooled, plot.columnScatter));
  warnings.push(...smallGroupWarnings(kind, plot, datasets, pooled));

  // Sort groups (`plot.barSort`, the bar chart's Sort control reused): every per-group array is put in the drawn order
  // here, before any geometry, so ticks, marks and labels follow. Each group keeps its own palette colour
  // (`colorIndex[drawn] = table position`) and a bracket stays on its own groups (`sortPos` remaps its 1-based ends).
  const { order: colorIndex, sortPos } = distributionSortOrder(kind, plot, datasets, stats, summaries, pooled);
  if (sortPos) {
    datasets = colorIndex.map((i) => datasets[i]!);
    pooled = colorIndex.map((i) => pooled[i]!);
    stats = colorIndex.map((i) => stats[i]!);
    summaries = colorIndex.map((i) => summaries[i]!);
  }
  /** A bracket's 1-based group (table order) → its 1-based drawn position. */
  const drawnGroup = (c: number): number => (sortPos && Number.isInteger(c) && c >= 1 && c <= sortPos.length ? sortPos[c - 1]! + 1 : c);

  // Second value axis — box, violin and column scatter, then raincloud and floating bar
  // too: down the right on a vertical chart, along the top on a horizontal one - every
  // kind this builder draws. Every glyph below reads the series' own `py`. A third axis (Y3) is never
  // drawn here.
  const kindName = kind === "scatter" ? "column scatter" : kind === "floatingbar" ? "floating bar" : kind;
  const y2Ids = new Set<NodeId>();
  for (const ds of datasets) {
    const axis = plot.seriesStyles?.[ds.id]?.axis;
    if (axis === "y2") {
      y2Ids.add(ds.id);
    } else if (axis === "y3") {
      warnings.push(`“${ds.name}” asks for a third value axis (Y3), but a ${kindName} chart draws at most one second axis — it is plotted on the main axis.`);
    }
  }
  // A series on Y2 scales to its own axis, so it must not stretch the left axis as well (that
  // would squash the other series). If every series is on Y2, the left axis keeps them (nothing else to fit).
  const onY2 = (i: number): boolean => y2Ids.has(datasets[i]!.id);
  const onLeft = (i: number): boolean => y2Ids.size === 0 || y2Ids.size === datasets.length || !onY2(i);

  // Y domain over every value (incl. outliers + scatter's SD reach); marks float (no forced 0).
  // Each dataset's reach goes to the axis it is drawn on (with nothing on Y2: all of it, in the
  // original order, to the left axis).
  const allValues = pooled.flat();
  const domainValues = pooled.filter((_, i) => onLeft(i)).flat();
  const y2Values = pooled.filter((_, i) => onY2(i)).flat();
  const reach = (i: number, ...vs: number[]): void => {
    if (onLeft(i)) domainValues.push(...vs);
    if (onY2(i)) y2Values.push(...vs);
  };
  // Summary-entered boxes reach min→max, but `pooled` holds only their median cells — fold
  // each box's extremes into the domain or the whiskers/box would clip at the axis edge.
  stats.forEach((b, i) => {
    for (const v of [b.min, b.max, b.whiskerLow, b.whiskerHigh]) if (Number.isFinite(v)) reach(i, v);
  });
  if (kind === "scatter") {
    summaries.forEach((s, i) => {
      const ce = scatterCentreError(s, stats[i]!, plot.columnScatter, isSummaryDataset(datasets[i]!) ? undefined : pooled[i]);
      if (ce.low !== undefined && ce.high !== undefined) reach(i, ce.low, ce.high);
      else reach(i, ce.center);
    });
  }
  // With a series on Y2 the planner's pooled data-unit heights mean nothing on either axis —
  // the brackets are placed from the drawn pixels instead (`releasePlannedHeights`).
  const annPlot = y2Ids.size > 0 ? releasePlannedHeights(plot) : plot;
  domainValues.push(...significanceHeadroom(annPlot, domainValues));
  // Y-axis Format-Axes config (X is a categorical band, so only Y is tunable).
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const yFmt = tickFormat(ySpec);
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yRev = ySpec.reversed ?? false;
  let yType: ScaleType = options.yScale ?? ySpec.scale ?? plot.yScale ?? "linear";
  if (isLog(yType) && !domainValues.every((v) => v > 0)) {
    yType = "linear";
    warnings.push("Log Y needs all-positive values — using linear.");
  }
  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const autoYDom = buildScale(
    yType,
    extent(isLog(yType) ? domainValues.filter((v) => v > 0) : domainValues),
    [0, 1],
    gridDensity,
    false,
    yFmt,
  ).domain;
  const yData = options.yDomain ?? applyRange(ySpec, autoYDom);
  const manualY = ySpec.min != null || ySpec.max != null;
  const exactY = options.yDomain != null || manualY;
  // The natural "home" domain — the rest state ignoring any pan/zoom window. `auto` must be
  // this and not an echo of the current domain: the renderer soft-locks back to it and reads it
  // to know whether the chart is zoomed. Echoing the window would make both reads meaningless — the
  // detent could never fire and drag-to-pan could never wake up.
  const homeData: [number, number] = options.yDomain != null ? applyRange(ySpec, autoYDom) : yData;

  // The second axis's scale type and default title — shared by both orientations. A log second axis
  // is honoured like the main axis's: only over all-positive values, else said and drawn linear.
  const y2Spec: AxisSpec = plot.y2Axis ?? {};
  let y2Type: ScaleType = y2Spec.scale ?? "linear";
  if (y2Ids.size > 0 && y2Type !== "linear" && !(isLog(y2Type) && y2Values.every((v) => v > 0))) {
    warnings.push(isLog(y2Type)
      ? "Log Y2 (second axis) needs all-positive values — using linear."
      : "A probability scale is not available on the second (Y2) axis — it is drawn linear.");
    y2Type = "linear";
  }
  // No typed title: the one series on the second axis names it (as on the XY chart); two or more, none.
  const y2FallbackTitle = y2Ids.size === 1 ? (datasets.find((ds) => y2Ids.has(ds.id))?.name ?? "") : "";

  // --- horizontal distribution charts: value axis on X, category bands on Y ---
  // (Raincloud is vertical-only — its cloud/box/rain layout assumes a band X axis.)
  const horiz = kind !== "raincloud" && (plot.barOrientation ?? "vertical") === "horizontal";
  if (horiz) {
    return buildDistributionSceneHorizontal({
      table, plot, datasets, stats, summaries, pooled, kind, palette, measure,
      width, height, fonts, heading, yType, yData, homeData, yRev, yFmt, ySpacing, gridDensity, exactY, manualY, warnings,
      ramps, y2Ids, y2Values, y2Type, y2FallbackTitle, annPlot, colorIndex, drawnGroup,
    });
  }

  // The right second axis: sized now (it joins the right-margin stack), placed once the plot exists.
  const y2Plan = y2Ids.size > 0
    ? planSecondAxis(y2Spec, y2Values, y2Type, gridDensity, measure, { tick: fonts.y2Tick.size, title: (fonts.y2AxisTitle ?? fonts.yAxisTitle).size }, y2FallbackTitle, "right", width)
    : null;

  const yProbe = buildScale(yType, yData, [0, 1], gridDensity, exactY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.yTick.size, measure, plot.yAxis);
  const yLabel = ySpec.title ?? (datasets.length === 1 ? datasets[0]!.name : "");
  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (yLabel ? textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6) : 4) + pad.l;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  const leg = groupLegend(plot, datasets, palette, measure, fonts.legend.size, width);
  const y2Margin = y2Plan?.margin ?? 0;
  // The legend sits outside the Y2 axis (the right-margin stack) — as on the bar chart.
  if (y2Margin > 0) leg.layout = { ...leg.layout, outsidePad: y2Margin };
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + y2Margin + pad.r;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const yb = buildScale(yType, yData, yRev ? [0, plotH] : [plotH, 0], gridDensity, exactY, yFmt, ySpacing);
  const yDomainOut: [number, number] = yRev ? [yb.domain[1], yb.domain[0]] : yb.domain;
  const homeB: [number, number] = options.yDomain != null
    ? buildScale(yType, homeData, [0, 1], gridDensity, manualY, yFmt, ySpacing).domain
    : yb.domain;
  const autoV: [number, number] = yRev ? [homeB[1], homeB[0]] : homeB;
  const pyLeft = (v: number): number => plotY + yb.scale(v);
  const py = pyLeft;
  const leftType = yType;
  const y2Placed = y2Plan ? placeSecondAxis(y2Plan, { x: plotX, y: plotY, width: plotW, height: plotH }, (fonts.y2AxisTitle ?? fonts.yAxisTitle).size) : null;

  const n = datasets.length;
  const bandW = n > 0 ? plotW / n : plotW;

  const series: SeriesScene[] = datasets.map((ds, i) => {
    // A series on Y2 draws every glyph against the right axis. These two shadow the left axis's
    // `py` / `yType` for the rest of this callback, so the box / violin / swarm code below is unchanged.
    const py = y2Placed && onY2(i) ? y2Placed.px : pyLeft;
    const yType: ScaleType = y2Placed && onY2(i) ? y2Plan!.type : leftType;
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(colorIndex[i]!, palette);
    const boxW = bandW * Math.min(0.9, Math.max(0.1, style?.boxWidth ?? 0.5));
    const b = stats[i]!;
    const sm = summaries[i]!;
    const cx = plotX + i * bandW + bandW / 2;
    const marks: MarkScene[] = [];
    if (b.n > 0 && kind === "raincloud") {
      // Raincloud = three glyphs per group: a half-violin "cloud" (left), a narrow
      // box (centre), and a density-jittered "rain" of raw points (right). Each is a
      // separate mark so it reuses the existing violin / box / scatter glyphs.
      // The "Width" slider (boxWidth, default 0.5) scales the whole raincloud spread;
      // spread = 1 at the default, the standard look.
      const spread = (Math.min(0.9, Math.max(0.1, style?.boxWidth ?? 0.5))) / 0.5;
      const cloudCx = cx - bandW * 0.04;
      const boxCx = cx + bandW * 0.07;
      const rainCx = cx + bandW * 0.26;
      const cloud = buildViolinPath(pooled[i]!, cloudCx, bandW * 0.34 * spread, py, yType, false, style?.violinBandwidth ?? 1, "left");
      if (cloud) {
        marks.push({ rowId: `${ds.id}-cloud`, rowNumber: i + 1, dx: i + 1, dy: b.median, cx: cloudCx, cy: py(b.median), n: b.n, label: ds.name, violin: cloud });
      }
      // Inner box — honours Show-box + its own width; the rain already draws every raw
      // point, so the box omits its outlier circles (they would double-plot in the rain).
      if (style?.violinShowBox !== false) {
        const innerW = bandW * 0.1 * spread * (style?.violinBoxWidth ?? 1);
        marks.push({
          rowId: `${ds.id}-box`, rowNumber: i + 1, dx: i + 1, dy: b.median, cx: boxCx, cy: py(b.median), n: b.n, label: ds.name,
          box: { x: boxCx - innerW / 2, w: innerW, q1: py(b.q1), q3: py(b.q3), median: py(b.median), whiskerLow: py(b.whiskerLow), whiskerHigh: py(b.whiskerHigh), outliers: [], ...boxNotchOf(b, style?.boxNotch, plot.boxWhisker, py, ds.name, warnings) },
        });
      }
      marks.push({ rowId: `${ds.id}-rain`, rowNumber: i + 1, dx: i + 1, dy: sm.mean, cx: rainCx, cy: py(sm.mean), n: sm.n, label: ds.name, points: swarmPoints(pooled[i]!, rainCx, bandW * 0.13 * spread, py, yType) });
    } else if (b.n > 0) {
      const mark: MarkScene = {
        rowId: ds.id,
        rowNumber: i + 1,
        dx: i + 1,
        dy: b.median,
        cx,
        cy: py(b.median),
        n: b.n,
        label: ds.name,
      };
      if (kind === "scatter") {
        // Every replicate as a dot, swarmed by density; centre + error overlay.
        const ce = scatterCentreError(sm, b, plot.columnScatter, isSummaryDataset(ds) ? undefined : pooled[i]);
        mark.dy = ce.center;
        mark.cy = py(ce.center);
        // The Point spread control scales the swarm's spread, not just its ceiling — same ratio the
        // raincloud uses above, and 1 at the default.
        const swarmW = bandW * scatterSwarmFraction(plot, style);
        mark.points = swarmPoints(pooled[i]!, cx, swarmW / 2, py, yType, false, swarmW / (bandW * 0.5));
        if (ce.low !== undefined && ce.high !== undefined) {
          mark.errLow = ce.low;
          mark.errHigh = ce.high;
          mark.errLowCy = py(ce.low);
          mark.errHighCy = py(ce.high);
        }
      } else if (kind === "floatingbar") {
        // A bar spanning the chosen definition (min→max by default, else percentiles or
        // mean±SD/SEM/CI — from `whisker`) with a line at the centre (mean/median/none). The
        // box glyph with whiskers collapsed to the box edges (so nothing protrudes).
        const lineMode = plot.floatingBar?.line ?? "mean";
        const center = lineMode === "median" ? b.median : sm.mean;
        mark.dy = center;
        mark.cy = py(center);
        mark.box = {
          x: cx - boxW / 2, w: boxW,
          q1: py(b.whiskerLow), q3: py(b.whiskerHigh),
          median: lineMode === "none" ? null : py(center),
          whiskerLow: py(b.whiskerLow), whiskerHigh: py(b.whiskerHigh), outliers: [],
        };
      } else {
        // box and violin show the quartile box; the violin slims it inside the
        // silhouette (and can hide it via violinShowBox).
        const showBox = kind !== "violin" || (style?.violinShowBox ?? true);
        const innerW = kind === "violin" ? boxW * (style?.violinBoxWidth ?? 0.34) : boxW;
        const overlayPoints = (kind === "box" || kind === "violin") && (plot.showBoxPoints ?? false);
        if (showBox) {
          mark.box = {
            x: cx - innerW / 2,
            w: innerW,
            q1: py(b.q1),
            q3: py(b.q3),
            median: py(b.median),
            whiskerLow: py(b.whiskerLow),
            whiskerHigh: py(b.whiskerHigh),
            outliers: overlayPoints ? [] : b.outliers.map(py), // the point overlay already shows them
            ...(plot.showBoxMean ? { mean: py(sm.mean) } : {}),
            ...boxNotchOf(b, style?.boxNotch, plot.boxWhisker, py, ds.name, warnings),
          };
        } else if (plot.showBoxMean) {
          // Inner box hidden but "Show mean (+)" is on → a mean-only glyph (no box/whiskers/median).
          mark.box = { x: cx - innerW / 2, w: innerW, q1: py(b.median), q3: py(b.median), median: null, whiskerLow: py(b.median), whiskerHigh: py(b.median), outliers: [], mean: py(sm.mean), meanOnly: true };
        }
        if (kind === "violin") {
          const v = buildViolinPath(pooled[i]!, cx, boxW / 2, py, yType, false, style?.violinBandwidth ?? 1);
          if (v) mark.violin = v;
        }
        if (overlayPoints) mark.points = swarmPoints(pooled[i]!, cx, boxW / 2, py, yType, false, seriesPointSpread(plot, style), kind === "violin" ? violinHalfAt(pooled[i]!, boxW / 2, yType, style?.violinBandwidth ?? 1) : undefined);
      }
      marks.push(mark);
    }
    return {
      id: ds.id,
      name: ds.name,
      color,
      linePath: "",
      symbol: style?.symbol ?? "circle",
      symbolSize: style?.symbolSize ?? 4,
      ...resolveSymbol(style, color),
      borderWidth: style?.borderWidth ?? 1.5,
      lineWidth: style?.lineWidth ?? 2,
      dash: null,
      errorCaps: true,
      errorDir: "both",
      // Box & whisker glyph styling — whiskers/median/outliers fall back to the
      // box contour (borderColor/borderWidth) so existing boxes look unchanged.
      whiskerSides: style?.whiskerSides ?? "both",
      whiskerColor: style?.whiskerColor ?? style?.borderColor ?? color,
      whiskerWidth: style?.whiskerWidth ?? style?.borderWidth ?? 1.5,
      // floatingbar has no whiskers (they collapse to the box min/max edges), so the
      // reused BoxGlyph must not draw cap ticks at those edges.
      whiskerCaps: kind === "floatingbar" ? false : (style?.whiskerCaps ?? true),
      whiskerCapWidth: style?.whiskerCapWidth ?? 0.28,
      medianColor: style?.medianColor ?? style?.borderColor ?? color,
      medianWidth: style?.medianWidth ?? (style?.borderWidth ?? 1.5) + 0.8,
      showOutliers: style?.showOutliers ?? true,
      outlierSize: style?.outlierSize ?? 2.4,
      ...seriesExtras(style, color, style?.lineWidth ?? 2, style?.symbolSize ?? 4, 0.18),
      marks,
    };
  });

  // Value-graduated fill across the datasets (one box/violin each → normalise over all).
  if (datasets.some((ds) => plot.seriesStyles?.[ds.id]?.fillType === "graduated")) {
    const mapVal = (map: GradMap | undefined, i: number): number => {
      const m = map ?? "value";
      return m === "value" ? (stats[i]?.median ?? NaN) : m === "x" ? i + 1 : i;
    };
    datasets.forEach((ds, i) => {
      const style = plot.seriesStyles?.[ds.id];
      const mark = series[i]?.marks[0];
      if (style?.fillType !== "graduated" || !mark) return;
      const dom = datasets.map((_, j) => mapVal(style.gradMap, j));
      paintGraduated([{ mark, v: dom[i]! }], style, series[i]!.color, dom, ramps);
    });
  }

  const xticks: AxisTick[] = datasets.map((ds, i) => ({
    value: i + 1,
    pos: plotX + i * bandW + bandW / 2,
    label: ds.name,
    minor: false,
  }));

  if (datasets.length > 0 && allValues.length === 0) warnings.push("No finite data points to plot.");

  const catX = (c: number): number | undefined => {
    const d = drawnGroup(c);
    return d >= 1 && d <= n ? plotX + (d - 1) * bandW + bandW / 2 : undefined;
  };
  const annotations = buildAnnotations(
    annPlot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: null, y: (v) => (Number.isFinite(v) && (!isLog(yType) || v > 0) ? py(v) : undefined), bracketX: catX },
    undefined,
    warnings,
  );

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: "linear", band: true, domain: [0, Math.max(1, n)], range: [plotX, plotX + plotW], ticks: deOverlapX(xticks, measure, fonts.tick.size), title: plot.xAxis?.title ?? "", ...axisLine(plot.xAxis) },
    y: { type: yType, domain: yDomainOut, range: [plotY + plotH, plotY], ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yLabel, ...axisLine(plot.yAxis) },
    ...(y2Placed ? { y2: y2Placed.axis } : {}),
    auto: { x: [0, Math.max(1, n)], y: autoV },
    // Only the value axis (Y) has a numeric domain to window; X bands the categories.
    zoomable: [{ visual: "y", key: "y" }],
    series,
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: plot.xAxis?.title ?? "Group", y: yLabel || "Value" },
    kind,
    fonts,
    warnings,
  };
}

/**
 * Before-after (paired / slopegraph) chart: each row is a subject, each dataset a
 * timepoint/condition on the band X axis. A connecting line + markers trace every
 * subject's trajectory across the conditions — the classic paired-data visual.
 */
function buildBeforeAfterScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const datasets = visibleDatasets(table, plot);
  const n = datasets.length;

  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);

  const allVals: number[] = [];
  for (const row of table.rows) {
    for (const ds of datasets) {
      const v = rowDatasetMean(row, ds);
      if (Number.isFinite(v)) allVals.push(v);
    }
  }
  // Honour the value axis's Scale (linear / log) + Range (min/max) + Ticks + Numbering.
  // A log value axis is legitimate here (e.g. viral loads before/after treatment); values
  // ≤ 0 can't be placed on it, so they're dropped per point (a subject then loses that end
  // of its connecting line) rather than forcing the whole axis back to linear.
  const ySpec: AxisSpec = plot.yAxis ?? {};
  let yType: ScaleType = options.yScale ?? ySpec.scale ?? plot.yScale ?? "linear";
  const posVals = allVals.filter((v) => v > 0);
  if (isLog(yType) && posVals.length === 0) {
    yType = "linear";
    warnings.push("Log value axis needs positive values — using linear.");
  }
  const logY = isLog(yType);
  if (logY && posVals.length < allVals.length) {
    warnings.push("Log value axis: non-positive values are omitted (their points and connecting lines are dropped).");
  }
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yFmt = tickFormat(ySpec);
  const yRev = ySpec.reversed ?? false;
  const wy = windowed(ySpec, (logY ? posVals : allVals).length ? extent(logY ? posVals : allVals) : ([0, 1] as [number, number]), options.yDomain);
  const yDom = wy.data;
  const manualY = wy.manual;
  const yLabel = plot.yAxis?.title ?? "Value";

  const yProbe = buildScale(yType, yDom, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);

  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6)) + pad.l;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  /*
   * Note: before–after legends the subjects, not the two conditions. Its series are the rows — one
   * trajectory each, each separately selectable and colourable — while `Pre` / `Post` are the two
   * x ticks. A per-column legend would name the axis; a per-subject one names the lines, which is
   * the thing a reader cannot otherwise tell apart. Off by default (a 40-patient key is rarely
   * wanted, and a saved figure must not change).
   *
   * Built here, before the margin, from the same row → label / colour rules the series loop uses
   * below; `beforeafter-legend.test.ts` holds the two in step.
   */
  const defColor = seriesColor(0, palette);
  const xCol = xColumn(table);
  const subjectLabel = (row: Row, i: number): string =>
    xCol ? String(row.cells[xCol.id] ?? `Subject ${i + 1}`) : `Subject ${i + 1}`;
  const hasPoint = (row: Row): boolean =>
    datasets.some((ds) => { const v = rowDatasetMean(row, ds); return Number.isFinite(v) && (!logY || v > 0); });
  const leg = resolveLegend(
    { ...plot, legend: { ...plot.legend, show: plot.legend?.show ?? false } },
    // A before-after legend row is one subject (a table row), styled through
    // `seriesStyles[row.id]` — so the row points at that id, not at a column.
    table.rows.filter(hasPoint).map((row, i) => ({
      label: subjectLabel(row, i),
      color: effectiveMarkerStyle(plot, plot.seriesStyles?.[row.id])?.color ?? defColor,
      select: { as: "series" as const, id: row.id },
    })),
    measure,
    fonts.legend.size,
    width,
  );
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const yb = buildScale(yType, yDom, yRev ? [0, plotH] : [plotH, 0], gridDensity, manualY, yFmt, ySpacing);
  const bandW = n > 0 ? plotW / n : plotW;
  const catX = (j: number): number => plotX + j * bandW + bandW / 2; // j 0-based
  const py = (v: number): number => plotY + yb.scale(v);

  // Each subject (row) is its own selectable series — per-subject line/marker/colour
  // overrides apply (click a trajectory → edit it), so nothing is "dead".
  // (`defColor` / `xCol` / `subjectLabel` are defined above, with the legend that mirrors them.)
  const series: SeriesScene[] = table.rows
    .map((row, i) => {
      const style = effectiveMarkerStyle(plot, plot.seriesStyles?.[row.id]);
      const color = style?.color ?? defColor;
      const lineWidth = style?.lineWidth ?? 1.5;
      const symbolSize = style?.symbolSize ?? 3;
      const pts = datasets
        .map((ds, j) => ({ j, v: rowDatasetMean(row, ds) }))
        .filter((p) => Number.isFinite(p.v) && (!logY || p.v > 0));
      const marks: MarkScene[] = pts.map((p) => ({
        rowId: row.id,
        rowNumber: i + 1,
        dx: p.j + 1,
        dy: p.v,
        cx: catX(p.j),
        cy: py(p.v),
        n: 1,
      }));
      const lineCurve = curveFor(style?.connect ?? "straight", style?.lineTension ?? 0.5);
      const linePath =
        marks.length >= 2 && (style?.connect ?? "straight") !== "none"
          ? d3line<MarkScene>().x((m) => m.cx).y((m) => m.cy).curve(lineCurve)(marks) ?? ""
          : "";
      return {
        id: row.id,
        name: subjectLabel(row, i),
        color,
        // Linked (default) → line follows the subject colour; unlinked → its own.
        lineColor: style?.linkLineColor === false ? (style?.lineColor ?? color) : color,
        linePath,
        symbol: style?.symbol ?? ("circle" as const),
        symbolSize,
        ...resolveSymbol(style, color),
        borderWidth: style?.borderWidth ?? 1,
        lineWidth,
        dash: dashArray(style?.lineDash ?? "solid", lineWidth),
        errorCaps: false,
        errorDir: "both" as const,
        ...seriesExtras(style, color, lineWidth, symbolSize, 1),
        marks,
      };
    })
    .filter((s) => s.marks.length > 0);

  const xticks: AxisTick[] = datasets.map((ds, j) => ({ value: j + 1, pos: catX(j), label: ds.name, minor: false }));
  if (n < 2) warnings.push("Before-after needs ≥ 2 conditions (columns).");

  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: null, y: (v) => (Number.isFinite(v) && (!logY || v > 0) ? py(v) : undefined), bracketX: (c) => (c >= 1 && c <= n ? catX(c - 1) : undefined) },
    undefined,
    warnings,
  );

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: "linear", band: true, domain: [0, Math.max(1, n)], range: [plotX, plotX + plotW], ticks: deOverlapX(xticks, measure, fonts.tick.size), title: plot.xAxis?.title ?? "", ...axisLine(plot.xAxis) },
    y: { type: yType, domain: yRev ? [yb.domain[1], yb.domain[0]] : yb.domain, range: [plotY + plotH, plotY], ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yLabel, ...axisLine(plot.yAxis) },
    auto: { x: [0, Math.max(1, n)], y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain },
    // Each subject is a line between two bands on X; only the measurement axis has a domain.
    zoomable: [{ visual: "y", key: "y" }],
    series,
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "Condition", y: yLabel || "Value" },
    kind: "beforeafter",
    fonts,
    warnings,
  };
}

/**
 * Pie chart: each dataset is a slice proportional to the sum of its (positive)
 * values. No axes — a centred pie with %-labels and a legend per slice.
 */
function buildPieScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const datasets = visibleDatasets(table, plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);

  // Parts-of-whole semantics: each row is a slice of one whole (the first value
  // column), labelled by the leading label column. Every other format keeps the
  // one-slice-per-dataset model (each column's total = one slice).
  const xCol = xColumn(table);
  // A parts-of-whole table with more than one value column is more than one whole (one column per
  // sample), so it draws small multiples — a grid of pies, one per column, built further down.
  const multiWhole = table.kind === "partsofwhole" && datasets.length > 1;
  // In a parts-of-whole pie each row is a slice but there is one value column, so the pie's
  // per-slice look (two-tone fill/stroke, slice explode) — set by the house defaults + preset on
  // the column's series style — must reach every row-slice, or a row-pie would draw flat next to
  // a column-pie. Each slice inherits the value column's style as its base, with a per-row style
  // override on top; the slice keeps its own palette colour (never the column's), so the two-tone
  // stroke shades each slice's own hue and a per-slice edit still wins.
  const colStyle = table.kind === "partsofwhole" && datasets.length >= 1 ? plot.seriesStyles?.[datasets[0]!.id] : undefined;
  const rawAll =
    table.kind === "partsofwhole" && datasets.length >= 1
      ? table.rows
          .map((row, i) => {
            const v = toNumber(row.cells[datasets[0]!.id]);
            if (Number.isFinite(v) && v < 0) warnings.push("Negative values are ignored in a pie chart.");
            const rowStyle = plot.seriesStyles?.[row.id];
            const style = colStyle || rowStyle ? { ...colStyle, ...rowStyle } : undefined;
            const label = xCol ? String(row.cells[xCol.id] ?? `Slice ${i + 1}`).trim() || `Slice ${i + 1}` : `Slice ${i + 1}`;
            return { id: row.id, label, color: rowStyle?.color ?? seriesColor(i, palette), value: Number.isFinite(v) && v > 0 ? v : 0, style };
          })
          .filter((s) => s.value > 0)
      : datasets.map((ds, i) => {
          const vals = poolDatasetValues(table, ds);
          if (vals.some((v) => v < 0)) warnings.push("Negative values are ignored in a pie chart.");
          const style = plot.seriesStyles?.[ds.id];
          return {
            id: ds.id,
            label: ds.name,
            color: style?.color ?? seriesColor(i, palette),
            value: vals.reduce((a, b) => a + (b > 0 ? b : 0), 0),
            style,
          };
        });
  // Waffle: small groups combined (`waffleMaxGroups`). The N largest groups keep
  // their place in table order; the rest become one group, last, neutral grey unless styled
  // (`seriesStyles[WAFFLE_OTHER_ID]`), named `waffleOtherName` or "Other". A single leftover is
  // left alone: folding one group into "Other" would only hide its name. Waffle only.
  const maxGroups = plot.pieDisplay === "waffle" && !multiWhole && plot.waffleMaxGroups != null ? Math.max(1, Math.floor(plot.waffleMaxGroups)) : undefined;
  let raw: typeof rawAll = rawAll;
  if (maxGroups != null && rawAll.length > maxGroups + 1) {
    const keep = new Set([...rawAll].sort((a, b) => b.value - a.value).slice(0, maxGroups).map((r) => r.id));
    const rest = rawAll.filter((r) => !keep.has(r.id));
    const otherStyle = plot.seriesStyles?.[WAFFLE_OTHER_ID];
    const style = colStyle || otherStyle ? { ...colStyle, ...otherStyle } : undefined;
    raw = [
      ...rawAll.filter((r) => keep.has(r.id)),
      { id: WAFFLE_OTHER_ID, label: plot.waffleOtherName?.trim() || "Other", color: otherStyle?.color ?? WAFFLE_OTHER_COLOR, value: rest.reduce((a, b) => a + b.value, 0), style },
    ];
  }
  const total = raw.reduce((a, b) => a + b.value, 0);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // A legend row is a slice, and `r.id` is the same key the slice's own click uses (a row id
  // for a parts-of-whole table, a dataset id otherwise) — so the row selects the slice it
  // names. A pie has no `scene.series`, so name-matching would find nothing at all.
  // Icon array (waffle display + `waffleIcons`): each category draws as one shape — its own
  // `symbol` if it has one that draws, else the icon cycle by category order — in the cells and
  // in its legend row, so the key reads without colour.
  const wantIcons = plot.pieDisplay === "waffle" && plot.waffleIcons === true && !multiWhole;
  const iconShapeOf = (r: { style?: SeriesStyle | undefined }, i: number): SymbolShape =>
    r.style?.symbol && r.style.symbol !== "none" ? r.style.symbol : WAFFLE_ICON_CYCLE[i % WAFFLE_ICON_CYCLE.length]!;
  // A two-tone category's key takes the icons' light fill + darker edge, as its cells do.
  const iconKey = (r: RawSlice, i: number): Partial<Pick<LegendEntry, "symbol" | "color" | "outline">> =>
    r.style?.fillType === "twotone"
      ? { symbol: iconShapeOf(r, i), color: twoToneFill(r.color, r.style?.twoToneTint), outline: twoToneContour(r.color, r.style?.twoToneShade) }
      : { symbol: iconShapeOf(r, i) };
  /**
   * A key matches what it names — colour and shape. A two-tone slice is drawn in its light tint with a darker
   * edge, so its key takes the same tint and edge rather than the full colour; and a key should match its mark
   * wherever it can, rather than a line with a dot beside round wedges and square cells.
   * A waffle's key is a square, a pie's a wedge, each in the slice's own fill + edge.
   */
  const plainKey = (r: RawSlice): Partial<Pick<LegendEntry, "color" | "outline" | "swatch" | "keyShape">> => {
    const shape = { keyShape: plot.pieDisplay === "waffle" ? ("square" as const) : ("wedge" as const) };
    if (r.style?.fillType !== "twotone") return { swatch: "bar", ...shape };
    return { swatch: "bar", ...shape, color: twoToneFill(r.color, r.style?.twoToneTint), outline: twoToneContour(r.color, r.style?.twoToneShade) };
  };
  const leg = resolveLegend(plot, raw.map((r, i) => ({ label: r.label, color: r.color, ...(wantIcons ? iconKey(r, i) : plainKey(r)), select: { as: "pie-slice" as const, id: r.id } })), measure, fonts.legend.size, width);
  // Edge gaps: 10px, as the venn (the 18px axis-chart margin would be room nothing on a pie uses).
  const PIE_EDGE = 10;
  const marginRight = PIE_EDGE + leg.outsideRightWidth + pad.r;
  const plotX = PIE_EDGE + pad.l;
  // Just below the heading (a further marginTop would leave a band the fitted pie could not use).
  const plotY = topPad > 0 ? topPad + 6 : DEFAULTS.marginTop;
  const plotW = Math.max(1, width - plotX - marginRight);
  // Note: `pad.b` and `pad.l` (above) must be applied here: top and right are folded into `topPad`
  // and `marginRight`, but the other two sides are not. An axis-less kind has no axis margin to
  // absorb them, so all four have to be applied by hand.
  const plotH = Math.max(1, height - plotY - PIE_EDGE - pad.b);
  const cx = plotX + plotW / 2;
  const cy = plotY + plotH / 2;
  // Leave headroom for outside labels + exploded slices.
  const maxExplode = Math.max(0, ...raw.map((d) => d.style?.sliceExplode ?? 0));
  const labelPos = plot.pieLabelPosition ?? "inside";
  const rim = labelPos === "outside" ? 0.26 : 0.06;
  const radiusFor = (side: number): number => Math.max(10, side / 2 - 8 - side * (rim + maxExplode) * 0.5);
  const r = radiusFor(Math.min(plotW, plotH)); // base CIRCULAR radius — arc paths stay circular
  // sx/sy: the wedge + label scale hooks. A pie is always round: turning `stretch` into an
  // ellipse filling the box would deform it, so `stretch` centres the circle in the box instead,
  // and both stay 1.
  const sx = 1; // a pie is always round: stretching it would deform it
  const sy = 1;

  // Rotation + sweep direction (d3 angles: 0 = 12 o'clock, +ve clockwise).
  const start = ((plot.pieStartAngle ?? 0) * Math.PI) / 180;
  const end = (plot.pieDirection ?? "cw") === "ccw" ? start - 2 * Math.PI : start + 2 * Math.PI;
  const innerFrac = Math.max(0, Math.min(0.9, plot.pieDonut ?? 0));
  const fmtVal = (v: number): string => (Number.isInteger(v) ? String(v) : v.toFixed(1));
  const labelFor = (mode: PieLabelMode, d: { label: string; value: number }, frac: number): string => {
    const pct = `${Math.round(frac * 100)}%`;
    switch (mode) {
      case "none": return "";
      case "value": return fmtVal(d.value);
      case "label": return d.label;
      case "label-percent": return `${d.label} ${pct}`;
      case "label-value": return `${d.label} ${fmtVal(d.value)}`;
      default: return pct;
    }
  };
  // Build the wedges for one pie centred at (pcx,pcy) with radius pr — shared by the single pie
  // and by each small-multiple panel, so both draw identically (explode, two-tone, labels).
  type RawSlice = { id: string; label: string; color: string; value: number; style?: SeriesStyle | undefined };
  const makeSlices = (rawSlices: RawSlice[], pcx: number, pcy: number, pr: number, psx: number, psy: number, labelScale = 1): PieSlice[] => {
    const ptotal = rawSlices.reduce((a, b) => a + b.value, 0);
    const innerR = innerFrac * pr;
    const arcs = d3pie<RawSlice>().sort(null).startAngle(start).endAngle(end).value((d) => d.value)(rawSlices);
    const arcGen = d3arc<(typeof arcs)[number]>().innerRadius(innerR).outerRadius(pr);
    // A small-multiple panel is a smaller pie, so its slice labels shrink with it (labelScale < 1)
    // and hide a touch sooner, keeping the grid legible instead of overrunning each small wedge.
    const baseLabelFont: ResolvedFont | undefined =
      labelScale !== 1 ? { ...fonts.sliceLabel, size: Math.max(8, Math.round(fonts.sliceLabel.size * labelScale)) } : undefined;
    const hideBelow = 0.04 / Math.max(0.4, labelScale);
    return arcs.map((a, i) => {
      const d = rawSlices[i]!;
      const mid = (a.startAngle + a.endAngle) / 2;
      const ux = Math.sin(mid);
      const uy = -Math.cos(mid);
      const explode = (d.style?.sliceExplode ?? 0) * pr;
      const ox = ux * explode;
      const oy = uy * explode;
      const fraction = ptotal > 0 ? d.value / ptotal : 0;
      const inside = labelPos === "inside";
      const c = arcGen.centroid(a); // midpoint between inner/outer radius
      const lr = pr + fonts.legend.size * 0.9;
      // The offset from the centre is scaled by (psx, psy); every caller passes 1, since a pie is always round.
      const labelX = inside ? pcx + ox + c[0] * psx : pcx + ox + ux * lr * psx;
      const labelY = inside ? pcy + oy + c[1] * psy : pcy + oy + uy * lr * psy;
      let text = labelFor(d.style?.sliceLabel ?? plot.pieLabels ?? "percent", d, fraction);
      if (inside && fraction < hideBelow) text = ""; // too small to label inside cleanly
      // Per-slice label font override (size / bold / italic) layered on the shared font (which is
      // already panel-scaled via `baseLabelFont` when this is a small-multiple panel).
      const sb = d.style;
      const labelFont: ResolvedFont | undefined =
        sb?.sliceLabelSize != null || sb?.sliceLabelBold != null || sb?.sliceLabelItalic != null || baseLabelFont
          ? {
              ...(baseLabelFont ?? fonts.sliceLabel),
              ...(sb?.sliceLabelSize != null ? { size: sb.sliceLabelSize } : {}),
              ...(sb?.sliceLabelBold != null ? { weight: sb.sliceLabelBold ? 700 : 400 } : {}),
              ...(sb?.sliceLabelItalic != null ? { italic: sb.sliceLabelItalic } : {}),
            }
          : undefined;
      // Two-tone: a slice's fill lightens its base hue and its border darkens it.
      const sliceTwoTone = d.style?.fillType === "twotone";
      const sliceFill = sliceTwoTone ? twoToneFill(d.color, d.style?.twoToneTint) : d.color;
      // Per-slice label drag offset + text override (reuses the value-label plumbing).
      const loff = plot.pointStyles?.[`${d.id}:${d.id}`];
      return {
        id: d.id,
        label: d.label,
        color: sliceFill,
        value: d.value,
        fraction,
        path: arcGen(a) ?? "",
        ox,
        oy,
        labelX,
        labelY,
        // A renamed slice label wins over the generated label/percent/value readout (blank
        // restores it). Presentation only — the slice's data is untouched. The `text === ""`
        // case above (a sliver too small to label inside) still wins: an override can't force
        // a label back into a slice with no room for it.
        labelText: text === "" ? text : loff?.valueText ?? text,
        labelInside: inside,
        // Inside labels are white; on a pale fill (a two-tone tint) white does not read, so the ink follows the fill.
        ...(inside && contrastInk(sliceFill, "#fff") !== "#fff" ? { labelInk: contrastInk(sliceFill) } : {}),
        ...(loff?.valueDx != null ? { labelDx: loff.valueDx } : {}),
        ...(loff?.valueDy != null ? { labelDy: loff.valueDy } : {}),
        ...(labelFont ? { labelFont } : {}),
        strokeColor: sliceTwoTone ? twoToneContour(d.color, d.style?.twoToneShade) : (d.style?.sliceStroke ?? null),
        strokeWidth: d.style?.sliceStrokeWidth ?? (sliceTwoTone ? 2 : 1.5),
      };
    });
  };
  /**
   * One pie fills its plot rect. The radius above is a flat rule — side/2 − 8 − side·(rim + the
   * largest explode)·½ reserved on every side, around a centred disc — while a slice only moves out
   * along its own direction by explode·r. That rule alone can leave wide blank bands beside the
   * pie, so the drawing is grown inside its box.
   *
   * The slice angles do not depend on the radius, so the drawn extent — every wedge where it actually
   * sits after its explode, its border, and the slice labels — is computed exactly at two radii, the
   * straight line solved for the largest radius that fits the rect, checked, and the drawing (not the
   * disc) centred. Small multiples and the waffle keep their own layout; a stretched box gets the same round fit.
   */
  let pieCx = cx;
  let pieCy = cy;
  let pieR = r;
  if (!multiWhole && plot.pieDisplay !== "waffle" && raw.length > 0) { // stretch too: a round pie grows to fill the box
    const arcsFit = d3pie<RawSlice>().sort(null).startAngle(start).endAngle(end).value((d) => d.value)(raw);
    const extentAt = (R: number): { x0: number; y0: number; x1: number; y1: number } => {
      const sl = makeSlices(raw, 0, 0, R, 1, 1);
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      const pt = (x: number, y: number): void => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); };
      arcsFit.forEach((a, i) => {
        const s = sl[i]!;
        const half = s.strokeWidth / 2;
        const inner = innerFrac * R;
        if (inner <= 0) pt(s.ox, s.oy);
        for (let k = 0; k <= 48; k++) {
          const t = a.startAngle + ((a.endAngle - a.startAngle) * k) / 48;
          pt(s.ox + Math.sin(t) * (R + half), s.oy - Math.cos(t) * (R + half));
          if (inner > 0) pt(s.ox + Math.sin(t) * inner, s.oy - Math.cos(t) * inner);
        }
        if (s.labelText) {
          const size = (s.labelFont ?? fonts.sliceLabel).size;
          const hw = measure(s.labelText, size) / 2;
          const baseline = s.labelY + size * 0.34;
          pt(s.labelX - hw, baseline - size * 0.8);
          pt(s.labelX + hw, baseline + size * 0.25);
        }
      });
      return { x0, y0, x1, y1 };
    };
    const e1 = extentAt(100);
    const e2 = extentAt(200);
    const kx = (e2.x1 - e2.x0 - (e1.x1 - e1.x0)) / 100;
    const ky = (e2.y1 - e2.y0 - (e1.y1 - e1.y0)) / 100;
    const bx = e1.x1 - e1.x0 - kx * 100;
    const by = e1.y1 - e1.y0 - ky * 100;
    let R = Math.max(10, Math.min(kx > 1e-9 ? (plotW - bx) / kx : Infinity, ky > 1e-9 ? (plotH - by) / ky : Infinity));
    for (let pass = 0; pass < 6; pass++) {
      const e = extentAt(R);
      const w = e.x1 - e.x0, h = e.y1 - e.y0;
      if ((w <= plotW + 0.5 && h <= plotH + 0.5) || R <= 10) break;
      R = Math.max(10, R * Math.min(plotW / w, plotH / h) * 0.995);
    }
    const e = extentAt(R);
    pieR = R;
    pieCx = plotX + (plotW - (e.x1 - e.x0)) / 2 - e.x0;
    pieCy = plotY + (plotH - (e.y1 - e.y0)) / 2 - e.y0;
  }
  const slices = makeSlices(raw, pieCx, pieCy, pieR, sx, sy);

  // Waffle / square-grid display: the same slices (colour · id · label · two-tone) laid out as a
  // 10×10 grid of unit cells, each ≈ 1% of the whole, filled bottom-up left-to-right. Cell counts
  // use a largest-remainder allocation so they total exactly 100. Reuses the row-slice `raw`, the
  // legend and the `pie-slice` selection id — only the mark changes.
  //
  // Count waffle (`waffleUnit: "count"`): one cell per observation instead of 1 %. Above
  // 100 observations one cell stands for `perCell` of them (the grid stays at about 100
  // cells), the grid is sized to the count (square cells, no wider or taller
  // than 2.5 : 1, as large as fits) and a caption under it says what one cell is.
  const wantWaffle = plot.pieDisplay === "waffle";
  const countMode = wantWaffle && plot.waffleUnit === "count" && !multiWhole;
  const obsTotal = raw.reduce((a, b) => a + b.value, 0);
  const perCell = countMode ? Math.max(1, Math.ceil(Math.round(obsTotal) / 100)) : 1;
  const cellTotal = countMode ? Math.round(obsTotal / perCell) : 100;
  if (countMode && raw.some((r) => !Number.isInteger(r.value))) warnings.push("Some counts are not whole numbers - each cell is one observation, so they were rounded.");
  const captionH = countMode ? fonts.legend.size * 1.8 : 0;
  const gridOf = (n: number, w: number, h: number): { cols: number; rows: number } => {
    if (!countMode) return { cols: 10, rows: 10 };
    let best = { cols: 1, rows: Math.max(1, n), cell: -1 };
    for (let c = 1; c <= Math.max(1, n); c++) {
      const r = Math.max(1, Math.ceil(n / c));
      if (Math.max(c / r, r / c) > 2.5) continue;
      const cell = Math.min(w / c, h / r);
      if (cell > best.cell + 1e-9) best = { cols: c, rows: r, cell };
    }
    return { cols: best.cols, rows: best.rows };
  };
  let caption: NonNullable<PieScene["caption"]> | undefined;
  const makeCells = (rawSlices: RawSlice[], areaX: number, areaY: number, areaW: number, areaH: number): WaffleCell[] => {
    const totalCells = cellTotal;
    const t = rawSlices.reduce((a, b) => a + b.value, 0);
    if (t <= 0) return [];
    const exact = rawSlices.map((s) => (s.value / t) * totalCells);
    const counts = exact.map((e) => Math.floor(e));
    let used = counts.reduce((a, b) => a + b, 0);
    // Hand the leftover cells to the largest fractional remainders first (largest-remainder rule).
    const order = exact.map((e, i) => ({ i, frac: e - Math.floor(e) })).sort((a, b) => b.frac - a.frac);
    for (let k = 0; used < totalCells && k < order.length; k++, used++) counts[order[k]!.i]!++;
    const gh = Math.max(1, areaH - captionH);
    const { cols, rows } = gridOf(totalCells, areaW, gh);
    const cell = Math.min(areaW / cols, gh / rows);
    const gap = cell * 0.14;
    const ox = areaX + (areaW - cols * cell) / 2;
    const oy = areaY + (gh - rows * cell) / 2;
    if (countMode) {
      const unit = plot.waffleUnitName?.trim() || "observation";
      const units = perCell === 1 || unit.endsWith("s") ? unit : `${unit}s`;
      const auto = `1 ${plot.waffleIcons ? "icon" : "square"} = ${perCell} ${units}`;
      caption = {
        text: plot.waffleCaption?.trim() ? plot.waffleCaption : auto,
        x: ox + (cols * cell) / 2,
        y: oy + rows * cell + fonts.legend.size * 1.2,
        ...(plot.waffleCaptionOffset ? { offset: plot.waffleCaptionOffset } : {}),
      };
    }
    const cells: WaffleCell[] = [];
    let idx = 0;
    rawSlices.forEach((s, ci) => {
      const twoTone = s.style?.fillType === "twotone";
      const fill = twoTone ? twoToneFill(s.color, s.style?.twoToneTint) : s.color;
      // A two-tone category's cells carry the darker edge, as its icons and its pie wedges do.
      const edge = twoTone ? { outline: twoToneContour(s.color, s.style?.twoToneShade) } : {};
      const icon = wantIcons ? { shape: iconShapeOf(s, ci), ...edge } : edge;
      for (let c = 0; c < counts[ci]!; c++, idx++) {
        const col = idx % cols;
        const rowFromBottom = rows - 1 - Math.floor(idx / cols); // fill the bottom row first, upward
        cells.push({ x: ox + col * cell + gap / 2, y: oy + rowFromBottom * cell + gap / 2, w: cell - gap, h: cell - gap, color: fill, id: s.id, label: s.label, ...icon });
      }
    });
    return cells;
  };
  // A legend placed in a corner of the plot (top/bottom, left/right) sits over the plot area. The grid
  // fills the plot, so it keeps clear of that side instead of running under the legend.
  const legPos = leg.layout.position;
  const legSide = legPos === "topright" || legPos === "bottomright" ? "right" : legPos === "topleft" || legPos === "bottomleft" ? "left" : undefined;
  const legReserve = legSide && leg.entries.length ? legendBoxWidth(leg.layout, leg.entries.map(legendLabelText), fonts.legend.size) + (leg.layout.inset ?? 8) + 6 : 0;
  const cells = wantWaffle && !multiWhole ? makeCells(raw, plotX + (legSide === "left" ? legReserve : 0), plotY, Math.max(1, plotW - legReserve), plotH) : undefined;
  if (wantWaffle && multiWhole) warnings.push("Waffle display applies to a single whole — small multiples are drawn as pies.");

  // Small multiples: one pie per value column (whole), laid out in a grid, sharing one legend and
  // one colour per slice-category (the rows). Each panel's slices keep the row id, so a category is
  // one colour and one selection target across every panel.
  let panels: PiePanel[] | undefined;
  if (multiWhole) {
    const n = datasets.length;
    const cols = Math.ceil(Math.sqrt(n));
    const rowsN = Math.ceil(n / cols);
    const cellW = plotW / cols;
    const cellH = plotH / rowsN;
    const titleH = fonts.legend.size * 1.4; // room for the whole's name above each pie
    const panelR = Math.max(10, Math.min(cellW, cellH - titleH) / 2 - 10 - Math.min(cellW, cellH - titleH) * (rim + maxExplode) * 0.5);
    panels = datasets.map((ds, di) => {
      const gc = di % cols;
      const gr = Math.floor(di / cols);
      const pcx = plotX + gc * cellW + cellW / 2;
      const pcy = plotY + gr * cellH + titleH + (cellH - titleH) / 2;
      const dsStyle = plot.seriesStyles?.[ds.id]; // this whole's house/preset series style (two-tone, explode)
      const rawPanel: RawSlice[] = table.rows
        .map((row, i) => {
          const v = toNumber(row.cells[ds.id]);
          const rowStyle = plot.seriesStyles?.[row.id];
          const style = dsStyle || rowStyle ? { ...dsStyle, ...rowStyle } : undefined;
          const label = xCol ? String(row.cells[xCol.id] ?? `Slice ${i + 1}`).trim() || `Slice ${i + 1}` : `Slice ${i + 1}`;
          return { id: row.id, label, color: rowStyle?.color ?? seriesColor(i, palette), value: Number.isFinite(v) && v > 0 ? v : 0, style };
        })
        .filter((s) => s.value > 0);
      return {
        cx: pcx,
        cy: pcy,
        r: panelR,
        title: ds.name,
        titleX: pcx,
        titleY: plotY + gr * cellH + fonts.legend.size,
        slices: makeSlices(rawPanel, pcx, pcy, panelR, 1, 1, Math.max(0.55, Math.min(1, panelR / r))),
      };
    });
  }
  if (!multiWhole && total <= 0) warnings.push("No positive values to chart.");

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "pie",
    fonts,
    pie:
      multiWhole && panels && panels.length
        ? { cx: panels[0]!.cx, cy: panels[0]!.cy, r: panels[0]!.r, slices: panels[0]!.slices, panels }
        : { cx: pieCx, cy: pieCy, r: pieR, slices, ...(cells && cells.length ? { cells } : {}), ...(caption && cells && cells.length ? { caption } : {}) },
    warnings,
  };
}

/**
 * Voronoi treemap (kind "treemap"): each row becomes a convex cell whose area is
 * proportional to its value, tiling a boundary (circle/ellipse/rect). Same data
 * read as a pie (label column + first value column, or one cell per dataset);
 * the tessellation replaces the wedges.
 */
/**
 * How far above its label a treemap cell's icon sits, in ems.
 *
 * Note: derived, not chosen. The icon draws at 1.35em and its box reaches 0.3 × that (= 0.405em)
 * below its own baseline, while a label's box starts 0.85em above its baseline. A 1.15em lift
 * would therefore always overlap the two by ~0.1em, so every icon would graze its own cell's
 * name. 0.85 + 0.405 = 1.255, so 1.35 is the smallest round lift that clears it.
 *
 * Module scope on purpose: the placement pass and the de-confliction pass both compute the
 * icon's y from it. Duplicating the number would let the fit test and the collision test
 * disagree about where the icon actually is.
 */
const TREEMAP_ICON_LIFT = 1.35;

function buildTreemapScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const datasets = visibleDatasets(table, plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const ts = plot.treemap ?? {};

  // Colour cells by a category ("region") column — parts-of-whole tables only.
  const groupCol = ts.groupColumn && table.kind === "partsofwhole" && table.columns.some((c) => c.id === ts.groupColumn) ? ts.groupColumn : undefined;
  // Per-cell icon/emoji column (a flag or symbol drawn atop each cell) — parts-of-whole only.
  const iconCol = ts.iconColumn && table.kind === "partsofwhole" && table.columns.some((c) => c.id === ts.iconColumn) ? ts.iconColumn : undefined;

  // Parts-of-whole semantics (identical to the pie): each row is a cell of one
  // whole (the first value column), labelled by the leading label column; any
  // other table shape falls back to one cell per dataset (column total). Each cell
  // carries its explicit override (seriesStyles) + palette fallback + group tag;
  // the final fill is resolved by `colorFor` once group hues are known.
  const xCol = xColumn(table);
  if (table.kind === "partsofwhole" && datasets.length > 1) {
    warnings.push(`Only the first value column (${datasets[0]!.name}) is charted; ${datasets.length - 1} other value column${datasets.length > 2 ? "s are" : " is"} ignored.`);
  }
  const raw =
    table.kind === "partsofwhole" && datasets.length >= 1
      ? table.rows
          .map((row, i) => {
            const v = toNumber(row.cells[datasets[0]!.id]);
            if (Number.isFinite(v) && v < 0) warnings.push("Negative values are ignored in a treemap.");
            const style = plot.seriesStyles?.[row.id];
            const label = xCol ? String(row.cells[xCol.id] ?? `Cell ${i + 1}`).trim() || `Cell ${i + 1}` : `Cell ${i + 1}`;
            const group = groupCol ? String(row.cells[groupCol] ?? "").trim() : undefined;
            const icon = iconCol ? String(row.cells[iconCol] ?? "").trim() : undefined;
            return { id: row.id, label, override: style?.color, stroke: style?.sliceStroke, strokeWidth: style?.sliceStrokeWidth, paletteColor: seriesColor(i, palette), value: Number.isFinite(v) && v > 0 ? v : 0, group, icon };
          })
          .filter((s) => s.value > 0)
      : datasets.map((ds, i) => {
          const vals = poolDatasetValues(table, ds);
          if (vals.some((v) => v < 0)) warnings.push("Negative values are ignored in a treemap.");
          const style = plot.seriesStyles?.[ds.id];
          return { id: ds.id, label: ds.name, override: style?.color, stroke: style?.sliceStroke, strokeWidth: style?.sliceStrokeWidth, paletteColor: seriesColor(i, palette), value: vals.reduce((a, b) => a + (b > 0 ? b : 0), 0), group: undefined as string | undefined, icon: undefined as string | undefined };
        });
  if (raw.length === 0) warnings.push("No positive values to chart.");

  // Group colouring: each distinct group gets a palette hue (in first-appearance
  // order); cells within a group are shaded lighter for smaller values so the
  // biggest cell shows the group's true hue.
  const groupOrder: string[] = [];
  const members = new Map<string, typeof raw>(); // group value → its cells (in row order)
  const groupHue = new Map<string, string>(); // cell id → resolved group colour
  if (groupCol) {
    for (const r of raw) {
      const g = r.group ?? "";
      if (!members.has(g)) { members.set(g, []); groupOrder.push(g); }
      members.get(g)!.push(r);
    }
    groupOrder.forEach((g, gi) => {
      const base = seriesColor(gi, palette);
      const ms = members.get(g)!.slice().sort((a, b) => b.value - a.value);
      const m = ms.length;
      ms.forEach((r, k) => {
        const t = m > 1 ? k / (m - 1) : 0; // 0 (largest = base hue) .. 1 (smallest = lightest)
        groupHue.set(r.id, mix(base, "#ffffff", t * 0.55));
      });
    });
  }
  const colorFor = (r: (typeof raw)[number]): string => r.override ?? (groupCol ? groupHue.get(r.id) ?? r.paletteColor : r.paletteColor);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // With group colouring the legend lists the groups (regions); otherwise the cells.
  // Note: two different targets, because the rows are two different things. A cell row selects its
  // cell — the same id its own click uses. A region row names a group that has no object of its
  // own (the region's hues are derived from the palette, and there is no per-region colour
  // field), so it opens the Treemap section, which is where a region's appearance is decided.
  const legendSource = groupCol
    // A treemap draws filled cells, so each key is a filled block (the legend's key follows its mark).
    ? groupOrder.map((g, gi) => ({ label: g || "(ungrouped)", color: seriesColor(gi, palette), swatch: "bar" as const, select: { as: "section" as const, id: "Treemap" } }))
    : raw.map((r) => ({ label: r.label, color: colorFor(r), swatch: "bar" as const, select: { as: "treemap-cell" as const, id: r.id } }));
  const layoutKind = ts.layout ?? "voronoi";
  const boundaryShape = ts.boundary ?? "circle";
  // Region headings live in a ring just outside the boundary — only meaningful with a
  // group column on a round Voronoi boundary. Reserve the ring width so they don't clip.
  const groupLabelSize = Math.max(9, (ts.labelSize ?? fonts.tick.size) * 0.82);
  const groupLabelsOn = !!groupCol && ts.showGroupLabels === true && layoutKind === "voronoi" && (boundaryShape === "circle" || boundaryShape === "ellipse");
  // Ring reserve = exactly what the heading placement uses (a flat
  // `size + 14` would leave ~12px of dead band all round). A heading's centre sits at
  // boundary + 0.6·F + 6 (see the groupLabels loop) and its glyph run is ~0.55·F + 2
  // half-thick, so the ring must cover 1.15·F + 8 beyond the boundary; the base inset
  // contributes 6, leaving 1.15·F + 2 for the ring. Caution: keep in sync with `lr` below.
  const labelRing = groupLabelsOn ? Math.ceil(groupLabelSize * 1.15 + 2) : 0;
  const inset = 6 + labelRing;
  // Outer margins: the treemap is made as large as possible within its box. Sides + bottom are
  // 10px — an axis-less chart gains nothing from the general 18px chart margins but background,
  // and 10px keeps a breath without wasting the card. The top keeps the standard 16px:
  // with Keep proportions off, the panel assembler's content-box solve evens out width and
  // bottom through its absorb terms but has no top absorb, so the top margin must match the
  // axis panels' band or their outer boxes drift 6px apart.
  // The scene box keeps its full size and the legend keeps its setting: fitting the scene
  // tightly around the disc or turning the legend off would change the figure's size and
  // remove content. The box belongs to the layout; this builder draws the biggest disc that fits inside it.
  const OUTER_SIDE = 10;
  const OUTER_TOP = DEFAULTS.marginTop;
  // Note: `pad.b` and `pad.l` must be applied to the plot box: top and right are folded
  // into `topPad` and `marginRight`, but the other two sides are not. An axis-less kind has
  // no axis margin to absorb them, so all four are applied by hand.
  const leg = resolveLegend(plot, legendSource, measure, fonts.legend.size, width);
  const marginRight = OUTER_SIDE + leg.outsideRightWidth + pad.r;
  const plotX = OUTER_SIDE + pad.l;
  const plotY = OUTER_TOP + topPad;
  const plotW = Math.max(1, width - plotX - marginRight);
  const plotH = Math.max(1, height - OUTER_TOP - topPad - OUTER_SIDE - pad.b);
  const cx = plotX + plotW / 2;
  const cy = plotY + plotH / 2;
  // Boundary radii (Voronoi circle/ellipse) — reused to anchor the region headings.
  let boundRx = 0;
  let boundRy = 0;

  // Layout: squarified (rectangular, optionally nested by group) or weighted-Voronoi.
  let cellsGeom: TreemapCell[];
  if (layoutKind === "squarified") {
    const plotRect = { x: plotX + inset, y: plotY + inset, w: Math.max(0, plotW - 2 * inset), h: Math.max(0, plotH - 2 * inset) };
    const geom: TreemapCell[] = raw.map((_, i) => ({ index: i, polygon: [], area: 0, site: { x: 0, y: 0 } }));
    if (groupCol && groupOrder.length > 0) {
      // Hierarchical: squarify the groups into the plot rect, then each group's
      // cells inside its rectangle (with a small gap so regions read as blocks).
      const groupTotals = groupOrder.map((g) => members.get(g)!.reduce((a, m) => a + m.value, 0));
      const groupRects = squarifyLayout(groupTotals, plotRect);
      const gap = 2;
      groupOrder.forEach((g, gi) => {
        const gr = groupRects[gi]!;
        const inner = { x: gr.x + gap, y: gr.y + gap, w: Math.max(0, gr.w - 2 * gap), h: Math.max(0, gr.h - 2 * gap) };
        const ms = members.get(g)!;
        const memberRects = squarifyLayout(ms.map((m) => m.value), inner);
        ms.forEach((m, k) => {
          const idx = raw.indexOf(m);
          const r = memberRects[k]!;
          if (idx >= 0 && r.w > 0 && r.h > 0) geom[idx] = { index: idx, polygon: rectToPolygon(r), area: r.w * r.h, site: { x: r.x + r.w / 2, y: r.y + r.h / 2 } };
        });
      });
    } else {
      const rects = squarifyLayout(raw.map((r) => r.value), plotRect);
      rects.forEach((r, i) => {
        if (r.w > 0 && r.h > 0) geom[i] = { index: i, polygon: rectToPolygon(r), area: r.w * r.h, site: { x: r.x + r.w / 2, y: r.y + r.h / 2 } };
      });
    }
    cellsGeom = geom;
  } else {
    // Boundary the Voronoi cells tile.
    const shape = boundaryShape;
    if (shape === "ellipse") {
      boundRx = plotW / 2 - inset;
      boundRy = plotH / 2 - inset;
    } else if (shape === "circle") {
      boundRx = boundRy = Math.min(plotW, plotH) / 2 - inset;
    }
    const boundary =
      shape === "rect"
        ? rectPolygon(plotX + inset, plotY + inset, plotW - 2 * inset, plotH - 2 * inset)
        : ellipsePolygon(cx, cy, boundRx, boundRy);
    cellsGeom = voronoiTreemap(
      raw.map((r) => r.value),
      boundary,
      { ...(ts.seed != null ? { seed: ts.seed } : {}), maxIterations: ts.iterations ?? 160 },
    );
  }

  // Auto-contrast label colour: light text on dark cells, dark on light.
  const contrast = (hex: string): string => contrastInk(hex);
  const fmtVal = (v: number): string => (Number.isInteger(v) ? String(v) : Number(v.toFixed(2)).toString());
  const baseSize = ts.labelSize ?? fonts.tick.size;
  const scaleLabels = ts.scaleLabels ?? true;
  const refArea = raw.length > 0 ? cellsGeom.reduce((a, c) => a + c.area, 0) / raw.length : 1;
  const fillOpacity = ts.fillOpacity ?? 1;
  const showValues = ts.showValues ?? false;

  /**
   * Horizontal width available inside a cell at height `y` — the span between the polygon's
   * leftmost and rightmost intersections with that scan-line. Exact for the convex cells a
   * power diagram produces, and far tighter than a bounding box (which would happily claim
   * room in a corner the text can never occupy).
   */
  const chordAt = (poly: { x: number; y: number }[], y: number): number => {
    let lo = Infinity;
    let hi = -Infinity;
    for (let k = 0; k < poly.length; k++) {
      const a = poly[k]!;
      const b = poly[(k + 1) % poly.length]!;
      if (a.y === b.y) continue;
      const t = (y - a.y) / (b.y - a.y);
      if (t < 0 || t > 1) continue;
      const x = a.x + t * (b.x - a.x);
      if (x < lo) lo = x;
      if (x > hi) hi = x;
    }
    return hi > lo ? hi - lo : 0;
  };

  const cells: TreemapCellScene[] = raw.map((d, i) => {
    const geom = cellsGeom[i]!;
    const fill = colorFor(d);
    // Big-cell cap 1.2: with the house base of 26, a 1.6× cap would scale the largest
    // cell's block into the heading ring and the de-confliction would drop the figure's
    // most prominent label. 1.2 keeps the hierarchy (big cells still read bigger) without
    // growing the block past what its cell can claim.
    const size = scaleLabels && refArea > 0 ? Math.max(baseSize * 0.55, Math.min(baseSize * 1.2, baseSize * Math.sqrt(geom.area / refArea))) : baseSize;
    const loff = plot.pointStyles?.[`${d.id}:${d.id}`]; // per-cell label drag offset
    // Auto-contrast on the on-screen colour: composite the fill onto the background by its
    // opacity, so a dark fill drawn faint (pale on screen) gets dark text, not light.
    const bgHex = plot.background && plot.background.startsWith("#") ? plot.background : "#ffffff";
    const onScreen = fillOpacity < 1 ? mix(bgHex, fill, fillOpacity) : fill;
    // A cell only carries the text that fits inside it. Without this every cell is labelled
    // regardless of size, so small cells spill their name, value and icon across their
    // neighbours. The renderer
    // stacks the label just above the site and the value ~1.05em below it, so each line is
    // measured against the cell's own width at that line's height.
    const poly = geom.polygon.map((p) => ({ x: p.x, y: p.y }));
    const valueText = showValues ? fmtVal(d.value) : "";
    /**
     * Does a glyph run fit inside this cell? Checked at both the baseline and the cap line,
     * because text grows upward from its baseline: testing the baseline alone would let icons (drawn
     * a full em tall) hang out of the top of their cell onto the neighbour above.
     * `chordAt` is 0 outside the polygon, so a line that escapes the cell fails automatically.
     */
    const fitsBox = (w: number, px: number, baselineY: number): boolean =>
      w <= chordAt(poly, baselineY) * 0.9 && w <= chordAt(poly, baselineY - px * 0.72) * 0.9;
    const fits = (text: string, px: number, atY: number): boolean =>
      text === "" || fitsBox(measure(text, px), px, atY);
    const labelY = geom.site.y + (valueText ? -size * 0.05 : size * 0.34);
    const valueY = geom.site.y + size * 1.05;
    const labelFits = fits(d.label, size, labelY);
    const valueFits = fits(valueText, size * 0.85, valueY);
    // The icon is drawn above the label at 1.35× its size, so it must be measured at its own
    // height and against its own width — checking the chord at the cell's centre against one
    // label-height would let icons spill onto neighbouring cells.
    // `chordAt` returns 0 outside the polygon, so this also enforces vertical fit for free.
    // An emoji's advance width is not its glyph box — `measure` badly under-reports it — so the
    // icon is sized from its font size (1.35em, matching the renderer) rather than measured.
    const iconY = geom.site.y - (labelFits ? size * TREEMAP_ICON_LIFT : size * 0.2);
    const iconPx = size * 1.35;
    const iconFits = !!d.icon && fitsBox(iconPx, iconPx, iconY);
    return {
      id: d.id,
      label: labelFits ? d.label : "",
      value: d.value,
      points: poly,
      fill,
      fillOpacity,
      labelX: geom.site.x,
      labelY: geom.site.y,
      labelSize: size,
      labelColor: contrast(onScreen),
      valueLabel: valueFits ? valueText : "",
      ...(loff?.valueDx != null ? { labelDx: loff.valueDx } : {}),
      ...(loff?.valueDy != null ? { labelDy: loff.valueDy } : {}),
      ...(d.stroke != null ? { stroke: d.stroke } : {}),
      ...(d.strokeWidth != null ? { strokeWidth: d.strokeWidth } : {}),
      // Icon badge atop the cell (scales with the cell via labelSize in the renderer).
      // `iconY` travels with it: the renderer must not recompute the lift (see TreemapCell).
      ...(iconFits ? { icon: d.icon, iconY } : {}),
    };
  });

  // Region headings around the boundary: place each group's name in the reserved ring,
  // at the angle of its (value-weighted) cell centroid, rotated tangentially.
  const groupLabels: TreemapGroupLabelScene[] = [];
  if (groupLabelsOn) {
    const byId = new Map(cells.map((c) => [c.id, c] as const));
    for (const g of groupOrder) {
      if (!g) continue; // skip the "(ungrouped)" bucket
      const ms = members.get(g)!;
      let sx = 0, sy = 0, sw = 0;
      for (const r of ms) {
        const c = byId.get(r.id);
        if (!c) continue;
        const w = Math.max(r.value, 1e-9);
        sx += c.labelX * w; sy += c.labelY * w; sw += w;
      }
      if (sw <= 0) continue;
      let dx = sx / sw - cx;
      let dy = sy / sw - cy;
      const len = Math.hypot(dx, dy) || 1;
      dx /= len; dy /= len;
      // Distance to the boundary along this direction, then push out into the ring.
      const s = boundRx > 0 && boundRy > 0 ? 1 / Math.hypot(dx / boundRx, dy / boundRy) : 0;
      // Caution: the ring reserve (`labelRing` above) is derived from this placement — change one,
      // change both, or headings clip at the scene edge.
      const lr = s + groupLabelSize * 0.6 + 6;
      let deg = (Math.atan2(dy, dx) * 180) / Math.PI + 90;
      if (deg > 90) deg -= 180;
      else if (deg < -90) deg += 180;
      const off = ts.groupLabelOffsets?.[g];
      groupLabels.push({ text: g, x: cx + dx * lr, y: cy + dy * lr, angle: deg, color: "#8a8f98", fontSize: groupLabelSize, ...(off?.dx != null ? { dx: off.dx } : {}), ...(off?.dy != null ? { dy: off.dy } : {}) });
    }
  }

  /**
   * Final de-confliction across every glyph in the figure.
   *
   * The per-cell fit test only ever asks "does this text fit inside its own cell?", which cannot
   * see two other collisions: a glyph sitting legitimately inside its own cell but touching a
   * neighbour's across the shared edge, and a cell's text meeting a region heading, which lives
   * in the boundary ring and is not a cell at all.
   *
   * Cell text resolves by dropping, not moving — a treemap label means "this cell", so it
   * cannot slide. Priority: cells by area first (the data is the figure's argument — the
   * biggest cell is its anchor), and within a cell label → value → icon; region headings
   * come last because they are the one element that can move (their outward dodge along
   * their own radius), so they place themselves around the claimed data instead of
   * deleting it. The same selective labelling the network uses, and what hand-made
   * infographics do.
   */
  {
    type Box = { x1: number; y1: number; x2: number; y2: number };
    const placed: Box[] = [];
    // PAD of 3, not 1: the glyph model here is approximate (font metrics, and an emoji's advance
    // width is not its box), and 1px leaves real 2px overlaps on screen. Cheap to be generous.
    const PAD = 3;
    const hits = (b: Box): boolean =>
      placed.some((p) => b.x1 < p.x2 + PAD && p.x1 < b.x2 + PAD && b.y1 < p.y2 + PAD && p.y1 < b.y2 + PAD);

    const boxOf = (text: string, cx: number, baseline: number, px: number): Box => {
      const w = measure(text, px) * 1.15; // `measure` under-reads, emoji worst of all
      return { x1: cx - w / 2, x2: cx + w / 2, y1: baseline - px * 0.85, y2: baseline + px * 0.3 };
    };
    // Cells claim first, headings dodge. A heading floats in the ring and can move outward,
    // while a cell label means "this cell" and cannot slide. Letting headings claim first
    // would, at the house label size, delete the figure's most prominent label (the biggest
    // cell's name, lost to its own region's heading). So the data claims its ground and the
    // headings use their outward dodge around it; only a heading that cannot dodge inside
    // the figure is dropped.
    const areaOf = (c: (typeof cells)[number]): number => {
      let a = 0;
      for (let i = 0, j = c.points.length - 1; i < c.points.length; j = i++) {
        a += (c.points[j]!.x + c.points[i]!.x) * (c.points[j]!.y - c.points[i]!.y);
      }
      return Math.abs(a / 2);
    };
    // Note: a cell's icon + label + value are one block, not three competitors. They are stacked a
    // deliberate ~1.05em apart, which is tighter than these padded boxes, so testing them against
    // each other would make every cell delete its own value. Claim the block; if it does not fit
    // alongside its neighbours, shed the least important part and try again — icon, then value,
    // then the label goes too.
    const union = (bs: Box[]): Box => ({
      x1: Math.min(...bs.map((b) => b.x1)), y1: Math.min(...bs.map((b) => b.y1)),
      x2: Math.max(...bs.map((b) => b.x2)), y2: Math.max(...bs.map((b) => b.y2)),
    });
    for (const c of [...cells].sort((a, b) => areaOf(b) - areaOf(a))) {
      const size = c.labelSize;
      const iconPx = size * 1.35;
      // The builder already placed it; recomputing it here would let the two passes drift apart.
      const iconY = c.iconY ?? c.labelY - size * TREEMAP_ICON_LIFT;
      // An emoji's advance width is not its glyph box, so size it from the font, not `measure`.
      const parts = () => {
        const bs: Box[] = [];
        if (c.icon) bs.push({ x1: c.labelX - iconPx / 2, x2: c.labelX + iconPx / 2, y1: iconY - iconPx * 0.85, y2: iconY + iconPx * 0.3 });
        if (c.label !== "") bs.push(boxOf(c.label, c.labelX, c.labelY, size));
        if (c.valueLabel !== "") bs.push(boxOf(c.valueLabel, c.labelX, c.labelY + size * 1.05, size * 0.85));
        return bs;
      };
      for (;;) {
        const bs = parts();
        if (bs.length === 0) break;
        const block = union(bs);
        if (!hits(block)) {
          placed.push(block);
          break;
        }
        if (c.icon) c.icon = undefined;
        else if (c.valueLabel !== "") c.valueLabel = "";
        else { c.label = ""; break; }
      }
    }
    // Region headings: rotated runs in the ring, placed around the claimed cell blocks.
    // Two adjacent regions can land at nearly the same angle, so they can collide with
    // each other (or with a cell block near the boundary) — push the later one further
    // out along its own radius before giving up on it.
    const cxr = plotX + plotW / 2;
    const cyr = plotY + plotH / 2;
    // The outward dodge must stop at the title band, not only at the figure edge, or a top heading
    // pushed out past the cells would be drawn across the title. The title band is as off-limits as the edge.
    // The band's last 10 px are the gap under the title's glyphs (headingPad: +6 under a title, +4
    // at the foot), so a heading may use them; the glyphs themselves are what it must not touch.
    const headingFloor = heading.title || heading.subtitle ? plotY - pad.t - 10 : 0;
    for (const g of groupLabels) {
      const h = g.fontSize;
      /**
       * Note: a region heading is drawn bold with 0.08em letter-spacing (PlotFigure), and neither
       * is in `measure`. A plain 1.15 slack would therefore under-read the real glyph run, so two
       * headings this pass had cleared could still meet on screen (by ~4.5px).
       *
       * Tracking is exact — (n−1) gaps of 0.08em — so it is added as a term rather than
       * absorbed into the correction factor; 1.06 covers the extra weight of the bold face.
       */
      // The heading is a rotated glyph run: its true footprint is the rotated w×h
      // rectangle, not a square of its length. A square approximation would over-block the
      // cells beside a near-vertical heading, and — when the disc fills its box edge to edge —
      // read side headings as wider than the margin and delete them. Exact axis-aligned
      // extents of a w×h rectangle at `angle`:
      const rad = (g.angle * Math.PI) / 180;
      const ux = g.x - cxr;
      const uy = g.y - cyr;
      const len = Math.hypot(ux, uy) || 1;
      let done = false;
      // A heading that cannot fit at full size shrinks before it is deleted
      // (a diagonal heading's rotated box reaches deep, and on a tightly fitted
      // figure the outward dodge alone can run out of margin — losing a region's name to
      // whitespace tuning is the worse trade). Each size retries the outward dodge.
      for (const fscale of [1, 0.85, 0.72]) {
        const fh = h * fscale;
        const w = measure(g.text, fh) * 1.15 * 1.06 + fh * 0.08 * Math.max(0, g.text.length - 1);
        const exX = (Math.abs(Math.cos(rad)) * w + Math.abs(Math.sin(rad)) * fh) / 2;
        const exY = (Math.abs(Math.sin(rad)) * w + Math.abs(Math.cos(rad)) * fh) / 2;
        for (let k = 0; k <= 3 && !done; k++) {
          const px2 = g.x + (ux / len) * k * fh;
          const py2 = g.y + (uy / len) * k * fh;
          const b: Box = { x1: px2 - exX, x2: px2 + exX, y1: py2 - exY, y2: py2 + exY };
          if (b.x1 < 0 || b.y1 < headingFloor || b.x2 > width || b.y2 > height) break; // pushed off the figure, or into its title
          if (!hits(b)) {
            placed.push(b);
            g.x = px2;
            g.y = py2;
            g.fontSize = fh;
            done = true;
          }
        }
        if (done) break;
      }
      if (!done) g.text = "";
    }
  }

  const treemap: TreemapScene = {
    cells,
    stroke: ts.stroke ?? "#ffffff",
    strokeWidth: ts.strokeWidth ?? 1.5,
    showLabels: ts.showLabels ?? true,
    ...(groupLabels.length > 0 ? { groupLabels } : {}),
  };

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "treemap",
    fonts,
    treemap,
    warnings,
  };
}

/** A closed annular-sector path (a ring segment) as a sampled polygon — robust for any sweep,
 *  including a full circle (where SVG arc commands are ambiguous). Angles are the compass
 *  convention: 0 = 12 o'clock, increasing clockwise. r0 = inner radius (0 → a pie slice). */
function ringSectorPath(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number): string {
  const P = (r: number, a: number): [number, number] => [cx + r * Math.sin(a), cy - r * Math.cos(a)];
  const span = a1 - a0;
  const steps = Math.max(2, Math.ceil(Math.abs(span) / (Math.PI / 90))); // ~2° per segment
  const outer: string[] = [];
  const inner: string[] = [];
  for (let i = 0; i <= steps; i++) {
    const a = a0 + (span * i) / steps;
    const [ox, oy] = P(r1, a);
    outer.push(`${ox.toFixed(2)},${oy.toFixed(2)}`);
    const [ix, iy] = P(r0, a);
    inner.push(`${ix.toFixed(2)},${iy.toFixed(2)}`);
  }
  inner.reverse();
  if (r0 <= 0.001) {
    // A pie slice from the centre: centre → outer arc → back to centre.
    return `M${cx.toFixed(2)},${cy.toFixed(2)} L${outer.join(" L")} Z`;
  }
  return `M${outer.join(" L")} L${inner.join(" L")} Z`;
}

/**
 * Sunburst (kind "sunburst"): a radial hierarchy of ring segments. The leading categorical columns
 * are the levels (inner ring = level 1); a value column (or the row count) sizes each leaf, and a
 * segment sweeps the angle of its share of the whole. Colour is by the top-level branch, shaded
 * lighter toward the leaves (as the treemap shades its groups). Reuses the core `sunburstHierarchy`
 * roll-up (independently tested) + the treemap axis-less scene shape.
 */
function buildSunburstScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const sb = plot.sunburst ?? {};
  const cols = table.columns;

  // Level columns: an explicit list, else the leading text columns (as on the alluvial chart).
  const isTextCol = (colId: NodeId): boolean => {
    let text = 0, tot = 0;
    for (const r of table.rows) {
      const v = r.cells[colId];
      if (v != null && String(v).trim() !== "") { tot++; if (!Number.isFinite(toNumber(v))) text++; }
    }
    return tot > 0 && text >= tot * 0.5;
  };
  let levelIds = (sb.levelColumns ?? []).filter((id) => cols.some((c) => c.id === id));
  if (levelIds.length === 0) {
    const auto = cols.filter((c) => isTextCol(c.id)).map((c) => c.id);
    levelIds = auto.length ? auto : cols.slice(0, 1).map((c) => c.id);
  }
  const levelCols = levelIds.map((id) => cols.find((c) => c.id === id)!).filter(Boolean);
  if (levelCols.length === 0) warnings.push("A sunburst needs at least one category column for its rings.");

  // Value column: explicit, else the first numeric column not used as a level; absent → count of 1.
  const explicitValue = sb.valueColumn && cols.some((c) => c.id === sb.valueColumn) ? sb.valueColumn : undefined;
  const valueCol = explicitValue
    ?? cols.find((c) => !levelIds.includes(c.id) && table.rows.some((r) => Number.isFinite(toNumber(r.cells[c.id]))))?.id;

  const items = table.rows.map((r) => ({
    path: levelCols.map((c) => String(r.cells[c.id] ?? "").trim()),
    value: valueCol ? toNumber(r.cells[valueCol]) : 1,
    rowId: r.id,
  }));
  const root = sunburstHierarchy(items, levelIds);
  const maxDepth = sunburstDepth(root);

  // Branch (level-1) colour index, first-appearance order — the top-level hue each subtree inherits.
  const branchIndex = new Map<string, number>();
  root.children.forEach((c, i) => branchIndex.set(c.name, i));
  const overrideOf = (name: string): string | undefined => plot.seriesStyles?.[name]?.color;

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const OUTER = 10;
  const OUTER_TOP = DEFAULTS.marginTop;
  // A sunburst draws ring segments: each key is a wedge, like a pie's (keys follow their marks).
  const legendSource = root.children.map((c, i) => ({
    label: c.name, color: overrideOf(c.name) ?? seriesColor(i, palette), swatch: "bar" as const, keyShape: "wedge" as const,
    select: { as: "section" as const, id: "Chart type" },
  }));
  const leg = resolveLegend(plot, legendSource, measure, fonts.legend.size, width);
  const plotX = OUTER + pad.l;
  const plotY = OUTER_TOP + topPad;
  const marginRight = OUTER + leg.outsideRightWidth + pad.r;
  const plotW = Math.max(1, width - plotX - marginRight);
  const plotH = Math.max(1, height - OUTER_TOP - topPad - OUTER - pad.b);
  const cx = plotX + plotW / 2;
  const cy = plotY + plotH / 2;
  const maxR = Math.max(1, Math.min(plotW, plotH) / 2 - 4);
  const innerFrac = Math.max(0, Math.min(0.8, sb.innerRadius ?? 0));
  const innerR = maxR * innerFrac;
  const ringThick = maxDepth > 0 ? (maxR - innerR) / maxDepth : 0;
  const padAngle = Math.max(0, Math.min(5, sb.padAngle ?? 0)) * Math.PI / 180;
  const showLabels = sb.showLabels !== false;
  const showValues = sb.showValues === true;
  // Label size, when set, is the size the labels are fitted and drawn at (carried on the scene, so the renderer
  // draws at it rather than at the tick font). Unset, the fitting stays one pixel under the tick font it is drawn
  // at.
  const labelBase = sb.labelSize ?? Math.max(9, fonts.tick.size - 1);
  const grandTotal = root.value || 1;

  type Seg = NonNullable<PlotScene["sunburst"]>["segments"][number];
  const segments: Seg[] = [];
  // Recursively assign each node an angular span proportional to its value within its parent's
  // span; a node at depth d occupies the ring [innerR+(d-1)·thick, innerR+d·thick].
  const walk = (node: typeof root, a0: number, a1: number, branch: string): void => {
    // The parent's full span, captured once. `a0` advances past each sibling, so measuring
    // against (a1 − a0) inside the loop would shrink every later sibling by the ones before it
    // (the inner ring would cover only ¾ of the turn).
    const full = a1 - a0;
    for (const child of node.children) {
      const frac = node.value > 0 ? child.value / node.value : 0;
      const span = full * frac;
      const c0 = a0, c1 = a0 + span;
      a0 = c1; // advance the cursor for the next sibling
      const br = node.depth === 0 ? child.name : branch;
      const bi = branchIndex.get(br) ?? 0;
      const base = overrideOf(br) ?? seriesColor(bi, palette);
      // Lighten toward the leaves so the branch hue reads at level 1 (as on the treemap).
      const tint = maxDepth > 1 ? ((child.depth - 1) / (maxDepth - 1)) * 0.5 : 0;
      const color = child.depth === 1 ? base : mix(base, "#ffffff", tint);
      const r0 = innerR + (child.depth - 1) * ringThick;
      const r1 = innerR + child.depth * ringThick;
      const gap = padAngle / 2;
      const sa0 = c0 + gap, sa1 = Math.max(c0 + gap, c1 - gap);
      const mid = (sa0 + sa1) / 2;
      const midR = (r0 + r1) / 2;
      // Label rotation: run the text along the radius, flipped to stay upright.
      let deg = (mid * 180) / Math.PI; // 0 at top, clockwise
      let rot = deg - 90; // along the radius
      if (deg > 180) rot = deg + 90;
      // A radial label is dropped when the segment is too thin to host it — angularly (its arc
      // height would clip the text) or radially (the ring is thinner than a line). Radial length
      // is not tested: a long name simply runs outward into the margin, which stays legible; the
      // legend + hover title name every segment regardless. This kills the small-segment pile-up.
      const arcHeight = (sa1 - sa0) * midR;
      // …and it must end on the canvas: it is centred at midR along its radius, so its outer
      // end reaches midR + half its length. At a 30 px font a long name can otherwise run tens
      // of px past the canvas edge.
      const reachText = showValues ? `${child.name} 100%` : child.name;
      const reachR = midR + measure(reachText, labelBase) / 2 + labelBase * 0.4;
      const endX = cx + reachR * Math.sin(mid);
      const endY = cy - reachR * Math.cos(mid);
      const onCanvas = endX >= 0 && endX <= width && endY >= 0 && endY <= height;
      const showLabel = showLabels && child.name !== "" && ringThick >= labelBase * 1.1 && arcHeight >= labelBase * 1.5 && onCanvas;
      segments.push({
        key: `${br}␀${child.depth}␀${child.name}␀${c0.toFixed(4)}`,
        depth: child.depth, label: child.name, value: child.value, frac: child.value / grandTotal,
        a0: c0, a1: c1,
        path: ringSectorPath(cx, cy, r0, r1, sa0, sa1), color,
        labelX: cx + midR * Math.sin(mid), labelY: cy - midR * Math.cos(mid), labelAngle: rot, showLabel,
        columnId: child.columnId, rowId: child.rowId,
      });
      walk(child, c0, c1, br);
    }
  };
  if (root.value > 0 && ringThick > 0) walk(root, 0, 2 * Math.PI, "");
  if (segments.length === 0 && levelCols.length > 0) warnings.push("No positive values to chart.");

  // Declutter labels as overlapping discs: each label covers a disc of radius ≈ half its (radial) text
  // length; the biggest segment claims first, and a smaller label is dropped when its disc would
  // touch a kept one (dist < the sum of the two radii). Radial labels converge toward the centre,
  // so this is what actually stops the pile-up. Depth-1 branches are named in the legend, so
  // dropping a crowded one there costs nothing.
  const kept: { x: number; y: number; reach: number }[] = [];
  for (const seg of [...segments].filter((s) => s.showLabel).sort((a, b) => b.value - a.value)) {
    const text = showValues ? `${seg.label} ${(seg.frac * 100).toFixed(0)}%` : seg.label;
    const reach = measure(text, labelBase) / 2 + labelBase * 0.35;
    if (kept.some((k) => Math.hypot(k.x - seg.labelX, k.y - seg.labelY) < k.reach + reach)) seg.showLabel = false;
    else kept.push({ x: seg.labelX, y: seg.labelY, reach });
  }

  const centerLabel = sb.showTotal === true && innerR > labelBase
    ? { text: `${grandTotal}`, x: cx, y: cy }
    : undefined;

  const sunburst: NonNullable<PlotScene["sunburst"]> = {
    cx, cy, maxR, innerR, segments, centerLabel,
    stroke: sb.stroke ?? "#ffffff",
    strokeWidth: sb.strokeWidth ?? 1,
    fillOpacity: Math.max(0, Math.min(1, sb.fillOpacity ?? 1)),
    showValues,
    ...(sb.labelSize !== undefined ? { labelSize: sb.labelSize } : {}), // absent = the tick size
  };
  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width, height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis, y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [], legend: leg.entries, legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title, subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "sunburst", fonts, sunburst, warnings,
  };
}

/** A chord ribbon: the source sub-arc, a Bézier through the centre to the target sub-arc, the
 *  target sub-arc, and a Bézier back — the classic d3 chord ribbon (control point at the centre
 *  pinches the band through the middle). Angles are compass (0 = top, clockwise). */
function chordRibbonPath(cx: number, cy: number, r: number, sa0: number, sa1: number, ta0: number, ta1: number): string {
  const P = (a: number): string => `${(cx + r * Math.sin(a)).toFixed(2)} ${(cy - r * Math.cos(a)).toFixed(2)}`;
  const largeS = sa1 - sa0 > Math.PI ? 1 : 0;
  const largeT = ta1 - ta0 > Math.PI ? 1 : 0;
  const c = `${cx.toFixed(2)} ${cy.toFixed(2)}`;
  return `M ${P(sa0)} A ${r} ${r} 0 ${largeS} 1 ${P(sa1)} Q ${c} ${P(ta0)} A ${r} ${r} 0 ${largeT} 1 ${P(ta1)} Q ${c} ${P(sa0)} Z`;
}

/**
 * Chord / circos diagram (kind "chord"): entities as arc segments around a ring, weighted
 * relationships as ribbons across the interior. Reads an edge list (Source · Target · Weight) or a
 * square adjacency matrix. Reuses the core `chordLayout` (arc + ribbon angles, independently
 * tested) + the treemap axis-less scene shape.
 */
function buildChordScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const ch = plot.chord ?? {};
  const cols = table.columns;

  const isTextCol = (colId: NodeId): boolean => {
    let text = 0, tot = 0;
    for (const r of table.rows) {
      const v = r.cells[colId];
      if (v != null && String(v).trim() !== "") { tot++; if (!Number.isFinite(toNumber(v))) text++; }
    }
    return tot > 0 && text >= tot * 0.5;
  };
  const byId = (id?: NodeId): Column | undefined => (id ? cols.find((c) => c.id === id) : undefined);
  const textCols = cols.filter((c) => isTextCol(c.id));
  const numericCols = cols.filter((c) => table.rows.some((r) => Number.isFinite(toNumber(r.cells[c.id]))));

  const srcCol = byId(ch.sourceColumn) ?? textCols[0] ?? cols[0];
  const tgtCol = byId(ch.targetColumn) ?? (textCols[1] && textCols[1].id !== srcCol?.id ? textCols[1] : cols[1]);
  const groupById = new Map<string, string>(); // node → group (edge-list mode, source's group)

  // Build the edge list. Edge-list mode when there are two distinct label columns; otherwise
  // matrix mode: one lead label column + numeric columns whose names are the targets.
  const edges: ChordEdge[] = [];
  const edgeListMode = !!srcCol && !!tgtCol && srcCol.id !== tgtCol.id && (isTextCol(srcCol.id) && isTextCol(tgtCol.id) || !!ch.sourceColumn);
  if (edgeListMode && srcCol && tgtCol) {
    const wCol = byId(ch.weightColumn) ?? numericCols.find((c) => c.id !== srcCol.id && c.id !== tgtCol.id);
    const gCol = byId(ch.groupColumn);
    for (const r of table.rows) {
      const s = String(r.cells[srcCol.id] ?? "").trim();
      const t = String(r.cells[tgtCol.id] ?? "").trim();
      if (s === "" || t === "") continue;
      const w = wCol ? toNumber(r.cells[wCol.id]) : 1;
      edges.push({ source: s, target: t, weight: Number.isFinite(w) ? w : 1 });
      if (gCol && !groupById.has(s)) { const g = String(r.cells[gCol.id] ?? "").trim(); if (g) groupById.set(s, g); }
    }
    if (!wCol) warnings.push("No weight column found — every link counts as 1.");
  } else if (srcCol) {
    // Matrix mode: lead label + numeric target columns; cell = weight from row-label to col-name.
    const targets = numericCols.filter((c) => c.id !== srcCol.id);
    for (const r of table.rows) {
      const s = String(r.cells[srcCol.id] ?? "").trim();
      if (s === "") continue;
      for (const tc of targets) {
        const w = toNumber(r.cells[tc.id]);
        if (Number.isFinite(w) && w > 0) edges.push({ source: s, target: tc.name, weight: w });
      }
    }
  }
  const selfLoops = edges.filter((e) => e.source.trim() === e.target.trim()).length;
  if (selfLoops > 0) warnings.push(`${selfLoops} self-link${selfLoops > 1 ? "s" : ""} (a node to itself) can't be drawn as a chord and ${selfLoops > 1 ? "were" : "was"} skipped.`);

  const padAngle = Math.max(0, Math.min(10, ch.padAngle ?? 2)) * Math.PI / 180;
  const layout = chordLayout(edges, { padAngle, ...(ch.order ? { order: ch.order } : {}) });
  if (layout.nodes.length === 0 && edges.length === 0) warnings.push("A chord diagram needs at least one weighted link between two nodes.");

  // Node colours: by group (a palette hue per group) or one palette hue per node; per-node override.
  const groupOrder: string[] = [];
  for (const n of layout.nodes) { const g = groupById.get(n.name); if (g && !groupOrder.includes(g)) groupOrder.push(g); }
  const nodeColor = (name: string, i: number): string => {
    // A per-node override lives under the node's own name in seriesStyles, as on the sunburst.
    const override = plot.seriesStyles?.[name]?.color;
    if (override) return override;
    const g = groupById.get(name);
    if (g) return seriesColor(groupOrder.indexOf(g), palette);
    return seriesColor(i, palette);
  };

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const OUTER = 10;
  const OUTER_TOP = DEFAULTS.marginTop;
  const showLabels = ch.showLabels !== false;
  const plotX = OUTER + pad.l;
  const plotY = OUTER_TOP + topPad;
  const plotW = Math.max(1, width - plotX - OUTER - pad.r);
  const plotH = Math.max(1, height - OUTER_TOP - topPad - OUTER - pad.b);
  const labelSize0 = ch.labelSize ?? fonts.tick.size;
  // The ring's radius with the names at `px`, measured per name in its own direction: a name stands outward from its
  // arc's middle, from radius + 6, so its far end must stay inside the plot box along that direction (half a text band
  // to spare across it). One flat reserve on every side for the longest name would keep a short name at the side as
  // far from the edge as a long one at the bottom, and leave the ring small in any box. A name claims no more than
  // 22% of the width.
  const capW = Math.round(width * 0.22) - 10;
  const ringAt = (px: number): number => {
    let r = Math.min(plotW, plotH) / 2 - 6;
    if (!showLabels) return Math.max(1, r);
    const t = px * 0.6;
    for (const n of layout.nodes) {
      if (!n.name) continue;
      const m = (n.startAngle + n.endAngle) / 2;
      const reach = 6 + Math.min(capW, measure(n.name, px));
      const sx = Math.abs(Math.sin(m));
      const sy = Math.abs(Math.cos(m));
      if (sx > 1e-6) r = Math.min(r, (plotW / 2 - t) / sx - reach);
      if (sy > 1e-6) r = Math.min(r, (plotH / 2 - t) / sy - reach);
    }
    return Math.max(1, r);
  };
  // The graph fills its box. When the
  // measured room still leaves the ring under FILL of half the box's shorter side (a figure card with Keep proportions
  // off), the names shrink just enough to reach it, never below 8 px, saying so when that size was set on the graph.
  const half = Math.min(plotW, plotH) / 2;
  const FILL = 0.5;
  const px10 = (px: number): number => Math.round(px * 10) / 10;
  const fills = (k: number): boolean => ringAt(px10(labelSize0 * k)) >= FILL * half;
  let textFit = 1;
  if (showLabels && !fills(1)) {
    let lo = Math.min(1, (options.minTextPx ?? 8) / Math.max(1, labelSize0));
    let hi = 1;
    if (fills(lo)) {
      for (let i = 0; i < 16; i++) { const mid = (lo + hi) / 2; if (fills(mid)) lo = mid; else hi = mid; }
    }
    textFit = lo;
  }
  const labelSize = textFit < 1 ? px10(labelSize0 * textFit) : labelSize0;
  if (textFit < 1 && (ch.labelSize ?? plot.fonts?.tick?.size) !== undefined) warnings.push(`Chord names are drawn at ${labelSize}px, not the ${labelSize0}px asked for: the ring would be too small in this box. A larger figure will honour it.`);
  const cx = plotX + plotW / 2;
  const cy = plotY + plotH / 2;
  const r = ringAt(labelSize);
  const arcThick = Math.max(0.02, Math.min(0.2, ch.arcThickness ?? 0.08)) * r;
  const rInner = r - arcThick;

  const colorByName = new Map(layout.nodes.map((n, i) => [n.name, nodeColor(n.name, i)] as const));
  const arcs = layout.nodes.map((n, i) => {
    const mid = (n.startAngle + n.endAngle) / 2;
    const outward = mid <= Math.PI; // right half → labels anchor start, left half → end
    const lr = r + 6;
    const deg = (mid * 180) / Math.PI;
    let rot = deg - 90;
    if (deg > 180) rot = deg + 90;
    const sweep = n.endAngle - n.startAngle;
    return {
      name: n.name,
      path: ringSectorPath(cx, cy, rInner, r, n.startAngle, n.endAngle),
      color: colorByName.get(n.name) ?? seriesColor(i, palette),
      labelX: cx + lr * Math.sin(mid), labelY: cy - lr * Math.cos(mid), labelAngle: rot,
      labelAnchor: (outward ? "start" : "end") as "start" | "end",
      // A radial label needs its text band of arc at the radius it is drawn at — measured at the
      // ring's middle against 0.6 of the font, neighbouring labels would meet at 30 px.
      showLabel: showLabels && n.name !== "" && sweep * lr >= labelSize * TEXT_BAND * 0.8,
      value: n.value,
    };
  });
  // Neighbours, not just the node's own arc: two adjacent radial labels collide when their
  // centres are closer than a text band along the ring at the label radius ("Endothelial" ×
  // "B cell" at 30 px). The bigger node keeps its label; a smaller one that would land on a
  // kept label is dropped — the ring's hover title still names it.
  {
    const band = labelSize * TEXT_BAND;
    const lr = r + 6;
    const kept: number[] = [];
    const order = layout.nodes.map((n, i) => ({ i, mid: (n.startAngle + n.endAngle) / 2, v: n.value })).sort((a, b) => b.v - a.v);
    for (const { i, mid } of order) {
      if (!arcs[i]!.showLabel) continue;
      const apart = (a: number, b: number): number => { const d = Math.abs(a - b) % (2 * Math.PI); return Math.min(d, 2 * Math.PI - d) * lr; };
      if (kept.some((k) => apart(mid, k) < band)) arcs[i]!.showLabel = false;
      else kept.push(mid);
    }
  }

  const colorBySource = ch.colorBySource !== false;
  const ribbons = layout.ribbons.map((rb) => {
    const col = colorBySource ? (colorByName.get(rb.source) ?? "#9aa0aa") : "#9aa0aa";
    return {
      source: rb.source, target: rb.target,
      path: chordRibbonPath(cx, cy, rInner, rb.sourceStart, rb.sourceEnd, rb.targetStart, rb.targetEnd),
      color: col, value: rb.value,
    };
  });

  const chord: NonNullable<PlotScene["chord"]> = {
    cx, cy, r, arcs, ribbons,
    ribbonOpacity: Math.max(0, Math.min(1, ch.ribbonOpacity ?? 0.65)),
    labelSize,
  };
  const leg = resolveLegend(plot, [], measure, fonts.legend.size, width);
  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width, height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis, y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [], legend: leg.entries, legendLayout: leg.layout, annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title, subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "chord", fonts, chord, warnings,
  };
}

/**
 * Oncoprint (kind "oncoprint"): a genes × samples grid of categorical alteration tiles. Reads an
 * "alterations" sheet (Sample · Gene · Alteration, one row per event). Genes go down the rows
 * (ordered by alteration frequency), samples across the columns (memo-sorted into the staircase),
 * and each cell shows every alteration recorded for it as stacked coloured bands. Reuses the core
 * `oncoprintMatrix` (the data fold + orderings, independently tested) + the heatmap tile grid.
 */
function buildOncoprintScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const op = plot.oncoprint ?? {};
  const cols = table.columns;
  const byId = (id?: NodeId): Column | undefined => (id ? cols.find((c) => c.id === id) : undefined);

  const sampleCol = byId(op.sampleColumn) ?? cols[0];
  const geneCol = byId(op.geneColumn) ?? cols[1];
  const altCol = byId(op.alterationColumn) ?? cols[2];
  if (!sampleCol) warnings.push("An oncoprint needs a Sample column.");
  if (!geneCol) warnings.push("An oncoprint needs a Gene column.");
  if (!altCol) warnings.push("An oncoprint needs an Alteration column.");

  const events: AlterationEvent[] = (sampleCol && geneCol && altCol)
    ? table.rows.map((r) => ({
        sample: String(r.cells[sampleCol.id] ?? "").trim(),
        gene: String(r.cells[geneCol.id] ?? "").trim(),
        alteration: String(r.cells[altCol.id] ?? "").trim(),
      })).filter((e) => e.sample && e.gene && e.alteration)
    : [];
  const matrix = oncoprintMatrix(events, {
    ...(op.geneSort ? { geneSort: op.geneSort } : {}),
    ...(op.sampleSort ? { sampleSort: op.sampleSort } : {}),
  });
  const genes = matrix.genes;
  const samples = matrix.samples;
  const nGenes = genes.length;
  const nSamples = samples.length;

  // Alteration-type → colour (palette; a per-type override lives under the type's name in
  // seriesStyles, as on the sunburst and chord diagram), plus the standard legend.
  const typeColor = new Map<string, string>();
  matrix.alterationTypes.forEach((t, i) => typeColor.set(t, plot.seriesStyles?.[t]?.color ?? seriesColor(i, palette)));
  const legendSource = matrix.alterationTypes.map((t) => ({
    label: t, color: typeColor.get(t)!, marker: false, swatch: "bar" as const,
    select: { as: "section" as const, id: "Chart type" },
  }));

  const showPercent = op.showPercent !== false;
  const showSampleLabels = op.showSampleLabels === true;
  const labelSize = op.labelSize ?? fonts.tick.size;
  const emptyColor = op.emptyColor ?? "#eceef1";
  const tileGap = Math.max(0, Math.min(0.5, op.tileGap ?? 0.15));

  const geneLabelW = Math.max(0, ...genes.map((g) => measure(g, labelSize))) + 8;
  const pctLabelW = showPercent ? measure("100%", labelSize) + 10 : 0;
  const sampleLabelH = showSampleLabels ? Math.max(0, ...samples.map((s) => measure(s, labelSize))) * 0.72 + 6 : 0;

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const OUTER = 10;
  const leg = resolveLegend(plot, legendSource, measure, fonts.legend.size, width);
  // Left-to-right: gene name · per-gene % · the grid · the legend (outside right). Keeping the %
  // on the left clears it of the legend column entirely.
  const geneLabelX = OUTER + pad.l + geneLabelW;
  const plotX = geneLabelX + pctLabelW;
  const plotY = DEFAULTS.marginTop + topPad;
  const marginRight = OUTER + leg.outsideRightWidth + pad.r;
  const plotW = Math.max(1, width - plotX - marginRight);
  const plotH = Math.max(1, height - plotY - OUTER - sampleLabelH - pad.b);
  const cellW = nSamples > 0 ? plotW / nSamples : plotW;
  const cellH = nGenes > 0 ? plotH / nGenes : plotH;

  type Tile = NonNullable<PlotScene["oncoprint"]>["tiles"][number];
  const tiles: Tile[] = [];
  genes.forEach((gene, gi) => {
    samples.forEach((sample, si) => {
      const x = plotX + si * cellW;
      const y = plotY + gi * cellH;
      const gap = Math.min(cellW, cellH) * tileGap;
      const tx = x + gap / 2, ty = y + gap / 2;
      const tw = Math.max(0.5, cellW - gap), th = Math.max(0.5, cellH - gap);
      const alts = matrix.cell(gene, sample);
      const bands = alts.map((a, k) => ({
        y: ty + (th * k) / alts.length, h: th / Math.max(1, alts.length), color: typeColor.get(a) ?? "#888",
      }));
      tiles.push({ x: tx, y: ty, w: tw, h: th, gene, sample, empty: alts.length === 0, bands });
    });
  });

  // A name dragged on the graph carries its offset (keyed by the name); none otherwise.
  const offOf = (map: Record<string, { dx: number; dy: number }> | undefined, name: string): { off?: { dx: number; dy: number } } =>
    map?.[name] ? { off: map[name]! } : {};
  const geneLabels = genes.map((g, gi) => ({ text: g, x: geneLabelX - 2, y: plotY + gi * cellH + cellH / 2, ...offOf(op.geneLabelOffsets, g) }));
  const percentLabels = showPercent && nSamples > 0
    ? genes.map((g, gi) => ({ text: `${Math.round((matrix.alteredCount(g) / nSamples) * 100)}%`, x: plotX - 4, y: plotY + gi * cellH + cellH / 2 }))
    : [];
  const sampleLabels = showSampleLabels
    ? samples.map((s, si) => ({ text: s, x: plotX + si * cellW + cellW / 2, y: plotY + plotH + 4, angle: -60, ...offOf(op.sampleLabelOffsets, s) }))
    : [];

  // The gap colour: a panel behind the tiles spanning the first tile's edge to the last, so only the gaps between
  // tiles take it (no border round the grid). Nothing when unset, or when there is no gap to show it.
  const gapPanel = op.gapColor && tileGap > 0 && tiles.length > 0
    ? (() => {
        const x0 = Math.min(...tiles.map((t) => t.x)), y0 = Math.min(...tiles.map((t) => t.y));
        const x1 = Math.max(...tiles.map((t) => t.x + t.w)), y1 = Math.max(...tiles.map((t) => t.y + t.h));
        return { x: x0, y: y0, w: x1 - x0, h: y1 - y0, color: op.gapColor };
      })()
    : undefined;
  const oncoprint: NonNullable<PlotScene["oncoprint"]> = { tiles, geneLabels, percentLabels, sampleLabels, emptyColor, labelSize, ...(gapPanel ? { gap: gapPanel } : {}) };
  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width, height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis, y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [], legend: leg.entries, legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title, subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "oncoprint", fonts, oncoprint, warnings,
  };
}

/**
 * Does a parallel-coordinates plot colour its lines by a continuous value ramp (else by category hues)?
 * A numeric colour column in "auto", or "value" forced. One rule for the builder and the gallery's Colour ramp control.
 */
export function parallelColoursByValue(table: DataTable, plot: Plot): boolean {
  const ps = plot.parallel ?? {};
  const colorColId = ps.colorColumn && table.columns.some((c) => c.id === ps.colorColumn) ? ps.colorColumn : undefined;
  if (colorColId == null) return false;
  const colorScale = ps.colorScale ?? "auto";
  if (colorScale !== "auto") return colorScale === "value";
  const finite = table.rows.map((r) => toNumber(r.cells[colorColId])).filter((v) => Number.isFinite(v));
  return finite.length >= Math.max(1, table.rows.length * 0.5);
}

/**
 * Parallel-coordinates plot (kind "parallel"): each numeric column becomes a
 * vertical axis (independently min/max scaled); each row is drawn as a polyline
 * crossing every axis at its value. Lines colour by an optional category column.
 */
function buildParallelScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const ps = plot.parallel ?? {};

  const datasets = visibleDatasets(table, plot);
  const colorColId = ps.colorColumn && table.columns.some((c) => c.id === ps.colorColumn) ? ps.colorColumn : undefined;
  // Parallel coordinates has no distinguished X — every numeric variable is an axis.
  // tableDatasets() omits the role:x column (col-0 on an XY table), so add it back as
  // its own single-column axis unless it's the colour column; the value-read fallback
  // in the line loop (dsById.get(id) ? rowDatasetMean : toNumber) handles it.
  const xCol = xColumn(table);
  const axisDatasets: Dataset[] =
    xCol && xCol.id !== colorColId && !datasets.some((d) => d.id === xCol.id)
      ? [{ id: xCol.id, name: xCol.name, replicates: [xCol.id] }, ...datasets]
      : datasets;
  // Axis variables = numeric datasets, minus the colour column. A non-numeric
  // column (e.g. a category label) has no finite values and drops out here.
  let axisStats = axisDatasets
    .filter((d) => d.id !== colorColId)
    .map((d) => {
      const vals = table.rows.map((r) => rowDatasetMean(r, d)).filter((v) => Number.isFinite(v));
      let min = vals.length ? Math.min(...vals) : 0;
      let max = vals.length ? Math.max(...vals) : 1;
      if (!(max > min)) { min -= 1; max += 1; } // flat variable → a nominal range
      return { id: d.id, name: d.name, min, max, count: vals.length };
    })
    .filter((a) => a.count > 0);
  if (axisStats.length < 2) warnings.push("A parallel-coordinates plot needs at least two numeric columns.");
  // Optional user axis order (drag a variable label to reorder): listed columns first in
  // that sequence, the rest keep their natural table order after (stable sort).
  const axisOrder = ps.axisOrder ?? [];
  if (axisOrder.length) {
    const rank = new Map(axisOrder.map((id, i) => [id, i]));
    axisStats = [...axisStats].sort((a, b) => (rank.get(a.id) ?? 1e9) - (rank.get(b.id) ?? 1e9));
  }
  // Per-axis brush filters (drag on an axis to set a value range → filter lines).
  const brushes = ps.brushes ?? {};
  const dsById = new Map(axisDatasets.map((d) => [d.id, d]));

  // Colour mode: a numeric colour column → a continuous value ramp (+ colorbar); a
  // categorical one → distinct palette hues (+ legend). "auto" picks by the column's type.
  const colFinite = colorColId ? table.rows.map((r) => toNumber(r.cells[colorColId])).filter((v) => Number.isFinite(v)) : [];
  const valueMode = parallelColoursByValue(table, plot);
  const ramp = ps.colorRamp ?? "viridis";
  const rampRev = ps.colorReverse ?? false;
  let cvMin = 0;
  let cvMax = 1;
  if (valueMode && colFinite.length) {
    cvMin = Math.min(...colFinite);
    cvMax = Math.max(...colFinite);
    if (!(cvMax > cvMin)) { cvMin -= 0.5; cvMax += 0.5; }
  }
  const lineShape: RampShape = {
    midpointValue: ps.colorMidpoint, gamma: ps.colorGamma, steps: ps.colorSteps,
    space: ps.colorSpace, lo: cvMin, hi: cvMax, values: colFinite,
  };
  const linePaint = ramps.ramp(ramp, "#440154", "#fde725", rampRev, lineShape);
  const valueColor = (v: number): string => linePaint((v - cvMin) / (cvMax - cvMin || 1)).color;

  const groupColor = new Map<string, string>();
  const groupOrder: string[] = [];
  if (colorColId && !valueMode) {
    for (const r of table.rows) {
      const g = String(r.cells[colorColId] ?? "").trim();
      if (!groupColor.has(g)) { groupColor.set(g, seriesColor(groupOrder.length, palette)); groupOrder.push(g); }
    }
  }
  const singleColor = ps.lineColor ?? seriesColor(0, palette);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // A row is a group of lines (the colour column's categories), not a line — `parallel-line`
  // selects one case by row id, so there is no per-group object to point at, and the group's
  // hue comes from the palette. The row opens the section that decides all of that instead.
  const legendSource = colorColId && !valueMode
    // Parallel coordinates draw lines and no dots: the key is the line alone.
    ? groupOrder.map((g, i) => ({ label: g || "(none)", color: seriesColor(i, palette), marker: false, select: { as: "section" as const, id: "Parallel coordinates" } }))
    : [];
  const leg = resolveLegend(plot, legendSource, measure, fonts.legend.size, width);
  const CB_W = valueMode ? 58 : 0; // colour-scale bar + its min/max labels
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + CB_W + pad.r;
  const plotX = DEFAULTS.marginRight + pad.l;
  const plotY = DEFAULTS.marginTop + topPad;
  const plotW = Math.max(1, width - plotX - marginRight);
  // Note: `pad.b` and `pad.l` (above) must be applied here: top and right are folded into `topPad`
  // and `marginRight`, but the other two sides are not. An axis-less kind has no axis margin to
  // absorb them, so all four have to be applied by hand.
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - DEFAULTS.marginRight - pad.b);

  const showTicks = ps.showTicks !== false;
  /**
   * Two fonts, and that is the point. The variable name is the axis's title; the scale numbers
   * are its ticks. With one shared font they would have the same size, weight and colour and
   * could not be tuned apart — shrinking the numbers to stop N ladders crowding the data field
   * would shrink every variable name with them.
   */
  const nameFont = fonts.axisTitle;
  /**
   * Gap between the variable name's baseline and the axis top — derived, not picked.
   *
   * The topmost tick label is centred on the axis top, so it rises ~0.5em above it, while the
   * name's descenders reach ~0.3em below its own baseline. A flat 6px gap would therefore put
   * the top tick label into the variable name. Both terms have to be in the sum, or one font size can be raised into the other.
   */
  const nameGap = showTicks ? nameFont.size * 0.3 + fonts.tick.size * 0.5 + 3 : 6;
  /**
   * Neighbouring names never print on each other. Every name is centred on its axis at one height, so long names on
   * close axes would run together (e.g. "RespondersNon-respondersSite North"). When two neighbours
   * would touch, every second name sits one line higher, and the band above the axes grows by that line. Decided
   * here, before the axes are spaced, from the narrowest spacing the end insets allow (a quarter kept in hand).
   */
  const nameOf = (a: { id: string; name: string }): string => ps.perAxis?.[a.id]?.title?.trim() || a.name;
  const nameW = (t: string): number => measure(t, nameFont.size) * 1.1;
  // The end insets as the layout below takes them (half the end names, the first axis's numbers - estimated from its
  // range at the tick font), so the estimate is the spacing the axes will actually get.
  const numW = (a: { min: number; max: number }): number => Math.max(...[a.min, a.max].map((v) => measure(String(Number(v.toPrecision(3))), fonts.tick.size))) * 1.1 + 9;
  const firstA = axisStats[0], lastA = axisStats[axisStats.length - 1];
  const insetEst = firstA && lastA ? Math.min(plotW * 0.35, Math.max(Math.min(40, plotW * 0.12), Math.max(nameW(nameOf(firstA)) / 2, numW(firstA)) + 2 - plotX, nameW(nameOf(lastA)) / 2 + 2 - (width - plotX - plotW))) : 0;
  const spacingEst = axisStats.length > 1 ? (plotW - 2 * insetEst) / (axisStats.length - 1) : Infinity;
  const staggerNames = axisStats.some((a, i) => i > 0 && (nameW(nameOf(axisStats[i - 1]!)) + nameW(nameOf(a))) / 2 + 6 > spacingEst);
  const nameStep = staggerNames ? nameFont.size * 1.15 : 0;
  const labelH = nameFont.size * 0.85 + nameGap + 2 + nameStep; // room above each axis for its variable name
  // Room below the axis foot: the lowest tick label is centred on its own y, so it needs half
  // a line, not a whole one.
  const tickH = showTicks ? fonts.tick.size * 0.7 : 2;
  const topY = plotY + labelH;
  const botY = Math.max(topY + 1, plotY + plotH - tickH);
  const n = axisStats.length;
  const TICK_MARK = 4;
  const TICK_GAP = 3; // between the tick mark and its label
  /**
   * Ticks per axis. Auto-derived from the axis length and the tick font, so a short figure or
   * a large font cannot produce a ladder whose labels sit on each other.
   */
  const autoTicks = Math.round((botY - topY) / Math.max(1, fonts.tick.size * 5.5));
  const tickCount = Math.max(2, Math.min(8, ps.tickCount ?? autoTicks));
  /** Minimum pixel gap between two tick labels (they are centred on their own y). */
  const MIN_TICK_GAP = Math.max(10, fonts.tick.size * 1.9);
  /**
   * Pick one axis's ladder: at most `tickCount` rungs, none closer than MIN_TICK_GAP, every
   * value on the round 1/2/5×10ᵏ sequence a reader expects.
   *
   * Note: ask d3 again for a smaller count; never thin the ladder it returned. `ticks(n)` treats
   * the count as a hint and overshoots freely (asking for 8 on a 470px axis returns 13), so
   * the obvious approach is to drop every k-th tick — and that silently produces steps like 1.5,
   * which is off the sequence and, if the label formatter derives its decimals from the step's
   * magnitude, prints the 1.5 tick as "2" and the 4.5 one as "5". A mislabelled tick misreports
   * the data. Walking the requested count down keeps every candidate round.
   *
   * `exact` — the domain stays the data extent. Rounding it outward (d3 `nice()`) is right for
   * an ordinary axis and wrong here: each axis is scaled independently so the bundle fills it,
   * and at these small counts nice() rounds by a whole step — an axis with data 0.0–2.6 would
   * widen to −1…3, throwing away a third of the axis and offering a negative value (e.g. a
   * petal width) to read off. Ticks inside the extent give the ladder without either cost.
   */
  /**
   * Note: a per-axis `majorStep` is an exact request and is honoured exactly — the auto path's
   * "walk the count down until the labels clear each other" is a way of guessing a good
   * spacing, and second-guessing a number the user typed would make the field feel broken.
   * That matches how every other axis in the app treats its own tick interval.
   */
  const pickLadder = (lo: number, hi: number, spec: ParallelAxisSpec | undefined, yLo: number, yHi: number): ParallelTickScene[] => {
    const minor = spec?.minorCount;
    const spacing = minor && minor > 0 ? { minorCount: minor } : undefined;
    // The pixel range is passed in (low-end first), so a reversed axis needs no special case
    // anywhere below: buildScale maps the domain onto whatever direction it is handed.
    const at = (want: number, step?: number): ParallelTickScene[] =>
      buildScale("linear", [lo, hi], [yLo, yHi], want, true, undefined, step ? { ...spacing, majorStep: step } : spacing)
        .ticks.map((t) => ({ value: t.value, y: t.pos, label: "", ...(t.minor ? { minor: true } : {}) }));
    if (spec?.majorStep != null && Number.isFinite(spec.majorStep) && spec.majorStep > 0) {
      return at(tickCount, spec.majorStep);
    }
    const want0 = Math.max(2, Math.min(8, spec?.tickCount ?? tickCount));
    let fallback = at(2);
    for (let want = want0; want >= 2; want--) {
      const ts = at(want);
      const majors = ts.filter((t) => !t.minor);
      if (majors.length < 2) continue;
      fallback = ts;
      if (majors.length <= want0 && Math.abs(majors[1]!.y - majors[0]!.y) >= MIN_TICK_GAP) return ts;
    }
    return fallback;
  };
  /**
   * Inset of the first/last axis from the plot edge, so their centred labels stay on the canvas.
   *
   * A flat `min(40, plotW * 0.12)` would be a guess about label width rather than a
   * measurement of it: at a large font the end axes' variable names and min/max values are far
   * wider than 40px, so half of each would hang off the figure. Derive the inset from the widest thing
   * actually drawn at each end instead, then clamp so the axes cannot collapse together.
   */
  /**
   * Per-axis ladder + labels. One decimal count per axis, taken from what the ticks need to
   * print exactly rather than guessed from the step's magnitude. Formatting each number on its
   * own (`Number.isInteger ? String : toFixed(2)`) would show "6" on one axis and "1.30" on
   * the next.
   */
  const perAxis = ps.perAxis ?? {};
  const scaled = axisStats.map((a) => {
    // The one place orientation is decided. Everything downstream — the ladder, the custom
    // ticks, the polylines, and the renderer's brush — interpolates between these two pixels,
    // so nothing else has to know a reversed axis exists.
    const yAtMin = perAxis[a.id]?.reversed === true ? topY : botY;
    const yAtMax = perAxis[a.id]?.reversed === true ? botY : topY;
    const yOf = (v: number): number => yAtMin + ((v - a.min) / (a.max - a.min || 1)) * (yAtMax - yAtMin);
    const kept = showTicks ? pickLadder(a.min, a.max, perAxis[a.id], yAtMin, yAtMax) : [];
    // Decimals come from the majors only — a minor tick carries no label, so letting it widen
    // the decimal count would add a place no visible number needs.
    let decimals = 0;
    for (const t of kept) {
      if (t.minor) continue;
      for (let d = decimals; d <= 6; d++) {
        if (Math.abs(Number(t.value.toFixed(d)) - t.value) < 1e-9) { decimals = Math.max(decimals, d); break; }
        if (d === 6) decimals = 6;
      }
    }
    /**
     * How this axis's numbers are written. An explicit `decimals` wins over the count derived
     * above: that derivation is what to do when nobody has said otherwise, and a user asking
     * for 1 place means 1. `format` likewise defaults to plain decimals rather than "auto",
     * so the ladder prints plain decimals unless told otherwise.
     */
    const spec = perAxis[a.id];
    const fmt: TickFormat = {
      format: spec?.format ?? "decimal",
      decimals: spec?.decimals ?? decimals,
      ...(spec?.prefix ? { prefix: spec.prefix } : {}),
      ...(spec?.suffix ? { suffix: spec.suffix } : {}),
      ...(spec?.thousands ? { thousands: spec.thousands } : {}),
    };
    const ticks: ParallelTickScene[] = kept.map((t) => ({
      ...t,
      label: t.minor ? "" : makeTickLabel(t.value, "linear", fmt),
    }));
    /**
     * Custom ticks, on top of the ladder — a threshold, a cut-off, a reference level.
     *
     * Out-of-range values are dropped rather than clamped: a tick pinned to the axis end would
     * claim the data reaches a value it does not. (`resolveAxisExtras` does the same for an
     * ordinary axis; this mirrors it rather than reinventing it.) A custom tick landing on a
     * ladder value replaces that rung, so the two never draw on top of each other — and the
     * user's own label wins, which is the point of adding it there.
     */
    for (const ex of perAxis[a.id]?.extraTicks ?? []) {
      if (!Number.isFinite(ex.value) || ex.value < a.min || ex.value > a.max) continue;
      const y = yOf(ex.value);
      const label = ex.label && ex.label.length ? ex.label : makeTickLabel(ex.value, "linear", fmt);
      const at = ticks.findIndex((t) => Math.abs(t.value - ex.value) < 1e-9);
      if (at >= 0) ticks[at] = { value: ex.value, y, label };
      else ticks.push({ value: ex.value, y, label });
    }
    // A title override renames the axis on the figure only; the column keeps its own name.
    return { ...a, name: spec?.title?.trim() ? spec.title.trim() : a.name, ticks, yAtMin, yAtMax };
  });

  const SLACK = 1.1; // `measure` under-reads — the axis-title fit uses the same allowance
  const wOf = (t: string): number => measure(t, fonts.tick.size) * SLACK;
  // The name is measured at its own size, or the end axes' inset is budgeted from the wrong font.
  const wName = (t: string): number => measure(t, nameFont.size) * SLACK;
  // The two label kinds sit differently and must be budgeted differently:
  //  · the variable name is centred on the axis      → needs half its width each side;
  //  · a tick value is drawn left of its tick mark, anchored "end" (PlotFigure)
  //    → it needs its full width to the left, and nothing to the right.
  // Budgeted as centred, a value would run off the left edge.
  const valueW = (a: (typeof scaled)[number] | undefined): number => {
    const labels = (a?.ticks ?? []).filter((t) => t.label !== "");
    return labels.length ? Math.max(...labels.map((t) => wOf(t.label))) + TICK_MARK + TICK_GAP + 2 : 0;
  };
  const nameHalf = (a: (typeof scaled)[number] | undefined): number => (a ? wName(a.name) / 2 : 0);
  const first = scaled[0];
  const last = scaled[scaled.length - 1];
  const needLeft = Math.max(nameHalf(first), valueW(first)) + 2 - plotX;
  const needRight = nameHalf(last) + 2 - (width - plotX - plotW);
  const hInset = Math.min(plotW * 0.35, Math.max(Math.min(40, plotW * 0.12), needLeft, needRight));
  const axX = (i: number): number => (n <= 1 ? plotX + plotW / 2 : plotX + hInset + (i / (n - 1)) * (plotW - 2 * hInset));

  const brushOf = (id: string): [number, number] | undefined => {
    const br = brushes[id];
    return Array.isArray(br) && br.length === 2 && Number.isFinite(br[0]) && Number.isFinite(br[1])
      ? [Math.min(br[0], br[1]), Math.max(br[0], br[1])]
      : undefined;
  };
  const axes: ParallelAxisScene[] = scaled.map((a, i) => {
    const loff = plot.pointStyles?.[`${a.id}:${a.id}`];
    const brush = brushOf(a.id);
    return {
      x: axX(i),
      topY,
      botY,
      label: a.name,
      labelX: axX(i),
      labelY: topY - nameGap - (i % 2 === 1 ? nameStep : 0),
      colId: a.id,
      ...(loff?.valueDx != null ? { labelDx: loff.valueDx } : {}),
      ...(loff?.valueDy != null ? { labelDy: loff.valueDy } : {}),
      min: a.min,
      max: a.max,
      yAtMin: a.yAtMin,
      yAtMax: a.yAtMax,
      ticks: a.ticks,
      ...(brush ? { brush } : {}),
    };
  });

  // One polyline per row (complete-case: a row missing any axis value is skipped).
  const lines: ParallelLineScene[] = [];
  let dropped = 0;
  const anyBrush = scaled.some((a) => brushOf(a.id));
  for (const r of table.rows) {
    const pts: { x: number; y: number }[] = [];
    let complete = true;
    let inBrush = true; // within EVERY brushed axis's range
    for (let i = 0; i < scaled.length; i++) {
      const a = scaled[i]!;
      const dsi = dsById.get(a.id);
      const v = dsi ? rowDatasetMean(r, dsi) : toNumber(r.cells[a.id]);
      if (!Number.isFinite(v)) { complete = false; break; }
      // Interpolate between the axis's own endpoints — a reversed axis needs no branch here.
      const t = (v - a.min) / (a.max - a.min || 1);
      pts.push({ x: axX(i), y: a.yAtMin + t * (a.yAtMax - a.yAtMin) });
      const br = brushOf(a.id);
      if (br && (v < br[0] || v > br[1])) inBrush = false;
    }
    if (!complete || pts.length < 2) { dropped++; continue; }
    let color = singleColor;
    if (valueMode) {
      const cv = toNumber(r.cells[colorColId!]);
      color = Number.isFinite(cv) ? valueColor(cv) : "#cccccc";
    } else if (colorColId) {
      color = groupColor.get(String(r.cells[colorColId] ?? "").trim()) ?? singleColor;
    }
    // A per-line override (click one line → pick a colour, to pull a single case out of the
    // bundle) wins over the colour-column mapping for that row only.
    // Per-line width/opacity ride alongside the per-line colour: colour alone cannot pull one
    // case out of a dense bundle. Undefined falls through to the scene-wide values.
    const wOverride = ps.lineWidths?.[r.id];
    const oOverride = ps.lineOpacities?.[r.id];
    lines.push({
      id: r.id,
      color: ps.lineColors?.[r.id] ?? color,
      points: pts,
      ...(anyBrush && !inBrush ? { dim: true } : {}),
      ...(wOverride !== undefined ? { width: wOverride } : {}),
      ...(oOverride !== undefined ? { opacity: oOverride } : {}),
    });
  }
  if (dropped > 0) warnings.push(`${dropped} row(s) with a missing value were skipped.`);
  if (lines.length === 0 && axisStats.length >= 2) warnings.push("No complete rows to plot.");

  const parallel: ParallelScene = {
    axes,
    lines,
    lineWidth: ps.lineWidth ?? 1,
    lineOpacity: ps.lineOpacity ?? 0.6,
    curved: ps.curved ?? false,
    showTicks,
    tickLen: TICK_MARK + TICK_GAP,
    nameFont,
    ...(ps.axisColor ? { axisColor: ps.axisColor } : {}),
  };

  // Continuous colour → a colour-scale bar in the reserved right strip.
  let colorbar: PlotScene["colorbar"];
  if (valueMode) {
    const bx = plotX + plotW + leg.outsideRightWidth + 16;
    const stops = ramps.barStops(ramp, "#440154", "#fde725", rampRev, lineShape);
    // Title from table.columns (not datasets) — the colour column may be the X column,
    // which tableDatasets() omits, so a datasets lookup would drop the title.
    // The bar's heading: a user override wins over the colour column's name (blank = hide).
    const cbTitle = ps.colorbarTitle ?? (colorColId ? table.columns.find((c) => c.id === colorColId)?.name : undefined);
    colorbar = { bar: { x: bx, y: topY, w: 12, h: Math.max(1, botY - topY) }, stops, min: cvMin, max: cvMax, ...(cbTitle ? { title: cbTitle } : {}) };
  }

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "parallel",
    fonts,
    parallel,
    ...(colorbar ? { colorbar } : {}),
    ...(plot.colorbarOffset ? { colorbarOffset: plot.colorbarOffset } : {}),
    warnings,
  };
}

/** Closed SVG band from a left slice (x0, y0Top..y0Bot) to a right slice (x1, y1Top..y1Bot) —
 *  a smooth cubic ribbon (or a straight quad). */
function alluvialBand(x0: number, y0Top: number, y0Bot: number, x1: number, y1Top: number, y1Bot: number, straight: boolean): string {
  if (straight) return `M ${x0} ${y0Top} L ${x1} ${y1Top} L ${x1} ${y1Bot} L ${x0} ${y0Bot} Z`;
  const mx = (x0 + x1) / 2;
  return `M ${x0} ${y0Top} C ${mx} ${y0Top} ${mx} ${y1Top} ${x1} ${y1Top} L ${x1} ${y1Bot} C ${mx} ${y1Bot} ${mx} ${y0Bot} ${x0} ${y0Bot} Z`;
}

/** `alluvialBand` transposed for a vertical flow (horizontal stacked bars): the ribbon runs
 *  from the bottom edge of one bar (y0, spanning x0L..x0R) down to the top edge of the next
 *  (y1, spanning x1L..x1R), easing in y instead of x. */
function alluvialBandV(y0: number, x0L: number, x0R: number, y1: number, x1L: number, x1R: number): string {
  const my = (y0 + y1) / 2;
  return `M ${x0L} ${y0} C ${x0L} ${my} ${x1L} ${my} ${x1L} ${y1} L ${x1R} ${y1} C ${x1R} ${my} ${x0R} ${my} ${x0R} ${y0} Z`;
}

/**
 * Alluvial / parallel-sets (kind "alluvial"): N ordered categorical columns are the axes;
 * each axis stacks its category blocks (nodes) sized by row count, and between adjacent
 * axes ribbons connect the blocks. Colours flow across all axes — each distinct full
 * category-tuple is one stream, coloured by its category on the first (or last) axis, so a
 * colour is traceable end-to-end. Ribbons within a node stack in a consistent global order.
 */
function buildAlluvialScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.alluvial ?? {};

  const cols = table.columns;
  const isTextCol = (colId: NodeId): boolean => {
    let text = 0;
    let tot = 0;
    for (const r of table.rows) {
      const v = r.cells[colId];
      if (v != null && String(v).trim() !== "") {
        tot++;
        if (!Number.isFinite(toNumber(v))) text++;
      }
    }
    return tot > 0 && text >= tot * 0.5;
  };
  let axisColIds = (cfg.columns ?? []).filter((id) => cols.some((c) => c.id === id));
  if (axisColIds.length < 2) {
    const auto = cols.filter((c) => isTextCol(c.id)).map((c) => c.id);
    if (auto.length >= 2) axisColIds = auto;
  }
  if (axisColIds.length < 2) axisColIds = cols.slice(0, 2).map((c) => c.id);
  const axisCols = axisColIds.map((id) => cols.find((c) => c.id === id)!).filter(Boolean);
  const nAxes = axisCols.length;
  if (nAxes < 2) warnings.push("An alluvial plot needs at least two categorical columns.");

  // Complete-case rows → category tuples (a row missing any axis category is skipped).
  const rowCats: string[][] = [];
  let dropped = 0;
  for (const r of table.rows) {
    const cats = axisCols.map((c) => String(r.cells[c.id] ?? "").trim());
    if (cats.some((v) => v === "")) { dropped++; continue; }
    rowCats.push(cats);
  }
  if (dropped > 0) warnings.push(`${dropped} row(s) with a missing category were skipped.`);
  const total = rowCats.length || 1;

  // Per-axis categories (first-appearance order) + counts + an index map.
  const axisCats: string[][] = axisCols.map(() => []);
  const axisCount = axisCols.map(() => new Map<string, number>());
  const catIndex = axisCols.map(() => new Map<string, number>());
  for (const cats of rowCats) {
    cats.forEach((cat, ax) => {
      const m = axisCount[ax]!;
      if (!m.has(cat)) { m.set(cat, 0); catIndex[ax]!.set(cat, axisCats[ax]!.length); axisCats[ax]!.push(cat); }
      m.set(cat, m.get(cat)! + 1);
    });
  }

  // Colour streams by the category on the first (default) or last axis.
  const colorAxis = cfg.colorBy === "last" ? nAxes - 1 : 0;
  const catColor = new Map<string, string>();
  (axisCats[colorAxis] ?? []).forEach((cat, i) => catColor.set(cat, seriesColor(i, palette)));

  // Flows = distinct full category tuples → count, ordered by category-index sequence.
  const flowCount = new Map<string, number>();
  const flowCats = new Map<string, string[]>();
  for (const cats of rowCats) {
    const k = cats.join("␀");
    flowCount.set(k, (flowCount.get(k) ?? 0) + 1);
    if (!flowCats.has(k)) flowCats.set(k, cats);
  }
  const flowKeys = [...flowCount.keys()].sort((a, b) => {
    const ca = flowCats.get(a)!;
    const cb = flowCats.get(b)!;
    for (let ax = 0; ax < nAxes; ax++) {
      const d = (catIndex[ax]!.get(ca[ax]!) ?? 0) - (catIndex[ax]!.get(cb[ax]!) ?? 0);
      if (d) return d;
    }
    return 0;
  });

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const nodeWidth = cfg.nodeWidth ?? 16;
  const gapFrac = Math.max(0, Math.min(0.2, cfg.nodeGap ?? 0.02));
  const showLabels = cfg.showLabels !== false;
  // Reserve space for the end-axis node labels (they extend left of axis 0 / right of the
  // last axis). Cap it both by an absolute max and by a fraction of the figure width, so a
  // small thumbnail (e.g. 360px) isn't squished to a sliver — at 360px a flat 130px cap on
  // each side would leave only ~64px of plot.
  // The cap follows the font above the house size (130 px at 20 px; 195 at 30): asked for a
  // 30 px label, the margins grow instead of the labels leaving the canvas. At and below
  // 20 px the cap is 130 px.
  const labelCap = Math.min(Math.max(130, Math.round(6.5 * fonts.tick.size)), Math.round(width * 0.24));
  // Reserve the header band from the legend font — the axis-header (column-name) labels
  // are rendered with fonts.legend (AlluvialFigure), so a larger legend size must not
  // overrun the top node row.
  const axisHeaderH = fonts.legend.size + 10;
  const marginTop = DEFAULTS.marginTop + topPad + axisHeaderH;
  const marginBottom = DEFAULTS.marginTop + pad.b;
  // Node labels are stacked down each column: the font shrinks to the row band of the densest
  // column (the fit the bar chart, the heatmap and the swimmer plot use), never below 7 px.
  const plotHApprox = Math.max(1, height - marginTop - marginBottom);
  const rowFit = Math.min(1, ...axisCats.map((cs) => fitStackedLabels(cs.length, plotHApprox / Math.max(1, cs.length), fonts.tick.size).font / fonts.tick.size));
  const labelFont = showLabels ? Math.max(7, Math.floor(fonts.tick.size * rowFit)) : fonts.tick.size;
  if (showLabels && labelFont < fonts.tick.size && plot.xAxis?.tickFont?.size !== undefined) {
    warnings.push(`Node labels are drawn at ${labelFont}px, not the ${fonts.tick.size}px asked for: the rows leave no room. A taller figure will honour it.`);
  }
  const labelW = showLabels ? Math.min(labelCap, Math.max(0, ...axisCats.flat().map((c) => measure(c, labelFont))) + 34) : 6;
  const marginLeft = DEFAULTS.marginRight + labelW + pad.l;
  const marginRight = DEFAULTS.marginRight + labelW + pad.r;
  const plotX = marginLeft;
  const plotY = marginTop;
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - marginTop - marginBottom);
  const axisX = (ax: number): number => (nAxes <= 1 ? plotX + (plotW - nodeWidth) / 2 : plotX + (ax / (nAxes - 1)) * (plotW - nodeWidth));

  // Nodes + per-node flow slices (a flow occupies the same y-range on both edges of a node).
  const nodes: AlluvialNode[] = [];
  const slice = new Map<string, { top: number; bot: number }>();
  for (let ax = 0; ax < nAxes; ax++) {
    const cats = axisCats[ax]!;
    const gapPx = gapFrac * plotH;
    const avail = Math.max(1, plotH - gapPx * Math.max(0, cats.length - 1));
    const x = axisX(ax);
    let y = plotY;
    for (const cat of cats) {
      const count = axisCount[ax]!.get(cat)!;
      const h = (count / total) * avail;
      let sy = y;
      for (const fk of flowKeys) {
        if (flowCats.get(fk)![ax] !== cat) continue;
        const fh = (flowCount.get(fk)! / total) * avail;
        slice.set(`${ax}|${cat}|${fk}`, { top: sy, bot: sy + fh });
        sy += fh;
      }
      const first = ax === 0;
      /**
       * The node label's drag offset, keyed `"<axisColId>:<category>"` in `pointStyles` — the same
       * store a pie slice label and a parallel-coordinates axis name use, so dragging one of these
       * needs no new model field. The column id (not the axis index) is the key, so reordering the
       * axes carries a nudged label with its own category instead of handing it to a stranger.
       */
      const ndCol = axisCols[ax]?.id;
      const ndOff = ndCol ? plot.pointStyles?.[`${ndCol}:${cat}`] : undefined;
      nodes.push({
        axis: ax,
        category: cat,
        x,
        y,
        w: nodeWidth,
        h,
        color: cfg.nodeColors?.[`${ax}:${cat}`] ?? cfg.nodeColor ?? "#9aa0aa",
        label: showLabels ? `${cat} (${count})` : "",
        count,
        labelX: first ? x - 6 : x + nodeWidth + 6,
        labelY: y + h / 2 + labelFont * 0.34,
        labelAnchor: first ? "end" : "start",
        ...(ndCol ? { colId: ndCol } : {}),
        ...(ndOff?.valueDx != null ? { labelDx: ndOff.valueDx } : {}),
        ...(ndOff?.valueDy != null ? { labelDy: ndOff.valueDy } : {}),
      });
      y += h + gapPx;
    }
  }
  // A node's height is its count, so a small category gets a short block — and its label, centred
  // on that block, lands on the neighbour's. Nudge them apart within each column rather than
  // hiding one: the label carries the category name and its count, so a dropped one loses data.
  // Biggest node first, since it has the strongest claim to sitting exactly on its block.
  // Note: one pass over every column, not per column. A label hangs to the right of its node
  // (except the first axis), and at a large font it is wider than the gap between axes — so it
  // reaches into the next column's labels. De-conflicting each column in isolation would miss
  // exactly that case (labels on different axes overlapping).
  let drawnLabelFont = labelFont;
  {
    const labelled = nodes.filter((nd) => nd.label !== "").sort((a, b) => b.h - a.h);
    if (labelled.length > 1) {
      // A label the nudge cannot place at this font is a collision on the page. Come down a
      // pixel at a time (to 7) until every label has a free spot: at 30 px in four columns
      // a label can otherwise have nowhere to go but onto its neighbour.
      let result = nudgeApartVertically(
        labelled.map((nd) => ({ id: `${nd.axis}|${nd.category}`, text: nd.label, x: nd.labelX, y: nd.labelY, anchor: nd.labelAnchor })),
        drawnLabelFont, measure, { w: width, h: height },
      );
      while (result.unplaced.length > 0 && drawnLabelFont > 7) {
        drawnLabelFont -= 1;
        result = nudgeApartVertically(
          labelled.map((nd) => ({ id: `${nd.axis}|${nd.category}`, text: nd.label, x: nd.labelX, y: nd.labelY, anchor: nd.labelAnchor })),
          drawnLabelFont, measure, { w: width, h: height },
        );
      }
      for (const nd of labelled) {
        const dy = result.moved.get(`${nd.axis}|${nd.category}`);
        if (dy != null) nd.labelY += dy;
      }
    }
  }

  // Ribbons: one per (flow, junction), connecting the flow's slice in adjacent nodes.
  const ribbons: AlluvialRibbon[] = [];
  const ribbonOpacity = Math.max(0.05, Math.min(1, cfg.ribbonOpacity ?? 0.5));
  const straight = cfg.straight ?? false;
  for (const fk of flowKeys) {
    const fc = flowCats.get(fk)!;
    // A recoloured node on the colour axis also recolours the flows it originates.
    const color = cfg.nodeColors?.[`${colorAxis}:${fc[colorAxis]}`] ?? catColor.get(fc[colorAxis]!) ?? seriesColor(0, palette);
    for (let ax = 0; ax < nAxes - 1; ax++) {
      const L = slice.get(`${ax}|${fc[ax]}|${fk}`);
      const R = slice.get(`${ax + 1}|${fc[ax + 1]}|${fk}`);
      if (!L || !R) continue;
      // `select` names the node the colour came from, one line above — the same lookup, so the
      // two can never disagree about which swatch moves this band.
      ribbons.push({ path: alluvialBand(axisX(ax) + nodeWidth, L.top, L.bot, axisX(ax + 1), R.top, R.bot, straight), color, opacity: ribbonOpacity, count: flowCount.get(fk)!, select: { axis: colorAxis, category: String(fc[colorAxis] ?? "") } });
    }
  }

  // The axis header's own drag offset, self-keyed (`"<colId>:<colId>"`) — the convention a
  // parallel-coordinates axis name already uses, so an axis label and a node label cannot
  // collide in `pointStyles` even when a category happens to share a column's name.
  const axisLabels = showLabels
    ? axisCols.map((c, ax) => {
        const off = plot.pointStyles?.[`${c.id}:${c.id}`];
        return {
          label: c.name,
          x: axisX(ax) + nodeWidth / 2,
          y: plotY - 8,
          colId: c.id,
          ...(off?.valueDx != null ? { dx: off.valueDx } : {}),
          ...(off?.valueDy != null ? { dy: off.valueDy } : {}),
        };
      })
    : [];
  const alluvial: AlluvialScene = { nodes, ribbons, axisLabels, nodeStroke: "#ffffff" };

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: [],
    legendLayout: NO_LEGEND,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "alluvial",
    fonts: drawnLabelFont < fonts.tick.size ? { ...fonts, tick: { ...fonts.tick, size: drawnLabelFont } } : fonts,
    alluvial,
    warnings,
  };
}

/**
 * Node-link network graph (kind "network"). The table is an edge list: the first
 * column is the source, the second the target, the first following numeric column
 * the edge weight, and a further numeric column a per-node value (diverging colour,
 * from the node's first appearance as a source). Nodes are laid out force-directed
 * (default) or circular by the self-contained `networkLayout` engine, then mapped
 * into the plot rect. No cartesian axes.
 */
function buildNetworkScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.network ?? {};

  const cols = table.columns;
  // A column is numeric when most of its non-blank cells parse as finite numbers.
  const isNumericCol = (colId: NodeId): boolean => {
    let num = 0;
    let tot = 0;
    for (const r of table.rows) {
      const v = r.cells[colId];
      if (v != null && String(v).trim() !== "") {
        tot++;
        if (Number.isFinite(toNumber(v))) num++;
      }
    }
    return tot > 0 && num >= tot * 0.6;
  };
  const srcCol = cols[0];
  const tgtCol = cols[1];
  // Weight = first numeric column after the two endpoints; value = the next numeric one.
  const numericCols = cols.slice(2).filter((c) => isNumericCol(c.id));
  const weightCol = numericCols[0];
  const valueCol = numericCols[1];
  if (!srcCol || !tgtCol) {
    warnings.push("A network graph needs an edge list — a source column and a target column.");
  }

  // Explicit data bindings: node group (categorical colour) and node size
  // (a metric) each name a column by id. A binding that cannot be honoured refuses with a warning.
  const groupCol = cfg.groupColumn ? cols.find((c) => c.id === cfg.groupColumn) : undefined;
  if (cfg.groupColumn && !groupCol) warnings.push("The node-group column is missing from this table — pick another in the Network graph section.");
  const sizeCol = cfg.sizeColumn ? cols.find((c) => c.id === cfg.sizeColumn) : undefined;
  if (cfg.sizeColumn && !sizeCol) warnings.push("The node-size column is missing from this table — pick another in the Network graph section.");

  const sources = srcCol ? table.rows.map((r) => String(r.cells[srcCol.id] ?? "").trim()) : [];
  const targets = tgtCol ? table.rows.map((r) => String(r.cells[tgtCol.id] ?? "").trim()) : [];
  const weights = weightCol ? table.rows.map((r) => toNumber(r.cells[weightCol.id])) : undefined;
  const values = valueCol ? table.rows.map((r) => toNumber(r.cells[valueCol.id])) : undefined;
  const groupCells = groupCol
    ? table.rows.map((r) => { const v = r.cells[groupCol.id]; return v == null ? undefined : String(v); })
    : undefined;
  const metricCells = sizeCol ? table.rows.map((r) => toNumber(r.cells[sizeCol.id])) : undefined;
  const graph = buildGraph(sources, targets, weights, values, groupCells, metricCells);
  if (srcCol && tgtCol && graph.edges.length === 0) warnings.push("No edges — check the source / target columns.");

  // A bound column whose cells never reach a node is a silent no-op — say so and fall back.
  const hasGroups = !!groupCol && graph.nodes.some((n) => n.group !== undefined);
  if (groupCol && !hasGroups) warnings.push("The node-group column has no usable values — nodes keep their value / flat colour.");
  const hasMetrics = !!sizeCol && graph.nodes.some((n) => n.metric !== undefined);
  if (sizeCol && !hasMetrics) warnings.push("The node-size column has no numeric values — node sizes follow degree instead.");

  // Node labels get their own size, not the tick font: the tick font is sized for axis
  // charts and at its default swamps a node-link diagram (a name ends up wider than the gap
  // between nodes). De-confliction and the renderer must use the same number.
  const labelSize = Math.max(1, cfg.labelSize ?? NETWORK_LABEL_SIZE);

  // Per-node value stats — needed before the margins so the value legend can reserve space.
  const vals = graph.nodes.map((n) => n.value).filter((v): v is number => v !== undefined && Number.isFinite(v));
  const hasValues = vals.length > 0;
  // While a group column owns the colour channel the diverging ramp is not what is drawn,
  // so its legend (and its left-margin reserve) must go too — a key must never claim an
  // encoding the picture doesn't use. The value still shows in each node's tooltip.
  const showValueLegend = hasValues && !hasGroups;
  const vMin = hasValues ? Math.min(...vals) : 0;
  const vMax = hasValues ? Math.max(...vals) : 1;
  // The exact legend label strings, measured here to size the reserve and carried on the
  // scene so the renderer draws the same strings (re-formatting there would size the same
  // space a second time, independently, and the two could disagree).
  const fmtLegendValue = (v: number): string => (Number.isFinite(v) ? String(Number(v.toFixed(6))) : "");
  const legendMinLabel = fmtLegendValue(vMin);
  const legendMaxLabel = fmtLegendValue(vMax);
  // The value legend sits as a vertical bar in the left margin (its labels above/below the
  // bar), clear of the network, the node labels (which hang right) and the title band.
  const legendReserveLeft = showValueLegend
    ? Math.max(8, Math.ceil(measure(legendMinLabel, labelSize)), Math.ceil(measure(legendMaxLabel, labelSize))) + 6
    : 0;

  // Group + edge-sign legend rows through the standard legend: rows target the "Network graph"
  // section; sign rows are line-only swatches, and only the signs actually drawn get a row.
  // Resolved before the margins so the outside-right column reserves its room. An unbound
  // network resolves no rows and reserves no room.
  const groupNames: string[] = [];
  if (hasGroups) for (const nd of graph.nodes) {
    if (nd.group !== undefined && !groupNames.includes(nd.group)) groupNames.push(nd.group);
  }
  const groupColorOf = (g: string): string => seriesColor(groupNames.indexOf(g), palette);
  const signOn = cfg.edgeSignColors === true;
  const posColor = cfg.edgePositiveColor ?? "#c0392b";
  const negColor = cfg.edgeNegativeColor ?? "#3b6fb0";
  const rawLegend: LegendEntry[] = groupNames.map((g) => ({
    label: g, color: groupColorOf(g), symbol: "circle" as const, select: { as: "section" as const, id: "Network graph" },
  }));
  if (signOn) {
    const signs = new Set(graph.edges.map((e) => e.sign));
    if (signs.has(1)) rawLegend.push({ label: "Positive links", color: posColor, marker: false, select: { as: "section", id: "Network graph" } });
    if (signs.has(-1)) rawLegend.push({ label: "Negative links", color: negColor, marker: false, select: { as: "section", id: "Network graph" } });
  }
  const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // Node labels hang off each node to the right, so the right margin has to hold one — a flat
  // 18px would not, and every right-hand node would push its name off the canvas. Reserve
  // the widest label, capped (as the alluvial builder caps its own) so one very long name
  // cannot eat the whole plot. The label-side flip in `nodes` below is only a backstop for a
  // name too long even for the cap.
  const widestNodeLabel = (cfg.showLabels ?? true)
    ? Math.max(0, ...graph.nodes.map((nd) => measure(cfg.nodeLabels?.[nd.id] ?? nd.label, labelSize)))
    : 0;
  const labelReserve = Math.min(Math.round(width * 0.18), Math.ceil(widestNodeLabel) + 6);
  const marginLeft = DEFAULTS.marginRight + pad.l + legendReserveLeft;
  const marginRight = DEFAULTS.marginRight + labelReserve + pad.r + leg.outsideRightWidth;
  // The room reserved for right-hand node names sits between the plot and an outside-right legend (the margin already
  // holds both), so the legend starts past it - drawn at the plot's edge, over that room, it would sit on a node name.
  // The plot keeps its size: only where the legend sits inside its own margin moves.
  if (leg.layout.position === "right" && leg.entries.length > 0 && labelReserve > 0) leg.layout = { ...leg.layout, outsidePad: labelReserve };
  const marginTop = DEFAULTS.marginTop + topPad;
  const marginBottom = DEFAULTS.marginTop + pad.b;
  const plotX = marginLeft;
  const plotY = marginTop;
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - marginTop - marginBottom);

  // Node radius: base size, optionally scaled by degree (sqrt so area tracks degree).
  const baseR = Math.max(1, cfg.nodeSize ?? 6);
  const sizeByDegree = cfg.sizeByDegree ?? true;
  const maxDeg = graph.nodes.reduce((m, nd) => Math.max(m, nd.degree), 0) || 1;
  const radiusOf = (deg: number): number => (sizeByDegree ? baseR * (0.7 + 0.9 * Math.sqrt(deg / maxDeg)) : baseR);
  // A bound size column beats degree scaling: the same 0.7–1.6× band, √-scaled over the
  // metric's min→max span so area tracks the value; a node with no metric sits at the floor.
  const metricSpan = (() => {
    if (!hasMetrics) return null;
    const ms = graph.nodes.map((n) => n.metric).filter((m): m is number => m !== undefined);
    return { min: Math.min(...ms), max: Math.max(...ms) };
  })();
  const metricRadius = (m: number | undefined): number => {
    if (!metricSpan) return baseR;
    if (m === undefined) return baseR * 0.7;
    const t = metricSpan.max > metricSpan.min ? (m - metricSpan.min) / (metricSpan.max - metricSpan.min) : 0.5;
    return baseR * (0.7 + 0.9 * Math.sqrt(t));
  };

  // Per-node value → diverging colour.
  // The value ramp follows an explicitly chosen palette, so the Palette control is live on a
  // valued network too. Untouched (`plot.palette` undefined) keeps the default blue→red — the
  // control only takes over once the user picks one.
  const paletteChosen = plot.palette !== undefined;
  const lowColor = cfg.lowColor ?? (paletteChosen ? seriesColor(0, palette) : "#3b6fb0");
  const highColor = cfg.highColor ?? (paletteChosen ? seriesColor(1, palette) : "#c0392b");
  const neutral = cfg.nodeColor ?? seriesColor(0, palette);
  const colorOf = (v: number | undefined): string => {
    // A node with no value takes `nodeColor` in both states. A fixed grey whenever the graph
    // has values would make the Node colour control inert on exactly the graphs people build;
    // the grey is only the fallback when no node colour is set.
    if (v === undefined || !Number.isFinite(v)) return hasValues ? (cfg.nodeColor ?? "#cfd3d8") : neutral;
    const t = vMax > vMin ? (v - vMin) / (vMax - vMin) : 0.5;
    return mix(lowColor, highColor, t);
  };

  // Layout in the unit box, normalise to fill it, then inset by the largest radius so
  // no node clips the plot edge and map to the plot rect.
  const layoutKind = cfg.layout ?? "force";
  const unit =
    layoutKind === "circular"
      ? circularLayout(graph.nodes)
      : layoutKind === "layered"
        ? layeredLayout(graph.nodes, graph.edges)
        : forceLayout(graph.nodes, graph.edges, cfg.seed !== undefined ? { seed: cfg.seed } : {});
  const norm = normalizePositions(unit);
  // A hand-set radius (nodeSizes) is the drawn radius, so the edge inset must honour it too;
  // then the bound size column; then degree scaling.
  const drawnRadius = (nd: { id: string; degree: number; metric?: number | undefined }): number =>
    Math.max(1, cfg.nodeSizes?.[nd.id] ?? (hasMetrics ? metricRadius(nd.metric) : radiusOf(nd.degree)));
  const rMax = graph.nodes.reduce((m, nd) => Math.max(m, drawnRadius(nd)), baseR);
  // Inset only by the node radius so no disc clips the plot edge — the node labels (which hang
  // right) are already reserved in `marginRight` (labelReserve) and a right-edge node whose label
  // would overflow flips it left (`overflowsRight` below). Reserving half the widest label on both
  // sides here as well would double-count it and collapse the graph into a narrow band, wasting
  // the right half of the figure.
  const insetX = rMax + 2;
  const insetY = rMax + 2;
  const availW = Math.max(1, plotW - 2 * insetX);
  const availH = Math.max(1, plotH - 2 * insetY);
  const posOf = new Map<string, { x: number; y: number }>();
  graph.nodes.forEach((nd, i) => {
    posOf.set(nd.id, { x: plotX + insetX + norm[i]!.x * availW, y: plotY + insetY + norm[i]!.y * availH });
  });
  // Manual position overrides (dragged nodes) — fractional of the plot rect, clamped.
  const manualPos = cfg.nodePositions;
  if (manualPos) {
    const clamp01 = (v: number): number => Math.max(0, Math.min(1, v));
    for (const nd of graph.nodes) {
      const m = manualPos[nd.id];
      if (m) posOf.set(nd.id, { x: plotX + clamp01(m.x) * plotW, y: plotY + clamp01(m.y) * plotH });
    }
  }

  const labelMinDeg = cfg.labelMinDegree ?? 0;
  const showLabels = cfg.showLabels ?? true;
  const nodeColorOverrides = cfg.nodeColors;
  const nodeLabelOverrides = cfg.nodeLabels;
  const nodes: NetworkNode[] = graph.nodes.map((nd) => {
    const p = posOf.get(nd.id)!;
    const labelText = nodeLabelOverrides?.[nd.id] ?? nd.label;
    const shown = showLabels && nd.degree >= labelMinDeg ? labelText : "";
    const rad = drawnRadius(nd);
    // Node positions are clamped to the plot rect, but their labels hang off to the right and
    // are not — so a node near the right edge would push its name off the canvas. Flip the
    // label to the node's left when it would not fit, measured at the label size it is drawn
    // at (not the tick font).
    const overflowsRight = shown !== "" && p.x + rad + 3 + measure(shown, labelSize) > width - 2;
    // Fill precedence: a hand-recoloured node · its group's palette hue (a groupless node
    // goes the same no-data grey the ramp uses) · the value ramp / flat colour.
    const fill = nodeColorOverrides?.[nd.id]
      ?? (hasGroups
        ? (nd.group !== undefined ? groupColorOf(nd.group) : cfg.nodeColor ?? "#cfd3d8")
        : colorOf(nd.value));
    // Outline: an explicit colour (per-node ⊕ shared) always wins; otherwise two-tone
    // derives the outline as a darker shade of the node's own fill — the same convention
    // as two-tone markers/bars (outline darker than the inner fill). Not a split disc.
    // Two-tone is the house default (matches the two-tone data-point markers); an explicit
    // per-node or plot-level `false` still turns it off.
    /**
     * Why this precedence: it keeps the two-tone control effective.
     *
     * A chain of `nodeStrokes[id] ?? nodeStroke ?? (twoTone ? … )` — with the two-tone branch
     * last — would never reach two-tone: the network house default always sets
     * `nodeStroke: "var(--bg)"` (the page-colour halo), so "Two-tone fill" would change nothing,
     * on or off. `kind-house-defaults.efficacy.test.tsx` guards this.
     *
     * An explicit choice beats the shared halo, and only an explicit one:
     *   per-node colour   most specific, always wins
     *   two-tone on       derive a darker shade of this node's own fill
     *   two-tone off      the shared halo (or no ring at all)
     *   untouched         the shared halo, else two-tone — so the house look is unchanged and
     *                     no saved figure moves.
     */
    const twoToneSet = cfg.nodeTwoTones?.[nd.id] ?? cfg.nodeTwoTone;
    const perNode = cfg.nodeStrokes?.[nd.id];
    const stroke =
      perNode !== undefined ? perNode
      : twoToneSet === true ? twoToneContour(fill, undefined)
      : twoToneSet === false ? cfg.nodeStroke
      : cfg.nodeStroke ?? twoToneContour(fill, undefined);
    const strokeWidth = cfg.nodeStrokeWidths?.[nd.id] ?? cfg.nodeStrokeWidth;
    return {
      id: nd.id,
      cx: p.x,
      cy: p.y,
      r: rad,
      color: fill,
      label: shown,
      ...(overflowsRight ? { labelAnchor: "end" as const } : {}),
      degree: nd.degree,
      value: nd.value,
      ...(stroke !== undefined ? { stroke } : {}),
      ...(strokeWidth !== undefined ? { strokeWidth } : {}),
    };
  });
  const maxW = graph.edges.reduce((m, e) => Math.max(m, e.weight), 0) || 1;
  const edgeW = Math.max(0.25, cfg.edgeWidth ?? 1);
  const edgeColor = cfg.edgeColor ?? "#5b6470";
  const edgeOpacity = cfg.edgeOpacity ?? 0.5;
  const curved = cfg.curved ?? false;
  const edges: NetworkEdge[] = graph.edges.map((e) => {
    const key = networkEdgeKey(e.source, e.target);
    const a = posOf.get(e.source)!;
    const b = posOf.get(e.target)!;
    // A gentle perpendicular bow for the curved mode (10% of the span).
    let cx: number | undefined;
    let cy: number | undefined;
    if (curved) {
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const len = Math.hypot(dx, dy) || 1;
      cx = mx - (dy / len) * len * 0.12;
      cy = my + (dx / len) * len * 0.12;
    }
    return {
      id: key,
      sourceId: e.source,
      targetId: e.target,
      x1: a.x,
      y1: a.y,
      x2: b.x,
      y2: b.y,
      ...(cx !== undefined ? { cx, cy } : {}),
      // A per-link override (click one link → set its thickness/colour/opacity) wins over
      // the shared edge style. The width override is the drawn width — a link tuned by hand
      // opts out of weight scaling, which is what "make this link thicker" means.
      width: cfg.edgeWidths?.[key] ?? edgeW * (0.6 + 0.9 * (e.weight / maxW)),
      // A hand-recoloured link wins; then the weight's sign when sign colouring is on
      // (a weightless link has no sign and keeps the shared colour); then the shared colour.
      color: cfg.edgeColors?.[key]
        ?? (signOn && e.sign > 0 ? posColor : signOn && e.sign < 0 ? negColor : edgeColor),
      opacity: cfg.edgeOpacities?.[key] ?? edgeOpacity,
    };
  });

  // Note: after the edges exist: a node label has to dodge the links, and they are the obstacle
  // it would collide with most often. (Run before the edges exist, the pass could not see them.)
  // No name is dropped while a smaller size fits (for example after Match Fonts enlarges the names). The placer blanks a name only when no spot around its node is clear; the names are then tried smaller, never
  // below 8 px, until every one is placed. Nodes and links stay where they are - the graph keeps its size.
  const names = nodes.map((nd) => nd.label);
  const place = (px: number): number => {
    nodes.forEach((nd, i) => { nd.label = names[i]!; });
    deconflictNodeLabels(
      nodes,
      edges,
      // An outside-right legend is drawn at the plot's edge, over the room reserved for right-hand names, so its box is an
      // obstacle too, or a name would run under a legend row. Only the box - a name below its rows still fits.
      insideLegendBox(leg.layout, leg.entries, plotX, plotY, plotW, plotH, fonts.legend.size, measure) ?? outsideRightLegendBox(leg.layout, leg.entries, plotX + plotW, plotY, fonts.legend.size),
      px,
      measure,
      { w: width, h: height, top: plotY },
      showValueLegend
        ? (() => {
            // Right edge 6 px left of the plot, 8 px wide, min/max labels right-aligned to it above and below.
            const x2 = plotX - 6 + (plot.colorbarOffset?.dx ?? 0);
            const barH = Math.max(24, Math.min(120, plotH - 2 * (px + 6)));
            const y1 = plotY + (plot.colorbarOffset?.dy ?? 0);
            return [{ x1: x2 - Math.max(8, measure(legendMinLabel, px), measure(legendMaxLabel, px)), x2, y1, y2: y1 + px + 4 + barH + px + 2 }];
          })()
        : [],
    );
    return nodes.filter((nd, i) => names[i] && !nd.label).length;
  };
  let drawnLabelSize = labelSize;
  if (place(labelSize) > 0) {
    const floor = Math.min(labelSize, options.minTextPx ?? 8);
    for (let px = labelSize * 0.92; px >= floor - 1e-6; px *= 0.92) {
      drawnLabelSize = Math.round(Math.max(px, floor) * 10) / 10;
      if (place(drawnLabelSize) === 0) break;
      if (px * 0.92 < floor && drawnLabelSize > floor) { drawnLabelSize = floor; place(floor); break; }
    }
    // Quiet, like the sunburst / treemap fits: every name is still drawn (the gallery card sets its own name size, so a
    // "not the size asked for" note could not tell the card's design from the user's choice).
  }

  const network: NetworkScene = {
    nodes,
    edges,
    labelSize: drawnLabelSize,
    ...(showValueLegend
      ? {
          valueLegend: {
            min: vMin,
            max: vMax,
            ramp: Array.from({ length: 12 }, (_v, i) => mix(lowColor, highColor, i / 11)),
            minLabel: legendMinLabel,
            maxLabel: legendMaxLabel,
          },
        }
      : {}),
  };

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: refuseAnnotations(plot, "a network diagram", warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "network",
    fonts,
    network,
    ...(plot.colorbarOffset ? { colorbarOffset: plot.colorbarOffset } : {}),
    warnings,
  };
}

/** Round up to a "nice" axis maximum (1/2/5 × 10ⁿ). */
function niceCeil(v: number): number {
  if (!(v > 0)) return 1;
  const p = Math.pow(10, Math.floor(Math.log10(v)));
  const f = v / p;
  const nf = f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10;
  return nf * p;
}

/**
 * Radar / spider chart (kind "radar"): one axis (spoke) per row radiating from
 * the centre, one closed polygon per Y dataset with a vertex on each spoke at the
 * dataset's value for that row. Concentric rings give the radial scale.
 */
function buildRadarScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  let fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const xCol = xColumn(table);
  const datasets = visibleDatasets(table, plot);
  const rows = table.rows;
  const n = rows.length;

  // Per (dataset, row) value: the summary mean if present, else the replicate mean.
  const valAt = (ds: Dataset, row: Row): number => {
    if (isSummaryDataset(ds)) return toNumber(row.cells[ds.replicates[0]!]);
    const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
  };
  let maxV = 0;
  for (const ds of datasets) for (const row of rows) {
    const v = valAt(ds, row);
    if (Number.isFinite(v)) maxV = Math.max(maxV, v);
  }
  const niceMax = niceCeil(maxV);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // A radar series is selectable — its polygon emits `{kind:"series", columnId: ds.id}` —
  // so the legend row points at the same id rather than being matched by name (this chart
  // has no `scene.series` at all, so name-matching could never find it).
  const legendEntries: LegendEntry[] = datasets.map((ds, i) => ({ label: ds.name, color: plot.seriesStyles?.[ds.id]?.color ?? seriesColor(i, palette), select: { as: "series" as const, id: ds.id } }));
  const tickPx0 = fonts.tick.size;
  const legendPx0 = fonts.legend.size;
  const spokeLabelPx = plot.radar?.labelFont?.size ?? tickPx0;
  const spokeNames = rows.map((row) => (xCol ? String(row.cells[xCol.id] ?? "") : ""));
  const plotX = DEFAULTS.marginRight + pad.l;
  const plotY = DEFAULTS.marginTop + topPad;
  // Note: `pad.b` and `pad.l` (above) must be applied here: top and right are folded into `topPad`
  // and `marginRight`, but the other two sides are not. An axis-less kind has no axis margin to
  // absorb them, so all four have to be applied by hand.
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - DEFAULTS.marginRight - pad.b);
  const px10 = (px: number): number => Math.round(px * 10) / 10;
  /**
   * The web with its names and legend at text scale `k` - the one layout the fit below tests and the drawing uses.
   * Always round, stretched or not: a squashed radar reads its equal spokes as different lengths.
   * Spoke-label room is measured at the size the names are drawn (their own Label font when set), never a flat
   * constant (a fixed allowance clips longer names). A side name sits at radius + 12,
   * start/end-anchored, so the horizontal reserve is its full width; top/bottom names are middle-anchored and need
   * only the line height (shifted up to ~0.7em outward, hence 1.5×font).
   * Two placements, the larger web wins: beside the legend (centred left of its column), or - in a box too narrow
   * for that - below it, across the full width. The legend itself never moves; the web only uses the empty space
   * under it.
   */
  const webAt = (k: number) => {
    const legendPx = px10(legendPx0 * k);
    const labelPx = px10(spokeLabelPx * k);
    const lg = resolveLegend(plot, legendEntries, measure, legendPx, width);
    const plotW = Math.max(1, width - plotX - (DEFAULTS.marginRight + lg.outsideRightWidth + pad.r));
    const hReserve = 12 + Math.max(0, ...spokeNames.map((t) => measure(t, labelPx))) + 4;
    const vReserve = 12 + labelPx * 1.5 + 4;
    const beside = Math.min(plotW / 2 - hReserve, plotH / 2 - vReserve);
    const box = outsideRightLegendBox(lg.layout, lg.entries, plotX + plotW, plotY, legendPx);
    const fullW = Math.max(1, width - plotX - DEFAULTS.marginRight - pad.r);
    const top = box ? Math.min(plotY + plotH, box.y2 + 4) : plotY;
    const under = box ? Math.min(fullW / 2 - hReserve, (plotY + plotH - top) / 2 - vReserve) : -Infinity;
    const below = under > beside + 0.5;
    return {
      lg,
      plotW,
      r: Math.max(10, below ? under : beside),
      cx: below ? plotX + fullW / 2 : plotX + plotW / 2,
      cy: below ? (top + plotY + plotH) / 2 : plotY + plotH / 2,
      room: Math.min(fullW, plotH) / 2,
    };
  };
  // The graph fills its box. In a box
  // much smaller than the graph's own size - a figure card with Keep proportions off - names and legend at full size
  // would take nearly all the width and the web would fall to its 10 px minimum, with names cut. So the
  // names and the legend shrink just enough for the web's radius to reach FILL of half the box's shorter side,
  // never below 8 px, saying so when that size was set on the graph. With room to spare (its own size, the gallery) nothing changes.
  const FILL = 0.6;
  const fills = (k: number): boolean => { const w = webAt(k); return w.r >= FILL * w.room; };
  let textFit = 1;
  if (!fills(1)) {
    let lo = Math.min(1, (options.minTextPx ?? 8) / Math.max(1, Math.min(spokeLabelPx, legendPx0)));
    let hi = 1;
    if (fills(lo)) {
      for (let i = 0; i < 16; i++) { const mid = (lo + hi) / 2; if (fills(mid)) lo = mid; else hi = mid; }
    }
    textFit = lo;
  }
  const fitFont = (rf: ResolvedFont): ResolvedFont => (textFit < 1 ? { ...rf, size: px10(rf.size * textFit) } : rf);
  if (textFit < 1) {
    fonts = { ...fonts, tick: fitFont(fonts.tick), legend: fitFont(fonts.legend) };
    if ((plot.radar?.labelFont?.size ?? plot.fonts?.tick?.size) !== undefined) warnings.push(`Radar names are drawn at ${px10(spokeLabelPx * textFit)}px, not the ${spokeLabelPx}px asked for: the web would be too small in this box. A larger figure will honour it.`);
  }
  const web = webAt(textFit);
  const leg = web.lg;
  const plotW = web.plotW;
  const cx = web.cx;
  const cy = web.cy;
  const rx = web.r;
  const ry = web.r;

  const angleAt = (i: number): number => -Math.PI / 2 + (i * 2 * Math.PI) / Math.max(1, n);
  const spokes: RadarSpoke[] = rows.map((row, i) => {
    const a = angleAt(i);
    const cosA = Math.cos(a);
    const sinA = Math.sin(a);
    const anchor: "start" | "middle" | "end" = Math.abs(cosA) < 0.3 ? "middle" : cosA > 0 ? "start" : "end";
    const loff = plot.pointStyles?.[`${row.id}:${row.id}`];
    return {
      x: cx + cosA * rx,
      y: cy + sinA * ry,
      label: xCol ? String(row.cells[xCol.id] ?? i + 1) : String(i + 1),
      labelX: cx + cosA * (rx + 12),
      labelY: cy + sinA * (ry + 12) + (sinA > 0.3 ? fonts.tick.size * 0.7 : sinA < -0.3 ? 0 : fonts.tick.size * 0.34),
      labelAnchor: anchor,
      rowId: row.id,
      ...(loff?.valueDx != null ? { labelDx: loff.valueDx } : {}),
      ...(loff?.valueDy != null ? { labelDy: loff.valueDy } : {}),
    };
  });
  const rstyle = plot.radar ?? {};
  const ringCount = Math.max(1, Math.round(rstyle.ringCount ?? 4));
  const scaleMax = rstyle.scaleMax && rstyle.scaleMax > 0 ? rstyle.scaleMax : niceMax;
  // Ring "radius" is scaled by the renderer as ring.radius / radar.r against each spoke. The web
  // is always round (rx === ry), so the ratio is the ring's fraction and the ring value-label
  // y-pos (cy − radius) lands on the web's top.
  // Ring value labels all sit at the same x, stacked up the vertical axis one per ring, so they
  // collide with each other once a line of text is taller than the ring spacing — and the
  // outermost one lands where the topmost spoke's category label goes. Thin them: keep every
  // k-th, and never label the outer ring, which is the one that meets the spoke label. The
  // values are a numeric scale, so a dropped one is still read off its neighbours.
  const ringGap = ry / ringCount;
  const ringStep = Math.max(1, Math.ceil((TEXT_BAND * fonts.tick.size + 2) / Math.max(1, ringGap)));
  const rings = Array.from({ length: ringCount }, (_, k) => ({
    radius: (ry * (k + 1)) / ringCount,
    value: (scaleMax * (k + 1)) / ringCount,
    labelled: k < ringCount - 1 && (ringCount - 1 - k) % ringStep === 0,
  }));
  const polygons = datasets.map((ds, di) => {
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(di, palette);
    const fill = style?.fillColor ?? color;
    const fillOpacity = style?.fillOpacity ?? 0.18;
    // Vertex dots honour the plot's marker default: two-tone → a lighter fill + darker edge,
    // inherited like PCA (a radar dataset id is not where a preset writes `symbolFill`).
    const sym = resolveSymbol(effectiveMarkerStyle(plot, style), color);
    const points = rows.map((row, i) => {
      const a = angleAt(i);
      const v = valAt(ds, row);
      const frac = Number.isFinite(v) ? Math.max(0, Math.min(1, v / scaleMax)) : 0;
      return { x: cx + Math.cos(a) * rx * frac, y: cy + Math.sin(a) * ry * frac };
    });
    return {
      id: ds.id, name: ds.name, color, fill, fillOpacity, lineWidth: style?.lineWidth ?? 2, points,
      vertexFill: sym.symbolFillColor ?? color,
      vertexOutline: sym.symbolFillColor ? sym.symbolOutline : undefined,
    };
  });
  if (n < 3) warnings.push("A radar chart needs at least 3 rows (spokes).");

  // Spread interval per (series, spoke) — radar's error bars. Reuses the same per-row error
  // spine as bars/points: a summary dataset goes through `summaryPointForRow`; raw replicates
  // through `errorPoint(summarize(...))`. Nothing is drawn on single-value data (no spread).
  const errType = rstyle.errorType && rstyle.errorType !== "none" ? rstyle.errorType : null;
  const radialPt = (a: number, frac: number): { x: number; y: number } => ({
    x: cx + Math.cos(a) * rx * Math.max(0, Math.min(1, frac)),
    y: cy + Math.sin(a) * ry * Math.max(0, Math.min(1, frac)),
  });
  const errorBars: NonNullable<RadarScene["errorBars"]> = [];
  const errorBands: NonNullable<RadarScene["errorBands"]> = [];
  if (errType) {
    for (const [di, ds] of datasets.entries()) {
      const style = plot.seriesStyles?.[ds.id];
      const color = style?.color ?? seriesColor(di, palette);
      const segments: { x1: number; y1: number; x2: number; y2: number }[] = [];
      const lo: { x: number; y: number }[] = [];
      const hi: { x: number; y: number }[] = [];
      let any = false;
      rows.forEach((row, i) => {
        const a = angleAt(i);
        const ep = isSummaryDataset(ds)
          ? summaryPointForRow(ds, row, errType)
          : (() => {
              const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
              return vals.length >= 2 ? errorPoint(summarize(vals), errType, ERROR_CONF) : { center: vals[0] ?? NaN, low: NaN, high: NaN, hasError: false, n: NaN };
            })();
        const loFrac = Number.isFinite(ep.low) ? ep.low / scaleMax : NaN;
        const hiFrac = Number.isFinite(ep.high) ? ep.high / scaleMax : NaN;
        const cFrac = Number.isFinite(ep.center) ? ep.center / scaleMax : 0;
        lo.push(radialPt(a, Number.isFinite(loFrac) ? loFrac : cFrac));
        hi.push(radialPt(a, Number.isFinite(hiFrac) ? hiFrac : cFrac));
        if (ep.hasError && Number.isFinite(loFrac) && Number.isFinite(hiFrac) && hiFrac > loFrac) {
          const p1 = radialPt(a, loFrac);
          const p2 = radialPt(a, hiFrac);
          segments.push({ x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y });
          any = true;
        }
      });
      // "As band" shows the spread as a shaded ring instead of per-vertex whiskers, not both.
      if (any) {
        if (rstyle.errorBand) errorBands.push({ id: ds.id, fill: style?.fillColor ?? color, fillOpacity: 0.22, lo, hi });
        else errorBars.push({ id: ds.id, color, width: Math.max(1, (style?.lineWidth ?? 2) - 0.5), segments });
      }
    }
  }

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "radar",
    fonts,
    radar: {
      cx, cy, r: ry, spokes, rings, polygons,
      spokeColor: rstyle.spokeColor, spokeWidth: rstyle.spokeWidth ?? 1,
      gridColor: rstyle.gridColor, gridWidth: rstyle.gridWidth ?? 1,
      gridDash: dashArray(rstyle.gridDash ?? "solid", rstyle.gridWidth ?? 1),
      spokeDash: dashArray(rstyle.spokeDash ?? "solid", rstyle.spokeWidth ?? 1),
      // Tick marks sit on the vertical axis, where the ring value labels already are —
      // that is the only spoke a reader reads numbers off, so ticking all of them would be
      // noise. Geometry here, not in the renderer: it already knows where each ring is.
      ...(rstyle.showTicks
        ? {
            ticks: rings
              .filter((rg) => rg.labelled !== false)
              .map((rg) => ({ x1: cx - Math.max(1, rstyle.tickLen ?? 5), y1: cy - rg.radius, x2: cx, y2: cy - rg.radius })),
            ...(rstyle.tickColor ? { tickColor: rstyle.tickColor } : {}),
          }
        : {}),
      ...(rstyle.labelFont ? { labelFont: fitFont(resolveFont(rstyle.labelFont, spokeLabelPx)) } : {}),
      ...(rstyle.ringFont || rstyle.labelFont
        ? { ringFont: fitFont(resolveFont(rstyle.ringFont ?? rstyle.labelFont!, tickPx0)) }
        : {}),
      showDots: rstyle.showDots !== false,
      // The radar panel's own "Dot size" still wins. Under it, the plot's marker size —
      // so a radar adopts a house/preset/whole-graph marker size like every other kind
      // instead of sitting alone on a private 2.5. Its vertex dot is a data point; there
      // is no reason it should be the one that ignores what a data point is set to.
      dotSize: rstyle.dotSize ?? plotMarkerDefault(plot).symbolSize ?? 2.5,
      ...(errorBars.length ? { errorBars } : {}),
      ...(errorBands.length ? { errorBands } : {}),
    },
    warnings,
  };
}

/**
 * Isometric 3-D scatter (kind "scatter3d"): the first three columns
 * are X, Y, Z; each row is a point projected with a classic 2:1 isometric camera.
 * Draws the three axis edges (labelled by column name), a floor grid on the X–Z
 * plane, and the points painter-sorted back-to-front. One series colour; a point can carry
 * its own colour override.
 */
function scatter3DSceneAt(table: DataTable, plot: Plot, options: BuildPlotSceneOptions, fit?: { k: number; dx: number; dy: number }): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cols = table.columns;
  const xCol = cols[0];
  const yCol = cols[1];
  const zCol = cols[2];
  if (!xCol || !yCol) warnings.push("A 3-D scatter needs at least an X and a Y column.");
  if (!zCol) warnings.push("Add a third column for the Z axis (only X·Y present).");

  const raw = table.rows.map((r) => ({
    rowId: r.id,
    x: xCol ? toNumber(r.cells[xCol.id]) : NaN,
    y: yCol ? toNumber(r.cells[yCol.id]) : NaN,
    z: zCol ? toNumber(r.cells[zCol.id]) : 0,
  })).filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y) && Number.isFinite(p.z));
  // A silent empty cube is a defect: on a label-led sheet (column / contingency) column 0 is text,
  // so every row is dropped above; the warning says why.
  if (xCol && yCol && table.rows.length > 0 && raw.length === 0) {
    warnings.push("No finite (X, Y, Z) points to plot — the first three columns must all be numeric.");
  }
  const ext = (sel: (p: typeof raw[number]) => number): [number, number] => {
    const vs = raw.map(sel);
    return vs.length ? [Math.min(...vs), Math.max(...vs)] : [0, 1];
  };
  const ex = ext((p) => p.x), ey = ext((p) => p.y), ez = ext((p) => p.z);

  /**
   * Each axis is a real scale (the Axis tab and its settings work on it):
   * manual min/max clamp the data→cube mapping, `scale: "log"` maps in log10 space,
   * and `buildScale` supplies the tick ladder — the same machinery every 2-D axis uses, so the
   * numbers and the "nice" intervals match the rest of the program.
   */
  const specs = [plot.xAxis ?? {}, plot.yAxis ?? {}, plot.zAxis ?? {}] as const;
  const axisScale = (spec: AxisSpec, data: [number, number], name: string) => {
    let type: ScaleType = spec.scale ?? "linear";
    const base = type === "log10" ? 10 : type === "log2" ? 2 : type === "ln" ? Math.E : null;
    if (type === "probit") {
      // Probit on a projected cube edge has no meaningful reading. Refuse with a warning, draw linear.
      warnings.push(`A probit scale cannot be drawn on a 3-D axis — the ${name} axis is drawn linear.`);
      type = "linear";
    } else if (base !== null && !(data[0] > 0 || (spec.min ?? 0) > 0)) {
      // A log axis needs a positive domain. Refuse with a warning and draw linear — a silently
      // linear "log" axis would misreport the numbers it shows.
      warnings.push(`The ${name} axis is set to log but its data reaches ${Math.min(data[0], 0)} — drawn linear. Set a positive Min to use log.`);
      type = "linear";
    }
    const b0 = type === "linear" ? null : (type === "log10" ? 10 : type === "log2" ? 2 : Math.E);
    const manual = spec.min != null || spec.max != null;
    const dom: [number, number] = [spec.min ?? data[0], spec.max ?? data[1]];
    // majorStep is the user's tick interval; `breaks` are deliberately not passed — an axis
    // break has no meaningful drawing on a projected cube edge (refused in the panel, with a message).
    const b = buildScale(type, dom, [0, 1], 6, manual, tickFormat(spec), { majorStep: spec.majorStep, minorCount: undefined, breaks: undefined });
    const toS = (v: number): number => (b0 === null ? v : Math.log(Math.max(v, Number.MIN_VALUE)) / Math.log(b0));
    const [d0, d1] = b.domain;
    const s0 = toS(d0), s1 = toS(d1);
    const span = s1 - s0 || 1;
    return {
      type,
      domain: b.domain,
      // ticks at [0,1] range → pos is the fraction along the edge
      ticks: b.ticks.filter((t) => !t.minor && t.label),
      norm: (v: number): number => (toS(v) - s0) / span,
    };
  };
  const scaleX = axisScale(specs[0], ex, "X");
  const scaleY = axisScale(specs[1], ey, "Y");
  const scaleZ = axisScale(specs[2], ez, "Z");

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // Note: only `pad.t` reaches this rect via `topPad`; right, bottom and left are applied here,
  // or three of the four margin boxes would do nothing.
  const plotX = DEFAULTS.marginRight + pad.l;
  const plotY = DEFAULTS.marginTop + topPad;
  const plotW = Math.max(1, width - plotX - DEFAULTS.marginRight - pad.r);
  const plotH = Math.max(1, height - plotY - DEFAULTS.marginRight - pad.b);
  // Orbit camera: the user drags to rotate (azimuth/elevation) and scrolls to zoom.
  // The default is a three-quarter view from slightly above; angles + zoom persist on plot.scatter3d.
  const cam = plot.scatter3d ?? {};
  const az = cam.azimuth ?? DEFAULT_CAM3D.az;
  const el = Math.max(-1.45, Math.min(1.45, cam.elevation ?? DEFAULT_CAM3D.el));
  const zoom3 = Math.max(0.3, Math.min(4, cam.zoom ?? 1));
  const cazi = Math.cos(az), sazi = Math.sin(az);
  const cel = Math.cos(el), sel = Math.sin(el);
  // Cube edge. The name-room fit below is computed at zoom 1 and the camera zoom multiplies
  // in afterwards — fitting the zoomed size instead would cancel the wheel (k ∝ 1/L, so
  // L·k would stay constant; the orbit-camera test guards this). Zooming past the fit may push the
  // axis names off-canvas, exactly like a 2-D zoom pushes data off — the user asked.
  let L = Math.min(plotW, plotH) * 0.58;
  // Rotate a centred unit-cube coord about Y (azimuth) then X (elevation); returns
  // screen-space [x, y] (pre-centre) + camera depth (larger = nearer the viewer).
  const rot = (nx: number, ny: number, nz: number): [number, number, number] => {
    const x = nx - 0.5, y = ny - 0.5, z = nz - 0.5;
    const x1 = x * cazi + z * sazi;
    const z1 = -x * sazi + z * cazi;
    const y2 = y * cel - z1 * sel;
    const z2 = y * sel + z1 * cel;
    return [x1 * L, -y2 * L, z2];
  };
  // Centre the projected cube in the plot rect (recomputed per camera angle).
  let corners = [0, 1].flatMap((a) => [0, 1].flatMap((b) => [0, 1].map((c) => rot(a, b, c))));
  /**
   * The cube makes room for its axis names — the same rule as the significance brackets
   * ("a graph makes its own room"). The names hang a fixed pixel gap beyond the
   * projected corners (that is what keeps them clear of the type at any size — the guard in
   * scatter3d-labels.test.tsx), so a large title font would push them off the canvas, and
   * clamping them back on would break the clearance. Shrink the cube by exactly what the names need:
   * cubeSpan · k + nameOverhang ≤ plot span, solved for k in one pass (the overhang is in px,
   * so it does not scale with k — no iteration needed).
   */
  {
    const titlePx = (sp: AxisSpec): number => sp.titleFont?.size ?? fonts.axisTitle.size;
    // The name sits [tick ladder] + [Title↔labels gap] beyond the edge. Both the 2-D Spacing
    // fields are honoured: `titleGap` is the Title↔labels gap (blank = the auto value), and a
    // wider `tickLabelGap` (Labels↔axis) grows the ladder the name must clear. The cube reserves
    // exactly this so a pushed-out name never clips; blank/blank gives the default reservation.
    const nameGapOf = (sp: AxisSpec, tf: ResolvedFont): number => {
      const autoLG = tf.size * 0.55 + 3;
      const extraLG = Math.max(0, (sp.tickLabelGap ?? autoLG) - autoLG);
      return (sp.hideTicks ? 0 : (sp.tickLen ?? 4) + tf.size * 1.25) + (sp.titleGap ?? (fonts.axisTitle.size * 0.9 + 8)) + extraLG;
    };
    const tickFontsPre = [
      fonts.xTick,
      fonts.yTick,
      resolveFont(mergeFontSpec(plot.fonts?.tick, plot.zAxis?.tickFont), DEFAULTS.tickFont),
    ];
    const o0 = rot(0, 0, 0);
    let over = 0;
    axisDefDirs: for (let ai = 0; ai < 3; ai++) {
      const sp = specs[ai]!;
      if (sp.hidden) continue axisDefDirs;
      const end = rot(ai === 0 ? 1 : 0, ai === 1 ? 1 : 0, ai === 2 ? 1 : 0);
      const vx = end[0] - o0[0], vy = end[1] - o0[1];
      const l = Math.hypot(vx, vy) || 1;
      const label = ai === 0 ? (plot.xAxis?.title || xCol?.name || "X") : ai === 1 ? (plot.yAxis?.title || yCol?.name || "Y") : (plot.zAxis?.title || cam.zTitle || zCol?.name || "Z");
      const g = nameGapOf(sp, tickFontsPre[ai]!);
      const halfW = measure(label, titlePx(sp)) / 2;
      const halfH = titlePx(sp) * 0.8;
      over = Math.max(over, g + Math.abs(vx / l) * halfW + Math.abs(vy / l) * halfH);
    }
    const xs0 = corners.map((p) => p[0]), ys0 = corners.map((p) => p[1]);
    const cw = Math.max(...xs0) - Math.min(...xs0), ch = Math.max(...ys0) - Math.min(...ys0);
    const k = Math.max(0.3, Math.min(1, (plotW - 2 * over) / (cw || 1), (plotH - 2 * over) / (ch || 1)));
    // `fit` (from buildScatter3DScene) replaces this one-pass, shrink-only estimate with a measured one.
    L *= fit ? fit.k : k;
    L *= zoom3;
    corners = [0, 1].flatMap((a) => [0, 1].flatMap((b) => [0, 1].map((c) => rot(a, b, c))));
  }
  const xs = corners.map((p) => p[0]), ys = corners.map((p) => p[1]);
  const bx = [Math.min(...xs), Math.max(...xs)] as const;
  const by = [Math.min(...ys), Math.max(...ys)] as const;
  // Normally the projected cube is centred in the plot rect (isotropic, whitespace on the wide
  // side) - with or without `stretch`: a skewed cube would leave its axis names no room.
  const bw = bx[1] - bx[0], bh = by[1] - by[0];
  const sx = 1; // never skewed: `stretch` does not fill the box anisotropically (that would cut off the axis names)
  const sy = 1;
  const offx = plotX + (plotW - bw) / 2 + (fit?.dx ?? 0);
  const offy = plotY + (plotH - bh) / 2 + (fit?.dy ?? 0);
  const proj = (nx: number, ny: number, nz: number): [number, number, number] => {
    const [px, py, d] = rot(nx, ny, nz);
    return [offx + (px - bx[0]) * sx, offy + (py - by[0]) * sy, d];
  };

  // Axis titles: X/Y reuse the standard axis-spec titles (editable in the 3-D
  // section); Z has no AxisSpec so it uses the scatter3d.zTitle override. Each falls
  // back to its source column name.
  const axisDef: [number, number, number, string][] = [
    [1, 0, 0, plot.xAxis?.title || xCol?.name || "X"],
    [0, 1, 0, plot.yAxis?.title || yCol?.name || "Y"],
    [0, 0, 1, plot.zAxis?.title || cam.zTitle || zCol?.name || "Z"],
  ];
  const [o0x, o0y] = proj(0, 0, 0);
  /**
   * The label sits a fixed number of pixels beyond the axis end, not 8% further along it.
   * `proj(ax * 1.08, …)` is a fraction of the cube, so the gap it leaves shrinks with zoom and
   * knows nothing about the type size — at a 22px axis-title font it does not clear and
   * the labels clash with their axes. A pixel gap scaled from the font keeps them clear.
   *
   * The direction is the axis' own screen-space vector from the origin, so each label pushes
   * straight outward whatever the camera is doing.
   */
  const labelGap = fonts.axisTitle.size * 0.9 + 8;
  // Outward = away from the cube's projected centre, recomputed per build — that is what makes
  // the tick marks and numbers survive an orbit: whichever way an edge swings, its scale stays
  // on the outside of the cube.
  const [ccx, ccy] = proj(0.5, 0.5, 0.5);
  const scales3 = [scaleX, scaleY, scaleZ];
  const tickFonts3 = [
    fonts.xTick,
    fonts.yTick,
    resolveFont(mergeFontSpec(plot.fonts?.tick, plot.zAxis?.tickFont), DEFAULTS.tickFont),
  ];
  const axes = axisDef.map(([ax, ay, az, label], ai) => {
    const spec = specs[ai]!;
    const [x2, y2] = proj(ax, ay, az);
    const vx = x2 - o0x, vy = y2 - o0y;
    const len = Math.hypot(vx, vy) || 1;
    // Tick numbers offset perpendicular to the projected edge, in one constant direction per axis
    // (pointing away from the cube centre) — so the ladder lines up parallel to its axis instead
    // of fanning radially from the centre, which would make the numbers look curved.
    const ex = vx / len, ey = vy / len;
    let perpx = -ey, perpy = ex;
    const midx = (o0x + x2) / 2, midy = (o0y + y2) / 2;
    if ((midx - ccx) * perpx + (midy - ccy) * perpy < 0) { perpx = -perpx; perpy = -perpy; }
    const tickFont = tickFonts3[ai]!;
    const sc = scales3[ai]!;
    /**
     * The name clears the ladder, not the other way round. A name hung a fixed `labelGap`
     * past the edge end would sit over the last tick numbers. Dropping the colliding numbers
     * instead would remove about half a small card's ladder (a measured-box test with an
     * estimated text width is greedy at 580px). The name is one text; the ladder is the
     * scale — the one that moves is the name.
     */
    // Spacing (mirrors the 2-D "Spacing" section): Labels↔axis = tickLabelGap (blank = auto),
    // Title↔labels = titleGap (blank = auto). Label side: "flip" mirrors the ticks/numbers to the
    // opposite side of the edge.
    const autoLGap = tickFont.size * 0.55 + 3;
    const effLGap = spec.tickLabelGap ?? autoLGap;
    const side = spec.labelSide === "flip" ? -1 : 1;
    const nameGap = (spec.hideTicks ? 0 : (spec.tickLen ?? 4) + tickFont.size * 1.25) + (spec.titleGap ?? labelGap) + Math.max(0, effLGap - autoLGap);
    const nameW = measure(label, spec.titleFont?.size ?? fonts.axisTitle.size);
    const nameH = spec.titleFont?.size ?? fonts.axisTitle.size;
    const nameX = x2 + (vx / len) * nameGap;
    const nameY = y2 + (vy / len) * nameGap;
    // Thin the ladder to what fits along the projected edge: an edge seen nearly end-on is only
    // a few px long, and every label on it would be a smear. Same convention as the 2-D
    // de-overlap: keep every nth, never draw text on text.
    const minGap = tickFont.size * 1.15;
    const widest = Math.max(0, ...sc.ticks.map((t) => measure(t.label ?? "", tickFont.size)));
    let lastKept: { x: number; y: number; w: number } | undefined;
    // Numbers are drawn centred beside the edge. The auto gap covers a two-digit number's half-width;
    // wider ones (a prefix, suffix or grouped thousands) push the whole ladder out by the widest one's
    // excess, or their ends would cross the edge. One offset per
    // axis, so the ladder stays a straight line.
    const halfOver = Math.max(0, widest / 2 - measure("00", tickFont.size) / 2) * Math.abs(perpx);
    const step = Math.max(1, Math.ceil((sc.ticks.length * minGap) / Math.max(len, 1)));
    const ticks = spec.hideTicks
      ? []
      : sc.ticks
          .filter((_, i) => i % step === 0)
          /**
           * Not at the shared corner, and not under the name. All three edges meet at the
           * origin, so each axis's first number would land on the other two's; and a number at
           * the far end would land under the axis name parked just beyond it. Both collisions
           * occur at the default size, not only with enlarged fonts. The ends of the
           * ladder carry the least information (the name and the neighbouring ticks say the
           * range), so the trims cost nothing a reader needs.
           */
          .filter((t) => t.pos > 0.07)
          .map((t) => {
            const f = t.pos; // range [0,1] → fraction along the edge
            const [px, py] = proj(ax * f, ay * f, az * f);
            const tl = spec.tickLen ?? 4;
            const lgap = tl + effLGap + halfOver; // Labels↔axis gap (honours the Spacing control)
            // Constant per-axis perpendicular (aligned ladder); `side` flips it to the other edge.
            const sideX = side * perpx, sideY = side * perpy;
            return {
              x: px, y: py,
              tx1: px, ty1: py, tx2: px + sideX * tl, ty2: py + sideY * tl,
              label: t.label ?? "",
              lx: px + sideX * lgap,
              ly: py + sideY * lgap + tickFont.size * 0.34 * (sideY > 0.3 ? 1 : sideY < -0.3 ? -0.2 : 0.5),
            };
          })
          /**
           * And never under the name. On a small card the ladder's last number can still
           * reach the pushed-out name (both hang off the same end of the edge). This is a true
           * box intersection with a 3px tolerance — a clearance window (keep if far in x or far
           * in y) would read every borderline estimate as a hit and remove half a 580px card's
           * ladder. Only a number the name genuinely covers is dropped,
           * and the name says what the end of the axis is anyway.
           */
          .filter((t) => {
            const overX = (measure(t.label, tickFont.size) + nameW) / 2 - Math.abs(t.lx - nameX);
            const overY = (tickFont.size + nameH) / 2 - Math.abs(t.ly - nameY);
            return !(overX > 3 && overY > 3);
          })
          /**
           * And never on each other. The thinning above spaces the ladder by line height, which is
           * enough for short numbers; a prefix / suffix / thousands mark makes a number wide, and on a
           * shallow edge the numbers would run together (e.g. "10 cm12 cm14 cm").
           * Walk the ladder and drop a number whose box meets the last one kept — the same true box test
           * as the name filter, so a ladder that did not collide keeps every number it had.
           */
          .filter((t) => {
            const w = measure(t.label, tickFont.size);
            if (lastKept && Math.abs(t.lx - lastKept.x) < (w + lastKept.w) / 2 && Math.abs(t.ly - lastKept.y) < tickFont.size * 0.95) return false;
            lastKept = { x: t.lx, y: t.ly, w };
            return true;
          });
    return {
      x1: o0x, y1: o0y, x2, y2, label,
      lx: nameX, ly: nameY,
      ticks,
      color: spec.lineColor,
      width: spec.lineWidth,
      titleSize: spec.titleFont?.size,
      tickFont,
      hidden: spec.hidden,
    };
  });
  // …and each label's own drag offset. X/Y keep theirs on their AxisSpec, Z on scatter3d.
  const zero = { dx: 0, dy: 0 };
  const labelOffsets = [plot.xAxis?.titleOffset ?? zero, plot.yAxis?.titleOffset ?? zero, cam.zTitleOffset ?? zero];
  // Floor grid on the X–Z plane (y=0), a few lines each way.
  const G = 4;
  const floor: { x1: number; y1: number; x2: number; y2: number }[] = [];
  // k starts at 1: the t=0 lines coincide exactly with the X and Z cube edges, and the
  // duplicate (drawn first, so it wins the hit test) would send an edge click to the floor's
  // controls instead of the axis.
  for (let k = 1; k <= G; k++) {
    const t = k / G;
    const a = proj(t, 0, 0), b = proj(t, 0, 1);
    const c = proj(0, 0, t), d = proj(1, 0, t);
    floor.push({ x1: a[0], y1: a[1], x2: b[0], y2: b[1] });
    floor.push({ x1: c[0], y1: c[1], x2: d[0], y2: d[1] });
  }
  const ystyle = plot.seriesStyles?.[yCol?.id ?? ""];
  const color = ystyle?.color ?? seriesColor(0, palette);
  const size = ystyle?.symbolSize ?? 4;
  // Resolve the point marker so the house style carries through: two-tone derives a
  // light fill + dark edge; open uses the chosen interior + outline; solid is flat.
  const sfill = ystyle?.symbolFill;
  const marker =
    sfill === "twotone"
      ? { fill: twoToneFill(color, ystyle?.twoToneTint), stroke: twoToneContour(color, ystyle?.twoToneShade), width: ystyle?.borderWidth ?? 1.5, opacity: ystyle?.symbolOpacity ?? 1 }
      : sfill === "open"
        ? { fill: ystyle?.symbolFillColor ?? "var(--bg)", stroke: ystyle?.symbolOutline ?? color, width: ystyle?.borderWidth ?? 1.5, opacity: ystyle?.symbolOpacity ?? 1 }
        : sfill === "clear"
          ? { fill: "none", stroke: ystyle?.symbolOutline ?? color, width: ystyle?.borderWidth ?? 1.5, opacity: ystyle?.symbolOpacity ?? 1 } // see-through (matches the 2-D 'clear' marker)
          : { fill: color, stroke: "var(--bg)", width: 0.75, opacity: ystyle?.symbolOpacity ?? 0.85 };
  const ax = axisLine(plot.xAxis);
  const axisColor = ax.lineColor ?? "var(--line-2)";
  const axisWidth = ax.lineWidth;
  const yId = yCol?.id;
  let clipped = 0;
  const projected = raw
    .filter((p) => {
      const inX = scaleX.norm(p.x), inY = scaleY.norm(p.y), inZ = scaleZ.norm(p.z);
      const inside = inX >= -1e-9 && inX <= 1 + 1e-9 && inY >= -1e-9 && inY <= 1 + 1e-9 && inZ >= -1e-9 && inZ <= 1 + 1e-9;
      if (!inside) clipped++;
      return inside;
    })
    .map((p) => {
      const nx = scaleX.norm(p.x), ny = scaleY.norm(p.y), nz = scaleZ.norm(p.z);
      const [sx, sy, depth] = proj(nx, ny, nz);
      // Per-point colour override ("format this point") — click a point, untick
      // "whole series", recolour just it. Only the fill is overridden (marker mode
      // otherwise follows the series), so open/two-tone 3-D markers stay intact.
      const override = yId ? plot.pointStyles?.[`${yId}:${p.rowId}`]?.color : undefined;
      return { x: sx, y: sy, color, r: size + 1, rowId: p.rowId, depth, value: { x: p.x, y: p.y, z: p.z }, ...(override ? { overrideFill: override } : {}) };
    });
  // Optional depth cue: fade points toward the back of the cloud (opacity only — never size)
  // so front/back reads on a no-perspective isometric view. `depth` is larger nearer the viewer.
  const depthShade = cam.depthShade === true && projected.length > 1;
  const depths = projected.map((q) => q.depth);
  const dmin = Math.min(...depths), dmax = Math.max(...depths), dspan = dmax - dmin || 1;
  const points = projected
    .sort((a, b) => a.depth - b.depth) // far (smaller camera depth) drawn first
    .map(({ depth, ...rest }) => (depthShade ? { ...rest, alpha: 0.4 + 0.6 * ((depth - dmin) / dspan) } : rest));

  /**
   * A number never sits on a data point. The ladders are placed before the points exist and know
   * nothing of them, so a point near an edge could draw over a tick number. Clearance is
   * a fixed gap measured from each point's edge, so it holds for a small point or a big one.
   *
   * The whole ladder of an edge steps outward (along its tick marks, one offset for every number, so it
   * stays a straight line) until no number touches a point. Only a number that still cannot clear at
   * the furthest step is dropped. Dropping first would, on a 580×380 figure, remove every number the
   * cube has.
   */
  const POINT_CLEAR = 4;
  for (const a of axes) {
    if (!a.ticks?.length) continue;
    const fs = a.tickFont?.size ?? fonts.tick.size;
    const t0 = a.ticks[0]!;
    const tl = Math.hypot(t0.tx2 - t0.tx1, t0.ty2 - t0.ty1) || 1;
    const ox = (t0.tx2 - t0.tx1) / tl, oy = (t0.ty2 - t0.ty1) / tl; // outward, the tick marks' own way
    const clashes = (t: { lx: number; ly: number; label: string }, k: number): boolean => {
      const w = measure(t.label, fs);
      const cx0 = t.lx + ox * k, cy0 = t.ly + oy * k;
      const x1 = cx0 - w / 2, x2 = cx0 + w / 2, y1 = cy0 - fs * 0.75, y2 = cy0 + fs * 0.25;
      return points.some((q) => Math.hypot(q.x - Math.min(Math.max(q.x, x1), x2), q.y - Math.min(Math.max(q.y, y1), y2)) < q.r + POINT_CLEAR);
    };
    const count = (k: number): number => a.ticks!.filter((t) => clashes(t, k)).length;
    let best = 0;
    let bestN = count(0);
    for (let k = 2; bestN > 0 && k <= fs * 2.5; k += 2) {
      const n = count(k);
      if (n < bestN) {
        best = k;
        bestN = n;
      }
    }
    a.ticks = a.ticks
      .map((t) => (best ? { ...t, lx: t.lx + ox * best, ly: t.ly + oy * best } : t))
      .filter((t) => !clashes(t, 0));
  }

  // A manual range that hides data must say so — a silently emptier cube reads as lost data.
  if (clipped > 0) warnings.push(`${clipped} point${clipped === 1 ? "" : "s"} outside the manual axis range (not drawn). Clear Min/Max to see everything.`);

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: [],
    legendLayout: resolveLegend(plot, [], measure, fonts.legend.size, width).layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "scatter3d",
    fonts,
    scatter3d: { axes, labelOffsets, floor, gridColor: cam.gridColor, showGrid: cam.showGrid !== false, points, axisColor, axisWidth, marker, cam: { az, el, zoom: zoom3 }, seriesId: yId },
    warnings,
  };
}

/**
 * The 3-D scatter fills its plot area. The drawing grows inside the box it is
 * given — never shrink the box, never drop content. A cube started at 58% of the plot's shorter
 * side, with a name-room fit that can only shrink it, would leave a 3:2 figure with a small
 * centred cube and a blank third.
 *
 * The drawing's extent is the cube (it scales with the fit factor k) plus its tick numbers and axis
 * names (fixed pixels), so two builds at zoom 1 give each side as a straight line in k. Solve for the
 * largest k that fits the plot rect on both sides, centre the whole drawing — names included, not
 * just the cube — then build once more to check, backing off if the ladder thinning moved an edge.
 * The mouse-wheel zoom multiplies the fitted cube afterwards.
 */
function buildScatter3DScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  // The graph fills its box. The fit
  // below sizes the cube so the cube and its names fit - but the names stay at full size, so in a box much smaller than
  // the graph's own (a figure card with Keep proportions off) they would take the room and shrink the cube to 16-37% of it.
  // Then the axis names and numbers shrink just enough for the cube to span FILL of the box, never below 8 px, saying so
  // when that size was set on the graph. 0.6 sits under the cube at the default 580×380 (0.62) and its own size (0.75), which are unaffected.
  const first = fitScatter3DScene(table, plot, options);
  const FILL = 0.6;
  const cubeFill = (sc: PlotScene): number => {
    const d = sc.scatter3d;
    if (!d) return 1;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    const pt = (x: number, y: number): void => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); };
    for (const a of d.axes) if (!a.hidden) { pt(a.x1, a.y1); pt(a.x2, a.y2); }
    for (const fl of d.floor) { pt(fl.x1, fl.y1); pt(fl.x2, fl.y2); }
    return Number.isFinite(x0) ? Math.max((x1 - x0) / sc.width, (y1 - y0) / sc.height) : 1;
  };
  if (cubeFill(first) >= FILL) return first;
  const f0 = resolveFonts(plot);
  const px10 = (px: number): number => Math.round(px * 10) / 10;
  const axisAt = (sp: AxisSpec | undefined, k: number): AxisSpec | undefined =>
    sp && (sp.titleFont?.size !== undefined || sp.tickFont?.size !== undefined)
      ? {
          ...sp,
          ...(sp.titleFont?.size !== undefined ? { titleFont: { ...sp.titleFont, size: px10(sp.titleFont.size * k) } } : {}),
          ...(sp.tickFont?.size !== undefined ? { tickFont: { ...sp.tickFont, size: px10(sp.tickFont.size * k) } } : {}),
        }
      : sp;
  const plotAt = (k: number): Plot => {
    const xA = axisAt(plot.xAxis, k), yA = axisAt(plot.yAxis, k), zA = axisAt(plot.zAxis, k);
    return {
      ...plot,
      fonts: {
        ...(plot.fonts ?? {}),
        tick: { ...(plot.fonts?.tick ?? {}), size: px10(f0.tick.size * k) },
        axisTitle: { ...(plot.fonts?.axisTitle ?? {}), size: px10(f0.axisTitle.size * k) },
      },
      ...(xA ? { xAxis: xA } : {}),
      ...(yA ? { yAxis: yA } : {}),
      ...(zA ? { zAxis: zA } : {}),
    };
  };
  const sizes = [f0.tick.size, f0.axisTitle.size, ...[plot.xAxis, plot.yAxis, plot.zAxis].flatMap((sp) => [sp?.titleFont?.size, sp?.tickFont?.size]).filter((x): x is number => x !== undefined)];
  let lo = Math.min(1, (options.minTextPx ?? 8) / Math.max(1, Math.min(...sizes)));
  let hi = 1;
  let best = fitScatter3DScene(table, plotAt(lo), options);
  if (cubeFill(best) >= FILL) {
    for (let i = 0; i < 8; i++) {
      const mid = (lo + hi) / 2;
      const sc = fitScatter3DScene(table, plotAt(mid), options);
      if (cubeFill(sc) >= FILL) { lo = mid; best = sc; } else hi = mid;
    }
  }
  if ([plot.fonts?.tick?.size, plot.fonts?.axisTitle?.size, ...[plot.xAxis, plot.yAxis, plot.zAxis].flatMap((sp) => [sp?.titleFont?.size, sp?.tickFont?.size])].some((x) => x !== undefined)) {
    best.warnings.push(`3-D axis names are drawn at ${px10(f0.axisTitle.size * lo)}px, not the ${f0.axisTitle.size}px asked for: the cube would be too small in this box. A larger figure will honour it.`);
  }
  return best;
}

/** The measured fit of a 3-D scatter into its box at the fonts it is given (the text-size fit is `buildScatter3DScene`). */
function fitScatter3DScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  // `stretch` (a figure panel's re-draw) gets the same measured fit: a skewed cube would leave no room for the axis
  // names, and the panel card would cut them off.
  const measure = options.measure ?? estimateWidth;
  const atZoom1 = { ...plot, scatter3d: { ...(plot.scatter3d ?? {}), zoom: 1 } } as Plot;
  const probe = (k: number, dx = 0, dy = 0) => scatter3DExtent(scatter3DSceneAt(table, atZoom1, options, { k, dx, dy }), measure);
  const a = probe(0.5), b = probe(1);
  const rect = scatter3DSceneAt(table, atZoom1, options, { k: 1, dx: 0, dy: 0 }).plot;
  if (!a || !b) return scatter3DSceneAt(table, plot, options);
  const kFor = (spanA: number, spanB: number, room: number): number => {
    const slope = (spanB - spanA) / 0.5;
    return slope > 1e-9 ? (room - (spanA - slope * 0.5)) / slope : Infinity;
  };
  let k = Math.max(0.3, Math.min(8, kFor(a.x1 - a.x0, b.x1 - b.x0, rect.width), kFor(a.y1 - a.y0, b.y1 - b.y0, rect.height)));
  for (let pass = 0; pass < 6; pass++) {
    const at = probe(k);
    if (!at) break;
    const dx = rect.x + (rect.width - (at.x1 - at.x0)) / 2 - at.x0;
    const dy = rect.y + (rect.height - (at.y1 - at.y0)) / 2 - at.y0;
    const got = probe(k, dx, dy);
    if (!got) break;
    const fits = got.x0 >= rect.x - 0.5 && got.y0 >= rect.y - 0.5 && got.x1 <= rect.x + rect.width + 0.5 && got.y1 <= rect.y + rect.height + 0.5;
    if (fits || k <= 0.3) return scatter3DSceneAt(table, plot, options, { k, dx, dy });
    k = Math.max(0.3, k * Math.min(rect.width / (got.x1 - got.x0), rect.height / (got.y1 - got.y0)) * 0.995);
  }
  return scatter3DSceneAt(table, plot, options);
}

/** The drawn extent of a 3-D scatter scene — edges, axis names and tick numbers as text boxes (drawn
 *  centred on their x, on their baseline), floor lines and points. Drag offsets are the user's own
 *  placement and are not part of the fit. Undefined when nothing is drawn. */
function scatter3DExtent(s: PlotScene, measure: (text: string, px: number) => number): { x0: number; y0: number; x1: number; y1: number } | undefined {
  const d = s.scatter3d;
  if (!d) return undefined;
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  const pt = (x: number, y: number): void => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); };
  const text = (label: string, x: number, y: number, px: number): void => {
    if (!label) return;
    const hw = measure(label, px) / 2;
    pt(x - hw, y - px * 0.8);
    pt(x + hw, y + px * 0.25);
  };
  for (const a of d.axes) {
    if (a.hidden) continue;
    pt(a.x1, a.y1);
    pt(a.x2, a.y2);
    text(a.label, a.lx, a.ly, a.titleSize ?? s.fonts.axisTitle.size);
    for (const t of a.ticks ?? []) text(t.label, t.lx, t.ly, a.tickFont?.size ?? s.fonts.tick.size);
  }
  for (const f of d.floor) { pt(f.x1, f.y1); pt(f.x2, f.y2); }
  for (const q of d.points) { pt(q.x - q.r, q.y - q.r); pt(q.x + q.r, q.y + q.r); }
  return Number.isFinite(x0) ? { x0, y0, x1, y1 } : undefined;
}

/** Default 3-D camera (radians): a three-quarter view from slightly above. */
const DEFAULT_CAM3D = { az: -0.7, el: 0.42 };

/** Round fractional axial hex coords to the nearest hex (cube-rounding). */
function hexRound(q: number, r: number): [number, number] {
  let x = q;
  let z = r;
  let y = -x - z;
  let rx = Math.round(x);
  let ry = Math.round(y);
  let rz = Math.round(z);
  const dx = Math.abs(rx - x);
  const dy = Math.abs(ry - y);
  const dz = Math.abs(rz - z);
  if (dx > dy && dx > dz) rx = -ry - rz;
  else if (dy > dz) ry = -rx - rz;
  else rz = -rx - ry;
  return [rx, rz];
}

/**
 * Point-data heatmaps (kind "heatmap", mode "density2d" | "hexbin"): the first two
 * columns are (x, y) points. `density2d` paints a smooth grid of a 2-D Gaussian
 * KDE (per-axis Silverman bandwidth) → a white→colour density cloud; `hexbin`
 * tallies points into flat-packed hexagons coloured by count. Both draw a real
 * continuous X/Y axis (pointMode) + the shared colour-scale bar.
 */
/** Optional colour-bar extras: a rotated title + interior tick labels.
 *  The bar runs max (top, bar.y) → min (bottom, bar.y+bar.h); the renderer always
 *  draws the min/max ends, so only the *interior* ticks are emitted here. */
function colorbarExtras(
  hs: NonNullable<Plot["heatmap"]>,
  min: number,
  max: number,
  bar: { x: number; y: number; w: number; h: number },
): { colorbarTitle?: string | undefined; colorbarTicks?: { value: number; y: number }[] | undefined; colorbarCustom?: boolean; barFont?: ResolvedFont | undefined } {
  const title = hs.colorbarTitle && hs.colorbarTitle.trim() ? hs.colorbarTitle : undefined;
  let ticks: { value: number; y: number }[] | undefined;
  // `custom` = the user typed explicit values → the renderer shows only those (the
  // auto min/max labels are dropped so they don't clash); else it auto-populates.
  let custom = false;
  const yFor = (v: number): number => bar.y + bar.h * (1 - (v - min) / (max - min));
  if (Number.isFinite(min) && Number.isFinite(max) && max > min) {
    const explicit = hs.colorbarTickValues?.filter((v) => Number.isFinite(v));
    if (explicit && explicit.length) {
      // User-chosen values: one labelled tick each (clamped to the bar, min→max order).
      ticks = [...explicit].sort((a, b) => a - b).map((v) => ({ value: v, y: yFor(Math.max(min, Math.min(max, v))) }));
      custom = true;
    } else if (hs.colorbarTicks) {
      ticks = [0.25, 0.5, 0.75].map((f) => ({ value: min + f * (max - min), y: bar.y + bar.h * (1 - f) }));
    }
  }
  // Distinct colour-bar font; undefined → renderer falls back to the legend font.
  const barFont = hs.colorbarFont ? resolveFont(hs.colorbarFont, DEFAULTS.legendFont) : undefined;
  return { colorbarTitle: title, colorbarTicks: ticks, ...(custom ? { colorbarCustom: true } : {}), barFont };
}

/** The colour-bar extras with the number font shrunk to the column when the column was capped. */
function cbarFitted(
  extras: ReturnType<typeof colorbarExtras>,
  requested: number,
  fitted: number,
): ReturnType<typeof colorbarExtras> {
  if (fitted >= requested) return extras;
  return { ...extras, barFont: { ...(extras.barFont ?? resolveFont(undefined, requested)), size: fitted } };
}

function buildDensityScene(
  table: DataTable,
  plot: Plot,
  options: BuildPlotSceneOptions,
  mode: "density2d" | "hexbin",
): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const hs = plot.heatmap ?? {};
  // The bubble grid is a matrix presentation (a dot per row×column cell); a density cloud
  // or hexbin has no such cells. Refuse out loud rather than silently ignoring the option.
  if (hs.cellShape === "bubble") {
    warnings.push("Bubble cells apply to the matrix view; the density / hexbin views ignore them.");
  }
  const colormap = hs.colormap ?? (mode === "density2d" ? "blues" : "viridis");
  const reverse = hs.reverse ?? false;
  const showColorbar = hs.showColorbar ?? true;

  const cols = table.columns;
  const xCol = cols[0];
  const yCol = cols[1];
  if (!xCol || !yCol) warnings.push("A density heatmap needs at least two numeric columns (X and Y).");
  const pts = table.rows
    .map((r) => ({ x: xCol ? toNumber(r.cells[xCol.id]) : NaN, y: yCol ? toNumber(r.cells[yCol.id]) : NaN }))
    .filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y));
  if (xCol && yCol && pts.length < 3) warnings.push("Not enough (x, y) points for a density estimate.");
  // Matrix-shape guard: point-mode reads only the first two columns as (x, y), so a
  // value-per-cell matrix (extra numeric columns) silently loses everything past col 2.
  // Warn + point at the "matrix" mode so it doesn't just "look wrong".
  const extraNumeric = cols.slice(2).filter((c) => table.rows.some((r) => Number.isFinite(toNumber(r.cells[c.id]))));
  if (xCol && yCol && pts.length >= 3 && extraNumeric.length > 0)
    warnings.push(
      `This looks like matrix data: ${mode} reads only the first two columns as X and Y, so ${extraNumeric.length} other numeric column${extraNumeric.length > 1 ? "s are" : " is"} ignored. For a value-per-cell grid, set the heatmap Mode to “matrix”.`,
    );

  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const xFmt = tickFormat(xSpec);
  const yFmt = tickFormat(ySpec);
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const gridDensity = plot.grid?.density ?? 6;
  const xsv = pts.map((p) => p.x);
  const ysv = pts.map((p) => p.y);
  const xAutoDom = pts.length ? buildScale("linear", extent(xsv), [0, 1], gridDensity, false, xFmt).domain : ([0, 1] as [number, number]);
  const yAutoDom = pts.length ? buildScale("linear", extent(ysv), [0, 1], gridDensity, false, yFmt).domain : ([0, 1] as [number, number]);
  const xData = options.xDomain ?? applyRange(xSpec, xAutoDom);
  const yData = options.yDomain ?? applyRange(ySpec, yAutoDom);
  const manualX = options.xDomain != null || xSpec.min != null || xSpec.max != null;
  const manualY = options.yDomain != null || ySpec.min != null || ySpec.max != null;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelW = Math.max(0, ...yProbe.ticks.filter((t) => !t.minor).map((t) => measure(t.label, fonts.tick.size)));
  const xLabel = xSpec.title ?? xCol?.name ?? "X";
  const yLabel = ySpec.title ?? yCol?.name ?? "Y";
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const scaleW = showColorbar ? 56 : 4;
  const marginLeft = ySpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelW + DEFAULTS.tickLen + (ySpec.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6)) + pad.l;
  const marginBottom = xSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + (xSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, xSpec.titleGap ?? 6)) + pad.b;
  const marginRight = DEFAULTS.marginRight + scaleW + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale("linear", xData, [0, plotW], gridDensity, manualX, xFmt, xSpacing);
  const yb = buildScale("linear", yData, [plotH, 0], gridDensity, manualY, yFmt, ySpacing);
  // The natural "home" domain — the rest state ignoring any pan/zoom window. `auto` must be
  // this and not an echo of the current domain: the renderer soft-locks back to it and reads it
  // to know whether the chart is zoomed. Echoing the window would make both reads meaningless — the
  // detent could never fire and drag-to-pan could never wake up.
  const homeX: [number, number] = options.xDomain != null
    ? buildScale("linear", applyRange(xSpec, xAutoDom), [0, 1], gridDensity, xSpec.min != null || xSpec.max != null, xFmt, xSpacing).domain
    : xb.domain;
  const homeY: [number, number] = options.yDomain != null
    ? buildScale("linear", applyRange(ySpec, yAutoDom), [0, 1], gridDensity, ySpec.min != null || ySpec.max != null, yFmt, ySpacing).domain
    : yb.domain;



  const clamp01 = (t: number): number => Math.max(0, Math.min(1, t));
  const densityShape: RampShape = {
    midpointValue: hs.colorMidpoint, gamma: hs.colorGamma, steps: hs.colorSteps,
    space: hs.colorSpace, lo: 0, hi: 1,
  };
  const densityPaint = ramps.ramp(colormap, "#f7fbff", "#08306b", reverse, densityShape);
  const ramp = (t: number): string => densityPaint(clamp01(t)).color;
  const res = Math.max(8, Math.min(120, Math.round(hs.resolution ?? 40)));

  const cells: HeatCell[] = [];
  const hexes: HexBin[] = [];
  let min = 0;
  let max = 1;
  // Colour normalization span. The Inspector "Scale min/max" (valueMin/valueMax) override
  // the auto 0→peak range for density2d + hexbin, for both the colours and the
  // colour bar. Default (unset) is the plain v/peak.
  let span = 1;

  // No usable (x,y) points — the classic case is a matrix heatmap switched to density2d/
  // hexbin (a value-per-cell grid has no point cloud). Drawing anyway gives a blank hexbin
  // or a meaningless flat density field, which reads as "the mode is broken".
  // Skip the fill and hand the renderer a centred message instead.
  const enoughPoints = pts.length >= 3;
  const notice = enoughPoints
    ? undefined
    : `${mode === "hexbin" ? "Hexbin" : "2-D density"} needs raw X, Y points in the first two columns — none were found here. If this is a value-per-cell matrix, set the heatmap Mode to “matrix”.`;

  if (enoughPoints && mode === "density2d") {
    const xSpan = xData[1] - xData[0] || 1;
    const ySpan = yData[1] - yData[0] || 1;
    const hx = (silvermanBandwidth(xsv) || xSpan / 20) * 1.0;
    const hy = (silvermanBandwidth(ysv) || ySpan / 20) * 1.0;
    const invhx2 = hx > 0 ? 1 / (2 * hx * hx) : 0;
    const invhy2 = hy > 0 ? 1 / (2 * hy * hy) : 0;
    const GX = res;
    const GY = Math.max(6, Math.round((res * plotH) / Math.max(1, plotW)));
    const cw = plotW / GX;
    const ch = plotH / GY;
    const dens: number[] = new Array(GX * GY).fill(0);
    let peak = 0;
    for (let j = 0; j < GY; j++) {
      const dy = yData[1] - ((j + 0.5) / GY) * ySpan; // pixel-top = data max
      for (let i = 0; i < GX; i++) {
        const dx = xData[0] + ((i + 0.5) / GX) * xSpan;
        let s = 0;
        for (const p of pts) {
          const ex = dx - p.x;
          const ey = dy - p.y;
          s += Math.exp(-(ex * ex * invhx2 + ey * ey * invhy2));
        }
        dens[j * GX + i] = s;
        if (s > peak) peak = s;
      }
    }
    min = hs.valueMin ?? 0;
    max = hs.valueMax ?? peak;
    span = (max - min) || 1;
    for (let j = 0; j < GY; j++) {
      for (let i = 0; i < GX; i++) {
        const v = dens[j * GX + i]!;
        cells.push({
          x: plotX + i * cw,
          y: plotY + j * ch,
          w: cw + 0.5,
          h: ch + 0.5,
          color: ramp((v - min) / span),
          value: v,
          row: j,
          col: i,
          label: "",
          labelColor: "#000",
        });
      }
    }
  } else if (enoughPoints) {
    // hexbin — flat-packed pointy-top hexagons; horizontal pitch √3·r, vertical 3/2·r.
    const r = Math.max(4, plotW / (res * Math.sqrt(3)));
    const bins = new Map<string, { q: number; rr: number; count: number }>();
    for (const p of pts) {
      const sx = xb.scale(p.x); // pixel offset within [0,plotW]
      const sy = yb.scale(p.y);
      const q = ((Math.sqrt(3) / 3) * sx - (1 / 3) * sy) / r;
      const rr = ((2 / 3) * sy) / r;
      const [hq, hr] = hexRound(q, rr);
      const key = `${hq},${hr}`;
      const b = bins.get(key);
      if (b) b.count += 1;
      else bins.set(key, { q: hq, rr: hr, count: 1 });
    }
    let peak = 0;
    for (const b of bins.values()) if (b.count > peak) peak = b.count;
    min = hs.valueMin ?? 0;
    max = hs.valueMax ?? (peak || 1);
    span = (max - min) || 1;
    const hexPath = (cx: number, cy: number): string => {
      const pts6: string[] = [];
      for (let k = 0; k < 6; k++) {
        const a = (Math.PI / 180) * (60 * k - 90); // pointy-top
        pts6.push(`${(cx + r * Math.cos(a)).toFixed(2)},${(cy + r * Math.sin(a)).toFixed(2)}`);
      }
      return `M${pts6.join("L")}Z`;
    };
    for (const b of bins.values()) {
      const sx = r * Math.sqrt(3) * (b.q + b.rr / 2);
      const sy = r * (3 / 2) * b.rr;
      const cx = plotX + sx;
      const cy = plotY + sy;
      hexes.push({ path: hexPath(cx, cy), cx, cy, color: ramp((b.count - min) / span), count: b.count });
    }
  }

  const xAxis: AxisScene = {
    type: "linear",
    domain: xb.domain,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, fonts.tick.size),
    title: xLabel,
    ...axisLine(xSpec),
  };
  const yAxis: AxisScene = {
    type: "linear",
    domain: yb.domain,
    range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })),
    title: yLabel,
    ...axisLine(ySpec),
  };

  const bar = { x: plotX + plotW + 14, y: plotY, w: 14, h: plotH };
  const scaleStops = ramps.barStops(colormap, "#f7fbff", "#08306b", reverse, densityShape);

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis,
    y: yAxis,
    auto: { x: homeX, y: homeY },
    // 2-D density / hexbin: both axes are continuous and both overrides are honoured above.
    // Note: declared because it is true of the builder — but this scene renders through
    // `HeatmapFigure`, which has no pan/zoom surface, so nothing offers the gesture.
    // Recorded rather than left undeclared so the two halves cannot drift.
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series: [],
    legend: [],
    legendLayout: NO_LEGEND,
    annotations: buildAnnotations(
      plot,
      { x: plotX, y: plotY, width: plotW, height: plotH },
      // Real linear x/y axes here, so a value-anchored annotation lands at its values.
      {
        x: (v) => (Number.isFinite(v) ? plotX + xb.scale(v) : undefined),
        y: (v) => (Number.isFinite(v) ? plotY + yb.scale(v) : undefined),
        bracketX: (v) => (Number.isFinite(v) ? plotX + xb.scale(v) : undefined),
      },
      false,
      warnings,
    ),
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: xLabel, y: yLabel },
    kind: "heatmap",
    fonts,
    heatmap: {
      cells,
      colLabels: [],
      rowLabels: [],
      // Density / hexbin draws continuous axes and no column labels, so there is no rotated
      // tail to lift clear of anything. Stated rather than made optional: a required field is
      // what stops the next builder from forgetting the number and letting the renderer guess.
      colLabelLift: 0,
      pointMode: true,
      hexes,
      notice,
      min,
      max,
      border: { color: hs.cellBorderColor ?? null, width: hs.cellBorderWidth ?? 0 },
      showColorbar,
      bar,
      scaleStops,
      ...colorbarExtras(hs, min, max, bar),
    },
    warnings,
  };
}

/**
 * Heatmap: a grid of cells (rows × datasets) coloured by value through a
 * perceptual colormap (viridis). Column labels = dataset names (top), row labels
 * = the X-column value (left), plus a vertical colour-scale bar.
 */
function buildHeatmapScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const mode = plot.heatmap?.mode ?? "matrix";
  if (mode === "density2d" || mode === "hexbin") return buildDensityScene(table, plot, options, mode);
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  /**
   * A multivariable sheet's text column is its row labels, not a row of grey cells.
   * `xColumn()` is undefined for a multivariable table (every column is a peer), so an untagged
   * leading text column ("Cell type", "Gene") would go into the matrix as a variable — every cell
   * of it NaN → a whole grey column of `nanColor` — with the rows labelled 1..n and no warning.
   * Read a leading column that holds only text as the
   * row-label column, exactly as an explicit `role:"x"` tag would. A tagged column still wins; a
   * numeric first column is data.
   *
   * Note: deliberately not a `warnings` entry. This is the correct reading of the sheet, not a
   * defect — the same drawing an explicit tag produces, silently. A warning here would demote
   * the heatmap in the graph-suggestion rank ("clean" = draws with no warning), placing it
   * behind a 3-D scatter that cannot draw the sheet at all. The datasheet's column menu offers
   * "Use as row labels" to make the tag explicit.
   */
  let xCol = xColumn(table);
  let datasets = visibleDatasets(table, plot);
  if (!xCol && table.kind === "multivariable" && table.columns.length > 1) {
    const first = table.columns[0]!;
    const cells = table.rows.map((r) => r.cells[first.id]).filter((v) => v != null && v !== "");
    const allText = cells.length > 0 && cells.every((v) => typeof v === "string" && !Number.isFinite(Number(v)));
    if (allText) {
      xCol = first;
      datasets = datasets.filter((d) => d.id !== first.id);
    }
  }
  // A column an annotation strip reads is not also a matrix column. Leaving it in draws the
  // same information twice — and a text annotation lands in the matrix as a row of grey
  // "missing" cells, which reads as broken data.
  const annotationCols = new Set((plot.heatmap?.rowTracks ?? []).map((t) => t.column).filter((c): c is NodeId => !!c));
  if (annotationCols.size) datasets = datasets.filter((d) => !annotationCols.has(d.id));
  let ncols = datasets.length;
  const rowsIn = table.rows;
  let nrows = rowsIn.length;

  const hs = plot.heatmap ?? {};
  const colormap = hs.colormap ?? "viridis";
  const reverse = hs.reverse ?? false;
  const nanColor = hs.nanColor ?? "#dddddd";
  const showColorbar = hs.showColorbar ?? true;
  const showRowLabels = hs.showRowLabels ?? true;
  const showColLabels = hs.showColLabels ?? true;
  const showValues = hs.showValues ?? false;

  // Each cell = the mean of the dataset's finite replicate subcolumns in that row (a
  // grouped/replicated table has >1 column per dataset); a single-column dataset is
  // unchanged (mean of the one value). Reading only ds.id (the lead replicate) would
  // silently discard replicates 2..k.
  const rawMatrix = rowsIn.map((row) => datasets.map((ds) => rowDatasetMean(row, ds)));

  /**
   * Replicate collapse — average the rows / columns that share an annotation value into one.
   *
   * Runs here, before the min/max, the clustering and the splits, because it changes the
   * matrix itself: everything downstream must see the collapsed data or the picture and the
   * numbers would disagree. What belongs together comes from an annotation strip, so the
   * grouping the figure shows is the grouping it averages — they cannot drift apart.
   */
  const reduceVals = (vals: number[], how: "mean" | "median"): number => {
    const ok = vals.filter((v) => Number.isFinite(v));
    if (ok.length === 0) return Number.NaN;
    if (how === "mean") return ok.reduce((a, b) => a + b, 0) / ok.length;
    const sorted = [...ok].sort((a, b) => a - b);
    const mid = sorted.length >> 1;
    return sorted.length % 2 ? sorted[mid]! : (sorted[mid - 1]! + sorted[mid]!) / 2;
  };
  /** Indices that share a value, in first-seen order. Undefined = nothing would be joined. */
  const groupsOf = (values: string[]): { label: string; members: number[] }[] | undefined => {
    const order: { label: string; members: number[] }[] = [];
    const seen = new Map<string, number>();
    values.forEach((v, i) => {
      // A blank groups with nothing. Two rows the user has not labelled are not "the same
      // treatment" — averaging them would invent a group nobody asked for.
      if (v === "") { order.push({ label: "", members: [i] }); return; }
      const at = seen.get(v);
      if (at === undefined) { seen.set(v, order.length); order.push({ label: v, members: [i] }); }
      else order[at]!.members.push(i);
    });
    return order.length === values.length ? undefined : order;
  };
  /** The chosen strip's values for an axis, before any reordering. */
  const collapseValues = (
    tracks: HeatTrack[] | undefined, which: number | undefined, axis: "row" | "col",
  ): string[] | undefined => {
    const t = (tracks ?? [])[Math.max(0, Math.floor(which ?? 0))];
    if (!t) return undefined;
    return axis === "row"
      ? rowsIn.map((r) => (t.column ? String(r.cells[t.column] ?? "") : ""))
      : datasets.map((d) => t.values?.[d.id] ?? "");
  };
  /** The label says it is an average. A group of one keeps its plain name — nothing was averaged. */
  const collapseName = (label: string, n: number, how: "mean" | "median"): string =>
    n > 1 ? `${label} (${how} of ${n})` : label;

  let matrix = rawMatrix;
  let collapsedRows: { label: string; members: number[] }[] | undefined;
  let collapsedCols: { label: string; members: number[] }[] | undefined;
  const howRows = hs.collapseRows ?? "off";
  const howCols = hs.collapseCols ?? "off";
  if (howRows !== "off") {
    const vals = collapseValues(hs.rowTracks, hs.collapseRowsBy, "row");
    const groups = vals ? groupsOf(vals) : undefined;
    if (!groups) {
      warnings.push("Collapsing replicate rows needs a row strip saying which rows belong together, with at least two rows sharing a value.");
    } else {
      collapsedRows = groups;
      const before = matrix;
      matrix = groups.map((g) => datasets.map((_d, j) => reduceVals(g.members.map((i) => before[i]![j]!), howRows)));
    }
  }
  if (howCols !== "off") {
    const vals = collapseValues(hs.colTracks, hs.collapseColsBy, "col");
    const groups = vals ? groupsOf(vals) : undefined;
    if (!groups) {
      warnings.push("Collapsing replicate columns needs a column strip saying which columns belong together, with at least two columns sharing a value.");
    } else {
      collapsedCols = groups;
      matrix = matrix.map((row) => groups.map((g) => reduceVals(g.members.map((j) => row[j]!), howCols)));
    }
  }
  // Everything downstream — the scale, the clustering, the splits, the labels — counts the
  // collapsed rows and columns.
  if (collapsedRows) nrows = collapsedRows.length;
  if (collapsedCols) ncols = collapsedCols.length;
  const finite = matrix.flat().filter((v) => Number.isFinite(v));
  const autoMin = finite.length ? Math.min(...finite) : 0;
  const autoMax = finite.length ? Math.max(...finite) : 1;
  const min = hs.valueMin ?? autoMin;
  const max = hs.valueMax ?? autoMax;
  const span = max - min || 1;
  const heatShape: RampShape = {
    midpointValue: hs.colorMidpoint, gamma: hs.colorGamma, steps: hs.colorSteps,
    space: hs.colorSpace, lo: min, hi: max, values: finite,
  };
  const heatPaint = ramps.ramp(colormap, "#440154", "#fde725", reverse, heatShape);
  // Not clamped here: a value outside a pinned scale has to reach the mapping, or its
  // under/over colour can never be applied (makeRamp clamps for everything else).
  const ramp = (t: number): string => heatPaint(t).color;
  const colorAt = (v: number): string => (Number.isFinite(v) ? ramp((v - min) / span) : nanColor);
  // Auto-contrast label colour: light text on dark cells, dark on light.
  const contrast = (hex: string): string => contrastInk(hex, "#000");
  const fmtCell = (v: number): string => (Number.isInteger(v) ? String(v) : Number(v.toFixed(2)).toString());

  // --- hierarchical clustering: reorder rows / columns so similar profiles sit
  //     adjacent (revealing blocks), and remember the trees for the attached dendrograms.
  const clusterMode = hs.cluster ?? "none";
  const cmetric = hs.clusterMetric ?? "euclidean";
  const clink = hs.clusterLinkage ?? "average";
  // Ward is only valid on Euclidean geometry; `hclust` forces it, so warn rather than
  // silently clustering on a different metric than the menu shows.
  if (clink === "ward" && cmetric !== "euclidean" && clusterMode !== "none")
    warnings.push("Ward linkage requires Euclidean distance — clustered on Euclidean, not the selected metric.");
  const clusterRows = clusterMode === "rows" || clusterMode === "both";
  const clusterCols = clusterMode === "columns" || clusterMode === "both";
  const showDendro = (hs.showDendrogram ?? true) && clusterMode !== "none";
  let rowRes: HClustResult | null = null;
  let colRes: HClustResult | null = null;
  // Note: from the collapsed counts, not from `rowsIn` / `datasets`: after a collapse the matrix
  // has fewer rows/columns than the table does, and an order built from the table would index
  // past the end of it (the labels would come out as `undefined`).
  let rowOrder = Array.from({ length: nrows }, (_v, i) => i);
  let colOrder = Array.from({ length: ncols }, (_v, j) => j);
  if (clusterRows && nrows >= 2) {
    rowRes = hclust(matrix, cmetric, clink);
    rowOrder = rowRes.order;
  }
  if (clusterCols && ncols >= 2) {
    const colVectors = Array.from({ length: ncols }, (_v, j) => matrix.map((row) => row[j]!));
    colRes = hclust(colVectors, cmetric, clink);
    colOrder = colRes.order;
  }
  // Display matrix in clustered order (identity when a side isn't clustered).
  const dmatrix = rowOrder.map((ri) => colOrder.map((ci) => matrix[ri]![ci]!));

  // Row/column labels get their own font (default = the tick font, capped ≤12 so
  // adjacent column labels don't collide) and an optional rotation for the columns.
  const labelFont = hs.labelFont ? resolveFont(hs.labelFont, Math.min(DEFAULTS.tickFont, 12)) : undefined;
  // The block names beside the splits are their own text, so they get their own font — falling
  // back to the row/column label font, which falls back to the tick font.
  const splitLabelFont = hs.splitLabelFont ? resolveFont(hs.splitLabelFont, Math.min(DEFAULTS.tickFont, 12)) : undefined;
  const labelSize = labelFont?.size ?? Math.min(fonts.tick.size, 12);
  let labelRotation = hs.labelRotation ?? 0;
  // Editable axis titles — rows axis (Y, left) and columns axis (X, bottom).
  const xTitle = plot.xAxis?.title ?? "";
  const yTitle = plot.yAxis?.title ?? "";

  const rowLabelTexts = collapsedRows
    ? collapsedRows.map((g) => collapseName(g.label, g.members.length, howRows === "median" ? "median" : "mean"))
    : rowsIn.map((row, i) => (xCol ? String(row.cells[xCol.id] ?? i + 1) : String(i + 1)));
  const colLabelTexts = collapsedCols
    ? collapsedCols.map((g) => collapseName(g.label, g.members.length, howCols === "median" ? "median" : "mean"))
    : datasets.map((ds) => ds.name);
  // Labels + cells follow the clustered display order.
  const dispRowLabels = rowOrder.map((ri) => rowLabelTexts[ri]!);
  const dispColLabels = colOrder.map((ci) => colLabelTexts[ci]!);
  /**
   * Annotation tracks — the strips that say what each row / column is.
   *
   * Resolved before the margins, because each strip has to be reserved room the way the
   * dendrograms and the colour bar are (the right margin is a stack; so is the left).
   *
   * Values are read in the display order. Clustering reorders the rows, and a strip built
   * from the table order would then label the wrong ones — the failure would look like the
   * annotation being wrong rather than the drawing.
   */
  // 16, not 14: at 14 the default word sits edge-to-edge in its band and reads as clipped.
  const trackSize = Math.max(2, hs.trackSize ?? 16);
  const trackGap = Math.max(0, hs.trackGap ?? 3);
  const trackFontSize = hs.trackFont?.size ?? Math.min(labelSize, 10);
  interface TrackData { track: HeatTrack; axis: "row" | "col"; values: string[]; nums: number[]; numeric: boolean; size: number }
  const readTrack = (track: HeatTrack, axis: "row" | "col"): TrackData => {
    // On a collapsed axis a strip has one value per group. Members that disagree carry none:
    // a strip that averaged "Ctrl" and "Treated" together must not claim to be either.
    const perItem = axis === "row"
      ? (collapsedRows
        ? collapsedRows.map((g) => {
          const vs = g.members.map((i) => (track.column ? String(rowsIn[i]?.cells[track.column] ?? "") : ""));
          return vs.every((v) => v === vs[0]) ? vs[0]! : "";
        })
        : rowsIn.map((r) => (track.column ? String(r.cells[track.column] ?? "") : "")))
      : (collapsedCols
        ? collapsedCols.map((g) => {
          const vs = g.members.map((j) => track.values?.[datasets[j]?.id ?? ""] ?? "");
          return vs.every((v) => v === vs[0]) ? vs[0]! : "";
        })
        : datasets.map((d) => track.values?.[d.id] ?? ""));
    const raw = (axis === "row" ? rowOrder : colOrder).map((i) => perItem[i] ?? "");
    const nums = raw.map((v) => Number(v));
    const allNum = raw.some((v) => v !== "") && raw.every((v) => v === "" || Number.isFinite(Number(v)));
    const scale = track.scale ?? "auto";
    const numeric = scale === "value" || (scale === "auto" && allNum);
    return { track, axis, values: raw, nums, numeric, size: Math.max(2, track.size ?? trackSize) };
  };
  const rowTrackData = (hs.rowTracks ?? []).map((t) => readTrack(t, "row"));
  const colTrackData = (hs.colTracks ?? []).map((t) => readTrack(t, "col"));
  // A row strip is a vertical band left of the cells; a column strip a horizontal one above.
  const rowTrackBand = rowTrackData.reduce((w, t) => w + t.size + trackGap, 0);
  const colTrackBand = colTrackData.reduce((h, t) => h + t.size + trackGap, 0);
  // The strip names sit at the head of each band (left of a row strip, above a column strip).
  // A row strip's name hangs below the plot reading bottom-to-top, so the room it needs is
  // its length, not one line of text; one line would let the rotated name run off the bottom
  // of the figure.
  const rowTrackNameH = Math.max(0, ...rowTrackData.map((t) => (t.track.name ? measure(t.track.name, trackFontSize) + 6 : 0)));
  const colTrackNameW = Math.max(0, ...colTrackData.map((t) => (t.track.name ? measure(t.track.name, trackFontSize) + 6 : 0)));
  /**
   * Keys for numeric strips. A categorical strip carries its own words; a numeric one shades
   * through a ramp with nothing to decode it, so it gets a small colour bar — the same answer
   * the `tracks` kind gives its numeric strips. They stack in one column at the far right, so
   * the margin grows by one column however many strips there are.
   */
  const showTrackKeys = hs.trackKeys !== false;
  const KEY_BAR_W = 12;
  /** The end numbers as the renderer will draw them — measured, so the column fits them. */
  const keyNum = (v: number): string => String(Math.round(v * 100) / 100);
  /** What a key says it decodes: the strip's name, else the sheet column it reads. */
  const keyCaption = (track: HeatTrack): string =>
    track.name || (track.column ? (table.columns.find((c) => c.id === track.column)?.name ?? "") : "");
  const trackRange = (t: TrackData): { lo: number; hi: number; nums: number[] } => {
    const finite = t.nums.filter((v) => Number.isFinite(v));
    return { lo: finite.length ? Math.min(...finite) : 0, hi: finite.length ? Math.max(...finite) : 1, nums: finite };
  };
  const keyTracks = showTrackKeys ? [...rowTrackData, ...colTrackData].filter((t) => t.numeric) : [];
  /**
   * Clear the main colour bar — measure it, do not assume it.
   *
   * `scaleW` is a flat 56px for the bar and its numbers, which is enough for the usual small
   * legend font and no title. The keys go beyond that, so with a big colour-bar font (or a
   * rotated colour-bar title) a fixed offset would print the key's caption straight through
   * the bar's numbers. This measures what the bar actually occupies and takes the difference.
   */
  // Note: the resolved legend size, not the raw default: a preset scales the fonts, so a
  // colour-bar number can be drawn half again as large as DEFAULTS.legendFont, and measuring at
  // the default would leave the caption overlapping by that much.
  const cbarFontSize = hs.colorbarFont?.size ?? fonts.legend.size;
  const cbarNumW = showColorbar ? Math.max(measure(keyNum(min), cbarFontSize), measure(keyNum(max), cbarFontSize)) : 0;
  // The rotated title stands at a fixed 34 px from the bar, in the same band as the numbers (it
  // runs along the bar's middle; the numbers sit at its ends) — so the column holds the wider of
  // the two, not their sum. Summing them would reserve a title's width twice over.
  const cbarTitleW = hs.colorbarTitle && hs.colorbarTitle.trim() ? cbarFontSize + 20 : 0;
  const cbarZoneWant = showColorbar ? 14 + 14 + Math.max(cbarNumW, cbarTitleW) : 8;
  /**
   * The colour-bar column gets what its numbers measure — behind a fixed 56, a "-1.56" at a 20 px
   * legend font would run 8 px past the figure's right edge — but never more than the figure can
   * spare: past 25% of the width (and never under 56) the numbers
   * shrink to the column instead, so a narrow figure keeps its cells (the gallery's narrow-figure
   * rule). The fitted size reaches the drawing through `barFont`.
   */
  const cbarZoneW = showColorbar ? Math.min(cbarZoneWant, Math.max(56, Math.floor(width * 0.25))) : 8;
  const cbarNumFit = showColorbar && cbarZoneW < cbarZoneWant && cbarZoneW - 28 < cbarNumW
    ? Math.max(7, Math.min(cbarFontSize, Math.floor((cbarFontSize * Math.max(0, cbarZoneW - 28)) / cbarNumW + 1e-6)))
    : cbarFontSize;
  // The column has to hold the widest of: the bar + its end numbers, and the caption above it.
  // Note: +12 in keyColX pushes the column clear of the bar's numbers; the column has to be that
  // much wider or the widest caption spills over the figure edge instead.
  const keyColW = keyTracks.length
    ? Math.max(
      ...keyTracks.map((t) => {
        const { lo, hi } = trackRange(t);
        return KEY_BAR_W + 4 + Math.max(measure(keyNum(lo), trackFontSize), measure(keyNum(hi), trackFontSize));
      }),
      ...keyTracks.map((t) => measure(keyCaption(t.track), trackFontSize)),
    ) + 18
    : 0;
  // Reserve a margin strip for each attached dendrogram (left for rows, top for cols).
  const DENDRO = 46;
  const rowDendW = showDendro && clusterRows && nrows >= 2 ? DENDRO : 0;
  const colDendH = showDendro && clusterCols && ncols >= 2 ? DENDRO : 0;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const rowLabelW = showRowLabels ? Math.max(0, ...rowLabelTexts.map((t) => measure(t, labelSize))) : 0;
  // Rotated Y-axis title strip on the far left: the title's whole glyph height, then its gap to what
  // stands right of it (the row tree or the row labels).
  //
  // The title's position is not left to the shared post-pass, which anchors a Y title left of the
  // axis's tick labels. A matrix heatmap has no ticks (its row names are drawn by the heatmap layer),
  // so that anchor would fall back to the grid's own edge and put the title on the row names. The
  // builder owns this one: glyph top at the left padding, gap = titleGap.
  const yTitleGap = plot.yAxis?.titleGap ?? 6;
  const yTitleW = yTitle ? Math.ceil(fonts.yAxisTitle.size * (TEXT_ASCENT + TEXT_DESCENT)) + yTitleGap : 0;
  // The colour-scale bar + its min/max labels: the measured width (cbarZoneW: bar, gaps and the
  // wider of the two numbers at their font), never less than 56. At a fixed width, a "-1.56"
  // at a 20 px legend font would run 8 px past the figure's right edge.
  const scaleW = showColorbar ? Math.max(56, cbarZoneW) : 8; // the bounded, measured column (see cbarZoneW)
  const keyClearW = keyTracks.length ? Math.max(0, cbarZoneW - scaleW) : 0;
  // The left margin is a stack too: [Y title][row tree][row labels][annotation strips][cells].
  // A column strip's name is drawn to the left of it, so it widens this band as well.
  const marginLeft = yTitleW + rowDendW + rowLabelW + 10 + rowTrackBand + Math.max(0, colTrackNameW - 4) + pad.l;
  // The right margin is a stack. A row-block name is drawn beyond the cells, so it has to be
  // reserved here or it lands on the colour bar and is clipped by the figure edge.
  const splitLabelSize = hs.splitLabelFont?.size ?? labelSize;
  const rowBlockW = Math.max(0, ...(hs.rowSplits ?? []).map((sp) => (sp.label ? measure(sp.label, splitLabelSize) + 8 : 0)));
  const colBlockH = (hs.colSplits ?? []).some((sp) => sp.label) ? splitLabelSize + 4 : 0;
  /**
   * Column names that do not fit flat turn 45°. Without fitting, long column names run into each
   * other even at the default size on a small heatmap. Only while the user has set no rotation (0° is
   * a choice and is kept). The column width does not depend on the rotation - it only grows the
   * room above the cells - so it is measured here, before that room is sized: the same margins and split gaps the
   * cells get below (a per-split gap override is not counted; the chart-wide gap is).
   */
  if (hs.labelRotation == null && showColLabels && ncols > 1) {
    const mR = DEFAULTS.marginRight + scaleW + keyClearW + rowBlockW + keyColW + pad.r;
    const w0 = effectiveWidth(plot, width, marginLeft, mR);
    const kTree = Math.floor(hs.colSplitK ?? 0);
    const breaks = kTree >= 2 && colRes ? kTree - 1 : (hs.colSplits ?? []).filter((sp) => sp.at >= 0 && sp.at < ncols - 1).length;
    const gapEach = (hs.splitStyle ?? "gap") === "line" ? 0 : Math.max(0, hs.splitGap ?? 8);
    const cellW0 = Math.max(1, w0 - marginLeft - mR - breaks * gapEach) / ncols;
    // At the size the names are drawn: one font styles rows and columns, and it shrinks to the row height below
    // (fitStackedLabels). Measured at the size asked for, names that fit once shrunk would be tilted needlessly.
    const mTop0 = DEFAULTS.marginTop + topPad + colDendH + labelSize + 8 + colBlockH + colTrackBand;
    const mBot0 = fonts.tick.size + 10 + (xTitle ? fonts.xAxisTitle.size + 8 : 0) + rowTrackNameH + pad.b;
    const h0 = effectiveHeight(plot, height, mTop0, mBot0);
    const kRow = Math.floor(hs.rowSplitK ?? 0);
    const rowBreaks = kRow >= 2 && rowRes ? kRow - 1 : (hs.rowSplits ?? []).filter((sp) => sp.at >= 0 && sp.at < nrows - 1).length;
    const cellH0 = nrows > 0 ? Math.max(1, h0 - mTop0 - mBot0 - rowBreaks * gapEach) / nrows : h0;
    const drawnSize = Math.min(labelSize, fitStackedLabels(nrows, cellH0, labelFont?.size ?? Math.min(DEFAULTS.tickFont, 12)).font);
    const widest = Math.max(0, ...colLabelTexts.map((t) => measure(t, drawnSize)));
    // No warning: this is the default look, not a refusal - the "Column label angle" control reads Auto and says
    // what it does, and a stock gallery card must warn of nothing.
    if (widest + 4 > cellW0) labelRotation = 45;
  }
  // Rotated column labels project their width onto the vertical, so reserve more top room.
  const rot = Math.abs(labelRotation) % 180;
  const maxColLabelW = showColLabels ? Math.max(0, ...colLabelTexts.map((t) => measure(t, labelSize))) : 0;
  /**
   * How far above the grid the column labels' pivot sits — the same approach the correlation matrix
   * uses as `colLabelLift`, and for the same reason.
   *
   * A rotated column label anchored at its end and rotated about that point hangs its tail
   * down-left by `width × sin(angle)`. With a flat 5 px lift, at 45° the labels would drop straight
   * into the first row of cells while the band this margin reserves for them sits empty above.
   *
   * Note: the gap is the renderer's own constant, named rather than repeated — at rot 0 the
   * lift is exactly 5.
   */
  const colLabelGap = 5;
  const colLabelDrop = showColLabels && rot !== 0 ? Math.ceil(maxColLabelW * Math.sin((Math.min(rot, 90) * Math.PI) / 180)) : 0;
  // A tilted name starts at the top of its own column and rises up-right. (Pinned at its end, with every one
  // lifted by the longest name's drop, a short name would hang ~110 px above its column.) Starting at the column,
  // every name touches the grid whatever its length; nothing hangs down into the cells, so the pivot sits the same
  // small gap above the grid at every angle.
  const colLabelLift = colLabelGap;
  const colLabelPad = showColLabels
    ? (rot === 0 ? labelSize + 8 : colLabelDrop + labelSize * 0.7 + colLabelGap + 8)
    : 4;
  const marginTop = DEFAULTS.marginTop + topPad + colDendH + colLabelPad + colBlockH + colTrackBand; // + annotation strips
  const xTitleH = xTitle ? fonts.xAxisTitle.size + 8 : 0; // X-axis title strip at the very bottom
  let marginRight = DEFAULTS.marginRight + scaleW + keyClearW + rowBlockW + keyColW + pad.r; // colour bar + block names + strip keys
  // A row strip's name is drawn under it, so it needs its own line at the bottom.
  const marginBottom = fonts.tick.size + 10 + xTitleH + rowTrackNameH + pad.b;
  /**
   * A tilted name rises right from its column, so the last columns' names reach past the grid's right edge. The right
   * margin grows by what the furthest-reaching name needs beyond the room it already has (the colour bar sits beside the
   * cells, below the names, and is not in their way), so no name runs off the figure.
   */
  if (showColLabels && rot > 0 && rot < 90) {
    const cos = Math.cos((rot * Math.PI) / 180);
    const cellW = Math.max(1, effectiveWidth(plot, width, marginLeft, marginRight) - marginLeft - marginRight) / Math.max(1, ncols);
    const reach = Math.max(0, ...dispColLabels.map((t, i) => measure(t, labelSize) * cos - (ncols - i - 0.5) * cellW));
    if (reach + 4 > marginRight) marginRight = Math.ceil(reach + 4);
  }
  // Honour xAxisLength / yAxisLength so panel-figure "Align X/Y-axes" resizes the cell
  // grid. With the raw figure size a matrix heatmap would ignore the aligned axis lengths
  // and keep its full height, towering over the other panels in a row. The bar/box/violin
  // builders do the same via effectiveWidth/effectiveHeight.
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, marginTop, marginBottom);
  const plotX = marginLeft;
  const plotY = marginTop;
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - marginTop - marginBottom);
  /**
   * Splits — the breaks that cut the matrix into blocks.
   *
   * The space a split opens is taken out of the plot before the cells are sized, so the matrix
   * still fills its box exactly: n cells share (plot − total gap). `before[k]` is how many
   * pixels of gap sit before index k, which is all the geometry any consumer needs — cells,
   * row/column labels and the dendrogram leaves all shift through the same two functions, so
   * they cannot drift apart.
   */
  const splitDefaults = {
    style: hs.splitStyle ?? "gap",
    gap: hs.splitGap ?? 8,
    lineWidth: hs.splitLineWidth ?? 1.5,
    color: hs.splitColor ?? "var(--ink)",
    dash: hs.splitDash ?? ("solid" as LineDash),
  };
  /** One split resolved against the chart-wide defaults (field by field). */
  const resolveSplit = (sp: HeatSplit) => {
    const style = sp.style ?? splitDefaults.style;
    return {
      at: Math.round(sp.at),
      style,
      gap: style === "line" ? 0 : Math.max(0, sp.gap ?? splitDefaults.gap),
      lineWidth: style === "gap" ? 0 : Math.max(0, sp.lineWidth ?? splitDefaults.lineWidth),
      color: sp.color ?? splitDefaults.color,
      dash: sp.dash ?? splitDefaults.dash,
      label: sp.label ?? "",
      labelOffset: sp.labelOffset,
    };
  };
  /** Keep the splits that can actually cut this matrix; say so about the ones that cannot. */
  const usableSplits = (list: HeatSplit[] | undefined, count: number, what: string) => {
    const out = (list ?? []).map(resolveSplit).filter((sp) => {
      if (sp.at >= 0 && sp.at < count - 1) return true;
      // A split outside the matrix cannot draw anything. Refused with a warning rather than
      // dropped, so the user does not keep re-typing a number that will never work.
      warnings.push(`A ${what} split after ${what} ${sp.at + 1} is outside this heatmap (it has ${count}), so it was not drawn.`);
      return false;
    });
    return out.sort((a, b) => a.at - b.at);
  };
  /**
   * Blocks from the tree. `rowSplitK`/`colSplitK` cut the dendrogram into k blocks and use the
   * result as the breaks — so they follow the data instead of being pinned to row numbers that
   * go stale the moment a row is added.
   *
   * Needs a tree. Asking for blocks on an axis that is not clustered draws nothing, so it is
   * refused with a warning. And if a hand-placed list is also present, that is reported too:
   * silently ignoring the user's own breaks would be a quiet override.
   */
  const derived = (k: number | undefined, res: HClustResult | null, list: HeatSplit[] | undefined, what: string): HeatSplit[] | undefined => {
    const kk = Math.floor(k ?? 0);
    if (kk < 2) return undefined;
    if (!res) {
      warnings.push(`Splitting the ${what}s into ${kk} blocks needs them clustered — set Cluster to include ${what}s.`);
      return undefined;
    }
    if ((list ?? []).length > 0) {
      warnings.push(`The ${what} breaks come from the tree (${kk} blocks), so the ${what} breaks you placed by hand are not drawn.`);
    }
    return clusterBreaks(res, kk).map((at) => ({ at }));
  };
  const rowFromTree = derived(hs.rowSplitK, rowRes, hs.rowSplits, "row");
  const colFromTree = derived(hs.colSplitK, colRes, hs.colSplits, "column");
  const rowSplits = usableSplits(rowFromTree ?? hs.rowSplits, nrows, "row");
  const colSplits = usableSplits(colFromTree ?? hs.colSplits, ncols, "column");
  /** Pixels of gap sitting before index k. */
  const gapOffsets = (splits: { at: number; gap: number }[], count: number): number[] => {
    const before = new Array<number>(count + 1).fill(0);
    let run = 0;
    for (let k = 0; k <= count; k++) {
      before[k] = run;
      for (const sp of splits) if (sp.at === k) run += sp.gap;
    }
    return before;
  };
  const colBefore = gapOffsets(colSplits, ncols);
  const rowBefore = gapOffsets(rowSplits, nrows);
  const colGapTotal = colBefore[ncols] ?? 0;
  const rowGapTotal = rowBefore[nrows] ?? 0;
  const cellW = ncols > 0 ? Math.max(1, plotW - colGapTotal) / ncols : plotW;
  const cellH = nrows > 0 ? Math.max(1, plotH - rowGapTotal) / nrows : plotH;
  // Row labels shrink to the cell height, then thin (as on the paired dot chart), so dense rows
  // (48 gene names, say) do not run into each other. One font styles rows and columns,
  // so both follow; a tall figure is untouched.
  const labelWant = labelFont?.size ?? Math.min(DEFAULTS.tickFont, 12);
  const rowFit = fitStackedLabels(nrows, cellH, labelWant);
  // No "not the size asked for" warning here, unlike the paired dot: the kind house default
  // writes `heatmap.labelFont.size` on every new heatmap, so a typed size cannot be told from
  // the default one, and the warning would fire on every dense heatmap in the gallery.
  const labelFontFit: ResolvedFont | undefined = rowFit.font < labelWant ? { ...(labelFont ?? resolveFont(undefined, labelWant)), size: rowFit.font } : labelFont;
  /** Left edge of column j / top edge of row i, with the splits' spaces included. */
  const colX = (j: number): number => plotX + j * cellW + (colBefore[Math.max(0, Math.min(ncols, j))] ?? 0);
  const rowY = (i: number): number => plotY + i * cellH + (rowBefore[Math.max(0, Math.min(nrows, i))] ?? 0);

  // Bubble grid: each cell a centred dot, area ∝ magnitude — |value| on a
  // domain crossing zero (corrplot: −0.8 draws as big as +0.8, colour carries the sign),
  // else the value's position in [min,max]. sqrt because area is the perceptually accurate channel.
  // Floored so a real value is never invisible (a vanished dot would read as missing data).
  const bubbles = (hs.cellShape ?? "tile") === "bubble";
  const rMax = Math.min(cellW, cellH) * 0.45;
  const maxAbs = Math.max(Math.abs(min), Math.abs(max), 1e-12);
  const bubbleR = (v: number): number => {
    const frac = min < 0 && max > 0 ? Math.abs(v) / maxAbs : (v - min) / (max - min || 1e-12);
    return Math.max(1.25, rMax * Math.sqrt(Math.max(0, Math.min(1, frac))));
  };
  const cells: HeatCell[] = [];
  for (let i = 0; i < nrows; i++) {
    for (let j = 0; j < ncols; j++) {
      const v = dmatrix[i]![j]!;
      const isNum = Number.isFinite(v);
      const color = colorAt(v);
      const r = bubbles && isNum ? bubbleR(v) : undefined;
      cells.push({
        x: colX(j),
        y: rowY(i),
        w: cellW,
        h: cellH,
        color,
        value: isNum ? v : null,
        row: i,
        col: j,
        label: showValues && isNum ? fmtCell(v) : "",
        // A small bubble's label sits mostly on the page, not the dot — contrast against
        // the page (theme ink) there, against the dot's colour when the dot is big enough.
        labelColor: hs.valueColor ?? (r != null && r < Math.min(cellW, cellH) * 0.35 ? "var(--ink)" : contrast(color)),
        ...(r != null ? { r } : {}),
      });
    }
  }
  // Per-label drag offsets (each column / row label moves independently).
  const colOff = hs.colLabelOffsets ?? {};
  const rowOff = hs.rowLabelOffsets ?? {};
  /**
   * What each label names, carried with it. `colOrder[j]` / `rowOrder[i]` map the drawn
   * position back through the clustering; a collapsed label stands for several source objects
   * and its real name is the annotation value the group shares.
   */
  const colTrackForCollapse = Math.max(0, Math.floor(hs.collapseColsBy ?? 0));
  const rowTrackForCollapse = Math.max(0, Math.floor(hs.collapseRowsBy ?? 0));
  const colIdentity = (j: number): { ids?: NodeId[]; groupValue?: string; trackIndex?: number } => {
    const ci = colOrder[j] ?? j;
    if (collapsedCols) {
      const g = collapsedCols[ci];
      return g
        ? { ids: g.members.map((m) => datasets[m]?.id).filter((x): x is NodeId => !!x), groupValue: g.label, trackIndex: colTrackForCollapse }
        : {};
    }
    const ds = datasets[ci];
    return ds ? { ids: [ds.id] } : {};
  };
  const rowIdentity = (i: number): { ids?: NodeId[]; groupValue?: string; groupColumn?: NodeId } => {
    const ri = rowOrder[i] ?? i;
    if (collapsedRows) {
      const g = collapsedRows[ri];
      const col = (hs.rowTracks ?? [])[rowTrackForCollapse]?.column;
      return g
        ? { ids: g.members.map((m) => rowsIn[m]?.id).filter((x): x is NodeId => !!x), groupValue: g.label, ...(col ? { groupColumn: col } : {}) }
        : {};
    }
    const row = rowsIn[ri];
    return row ? { ids: [row.id] } : {};
  };
  const colLabels = showColLabels ? dispColLabels.map((label, j) => ({ label, x: colX(j) + cellW / 2, ...(colOff[j] ? { dx: colOff[j]!.dx, dy: colOff[j]!.dy } : {}), ...colIdentity(j) })) : [];
  const rowLabels = showRowLabels ? dispRowLabels.map((label, i) => ({ label: rowFit.keep && !rowFit.keep.has(i) ? "" : label, y: rowY(i) + cellH / 2, ...(rowOff[i] ? { dx: rowOff[i]!.dx, dy: rowOff[i]!.dy } : {}), ...rowIdentity(i) })) : [];
  // Attached dendrograms: the row tree grows left of the labels, the col tree up above.
  let dendrograms: HeatmapScene["dendrograms"];
  if (showDendro && (rowRes || colRes)) {
    const dendColor = "#5b616b";
    let rowPath: string | undefined;
    let colPath: string | undefined;
    // Note: each tree starts outside its labels, not at the plot edge.
    //
    // `marginLeft` already reserves `rowDendW + rowLabelW`, so the band left of the cells is
    // [tree][labels][cells] — measuring both inward from `plotX` would draw the tree straight
    // through the labels, with every row and column name on top of the tree as soon as
    // clustering is switched on.
    //
    // The renderer draws row labels ending at `plot.x - 6` and column labels just above
    // `plot.y`, so the tree's baseline has to clear that strip: back off by the label width
    // (or the label height for columns) plus the same gap the margin allowed.
    const rowLabelStrip = (showRowLabels ? rowLabelW + 10 : 4) + rowTrackBand;
    const colLabelStrip = (showColLabels ? colLabelPad : 4) + colTrackBand;
    if (rowRes) {
      const coords = dendrogramCoords(rowRes);
      const maxH = Math.max(1e-9, ...rowRes.nodes.map((n) => n.height));
      const leafPx = (coord: number): number => rowY(Math.floor(coord)) + (coord - Math.floor(coord) + 0.5) * cellH;
      const base = plotX - rowLabelStrip;
      const heightPx = (h: number): number => base - (h / maxH) * (rowDendW - 8);
      const ids = rowRes.nodes.filter((n) => n.left !== null).map((n) => n.id);
      rowPath = dendroBrackets(rowRes, coords, leafPx, heightPx, true, ids);
    }
    if (colRes) {
      const coords = dendrogramCoords(colRes);
      const maxH = Math.max(1e-9, ...colRes.nodes.map((n) => n.height));
      const leafPx = (coord: number): number => colX(Math.floor(coord)) + (coord - Math.floor(coord) + 0.5) * cellW;
      const base = plotY - colLabelStrip;
      const heightPx = (h: number): number => base - (h / maxH) * (colDendH - 8);
      const ids = colRes.nodes.filter((n) => n.left !== null).map((n) => n.id);
      colPath = dendroBrackets(colRes, coords, leafPx, heightPx, false, ids);
    }
    dendrograms = { color: dendColor, ...(rowPath ? { row: rowPath } : {}), ...(colPath ? { col: colPath } : {}) };
  }
  /**
   * The strips, laid out. Each sits in the band reserved for it: row strips march left from the
   * cells, column strips march up from them, in the order the user listed them.
   *
   * Colour: a numeric track shades through its ramp (the same resolver every other ramp in the
   * program uses, so a custom gradient works here too); anything else takes one palette hue per
   * distinct value, in first-seen order, with the user's own colour winning.
   */
  // Always resolved, never left to the renderer's fallback. The builder measures with
  // `trackFontSize` when deciding whether a word fits its band; if the drawing then used the
  // (larger) row/column label font, every word would be bigger than the space that was checked
  // for it, and words would touch both edges of a strip.
  const trackFontResolved = resolveFont(hs.trackFont ?? {}, trackFontSize);
  // Where the key column starts: past the block names and the main colour bar's own slot.
  const keyColX = plotX + plotW + rowBlockW + scaleW + keyClearW + 12;
  const keySlotH = keyTracks.length ? plotH / keyTracks.length : 0;
  const buildTrack = (t: TrackData, offset: number, keySlot: number): HeatTrackScene => {
    const finiteNums = t.nums.filter((v) => Number.isFinite(v));
    const lo = finiteNums.length ? Math.min(...finiteNums) : 0;
    const hi = finiteNums.length ? Math.max(...finiteNums) : 1;
    const paint = ramps.ramp(t.track.ramp ?? "blues", "#f7fbff", "#08306b", false, { lo, hi, values: finiteNums });
    const cats: string[] = [];
    for (const v of t.values) if (v !== "" && !cats.includes(v)) cats.push(v);
    const colourOf = (v: string, i: number): string => {
      if (v === "") return nanColor;
      if (t.track.colors?.[v]) return t.track.colors[v]!;
      if (t.numeric) return paint(hi > lo ? (t.nums[i]! - lo) / (hi - lo) : 0.5).color;
      const hues = options.palette ?? OKABE_ITO;
      return hues[cats.indexOf(v) % hues.length]!;
    };
    const isRow = t.axis === "row";
    // The band grows away from the cells: strip 0 is the one nearest them.
    const near = isRow ? plotX - trackGap - t.size - offset : plotY - trackGap - t.size - offset;
    const blocks = t.values.map((v, i) => ({
      x: isRow ? near : colX(i),
      y: isRow ? rowY(i) : near,
      w: isRow ? t.size : cellW,
      h: isRow ? cellH : t.size,
      color: colourOf(v, i),
      value: v,
    }));
    // Runs of equal values — five "Treated" rows want one word, not five. A run whose box
    // cannot hold its word carries an empty label rather than a clipped one.
    const runs: HeatTrackScene["runs"] = [];
    for (let i = 0; i < t.values.length; ) {
      let j = i;
      while (j + 1 < t.values.length && t.values[j + 1] === t.values[i]) j++;
      const first = blocks[i]!;
      const last = blocks[j]!;
      const x = isRow ? first.x : first.x;
      const y = isRow ? first.y : first.y;
      const w = isRow ? first.w : last.x + last.w - first.x;
      const h = isRow ? last.y + last.h - first.y : first.h;
      const text = t.values[i] ?? "";
      // A word needs its own length along the strip and its height across it, with room to
      // breathe — a glyph touching both edges of its band reads as clipped even when it is not.
      const along = isRow ? h : w;
      const across = isRow ? w : h;
      const fits = text !== "" && along >= measure(text, trackFontSize) + 4 && across >= trackFontSize + 3;
      const off = t.track.labelOffsets?.[text];
      runs.push({ x, y, w, h, label: fits && !t.numeric ? text : "", value: text, ...(off ? { off } : {}) });
      i = j + 1;
    }
    // The key: a small bar in the right-margin column, its caption above it, one slot per
    // numeric strip from the top. Capped at 78px so two strips do not draw two half-height
    // bars that read as one tall gradient.
    let key: HeatTrackScene["key"];
    if (keySlot >= 0) {
      const capH = trackFontSize + 8;
      const slotTop = plotY + keySlot * keySlotH;
      const barH = Math.max(10, Math.min(140, keySlotH - capH - 6));
      key = {
        bar: { x: keyColX, y: slotTop + capH, w: KEY_BAR_W, h: barH },
        stops: ramps.barStops(t.track.ramp ?? "blues", "#f7fbff", "#08306b", false, { lo, hi, values: finiteNums }),
        min: lo,
        max: hi,
        caption: keyCaption(t.track),
        nameX: keyColX,
        nameY: slotTop + trackFontSize,
        ...(t.track.keyOffset ? { off: t.track.keyOffset } : {}),
      };
    }
    return {
      axis: t.axis,
      name: t.track.name ?? "",
      // A row strip is a vertical band, so its name sits under it (out to the right is where
      // the block names and the colour bar already are, so a name there would sit on them)
      // and it reads bottom-to-top: a band is ~16px wide, and two horizontal names centred under
      // their own bands overprint each other. The anchor is the top of the rotated text.
      nameX: isRow ? near + t.size / 2 : near - 6,
      nameY: isRow ? plotY + plotH + 6 : near + t.size / 2,
      ...(isRow ? { nameAngle: -90 } : {}),
      blocks,
      runs,
      numeric: t.numeric,
      ...(t.track.nameOffset ? { nameOff: t.track.nameOffset } : {}),
      ...(key ? { key } : {}),
    };
  };
  const trackScenes: HeatTrackScene[] = [];
  let rowBandOff = 0;
  // `keyTracks` fixes the slot order (rows then columns, numeric only), so a strip's key keeps
  // its slot when a categorical strip is added beside it.
  const keySlotOf = (t: TrackData): number => keyTracks.indexOf(t);
  for (const t of rowTrackData) { trackScenes.push(buildTrack(t, rowBandOff, keySlotOf(t))); rowBandOff += t.size + trackGap; }
  let colBandOff = 0;
  for (const t of colTrackData) { trackScenes.push(buildTrack(t, colBandOff, keySlotOf(t))); colBandOff += t.size + trackGap; }

  // The drawn splits. A rule sits in the middle of the space its split opened (so a "both"
  // split reads as one break, not as a line stuck to one block); a rule-only split sits exactly
  // on the boundary between the two cells.
  const splitScenes: HeatSplitScene[] = [
    ...rowSplits.map((sp) => {
      const y = rowY(sp.at + 1) - sp.gap / 2;
      return { axis: "row" as const, at: sp.at, x1: plotX, y1: y, x2: plotX + plotW, y2: y, lineWidth: sp.lineWidth, color: sp.color, dash: dashArray(sp.dash, sp.lineWidth), gap: sp.gap, label: sp.label, ...(sp.labelOffset ? { labelOff: sp.labelOffset } : {}) };
    }),
    ...colSplits.map((sp) => {
      const x = colX(sp.at + 1) - sp.gap / 2;
      return { axis: "col" as const, at: sp.at, x1: x, y1: plotY, x2: x, y2: plotY + plotH, lineWidth: sp.lineWidth, color: sp.color, dash: dashArray(sp.dash, sp.lineWidth), gap: sp.gap, label: sp.label, ...(sp.labelOffset ? { labelOff: sp.labelOffset } : {}) };
    }),
  ];
  const bar = { x: plotX + plotW + 14 + rowBlockW, y: plotY, w: 14, h: plotH };
  const scaleStops = ramps.barStops(colormap, "#440154", "#fde725", reverse, heatShape);
  const border = { color: hs.cellBorderColor ?? null, width: hs.cellBorderWidth ?? 0 };
  if (ncols === 0 || nrows === 0) warnings.push("Heatmap needs at least one row and one column.");

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { ...emptyAxis, title: xTitle },
    y: { ...emptyAxis, range: [plotY + plotH, plotY], title: yTitle, ...(yTitle ? { titlePos: pad.l + fonts.yAxisTitle.size * TEXT_ASCENT } : {}) },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: [],
    legendLayout: NO_LEGEND,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: xTitle, y: yTitle },
    kind: "heatmap",
    fonts,
    heatmap: { cells, colLabels, rowLabels, min, max, border, showColorbar, bar, scaleStops, ...cbarFitted(colorbarExtras(hs, min, max, bar), cbarFontSize, cbarNumFit), ...(labelFontFit ? { labelFont: labelFontFit } : {}), ...(labelRotation ? { labelRotation } : {}), colLabelLift, ...(dendrograms ? { dendrograms } : {}), ...(splitScenes.length ? { splits: splitScenes } : {}), ...(splitLabelFont ? { splitLabelFont } : {}), ...(trackScenes.length ? { tracks: trackScenes } : {}), ...(trackScenes.length ? { trackFont: trackFontResolved } : {}), ...(rowTrackBand || colTrackBand ? { labelInset: { left: rowTrackBand, top: colTrackBand } } : {}) },
    warnings,
  };
}

/** SVG path for a full circle centred at (cx,cy). */
function corrCirclePath(cx: number, cy: number, r: number): string {
  return `M ${cx - r} ${cy} A ${r} ${r} 0 1 0 ${cx + r} ${cy} A ${r} ${r} 0 1 0 ${cx - r} ${cy} Z`;
}

/** SVG path for a pie wedge from 12 o'clock, sweeping clockwise by `frac` (0–1) of the circle. */
function corrPieWedge(cx: number, cy: number, r: number, frac: number): string {
  const f = Math.max(0, Math.min(1, frac));
  if (f <= 0) return "";
  if (f >= 1) return corrCirclePath(cx, cy, r);
  const a0 = -Math.PI / 2;
  const a1 = a0 + f * 2 * Math.PI;
  const x0 = cx + r * Math.cos(a0);
  const y0 = cy + r * Math.sin(a0);
  const x1 = cx + r * Math.cos(a1);
  const y1 = cy + r * Math.sin(a1);
  const large = f > 0.5 ? 1 : 0;
  return `M ${cx} ${cy} L ${x0} ${y0} A ${r} ${r} 0 ${large} 1 ${x1} ${y1} Z`;
}

/** SVG polygon path for a correlation ellipse (corrplot style): major axis = `radius`,
 *  minor axis shrinks to a line as |r|→1, tilted +45° for r>0 / −45° for r<0 (a circle
 *  at r=0). Sampled as a closed polygon so it renders through the same path pipeline. */
function corrEllipse(cx: number, cy: number, radius: number, r: number): string {
  const a = Math.min(1, Math.abs(r));
  const rx = radius; // major axis
  const ry = radius * (1 - a); // minor axis → 0 (a line) as |r| → 1
  const theta = ((r >= 0 ? -45 : 45) * Math.PI) / 180; // "/" for +, "\" for −
  const ct = Math.cos(theta);
  const st = Math.sin(theta);
  const N = 40;
  let d = "";
  for (let k = 0; k <= N; k++) {
    const t = (k / N) * 2 * Math.PI;
    const ex = rx * Math.cos(t);
    const ey = ry * Math.sin(t);
    const x = cx + ex * ct - ey * st;
    const y = cy + ex * st + ey * ct;
    d += (k === 0 ? "M " : "L ") + x.toFixed(2) + " " + y.toFixed(2) + " ";
  }
  return d + "Z";
}

/**
 * Correlation matrix (kind "corrmatrix"): an N×N grid where each cell is a glyph
 * encoding the pairwise correlation r between two of the table's numeric columns —
 * a pie wedge whose fill-fraction ∝ |r| and hue is blue (r>0) / red (r<0), saturating
 * toward white at r = 0 (also circle / square / number glyphs). Lower-triangular by
 * default, with the r = 1 self-correlations on the diagonal, an optional pie-glyph
 * scale legend, and optional dashed domain-block dividers. Pure + reactive: the matrix
 * recomputes from the columns whenever the data changes.
 */
function buildCorrMatrixScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const datasets = visibleDatasets(table, plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);

  const cfg = plot.corrmatrix ?? {};
  const method = cfg.method ?? "pearson";
  const triangle = cfg.triangle ?? "lower";
  const glyph = cfg.glyph ?? "pie";
  // The +/− diverging colours follow the figure's palette (so changing the palette recolours
  // the matrix) unless the user pins an explicit Positive/Negative colour. The
  // palette's first two hues are the endpoints (Okabe-Ito → blue +, orange −: a CVD-safe pair).
  const palette = options.palette ?? OKABE_ITO;
  const posColor = cfg.positiveColor ?? palette[0] ?? "#2166ac";
  const negColor = cfg.negativeColor ?? palette[1] ?? palette[0] ?? "#b2182b";
  const showDiagonal = cfg.showDiagonal ?? true;
  const showValues = cfg.showValues ?? false;
  const decimals = Math.max(0, Math.min(4, cfg.valueDecimals ?? 2));
  const showRowLabels = cfg.showRowLabels ?? true;
  const showColLabels = cfg.showColLabels ?? true;
  const labelRotation = cfg.labelRotation ?? 45;
  const showLegend = cfg.showLegend ?? true;
  // Symbol size, in the cells and in the key. Both are multipliers on the size each already
  // takes from the cell, so 1 draws the symbol at the cell's own size.
  const glyphScale = Math.max(0.2, Math.min(1.2, cfg.glyphScale ?? 1));
  const legendGlyphScale = Math.max(0.4, Math.min(2, cfg.legendGlyphScale ?? 1));
  const borderColor = cfg.cellBorderColor === "" || cfg.cellBorderColor === "none" ? null : cfg.cellBorderColor ?? "#e6e6e6";

  const n = datasets.length;
  const labels = datasets.map((d) => d.name);
  const cols: number[][] = datasets.map((ds) => table.rows.map((r) => rowDatasetMean(r, ds)));
  const R = correlationMatrix(cols, method);
  if (n < 2) warnings.push("Correlation matrix needs at least two numeric columns.");

  const ownLabelFont = cfg.labelFont ? resolveFont(cfg.labelFont, Math.min(DEFAULTS.tickFont, 12)) : undefined;
  const labelSize = ownLabelFont?.size ?? Math.min(fonts.tick.size, 12);
  // The variable names' style: this chart's own label font over the chart-wide tick font, field by field.
  // Drawing with the tick font plus only the size would make the label font's Bold / Colour / Family / Italic
  // dead controls. A plain swap would drop the family or bold a graph inherits from the tick font when it sets
  // only a label size - hence the merge. Written only when the chart has a label font of its own.
  // Guard: corrmatrix-label-font.test.tsx.
  const labelFont = cfg.labelFont ? { ...resolveFont(mergeFontSpec(plot.fonts?.tick, cfg.labelFont), labelSize), size: labelSize } : undefined;

  // Diverging fill for r: white at 0 → posColor at +1 / negColor at −1.
  const corrColor = (r: number): string => mix("#ffffff", r >= 0 ? posColor : negColor, Math.min(1, Math.abs(r)));
  const contrast = (hex: string): string => contrastInk(hex);

  // --- margins ---
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const rowLabelW = showRowLabels ? Math.max(0, ...labels.map((t) => measure(t, labelSize))) : 0;
  const maxColLabelW = showColLabels ? Math.max(0, ...labels.map((t) => measure(t, labelSize))) : 0;
  const rot = Math.abs(labelRotation) % 180;
  // Clearance between the column labels and the top row of glyphs (the figure draws the
  // labels at grid.y − colLabelGap). Font-scaled so labels don't touch the top cells.
  const colLabelGap = Math.max(7, labelSize * 0.6);
  // A rotated column label is anchored at its end, so it hangs down-left from its pivot by
  // width × sin(angle). Lift the pivot by exactly that, or the tail drops into the first row of
  // cells and lands on that row's label.
  const colLabelDrop = rot === 0 ? 0 : Math.ceil(maxColLabelW * Math.sin((Math.min(rot, 90) * Math.PI) / 180));
  const colLabelLift = colLabelGap + colLabelDrop;
  const colLabelPad = showColLabels
    ? rot === 0
      ? labelSize + colLabelGap + 8
      : colLabelDrop + labelSize * 0.7 + colLabelGap + 8
    : 4;
  /**
   * The reserved strip for the key: at least 96px; a scaled symbol has to widen it or it
   * lands under its own label. Sized from the symbol cap (9px x scale) rather than the symbol
   * itself, because the symbol is derived from `cell`, and `cell` is derived from what is left
   * after this reservation — reading it here would be circular.
   */
  const legendW = showLegend ? Math.max(96, 36 + 18 * legendGlyphScale + measure("-0.75", Math.min(fonts.tick.size, 12))) : 0;
  // The figure draws a row name ending 6px left of the grid, so +10 would leave only 4px to the figure edge. A
  // measured width a few px short of the rendered one (a font the measurer does not know) can put a name
  // within a fraction of a pixel of the edge. ROW_LABEL_EDGE keeps the widest name clear of it.
  const ROW_LABEL_EDGE = 8;
  const marginLeft = rowLabelW + 10 + (showRowLabels ? ROW_LABEL_EDGE : 0) + pad.l;
  const marginTop = DEFAULTS.marginTop + topPad + colLabelPad;
  const marginRight = DEFAULTS.marginRight + legendW + pad.r;
  const marginBottom = 10 + pad.b;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, marginTop, marginBottom);
  const availW = Math.max(1, width - marginLeft - marginRight);
  const availH = Math.max(1, height - marginTop - marginBottom);
  const cell = n > 0 ? Math.max(6, Math.min(availW, availH) / n) : Math.min(availW, availH);
  const gridSize = cell * n;
  const plotX = marginLeft;
  const plotY = marginTop;

  // --- optional domain-block dividers + faint tints on the diagonal blocks ---
  const blockSizes = (cfg.blockSizes ?? []).filter((s) => s > 0);
  let blockDividers: CorrMatrixScene["blockDividers"];
  let blockTints: CorrMatrixScene["blockTints"];
  if (blockSizes.length && blockSizes.reduce((a, b) => a + b, 0) <= n) {
    const bounds: number[] = [];
    let acc = 0;
    for (const s of blockSizes) {
      acc += s;
      bounds.push(acc);
    }
    const dividers: NonNullable<CorrMatrixScene["blockDividers"]> = [];
    const tints: NonNullable<CorrMatrixScene["blockTints"]> = [];
    for (const b of bounds) {
      if (b <= 0 || b >= n) continue;
      const p = plotX + b * cell;
      const q = plotY + b * cell;
      dividers.push({ x1: p, y1: plotY, x2: p, y2: plotY + gridSize });
      dividers.push({ x1: plotX, y1: q, x2: plotX + gridSize, y2: q });
    }
    let start = 0;
    for (const s of blockSizes) {
      tints.push({ x: plotX + start * cell, y: plotY + start * cell, w: s * cell, h: s * cell, color: "#000000" });
      start += s;
    }
    blockDividers = dividers;
    blockTints = tints;
  }

  // --- cells ---
  const glyphR = cell * 0.42 * glyphScale;
  const cells: CorrCell[] = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const isDiag = i === j;
      const inTriangle = triangle === "full" || (triangle === "lower" ? i >= j : i <= j);
      if (!inTriangle || (isDiag && !showDiagonal)) continue;
      const cx = plotX + (j + 0.5) * cell;
      const cy = plotY + (i + 0.5) * cell;
      const r = R[i]![j];
      let glyphPath = "";
      let outlinePath = "";
      let color = "#ffffff";
      // A per-cell colour override (click a glyph to recolour it) wins over the r-scale.
      const cellOverride = cfg.cellColors?.[`${i}:${j}`];
      if (r != null) {
        color = cellOverride ?? corrColor(r);
        const a = Math.min(1, Math.abs(r));
        if (glyph === "pie") {
          outlinePath = corrCirclePath(cx, cy, glyphR);
          glyphPath = corrPieWedge(cx, cy, glyphR, a);
        } else if (glyph === "circle") {
          glyphPath = corrCirclePath(cx, cy, Math.max(0.5, glyphR * Math.sqrt(a)));
        } else if (glyph === "square") {
          glyphPath = `M ${cx - glyphR} ${cy - glyphR} H ${cx + glyphR} V ${cy + glyphR} H ${cx - glyphR} Z`;
        } else if (glyph === "ellipse") {
          glyphPath = corrEllipse(cx, cy, glyphR, r);
        }
      }
      const showNum = (showValues || glyph === "number") && r != null;
      cells.push({
        x: plotX + j * cell,
        y: plotY + i * cell,
        w: cell,
        h: cell,
        row: i,
        col: j,
        r: r ?? null,
        color,
        glyphPath,
        outlinePath,
        label: showNum ? Number(r!.toFixed(decimals)).toString() : "",
        labelColor: glyph === "number" ? "#222" : contrast(color),
        labelX: cx,
        labelY: cy,
      });
    }
  }

  // Per-label drag offsets (each variable label moves independently, mirrors the heatmap).
  const colOff = cfg.colLabelOffsets ?? {};
  const rowOff = cfg.rowLabelOffsets ?? {};
  const colLabels = showColLabels ? labels.map((label, j) => ({ label, x: plotX + (j + 0.5) * cell, angle: labelRotation, ...(colOff[j] ? { dx: colOff[j]!.dx, dy: colOff[j]!.dy } : {}) })) : [];
  const rowLabels = showRowLabels ? labels.map((label, i) => ({ label, y: plotY + (i + 0.5) * cell, ...(rowOff[i] ? { dx: rowOff[i]!.dx, dy: rowOff[i]!.dy } : {}) })) : [];

  // --- correlation-scale legend (pie glyphs +1 … −1) in the reserved right strip ---
  let scaleLegend: CorrMatrixScene["scaleLegend"];
  if (showLegend) {
    const values = [1, 0.75, 0.5, 0.25, -0.25, -0.5, -0.75, -1];
    const lr = Math.min(9, Math.max(5, cell * 0.42)) * legendGlyphScale;
    const step = lr * 2 + 9;
    const gx = plotX + gridSize + 30 + lr;
    const blockH = values.length * step;
    const y0 = Math.max(plotY + lr + 14, plotY + (gridSize - blockH) / 2 + lr);
    const items: CorrLegendItem[] = values.map((v, k) => {
      const cy = y0 + k * step;
      const color = corrColor(v);
      return {
        glyphPath: corrPieWedge(gx, cy, lr, Math.abs(v)),
        outlinePath: corrCirclePath(gx, cy, lr),
        color,
        label: v > 0 ? `+${v}` : `${v}`,
        labelX: gx + lr + 6,
        labelY: cy + lr * 0.5,
      };
    });
    scaleLegend = { title: "Correlation", titleX: gx - lr, titleY: y0 - lr - 6, items, ...(cfg.legendOffset ? { offset: cfg.legendOffset } : {}) };
  }

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + gridSize], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: gridSize, height: gridSize },
    x: { ...emptyAxis },
    y: { ...emptyAxis, range: [plotY + gridSize, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: [],
    legendLayout: NO_LEGEND,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: n * cell, height: n * cell }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "corrmatrix",
    fonts,
    corrmatrix: {
      cells,
      colLabels,
      rowLabels,
      grid: { x: plotX, y: plotY, w: gridSize, h: gridSize },
      cell,
      labelSize,
      colLabelLift,
      border: borderColor,
      ...(blockDividers ? { blockDividers } : {}),
      ...(blockTints ? { blockTints } : {}),
      ...(scaleLegend ? { scaleLegend } : {}),
      ...(labelFont ? { labelFont } : {}),
    },
    warnings,
  };
}

/**
 * Ridgeline / joyplot (kind "ridgeline"): one translucent Gaussian-KDE density
 * trace per dataset, stacked on evenly-spaced baselines down the plot and
 * overlapping the row above (overlap > 1 → the classic joyplot look). The value
 * axis is a continuous X; dataset names label the Y baselines. Each trace is a
 * selectable series carrying its filled density (`areaPath`) + a thin top stroke
 * (`linePath`) — the renderer's line/area path is reused, so kind "ridgeline" is
 * a `lineKind`. Rows are emitted top→bottom = back→front so each overlaps the
 * one above. Reuses the violin KDE machinery (Silverman bandwidth × multiplier,
 * sampled across each dataset's own value range — no ballooning past the data).
 */
function buildRidgelineScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  const datasets = visibleDatasets(table, plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);

  const cfg = plot.ridgeline ?? {};
  // Profile rows default to no overlap (1.0): they are values, and letting one row's lobe
  // cross another's misreads as that row's data, so each row keeps a flat strip of its own.
  // The joyplot default 1.5 stands for densities; an explicit overlap always wins.
  const overlap = Math.max(0.2, Math.min(4, cfg.overlap ?? ((cfg.source ?? "density") === "profile" ? 1 : 1.5)));
  const bwScale = Math.max(0.1, Math.min(5, cfg.bandwidth ?? 1));
  const fillOpacity = Math.max(0, Math.min(1, cfg.fillOpacity ?? 0.55));

  const pooled = datasets.map((ds) => poolDatasetValues(table, ds));

  // ── "profile" source: each row = the dataset's value over the table's X column ──
  // (row height = |value|, negatives fold upward — level bands give them the negative
  // colours). The classic joyplot ("density") stays the default and is untouched.
  const xColP = xColumn(table);
  const profileXs = xColP ? table.rows.map((r) => toNumber(r.cells[xColP.id])) : [];
  let profile = (cfg.source ?? "density") === "profile";
  if (profile && profileXs.filter((v) => Number.isFinite(v)).length < 2) {
    warnings.push("Values-over-X rows need an X column with numeric values — drawing densities instead (Chart type ▸ Rows show).");
    profile = false;
  }
  /** Per dataset: its (x, value) pairs, replicates averaged, sorted by x. */
  const profilePts: { x: number; v: number }[][] = profile
    ? datasets.map((ds) =>
        table.rows
          .map((row, ri) => {
            const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
            return { x: profileXs[ri]!, v: vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN };
          })
          .filter((p) => Number.isFinite(p.x) && Number.isFinite(p.v))
          .sort((p, q) => p.x - q.x),
      )
    : [];
  /** Shared height scale across every row, so rows stay comparable. */
  const maxAbs = profile ? Math.max(1e-9, ...profilePts.flat().map((p) => Math.abs(p.v))) : 0;

  // ── the banded fold's origin, per row (BiomeHorizon's convention): deviations from each
  // row's own median by default, so raw abundances work without pre-computed z-scores;
  // "mean" and "zero" (values as entered — right for z-scores) are the alternatives. Only
  // the banded fold re-centres: the plain profile lobe stays |value| (see RidgelineStyle).
  const originMode = cfg.origin ?? "median";
  const originD: number[] = profile
    ? profilePts.map((pts) => {
        if (originMode === "zero" || pts.length === 0) return 0;
        const vs = pts.map((p) => p.v).sort((a, b) => a - b);
        return originMode === "mean" ? vs.reduce((a, b) => a + b, 0) / vs.length : quantileSorted(vs, 0.5);
      })
    : [];
  /** Shared deviation scale for the banded fold (max |v − origin| across all rows). */
  const maxDev = profile
    ? Math.max(1e-9, ...profilePts.flatMap((pts, i) => pts.map((p) => Math.abs(p.v - originD[i]!))))
    : 0;

  // ── nested level bands: the row's height sliced into N equal levels, each one
  // shade deeper — light tint at level 1 up to the ramp anchor verbatim at the top level
  // (so a chosen hue reaches the ink). Bands replace the plain fill and the spectrum.
  const bandsN = Math.max(0, Math.min(8, Math.round(cfg.bands ?? 0)));
  const bandsOn = bandsN > 0;
  const bandPos = cfg.bandPosColor ?? "#2166ac";
  const bandNeg = cfg.bandNegColor ?? "#b2182b";
  const bandColor = (sign: 1 | -1, k: number): string => {
    const anchor = sign > 0 ? bandPos : bandNeg;
    return k >= bandsN ? anchor : mix("#ffffff", anchor, 0.35 + (0.65 * k) / bandsN);
  };
  const hasNeg = profile && profilePts.some((pts, i) => pts.some((p) => p.v - originD[i]! < 0));

  const allValues = profile
    ? profilePts.flat().map((p) => p.x)
    : pooled.flat().filter((v) => Number.isFinite(v));

  // Value axis = X (continuous). Honour the X Format-Axes spec (scale/range/format).
  const xSpec: AxisSpec = plot.xAxis ?? {};
  const xFmt = tickFormat(xSpec);
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const xRev = xSpec.reversed ?? false;
  let xType: ScaleType = options.xScale ?? xSpec.scale ?? plot.xScale ?? "linear";
  if (isLog(xType) && !allValues.every((v) => v > 0)) {
    xType = "linear";
    warnings.push("Log axis needs all-positive values — using linear.");
  }
  const gridDensity = plot.grid?.density ?? 6;

  const autoXDom = allValues.length
    ? buildScale(xType, extent(isLog(xType) ? allValues.filter((v) => v > 0) : allValues), [0, 1], gridDensity, false, xFmt).domain
    : ([0, 1] as [number, number]);
  const xData = options.xDomain ?? applyRange(xSpec, autoXDom);
  const manualX = options.xDomain != null || xSpec.min != null || xSpec.max != null;

  // Margins: dataset names sit at the left as Y baseline (row) labels. The X axis
  // is the value axis (each dataset's pooled measurements), so its title follows
  // the measured quantity — the lone dataset's name, or a generic "Value".
  const catLabelW = Math.max(0, ...datasets.map((ds) => measure(ds.name, fonts.tick.size)), turnedYLabelsReach(datasets.map((ds) => ds.name), fonts.tick.size, measure, plot.yAxis?.tickRotation));
  // Profile rows share the X column's axis (Day, Time…); density rows pool values along X.
  const xLabel = profile ? xColP?.name ?? "X" : datasets.length === 1 ? datasets[0]!.name : "Value";
  const yLabel = plot.yAxis?.title ?? "";
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (yLabel ? textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6) : 4) + pad.l;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  // With bands on, the legend is the band key (levels, deepest first, − side after +) and
  // shows by default — a banded figure without its key is unreadable. The rows themselves
  // stay named on the Y axis. A band row is a fill block opening the
  // Chart type section (the volcano-zone rule: a level is a range, not a clickable object).
  const fmtLvl = (v: number): string => String(Number(v.toFixed(Math.abs(v) >= 10 ? 0 : 2)));
  const bandEntries: LegendEntry[] = [];
  if (bandsOn) {
    const stepV = profile ? maxDev / bandsN : NaN;
    for (let k = bandsN; k >= 1; k -= 1) {
      bandEntries.push({
        label: profile ? `+${fmtLvl(k * stepV)}` : `${Math.round((100 * k) / bandsN)}%`,
        color: bandColor(1, k),
        swatch: "bar",
        select: { as: "section", id: "Chart type" },
      });
    }
    if (hasNeg) {
      for (let k = 1; k <= bandsN; k += 1) {
        bandEntries.push({ label: `−${fmtLvl(k * stepV)}`, color: bandColor(-1, k), swatch: "bar", select: { as: "section", id: "Chart type" } });
      }
    }
  }
  const leg = bandsOn
    ? resolveLegend({ ...plot, legend: { ...plot.legend, show: plot.legend?.show ?? true } }, bandEntries, measure, fonts.legend.size, width)
    : groupLegend(plot, datasets, palette, measure, fonts.legend.size, width);
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale(xType, xData, xRev ? [plotW, 0] : [0, plotW], gridDensity, manualX, xFmt, xSpacing);
  const xDomainOut: [number, number] = xRev ? [xb.domain[1], xb.domain[0]] : xb.domain;
  // The natural "home" domain — the rest state ignoring any pan/zoom window. `auto` must be
  // this and not an echo of the current domain: the renderer soft-locks back to it and reads it
  // to know whether the chart is zoomed. Echoing the window would make both reads meaningless — the
  // detent could never fire and drag-to-pan could never wake up.
  const homeX: [number, number] = options.xDomain != null
    ? buildScale(xType, applyRange(xSpec, autoXDom), [0, 1], gridDensity, xSpec.min != null || xSpec.max != null, xFmt, xSpacing).domain
    : xb.domain;
  const px = (v: number): number => plotX + xb.scale(v);

  const n = datasets.length;
  // Baselines run top→bottom. step·(n−1+overlap) = plotH pins the bottom baseline to
  // plotY+plotH and leaves `rowHeight` of headroom above the top row for its peak.
  const step = n > 1 ? plotH / (n - 1 + overlap) : 0;
  const rowHeight = n > 1 ? step * overlap : plotH * 0.85;
  const baselineAt = (i: number): number => (n > 1 ? plotY + rowHeight + step * i : plotY + plotH);

  // Spectrum fill: one gradient anchored to the X axis, shared by every ridge. `px()` maps the
  // numeric domain endpoints to plot pixels, so the low colour sits at the axis minimum and the
  // high colour at the maximum — correct even when the axis is reversed.
  // Level bands replace it — both at once would paint two fills on one lobe. A warning says so.
  let spectrum = cfg.spectrum ?? false;
  if (bandsOn && spectrum) {
    warnings.push("Level bands replace the spectrum fill — turn the bands off (Chart type ▸ Level bands: 0) to use the spectrum.");
    spectrum = false;
  }
  // A perceptual colormap (default coolwarm) → evenly-spaced gradient stops, so the spectrum
  // stays vivid across the whole axis instead of passing through a muddy 2-colour midpoint.
  // Through the resolver, not COLORMAPS directly, so a custom gradient can
  // reach it. "coolwarm" is the fallback for a ramp with no colours of its own.
  const spectrumStops = ramps.stops((cfg.spectrumMap ?? "coolwarm") as GradRamp, "coolwarm", {
    midpointValue: cfg.spectrumMidpoint, gamma: cfg.spectrumGamma, steps: cfg.spectrumSteps,
    space: cfg.spectrumSpace, lo: Math.min(xb.domain[0], xb.domain[1]), hi: Math.max(xb.domain[0], xb.domain[1]),
  });
  const gradX1 = px(xb.domain[0]);
  const gradX2 = px(xb.domain[1]);

  const STEPS = 120;
  // Every ridge's density is evaluated over the full value axis (all groups' shared extent), not
  // just its own min→max — so each ridge spans the whole width with near-zero tails to both edges,
  // the way a joyplot reads (and the shape the axis-wide spectrum needs to show its full sweep).
  const domLo = Math.min(xb.domain[0], xb.domain[1]);
  const domHi = Math.max(xb.domain[0], xb.domain[1]);
  // Broken x-axis: the visible sub-intervals between the compressed cuts come straight from the
  // scale (`buildScale` already cleaned/merged the breaks), so each ridge draws a separate closed
  // lobe per interval and the fill stops at the break instead of bridging the gap. No breaks →
  // one full-domain segment.
  const visSegs: Array<[number, number]> = (xb.segments ?? [{ from: domLo, to: domHi }]).map(
    (s) => [Math.min(s.from, s.to), Math.max(s.from, s.to)] as [number, number],
  );
  /**
   * Horizon bands over one segment's height samples (normalised, signed, |h| ≤ 1) — the
   * BiomeHorizon construction (blekhmanlab/biomehorizon, MIT-licensed; this is an
   * independent re-implementation from their documented description, no code reused — the
   * horizon-plot technique itself long predates it: Saito et al. 2005, Heer et al. 2009).
   * The construction: the row
   * strip is one band tall, and every level's slice is cut and collapsed back onto the
   * baseline, then overlaid dark-over-light. Slice k's height at x is
   * clamp(|h|·N − (k−1), 0, 1) of the strip wherever the sign matches (negatives mirror
   * upward), zero elsewhere — so a peak crossing all levels shows as nested lobes whose
   * every visible edge is a piece of the curve, never a flat shelf.
   * Not slices stacked at their level lines with clamped-flat tops — that renders as
   * broken horizontal slabs.
   */
  const bandPathsFor = (
    xsPx: number[],
    hs: number[], // signed heights, |h| ≤ 1
    baseY: number,
    out: { path: string; color: string }[],
  ): void => {
    const y0 = baseY.toFixed(2);
    for (const sign of [1, -1] as const) {
      if (!hs.some((h) => (sign > 0 ? h > 0 : h < 0))) continue;
      for (let k = 1; k <= bandsN; k += 1) {
        if (!hs.some((h) => (sign > 0 ? h > 0 : h < 0) && Math.abs(h) * bandsN > k - 1)) continue;
        const tops = xsPx.map((x, j) => {
          const on = sign > 0 ? hs[j]! > 0 : hs[j]! < 0;
          const t = on ? Math.min(Math.max(Math.abs(hs[j]!) * bandsN - (k - 1), 0), 1) : 0;
          return `${x.toFixed(2)},${(baseY - t * rowHeight).toFixed(2)}`;
        });
        out.push({
          path: `M${xsPx[0]!.toFixed(2)},${y0}L${tops.join("L")}L${xsPx[xsPx.length - 1]!.toFixed(2)},${y0}Z`,
          color: bandColor(sign, k),
        });
      }
    }
  };

  const series: SeriesScene[] = datasets.map((ds, i) => {
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(i, palette);
    const lineWidth = style?.lineWidth ?? 1.25;
    const baseY = baselineAt(i);
    const vals = pooled[i]!.filter((v) => Number.isFinite(v) && (!isLog(xType) || v > 0));
    let areaPath = "";
    let linePath = "";
    const levelBands: { path: string; color: string }[] = [];
    if (profile) {
      // ── profile row: the dataset's value over the X column, |v| folded upward ──
      const pts = profilePts[i]!;
      if (pts.length >= 2) {
        for (const [a, b] of visSegs) {
          const seg = pts.filter((p) => p.x >= a && p.x <= b);
          if (seg.length < 2) continue;
          const xsPx = seg.map((p) => px(p.x));
          // Banded fold: signed deviations from this row's origin, |h| ≤ 1 on the shared scale.
          const hs = seg.map((p) => (p.v - originD[i]!) / maxDev);
          if (bandsOn) {
            // A horizon strip is one band tall — an outer |v| curve would tower N× above
            // it, so the overlaid slices are the drawing (their edges are the curve).
            bandPathsFor(xsPx, hs, baseY, levelBands);
          } else {
            const top = seg.map((p, j) => `${xsPx[j]!.toFixed(2)},${(baseY - (Math.abs(p.v) / maxAbs) * rowHeight).toFixed(2)}`);
            linePath += (linePath ? " " : "") + `M${top.join("L")}`;
            areaPath += (areaPath ? " " : "") + `M${xsPx[0]!.toFixed(2)},${baseY.toFixed(2)}L${top.join("L")}L${xsPx[xsPx.length - 1]!.toFixed(2)},${baseY.toFixed(2)}Z`;
          }
        }
        if (!bandsOn && pts.some((p) => p.v < 0)) {
          warnings.push(`"${ds.name}" has negative values — they fold upward; turn on Level bands to colour them by sign.`);
        }
      } else {
        warnings.push(`"${ds.name}" needs at least 2 (x, value) pairs.`);
      }
    } else if (vals.length >= 2 && Math.max(...vals) > Math.min(...vals)) {
      const base = silvermanBandwidth(vals);
      const bw = bwScale !== 1 && base > 0 ? base * bwScale : undefined;
      // Sample each visible segment; keep one global maxD across the whole ridge so the height
      // scale is consistent, then draw a separate closed lobe (area) + line per segment.
      const spanTot = Math.max(1e-9, domHi - domLo);
      const segSamples = visSegs.map(([a, b]) => {
        const m = Math.max(2, Math.round(STEPS * ((b - a) / spanTot)));
        const xs = Array.from({ length: m + 1 }, (_, k) => a + ((b - a) * k) / m);
        return { a, b, xs, dens: gaussianKde(vals, xs, bw) };
      });
      const maxD = Math.max(...segSamples.flatMap((s) => s.dens));
      if (maxD > 0) {
        const areas: string[] = [];
        const lines: string[] = [];
        for (const { a, b, xs, dens } of segSamples) {
          if (bandsOn) {
            // Density horizon: the same overlaid slicing of the normalised height (never
            // negative) — and no outer curve, for the same one-band-strip reason as above.
            bandPathsFor(xs.map((v) => px(v)), dens.map((d) => d / maxD), baseY, levelBands);
          } else {
            const pts = xs.map((v, k) => `${px(v).toFixed(2)},${(baseY - (dens[k]! / maxD) * rowHeight).toFixed(2)}`);
            lines.push(`M${pts.join("L")}`);
            areas.push(`M${px(a).toFixed(2)},${baseY.toFixed(2)}L${pts.join("L")}L${px(b).toFixed(2)},${baseY.toFixed(2)}Z`);
          }
        }
        linePath = lines.join(" ");
        areaPath = areas.join(" ");
      }
    } else if (vals.length < 2) {
      warnings.push(`"${ds.name}" needs at least 2 values for a density.`);
    }
    return {
      id: ds.id,
      name: ds.name,
      color,
      linePath,
      areaPath,
      symbol: "circle",
      symbolSize: 0,
      ...resolveSymbol(style, color),
      borderWidth: style?.borderWidth ?? 1.5,
      lineWidth,
      dash: dashArray(style?.lineDash ?? "solid", lineWidth),
      errorCaps: false,
      errorDir: "both",
      ...seriesExtras(style, color, lineWidth, 0, fillOpacity),
      /**
       * Note: after the spread, on purpose. `seriesExtras` forces `fillOpacity: 1` whenever the
       * series uses a two-tone fill — and two-tone is the house preset's default, so without
       * this the Ridgeline panel's own "Fill opacity" control would do nothing on essentially
       * every ridgeline, and the translucency the chart type depends on (rows reading through
       * the row above) would be lost with it.
       *
       * The kind-level setting has to beat that generic rule. A per-series override still
       * wins over both, which is the same precedence every other field here follows.
       */
      fillOpacity: style?.fillOpacity ?? fillOpacity,
      // Spectrum is a global fill mode: when on, every ridge shares the one axis-anchored
      // gradient, overriding the resolved solid / two-tone fill (and any per-series colour) —
      // that shared spectrum is the whole point. The per-series colour still tints the outline.
      ...(spectrum ? { fillSpec: { type: "axisGradient" as const, stops: spectrumStops, x1: gradX1, x2: gradX2 } } : {}),
      ...(levelBands.length ? { levelBands } : {}),
      // With bands on, the row outline goes neutral: ten palette-coloured outlines fighting
      // one two-hue ramp read as ten extra series. A per-series
      // line colour still wins — diverging is the deliberate act.
      ...(bandsOn ? { lineColor: style?.lineColor ?? "#8b8792" } : {}),
      marks: [],
    };
  });

  if (n === 0) warnings.push("Ridgeline needs at least one dataset.");

  const xAxis: AxisScene = {
    type: xType,
    domain: xDomainOut,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, fonts.tick.size),
    title: xSpec.title ?? xLabel,
    // Draw the break glyph(s) at each compressed cut; without them the ridgeline's
    // split x-axis would show no marker at all.
    ...(xb.breakMarks?.length ? { breakMarks: xb.breakMarks.map((p) => plotX + p), breakStyle: xSpec.breakStyle ?? "slash", segments: (xb.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotX + xb.scale(s.from), p1: plotX + xb.scale(s.to) })) } : {}),
    ...axisLine(xSpec),
  };
  // Y is a band axis: one labelled tick per dataset at its baseline (the row name).
  const yAxis: AxisScene = {
    type: "linear",
    domain: [0, Math.max(1, n)],
    range: [plotY + plotH, plotY],
    band: true,
    ticks: datasets.map((ds, i) => ({ value: i, pos: baselineAt(i), label: ds.name, minor: false })),
    title: yLabel,
    ...axisLine(plot.yAxis),
  };

  const mapXann = (v: number): number | undefined =>
    Number.isFinite(v) && (!isLog(xType) || v > 0) ? plotX + xb.scale(v) : undefined;
  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: mapXann, y: () => undefined, bracketX: mapXann },
    undefined,
    warnings,
  );

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis,
    y: yAxis,
    auto: { x: homeX, y: [0, Math.max(1, n)] },
    // Ridgeline pools each dataset's measurements along X, so the value spec here is
    // `plot.xAxis` and the override key is `xDomain` — the opposite of every other value-on-X
    // chart in this file. Y stacks the ridges; it has no numeric domain.
    zoomable: [{ visual: "x", key: "x" }],
    series,
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: xLabel, y: yLabel },
    kind: "ridgeline",
    fonts,
    warnings,
  };
}

/**
 * Lollipop / dumbbell (kind "lollipop"): one category row per table row. A single
 * dataset draws a lollipop — a stem from the baseline/index value to a value dot,
 * a bold value label, and a green Δ% (vs baseline) at the dot. Two+ datasets draw
 * a dumbbell — a dot per dataset joined by the stem, with Δ% first→last. Default
 * orientation is horizontal (value on X, categories down Y). Per-dataset means
 * (replicate mean or summary mean) supply the values (as the radar's `valAt` does).
 */
function buildLollipopScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a lollipop / dumbbell chart", warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const datasets = visibleDatasets(table, plot);
  const xCol = xColumn(table);
  const rows = table.rows;
  const n = rows.length;
  const m = datasets.length;
  const horiz = (plot.barOrientation ?? "horizontal") === "horizontal";

  const cfg = plot.lollipop ?? {};
  const dotSize = Math.max(1, cfg.dotSize ?? 5);
  // Fixed dot→label gap (mirrors PlotFigure's DOT_LABEL_GAP). Deliberately not tied to
  // dotSize: the value / Δ% labels — and the right-margin they reserve — must not shift
  // when the "Dot size" slider moves, or the slider silently reflows every label.
  const LABEL_GAP = 9;
  const stemWidth = Math.max(0.5, cfg.stemWidth ?? 2);
  const showValues = cfg.showValues ?? true;
  const showDelta = cfg.showDelta ?? true;
  // Stem colour linked to the data-point colour (each stem follows its own dot);
  // otherwise the stem is independent (its own cfg.stemColor / the neutral default).
  const stemLinked = cfg.stemLinkColor ?? false;
  const dumbbell = m >= 2;
  const baseVal = cfg.baseline ?? 0;
  // Second value axis: a series on "y2" scales to its own axis - down the right
  // on a vertical lollipop, along the top on a horizontal one, as the bar chart. One second axis only.
  const y2Ids = new Set<NodeId>();
  for (const ds of datasets) {
    const axis = plot.seriesStyles?.[ds.id]?.axis;
    if (axis === "y2") y2Ids.add(ds.id);
    else if (axis === "y3") warnings.push(`“${ds.name}” asks for a third value axis (Y3), but a lollipop chart draws at most one second axis — it is plotted on the main axis.`);
  }
  const onY2 = (di: number): boolean => y2Ids.has(datasets[di]!.id);
  // With every series on Y2 the main axis keeps them too (nothing else to fit) - the box builder's rule.
  const onLeft = (di: number): boolean => y2Ids.size === 0 || y2Ids.size === m || !onY2(di);

  const valAt = (ds: Dataset, row: Row): number => {
    if (isSummaryDataset(ds)) return toNumber(row.cells[ds.replicates[0]!]);
    const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
  };
  // Mean±error whisker on the dot — off unless chosen (default "none": a whisker is unusual on
  // this kind and can crowd the dots). The type is a series property; new
  // wizard lollipops stamp it at creation, and the Inspector's errDefault matches ("none" here).
  const errType = (ds: Dataset): ErrorBarType => resolveErrorType(ds, plot.seriesStyles?.[ds.id]?.errorBars ?? "none");
  const errAt = (ds: Dataset, row: Row): ErrorPoint | null => {
    const type = errType(ds);
    if (type === "none") return null;
    if (isSummaryDataset(ds)) return summaryPointForRow(ds, row, type);
    const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
    return errorPoint(summarize(vals), type, ERROR_CONF);
  };
  for (const ds of datasets) warnUndrawableError(ds, errType(ds), isSummaryDataset(ds), warnings);
  const rowErr = rows.map((row) => datasets.map((ds) => errAt(ds, row)));
  // The dot sits at its interval's own centre when a whisker is shown — IQR centres on the
  // median, geometric SD on the geometric mean — so the dot can never fall outside its own
  // whisker on skewed data. With no whisker (the default) it is the arithmetic
  // mean; SD/SEM/CI whiskers centre on the mean too, as do summary entries whose lead cell is
  // the centre, so only a raw-replicate IQR / geometric-SD lollipop has its dot off the mean.
  const rowVals = rows.map((row, i) => datasets.map((ds, di) => {
    const ep = rowErr[i]![di];
    return ep && ep.hasError && Number.isFinite(ep.center) ? ep.center : valAt(ds, row);
  }));
  // Each value goes to the range of the axis its series is drawn on.
  const allVals: number[] = [];
  const y2Vals: number[] = [];
  const reachV = (di: number, v: number): void => {
    if (!Number.isFinite(v)) return;
    if (onLeft(di)) allVals.push(v);
    if (onY2(di)) y2Vals.push(v);
  };
  rowVals.forEach((vs) => vs.forEach((v, di) => reachV(di, v)));
  if (!dumbbell && Number.isFinite(baseVal)) reachV(0, baseVal);
  // The value axis must fit the whisker reach, not just the dots.
  rowErr.forEach((es) => es.forEach((ep, di) => {
    if (ep && ep.hasError) {
      reachV(di, ep.low);
      reachV(di, ep.high);
    }
  }));
  if (n === 0 || m === 0) warnings.push("Lollipop needs at least one category row and one value column.");

  const vSpec: AxisSpec = (horiz ? plot.xAxis : plot.yAxis) ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const gridDensity = plot.grid?.density ?? 6;
  const vAuto = allVals.length ? buildScale("linear", extent(allVals), [0, 1], gridDensity, false, vFmt).domain : ([0, 1] as [number, number]);
  // Note: the value spec follows the orientation (`horiz ? plot.xAxis : plot.yAxis`), so the window
  // key does too — a horizontal lollipop zooms through `xDomain`, a vertical one through
  // `yDomain`. Visual axis and key coincide here, unlike a flipped bar.
  const wv = windowed(vSpec, vAuto, horiz ? options.xDomain : options.yDomain);
  const vData = wv.data;
  const manualV = wv.manual;
  const vRev = vSpec.reversed ?? false;

  const catLabels = rows.map((r, i) => (xCol ? String(r.cells[xCol.id] ?? i + 1) : String(i + 1)));
  /**
   * The category names and the value numbers have their own fonts. Using the shared
   * `fonts.tick` for both would leave the Axis tab's "Category label font" and "Tick label font"
   * (both write `xAxis.tickFont` / `yAxis.tickFont`) with no effect here. `xTick`/`yTick` fall
   * back to the shared font, so a figure with no per-axis override is unchanged.
   */
  const catFont = horiz ? fonts.yTick : fonts.xTick;
  const valFont = horiz ? fonts.xTick : fonts.yTick;
  // The names sit on Y only when horizontal; there their rotation is the Y axis's.
  const catLabelW = Math.max(0, ...catLabels.map((t) => measure(t, catFont.size)), turnedYLabelsReach(catLabels, catFont.size, measure, horiz ? plot.yAxis?.tickRotation : undefined));
  // A column with no saved colour never repeats a sibling's. Colours are saved counting every column
  // of the sheet; these datasets skip hidden (and, on paired dot, section text) columns, so the plain
  // slot of an added column could be a sibling's colour.
  const dsColors = seriesColors(datasets.map((ds) => plot.seriesStyles?.[ds.id]?.color), palette);
  const dsColor = (di: number): string => dsColors[di]!;
  const fmtVal = (v: number): string => (Number.isInteger(v) ? String(v) : Number(v.toFixed(2)).toString());

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const leg = resolveLegend(
    plot,
    dumbbell ? datasets.map((ds, i) => ({ label: ds.name, color: dsColor(i), select: { as: "series" as const, id: ds.id } })) : [],
    measure,
    fonts.legend.size,
    width,
  );

  // Margins differ by orientation: the category labels go on the band axis, the
  // value ticks/title on the value axis.
  const vProbe = buildScale("linear", vData, [0, 1], gridDensity, manualV, vFmt, vSpacing);
  const vLabelW = Math.max(0, ...vProbe.ticks.filter((t) => !t.minor).map((t) => measure(t.label, valFont.size)));
  const vTitle = vSpec.title ?? (m === 1 ? datasets[0]!.name : "Value");
  const catSpec: AxisSpec = (horiz ? plot.yAxis : plot.xAxis) ?? {};
  const catTitle = catSpec.title ?? (xCol?.name ?? "");
  // Honour the Axis → Spacing options (label↔axis + title↔labels) for both the value axis
  // (vSpec) and the category axis (catSpec). Defaults follow the app convention: X-axis gap 6,
  // Y-axis gap 8. Hardcoded gaps would leave the Spacing controls doing nothing.
  const vTickGap = vSpec.tickLabelGap ?? (horiz ? 6 : 8);
  const vTitleGap = vSpec.titleGap ?? 6;
  const catTickGap = catSpec.tickLabelGap ?? (horiz ? 8 : 6);
  const catTitleGap = catSpec.titleGap ?? 6;

  let marginLeft: number;
  let marginBottom: number;
  if (horiz) {
    marginLeft = catSpec.hidden
      ? HIDDEN_AXIS_MARGIN
      : catLabelW + DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catTitleGap) : 4);
    marginBottom = vSpec.hidden
      ? HIDDEN_AXIS_MARGIN
      : valFont.size + vTickGap + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, vTitleGap));
  } else {
    marginLeft = vSpec.hidden
      ? HIDDEN_AXIS_MARGIN
      : vLabelW + DEFAULTS.tickLen + vTickGap + (textBand(fonts.yAxisTitle.size, vTitleGap));
    marginBottom = catSpec.hidden
      ? HIDDEN_AXIS_MARGIN
      : catFont.size + catTickGap + DEFAULTS.tickLen + (catTitle ? textBand(fonts.xAxisTitle.size, catTitleGap) : 4);
  }
  // Horizontal lollipops draw a "+NN%" Δ label just right of the rightmost dot;
  // reserve room so it isn't clipped in-app (export also expands to the bbox). Uses the
  // fixed LABEL_GAP (not dotSize) so changing dot size never rescales the plot width.
  // Measured in the value-label font, because that is what letters it: the builder and the
  // renderer both follow the numbers beside the dots, so enlarging that font widens the
  // reserve instead of running the Δ off the right edge.
  const deltaReserve = horiz && showDelta && dumbbell ? measure("+100%", fonts.valueLabel.size) + LABEL_GAP + 6 : 0;
  // The second axis takes a band above the plot (horizontal) or joins the right-margin stack, inside the legend.
  const y2Spec: AxisSpec = plot.y2Axis ?? {};
  if (y2Ids.size > 0 && y2Spec.scale && y2Spec.scale !== "linear") {
    warnings.push(`A ${y2Spec.scale === "probit" ? "probability" : "log"} scale is not available on a lollipop chart's second (Y2) axis — it is drawn linear.`);
  }
  const y2TitleFont = fonts.y2AxisTitle ?? (horiz ? fonts.xAxisTitle : fonts.yAxisTitle);
  const y2Plan = y2Ids.size > 0
    ? planSecondAxis(y2Spec, y2Vals, "linear", gridDensity, measure, { tick: fonts.y2Tick.size, title: y2TitleFont.size }, y2Ids.size === 1 ? (datasets.find((ds) => y2Ids.has(ds.id))?.name ?? "") : "", horiz ? "top" : "right", width)
    : null;
  const y2Top = horiz ? (y2Plan?.margin ?? 0) : 0;
  const y2Right = horiz ? 0 : (y2Plan?.margin ?? 0);
  if (y2Right > 0) leg.layout = { ...leg.layout, outsidePad: y2Right };
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + deltaReserve + y2Right + pad.r;
  marginLeft += pad.l;
  marginBottom += pad.b;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad + y2Top;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad + y2Top, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - y2Top - marginBottom);

  const vb = buildScale("linear", vData, horiz ? (vRev ? [plotW, 0] : [0, plotW]) : (vRev ? [0, plotH] : [plotH, 0]), gridDensity, manualV, vFmt, vSpacing);
  const vpx = (v: number): number => (horiz ? plotX + vb.scale(v) : plotY + vb.scale(v));
  const y2Placed = y2Plan ? placeSecondAxis(y2Plan, { x: plotX, y: plotY, width: plotW, height: plotH }, y2TitleFont.size) : null;
  /** The value scale a dataset is drawn against: its own second axis, or the main one. */
  const pxFor = (di: number): ((v: number) => number) => (y2Placed && onY2(di) ? y2Placed.px : vpx);
  // Δ% between the first and last series compares their values - meaningless across two axes' units.
  const deltaAcrossAxes = dumbbell && !!y2Placed && onY2(0) !== onY2(m - 1);
  if (showDelta && deltaAcrossAxes) {
    warnings.push("The change (Δ%) labels are not drawn: the first and last series are on different value axes, so a percentage between them would compare different units.");
  }
  const band = (horiz ? plotH : plotW) / Math.max(1, n);
  const bandCenter = (i: number): number => (horiz ? plotY : plotX) + i * band + band / 2;


  const lollipopRows: LollipopRow[] = rows.map((row, i) => {
    const cc = bandCenter(i);
    const vals = rowVals[i]!;
    const dots = datasets.map((ds, di) => {
      const v = vals[di]!;
      const pos = pxFor(di)(v);
      const has = Number.isFinite(v);
      // Resolve the dot's full symbol style: per-point override wins over the
      // series style; each field falls back to the lollipop default at render.
      const ss = plot.seriesStyles?.[ds.id];
      const ps = plot.pointStyles?.[`${ds.id}:${row.id}`];
      const pick = <K extends keyof SeriesStyle>(k: K): SeriesStyle[K] | undefined => ps?.[k] ?? ss?.[k];
      const dotColor = ps?.color ?? dsColor(di);
      // Two-tone dot: expand "twotone" into a concrete open marker with a light
      // interior + darker outline derived from the dot's own hue — exactly what
      // resolveSymbol() does for every other marker. buildLollipopScene picks
      // style fields directly (it never runs dots through resolveSymbol), so
      // without this the renderer receives an unknown "twotone" fill and draws the
      // dot hollow (fill → "none"). Non-two-tone dots are untouched.
      const rawFill = pick("symbolFill");
      const twoTone = rawFill === "twotone";
      const symbolFill = twoTone ? "open" : rawFill;
      // Two-tone always derives from the hue + the tint/shade sliders (never an
      // existing symbolFillColor) — matching resolveSymbol(). Deriving
      // unconditionally is what makes the fill re-tint when the Colour changes and
      // respond to the Fill-lightness / Edge-darkness sliders. (A stale
      // symbolFillColor from e.g. the house preset must not pin the fill.)
      const symbolFillColor = twoTone ? twoToneFill(dotColor, pick("twoToneTint")) : pick("symbolFillColor");
      // Fall back to the dot's own hue (like resolveSymbol does for every other marker),
      // so an open dot with no explicit outline draws a visible ring instead of a
      // page-background one that renders invisible.
      const symbolOutline = twoTone
        ? (pick("twoToneEdge") ?? twoToneContour(dotColor, pick("twoToneShade")))
        : (pick("symbolOutline") ?? dotColor);
      return {
        id: ds.id,
        cx: horiz ? (has ? pos : plotX) : cc,
        cy: horiz ? cc : has ? pos : plotY + plotH,
        color: dotColor,
        value: v,
        // Per-dot value-label text override (double-click to edit, like bars); empty/undefined
        // falls back to the formatted number. Only shown when the Values toggle is on.
        label: showValues && has ? (ps?.valueText != null && ps.valueText !== "" ? ps.valueText : fmtVal(v)) : "",
        symbol: pick("symbol"),
        // Dot-size precedence: a per-point highlight wins; then the dedicated "Dot size"
        // slider (cfg.dotSize) — so it actually controls the dots even after a style
        // preset baked a generic markerSize into every series (applyStylePreset writes
        // seriesStyles.symbolSize, which would otherwise shadow the slider and make it dead);
        // then the per-series marker size; else the render default. (`pick` = ps ?? ss.)
        size: ps?.symbolSize ?? cfg.dotSize ?? ss?.symbolSize,
        symbolFill,
        symbolOpacity: pick("symbolOpacity"),
        symbolOutline,
        symbolFillColor,
        borderWidth: pick("borderWidth"),
        valueDx: ps?.valueDx,
        valueDy: ps?.valueDy,
        // Mean±error whisker (opt-in): its value-axis pixel ends + resolved styling. Absent
        // unless a spread exists and the series' error type is set (default "none").
        ...(() => {
          const ep = rowErr[i]![di];
          if (!ep || !ep.hasError || !Number.isFinite(ep.low) || !Number.isFinite(ep.high)) return {};
          return {
            error: {
              low: ep.low,
              high: ep.high,
              lowPx: pxFor(di)(ep.low),
              highPx: pxFor(di)(ep.high),
              color: pick("errorColor") ?? dotColor,
              width: pick("errorWidth") ?? 1.5,
              capWidth: pick("errorCapWidth") ?? 4,
              caps: pick("errorCaps") ?? true,
              dir: pick("errorDir") ?? "both",
            },
          };
        })(),
      };
    });
    // Stem: dumbbell → between first & last dot; single → baseline → the value dot.
    let stem: LollipopRow["stem"];
    if (dumbbell) {
      const a = dots[0]!;
      const b = dots[dots.length - 1]!;
      stem = horiz ? { x1: a.cx, y1: cc, x2: b.cx, y2: cc } : { x1: cc, y1: a.cy, x2: cc, y2: b.cy };
    } else {
      const b0 = pxFor(0)(baseVal);
      const d = dots[0]!;
      stem = horiz ? { x1: b0, y1: cc, x2: d.cx, y2: cc } : { x1: cc, y1: b0, x2: cc, y2: d.cy };
    }
    // Δ%: dumbbell first→last; single value vs baseline (skip when baseline 0 / ref 0).
    let delta: LollipopRow["delta"] | undefined;
    if (showDelta && !deltaAcrossAxes) {
      const from = dumbbell ? vals[0]! : baseVal;
      const to = dumbbell ? vals[vals.length - 1]! : vals[0]!;
      if (Number.isFinite(from) && Number.isFinite(to) && from !== 0) {
        const pct = ((to - from) / Math.abs(from)) * 100;
        const endDot = dots.reduce((p, q) => (horiz ? (q.cx > p.cx ? q : p) : q.cy < p.cy ? q : p));
        // Drag nudge + text override stored under a reserved point-style key, so the Δ% is
        // both movable and renamable like the dot value labels beside it.
        const dps = plot.pointStyles?.[`__delta__:${row.id}`];
        // A renamed Δ wins over the computed percentage (blank restores it). Presentation
        // only — the underlying values are untouched, so a data edit still recomputes it.
        const text = dps?.valueText ?? `${pct >= 0 ? "+" : ""}${pct.toFixed(0)}%`;
        const deltaColor = cfg.deltaColor ?? "#1a9850"; // user-settable; green by default
        delta = horiz
          ? { text, x: endDot.cx + LABEL_GAP, y: cc + fonts.valueLabel.size * 0.34, anchor: "start" as const, color: deltaColor, dx: dps?.valueDx, dy: dps?.valueDy }
          : { text, x: cc, y: endDot.cy - LABEL_GAP, anchor: "middle" as const, color: deltaColor, dx: dps?.valueDx, dy: dps?.valueDy };
      }
    }
    // Linked stem → follows this row's dot colour (the primary/first dot).
    const stemColor = stemLinked ? dots[0]?.color : undefined;
    return { rowId: row.id, label: catLabels[i]!, stem, ...(stemColor ? { stemColor } : {}), dots, ...(delta ? { delta } : {}) };
  });

  // Reference (index) line at the baseline value — single-series only.
  let baseline: { x1: number; y1: number; x2: number; y2: number } | undefined;
  if (!dumbbell && Number.isFinite(baseVal)) {
    const b0 = pxFor(0)(baseVal);
    baseline = horiz
      ? { x1: b0, y1: plotY, x2: b0, y2: plotY + plotH }
      : { x1: plotX, y1: b0, x2: plotX + plotW, y2: b0 };
  }

  const valueAxis: AxisScene = {
    type: "linear",
    domain: vRev ? [vb.domain[1], vb.domain[0]] : vb.domain,
    range: horiz ? [plotX, plotX + plotW] : [plotY + plotH, plotY],
    ticks: (horiz ? deOverlapX(vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, valFont.size) : vb.ticks.map((t) => ({ ...t, pos: plotY + t.pos }))),
    title: vTitle,
    ...axisLine(vSpec),
  };
  const catAxis: AxisScene = {
    type: "linear",
    domain: [0, Math.max(1, n)],
    range: horiz ? [plotY + plotH, plotY] : [plotX, plotX + plotW],
    band: true,
    // Flat names along X drop one that would land on its neighbour - the box and bar charts' rule, the name kept on
    // the tick for grouping. Without it, the narrower plot a second axis leaves would run names together.
    ticks: (() => {
      const t = rows.map((_r, i) => ({ value: i, pos: bandCenter(i), label: catLabels[i]!, minor: false }));
      return !horiz && !plot.xAxis?.tickRotation ? deOverlapX(t, measure, catFont.size) : t;
    })(),
    title: catTitle,
    ...axisLine((horiz ? plot.yAxis : plot.xAxis)),
  };

  // Annotations (reference lines / text / bands / brackets) — mirror the categorical
  // bar builder for both orientations: on a horizontal lollipop the value axis is X
  // (transposed → a value reference line draws vertically; brackets span categories on
  // Y); on a vertical lollipop the value axis is Y (X is categorical → no vline).
  const catToBand = (c: number): number | undefined => (c >= 1 && c <= n ? bandCenter(c - 1) : undefined);
  const valAnn = (v: number): number | undefined => (Number.isFinite(v) ? vpx(v) : undefined);
  const annRect = { x: plotX, y: plotY, width: plotW, height: plotH };
  const annotations = horiz
    ? buildAnnotations(plot, annRect, { x: valAnn, y: valAnn, bracketX: catToBand }, true, warnings)
    : buildAnnotations(plot, annRect, { x: null, y: valAnn, bracketX: catToBand }, undefined, warnings);
  // Note: lollipop defaults to horizontal, so its value axis is X unless flipped. `isTransposedPlot`
  // does not cover the lollipop, so this reads the builder's own flag.
  const valueAxisSide = horiz ? ("x" as const) : ("y" as const);

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: horiz ? valueAxis : catAxis,
    y: horiz ? catAxis : valueAxis,
    ...(y2Placed ? { y2: y2Placed.axis } : {}),
    auto: (() => {
      const hv = (horiz ? options.xDomain : options.yDomain) != null
        ? buildScale("linear", wv.home, [0, 1], gridDensity, wv.homeManual, vFmt, vSpacing).domain
        : vb.domain;
      const v: [number, number] = vRev ? [hv[1], hv[0]] : hv;
      return { x: horiz ? v : ([0, n] as [number, number]), y: horiz ? ([0, n] as [number, number]) : v };
    })(),
    zoomable: [horiz ? { visual: "x" as const, key: "x" as const } : { visual: "y" as const, key: "y" as const }],
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    valueAxis: valueAxisSide,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: horiz ? vTitle : catTitle, y: horiz ? catTitle : vTitle },
    kind: "lollipop",
    fonts,
    lollipop: { rows: lollipopRows, horizontal: horiz, dotSize, stemWidth, stemColor: cfg.stemColor, ...(baseline ? { baseline } : {}) },
    warnings,
  };
}

/**
 * Paired / grouped Cleveland dot plot (kind "paireddot"). Horizontal category
 * rows (labelled by the X column); each numeric series draws one marker per row.
 * A leading text column (besides the X label column) is auto-detected as a section
 * grouping — contiguous rows sharing a section value get a dashed divider and a
 * rotated section label on the right. `connector` picks the row form: `toZero` = a stem from the
 * baseline to each dot (a double lollipop, dots spread vertically within the band);
 * `dumbbell` = the dots on the row centre line joined by one connector; `none` =
 * dots only. Per-series means (replicate/summary mean) supply the values.
 */
function buildPairedDotScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a paired dot plot", warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const xCol = xColumn(table);
  const rows = table.rows;
  const n = rows.length;

  const cfg = plot.paireddot ?? {};
  const connector = cfg.connector ?? "toZero";
  const toZero = connector === "toZero";
  const dotSize = Math.max(1, cfg.dotSize ?? 5);
  const stemWidth = Math.max(0.5, cfg.stemWidth ?? 2);
  const stemLinked = cfg.stemLinkColor ?? true;
  const spread = Math.max(0, Math.min(1, cfg.seriesSpread ?? 0.55));
  const showValues = cfg.showValues ?? false;
  const showSections = cfg.showSections ?? true;
  const baseVal = cfg.baseline ?? 0;


  const valAt = (ds: Dataset, row: Row): number => {
    if (isSummaryDataset(ds)) return toNumber(row.cells[ds.replicates[0]!]);
    const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
  };
  // A dataset whose values are all non-numeric (and at least one is a non-empty
  // string) is a text column → the section grouping, not a plotted series. Take the
  // first such as the section; any other text column is ignored (never a NaN series).
  const allDatasets = visibleDatasets(table, plot);
  const textOf = (ds: Dataset, row: Row): string => String(row.cells[ds.replicates[0] ?? ds.id] ?? "").trim();
  const isTextDs = (ds: Dataset): boolean =>
    n > 0 && rows.every((r) => !Number.isFinite(valAt(ds, r))) && rows.some((r) => textOf(ds, r) !== "");
  const sectionDs = allDatasets.find(isTextDs);
  const datasets = allDatasets.filter((ds) => ds !== sectionDs && !isTextDs(ds));
  const m = datasets.length;
  if (n === 0 || m === 0) warnings.push("Paired dot plot needs at least one category row and one numeric value column.");

  const rowVals = rows.map((row) => datasets.map((ds) => valAt(ds, row)));
  const allVals = rowVals.flat().filter((v) => Number.isFinite(v));
  if (toZero && Number.isFinite(baseVal)) allVals.push(baseVal);

  // Value (X) axis.
  const vSpec: AxisSpec = plot.xAxis ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const gridDensity = plot.grid?.density ?? 6;
  const vAuto = allVals.length ? buildScale("linear", extent(allVals), [0, 1], gridDensity, false, vFmt).domain : ([0, 1] as [number, number]);
  const wv = windowed(vSpec, vAuto, options.xDomain);
  const vData = wv.data;
  const manualV = wv.manual;
  const vRev = vSpec.reversed ?? false;

  const catLabelsRaw = rows.map((r, i) => (xCol ? String(r.cells[xCol.id] ?? i + 1) : String(i + 1)));
  // A column with no saved colour never repeats a sibling's. Colours are saved counting every column
  // of the sheet; these datasets skip hidden (and, on paired dot, section text) columns, so the plain
  // slot of an added column could be a sibling's colour.
  const dsColors = seriesColors(datasets.map((ds) => plot.seriesStyles?.[ds.id]?.color), palette);
  const dsColor = (di: number): string => dsColors[di]!;
  const fmtVal = (v: number): string => (Number.isInteger(v) ? String(v) : Number(v.toFixed(2)).toString());

  // Section runs: contiguous rows sharing a section label (data order, no reorder).
  const sectionLabels: string[] = sectionDs ? rows.map((r) => textOf(sectionDs, r)) : [];
  const hasSections = showSections && !!sectionDs && sectionLabels.some((s) => s !== "");

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const legEntry = (ds: Dataset, i: number, label: string): LegendEntry =>
    ({ label, color: dsColor(i), select: { as: "series" as const, id: ds.id } });

  const vTitle = vSpec.title ?? (m === 1 ? datasets[0]!.name : "Value");
  const catSpec: AxisSpec = plot.yAxis ?? {};
  const catTitle = catSpec.title ?? (xCol?.name ?? "");
  const vTickGap = vSpec.tickLabelGap ?? 6;
  const vTitleGap = vSpec.titleGap ?? 6;
  const catTickGap = catSpec.tickLabelGap ?? 8;
  const catTitleGap = catSpec.titleGap ?? 6;
  // Reserve room on the right for the rotated section labels (drawn vertically, so
  // only the font height + a gap eats horizontal space).
  const sectionReserve = hasSections ? fonts.legend.size + 14 : 0;

  /**
   * Two unbounded text bands would consume the graph. This chart has a row label on the left and
   * a series legend on the right; uncapped, the plot gets whatever the words leave. For example,
   * a 172 px row label and a 154 px legend name give marginLeft 255 +
   * marginRight 198 = 453 px of margin: at the 580 default that leaves 127 px of plot (22%); at
   * 360 it leaves one pixel, which `Math.max(1, …)` below would hide — a graph drawn with no
   * plot area and no warning.
   *
   * The rule: the plot keeps at least `MIN_PLOT_SHARE` of the width, and when the two bands
   * cannot both have what they want they are cut proportionally and their labels ellipsised,
   * so the reservation and the drawing shrink together. Degrading both is what keeps the chart
   * legible either way — starving one to spare the other just moves the damage.
   *
   * 0.20 is a floor against collapse, not a quality target, and the difference matters. A value
   * like 0.42 would start truncating at the default 580 width, cutting the labels of ordinary
   * paired-dot graphs to serve tiny ones; `gallery.test.ts` guards this by refusing a card that
   * emits a warning. A figure wide enough to be usable draws its labels in full; only the
   * degenerate case is cut.
   */
  const MIN_PLOT_SHARE = 0.20;
  const BAND_FLOOR = 26; // below this a label is an ellipsis and nothing else
  /** Same rule as the lollipop: the trait names and the value numbers each take their own axis
   *  font rather than the shared `fonts.tick`, so the Axis tab's two font blocks apply here. A paired dot is
   *  always horizontal — values on X, categories on Y. `xTick`/`yTick` fall back to the shared
   *  font, so a figure with no axis-specific font uses the shared tick font. */
  const catFont = fonts.yTick;
  const valFont = fonts.xTick;
  const catWantW = catSpec.hidden ? 0 : Math.max(0, ...catLabelsRaw.map((t) => measure(t, catFont.size)));
  // What the legend costs besides its text, and whether it is drawn outside at all. Asked of
  // `resolveLegend` rather than re-derived here, so the two cannot drift.
  // Note: no figureWidth here, and none on the real call below: this chart runs its own, stricter
  // cap (the two text bands are cut proportionally against a plot-share floor). Letting the
  // generic legend cap fire first would feed this probe an already-shortened width, so `legFixed`
  // would come out negative, the text bands would be given more than their budget, and the plot
  // would shrink below its floor share of the figure.
  const legProbe = resolveLegend(plot, datasets.map((ds, i) => legEntry(ds, i, ds.name)), measure, fonts.legend.size);
  const legWantW = legProbe.outsideRightWidth > 0 ? Math.max(0, ...datasets.map((ds) => measure(ds.name, fonts.legend.size))) : 0;
  const legFixed = legProbe.outsideRightWidth > 0 ? legProbe.outsideRightWidth - legWantW : 0;
  const fixedMargins =
    (catSpec.hidden ? HIDDEN_AXIS_MARGIN : DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catTitleGap) : 4)) +
    pad.l + DEFAULTS.marginRight + sectionReserve + pad.r + legFixed;
  const textBudget = width * (1 - MIN_PLOT_SHARE) - fixedMargins;
  const wanted = catWantW + legWantW;
  const squeeze = wanted > 0 && wanted > textBudget ? Math.max(0, textBudget) / wanted : 1;
  const catCapW = squeeze < 1 ? Math.max(BAND_FLOOR, catWantW * squeeze) : catWantW;
  const legCapW = squeeze < 1 ? Math.max(BAND_FLOOR, legWantW * squeeze) : legWantW;
  const catLabels = squeeze < 1 ? catLabelsRaw.map((t) => truncateToWidth(t, catFont.size, catCapW, measure) || t.slice(0, 1)) : catLabelsRaw;
  const legendNames = squeeze < 1 ? datasets.map((ds) => truncateToWidth(ds.name, fonts.legend.size, legCapW, measure) || ds.name.slice(0, 1)) : datasets.map((ds) => ds.name);
  if (squeeze < 1) {
    warnings.push("The row labels and legend are too wide for this figure — both were shortened so the plot keeps its room. Widen the figure to see them in full.");
  }
  const catLabelW = Math.max(0, ...catLabels.map((t) => measure(t, catFont.size)), turnedYLabelsReach(catLabels, catFont.size, measure, catSpec.tickRotation));
  const leg = resolveLegend(plot, datasets.map((ds, i) => legEntry(ds, i, legendNames[i]!)), measure, fonts.legend.size);

  let marginLeft = catSpec.hidden
    ? HIDDEN_AXIS_MARGIN // pad.l is added below
    : catLabelW + DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catTitleGap) : 4);
  const marginBottom = vSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : valFont.size + vTickGap + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, vTitleGap)) + pad.b;
  // Push the outside-right legend past the rotated section-label band — both otherwise land
  // at plotX+plotW+12 and stack on top of each other. The room is already in marginRight.
  if (sectionReserve) leg.layout = { ...leg.layout, outsidePad: sectionReserve };
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + sectionReserve + pad.r;
  marginLeft += pad.l;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const vb = buildScale("linear", vData, vRev ? [plotW, 0] : [0, plotW], gridDensity, manualV, vFmt, vSpacing);
  const vpx = (v: number): number => plotX + vb.scale(v);
  const band = plotH / Math.max(1, n);
  const bandTop = (i: number): number => plotY + i * band;
  const bandCenter = (i: number): number => plotY + i * band + band / 2;
  // Per-series vertical offset within a band (toZero spreads the dots; dumbbell/none align them).
  const spreadPx = toZero ? spread * band : 0;
  const seriesOffset = (di: number): number => (m > 1 ? -spreadPx / 2 + di * (spreadPx / (m - 1)) : 0);

  const baseX = vpx(baseVal);
  // Row labels stack one per band, so they collide as soon as a band is shorter than a line of
  // text. Shrink to fit rather than drop: on this chart every row is a named trait.
  const rowLabelFit = fitStackedLabels(n, band, catFont.size);
  /**
   * Report it when the fit wins. The row labels are shrunk (and thinned) to stop stacked
   * names colliding, which means a size the user typed can come out smaller — done silently,
   * "Category label font → Size" would look like a dead control.
   * Only warned when the size was set explicitly: every default figure is fitted too, and a
   * warning nobody asked for is noise.
   */
  if (catSpec.tickFont?.size !== undefined && rowLabelFit.font < catSpec.tickFont.size) {
    warnings.push(
      `Category labels are drawn at ${rowLabelFit.font}px, not the ${catSpec.tickFont.size}px asked for: ${n} rows leave no room. A taller figure, or fewer rows, will honour it.`,
    );
  }
  const pdRows: PairedDotRow[] = rows.map((row, i) => {
    const cc = bandCenter(i);
    const vals = rowVals[i]!;
    const marks: PairedDotMark[] = datasets.map((ds, di) => {
      const v = vals[di]!;
      const has = Number.isFinite(v);
      const cy = cc + seriesOffset(di);
      const cx = has ? vpx(v) : plotX;
      const ss = plot.seriesStyles?.[ds.id];
      const ps = plot.pointStyles?.[`${ds.id}:${row.id}`];
      const pick = <K extends keyof SeriesStyle>(k: K): SeriesStyle[K] | undefined => ps?.[k] ?? ss?.[k];
      const dotColor = ps?.color ?? dsColor(di);
      const rawFill = pick("symbolFill");
      const twoTone = rawFill === "twotone";
      const symbolFill = twoTone ? "open" : rawFill;
      const symbolFillColor = twoTone ? twoToneFill(dotColor, pick("twoToneTint")) : pick("symbolFillColor");
      const symbolOutline = twoTone ? (pick("twoToneEdge") ?? twoToneContour(dotColor, pick("twoToneShade"))) : (pick("symbolOutline") ?? dotColor);
      const stem = toZero && has ? { x1: baseX, y1: cy, x2: cx, y2: cy } : undefined;
      return {
        id: ds.id,
        cx,
        cy,
        color: dotColor,
        value: v,
        label: showValues && has ? (ps?.valueText != null && ps.valueText !== "" ? ps.valueText : fmtVal(v)) : "",
        ...(stem ? { stem } : {}),
        symbol: pick("symbol"),
        size: ps?.symbolSize ?? cfg.dotSize ?? ss?.symbolSize,
        symbolFill,
        symbolOpacity: pick("symbolOpacity"),
        symbolOutline,
        symbolFillColor,
        borderWidth: pick("borderWidth"),
        valueDx: ps?.valueDx,
        valueDy: ps?.valueDy,
      };
    });
    // Dumbbell connector: a single line across the row's finite marks (min→max x).
    let conn: PairedDotRow["connector"];
    if (connector === "dumbbell") {
      const fin = marks.filter((mk) => Number.isFinite(mk.value));
      if (fin.length >= 2) {
        const xs = fin.map((mk) => mk.cx);
        conn = { x1: Math.min(...xs), y1: cc, x2: Math.max(...xs), y2: cc, color: cfg.stemColor ?? "var(--line-2)" };
      }
    }
    const full = catLabels[i]!;
    const shown = rowLabelFit.keep && !rowLabelFit.keep.has(i) ? "" : full;
    return {
      rowId: row.id,
      label: shown,
      ...(shown === "" ? { suppressedLabel: full } : {}),
      cy: cc,
      marks,
      ...(conn ? { connector: conn } : {}),
    };
  });

  // Section geometry (dividers at each run's leading edge + a rotated centred label).
  // The dividers are the chart's reference line: clicking one opens the same panel the
  // Bland-Altman limits and the ROC diagonal use. `show:false` drops them, as the
  // "Show sections" switch does for the headings.
  const pdDivider = resolveRefLine(plot, "pd-section", { dash: "6 4", width: 1.25 });
  const sections: PairedDotSection[] = [];
  if (hasSections) {
    let start = 0;
    for (let i = 1; i <= n; i++) {
      if (i === n || sectionLabels[i] !== sectionLabels[start]) {
        const label = sectionLabels[start] ?? "";
        if (label !== "") {
          const yTop = bandTop(start);
          const yBot = bandTop(i);
          const soff = cfg.sectionLabelOffsets?.[label];
          // The heading is rotated 90°, so its length runs down the section — a name longer
          // than its band spills into the neighbouring section's heading. Trim it to the band
          // rather than letting two headings collide.
          //
          // A fixed gap, not a percentage: a proportional allowance (e.g. `* 0.92`) leaves ~1.7px
          // of real overlap between adjacent headings, because it shrinks exactly when the band
          // is small and the clash is most likely, and because `measure` only estimates width —
          // any under-estimate is spent straight into the neighbour. 8px is comfortably past that
          // error and independent of band size.
          const SECTION_LABEL_GAP = 8;
          const fitted = truncateToWidth(label, fonts.legend.size, Math.max(0, yBot - yTop - SECTION_LABEL_GAP), measure);
          sections.push({
            label,
            ...(fitted === label ? {} : { display: fitted }),
            // Hiding the reference line drops the rules and keeps the headings — a section is
            // still a section without a line drawn across the chart.
            ...(pdDivider.show ? { divider: { x1: plotX, y1: yTop, x2: plotX + plotW, y2: yTop } } : {}),
            labelX: plotX + plotW + 12,
            labelY: (yTop + yBot) / 2,
            ...(soff?.dx != null ? { dx: soff.dx } : {}),
            ...(soff?.dy != null ? { dy: soff.dy } : {}),
          });
        }
        start = i;
      }
    }
  }

  const valueAxis: AxisScene = {
    type: "linear",
    domain: vRev ? [vb.domain[1], vb.domain[0]] : vb.domain,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, valFont.size),
    title: vTitle,
    ...axisLine(vSpec),
  };
  const catAxis: AxisScene = {
    type: "linear",
    domain: [0, Math.max(1, n)],
    range: [plotY + plotH, plotY],
    band: true,
    // A row name shortened to fit keeps its full name as its identity (`suppressedLabel`), so a
    // category group keyed by the name still matches at any figure width.
    ticks: rows.map((_r, i) => ({
      value: i, pos: bandCenter(i), label: catLabels[i]!, minor: false,
      ...(catLabels[i] !== catLabelsRaw[i] ? { suppressedLabel: catLabelsRaw[i]! } : {}),
    })),
    title: catTitle,
    ...axisLine(plot.yAxis),
  };

  const catToBand = (c: number): number | undefined => (c >= 1 && c <= n ? bandCenter(c - 1) : undefined);
  const valAnn = (v: number): number | undefined => (Number.isFinite(v) ? vpx(v) : undefined);
  const annRect = { x: plotX, y: plotY, width: plotW, height: plotH };
  const annotations = buildAnnotations(plot, annRect, { x: valAnn, y: valAnn, bracketX: catToBand }, true, warnings);
  const valueAxisSide = "x" as const;

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: valueAxis,
    y: catAxis,
    auto: (() => {
      const hv = options.xDomain != null
        ? buildScale("linear", wv.home, [0, 1], gridDensity, wv.homeManual, vFmt, vSpacing).domain
        : vb.domain;
      return { x: (vRev ? [hv[1], hv[0]] : hv) as [number, number], y: [0, n] as [number, number] };
    })(),
    // Values run along X; Y bands the categories being compared.
    zoomable: [{ visual: "x", key: "x" }],
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    valueAxis: valueAxisSide,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: vTitle, y: catTitle },
    kind: "paireddot",
    fonts,
    // "Link stem to dot colour": when linked, ship no stem colour so the renderer falls
    // back to each mark's dot colour — so re-checking the box restores the linked colour.
    paireddot: {
      rows: pdRows, sections, labelFont: rowLabelFit.font, dotSize, stemWidth,
      stemColor: stemLinked ? undefined : cfg.stemColor,
      // Note: the divider colour keeps coming from `paireddot.sectionColor` — it colours the
      // rotated section headings too, and splitting those apart would silently restyle every
      // existing graph. The reference-line colour override wins when it is set.
      sectionColor: pdDivider.color ?? cfg.sectionColor,
      sectionWidth: pdDivider.width,
      sectionDash: pdDivider.dash,
    },
    warnings,
  };
}

/** One category's value + error for a dataset. */
interface CatVal {
  center: number;
  low: number;
  high: number;
  hasError: boolean;
  n: number;
}

/** Histogram (kind "histogram"): bin the first dataset's pooled values into a
 *  frequency distribution, then render it through the bar builder as contiguous
 *  (gapless) bars — bin-range labels on X, count on Y. Reuses all bar machinery. */
function buildHistogramScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const datasets = visibleDatasets(table, plot);
  const ds0 = datasets[0];
  const values: number[] = [];
  if (ds0) {
    const cols = ds0.replicates.length ? ds0.replicates : [ds0.id];
    for (const row of table.rows) {
      for (const c of cols) {
        const v = toNumber(row.cells[c]);
        if (Number.isFinite(v)) values.push(v);
      }
    }
  }
  const extraWarn = values.length < 2 ? ["Histogram needs at least 2 numeric values."] : [];
  const [lo, hi] = values.length ? extent(values) : [0, 1];
  const span = hi - lo || 1;
  const hcfg = plot.histogram ?? {};
  // Just-enough decimals for a bin width, so edge labels carry no trailing-zero noise.
  const edgeDecimals = (w: number): number => (w >= 1 ? 0 : Math.min(6, Math.ceil(-Math.log10(w)) + 1));
  // Custom bin ranges win over width/count/origin: each [lo, hi] is one bin, `null` = open on
  // that side, so unequal widths, gaps (a value in no range is left out) and open bins ("90+")
  // are all expressible. Half-open [lo, hi); a value on a bin's upper edge that no half-open bin
  // claims falls into that bin (so the maximum, and shared edges, land where a histogram expects).
  const ranges: Array<[number | null, number | null]> = (hcfg.binRanges ?? []).filter(
    (r) =>
      Array.isArray(r) && r.length === 2 &&
      (r[0] != null || r[1] != null) &&
      (r[0] == null || Number.isFinite(r[0])) &&
      (r[1] == null || Number.isFinite(r[1])) &&
      (r[0] == null || r[1] == null || r[0] < r[1]),
  );
  let counts: number[];
  let labels: string[];
  let binBounds: Array<[number | null, number | null]>; // numeric [lo,hi] per bin, for proportional width
  if (ranges.length >= 1) {
    counts = new Array<number>(ranges.length).fill(0);
    let dropped = 0;
    // Half-open [lo, hi) throughout, so shared edges go to the upper bin (the histogram norm).
    // Only the dataset maximum is rescued at a closed top edge — that keeps the top bin closed
    // (like numpy's last bin) without making every bin's upper edge inclusive, which would pull
    // a shared/gap boundary value into the wrong bin.
    const maxV = values.reduce((m, v) => (v > m ? v : m), -Infinity);
    for (const v of values) {
      let b = ranges.findIndex(([lo, hi]) => (lo == null || v >= lo) && (hi == null || v < hi));
      if (b < 0 && v === maxV) b = ranges.findIndex(([lo, hi]) => hi != null && v === hi && (lo == null || v >= lo));
      if (b < 0) dropped++;
      else counts[b] = (counts[b] ?? 0) + 1;
    }
    if (dropped > 0) extraWarn.push(`${dropped} value${dropped === 1 ? "" : "s"} fell outside the custom bins and ${dropped === 1 ? "was" : "were"} left out.`);
    const widths = ranges.map(([lo, hi]) => (lo != null && hi != null ? hi - lo : Infinity)).filter((w) => Number.isFinite(w) && w > 0);
    const dcm = edgeDecimals(widths.length ? Math.min(...widths) : 1);
    const f = (v: number): string => String(Number(v.toFixed(Math.max(0, dcm))));
    labels = ranges.map(([lo, hi]) => (lo == null ? `<${f(hi!)}` : hi == null ? `≥${f(lo)}` : `${f(lo)}–${f(hi)}`));
    binBounds = ranges;
  } else {
    // Binning. Explicit width wins (tidy, predictable edges); else an explicit count
    // divides the range exactly; else auto picks a nice 1·2·2.5·5 width near the
    // Sturges target so the edges are round numbers instead of long decimals.
    let binW: number;
    let origin: number;
    let nBins: number;
    if (hcfg.binWidth != null && hcfg.binWidth > 0) {
      binW = hcfg.binWidth;
      origin = hcfg.origin ?? Math.floor(lo / binW) * binW;
      nBins = Math.max(1, Math.min(200, Math.ceil((hi - origin) / binW - 1e-9) || 1));
    } else if (hcfg.bins != null) {
      nBins = Math.max(1, Math.min(60, Math.round(hcfg.bins)));
      origin = hcfg.origin ?? lo;
      binW = (hi - origin || 1) / nBins;
    } else {
      const target = Math.max(1, Math.ceil(1 + Math.log2(Math.max(1, values.length)))); // Sturges
      binW = niceBinWidth(span / target);
      origin = hcfg.origin ?? Math.floor(lo / binW) * binW;
      nBins = Math.max(1, Math.min(60, Math.ceil((hi - origin) / binW - 1e-9) || 1));
    }
    counts = new Array<number>(nBins).fill(0);
    for (const v of values) {
      let b = Math.floor((v - origin) / binW);
      if (b < 0) b = 0;
      else if (b >= nBins) b = nBins - 1;
      counts[b] = (counts[b] ?? 0) + 1;
    }
    const dcm = edgeDecimals(binW);
    const f = (v: number): string => String(Number(v.toFixed(Math.max(0, dcm))));
    labels = counts.map((_, i) => `${f(origin + i * binW)}–${f(origin + (i + 1) * binW)}`);
    binBounds = counts.map((_, i) => [origin + i * binW, origin + (i + 1) * binW]);
  }
  // Frequency mode: what the bar heights represent (count / relative / percent /
  // cumulative / cumulative %). The bin math above is unchanged — only the heights scale.
  const total = values.length || 1;
  const freqMode = hcfg.freq ?? "count";
  let heights: number[] = counts.slice();
  if (freqMode === "relative") heights = counts.map((c) => c / total);
  else if (freqMode === "percent") heights = counts.map((c) => (c / total) * 100);
  else if (freqMode === "cumulative" || freqMode === "cumulativePercent") {
    let run = 0;
    heights = counts.map((c) => (run += c));
    if (freqMode === "cumulativePercent") heights = heights.map((c) => (c / total) * 100);
  }
  const yTitle =
    freqMode === "relative" ? "Relative frequency"
    : freqMode === "percent" ? "Percent of total"
    : freqMode === "cumulative" ? "Cumulative count"
    : freqMode === "cumulativePercent" ? "Cumulative %"
    : "Count";
  // Carry the real series id so a bar click selects (and styles) the actual series,
  // and forward its full style (fill / two-tone / border …), not just the colour —
  // otherwise the two-tone and other fill options never reach the bars, and edits land on a
  // synthetic key nothing reads.
  const seriesId = ds0?.id ?? "count";
  const synth: DataTable = {
    id: `${table.id}-hist`,
    kind: "column",
    name: table.name,
    columns: [
      { id: "__hbin__", name: ds0?.name ?? "Value", role: "x" },
      { id: seriesId, name: yTitle, role: "y" },
    ],
    rows: heights.map((c, i) => ({ id: `bin-${i}`, cells: { __hbin__: labels[i] ?? `bin ${i + 1}`, [seriesId]: c } })),
  };
  const fullStyle = ds0 ? plot.seriesStyles?.[ds0.id] : undefined;
  const barPlot: Plot = {
    ...plot,
    kind: "bar",
    barLayout: "grouped",
    barWidth: plot.barWidth ?? 1, // contiguous bins (no gaps)
    // A series' own bar width is a bar-chart setting: a histogram has one series and no such control.
    seriesStyles: fullStyle ? { [seriesId]: { ...fullStyle, barWidth: undefined } } : {},
    xAxis: { ...(plot.xAxis ?? {}), title: plot.xAxis?.title ?? ds0?.name ?? "Value" },
    yAxis: { ...(plot.yAxis ?? {}), title: plot.yAxis?.title ?? yTitle },
  };
  // Distribution-curve overlays (opt-in), drawn over the bars — the bars stay:
  //   • "normal": a Gaussian with the data's own mean + SD;
  //   • "density": the violin's kernel density estimate (`gaussianKde`,
  //     Silverman bandwidth × `densityBandwidth`).
  // Both are scaled to the frequency axis by the same factor (count → n·binW, relative → binW,
  // percent → 100·binW) so they are comparable on one histogram. Frequency modes + equal-width
  // bins only — a cumulative histogram or custom/open bins warn instead of drawing a misleading
  // curve. Planned here, before the bars are laid out, so the value axis can make room for the
  // curve peaks (`extraYValues`) instead of clamping a tall curve flat along the plot top.
  // The paths are drawn after the scene.
  const wantNormal = hcfg.normalCurve === true;
  const wantDensity = hcfg.densityCurve === true;
  let curvePlan: { xs: number[]; scaleH: number; normal?: number[]; density?: number[] } | undefined;
  if ((wantNormal || wantDensity) && values.length >= 2) {
    const cumulative = freqMode === "cumulative" || freqMode === "cumulativePercent";
    const widths = binBounds.map((b) => (b[0] != null && b[1] != null ? b[1]! - b[0]! : NaN));
    const uniform = widths.length > 0 && widths.every((w) => Number.isFinite(w) && Math.abs(w - widths[0]!) < 1e-9);
    const asked = [wantNormal ? "normal curve" : "", wantDensity ? "density curve" : ""].filter(Boolean).join(" and ");
    if (cumulative) extraWarn.push(`The ${asked} is drawn on a frequency histogram — switch Cumulative off to see it.`);
    else if (!uniform) extraWarn.push(`The ${asked} needs equal-width bins — it is not drawn over custom or open-ended bins.`);
    else {
      const binW = widths[0]!;
      const scaleH = freqMode === "relative" ? binW : freqMode === "percent" ? 100 * binW : total * binW;
      const xStart = binBounds[0]![0]!, xEnd = binBounds[binBounds.length - 1]![1]!;
      const N = 96;
      const xs = Array.from({ length: N + 1 }, (_, k) => xStart + ((xEnd - xStart) * k) / N);
      curvePlan = { xs, scaleH };
      if (wantNormal) {
        const mean = values.reduce((s, v) => s + v, 0) / values.length;
        const variance = values.reduce((s, v) => s + (v - mean) ** 2, 0) / (values.length - 1);
        const sd = Math.sqrt(variance);
        if (sd > 0) curvePlan.normal = xs.map((x) => Math.exp(-((x - mean) ** 2) / (2 * variance)) / (sd * Math.sqrt(2 * Math.PI)));
      }
      if (wantDensity) {
        const base = silvermanBandwidth(values);
        const mult = hcfg.densityBandwidth ?? 1;
        const dens = gaussianKde(values, xs, base > 0 && mult !== 1 ? base * mult : undefined);
        if (dens.some((d) => d > 0)) curvePlan.density = dens;
      }
    }
  }
  const plan = curvePlan;
  const curvePeaks = plan ? [plan.normal, plan.density].filter((a): a is number[] => !!a).map((a) => plan.scaleH * Math.max(...a)) : [];
  const scene = buildCategoricalScene(synth, barPlot, { ...options, barRowsAreCategories: true, extraYValues: curvePeaks });
  // Proportional-width bars (opt-in, vertical only): re-lay the bars on a continuous numeric X
  // axis so each bar's width tracks its bin's data range, and swap the categorical bin-label
  // ticks for numeric edge ticks. Reuses the categorical scene's fills / heights / selection —
  // only the bar rects, their centres, and the X axis change. Open-ended bins are clamped to the
  // data extent so they get a finite width.
  if (hcfg.proportionalWidth && (plot.barOrientation ?? "vertical") !== "horizontal" && binBounds.length) {
    const finiteLos = binBounds.map((b) => b[0]).filter((n): n is number => n != null && Number.isFinite(n));
    const finiteHis = binBounds.map((b) => b[1]).filter((n): n is number => n != null && Number.isFinite(n));
    const axisLo = Math.min(...finiteLos, ...(values.length ? [lo] : []));
    const axisHi = Math.max(...finiteHis, ...(values.length ? [hi] : []));
    const axisSpan = axisHi - axisLo;
    const [left, right] = scene.x.range;
    if (Number.isFinite(axisSpan) && axisSpan > 0 && Number.isFinite(left) && Number.isFinite(right)) {
      const toPx = (v: number): number => left + ((v - axisLo) / axisSpan) * (right - left);
      // The bar-width slider (plot.barWidth) puts gaps between the bars: shrink each bar around
      // its bin centre, so the gap is honoured in proportional mode too, not just categorical.
      const gap = Math.min(1, Math.max(0.1, plot.barWidth ?? 1));
      for (const m of scene.series[0]?.marks ?? []) {
        const idx = Number(String(m.rowId).replace("bin-", ""));
        if (!Number.isInteger(idx) || idx < 0 || idx >= binBounds.length || !m.bar) continue;
        const x0 = toPx(binBounds[idx]![0] ?? axisLo);
        const full = Math.max(0, toPx(binBounds[idx]![1] ?? axisHi) - x0);
        const w = full * gap;
        m.bar = { ...m.bar, x: x0 + (full - w) / 2, w };
        m.cx = x0 + full / 2;
      }
      const widthsP = binBounds.map(([l, h]) => (l != null && h != null ? h - l : Infinity)).filter((w) => Number.isFinite(w) && w > 0);
      const decm = edgeDecimals(widthsP.length ? Math.min(...widthsP) : 1);
      const edgeVals = [...new Set([axisLo, axisHi, ...finiteLos, ...finiteHis])]
        .filter((v) => v >= axisLo - 1e-9 && v <= axisHi + 1e-9)
        .sort((a, b) => a - b);
      const ticks = edgeVals.map((v) => ({ value: v, pos: toPx(v), label: String(Number(v.toFixed(Math.max(0, decm)))), minor: false }));
      scene.x = { ...scene.x, type: "linear", domain: [axisLo, axisHi], ticks };
    }
  }
  // A histogram is bars; the per-bar data-point dots are off unless asked for.
  // Remove both the marker symbol and any scatter-overlay points the forwarded style brought in.
  if (hcfg.showPoints !== true) {
    for (const s of scene.series) {
      s.symbol = "none";
      for (const m of s.marks) if (m.points) delete m.points;
    }
  }
  // Draw the planned distribution curves (see `curvePlan` above) now that the bars are placed.
  // When both are on, the normal curve is dashed so a reader can tell them apart.
  const distributionCurves: DistributionCurveScene[] = [];
  if (plan && (plan.normal || plan.density)) {
    // Map a bin index → its bar centre pixel (works in both categorical + proportional modes,
    // since the bars are placed by this point); a linear data→px comes from the ends.
    const cxByBin = new Map<number, number>();
    for (const m of scene.series[0]?.marks ?? []) {
      const idx = Number(String(m.rowId).replace("bin-", ""));
      if (Number.isInteger(idx) && idx >= 0 && idx < binBounds.length) cxByBin.set(idx, m.cx);
    }
    const centerOf = (i: number): number => (binBounds[i]![0]! + binBounds[i]![1]!) / 2;
    const keys = [...cxByBin.keys()];
    if (keys.length >= 2) {
      const i0 = Math.min(...keys), iN = Math.max(...keys);
      const c0 = centerOf(i0), cN = centerOf(iN);
      const px0 = cxByBin.get(i0)!, pxN = cxByBin.get(iN)!;
      const xPx = (v: number): number => (cN === c0 ? px0 : px0 + ((v - c0) / (cN - c0)) * (pxN - px0));
      const [yr0, yr1] = scene.y.range;
      const [yd0, yd1] = scene.y.domain;
      const yPx = (h: number): number => yr0 + ((h - yd0) / ((yd1 - yd0) || 1)) * (yr1 - yr0);
      const top = scene.plot.y;
      // A pdf sampled over the bins' span → one SVG path. The axis was grown to hold the peak;
      // the clamp only guards a user-pinned axis max (never draw above the box).
      const pathFor = (pdfAt: number[]): string =>
        `M${plan.xs.map((x, k) => `${xPx(x).toFixed(2)},${Math.max(top, yPx(plan.scaleH * pdfAt[k]!)).toFixed(2)}`).join(" L")}`;
      if (plan.normal) {
        distributionCurves.push({
          path: pathFor(plan.normal),
          color: hcfg.normalCurveColor ?? "#c0392b",
          width: 2,
          dash: plan.density ? dashArray("dashed", 2) : null,
          label: "normal",
        });
      }
      if (plan.density) {
        distributionCurves.push({ path: pathFor(plan.density), color: hcfg.densityCurveColor ?? "#1f6f8b", width: 2, dash: null, label: "density" });
      }
    }
  }
  return { ...scene, kind: "histogram", ...(distributionCurves.length ? { distributionCurves } : {}), warnings: [...scene.warnings, ...extraWarn] };
}

/** Round a raw bin width up to a tidy 1·2·2.5·5·10 × 10ⁿ value so histogram edges
 *  land on round numbers (e.g. 0–10, 10–20) rather than 6.142857…-wide bins. */
function niceBinWidth(raw: number): number {
  if (!(raw > 0) || !Number.isFinite(raw)) return 1;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const norm = raw / mag; // [1, 10)
  const nice = norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 2.5 ? 2.5 : norm <= 5 ? 5 : 10;
  return nice * mag;
}

/** Read a dataset's value in a row: the mean of its finite replicate cells (NaN if none). */
function datasetRowValue(ds: Dataset | undefined, row: Row): number {
  if (!ds) return NaN;
  const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
}

/** Assemble a complete marker SeriesScene from a style + colour + its marks (shared by
 *  the bespoke marker-path builders: forest, Bland-Altman). */
function markerSeries(
  id: NodeId,
  name: string,
  style: SeriesStyle | undefined,
  color: string,
  symbol: SymbolShape,
  symbolSize: number,
  marks: MarkScene[],
): SeriesScene {
  return {
    id, name, color, linePath: "",
    symbol: style?.symbol ?? symbol, symbolSize: style?.symbolSize ?? symbolSize,
    ...resolveSymbol(style, color),
    borderWidth: style?.borderWidth ?? 1.5, lineWidth: style?.lineWidth ?? 2, dash: null,
    errorCaps: style?.errorCaps ?? true, errorDir: style?.errorDir ?? "both",
    ...seriesExtras(style, color, style?.lineWidth ?? 2, style?.symbolSize ?? symbolSize, 1),
    marks,
  };
}

/** The "sets" membership rule, shared by the Venn + UpSet builders: any non-empty,
 *  non-zero cell makes the row a member of that column's set. */
function setCellIsMember(v: unknown): boolean {
  if (v == null) return false;
  const s = String(v).trim();
  if (s === "") return false;
  const n = Number(s);
  return Number.isNaN(n) ? true : n !== 0;
}

/** Per-row membership bitmasks over `sets` → exclusive-combination counts (bitmask → count;
 *  bit i = sets[i]) plus the union size (rows in at least one set). Shared by Venn + UpSet. */
function setMembershipCounts(
  table: DataTable,
  sets: { replicates: NodeId[] }[],
): { zoneCounts: Map<number, number>; union: number } {
  const zoneCounts = new Map<number, number>();
  let union = 0;
  for (const row of table.rows) {
    let mask = 0;
    sets.forEach((ds, i) => {
      if (ds.replicates.some((cid) => setCellIsMember(row.cells[cid]))) mask |= 1 << i;
    });
    if (mask === 0) continue;
    union += 1;
    zoneCounts.set(mask, (zoneCounts.get(mask) ?? 0) + 1);
  }
  return { zoneCounts, union };
}

/** Zone/combination key: letters in set order ("A" · "AB" · "ABC" …). */
function setZoneKey(mask: number, nSets: number): string {
  let k = "";
  for (let i = 0; i < nSets; i++) if (mask & (1 << i)) k += String.fromCharCode(65 + (i % 26));
  return k;
}

/** Two-circle intersection (lens) area — shared by the proportional Venn's solver and its
 *  accuracy check. Nested → the smaller disc; separated → 0. */
function vennLensArea(r1: number, r2: number, d: number): number {
  if (d >= r1 + r2) return 0;
  if (d <= Math.abs(r1 - r2)) return Math.PI * Math.min(r1, r2) ** 2;
  const a1 = r1 * r1 * Math.acos((d * d + r1 * r1 - r2 * r2) / (2 * d * r1));
  const a2 = r2 * r2 * Math.acos((d * d + r2 * r2 - r1 * r1) / (2 * d * r2));
  const a3 = 0.5 * Math.sqrt((-d + r1 + r2) * (d + r1 - r2) * (d - r1 + r2) * (d + r1 + r2));
  return a1 + a2 - a3;
}

/** Centre distance at which two discs' lens equals `target` — bisection on the monotone
 *  lens(d). Handles the Euler ends: target ≥ smaller disc → nested; target ≤ 0 → apart. */
function vennSolveDistance(r1: number, r2: number, target: number): number {
  const rMin = Math.min(r1, r2);
  if (target <= 0) return r1 + r2 + rMin * 0.25; // disjoint, with visible daylight
  if (target >= Math.PI * rMin * rMin - 1e-9) return Math.abs(r1 - r2) * 0.999; // subset → nested
  let lo = Math.abs(r1 - r2);
  let hi = r1 + r2;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    if (vennLensArea(r1, r2, mid) > target) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

/**
 * Venn / Euler diagram: 2–3 discs from a "sets" membership table (row = item, one column per
 * set, non-empty-and-non-zero cell = member), every exclusive zone printing its count.
 * Classic = equal circles in the textbook arrangement. Proportional = areas ∝ counts —
 * exact for two sets (closed-form lens + bisection), best-fit for three (pairwise-exact
 * distances, third centre by trilateration) with a warning when the drawn zones
 * misstate the counts (three circles cannot always be faithful). Zone label spots and the
 * accuracy check share one grid-sampling pass. Set colours are the per-dataset series colours.
 */
/**
 * The Venn fills its figure. The drawing grows inside the box it is given. Reserving a set-name
 * strip above and below the discs whether or not a name sits there would make the discs smaller
 * than the figure allows.
 *
 * The drawing's extent is the discs (they scale with s) plus the set names outside them (fixed pixels),
 * so two builds give each side as a straight line in s. Solve for the largest s that fits the plot rect
 * on both sides, centre the whole drawing, and check with one more build.
 */
function buildVennScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const measure = options.measure ?? estimateWidth;
  const base = vennSceneAt(table, plot, options);
  const r0 = base.venn?.circles[0]?.r;
  const unitR = vennSceneAt(table, plot, options, { s: 1, dx: 0, dy: 0 }).venn?.circles[0]?.r;
  if (!r0 || !unitR) return base;
  const s0 = r0 / unitR;
  const probe = (s: number, dx = 0, dy = 0) => {
    const scene = vennSceneAt(table, plot, options, { s, dx, dy });
    return { scene, e: vennExtent(scene, measure) };
  };
  const a = probe(s0 * 0.5), b = probe(s0);
  const rect = base.plot;
  if (!a.e || !b.e) return base;
  const sFor = (spanA: number, spanB: number, room: number): number => {
    const slope = (spanB - spanA) / (s0 * 0.5);
    return slope > 1e-9 ? (room - (spanA - slope * s0 * 0.5)) / slope : Infinity;
  };
  const sMin = s0 * 0.2;
  let s = Math.max(sMin, Math.min(sFor(a.e.x1 - a.e.x0, b.e.x1 - b.e.x0, rect.width), sFor(a.e.y1 - a.e.y0, b.e.y1 - b.e.y0, rect.height)));
  for (let pass = 0; pass < 6; pass++) {
    const at = probe(s);
    if (!at.e) break;
    const dx = rect.x + (rect.width - (at.e.x1 - at.e.x0)) / 2 - at.e.x0;
    const dy = rect.y + (rect.height - (at.e.y1 - at.e.y0)) / 2 - at.e.y0;
    const got = probe(s, dx, dy);
    if (!got.e) break;
    const fits = got.e.x0 >= rect.x - 0.5 && got.e.y0 >= rect.y - 0.5 && got.e.x1 <= rect.x + rect.width + 0.5 && got.e.y1 <= rect.y + rect.height + 0.5;
    if (fits || s <= sMin) return got.scene;
    s = Math.max(sMin, s * Math.min(rect.width / (got.e.x1 - got.e.x0), rect.height / (got.e.y1 - got.e.y0)) * 0.995);
  }
  return base;
}

/** The drawn extent of a Venn scene: the discs, the set names (centred on their baseline) and the zone
 *  counts (centred, baseline 0.34·size below the spot) — both in the legend font, as PlotFigure draws
 *  them. Drag offsets are the user's own placement and are not part of the fit. */
function vennExtent(s: PlotScene, measure: (text: string, px: number) => number): { x0: number; y0: number; x1: number; y1: number } | undefined {
  const v = s.venn;
  if (!v || v.circles.length === 0) return undefined;
  const fs = s.fonts.legend.size;
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  const pt = (x: number, y: number): void => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); };
  const text = (t: string, cx: number, baseline: number): void => {
    if (!t) return;
    const hw = measure(t, fs) / 2;
    pt(cx - hw, baseline - fs * 0.8);
    pt(cx + hw, baseline + fs * 0.25);
  };
  for (const c of v.circles) {
    pt(c.cx - c.r, c.cy - c.r);
    pt(c.cx + c.r, c.cy + c.r);
    text(c.label, c.labelX, c.labelY);
  }
  for (const z of v.zones) text(z.text, z.labelX, z.labelY + fs * 0.34);
  return { x0, y0, x1, y1 };
}

function vennSceneAt(table: DataTable, plot: Plot, options: BuildPlotSceneOptions, fit?: { s: number; dx: number; dy: number }): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.venn ?? {};

  // Hiding a set column removes its disc, as hiding a series does on every chart.
  const all = visibleDatasets(table, plot);
  const sets = all.slice(0, 3);
  if (all.length > 3) {
    warnings.push(
      `A Venn diagram is unreadable past three sets — ${all.slice(3).map((d) => `"${d.name}"`).join(", ")} ${all.length === 4 ? "is" : "are"} not drawn. The UpSet plot shows any number of sets.`,
    );
  }
  if (sets.length === 0) warnings.push("No set columns to draw.");

  // Membership + exclusive-zone counts: the shared "sets" rule (setCellIsMember /
  // setMembershipCounts — one home, used by the UpSet plot too).
  const zoneKey = (mask: number): string => setZoneKey(mask, sets.length);
  const { zoneCounts, union } = setMembershipCounts(table, sets);
  const setTotal = (i: number): number => {
    let t = 0;
    for (const [mask, c] of zoneCounts) if (mask & (1 << i)) t += c;
    return t;
  };
  const pairCount = (i: number, j: number): number => {
    let t = 0;
    for (const [mask, c] of zoneCounts) if (mask & (1 << i) && mask & (1 << j)) t += c;
    return t;
  };

  // --- unit-space geometry -------------------------------------------------------------
  interface UC { x: number; y: number; r: number }
  let unit: UC[];
  const proportional = cfg.proportional ?? false;
  if (!proportional || sets.length < 2) {
    // Classic: equal discs in the textbook arrangement.
    if (sets.length <= 1) unit = [{ x: 0, y: 0, r: 1 }].slice(0, sets.length);
    else if (sets.length === 2) unit = [{ x: -0.62, y: 0, r: 1 }, { x: 0.62, y: 0, r: 1 }];
    else {
      const cd = 0.66;
      unit = [90, 210, 330].map((deg) => ({ x: cd * Math.cos((deg * Math.PI) / 180), y: -cd * Math.sin((deg * Math.PI) / 180), r: 1 }));
    }
  } else {
    // Proportional: unit area = one item. An empty set keeps a small visible disc.
    const rOf = (i: number): number => Math.sqrt(Math.max(setTotal(i), 0.35) / Math.PI);
    const rs = sets.map((_s, i) => rOf(i));
    if (sets.length === 2) {
      const d = vennSolveDistance(rs[0]!, rs[1]!, pairCount(0, 1));
      unit = [{ x: 0, y: 0, r: rs[0]! }, { x: d, y: 0, r: rs[1]! }];
    } else {
      const d01 = vennSolveDistance(rs[0]!, rs[1]!, pairCount(0, 1));
      const d02 = vennSolveDistance(rs[0]!, rs[2]!, pairCount(0, 2));
      const d12 = vennSolveDistance(rs[1]!, rs[2]!, pairCount(1, 2));
      // Trilateration; an impossible triangle clamps and the sampling pass below reports it.
      const x3 = (d02 * d02 - d12 * d12 + d01 * d01) / (2 * d01);
      const y3sq = d02 * d02 - x3 * x3;
      const y3 = Math.sqrt(Math.max(0, y3sq));
      unit = [{ x: 0, y: 0, r: rs[0]! }, { x: d01, y: 0, r: rs[1]! }, { x: x3, y: y3, r: rs[2]! }];
    }
  }

  // --- fit the discs into the content box ----------------------------------------------
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  // No flat strip for the set names above and below: a name sits outside a disc only on some sides (the lower
  // names often sit inside their discs, and a flat strip below would be empty).
  // buildVennScene measures where the names land and sizes the discs so everything reaches this rect.
  const marginL = pad.l + 10;
  const marginR = pad.r + 10;
  const marginB = pad.b + 6;
  // No effectiveWidth/Height here: a venn has no axes, so the panel-align axis-length
  // overrides must not shrink it — it tiles by its outer box (FOOTPRINT_ALIGN, measured).
  const plotX = marginL;
  const plotY = topPad > 0 ? topPad + 6 : DEFAULTS.marginTop;
  const plotW = Math.max(1, width - marginL - marginR);
  const plotH = Math.max(1, height - plotY - marginB);
  const bb = unit.length
    ? {
        x1: Math.min(...unit.map((c) => c.x - c.r)),
        y1: Math.min(...unit.map((c) => c.y - c.r)),
        x2: Math.max(...unit.map((c) => c.x + c.r)),
        y2: Math.max(...unit.map((c) => c.y + c.r)),
      }
    : { x1: -1, y1: -1, x2: 1, y2: 1 };
  const s = fit ? fit.s : Math.min(plotW / Math.max(1e-9, bb.x2 - bb.x1), plotH / Math.max(1e-9, bb.y2 - bb.y1));
  const ox = plotX + (plotW - (bb.x2 - bb.x1) * s) / 2 - bb.x1 * s + (fit?.dx ?? 0);
  const oy = plotY + (plotH - (bb.y2 - bb.y1) * s) / 2 - bb.y1 * s + (fit?.dy ?? 0);
  const px = (c: UC): { cx: number; cy: number; r: number } => ({ cx: ox + c.x * s, cy: oy + c.y * s, r: c.r * s });
  const discs = unit.map(px);

  // --- one sampling pass: zone label spots + the proportional accuracy check ------------
  const GRID = 110;
  const zoneSum = new Map<number, { n: number; sx: number; sy: number }>();
  if (discs.length) {
    const x1 = Math.min(...discs.map((c) => c.cx - c.r));
    const x2 = Math.max(...discs.map((c) => c.cx + c.r));
    const y1 = Math.min(...discs.map((c) => c.cy - c.r));
    const y2 = Math.max(...discs.map((c) => c.cy + c.r));
    for (let gy = 0; gy < GRID; gy++) {
      for (let gx = 0; gx < GRID; gx++) {
        const X = x1 + ((gx + 0.5) / GRID) * (x2 - x1);
        const Y = y1 + ((gy + 0.5) / GRID) * (y2 - y1);
        let mask = 0;
        discs.forEach((c, i) => {
          if ((X - c.cx) ** 2 + (Y - c.cy) ** 2 <= c.r * c.r) mask |= 1 << i;
        });
        if (mask === 0) continue;
        const acc = zoneSum.get(mask) ?? { n: 0, sx: 0, sy: 0 };
        acc.n += 1;
        acc.sx += X;
        acc.sy += Y;
        zoneSum.set(mask, acc);
      }
    }
  }
  const totalSamples = [...zoneSum.values()].reduce((a, z) => a + z.n, 0) || 1;
  if (proportional && sets.length === 3 && union > 0) {
    // Accuracy: two ways a drawing can misstate the counts: quantitative drift (a zone's
    // area share far from its count share) and qualitative mismatch (a zone drawn that has
    // no members — its printed 0 sits in visible area — or a counted zone circles could not
    // open at all). Either produces the warning; pairwise overlaps stay exact.
    let worst = 0;
    let qualitative = false;
    const masks = new Set<number>([...zoneCounts.keys(), ...zoneSum.keys()]);
    for (const mask of masks) {
      const drawn = (zoneSum.get(mask)?.n ?? 0) / totalSamples;
      const want = (zoneCounts.get(mask) ?? 0) / union;
      worst = Math.max(worst, Math.abs(drawn - want));
      if ((want === 0 && drawn > 0.02) || (want > 0 && drawn === 0)) qualitative = true;
    }
    if (worst > 0.06 || qualitative) {
      warnings.push("Three circles cannot draw these overlaps exactly — zone areas are a best-fit approximation of the counts (pairwise overlaps are exact).");
    }
  }

  // --- scene parts ----------------------------------------------------------------------
  const offsets = cfg.labelOffsets ?? {};
  const centreX = discs.length ? discs.reduce((a, c) => a + c.cx, 0) / discs.length : plotX + plotW / 2;
  const centreY = discs.length ? discs.reduce((a, c) => a + c.cy, 0) / discs.length : plotY + plotH / 2;
  const circles = sets.map((ds, i) => {
    const c = discs[i]!;
    const color = plot.seriesStyles?.[ds.id]?.color ?? seriesColor(i, palette);
    // Label just outside the disc, away from the diagram centre (top disc labels upward).
    // Base anchor only — the stored drag offset rides separately (labelOff) so a second
    // drag composes with the first instead of restarting from zero.
    const ang = Math.atan2(c.cy - centreY, c.cx - centreX);
    const lx = c.cx + Math.cos(ang) * (c.r * 0.55);
    const ly = c.cy + Math.sin(ang) * (c.r + fonts.legend.size * 0.9) + (Math.sin(ang) < 0 ? -2 : fonts.legend.size * 0.6);
    return {
      setId: ds.id,
      label: ds.name,
      cx: c.cx,
      cy: c.cy,
      r: c.r,
      color,
      fillOpacity: cfg.fillOpacity ?? 0.35,
      outline: cfg.outlineColor ?? color,
      outlineWidth: cfg.outlineWidth ?? 1.5,
      labelX: lx,
      labelY: ly,
      ...(offsets[ds.id] ? { labelOff: offsets[ds.id] } : {}),
    };
  });
  const showCounts = cfg.showCounts ?? true;
  const zones: NonNullable<PlotScene["venn"]>["zones"] = [];
  const allMasks = new Set<number>([...zoneCounts.keys(), ...zoneSum.keys()]);
  for (const mask of [...allMasks].sort((a, b) => a - b)) {
    const count = zoneCounts.get(mask) ?? 0;
    if (!showCounts && count === 0) continue;
    const acc = zoneSum.get(mask);
    // A counted zone circles could not draw (area 0): park its label between the members.
    const members = sets.map((_s, i) => i).filter((i) => mask & (1 << i));
    const fx = acc ? acc.sx / acc.n : members.reduce((a, i) => a + discs[i]!.cx, 0) / Math.max(1, members.length);
    const fy = acc ? acc.sy / acc.n : members.reduce((a, i) => a + discs[i]!.cy, 0) / Math.max(1, members.length);
    zones.push({
      key: zoneKey(mask),
      count,
      text: showCounts ? `${count}${(cfg.showPercents ?? false) && union > 0 ? ` (${Math.round((100 * count) / union)}%)` : ""}` : "",
      labelX: fx,
      labelY: fy,
    });
  }

  const leg = resolveLegend(plot, [], measure, fonts.legend.size, width);
  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "venn",
    fonts,
    venn: { circles, zones },
    warnings,
  };
}

/**
 * Polar histogram / wind rose: the first value column is an angle in degrees (wrapped
 * mod 360), binned into `sectors` equal angular bins — core `histogram()` over [0, 360),
 * the same maths as the linear histogram — and each bin's count drawn as a wedge from the
 * centre. An optional second value column (magnitude) stacks each wedge into equal-width
 * bands from 0 to the maximum, colour-ramped from the angle series' colour, with a
 * band-range legend. Wedges are bins (many rows each, never series marks): a wedge click
 * selects the chart-section. Ring circles carry the count ladder; direction labels
 * (N/NE/… or degree marks) are the angular axis's ticks. No effectiveWidth/Height —
 * axis-less box tiling (FOOTPRINT_ALIGN, measured).
 */
function buildRoseScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  let fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.rose ?? {};
  const compass = cfg.compass ?? true;
  const sectors = Math.max(4, Math.min(36, Math.round(cfg.sectors ?? 16)));
  const bandsWanted = Math.max(1, Math.min(8, Math.round(cfg.bands ?? 4)));

  const datasets = tableDatasets(table);
  const angleDs = datasets[0];
  // The magnitude is the second value column when it holds any numbers; a text column
  // there is a label column, not a misplaced magnitude.
  const magDs = datasets[1] && table.rows.some((r) => Number.isFinite(datasetRowValue(datasets[1]!, r))) ? datasets[1] : undefined;
  if (!angleDs) warnings.push("Polar histogram needs a value column of angles (degrees).");
  const extras = datasets.slice(2).filter((d) => table.rows.some((r) => Number.isFinite(datasetRowValue(d, r))));
  if (extras.length > 0)
    warnings.push(`Only the first two value columns are read (angle, magnitude) — ${extras.map((d) => `"${d.name}"`).join(", ")} ${extras.length === 1 ? "is" : "are"} not drawn.`);

  // One (angle, magnitude) pair per row; angles wrap mod 360, angle-less rows are counted.
  const obs: { a: number; m: number | null }[] = [];
  let noAngle = 0;
  let noMag = 0;
  if (angleDs) {
    for (const row of table.rows) {
      const raw = datasetRowValue(angleDs, row);
      const mRaw = magDs ? datasetRowValue(magDs, row) : NaN;
      const rowBlank = !Number.isFinite(raw) && !Number.isFinite(mRaw);
      if (!Number.isFinite(raw)) {
        if (!rowBlank) noAngle++;
        continue;
      }
      const a = ((raw % 360) + 360) % 360;
      if (magDs && !Number.isFinite(mRaw)) noMag++;
      obs.push({ a, m: magDs && Number.isFinite(mRaw) ? mRaw : null });
    }
  }
  if (noAngle > 0)
    warnings.push(`${noAngle} ${noAngle === 1 ? "row has" : "rows have"} no usable angle (a number, in degrees) and ${noAngle === 1 ? "is" : "are"} not drawn.`);
  if (noMag > 0)
    warnings.push(`${noMag} ${noMag === 1 ? "row has" : "rows have"} an angle but no magnitude — ${noMag === 1 ? "it joins" : "they join"} the lowest band.`);

  // Sector × band counts. Sector edges come straight from the angle arithmetic; band
  // edges are equal-width from 0 to the maximum magnitude (as `histogram()` bins).
  const bands = magDs ? bandsWanted : 1;
  const magMax = magDs ? Math.max(1e-9, ...obs.map((o) => o.m ?? 0)) : 1;
  const counts: number[][] = Array.from({ length: sectors }, () => new Array<number>(bands).fill(0));
  for (const o of obs) {
    const si = Math.min(sectors - 1, Math.floor((o.a / 360) * sectors));
    const bi = magDs && o.m != null ? Math.min(bands - 1, Math.floor((o.m / magMax) * bands)) : 0;
    counts[si]![bi]! += 1;
  }
  const sectorTotals = counts.map((c) => c.reduce((a, b) => a + b, 0));
  const maxCount = Math.max(0, ...sectorTotals);
  if (obs.length === 0 && table.rows.length > 0 && angleDs) warnings.push("No row has a usable angle to bin.");
  // Cross-check the sector totals against core histogram() on the same angles — two
  // implementations of one binning must never disagree.
  if (obs.length > 0) {
    const ref = histogram(obs.map((o) => o.a), { bins: sectors, range: [0, 360] });
    if (ref.length === sectors && ref.some((b, i) => b.count !== sectorTotals[i])) {
      warnings.push("The sector counts do not match a second count of the same angles. This is a program error — please report it.");
    }
  }

  // Legend (band ranges) before the box so the right margin reserves its room.
  const base = (angleDs ? plot.seriesStyles?.[angleDs.id]?.color : undefined) ?? seriesColor(0, palette);
  // Bands ramp from a light tint up to the pure series colour (the strongest band is the
  // series colour) — so a preset's palette reaches the ink unchanged.
  // A band's own colour (Chart type > Polar histogram, `bandColors`) wins over its shade of the base.
  const bandColor = (bi: number): string =>
    bands === 1 ? base : cfg.bandColors?.[String(bi)] ?? mix("#ffffff", base, 0.35 + (0.65 * (bi + 1)) / bands);
  const fmtMag = (v: number): string => String(Number(v.toFixed(2)));
  const bandRanges = magDs
    ? Array.from({ length: bands }, (_x, bi) => ({ lo: (bi * magMax) / bands, hi: ((bi + 1) * magMax) / bands, color: bandColor(bi) }))
    : [];
  const rawLegend: LegendEntry[] = bands > 1
    // A rose draws wedges: each band's key is a wedge (keys follow their marks).
    ? bandRanges.map((b) => ({ label: `${fmtMag(b.lo)}–${fmtMag(b.hi)}`, color: b.color, swatch: "bar" as const, keyShape: "wedge" as const, select: { as: "section" as const, id: "Chart type" } }))
    : [];
  // --- the polar box (the venn rule: no effectiveWidth/Height) --------------------------
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const tickPx0 = fonts.tick.size;
  const legendPx0 = fonts.legend.size;
  const px10 = (px: number): number => Math.round(px * 10) / 10;
  /**
   * The polar box with the direction labels and the legend at text scale `k` - the one layout the fit tests and the
   * drawing uses. Two placements, the larger ring wins: beside the legend (centred left of its column), or - in a box too
   * narrow for that - below it across the full width, its "N" clear of the legend's bottom. The legend never moves.
   */
  const roseAt = (k: number) => {
    const tickPx = k < 1 ? px10(tickPx0 * k) : tickPx0;
    const legendPx = k < 1 ? px10(legendPx0 * k) : legendPx0;
    const lg = resolveLegend(plot, rawLegend, measure, legendPx, width);
    const labelBand = tickPx + 14; // direction labels ring the circle
    const marginL = pad.l + labelBand + 8;
    const marginR = pad.r + labelBand + 8 + lg.outsideRightWidth;
    const marginB = pad.b + labelBand + 4;
    const plotY = DEFAULTS.marginTop + topPad + labelBand;
    const plotW = Math.max(1, width - marginL - marginR);
    const plotH = Math.max(1, height - plotY - marginB);
    const beside = Math.min(plotW, plotH) / 2 - 4;
    const box = outsideRightLegendBox(lg.layout, lg.entries, marginL + plotW, plotY, legendPx);
    const fullW = Math.max(1, width - marginL - (pad.r + labelBand + 8));
    const top = box ? Math.min(plotY + plotH, box.y2 + 4 + labelBand) : plotY;
    const under = box ? Math.min(fullW, plotY + plotH - top) / 2 - 4 : -Infinity;
    const below = under > beside + 0.5;
    return {
      lg, plotX: marginL, plotY, plotW, plotH,
      maxR: Math.max(10, below ? under : beside),
      cx: below ? marginL + fullW / 2 : marginL + plotW / 2,
      cy: below ? (top + plotY + plotH) / 2 : plotY + plotH / 2,
    };
  };
  // The graph fills its box. In a box
  // much smaller than the rose's own size - a narrow figure card with Keep proportions off - the direction labels and
  // the legend at full size would take the width and the ring would fall to 13% of the box. So they shrink just enough
  // for the ring to span FILL of the box's shorter side, never below 8 px, saying so when that size was set on the graph.
  // At its own size and at the default 580×380 (65-73%) nothing shrinks.
  const FILL = 0.6;
  const fills = (k: number): boolean => (2 * roseAt(k).maxR) / Math.max(1, Math.min(width, height)) >= FILL;
  let textFit = 1;
  if (!fills(1)) {
    let lo = Math.min(1, (options.minTextPx ?? 8) / Math.max(1, Math.min(tickPx0, rawLegend.length ? legendPx0 : tickPx0)));
    let hi = 1;
    if (fills(lo)) {
      for (let i = 0; i < 16; i++) { const mid = (lo + hi) / 2; if (fills(mid)) lo = mid; else hi = mid; }
    }
    textFit = lo;
  }
  if (textFit < 1) {
    fonts = { ...fonts, tick: { ...fonts.tick, size: px10(tickPx0 * textFit) }, legend: { ...fonts.legend, size: px10(legendPx0 * textFit) } };
    if (plot.fonts?.tick?.size !== undefined) warnings.push(`Rose direction labels are drawn at ${fonts.tick.size}px, not the ${tickPx0}px asked for: the ring would be too small in this box. A larger figure will honour it.`);
  }
  const { lg: leg, plotX, plotY, plotW, plotH, maxR, cx, cy } = roseAt(textFit);

  // Radial count ladder: nice steps (1/2/5 · 10^k), topped at ≥ the fullest wedge.
  // Counts are integers, so the step is floored at 1 — without that floor an empty rose
  // (no usable angles) would collapse the step toward 1e-9 and the ring loop would allocate
  // until it runs out of memory.
  const rawStep = Math.max(1, maxCount) / 4;
  const magPow = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const norm = rawStep / magPow;
  const step = Math.max(1, magPow * (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10));
  const ringTop = Math.max(step, Math.ceil(Math.max(1, maxCount) / step) * step);
  const rOf = (count: number): number => (count / ringTop) * maxR;
  // The ring lines' own look (Chart type > Polar histogram). Written only when one is set, so an untouched rose
  // carries no ring style.
  const rs = plot.rose;
  const ringWidth = rs?.ringWidth ?? 1;
  const ringStyle = rs && (rs.ringShow !== undefined || rs.ringColor !== undefined || rs.ringWidth !== undefined || rs.ringDash !== undefined)
    ? { show: rs.ringShow ?? true, color: rs.ringColor ?? null, width: ringWidth, dash: dashArray(rs.ringDash ?? "solid", ringWidth) }
    : undefined;
  const rings: NonNullable<PlotScene["rose"]>["rings"] = [];
  for (let c = step; c <= ringTop + 1e-9; c += step) {
    const r = rOf(c);
    // Label inside its ring (just under the top) — outside, the outermost number would sit on
    // the "N" direction label.
    rings.push({ r, count: c, labelX: cx + 4, labelY: cy - r + fonts.tick.size + 1 });
  }

  // Point on the circle for a data angle: compass = 0° North, clockwise; math = 0° East, ccw.
  const pt = (aDeg: number, r: number): { x: number; y: number } => {
    const rad = (aDeg * Math.PI) / 180;
    return compass ? { x: cx + r * Math.sin(rad), y: cy - r * Math.cos(rad) } : { x: cx + r * Math.cos(rad), y: cy - r * Math.sin(rad) };
  };
  const sweep = compass ? 1 : 0;
  const GAP = sectors <= 24 ? 1.5 : 0.75; // degrees of breathing room between wedges
  const wedgePath = (a0: number, a1: number, r0: number, r1: number): string => {
    const p0o = pt(a0, r1);
    const p1o = pt(a1, r1);
    if (r0 <= 0.5) {
      return `M${cx.toFixed(2)},${cy.toFixed(2)} L${p0o.x.toFixed(2)},${p0o.y.toFixed(2)} A${r1.toFixed(2)},${r1.toFixed(2)} 0 0 ${sweep} ${p1o.x.toFixed(2)},${p1o.y.toFixed(2)} Z`;
    }
    const p0i = pt(a0, r0);
    const p1i = pt(a1, r0);
    return `M${p0i.x.toFixed(2)},${p0i.y.toFixed(2)} L${p0o.x.toFixed(2)},${p0o.y.toFixed(2)} A${r1.toFixed(2)},${r1.toFixed(2)} 0 0 ${sweep} ${p1o.x.toFixed(2)},${p1o.y.toFixed(2)} L${p1i.x.toFixed(2)},${p1i.y.toFixed(2)} A${r0.toFixed(2)},${r0.toFixed(2)} 0 0 ${1 - sweep} ${p0i.x.toFixed(2)},${p0i.y.toFixed(2)} Z`;
  };

  const wedges: NonNullable<PlotScene["rose"]>["wedges"] = [];
  for (let si = 0; si < sectors; si++) {
    const a0 = (si * 360) / sectors + GAP / 2;
    const a1 = ((si + 1) * 360) / sectors - GAP / 2;
    const total = sectorTotals[si]!;
    const segments: NonNullable<PlotScene["rose"]>["wedges"][number]["segments"] = [];
    let cum = 0;
    for (let bi = 0; bi < bands; bi++) {
      const c = counts[si]![bi]!;
      if (c === 0) continue;
      segments.push({ band: bi, count: c, path: wedgePath(a0, a1, rOf(cum), rOf(cum + c)), color: bandColor(bi) });
      cum += c;
    }
    const mid = pt((a0 + a1) / 2, rOf(total) * 0.6);
    wedges.push({ index: si, count: total, midX: mid.x, midY: mid.y, outerR: rOf(total), segments });
  }

  // Angular tick labels: the 8 compass points, or degree marks every 45°.
  const COMPASS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];
  const directionLabels = Array.from({ length: 8 }, (_x, i) => {
    const a = i * 45;
    // Past the ring by a fixed 10 px plus the font's descent: the ring's outer value label sits
    // just inside the ring, and at a 30 px tick font the two boxes would otherwise meet.
    const p = pt(a, maxR + 12 + fonts.tick.size * TEXT_DESCENT);
    // Renamed / dragged on the graph: keyed by the label's own default words.
    const key = compass ? COMPASS[i]! : `${a}°`;
    const own = cfg.directionText?.[key];
    const off = cfg.directionOffsets?.[key];
    return { text: own ?? key, x: p.x, y: p.y, ...(own !== undefined ? { key } : {}), ...(off ? { off } : {}) };
  });

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "rose",
    fonts,
    warnings,
    rose: { cx, cy, maxR, wedges, rings, directionLabels, bandRanges, ...(ringStyle ? { ringStyle } : {}) },
  };
}

/**
 * Ternary plot: each row a 3-part composition (the first three value columns by position —
 * as on the forest and funnel plots), normalized per row and drawn as one point inside an equilateral
 * triangle: P = a·A + b·B + c·C with corners A bottom-left, B bottom-right, C top. Edge
 * axes (counterclockwise convention): the first component reads down the left edge, the
 * second along the bottom, the third up the right. The triangular grid honours the standard
 * Plot.grid options (density = divisions, clamped 2–10). Points are a real marker series —
 * per-point styles + colour-by-column (DATA_DRIVEN_KINDS) — while the triangle, ticks,
 * grid and edge titles are `scene.ternary` chrome. No effectiveWidth/Height: an axis-less
 * kind tiles by its outer box (FOOTPRINT_ALIGN, measured).
 */
function ternarySceneAt(table: DataTable, plot: Plot, options: BuildPlotSceneOptions, fit?: { s: number; dx: number; dy: number }): PlotScene {
  const width = options.width ?? DEFAULTS.width;
  const height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.ternary ?? {};

  const datasets = tableDatasets(table);
  const comps = datasets.slice(0, 3);
  if (datasets.length < 3) warnings.push("Ternary plot needs three value columns — the composition's components.");
  else {
    // A column consumed by a colour/symbol binding is drawn (as the encoding), and a text
    // column past the composition is a grouping/label column (usable for colour by data), not a
    // misplaced component — only unused numeric extras get the not-drawn warning.
    const bound = new Set<string>();
    for (const st of Object.values(plot.seriesStyles ?? {})) {
      if (st?.colorFromColumn) bound.add(st.colorFromColumn);
      if (st?.symbolFromColumn) bound.add(st.symbolFromColumn);
    }
    const unused = datasets.slice(3).filter(
      (d) => !bound.has(d.id) && table.rows.some((row) => Number.isFinite(datasetRowValue(d, row))),
    );
    if (unused.length > 0)
      warnings.push(`Only the first three value columns form the composition — ${unused.map((d) => `"${d.name}"`).join(", ")} ${unused.length === 1 ? "is" : "are"} not drawn.`);
  }

  const xCol = xColumn(table);
  // Normalize per row (percentages, fractions and raw amounts all enter); a row with a
  // missing/negative component or a zero sum is not placeable — counted, never silent.
  // Fully blank rows (sheet tails) are skipped without counting.
  interface TPoint { id: NodeId; label: string; a: number; b: number; c: number }
  const pts: TPoint[] = [];
  let dropped = 0;
  if (comps.length === 3) {
    table.rows.forEach((row, i) => {
      const vals = comps.map((d) => datasetRowValue(d, row));
      if (vals.every((v) => !Number.isFinite(v))) return;
      const sum = (vals[0] ?? NaN) + (vals[1] ?? NaN) + (vals[2] ?? NaN);
      if (!vals.every((v) => Number.isFinite(v) && v >= 0) || !(sum > 0)) {
        dropped++;
        return;
      }
      pts.push({
        id: row.id,
        label: xCol ? String(row.cells[xCol.id] ?? `Row ${i + 1}`) : `Row ${i + 1}`,
        a: vals[0]! / sum,
        b: vals[1]! / sum,
        c: vals[2]! / sum,
      });
    });
  }
  if (dropped > 0)
    warnings.push(`${dropped} ${dropped === 1 ? "row is" : "rows are"} not placeable (a missing or negative component, or a zero sum) and ${dropped === 1 ? "is" : "are"} not drawn.`);
  if (comps.length === 3 && pts.length === 0 && table.rows.length > 0 && dropped === table.rows.length)
    warnings.push("No row has a usable composition to place.");

  // Legend / colour bindings resolved before the box so the right margin can reserve room.
  const ddLeg = comps.length === 3 ? dataDrivenLegend(plot, comps.slice(0, 1), table, palette) : null;
  const leg = resolveLegend(plot, ddLeg ?? [], measure, fonts.legend.size, width);
  const cbarInfo = comps.length === 3 ? continuousColorInfo(plot, comps.slice(0, 1), table, palette) : null;
  const CB_BAR_W = 14;
  const colorbarMargin = cbarInfo ? CB_BAR_W + 60 : 0;
  if (leg.outsideRightWidth || colorbarMargin) leg.layout = { ...leg.layout, outsidePad: colorbarMargin };

  // --- fit the unit triangle into the content box (as the venn fits its box) -------------------
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const TICK = 6;
  const tickBand = TICK + 4 + fonts.tick.size; // tick + gap + label height/width estimate
  const titleBand = textBand(fonts.xAxisTitle.size, 6);
  // The plot rect is the room the drawing may use: the canvas inside a small edge gap and the legend /
  // colour-bar strip. The tick numbers and edge names are not reserved as flat strips here — the fit in
  // buildTernaryScene measures where they land and sizes the triangle so they reach this rect.
  const marginL = pad.l + 8;
  const marginR = pad.r + 8 + leg.outsideRightWidth + colorbarMargin;
  const marginB = pad.b + 6;
  const plotX = marginL;
  // The heading block (`topPad`) already ends where the title does; a further marginTop would leave a ~22px band
  // the fitted drawing could not use. With no heading, the usual top margin.
  const plotY = topPad > 0 ? topPad + 6 : DEFAULTS.marginTop;
  const plotW = Math.max(1, width - marginL - marginR);
  const plotH = Math.max(1, height - plotY - marginB);
  const H = Math.sqrt(3) / 2;
  const s = fit ? fit.s : Math.min(plotW, plotH / H);
  const triW = s;
  const triH = H * s;
  const ox = plotX + (plotW - triW) / 2 + (fit?.dx ?? 0);
  const oy = plotY + (plotH - triH) / 2 + (fit?.dy ?? 0);
  const A = { x: ox, y: oy + triH };
  const B = { x: ox + triW, y: oy + triH };
  const C = { x: ox + triW / 2, y: oy };
  const P = (a: number, b: number, c: number): { x: number; y: number } => ({
    x: a * A.x + b * B.x + c * C.x,
    y: a * A.y + b * B.y + c * C.y,
  });
  const G = { x: (A.x + B.x + C.x) / 3, y: (A.y + B.y + C.y) / 3 };
  const outward = (p: { x: number; y: number }): { x: number; y: number } => {
    const d = Math.hypot(p.x - G.x, p.y - G.y) || 1;
    return { x: (p.x - G.x) / d, y: (p.y - G.y) / d };
  };

  // --- ticks + grid ---------------------------------------------------------------------
  const divisions = Math.max(2, Math.min(10, Math.round(plot.grid?.density ?? 5)));
  const percent = cfg.percent ?? true;
  const fmtTick = (t: number): string => (percent ? String(Math.round(t * 100)) : String(Number(t.toFixed(2))));
  type TTick = NonNullable<PlotScene["ternary"]>["ticks"][number];
  const ticks: TTick[] = [];
  // Each component's scale runs along one edge, endpoints included (corners share labels —
  // the standard ternary look): first on the left (1 at A → 0 at C), second on the bottom
  // (0 at A → 1 at B), third on the right (0 at B → 1 at C).
  const edgeTick = (pt: { x: number; y: number }, edgeMid: { x: number; y: number }, label: string): TTick => {
    const o = outward(edgeMid);
    const lx = pt.x + o.x * (TICK + 4) + (o.x > 0.3 ? 2 : o.x < -0.3 ? -2 : 0);
    const ly = pt.y + o.y * (TICK + 4) + (o.y > 0.3 ? fonts.tick.size * 0.9 : fonts.tick.size * 0.3);
    return {
      x1: pt.x, y1: pt.y, x2: pt.x + o.x * TICK, y2: pt.y + o.y * TICK,
      label, lx, ly, anchor: o.x > 0.3 ? "start" : o.x < -0.3 ? "end" : "middle",
    };
  };
  const midAC = { x: (A.x + C.x) / 2, y: (A.y + C.y) / 2 };
  const midAB = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
  const midBC = { x: (B.x + C.x) / 2, y: (B.y + C.y) / 2 };
  for (let i = 0; i <= divisions; i++) {
    const t = i / divisions;
    ticks.push(edgeTick(P(t, 0, 1 - t), midAC, fmtTick(t))); // left: component 1 = t
    ticks.push(edgeTick(P(1 - t, t, 0), midAB, fmtTick(t))); // bottom: component 2 = t
    ticks.push(edgeTick(P(0, 1 - t, t), midBC, fmtTick(t))); // right: component 3 = t
  }
  const gridLines: NonNullable<PlotScene["ternary"]>["gridLines"] = [];
  if (plot.grid?.show ?? false) {
    for (let i = 1; i < divisions; i++) {
      const t = i / divisions;
      const seg = (p: { x: number; y: number }, q: { x: number; y: number }): void => {
        gridLines.push({ x1: p.x, y1: p.y, x2: q.x, y2: q.y });
      };
      seg(P(t, 1 - t, 0), P(t, 0, 1 - t)); // constant component 1
      seg(P(1 - t, t, 0), P(0, t, 1 - t)); // constant component 2
      seg(P(1 - t, 0, t), P(0, 1 - t, t)); // constant component 3
    }
  }
  const gridWidth = plot.grid?.width ?? 1;
  const gridStyle = {
    color: plot.grid?.color ?? "#c9ced4",
    width: gridWidth,
    dash: dashArray(plot.grid?.dash ?? "solid", gridWidth),
  };

  // --- edge titles: the composition column names (base anchor + separate drag offset) ---
  const offs = cfg.axisLabelOff ?? {};
  const titleAt = (ds: Dataset, edgeMid: { x: number; y: number }, angle: number): NonNullable<PlotScene["ternary"]>["axisTitles"][number] => {
    const o = outward(edgeMid);
    const r = tickBand + titleBand * 0.7;
    return {
      datasetId: ds.id, text: ds.name, angle,
      x: edgeMid.x + o.x * r, y: edgeMid.y + o.y * r + (o.y > 0.3 ? fonts.xAxisTitle.size * 0.4 : 0),
      ...(offs[ds.id] ? { off: offs[ds.id] } : {}),
    };
  };
  const axisTitles = comps.length === 3
    ? [titleAt(comps[0]!, midAC, -60), titleAt(comps[1]!, midAB, 0), titleAt(comps[2]!, midBC, 60)]
    : [];

  // --- the points: one real marker series anchored on the first composition column ------
  const style = comps[0] ? plot.seriesStyles?.[comps[0].id] : undefined;
  const color = style?.color ?? seriesColor(0, palette);
  const baseSize = style?.symbolSize ?? 6;
  const marks: MarkScene[] = pts.map((p, i) => {
    const q = P(p.a, p.b, p.c);
    // dx/dy = unit-triangle coords (x across, height fraction) — stable data-ish anchors.
    return { rowId: p.id, rowNumber: i + 1, dx: p.b + p.c / 2, dy: p.c, cx: q.x, cy: q.y, n: 1, label: p.label, symbolSize: baseSize };
  });
  const series: SeriesScene[] = comps.length === 3
    ? [markerSeries(comps[0]!.id, comps[0]!.name ?? "Composition", style, color, "circle", baseSize, marks)]
    : [];

  let colorbar: PlotScene["colorbar"];
  if (cbarInfo) {
    const barX = plotX + plotW + 14;
    const stops = ramps.barStops(cbarInfo.ramp, cbarInfo.base, "#1a1a1a", cbarInfo.rev, cbarInfo.shape);
    colorbar = { bar: { x: barX, y: oy, w: CB_BAR_W, h: triH }, stops, min: cbarInfo.lo, max: cbarInfo.hi, ...(cbarInfo.title ? { title: cbarInfo.title } : {}) };
  }

  const emptyAxis: AxisScene = { type: "linear", domain: [0, 1], range: [plotX, plotX + plotW], ticks: [], title: "" };
  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: emptyAxis,
    y: { ...emptyAxis, range: [plotY + plotH, plotY] },
    auto: { x: [0, 1], y: [0, 1] },
    series,
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations: fractionalAnnotations(plot, { x: plotX, y: plotY, width: plotW, height: plotH }, warnings),
    grid: { show: false, color: null, width: 1, dash: null, minor: false } satisfies GridScene,
    axisStyle: { frame: "none", tickDir: "none", tickLen: 0 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: "", y: "" },
    kind: "ternary",
    fonts,
    warnings,
    ...(colorbar ? { colorbar } : {}),
    ternary: { corners: [A, B, C], ticks, gridLines, gridStyle, axisTitles },
  };
}

/**
 * The ternary triangle fills its figure. The drawing grows inside the box it is
 * given. Reserving equal flat strips for the tick numbers and edge names left, right and below,
 * larger than those need, and fitting the triangle inside them would leave much of the figure
 * blank.
 *
 * The drawing's extent is the triangle (it scales with the side s) plus its tick numbers and edge names
 * (fixed pixels), so two builds give each side as a straight line in s. Solve for the largest s that
 * fits the plot rect on both sides, centre the whole drawing — names included — then build once more to
 * check and back off if it does not fit.
 */
function buildTernaryScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const measure = options.measure ?? estimateWidth;
  const probe = (s: number, dx = 0, dy = 0) => {
    const scene = ternarySceneAt(table, plot, options, { s, dx, dy });
    return { scene, e: ternaryExtent(scene, measure) };
  };
  const a = probe(100), b = probe(200);
  if (!a.e || !b.e) return ternarySceneAt(table, plot, options);
  const rect = b.scene.plot;
  const sFor = (spanA: number, spanB: number, room: number): number => {
    const slope = (spanB - spanA) / 100;
    return slope > 1e-9 ? (room - (spanA - slope * 100)) / slope : Infinity;
  };
  let s = Math.max(20, sFor(a.e.x1 - a.e.x0, b.e.x1 - b.e.x0, rect.width), 0);
  s = Math.max(20, Math.min(s, sFor(a.e.y1 - a.e.y0, b.e.y1 - b.e.y0, rect.height)));
  for (let pass = 0; pass < 6; pass++) {
    const at = probe(s);
    if (!at.e) break;
    const dx = rect.x + (rect.width - (at.e.x1 - at.e.x0)) / 2 - at.e.x0;
    const dy = rect.y + (rect.height - (at.e.y1 - at.e.y0)) / 2 - at.e.y0;
    const got = probe(s, dx, dy);
    if (!got.e) break;
    const fits = got.e.x0 >= rect.x - 0.5 && got.e.y0 >= rect.y - 0.5 && got.e.x1 <= rect.x + rect.width + 0.5 && got.e.y1 <= rect.y + rect.height + 0.5;
    if (fits || s <= 20) return got.scene;
    s = Math.max(20, s * Math.min(rect.width / (got.e.x1 - got.e.x0), rect.height / (got.e.y1 - got.e.y0)) * 0.995);
  }
  return ternarySceneAt(table, plot, options);
}

/** The drawn extent of a ternary scene: corners, tick marks, tick numbers (on their baseline, with their
 *  own anchor), edge names (centred on their baseline, turned about their anchor) and the points. Drag
 *  offsets are the user's own placement and are not part of the fit. Undefined when there is no triangle. */
function ternaryExtent(s: PlotScene, measure: (text: string, px: number) => number): { x0: number; y0: number; x1: number; y1: number } | undefined {
  const t = s.ternary;
  if (!t) return undefined;
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  const pt = (x: number, y: number): void => { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); };
  for (const c of t.corners) pt(c.x, c.y);
  const tick = s.fonts.tick.size;
  const title = s.fonts.xAxisTitle.size;
  for (const k of t.ticks) {
    pt(k.x2, k.y2);
    if (!k.label) continue;
    const w = measure(k.label, tick);
    const left = k.anchor === "start" ? k.lx : k.anchor === "end" ? k.lx - w : k.lx - w / 2;
    pt(left, k.ly - tick * 0.8);
    pt(left + w, k.ly + tick * 0.25);
  }
  for (const a of t.axisTitles) {
    const hw = measure(a.text, title) / 2;
    const rad = (a.angle * Math.PI) / 180;
    const c = Math.cos(rad), sn = Math.sin(rad);
    for (const [lx, ly] of [[-hw, -title * 0.8], [hw, -title * 0.8], [-hw, title * 0.25], [hw, title * 0.25]] as const) pt(a.x + lx * c - ly * sn, a.y + lx * sn + ly * c);
  }
  for (const m of s.series.flatMap((x) => x.marks)) {
    const r = (m.symbolSize ?? 6) / 2 + 1;
    pt(m.cx - r, m.cy - r);
    pt(m.cx + r, m.cy + r);
  }
  return Number.isFinite(x0) ? { x0, y0, x1, y1 } : undefined;
}

/** UpSet neutral ink: the default intersection-bar / matrix-dot colour (classic monochrome). */
const UPSET_INK = "#454c54";

/**
 * UpSet plot: the Venn's any-number-of-sets sibling on the same "sets" membership table.
 * Exclusive-intersection bars ride a real count Y axis and are built by the bar builder from
 * a synthesised one-row-per-intersection table (the histogram delegation pattern), so
 * yAxisLength consumption, hlines/data-anchored bands, manual brackets (from/to = 1-based
 * drawn columns) and the standard value-label machinery are all the bar's own. The
 * set-membership dot matrix (below, on the shared column grid) and the set-size bars (left)
 * are added as `scene.upset`; their room is reserved through the delegated plot's plotPad so
 * all four user pad sides stay honoured on top.
 */
function buildUpsetScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  const warnings: string[] = [];
  const cfg = plot.upset ?? {};
  const fonts = resolveFonts(plot);
  const measure = options.measure ?? estimateWidth;
  const pad = plotPadOf(plot);

  // Hiding a set column recomputes the intersections without it — the hide-series contract.
  const sets = visibleDatasets(table, plot);
  if (sets.length === 0) warnings.push("No set columns to draw.");
  const { zoneCounts } = setMembershipCounts(table, sets);

  // --- the intersection columns: exclusive combinations, sorted, filtered, capped ---------
  const popcount = (m: number): number => {
    let c = 0;
    for (let x = m; x; x >>= 1) c += x & 1;
    return c;
  };
  let masks: number[] = [...zoneCounts.keys()];
  if (cfg.showEmpty ?? false) {
    if (sets.length > 12) {
      warnings.push("Empty intersections are only enumerated up to 12 sets — showing the non-empty ones.");
    } else {
      masks = [];
      for (let m = 1; m < 1 << sets.length; m++) masks.push(m);
    }
  }
  const countOf = (m: number): number => zoneCounts.get(m) ?? 0;
  const minSize = cfg.minSize ?? 0;
  if (minSize > 0) masks = masks.filter((m) => countOf(m) >= minSize);
  const byDegree = (cfg.sortBy ?? "size") === "degree";
  masks.sort((a, b) =>
    byDegree
      ? popcount(a) - popcount(b) || countOf(b) - countOf(a) || a - b
      : countOf(b) - countOf(a) || popcount(a) - popcount(b) || a - b,
  );
  const cap = Math.max(1, Math.round(cfg.maxIntersections ?? 15));
  const totalCombos = masks.length;
  if (totalCombos > cap) {
    masks = masks.slice(0, cap);
    warnings.push(`Showing ${cap} of ${totalCombos} intersections — ${totalCombos - cap} hidden (raise "Max intersections" in the UpSet plot section).`);
  }
  const combos = masks.map((m) => ({
    mask: m,
    key: setZoneKey(m, sets.length),
    members: sets.map((_s, i) => i).filter((i) => m & (1 << i)),
    count: countOf(m),
  }));

  // --- reserve the matrix band (below) + the set-size/label region (left) via plotPad -----
  const rowFont = fonts.xTick; // the matrix REPLACES the x tick labels, so their font styles it
  const rowH = Math.max(16, rowFont.size + 8);
  // The count axis's "0" label sits on the baseline; the first set label must start below its
  // text band.
  const matrixGap = 6 + Math.ceil(fonts.yTick.size * 0.6);
  const matrixH = sets.length * rowH + matrixGap + 4;
  const showSetSizes = cfg.showSetSizes ?? true;
  const totals = sets.map((_s, i) => {
    let t = 0;
    for (const [m, c] of zoneCounts) if (m & (1 << i)) t += c;
    return t;
  });
  const maxLabelW = sets.length ? Math.max(...sets.map((ds) => measure(ds.name, rowFont.size))) : 0;
  const maxTotalW = showSetSizes && totals.length ? Math.max(...totals.map((t) => measure(String(t), rowFont.size))) : 0;
  const SET_BAR_W = showSetSizes ? 64 : 0;
  const leftW = SET_BAR_W + (showSetSizes ? maxTotalW + 10 : 0) + maxLabelW + 14;

  // --- delegate the bars to the bar builder over a synthesised table ----------------------
  const COUNT_ID = "__upsetn__";
  const synth: DataTable = {
    id: `${table.id}-upset`,
    kind: "column",
    name: table.name,
    columns: [
      { id: "__ixname__", name: "Intersection", role: "x" },
      { id: COUNT_ID, name: "Intersection size", role: "y" },
    ],
    rows: combos.map((c, i) => ({ id: `ix-${i}`, cells: { __ixname__: c.key, [COUNT_ID]: c.count } })),
  };
  const ySpec = plot.yAxis ?? {};
  let yPatch = ySpec;
  if (ySpec.scale && isLog(ySpec.scale)) {
    warnings.push("The count axis is linear — intersection sizes count items from 0, which a log axis cannot show.");
    yPatch = { ...ySpec, scale: "linear" };
  }
  const barPlot: Plot = {
    ...plot,
    kind: "bar",
    barLayout: "grouped",
    barOrientation: "vertical",
    barSort: "none", // columns are pre-sorted here; the bar option must not re-sort them
    barSeriesGroups: undefined,
    pointStyles: {},
    // barColor is the default; an explicit style stored under the count series' own id
    // still wins (the per-series contract — no builder drops seriesStyles).
    // (A series' own bar width is a bar-chart setting with no control here, so it is left out.)
    seriesStyles: { [COUNT_ID]: { ...plot.seriesStyles?.[COUNT_ID], color: plot.seriesStyles?.[COUNT_ID]?.color ?? cfg.barColor ?? UPSET_INK, barWidth: undefined } },
    legend: { ...(plot.legend ?? {}), show: false },
    yAxis: { ...yPatch, title: yPatch.title ?? "Intersection size" },
    // No x title band (the matrix is the labelling) and no category grouping — the
    // intersections are computed, not table categories (the control is withheld too).
    xAxis: { ...(plot.xAxis ?? {}), title: "", categoryGroups: undefined },
    plotPad: { top: pad.t, right: pad.r, bottom: pad.b + matrixH, left: pad.l + leftW },
  };
  /**
   * No margin reserved twice. The bar builder keeps its own margins on top of `plotPad`: a left one
   * for the count axis's numbers + title, and a bottom one for the category names this function then
   * deletes. Counted twice, they leave a blank band below the matrix and a
   * blank strip at the far left — the axis sits beside the bars, above the matrix, so it can share the
   * set-name region's width. Read the bar builder's own margins from a build, take them out of what
   * `plotPad` asks for (keeping an EDGE gap), and rebuild until they settle (the category-name band
   * can change with the plot's width).
   */
  const EDGE = 8;
  // Note: the shared room is the bar builder's margin at its own spacing. A Labels↔axis / Title↔labels gap
  // the user sets must still widen the margin by what they asked (the test "axis-bearing kinds honour the
  // Spacing options" in PlotFigure.matrix.test.tsx). Measuring the margin with the gap would let the set-name region
  // silently absorb it. So the margins are read from a build without those gaps, and the real build
  // keeps them on top.
  const noGap = (sp: AxisSpec | undefined): AxisSpec => ({ ...(sp ?? {}), tickLabelGap: undefined, titleGap: undefined });
  const buildWith = (left: number, bottom: number, spacing: boolean): PlotScene =>
    buildCategoricalScene(
      synth,
      { ...barPlot, ...(spacing ? {} : { xAxis: noGap(barPlot.xAxis), yAxis: noGap(barPlot.yAxis) }), plotPad: { top: pad.t, right: pad.r, bottom, left } },
      { ...options, barRowsAreCategories: true },
    );
  let padL = pad.l + leftW;
  let padB = pad.b + matrixH;
  for (let pass = 0; pass < 3; pass++) {
    const bare = buildWith(padL, padB, false);
    const ownLeft = bare.plot.x - padL;
    const ownBottom = bare.height - (bare.plot.y + bare.plot.height) - padB;
    const nextL = pad.l + Math.max(0, leftW + EDGE - ownLeft);
    const nextB = pad.b + Math.max(0, matrixH + EDGE - ownBottom);
    const settled = Math.abs(nextL - padL) < 0.5 && Math.abs(nextB - padB) < 0.5;
    padL = nextL;
    padB = nextB;
    if (settled) break;
  }
  const scene = buildWith(padL, padB, true);
  // The membership matrix is the category labelling — no x ticks under the bars.
  scene.x = { ...scene.x, ticks: [] };
  // A count has no replicates: remove the bar's per-point dot overlay (as the histogram does).
  for (const s of scene.series) {
    s.symbol = "none";
    for (const m of s.marks) if (m.points) delete m.points;
  }

  // --- matrix + set-size bar geometry ------------------------------------------------------
  const { x: plotX, y: plotY, width: plotW, height: plotH } = scene.plot;
  // The count axis's title runs its length down the bar plot; the generic cap fits it to the
  // canvas, which here continues into the matrix — at 40 px the title would reach the set
  // labels. Cap it to the bar plot's own height.
  {
    const yTitle = scene.y.title ?? "";
    const size = scene.y.titleFont ?? scene.fonts.yAxisTitle.size;
    const len = yTitle ? measure(yTitle, size) : 0;
    if (len > plotH) scene.y.titleFont = Math.max(8, Math.floor((size * plotH) / len));
  }
  const cxOf = new Map<string, number>();
  for (const m of scene.series[0]?.marks ?? []) if (m.bar) cxOf.set(String(m.rowId), m.bar.x + m.bar.w / 2);
  const columns = combos.map((c, i) => ({
    key: c.key,
    members: c.members,
    count: c.count,
    cx: cxOf.get(`ix-${i}`) ?? plotX + ((i + 0.5) / Math.max(1, combos.length)) * plotW,
  }));
  const mTop = plotY + plotH + matrixGap;
  const bandW = combos.length ? plotW / combos.length : plotW;
  const dotR = Math.max(2.5, Math.min(7, rowH * 0.34, bandW * 0.35));
  const offsets = cfg.labelOffsets ?? {};
  const dotColor = cfg.dotColor ?? UPSET_INK;
  const maxTotal = Math.max(1, ...totals);
  const barRight = plotX - maxLabelW - 14;
  const upsetSets = sets.map((ds, i) => {
    const rowCy = mTop + i * rowH + rowH / 2;
    const w = (totals[i]! / maxTotal) * SET_BAR_W;
    return {
      setId: ds.id,
      label: ds.name,
      total: totals[i]!,
      rowCy,
      color: plot.seriesStyles?.[ds.id]?.color ?? dotColor,
      ...(showSetSizes ? { bar: { x: barRight - w, y: rowCy - rowH * 0.28, w, h: rowH * 0.56 } } : {}),
      // Base anchor only — the stored drag offset rides separately (labelOff) so the
      // figure's DraggableTitle composes repeated drags instead of jumping back.
      labelX: plotX - 8,
      labelY: rowCy + rowFont.size * 0.34,
      ...(offsets[ds.id] ? { labelOff: offsets[ds.id] } : {}),
    };
  });

  return {
    ...scene,
    kind: "upset",
    upset: { columns, sets: upsetSets, matrix: { top: mTop, rowH, dotR }, dotColor },
    warnings: [...scene.warnings, ...warnings],
  };
}

/**
 * Swimmer plot: one horizontal timeline bar per subject (the lollipop row-per-row chassis) —
 * xy table, lead column = subject. Datasets 1–2 are the bar Start/End by position (or the
 * survival date-role pair survStart/survEnd → elapsed days); a dataset named exactly
 * "Response start"/"Response end" is the in-bar response overlay, one named "Ongoing" flags
 * the arrow cap (the sets membership cell rule, shared helper); every other numeric dataset
 * is an event-glyph series — a real SeriesScene, so the standard marker/colour/per-point/
 * legend controls, and the shared passes for data-driven colour and per-point styles, apply
 * to it. All-text
 * datasets are attribute columns (e.g. Stage), never series. Bars anchor styling on the
 * Start dataset: seriesStyles[start].color · pointStyles["start:rowId"].color · a
 * categorical colorFromColumn binding (the classic colour-by-stage look). Sorted longest
 * bar first by default; rowId keys survive the sort. Brackets refused — the rows are
 * individual subjects, not group comparisons.
 */
function buildSwimmerScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a swimmer plot", warnings, "treatment durations start at 0, which a log axis cannot show");
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.swimmer ?? {};
  const xCol = xColumn(table);
  const rowsAll = table.rows;

  // --- the column contract (core swimmerColumns — shared with the Inspector's hide-box
  // gating, so the two can never disagree about which columns are structural) -------------
  const dateStart = table.columns.find((c) => c.role === "survStart");
  const dateEnd = table.columns.find((c) => c.role === "survEnd");
  const allDs = tableDatasets(table); // already excludes the lead + the survival date pair
  const cols = swimmerColumns(table);
  const dateMode = cols.dateMode;
  const startDs = cols.start;
  const endDs = cols.end;
  const respStartDs = cols.responseStart;
  const respEndDs = cols.responseEnd;
  const ongoingDs = cols.ongoing;
  const valAt = (ds: Dataset, row: Row): number => {
    const vals = ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v));
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : NaN;
  };
  if (!dateMode && (!startDs || !endDs)) {
    warnings.push("A swimmer plot needs two numeric columns — bar Start and End — before any event columns (or the survival Start/End date pair).");
  }
  // Hiding an event column removes its glyphs; Start/End/Response/Ongoing are structural
  // (their rows carry no hide box — the shared swimmerColumns contract).
  const events = cols.events.filter((ds) => plot.seriesStyles?.[ds.id]?.hidden !== true);

  // --- rows: start/end/duration, sorted --------------------------------------------------
  interface SwimEntry { row: Row; s: number; e: number; dur: number }
  const entries: SwimEntry[] = [];
  let unusable = 0;
  for (const row of rowsAll) {
    let s = dateMode ? toNumber(row.cells[dateStart!.id]) : startDs ? valAt(startDs, row) : NaN;
    let e = dateMode ? toNumber(row.cells[dateEnd!.id]) : endDs ? valAt(endDs, row) : NaN;
    if (dateMode) {
      // Date pair → elapsed: every bar runs 0 → (end − start) days.
      if (Number.isFinite(s) && Number.isFinite(e)) { e = e - s; s = 0; } else { s = NaN; e = NaN; }
    }
    if (!Number.isFinite(s) && Number.isFinite(e)) s = 0; // a blank start means "from day 0"
    if (!Number.isFinite(s) || !Number.isFinite(e)) { unusable += 1; continue; }
    entries.push({ row, s, e, dur: Math.abs(e - s) });
  }
  if (unusable > 0 && (dateMode || (startDs && endDs))) {
    warnings.push(`${unusable} subject${unusable === 1 ? " has" : "s have"} no usable Start/End and ${unusable === 1 ? "is" : "are"} not drawn.`);
  }
  if ((cfg.sortBy ?? "duration") === "duration") entries.sort((a, b) => b.dur - a.dur);
  const n = entries.length;
  if (rowsAll.length === 0) warnings.push("A swimmer plot needs one row per subject.");

  // --- value domain: bars + response + every event glyph must fit ------------------------
  const respAt = (row: Row): { lo: number; hi: number } | null => {
    if (!respStartDs || !respEndDs) return null;
    const a = valAt(respStartDs, row);
    const b = valAt(respEndDs, row);
    return Number.isFinite(a) && Number.isFinite(b) ? { lo: Math.min(a, b), hi: Math.max(a, b) } : null;
  };
  const allVals: number[] = [0];
  for (const x of entries) {
    allVals.push(x.s, x.e);
    const r = respAt(x.row);
    if (r) allVals.push(r.lo, r.hi);
    for (const ds of events) {
      const v = valAt(ds, x.row);
      if (Number.isFinite(v)) allVals.push(v);
    }
  }
  const vSpec: AxisSpec = plot.xAxis ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const gridDensity = plot.grid?.density ?? 6;
  const vAuto = buildScale("linear", extent(allVals), [0, 1], gridDensity, false, vFmt).domain;
  const wv = windowed(vSpec, vAuto, options.xDomain);
  const vData = wv.data;
  const manualV = wv.manual;
  const vRev = vSpec.reversed ?? false;

  // --- margins (the horizontal-lollipop arrangement) -------------------------------------
  const catFont = fonts.yTick;
  const valFont = fonts.xTick;
  const catLabels = entries.map((x, i) => (xCol ? String(x.row.cells[xCol.id] ?? i + 1) : String(i + 1)));
  const catLabelW = Math.max(0, ...catLabels.map((t) => measure(t, catFont.size)), turnedYLabelsReach(catLabels, catFont.size, measure, plot.yAxis?.tickRotation));
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const catSpec: AxisSpec = plot.yAxis ?? {};
  const catTitle = catSpec.title ?? (xCol?.name ?? "");
  const vTitle = vSpec.title ?? "Time";
  const vTickGap = vSpec.tickLabelGap ?? 6;
  const vTitleGap = vSpec.titleGap ?? 6;
  const catTickGap = catSpec.tickLabelGap ?? 8;
  const catTitleGap = catSpec.titleGap ?? 6;
  const responseFill = cfg.responseFill ?? "#1a9850";
  const responseOpacity = Math.max(0, Math.min(1, cfg.responseOpacity ?? 0.9));
  const anyResponse = entries.some((x) => respAt(x.row) != null);
  const showArrow = cfg.showOngoingArrow ?? true;
  const showDur = plot.showValues ?? false;
  const fmtVal = (v: number): string => (Number.isInteger(v) ? String(v) : Number(v.toFixed(2)).toString());

  // Legend: the event series (+ a Response swatch) — replaced wholesale by a data-driven
  // category legend when a colour binding is set (the xy rule).
  const ddLeg = dataDrivenLegend(plot, allDs, table, palette);
  const evColor = (ds: Dataset, i: number): string => plot.seriesStyles?.[ds.id]?.color ?? seriesColor(i + 1, palette);
  const rawLegend: LegendEntry[] =
    ddLeg ?? [
      ...events.map((ds, i) => ({ label: ds.name, color: evColor(ds, i), select: { as: "series" as const, id: ds.id } })),
      // Response is drawn as a filled band inside each bar, so its key is a filled block (keys follow their marks).
      ...(anyResponse ? [{ label: "Response", color: responseFill, swatch: "bar" as const, select: { as: "section" as const, id: "Swimmer plot" } }] : []),
    ];
  const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);

  let marginLeft = catSpec.hidden
    ? HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catTitleGap) : 4);
  let marginBottom = vSpec.hidden
    ? HIDDEN_AXIS_MARGIN
    : valFont.size + vTickGap + DEFAULTS.tickLen + textBand(fonts.xAxisTitle.size, vTitleGap);
  // Room past the longest bar for the arrow cap and/or the duration labels. A label sits 8 px past its bar's end, or
  // 16 px when the arrow cap is there (`label.x` below); `measure` under-reads, hence × 1.1.
  const durReserve = showDur ? Math.max(0, ...entries.map((x) => measure(fmtVal(x.dur), fonts.valueLabel.size))) * 1.1 + (showArrow ? 16 : 8) + 4 : 0;
  const arrowReserve = showArrow ? 14 : 0;
  const endReserve = Math.max(durReserve, arrowReserve);
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + endReserve + pad.r;
  // …and the legend starts past that room, not at the plot's edge, so it never sits on a bar's end label or its
  // arrow. The right-margin stack's `outsidePad`, as every other chart.
  if (endReserve > 0) leg.layout = { ...leg.layout, outsidePad: endReserve };
  marginLeft += pad.l;
  marginBottom += pad.b;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const vb = buildScale("linear", vData, vRev ? [plotW, 0] : [0, plotW], gridDensity, manualV, vFmt, vSpacing);
  const vpx = (v: number): number => plotX + vb.scale(v);
  const band = plotH / Math.max(1, n);
  const bandCenter = (i: number): number => plotY + i * band + band / 2;
  const barH = band * Math.max(0.1, Math.min(1, cfg.barHeight ?? 0.55));
  // Subject labels are stacked one per band: shrink to the band, thin past the readable floor
  // (the same fit the horizontal bar chart and the heatmap rows use). Without it, an enlarged tick
  // font on a 20-subject chart would stack neighbouring names into each other.
  const catFit = fitStackedLabels(n, band, catFont.size);
  // The bar-end numbers are stacked one per band too, so they follow the same fit — shrink to the band, thin past the
  // readable floor (otherwise, e.g. with 40 patients, the names shrink but neighbouring numbers touch). The room
  // reserved past the bars keeps the full size, so it is never short.
  const durFit = showDur ? fitStackedLabels(n, band, fonts.valueLabel.size) : { font: fonts.valueLabel.size, keep: null };
  if (showDur && plot.fonts?.valueLabel?.size !== undefined && durFit.font < fonts.valueLabel.size) {
    warnings.push(`Duration numbers are drawn at ${durFit.font}px, not the ${fonts.valueLabel.size}px asked for: ${n} rows leave no room. A taller figure, or fewer rows, will honour it.`);
  }
  if (catSpec.tickFont?.size !== undefined && catFit.font < catFont.size) {
    warnings.push(`Subject labels are drawn at ${catFit.font}px, not the ${catFont.size}px asked for: ${n} rows leave no room. A taller figure, or fewer rows, will honour it.`);
  }

  // --- per-bar colour: point override > categorical column binding > Start colour --------
  const startId = dateMode ? null : (startDs?.id ?? null);
  const stStart = startId ? plot.seriesStyles?.[startId] : undefined;
  const barBase = stStart?.color ?? seriesColor(0, palette);
  let ddCats: string[] | null = null;
  let ddCol: NodeId | null = null;
  if (stStart?.colorFromColumn) {
    if (ddColorMode(stStart, table, stStart.colorFromColumn) === "continuous") {
      warnings.push("Bar colour from a column uses categories — a continuous colour ramp over a timeline bar has no reading. Bind a text/category column instead.");
    } else {
      ddCol = stStart.colorFromColumn;
      ddCats = ddCategories(table, ddCol);
    }
  }
  const barColor = (row: Row): string => {
    const override = startId ? plot.pointStyles?.[`${startId}:${row.id}`]?.color : undefined;
    if (override) return override;
    if (ddCats && ddCol) {
      const k = ddCellKey(row.cells[ddCol]);
      if (k !== null) return palette[Math.max(0, ddCats.indexOf(k)) % palette.length]!;
    }
    return barBase;
  };

  const swRows: NonNullable<PlotScene["swimmer"]>["rows"] = entries.map((x, i) => {
    const cy = bandCenter(i);
    const x1 = vpx(Math.min(x.s, x.e));
    const x2 = vpx(Math.max(x.s, x.e));
    const r = respAt(x.row);
    const ongoing =
      showArrow && ongoingDs != null && setCellIsMember(x.row.cells[ongoingDs.replicates[0] ?? ongoingDs.id]);
    return {
      rowId: x.row.id,
      subject: catLabels[i]!,
      cy,
      barX1: Math.min(x1, x2),
      barX2: Math.max(x1, x2),
      barH,
      color: barColor(x.row),
      ongoing,
      duration: x.dur,
      ...(r ? { response: { x1: Math.min(vpx(r.lo), vpx(r.hi)), x2: Math.max(vpx(r.lo), vpx(r.hi)) } } : {}),
      ...(showDur && (!durFit.keep || durFit.keep.has(i))
        ? (() => {
            // The duration label reads its per-point drag offset + text override from pointStyles
            // (keyed `${startId}:${rowId}` — the same key its colour uses), so it drags + renames
            // like every other value label.
            const ps = startId ? plot.pointStyles?.[`${startId}:${x.row.id}`] : undefined;
            return {
              label: {
                text: ps?.valueText != null && ps.valueText !== "" ? ps.valueText : fmtVal(x.dur),
                x: Math.max(x1, x2) + (ongoing ? 16 : 8), y: cy + durFit.font * 0.34,
                ...(ps?.valueDx != null ? { dx: ps.valueDx } : {}),
                ...(ps?.valueDy != null ? { dy: ps.valueDy } : {}),
              },
            };
          })()
        : {}),
    };
  });

  // --- event-glyph series (real series, so the shared data-driven and per-point style passes apply) ---
  const series: SeriesScene[] = events.map((ds, i) => {
    const style = plot.seriesStyles?.[ds.id];
    const marks: MarkScene[] = [];
    entries.forEach((x, ri) => {
      const v = valAt(ds, x.row);
      if (!Number.isFinite(v)) return;
      marks.push({ rowId: x.row.id, rowNumber: ri + 1, dx: v, dy: v, cx: vpx(v), cy: bandCenter(ri) });
    });
    return markerSeries(ds.id, ds.name, style, evColor(ds, i), DD_SYMBOL_CYCLE[i % DD_SYMBOL_CYCLE.length]!, 6.5, marks);
  });

  // --- axes + annotations (the horizontal-lollipop transposed arrangement) ---------------
  const valueAxis: AxisScene = {
    type: "linear",
    domain: vRev ? [vb.domain[1], vb.domain[0]] : vb.domain,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, valFont.size),
    title: vTitle,
    ...axisLine(vSpec),
  };
  const catAxis: AxisScene = {
    type: "linear",
    domain: [0, Math.max(1, n)],
    range: [plotY + plotH, plotY],
    band: true,
    ticks: entries.map((_x, i) => ({
      value: i, pos: bandCenter(i), minor: false,
      label: catFit.keep && !catFit.keep.has(i) ? "" : catLabels[i]!,
      ...(catFit.keep && !catFit.keep.has(i) ? { suppressedLabel: catLabels[i]! } : {}),
    })),
    title: catTitle,
    ...axisLine(catSpec),
  };
  // Brackets are refused entirely: subject timelines are individuals, not
  // group comparisons — dropped here with the real reason, before the generic path could
  // drop them with a misleading one.
  const nBrackets = (plot.annotations ?? []).filter((a) => a.kind === "bracket").length;
  const annPlot = nBrackets > 0 ? { ...plot, annotations: (plot.annotations ?? []).filter((a) => a.kind !== "bracket") } : plot;
  if (nBrackets > 0) {
    warnings.push(`${nBrackets === 1 ? "A significance bracket was" : `${nBrackets} significance brackets were`} not drawn: swimmer rows are individual subjects, not group comparisons.`);
  }
  const valAnn = (v: number): number | undefined => (Number.isFinite(v) ? vpx(v) : undefined);
  const annotations = buildAnnotations(
    annPlot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: valAnn, y: valAnn, bracketX: () => undefined },
    true,
    warnings,
  );

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: valueAxis,
    y: catAxis,
    auto: (() => {
      const hv = options.xDomain != null
        ? buildScale("linear", wv.home, [0, 1], gridDensity, wv.homeManual, vFmt, vSpacing).domain
        : vb.domain;
      const v: [number, number] = vRev ? [hv[1], hv[0]] : hv;
      return { x: v, y: [0, Math.max(1, n)] as [number, number] };
    })(),
    zoomable: [{ visual: "x" as const, key: "x" as const }],
    series,
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    valueAxis: "x",
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: vTitle, y: catTitle },
    kind: "swimmer",
    fonts: {
      ...fonts,
      ...(catFit.font < catFont.size ? { yTick: { ...fonts.yTick, size: catFit.font } } : {}),
      ...(durFit.font < fonts.valueLabel.size ? { valueLabel: { ...fonts.valueLabel, size: durFit.font } } : {}),
    },
    swimmer: { rows: swRows, startId, responseFill, responseOpacity },
    warnings,
  };
}

/**
 * Timeline tracks: several stacked single-row tile strips, one per data
 * column, along one shared time (x) axis. A numeric column becomes a continuous track — its
 * tiles ramp-coloured on that column's own min/max, with its own colour bar beside the strip
 * (the divergence from the heatmap, which shares one colour domain across the whole grid). A
 * text column becomes a categorical track — one palette hue per distinct label, its keys in
 * the standard legend. The time column is the lead (an xy sheet's x column, else the first
 * column). Consumes xAxisLength (not a footprint kind) so the panel assembler can line the
 * tile columns up, time-for-time, with a chart stacked with it. Reuses the per-column colour
 * settings (`seriesStyles[col].colorFromRamp` / `colorFromReversed`) for a numeric track's ramp.
 */
function buildTracksScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);
  warnLogUnsupported(plot, "timeline tracks", warnings, "a time axis of tiles has no use for a log scale");
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const cfg = plot.tracks ?? {};
  const gridDensity = plot.grid?.density ?? 6;

  // --- the column contract: lead = time (x), every other column = one track --------------
  const timeCol = xColumn(table) ?? table.columns[0];
  const allDs = tableDatasets(table); // excludes an explicit x-role lead column
  const trackDs = allDs.filter((d) => !timeCol || d.id !== timeCol.id);
  if (!timeCol) warnings.push("Timeline tracks need a first column of time values.");
  if (trackDs.length === 0) warnings.push("Timeline tracks need at least one track column beside the time column.");

  const timeOf = (row: Row): number => (timeCol ? toNumber(row.cells[timeCol.id]) : NaN);
  const usable = timeCol ? table.rows.filter((r) => Number.isFinite(timeOf(r))) : table.rows;
  const droppedT = table.rows.length - usable.length;
  if (droppedT > 0) warnings.push(`${droppedT} row${droppedT === 1 ? "" : "s"} with no numeric time ${droppedT === 1 ? "is" : "are"} not drawn.`);
  const rowsSorted = [...usable].sort((a, b) => timeOf(a) - timeOf(b));
  const m = rowsSorted.length;
  const haveTime = m > 0 && rowsSorted.some((r) => Number.isFinite(timeOf(r)));
  if (m > 0 && !haveTime) warnings.push("The time column is not numeric — tiles are placed in table order.");
  const tvals = haveTime ? rowsSorted.map(timeOf) : rowsSorted.map((_r, i) => i + 1);

  // Tile edges = midpoints between adjacent sample times; the first/last extend half a step.
  const leftEdge = (i: number): number => {
    if (m <= 1) return tvals[0] != null ? tvals[0] - 0.5 : -0.5;
    if (i === 0) return tvals[0]! - (tvals[1]! - tvals[0]!) / 2;
    return (tvals[i - 1]! + tvals[i]!) / 2;
  };
  const rightEdge = (i: number): number => {
    if (m <= 1) return tvals[0] != null ? tvals[0] + 0.5 : 0.5;
    if (i === m - 1) return tvals[m - 1]! + (tvals[m - 1]! - tvals[m - 2]!) / 2;
    return (tvals[i]! + tvals[i + 1]!) / 2;
  };

  // --- time (x) value axis ---------------------------------------------------------------
  const vSpec: AxisSpec = plot.xAxis ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const domainAll: [number, number] = m > 0 ? [leftEdge(0), rightEdge(m - 1)] : [0, 1];
  // Exact tile extent, not nice-rounded: a week axis that starts at 0 must not open at −2 (an
  // empty band implying negative weeks). Ticks are still chosen nicely
  // inside the extent; a user min/max still wins through `windowed`.
  const vAuto = buildScale("linear", domainAll, [0, 1], gridDensity, true, vFmt).domain;
  const wv = windowed(vSpec, vAuto, options.xDomain);
  const vData = wv.data;

  const vRev = vSpec.reversed ?? false;

  // --- per-track: numeric (own ramp + own domain) vs categorical (palette per label) -----
  const rawCell = (ds: Dataset, row: Row): CellValue | undefined => row.cells[ds.replicates[0] ?? ds.id];
  const isNumericTrack = (ds: Dataset): boolean => {
    const mode = plot.seriesStyles?.[ds.id]?.colorFromMode;
    if (mode === "continuous") return true;
    if (mode === "category") return false;
    const cells = rowsSorted.map((r) => rawCell(ds, r)).filter((v) => v != null && v !== "");
    return cells.length > 0 && cells.every((v) => Number.isFinite(Number(v)));
  };
  interface TrackInfo { ds: Dataset; numeric: boolean; mn: number; mx: number; ramp: (v: number) => string; barStops: { offset: number; color: string }[]; cats: string[] }
  const tracks: TrackInfo[] = trackDs.map((ds) => {
    if (isNumericTrack(ds)) {
      const vals = rowsSorted.map((r) => rowDatasetMean(r, ds)).filter((v) => Number.isFinite(v));
      const mn = vals.length ? Math.min(...vals) : 0;
      const mx = vals.length ? Math.max(...vals) : 1;
      const span = mx - mn || 1;
      // Per-column colour settings (the "Colour by data" controls) → each track can carry its own
      // ramp; the tracks style slot's `colormap` is the fallback for all numeric tracks.
      const cmap = plot.seriesStyles?.[ds.id]?.colorFromRamp ?? cfg.colormap ?? "viridis";
      const rev = plot.seriesStyles?.[ds.id]?.colorFromReversed ?? false;
      const trackShape: RampShape = {
        midpointValue: cfg.colorMidpoint, gamma: cfg.colorGamma, steps: cfg.colorSteps,
        space: cfg.colorSpace, lo: mn, hi: mx, values: vals,
      };
      const trackPaint = ramps.ramp(cmap, "#440154", "#fde725", rev, trackShape);
      const barStops = ramps.barStops(cmap, "#440154", "#fde725", rev, trackShape);
      const ramp = (v: number): string => trackPaint(Math.max(0, Math.min(1, (v - mn) / span))).color;
      return { ds, numeric: true, mn, mx, ramp, barStops, cats: [] };
    }
    const cats: string[] = [];
    for (const r of rowsSorted) { const k = ddCellKey(rawCell(ds, r)); if (k !== null && !cats.includes(k)) cats.push(k); }
    return { ds, numeric: false, mn: 0, mx: 1, ramp: () => "", barStops: [], cats };
  });
  // Categorical hues come from the preset palette (so a restyle reaches the strips — the rose
  // wedge-colour rule), one hue per distinct label within each track.
  const catColorFor = (ti: number, k: string): string => palette[Math.max(0, tracks[ti]!.cats.indexOf(k)) % palette.length]!;
  const anyNumeric = tracks.some((t) => t.numeric);

  // --- legend: categorical track keys (numeric tracks carry their own colour bar) --------
  const legEntries: LegendEntry[] = tracks.flatMap((t, ti) =>
    // A tile is a fill, so its key is a fill block (the bar/area rule), not a marker dot.
    t.numeric ? [] : t.cats.map((k) => ({ label: k, color: catColorFor(ti, k), select: { as: "section" as const, id: "Chart type" }, swatch: "bar" as const })),
  );
  const leg = resolveLegend(plot, legEntries, measure, fonts.legend.size, width);

  // --- margins ---------------------------------------------------------------------------
  const catFont = fonts.yTick;
  const valFont = fonts.xTick;
  const showLabels = cfg.showTrackLabels ?? true;
  const trackNames = tracks.map((t) => t.ds.name);
  const catLabelW = showLabels ? Math.max(0, ...trackNames.map((t) => measure(t, catFont.size)), turnedYLabelsReach(trackNames, catFont.size, measure, plot.yAxis?.tickRotation)) : 0;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const catSpec: AxisSpec = plot.yAxis ?? {};
  const catTitle = catSpec.title ?? "";
  const vTitle = vSpec.title ?? (timeCol?.name ?? "Time");
  const vTickGap = vSpec.tickLabelGap ?? 6;
  const vTitleGap = vSpec.titleGap ?? 6;
  const catTickGap = catSpec.tickLabelGap ?? 8;
  const catTitleGap = catSpec.titleGap ?? 6;
  const barFont = fonts.legend;
  const fmtV = (v: number): string => (Number.isInteger(v) ? String(v) : Number(v.toFixed(2)).toString());
  const barLabelW = anyNumeric
    ? Math.max(0, ...tracks.filter((t) => t.numeric).flatMap((t) => [measure(fmtV(t.mn), barFont.size), measure(fmtV(t.mx), barFont.size)]))
    : 0;
  const barReserve = anyNumeric ? 12 + 6 + barLabelW : 0;
  let marginLeft = !showLabels || catSpec.hidden
    ? HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catTitleGap) : 4);
  let marginBottom = vSpec.hidden
    ? HIDDEN_AXIS_MARGIN
    : valFont.size + vTickGap + DEFAULTS.tickLen + textBand(fonts.xAxisTitle.size, vTitleGap);
  let marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + barReserve + pad.r;
  marginLeft += pad.l;
  marginBottom += pad.b;
  // Narrow-figure floor (the paireddot rule): never let the labels/legend/colour-bars swallow
  // the whole plot — keep at least a fifth of a fixed-width figure to draw in, shrinking the
  // side margins proportionally in the degenerate case (they clip; the plot survives). When an
  // axis length is pinned (panel assembler), the plot width is that length regardless of margins.
  if (plot.xAxisLength == null) {
    const maxSide = width * 0.8;
    if (marginLeft + marginRight > maxSide) {
      const scale = maxSide / (marginLeft + marginRight);
      marginLeft = Math.floor(marginLeft * scale);
      marginRight = Math.floor(marginRight * scale);
    }
  }
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  // Exact extent (see vAuto above): the tiles set the ends; ticks fall nicely inside.
  const vb = buildScale("linear", vData, vRev ? [plotW, 0] : [0, plotW], gridDensity, true, vFmt, vSpacing);
  const vpx = (v: number): number => plotX + vb.scale(v);

  // --- Y bands (tracks stacked top-down) -------------------------------------------------
  const nT = tracks.length;
  const gap = Math.max(0, cfg.trackGap ?? 4);
  const tileGap = Math.max(0, cfg.tileGap ?? 0);
  const bandH = cfg.trackHeight != null
    ? Math.max(1, cfg.trackHeight)
    : Math.max(1, (plotH - gap * Math.max(0, nT - 1)) / Math.max(1, nT));
  const stripY = (i: number): number => plotY + i * (bandH + gap);
  // A missing cell leaves a gap by default; with fillGaps on, paint it with nanColor.
  const nanColor = (cfg.fillGaps ?? false) ? (cfg.nanColor ?? "#dddddd") : undefined;

  const strips = tracks.map((t, i) => {
    const y = stripY(i);
    const tiles: { x: number; w: number; color: string; value: number | null; label: string }[] = [];
    rowsSorted.forEach((row, ri) => {
      const l = vpx(leftEdge(ri));
      const r = vpx(rightEdge(ri));
      const x0 = Math.min(l, r) + tileGap / 2;
      const x1 = Math.max(l, r) - tileGap / 2;
      const w = Math.max(0.5, x1 - x0);
      if (t.numeric) {
        const v = rowDatasetMean(row, t.ds);
        if (Number.isFinite(v)) tiles.push({ x: x0, w, color: t.ramp(v), value: v, label: "" });
        else if (nanColor) tiles.push({ x: x0, w, color: nanColor, value: null, label: "" });
      } else {
        const k = ddCellKey(rawCell(t.ds, row));
        if (k !== null) tiles.push({ x: x0, w, color: catColorFor(i, k), value: null, label: k });
        else if (nanColor) tiles.push({ x: x0, w, color: nanColor, value: null, label: "" });
      }
    });
    // The bar is inset by a label height at each end: its min/max labels sit at the bar ends, and
    // two numeric tracks stacked flush would put the upper bar's min on top of the lower bar's max.
    // The inset keeps each bar's labels inside its own strip.
    const cbInset = Math.min(bandH / 3, barFont.size * 0.75);
    const colorbar = t.numeric
      ? {
          x: plotX + plotW + 6,
          y: y + cbInset,
          w: 12,
          h: Math.max(4, bandH - 2 * cbInset),
          min: t.mn,
          max: t.mx,
          stops: t.barStops,
        }
      : undefined;
    return { id: t.ds.id, name: t.ds.name, y, h: bandH, numeric: t.numeric, tiles, ...(colorbar ? { colorbar } : {}) };
  });

  // --- axes ------------------------------------------------------------------------------
  const valueAxis: AxisScene = {
    type: "linear",
    domain: vRev ? [vb.domain[1], vb.domain[0]] : vb.domain,
    range: [plotX, plotX + plotW],
    ticks: deOverlapX(vb.ticks.map((tk) => ({ ...tk, pos: plotX + tk.pos })), measure, valFont.size),
    title: vTitle,
    ...axisLine(vSpec),
  };
  const catAxis: AxisScene = {
    type: "linear",
    domain: [0, Math.max(1, nT)],
    range: [plotY, plotY + plotH],
    band: true,
    ticks: strips.map((s, i) => ({ value: i, pos: s.y + s.h / 2, label: showLabels ? s.name : "", minor: false })),
    title: catTitle,
    ...axisLine(catSpec),
  };

  // Brackets refused entirely (tracks are not group comparisons); an hline has no Y scale to
  // land on (the Y axis holds tracks, not values) — a vline / vband marks a time.
  const nBrackets = (plot.annotations ?? []).filter((a) => a.kind === "bracket").length;
  const annPlot = nBrackets > 0 ? { ...plot, annotations: (plot.annotations ?? []).filter((a) => a.kind !== "bracket") } : plot;
  if (nBrackets > 0) {
    warnings.push(`${nBrackets === 1 ? "A significance bracket was" : `${nBrackets} significance brackets were`} not drawn: timeline tracks are not group comparisons.`);
  }
  const annotations = buildAnnotations(
    annPlot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: (v) => (Number.isFinite(v) ? vpx(v) : undefined), y: () => undefined, bracketX: () => undefined },
    false,
    warnings,
  );

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: valueAxis,
    y: catAxis,
    auto: (() => {
      const hv = options.xDomain != null
        ? buildScale("linear", wv.home, [0, 1], gridDensity, true, vFmt, vSpacing).domain
        : vb.domain;
      const v: [number, number] = vRev ? [hv[1], hv[0]] : hv;
      return { x: v, y: [0, Math.max(1, nT)] as [number, number] };
    })(),
    zoomable: [{ visual: "x" as const, key: "x" as const }],
    series: [],
    legend: leg.entries,
    legendLayout: leg.layout,
    annotations,
    valueAxis: "x",
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: vTitle, y: catTitle },
    kind: "tracks",
    fonts,
    tracks: { strips },
    warnings,
  };
}

/**
 * Funnel plot: the forest plot's publication-bias companion, drawn from the same table
 * (Study · Estimate · Lower · Upper). X = effect (log-capable, forest's axis rule);
 * Y = each study's back-calculated standard error on an inverted axis (SE 0 at the top —
 * the convention, so precise studies sit high and the cloud fans out downward). One dot
 * per study; a pseudo-CI triangle spreads pooled ± z·SE (fixed/random pooling via core
 * `metaAnalysis` — no new maths); contour mode instead shades zero-centred significance
 * bands (p .10/.05/.01), the standard aid for judging where the asymmetry sits.
 */
function buildFunnelScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  // Not `visibleDatasets` — estimate · lower · upper are read by position (the forest rule).
  const datasets = tableDatasets(table);
  const xCol = xColumn(table);
  const rows = table.rows;
  const cfg = plot.funnel ?? {};
  if (datasets.length < 3) warnings.push("Funnel plot needs three value columns: estimate, lower CI, upper CI.");
  const estDs = datasets[0];
  const loDs = datasets[1];
  const hiDs = datasets[2];
  const inputConf = cfg.ciLevel ?? 0.95;
  const zIn = normalCiMultiplier(inputConf);

  // Effect (X) axis — forest's rule: honours the standard spec incl. log for ratio measures.
  const vSpec: AxisSpec = plot.xAxis ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const vRev = vSpec.reversed ?? false;
  interface FStudy { id: NodeId; label: string; est: number; lo: number; hi: number; se: number }
  const rawStudies = rows.map((row, i) => ({
    id: row.id,
    label: xCol ? String(row.cells[xCol.id] ?? `Study ${i + 1}`) : `Study ${i + 1}`,
    est: datasetRowValue(estDs, row),
    lo: datasetRowValue(loDs, row),
    hi: datasetRowValue(hiDs, row),
  }));
  let vType: ScaleType = options.xScale ?? vSpec.scale ?? "linear";
  const allEffectVals = rawStudies.flatMap((s) => [s.est, s.lo, s.hi]).filter((v) => Number.isFinite(v));
  if (isLog(vType) && !allEffectVals.every((v) => v > 0)) {
    vType = "linear";
    warnings.push("Log effect axis needs all-positive values — using linear.");
  }
  const logAxis = isLog(vType);
  const tf = logAxis ? Math.log : (x: number): number => x;
  const tinv = logAxis ? Math.exp : (x: number): number => x;

  // Each study's SE from its reported CI — the one shared formula (core studySE).
  const studies: FStudy[] = rawStudies.map((s) => ({ ...s, se: logAxis && s.est <= 0 ? NaN : studySE(s.lo, s.hi, zIn, logAxis) }));
  const drawable = studies.filter((s) => Number.isFinite(s.est) && Number.isFinite(s.se));
  const dropped = studies.length - drawable.length;
  if (rows.length > 0 && drawable.length === 0) warnings.push("No study has both a finite estimate and a usable CI to place it by.");
  else if (dropped > 0) warnings.push(`${dropped} ${dropped === 1 ? "study has" : "studies have"} no usable CI (needs lower < upper${logAxis ? ", all positive on a log axis" : ""}) and ${dropped === 1 ? "is" : "are"} not drawn.`);

  // Pooling — core metaAnalysis, in log space on a log axis (crosschecked maths, reused).
  const model: "fixed" | "random" = cfg.model === "random" ? "random" : "fixed";
  const meta = metaAnalysis(
    drawable.map((s) => ({ est: s.est, lo: s.lo, hi: s.hi })),
    { model, inputConf, pooledConf: inputConf, log: logAxis },
  );
  const pooledT = meta ? tf(meta.est) : NaN;
  const zRegion = normalCiMultiplier(cfg.ciLevel ?? 0.95);
  const seMax = drawable.length ? Math.max(...drawable.map((s) => s.se)) : 1;
  const seDomMax = seMax * 1.06; // headroom so the widest dot doesn't sit on the frame

  // Trim-and-fill overlay — core trimAndFill, the same crosschecked maths the Publication
  // bias analysis reports. Computed before the domain: the mirrored studies extend the
  // effect axis and must not be clipped off. An overlay that cannot run says why.
  const tfRes = (cfg.trimFill ?? false)
    ? trimAndFill(drawable.map((s) => ({ est: s.est, lo: s.lo, hi: s.hi })), { model, inputConf, pooledConf: inputConf, log: logAxis })
    : null;
  if ((cfg.trimFill ?? false) && !tfRes) warnings.push("Trim-and-fill needs at least 3 studies with usable CIs — nothing imputed.");
  else if (tfRes && tfRes.k0 === 0) warnings.push("Trim-and-fill found no missing studies (k₀ = 0) — the funnel reads symmetric; nothing to impute.");

  // X domain: every estimate + the region's base corners, so the triangle always fits.
  const domVals: number[] = drawable.map((s) => s.est);
  if (meta) domVals.push(tinv(pooledT - zRegion * seDomMax), tinv(pooledT + zRegion * seDomMax));
  if (tfRes && tfRes.k0 > 0) domVals.push(tfRes.adjusted.est, ...tfRes.imputed.map((s) => s.est));
  if (domVals.length === 0) domVals.push(0, 1);
  const vAuto = buildScale(vType, extent(logAxis ? domVals.filter((v) => v > 0) : domVals), [0, 1], gridDensity, false, vFmt).domain;
  const wfx = windowed(vSpec, vAuto, options.xDomain);

  // SE (Y) axis — linear only, and inverted by default (SE 0 at the top).
  const ySpec: AxisSpec = plot.yAxis ?? {};
  if (ySpec.scale && isLog(ySpec.scale)) warnings.push("The standard-error axis is linear — a log SE axis would push SE 0 (the funnel's apex) to infinity.");
  const yRev = ySpec.reversed ?? true;
  const yFmt = tickFormat(ySpec);
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const wfy = windowed(ySpec, [0, seDomMax], options.yDomain);

  const vTitle = vSpec.title ?? (estDs?.name ?? "Effect");
  const yTitle = ySpec.title ?? "Standard error";
  const vTickGap = vSpec.tickLabelGap ?? 6;
  const vTitleGap = vSpec.titleGap ?? 6;
  const yTickGap = ySpec.tickLabelGap ?? 6;
  // Width estimate only — the real labels come from buildScale's ticks (yFmt is a spec
  // for buildScale, not a callable). Two decimals covers a typical SE range readout.
  // Plus any custom tick labels on this axis (a typed label gets its room). There are
  // no probe ticks here to bound them, so every finite custom tick counts.
  const yTickW = Math.max(0, ...[0, seDomMax].map((v) => measure(v.toFixed(2), fonts.tick.size)), ...customTickLabels(ySpec, []).map((l) => measure(l, fonts.tick.size)));
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = ySpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yTickW + DEFAULTS.tickLen + yTickGap + (yTitle ? textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6) : 4) + pad.l;
  const marginBottom = vSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + vTickGap + DEFAULTS.tickLen + textBand(fonts.xAxisTitle.size, vTitleGap) + pad.b;
  const marginRight = DEFAULTS.marginRight + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale(vType, wfx.data, vRev ? [plotW, 0] : [0, plotW], gridDensity, wfx.manual, vFmt, vSpacing);
  const px = (v: number): number => plotX + xb.scale(v);
  // Reversed (default): SE 0 maps to the top of the plot; a plain axis puts it at the bottom.
  const yb = buildScale("linear", wfy.data, yRev ? [0, plotH] : [plotH, 0], gridDensity, wfy.manual, yFmt, ySpacing);
  const pyse = (se: number): number => plotY + yb.scale(se);

  // Study dots. sizeByPrecision: dot area ∝ inverse-variance weight (radius ∝ 1/SE),
  // anchored so the most precise study keeps the base size — the forest weightMarkers rule.
  const style = plot.seriesStyles?.[estDs?.id ?? "funnel"];
  const color = style?.color ?? seriesColor(0, palette);
  const baseSize = style?.symbolSize ?? 6;
  const seMin = drawable.length ? Math.min(...drawable.map((s) => s.se)) : 1;
  // Takes anything with an `se` — the trim-and-fill imputed dots share the sizing rule.
  const sizeOf = (s: { se: number }): number =>
    cfg.sizeByPrecision ? Math.max(3, Math.min(baseSize * 2.2, baseSize * (seMin / s.se))) : baseSize;
  const marks: MarkScene[] = drawable.map((s, i) => ({
    rowId: s.id, rowNumber: i + 1, dx: s.est, dy: s.se, cx: px(s.est), cy: pyse(s.se), n: 1,
    label: s.label, symbolSize: sizeOf(s),
  }));
  const series: SeriesScene[] = [markerSeries(estDs?.id ?? "funnel", estDs?.name ?? "Effect", style, color, "circle", baseSize, marks)];

  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    // bracketX = the data-x family rule (xy/volcano/blandaltman): a bracket's endpoints are
    // effect values mapped through the axis — so programmatic/freeform brackets place, even
    // though the kind has no UI bracket button (not in BRACKET_KINDS).
    { x: (v) => (Number.isFinite(v) ? px(v) : undefined), y: (v) => (Number.isFinite(v) ? pyse(v) : undefined), bracketX: (v) => (Number.isFinite(v) ? px(v) : undefined) },
    false,
    warnings,
  );
  // The pooled-effect centre line — a registered reference line (`funnel-pooled`), so its
  // style/hide panel and label drag come from the shared machinery.
  const rl = resolveRefLine(plot, "funnel-pooled", { dash: "4 3", width: 1.25 });
  if (meta && rl.show && (cfg.showPooled ?? true)) {
    const rx = px(meta.est);
    if (rx >= plotX - 0.5 && rx <= plotX + plotW + 0.5) {
      annotations.push({ id: "funnel-pooled", kind: "line", x1: rx, x2: rx, y1: plotY, y2: plotY + plotH, color: rl.color, dash: rl.dash, width: rl.width });
    }
  }
  // Trim-and-fill: imputed studies as chrome (hollow dots — no table row exists to
  // click) + the adjusted-effect centre line, registered like the pooled one.
  let tfImputed: NonNullable<PlotScene["funnel"]>["imputed"];
  if (tfRes && tfRes.k0 > 0) {
    tfImputed = tfRes.imputed.map((s) => {
      const se = studySE(s.lo, s.hi, zIn, logAxis);
      return { cx: px(s.est), cy: pyse(se), r: sizeOf({ se }), est: s.est, se };
    });
    const rlAdj = resolveRefLine(plot, "funnel-adjusted", { dash: "2 3", width: 1.25 });
    if (rlAdj.show) {
      const ax = px(tfRes.adjusted.est);
      if (ax >= plotX - 0.5 && ax <= plotX + plotW + 0.5) {
        annotations.push({ id: "funnel-adjusted", kind: "line", x1: ax, x2: ax, y1: plotY, y2: plotY + plotH, color: rlAdj.color, dash: rlAdj.dash, width: rlAdj.width });
      }
    }
  }

  // Pseudo-CI region: a triangle pooled ± z·SE — straight in pixels on a log axis too,
  // because log px is linear in the transformed value. Suppressed in contour mode (the two
  // shadings answer different questions and would overprint).
  const contourOn = (cfg.contour ?? false) && !logAxis;
  if ((cfg.contour ?? false) && logAxis) {
    warnings.push("Significance contours are centred on zero — a log effect axis has no zero, so the plain funnel is shown.");
  }
  let region: NonNullable<PlotScene["funnel"]>["region"];
  if (meta && (cfg.showRegion ?? true) && !contourOn) {
    const apex = `${px(meta.est).toFixed(2)},${pyse(0).toFixed(2)}`;
    const bl = `${px(tinv(pooledT - zRegion * seDomMax)).toFixed(2)},${pyse(seDomMax).toFixed(2)}`;
    const br = `${px(tinv(pooledT + zRegion * seDomMax)).toFixed(2)},${pyse(seDomMax).toFixed(2)}`;
    region = { path: `M${apex} L${bl} L${br} Z`, apexX: meta.est, halfWidthAtMaxSe: zRegion * seMax, opacity: cfg.regionOpacity ?? 0.08 };
  }
  let contours: NonNullable<PlotScene["funnel"]>["contours"];
  if (contourOn) {
    const zero = px(0);
    const yTop = pyse(0);
    const yBase = pyse(seDomMax);
    const left = plotX;
    const right = plotX + plotW;
    const cl = (x: number): number => Math.max(left, Math.min(right, x));
    // Bands: p .10–.05 · .05–.01 · <.01 (outside the z 2.576 lines), mirrored about zero.
    const bands: { zLo: number; zHi: number | null; fill: string; opacity: number; p: number }[] = [
      { zLo: 1.6449, zHi: 1.96, fill: "#d9d9d9", opacity: 0.55, p: 0.1 },
      { zLo: 1.96, zHi: 2.5758, fill: "#bdbdbd", opacity: 0.55, p: 0.05 },
      { zLo: 2.5758, zHi: null, fill: "#9e9e9e", opacity: 0.45, p: 0.01 },
    ];
    contours = bands.map((b) => {
      const wedge = (sign: 1 | -1): string => {
        const xi = cl(zero + sign * b.zLo * (px(1) - px(0)) * seDomMax); // value-units: z·SE
        const xo = b.zHi == null ? (sign === 1 ? right : left) : cl(zero + sign * b.zHi * (px(1) - px(0)) * seDomMax);
        const apexPt = `${zero.toFixed(2)},${yTop.toFixed(2)}`;
        const base = `L${xi.toFixed(2)},${yBase.toFixed(2)} L${xo.toFixed(2)},${yBase.toFixed(2)}`;
        return b.zHi == null
          ? `M${apexPt} ${base} L${xo.toFixed(2)},${yTop.toFixed(2)} Z`
          : `M${apexPt} ${base} Z`;
      };
      return { path: `${wedge(1)} ${wedge(-1)}`, fill: b.fill, opacity: b.opacity, p: b.p };
    });
  }

  const leg = resolveLegend(plot, [], measure, fonts.legend.size, width);
  return {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: vType, domain: vRev ? [xb.domain[1]!, xb.domain[0]!] : xb.domain, range: [plotX, plotX + plotW], ticks: xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), title: vTitle, ...axisLine(vSpec) },
    // Reversed is the default here, so an explicit view override (a zoom/brush) must come
    // back exactly as given — the brush contract; only the auto presentation flips.
    y: { type: "linear", domain: options.yDomain != null ? yb.domain : yRev ? [yb.domain[1]!, yb.domain[0]!] : yb.domain, range: [plotY + plotH, plotY], ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yTitle, ...axisLine(ySpec) },
    auto: {
      x: options.xDomain != null ? buildScale(vType, wfx.home, [0, 1], gridDensity, wfx.homeManual, vFmt, vSpacing).domain : xb.domain,
      y: (() => {
        const home = options.yDomain != null ? buildScale("linear", wfy.home, [0, 1], gridDensity, wfy.homeManual, yFmt, ySpacing).domain : yb.domain;
        return yRev ? ([home[1]!, home[0]!] as [number, number]) : home;
      })(),
    },
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: vTitle, y: yTitle }, kind: "funnel", fonts, warnings,
    funnel: {
      pooled: meta ? meta.est : NaN,
      seMax,
      ...(region ? { region } : {}),
      ...(contours ? { contours } : {}),
      ...(tfImputed ? { imputed: tfImputed } : {}),
      ...(tfRes && tfRes.k0 > 0 ? { trimFill: { k0: tfRes.k0, side: tfRes.side, adjusted: tfRes.adjusted.est } } : {}),
    },
  };
}

/**
 * Forest plot: one horizontal row per study — a point-estimate marker with a
 * horizontal CI whisker (lower→upper), a vertical no-effect reference line, and an
 * optional pooled fixed-effect inverse-variance summary diamond. The first three
 * value columns supply the estimate, lower CI, and upper CI; the label column names
 * the studies. The effect (X) axis honours the Axis panel's log scale (OR/RR/HR).
 * Renders through the default marker path (a non-categorical scene): per-study markers
 * + the unconditional horizontal error-bar layer + an annotation reference line.
 */
function buildForestScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  // Not `visibleDatasets`: estimate · lower · upper are read by position, so dropping a hidden
  // one would re-role the rest — hiding "Lower" would make the whisker's low end the old Upper.
  // Same rule as the estimation / Bland-Altman builders above.
  const datasets = tableDatasets(table);
  const xCol = xColumn(table);
  const rows = table.rows;
  const cfg = plot.forest ?? {};

  if (datasets.length < 3) warnings.push("Forest plot needs three value columns: estimate, lower CI, upper CI.");
  const estDs = datasets[0];
  const loDs = datasets[1];
  const hiDs = datasets[2];
  interface Study { id: NodeId; label: string; est: number; lo: number; hi: number }
  const studies: Study[] = rows.map((row, i) => ({
    id: row.id,
    label: xCol ? String(row.cells[xCol.id] ?? `Study ${i + 1}`) : `Study ${i + 1}`,
    est: datasetRowValue(estDs, row),
    lo: datasetRowValue(loDs, row),
    hi: datasetRowValue(hiDs, row),
  }));
  const drawable = studies.filter((s) => Number.isFinite(s.est));
  if (rows.length > 0 && drawable.length === 0) warnings.push("No finite estimates to plot.");
  // The no-effect null follows the effect measure, not the display scale: ratio measures
  // (OR/RR/HR) are strictly positive with null = 1; difference measures (mean/risk difference)
  // straddle 0 with null = 0. Only a non-positive value proves the measure is a difference, so
  // that forces the 0 default; all-positive data keeps the ratio default of 1 — an odds-ratio
  // forest stays put whether its axis is linear or log. The user's explicit refValue always
  // wins; `null` hides the line. (Keying off the axis scale instead would wrongly move a
  // linear-axis odds-ratio forest's null from 1 to 0.)
  const refDefault = drawable.every((s) => [s.est, s.lo, s.hi].every((v) => !Number.isFinite(v) || v > 0)) ? 1 : 0;
  const refValue = cfg.refValue === undefined ? refDefault : cfg.refValue;

  // Effect (value) axis = X; honours the standard xAxis spec incl. a log scale.
  const vSpec: AxisSpec = plot.xAxis ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const vRev = vSpec.reversed ?? false;
  const domVals: number[] = [];
  for (const s of drawable) for (const v of [s.est, s.lo, s.hi]) if (Number.isFinite(v)) domVals.push(v);
  if (refValue != null && Number.isFinite(refValue)) domVals.push(refValue);
  let vType: ScaleType = options.yScale ?? vSpec.scale ?? "linear";
  if (isLog(vType) && !domVals.every((v) => v > 0)) {
    vType = "linear";
    warnings.push("Log effect axis needs all-positive values — using linear.");
  }
  if (domVals.length === 0) domVals.push(0, 1);
  const vAuto = buildScale(vType, extent(isLog(vType) ? domVals.filter((v) => v > 0) : domVals), [0, 1], gridDensity, false, vFmt).domain;
  const wf = windowed(vSpec, vAuto, options.xDomain);
  const vData = wf.data;
  const manualV = wf.manual;

  // Pooled inverse-variance summary (fixed- or random-effects) + per-study SE for marker
  // weighting — both honour the entered CI level (cfg.ciLevel), not a hardcoded 1.96, so a
  // study reported at 90/99% is weighted correctly. Random-effects = DerSimonian-
  // Laird; heterogeneity (I², τ²) comes back for either model. Pooling runs in log space on a
  // log axis. All the meta maths lives in core `metaAnalysis` (cross-checked vs statsmodels).
  const showSummary = cfg.showSummary ?? false;
  const inputConf = cfg.ciLevel ?? 0.95;
  const model: "fixed" | "random" = cfg.model === "random" ? "random" : "fixed";
  const zIn = normalCiMultiplier(inputConf);
  const logAxis = isLog(vType);
  const seOf = (s: Study): number => {
    if (!Number.isFinite(s.lo) || !Number.isFinite(s.hi) || s.hi <= s.lo) return NaN;
    if (logAxis && (s.lo <= 0 || s.hi <= 0 || s.est <= 0)) return NaN;
    const se = ((logAxis ? Math.log(s.hi) : s.hi) - (logAxis ? Math.log(s.lo) : s.lo)) / (2 * zIn);
    return se > 0 ? se : NaN;
  };
  const meta = showSummary ? metaAnalysis(drawable, { model, inputConf, pooledConf: 0.95, log: logAxis }) : null;
  const pooled: { est: number; lo: number; hi: number } | null = meta ? { est: meta.est, lo: meta.lo, hi: meta.hi } : null;

  // Marker size ∝ √(inverse-variance weight) when weightMarkers is on.
  const baseSize = plot.seriesStyles?.[estDs?.id ?? ""]?.symbolSize ?? 5;
  const wMax = cfg.weightMarkers
    ? Math.max(0, ...drawable.map((s) => { const se = seOf(s); return Number.isFinite(se) ? 1 / (se * se) : 0; }))
    : 0;
  const sizeOf = (s: Study): number => {
    if (!cfg.weightMarkers || !(wMax > 0)) return baseSize;
    const se = seOf(s);
    if (!Number.isFinite(se)) return baseSize * 0.6;
    return 3 + 7 * Math.sqrt((1 / (se * se)) / wMax);
  };

  // Study (category) axis = Y bands; labels on the left. Summary gets its own band, tagged with
  // the model (RE = random-effects) and the data's heterogeneity I² — the standard readout that
  // says whether pooling was even appropriate.
  const summaryLabel = meta
    ? `Summary${meta.model === "random" ? " (RE)" : ""} · I²=${Math.round(meta.i2)}%`
    : "Summary";
  const nBands = studies.length + (pooled ? 1 : 0);
  const catLabels = [...studies.map((s) => s.label), ...(pooled ? [summaryLabel] : [])];
  // ×1.1 to match the escaping-label trimmer's own margin (resolveAxisExtras measures Y labels
  // at 1.1×); reserving the plain width would under-size the margin, and the widest label — the
  // "Summary · I²=…%" row, or any long study name — would be blanked.
  const catLabelW = Math.max(0, ...catLabels.map((t) => measure(t, fonts.tick.size) * 1.1), turnedYLabelsReach(catLabels, fonts.tick.size, measure, plot.yAxis?.tickRotation));
  const catSpec: AxisSpec = plot.yAxis ?? {};
  const catTitle = catSpec.title ?? "";
  const vTitle = vSpec.title ?? (estDs?.name ?? "Effect");
  const vTickGap = vSpec.tickLabelGap ?? 6;
  const vTitleGap = vSpec.titleGap ?? 6;
  const catTickGap = catSpec.tickLabelGap ?? 8;

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = catSpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catSpec.titleGap ?? 6) : 4) + pad.l;
  const marginBottom = vSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + vTickGap + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, vTitleGap)) + pad.b;
  const marginRight = DEFAULTS.marginRight + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const vb = buildScale(vType, vData, vRev ? [plotW, 0] : [0, plotW], gridDensity, manualV, vFmt, vSpacing);
  const px = (v: number): number => plotX + vb.scale(v);
  const vDomainOut: [number, number] = vRev ? [vb.domain[1], vb.domain[0]] : vb.domain;
  const band = plotH / Math.max(1, nBands);
  const bandCenter = (i: number): number => plotY + i * band + band / 2;

  const style = plot.seriesStyles?.[estDs?.id ?? "forest"];
  const color = style?.color ?? seriesColor(0, palette);
  const marks: MarkScene[] = [];
  studies.forEach((s, i) => {
    if (!Number.isFinite(s.est)) return;
    const cy = bandCenter(i);
    const mark: MarkScene = {
      rowId: s.id, rowNumber: i + 1, dx: s.est, dy: s.est, cx: px(s.est), cy, n: 1,
      label: s.label, symbolSize: sizeOf(s),
    };
    if (Number.isFinite(s.lo)) { mark.errLow = s.lo; mark.errLowCx = px(s.lo); }
    if (Number.isFinite(s.hi)) { mark.errHigh = s.hi; mark.errHighCx = px(s.hi); }
    marks.push(mark);
  });
  const series: SeriesScene[] = [markerSeries(estDs?.id ?? "forest", estDs?.name ?? "Effect", style, color, "square", baseSize, marks)];

  const yticks: AxisTick[] = studies.map((s, i) => ({ value: i + 1, pos: bandCenter(i), label: s.label, minor: false }));
  if (pooled) yticks.push({ value: studies.length + 1, pos: bandCenter(studies.length), label: summaryLabel, minor: false });

  const valAnn = (v: number): number | undefined => px(v);
  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: valAnn, y: valAnn, bracketX: (i: number) => bandCenter(i - 1) },
    true,
    warnings,
  );
  // Vertical no-effect reference line (synthetic — regenerated each build).
  const forestRl = resolveRefLine(plot, "forest-ref", { dash: "4 3", width: 1 });
  if (forestRl.show && refValue != null && Number.isFinite(refValue)) {
    const rx = px(refValue);
    if (rx >= plotX - 0.5 && rx <= plotX + plotW + 0.5) {
      annotations.push({ id: "forest-ref", kind: "line", x1: rx, x2: rx, y1: plotY, y2: plotY + plotH, color: forestRl.color, dash: forestRl.dash, width: forestRl.width });
    }
  }

  const leg = resolveLegend(plot, [], measure, fonts.legend.size, width);
  const scene: PlotScene = {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: vType, domain: vDomainOut, range: [plotX, plotX + plotW], ticks: vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), title: vTitle, ...axisLine(vSpec) },
    y: { type: "linear", band: true, domain: [0, Math.max(1, nBands)], range: [plotY + plotH, plotY], ticks: yticks, title: catTitle, ...axisLine(catSpec) },
    auto: {
      x: options.xDomain != null ? buildScale(vType, wf.home, [0, 1], gridDensity, wf.homeManual, vFmt, vSpacing).domain : vb.domain,
      y: [0, Math.max(1, nBands)],
    },
    // The effect axis runs along X; Y bands the studies.
    zoomable: [{ visual: "x", key: "x" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    valueAxis: "x" as const,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: vTitle, y: catTitle || "Study" }, kind: "forest", fonts, warnings,
  };
  /**
   * The pooled summary, styled like any other data point.
   *
   * It is a mark like the study
   * markers are marks, so it takes the same vocabulary: its own colour, fill mode (solid /
   * open / clear / two-tone), outline colour, outline width, opacity and size.
   *
   * Keyed `forest-summary`, a synthetic id — the summary is computed, not a table column, so
   * there is no dataset to hang it on. Every value falls back to the default look (the
   * study colour, solid, 1px) until something is set.
   *
   * `hidden` is honoured here rather than left to the control: the Series list offers a
   * show/hide toggle for every entry it lists, and a toggle that did nothing would be a dead
   * control the moment "Summary" appeared in that list.
   */
  const sumStyle = plot.seriesStyles?.["forest-summary"];
  /**
   * The link. Ticked (the default) the summary wears the study markers' appearance, so a
   * restyle of the studies carries it along and the chart reads as one object; unticked it
   * uses its own.
   *
   * The default is false on a plot that already carries summary appearance overrides, so a
   * summary styled by hand keeps its own look instead of taking the study look.
   *
   * Note: `summaryShape`, `hidden` and `symbol` are not part of the link: the link carries
   * colours, not form. A pooled diamond among study squares is the convention, not an accident.
   */
  const SUMMARY_LOOK = ["color", "symbolFill", "symbolFillColor", "symbolOpacity", "symbolOutline", "symbolBorderWidth", "borderWidth", "symbolSize", "twoToneTint", "twoToneShade", "twoToneEdge", "filled"] as const;
  const summaryStyled = SUMMARY_LOOK.some((k) => sumStyle?.[k] !== undefined);
  const summaryLinked = sumStyle?.linkSummaryToStudies ?? !summaryStyled;
  const look: SeriesStyle | undefined = summaryLinked ? style : sumStyle;
  if (pooled && sumStyle?.hidden !== true) {
    const cy = bandCenter(studies.length);
    const base = look?.color ?? color;
    const sym = resolveSymbol(look, base);
    // Height follows the marker size, so "Size" means something here too; the horizontal
    // extent stays the CI and is never style. Clamped to the band so it cannot overlap the
    // study above it.
    const halfH = Math.min(band * 0.32 * ((look?.symbolSize ?? 5) / 5), band * 0.46);
    scene.forestSummary = {
      // Note: read from the summary's own style even when linked — see the note above.
      shape: sumStyle?.summaryShape ?? "diamond",
      // The marker form takes the study glyph default ("square") so an unstyled switch to
      // "marker" produces the same mark the studies use, with the CI as its whisker.
      symbol: sumStyle?.symbol ?? "square",
      symbolSize: look?.symbolSize ?? baseSize,
      symbolFill: sym.symbolFill === "clear" ? "clear" : sym.symbolFill === "open" ? "open" : "solid",
      xLo: px(pooled.lo),
      xHi: px(pooled.hi),
      cx: px(pooled.est),
      cy,
      halfH,
      // "clear" = see-through (the outline alone); "open" = the page colour behind it, so
      // it hides what it overlaps; two-tone resolves to "open" carrying a derived light
      // interior. Caution: `open` must not fall back to the series colour — that would fill a
      // hollow diamond solid and make the Fill control look broken.
      color:
        sym.symbolFill === "clear"
          ? "none"
          : sym.symbolFill === "open"
            ? (sym.symbolFillColor ?? "var(--bg)")
            : (sym.symbolFillColor ?? base),
      fillOpacity: sym.symbolOpacity ?? 1,
      outline: sym.symbolOutline ?? base,
      outlineWidth: look?.symbolBorderWidth ?? look?.borderWidth ?? 1,
    };
  }
  return scene;
}

/**
 * Bland-Altman method-comparison plot: for each paired row X = the mean of the
 * two methods, Y = their difference (A − B, or a percent of the mean). Horizontal
 * reference lines mark the bias (mean difference) and the limits of agreement
 * (bias ± k·SD). A plain scatter scene (renders through the default marker path).
 */
function buildBlandAltmanScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a Bland-Altman plot", warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const datasets = tableDatasets(table); // positional, not independent series — see note below
  // Not `visibleDatasets`. This builder reads datasets by position (control vs test,
  // method A vs B, left vs right), so dropping a hidden one renumbers the rest and the
  // chart silently compares a different pair. In Bland-Altman, for example, `styleId` is
  // `datasets[1].id`, so filtering would make the hidden lookup miss and bring the legend back.
  // Hiding a structural input is not "show less", it is "compute something else".
  const cfg = plot.blandAltman ?? {};
  const percent = cfg.percent ?? false;
  const k = cfg.agreementK ?? 1.96;
  // Bland-Altman compares two measurement columns (A vs B). An analysis-spawned plot is created
  // on an "xy" table, so method A lands in the x-role column and tableDatasets sees only one
  // dataset — fall back to (x column, dataset 0) so it isn't empty; otherwise use the first two.
  const xc = xColumn(table);
  const twoDatasets = datasets.length >= 2;
  const aVal = (row: Row): number => (twoDatasets ? datasetRowValue(datasets[0], row) : xc ? toNumber(row.cells[xc.id]) : NaN);
  const bVal = (row: Row): number => (twoDatasets ? datasetRowValue(datasets[1], row) : datasetRowValue(datasets[0], row));
  const aName = twoDatasets ? datasets[0]!.name : xc?.name ?? "A";
  const bName = twoDatasets ? datasets[1]!.name : datasets[0]?.name ?? "B";
  const styleId = (twoDatasets ? datasets[1]?.id : datasets[0]?.id) ?? "";
  if (!twoDatasets && !(datasets.length === 1 && xc)) warnings.push("Bland-Altman needs two measurement columns (methods A and B).");
  interface Pt { id: NodeId; n: number; mean: number; diff: number }
  const pts: Pt[] = [];
  table.rows.forEach((row, i) => {
    const a = aVal(row);
    const b = bVal(row);
    if (!Number.isFinite(a) || !Number.isFinite(b)) return;
    const mean = (a + b) / 2;
    const diff = percent ? (mean !== 0 ? (100 * (a - b)) / mean : NaN) : a - b;
    if (!Number.isFinite(diff)) return;
    pts.push({ id: row.id, n: i + 1, mean, diff });
  });
  if (table.rows.length > 0 && pts.length === 0) warnings.push("No paired finite values to plot.");
  const diffs = pts.map((p) => p.diff);
  const bias = diffs.length ? diffs.reduce((s, v) => s + v, 0) / diffs.length : 0;
  const sd = diffs.length >= 2 ? Math.sqrt(diffs.reduce((s, v) => s + (v - bias) ** 2, 0) / (diffs.length - 1)) : 0;
  const loaHi = bias + k * sd;
  const loaLo = bias - k * sd;

  const xSpec: AxisSpec = plot.xAxis ?? {};
  const xFmt = tickFormat(xSpec);
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const xRev = xSpec.reversed ?? false;
  const manualX = xSpec.min != null || xSpec.max != null || options.xDomain != null;
  const means = pts.map((p) => p.mean);
  let xType: ScaleType = xSpec.scale ?? "linear";
  if (isLog(xType) && !means.every((v) => v > 0)) { xType = "linear"; warnings.push("Log X needs all-positive means — using linear."); }
  const xAuto = buildScale(xType, extent(means.length ? means : [0, 1]), [0, 1], gridDensity, false, xFmt).domain;
  const wx = windowed(xSpec, xAuto, options.xDomain);
  const xData = wx.data;

  const ySpec: AxisSpec = plot.yAxis ?? {};
  const yFmt = tickFormat(ySpec);
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yRev = ySpec.reversed ?? false;
  const manualY = ySpec.min != null || ySpec.max != null || options.yDomain != null;
  // Include the bias + LoA lines in the domain so they are always visible.
  const yVals = diffs.slice();
  if (Number.isFinite(bias)) yVals.push(bias);
  if (sd > 0) yVals.push(loaHi, loaLo);
  if (yVals.length === 0) yVals.push(0, 1);
  const yType: ScaleType = "linear"; // differences span zero → always linear
  const yAuto = buildScale(yType, extent(yVals), [0, 1], gridDensity, false, yFmt).domain;
  const wy = windowed(ySpec, yAuto, options.yDomain);
  const yData = wy.data;

  const yProbe = buildScale(yType, yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  const yTitle = ySpec.title ?? (percent ? "Difference (%)" : `Difference (${aName} − ${bName})`);
  const xTitle = xSpec.title ?? "Mean of methods";
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = ySpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (ySpec.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6)) + pad.l;
  const marginBottom = xSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + (xSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, xSpec.titleGap ?? 6)) + pad.b;
  const style = plot.seriesStyles?.[styleId];
  const color = style?.color ?? seriesColor(0, palette);
  // Bland-Altman draws one "Difference" series — give the legend a single entry (in the series
  // colour) so an explicitly-enabled legend shows something instead of nothing.
  const leg = resolveLegend(plot, style?.hidden ? [] : [{ label: "Difference", color, select: { as: "series" as const, id: styleId } }], measure, fonts.legend.size, width);
  // Reserve the right margin for the widest limit-of-agreement label actually drawn (±k·SD,
  // honouring any renamed label) — not a literal "1.96", which would mis-size the reserve for
  // every other agreement multiplier.
  const loaLabelW = Math.max(
    measure(plot.refLineLabels?.["ba-loa-hi"] ?? `+${k} SD`, fonts.legend.size),
    measure(plot.refLineLabels?.["ba-loa-lo"] ?? `−${k} SD`, fonts.legend.size),
  );
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + loaLabelW + 8 + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale(xType, xData, xRev ? [plotW, 0] : [0, plotW], gridDensity, manualX, xFmt, xSpacing);
  const yb = buildScale(yType, yData, yRev ? [0, plotH] : [plotH, 0], gridDensity, manualY, yFmt, ySpacing);
  const px = (v: number): number => plotX + xb.scale(v);
  const py = (v: number): number => plotY + yb.scale(v);

  const marks: MarkScene[] = pts.map((p) => ({ rowId: p.id, rowNumber: p.n, dx: p.mean, dy: p.diff, cx: px(p.mean), cy: py(p.diff), n: 1 }));
  // One "Difference" series; the Inspector lists it as a single entry keyed by styleId, so
  // its show/hide toggle (seriesStyles[styleId].hidden) must drop the plotted points.
  const series: SeriesScene[] = style?.hidden ? [] : [markerSeries(styleId || "bland", "Difference", style, color, "circle", 4, marks)];

  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: (v: number) => px(v), y: (v: number) => py(v), bracketX: (v: number) => px(v) },
    false,
  );
  // Bias (solid) + limits-of-agreement (dashed) reference lines. The per-line dash is
  // kept (bias solid, LoA dashed) so the distinction survives; only colour/width/show
  // are user-overridable via refLine.
  const refLine = (id: string, val: number, dash: string, w: number, label: string): void => {
    // Two switches, deliberately separate: `refLine.show` hides all three at once, and
    // `refLineHidden[id]` drops just this one. The per-line one is what "delete this line"
    // resolves to — a computed line has no entry in `plot.annotations`, so a delete could not
    // stick; it would be back on the next rebuild. Both live in `resolveRefLine.show`.
    const baRl = resolveRefLine(plot, id, { dash, width: w });
    if (!baRl.show || !Number.isFinite(val)) return;
    const y = py(val);
    if (y < plotY - 0.5 || y > plotY + plotH + 0.5) return;
    // `locked`: these sit at computed statistics (bias = mean difference, LoA = bias ± k·SD).
    // Dragging one would assert a bias the data doesn't have, so the renderer must offer no
    // move affordance.
    // The caption is a different question with the opposite answer: it carries no claim
    // about the data, and parked at the right edge it lands on the points. So it gets
    // `labelOffset` — the renderer translates the words, never the line.
    annotations.push({ id, kind: "line", x1: plotX, x2: plotX + plotW, y1: y, y2: y, color: baRl.color, dash: baRl.dash, width: baRl.width, label: plot.refLineLabels?.[id] ?? label, labelX: plotX + plotW - 2, labelY: y - 3, labelAnchor: "end", labelOffset: plot.refLineLabelOffsets?.[id] ?? { dx: 0, dy: 0 }, locked: true, deletable: false });
  };
  refLine("ba-bias", bias, dashArray("solid", 1.25) ?? "", 1.25, `Bias ${Number(bias.toFixed(2))}`);
  if (sd > 0) {
    refLine("ba-loa-hi", loaHi, "5 3", 1, `+${k} SD`);
    refLine("ba-loa-lo", loaLo, "5 3", 1, `−${k} SD`);
  }

  const scene: PlotScene = {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: xType, domain: xRev ? [xb.domain[1], xb.domain[0]] : xb.domain, range: [plotX, plotX + plotW], ticks: xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), title: xTitle, ...axisLine(xSpec) },
    y: { type: yType, domain: yRev ? [yb.domain[1], yb.domain[0]] : yb.domain, range: [plotY + plotH, plotY], ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yTitle, ...axisLine(ySpec) },
    auto: {
      x: options.xDomain != null ? buildScale("linear", wx.home, [0, 1], gridDensity, wx.homeManual, xFmt, xSpacing).domain : xb.domain,
      y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain,
    },
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: xTitle, y: yTitle }, kind: "blandaltman", fonts, warnings,
  };
  return scene;
}

/**
 * Population pyramid: mirrored horizontal bars over shared categories (rows).
 * The first two value columns are the two groups — group 1 grows left of a central
 * zero axis, group 2 grows right. The value axis is symmetric and its tick labels
 * show absolute magnitudes. Renders through the categorical bar path (m.bar rects).
 */
function buildPyramidScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a population pyramid", warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const datasets = tableDatasets(table); // positional, not independent series — see note below
  // Not `visibleDatasets`. This builder reads datasets by position (control vs test,
  // method A vs B, left vs right), so dropping a hidden one renumbers the rest and the
  // chart silently compares a different pair. In Bland-Altman, for example, `styleId` is
  // `datasets[1].id`, so filtering would make the hidden lookup miss and bring the legend back.
  // Hiding a structural input is not "show less", it is "compute something else".
  const xCol = xColumn(table);
  const rows = table.rows;
  const cfg = plot.pyramid ?? {};
  const barFrac = Math.min(1, Math.max(0.1, cfg.barWidth ?? 0.8));
  const showValues = cfg.showValues ?? false;
  if (datasets.length < 2) warnings.push("Population pyramid needs two value columns (the two groups).");
  const leftDs = datasets[0];
  const rightDs = datasets[1];
  interface Cat { id: NodeId; label: string; left: number; right: number }
  const cats: Cat[] = rows.map((row, i) => ({
    id: row.id,
    label: xCol ? String(row.cells[xCol.id] ?? i + 1) : String(i + 1),
    left: datasetRowValue(leftDs, row),
    right: datasetRowValue(rightDs, row),
  }));
  const mags = cats.flatMap((c) => [Math.abs(c.left), Math.abs(c.right)]).filter((v) => Number.isFinite(v) && v > 0);
  const maxMag = mags.length ? Math.max(...mags) : 1;
  if (rows.length > 0 && mags.length === 0) warnings.push("No finite values to plot.");

  // Value axis = X, symmetric about 0; honours a manual range (overrides symmetry).
  const vSpec: AxisSpec = plot.xAxis ?? {};
  const vFmt = tickFormat(vSpec);
  const vSpacing: TickSpacing = { majorStep: vSpec.majorStep, minorCount: vSpec.minorCount, breaks: vSpec.breaks };
  const vRev = vSpec.reversed ?? false;
  const symAuto = buildScale("linear", [-maxMag, maxMag], [0, 1], gridDensity, false, vFmt).domain;
  const wp = windowed(vSpec, symAuto, options.xDomain);
  const manualV = wp.manual;
  let vData = wp.data;

  const catLabels = cats.map((c) => c.label);
  const catLabelW = Math.max(0, ...catLabels.map((t) => measure(t, fonts.tick.size)), turnedYLabelsReach(catLabels, fonts.tick.size, measure, plot.yAxis?.tickRotation));
  const catSpec: AxisSpec = plot.yAxis ?? {};
  const catTitle = catSpec.title ?? (xCol?.name ?? "");
  const vTitle = vSpec.title ?? "Count";
  const vTickGap = vSpec.tickLabelGap ?? 6;
  const catTickGap = catSpec.tickLabelGap ?? 8;

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = catSpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + catTickGap + (catTitle ? textBand(fonts.yAxisTitle.size, catSpec.titleGap ?? 6) : 4) + pad.l;
  const marginBottom = vSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + vTickGap + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, vSpec.titleGap ?? 6)) + pad.b;
  // A pyramid draws bars: each side's key is the bar's filled block (keys follow their marks).
  const leg = resolveLegend(plot, datasets.slice(0, 2).map((ds, i) => ({ label: ds.name, color: plot.seriesStyles?.[ds.id]?.color ?? seriesColor(i, palette), swatch: "bar" as const, select: { as: "series" as const, id: ds.id } })), measure, fonts.legend.size, width);
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  // Tip labels fit inside the plot (otherwise, e.g., a 97 on a 0–100 axis would put its label "97" on the neighbouring
  // row name). Each number sits 4 px past its bar's tip, so the half-range must hold the longest bar and its
  // label: D >= |v| * half / (half - 4 - labelWidth). Grown only when a label would cross the plot edge, only on the
  // automatic range (a range the user set is theirs), and never for a label the user dragged elsewhere.
  // The same growth applies to the home range reported while zoomed, so zoomed and un-zoomed agree on where home is.
  const fitTips = (d: [number, number]): [number, number] => {
    if (!showValues) return d;
    const half = plotW / 2;
    let need = Math.max(Math.abs(d[0]), Math.abs(d[1]));
    const d0 = need;
    cats.forEach((c) => {
      datasets.slice(0, 2).forEach((ds, di) => {
        const v = di === 0 ? c.left : c.right;
        const key = `${ds.id}-${c.id}`;
        if (!Number.isFinite(v) || cfg.valueLabelPos?.[key]) return;
        const text = cfg.valueLabelText?.[key] ?? String(Number(Math.abs(v).toFixed(2)));
        const room = half - 4 - measure(text, fonts.valueLabel.size) - 1;
        if (room > 0) need = Math.max(need, (Math.abs(v) * half) / room);
      });
    });
    return need > d0 ? buildScale("linear", [-need, need], [0, 1], gridDensity, false, vFmt).domain : d;
  };
  if (!manualV && options.xDomain == null) vData = fitTips(vData);
  const vb = buildScale("linear", vData, vRev ? [plotW, 0] : [0, plotW], gridDensity, manualV, vFmt, vSpacing);
  const px = (v: number): number => plotX + vb.scale(v);
  const vDomainOut: [number, number] = vRev ? [vb.domain[1], vb.domain[0]] : vb.domain;
  const zeroX = px(0);
  const n = cats.length;
  const band = plotH / Math.max(1, n);
  const bandCenter = (i: number): number => plotY + i * band + band / 2;
  const barH = band * barFrac;

  const valueAnns: AnnotationScene[] = [];
  const mkSeries = (ds: Dataset, di: number, sign: 1 | -1): SeriesScene => {
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(di, palette);
    const marks: MarkScene[] = [];
    cats.forEach((c, i) => {
      const v = di === 0 ? c.left : c.right;
      if (!Number.isFinite(v)) return;
      const cy = bandCenter(i);
      const tipX = px(sign * Math.abs(v));
      const x0 = Math.min(zeroX, tipX);
      const w = Math.abs(tipX - zeroX);
      marks.push({ rowId: c.id, rowNumber: i + 1, dx: sign * Math.abs(v), dy: v, cx: x0 + w / 2, cy, n: 1, label: c.label, bar: { x: x0, y: cy - barH / 2, w, h: barH } });
      if (showValues && Number.isFinite(v)) {
        // Honour a per-label drag override (fractional plot-rect coords) if the user
        // has repositioned this value label; otherwise sit at the bar tip.
        const key = `${ds.id}-${c.id}`;
        const pos = cfg.valueLabelPos?.[key];
        valueAnns.push({
          // deletable:false — builder-owned: it has no plot.annotations entry and is
          // regenerated from the data each rebuild, so removeAnnotation refuses it. The
          // renderer must therefore not draw a delete (×) handle on it (hide the class via showValues).
          id: `pyr-val-${key}`, kind: "text", deletable: false, color: fonts.valueLabel.color, dash: null, width: 0,
          // An edited value label (presentation override) wins over the formatted value.
          label: cfg.valueLabelText?.[key] ?? String(Number(Math.abs(v).toFixed(2))),
          labelX: pos ? plotX + pos.x * plotW : tipX + sign * 4,
          labelY: pos ? plotY + pos.y * plotH : cy + fonts.valueLabel.size * 0.34,
          labelAnchor: sign < 0 ? "end" : "start", fontSize: fonts.valueLabel.size,
          // Carry the value-label font so a font control changes the tip numbers' typeface.
          ...(fonts.valueLabel.family ? { fontFamily: fonts.valueLabel.family } : {}),
          ...(fonts.valueLabel.weight >= 600 ? { bold: true } : {}),
          ...(fonts.valueLabel.italic ? { italic: true } : {}),
        });
      }
    });
    return {
      id: ds.id, name: ds.name, color, linePath: "", symbol: "square", symbolSize: 4,
      ...resolveSymbol(style, color), borderWidth: style?.borderWidth ?? 1, lineWidth: 2, dash: null,
      errorCaps: false, errorDir: "both", ...seriesExtras(style, color, 2, 4, 0.9), marks,
    };
  };
  // Only build a side for each value column that actually exists (a 1-column table
  // draws just the left side rather than crashing on a missing second dataset).
  const series: SeriesScene[] = [];
  if (leftDs) series.push(mkSeries(leftDs, 0, -1));
  if (rightDs) series.push(mkSeries(rightDs, 1, 1));

  const yticks: AxisTick[] = cats.map((c, i) => ({ value: i + 1, pos: bandCenter(i), label: c.label, minor: false }));
  // Value ticks: symmetric positions, labels show absolute magnitude (strip the sign).
  const xticks: AxisTick[] = vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos, label: t.label.replace(/^[-−]/, "") }));

  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: (v: number) => px(v), y: (v: number) => px(v), bracketX: (i: number) => bandCenter(i - 1) },
    true,
    warnings,
  );
  const pyrCenter = resolveRefLine(plot, "pyr-center", { dash: null, width: 1 });
  if (pyrCenter.show) {
    annotations.push({ id: "pyr-center", kind: "line", x1: zeroX, x2: zeroX, y1: plotY, y2: plotY + plotH, color: pyrCenter.color, dash: pyrCenter.dash, width: pyrCenter.width });
  }
  annotations.push(...valueAnns);

  return {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: "linear", domain: vDomainOut, range: [plotX, plotX + plotW], ticks: xticks, title: vTitle, ...axisLine(vSpec) },
    y: { type: "linear", band: true, domain: [0, Math.max(1, n)], range: [plotY + plotH, plotY], ticks: yticks, title: catTitle, ...axisLine(catSpec) },
    auto: {
      x: options.xDomain != null ? buildScale("linear", wp.homeManual ? wp.home : fitTips(wp.home), [0, 1], gridDensity, wp.homeManual, vFmt, vSpacing).domain : vb.domain,
      y: [0, Math.max(1, n)],
    },
    // Values run left/right along X; Y bands the shared categories.
    zoomable: [{ visual: "x", key: "x" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    valueAxis: "x" as const,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: vTitle, y: catTitle || "Group" }, kind: "pyramid", fonts, barHorizontal: true, warnings,
  };
}

/**
 * PCA scatter family: score plot (`pcascore`, cases in PC space, coloured by
 * group), loadings plot (`pcaload`, one arrow per variable from the origin), and
 * biplot (`pcabiplot`, scores + scaled loading arrows overlaid). Reads `plot.pca`
 * (from a PCA analysis). Axes are labelled "PCk (xx.x%)"; a dashed origin cross is
 * drawn. Renders through the default marker path (a non-categorical scene).
 */
function buildPcaScatterScene(_table: DataTable, plot: Plot, options: BuildPlotSceneOptions, kind: PlotScene["kind"]): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, kind === "pcaload" ? "a PCA loadings plot" : kind === "pcabiplot" ? "a PCA biplot" : kind === "triplot" ? "an ordination triplot" : "an ordination score plot", warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const pca = plot.pca;
  const cfg = plot.pcaStyle ?? {};
  const ncomp = pca?.pcLabels?.length ?? 0;
  if (!pca || ncomp === 0) warnings.push(kind === "triplot" ? "No ordination data to plot." : "No PCA data to plot.");
  // A triplot without its explanatory variables is a score plot wearing the wrong name —
  // say so rather than drawing two thirds of a picture in silence.
  if (kind === "triplot" && pca && (pca.envScores?.length ?? 0) === 0) {
    warnings.push("This graph has no explanatory variables, so it draws no arrows — a triplot needs a constrained ordination (Analyze ▸ redundancy analysis).");
  }
  const xi = Math.max(0, Math.min(Math.max(0, ncomp - 1), cfg.xComponent ?? 0));
  const yi = Math.max(0, Math.min(Math.max(0, ncomp - 1), cfg.yComponent ?? 1));
  const isBiplot = kind === "pcabiplot";
  /**
   * A triplot is the constrained ordination's graph: the cases, the response variables as
   * points, and the explanatory variables as arrows from the origin. It shares this builder
   * rather than forking one — the score cloud, the arrow drawing, the per-arrow colours and
   * the draggable/renameable arrow labels are all already here, so a second parallel scatter
   * builder would only duplicate them.
   */
  const isTriplot = kind === "triplot";
  const showScores = kind === "pcascore" || isBiplot || (isTriplot && cfg.showSites !== false);
  const showLoadings = kind === "pcaload" || isBiplot;

  /**
   * LC vs WA — the choice the ordination literature argues about, and the reason it is
   * offered by name. LC places each case from the explanatory variables (the fitted
   * values); WA places it from what was actually observed. They agree where the model fits and
   * separate where it does not, so a figure has to say which it drew.
   */
  const siteScoreMode = cfg.siteScores ?? "wa";
  const scores = (isTriplot
    ? (siteScoreMode === "lc" ? pca?.lcScores : pca?.waScores) ?? pca?.scores
    : pca?.scores) ?? [];
  const loadings = pca?.loadings ?? [];
  const varLabels = pca?.varLabels ?? [];
  const groups = pca?.groups;
  /**
   * Species points — an ordination (CA / PCoA / NMDS) places the variables in the same space
   * as the cases, as positions rather than as arrows. They are not loadings and must never
   * be drawn as vectors from the origin: a loading is a direction, a species point is a place.
   * Only the score plot shows them (a loadings plot has no scores to sit them among).
   */
  const speciesRaw = pca?.speciesScores ?? [];
  const speciesLabels = pca?.speciesLabels ?? varLabels;
  const showSpecies = (kind === "pcascore" || isTriplot) && speciesRaw.length > 0 && cfg.showSpecies !== false;
  const speciesPts = showSpecies
    ? speciesRaw
      .map((sp, j) => ({ j, label: speciesLabels[j] ?? `V${j + 1}`, x: sp[xi] ?? NaN, y: sp[yi] ?? NaN }))
      .filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y))
    : [];
  /**
   * The third family — the explanatory variables. A continuous one is an arrow from the origin
   * (its direction is the direction of increase); a level of a factor is a centroid, because
   * "Management: grazed" names a place in the ordination and has no direction of increase. The
   * builder must not draw one as the other: an arrow on a category is a claim the data cannot
   * support.
   */
  const envRaw = pca?.envScores ?? [];
  const envLabels = pca?.envLabels ?? [];
  const envIsFactor = pca?.envIsFactor ?? [];
  const showEnv = isTriplot && envRaw.length > 0 && cfg.showEnv !== false;
  // `speciesAs: "arrows"` draws the response variables as vectors from the origin instead of
  // points — the convention some journals use for an RDA. The points series is then not drawn,
  // or the same variable would appear twice.
  const speciesAsArrows = isTriplot && cfg.speciesAs === "arrows";
  const envRawPts = showEnv
    ? envRaw
      .map((e, j) => ({ j, label: envLabels[j] ?? `X${j + 1}`, centroid: envIsFactor[j] === true, x: e[xi] ?? NaN, y: e[yi] ?? NaN }))
      .filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y))
    : [];

  interface Pt { i: number; x: number; y: number }
  const scorePts: Pt[] = showScores
    ? scores.map((s, i) => ({ i, x: s[xi] ?? NaN, y: s[yi] ?? NaN })).filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y))
    : [];
  const maxAbs = (a: number[]): number => (a.length ? Math.max(...a.map((v) => Math.abs(v))) : 0);
  const rawLoad = showLoadings
    ? loadings.map((l, i) => ({ label: varLabels[i] ?? `V${i + 1}`, x: l[xi] ?? NaN, y: l[yi] ?? NaN })).filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y))
    : [];
  // Biplot: scale the loading arrows to fill the score cloud (standard 0.8× reach).
  let loadScale = 1;
  if (isBiplot && rawLoad.length && scorePts.length) {
    const sMax = Math.max(maxAbs(scorePts.map((p) => p.x)), maxAbs(scorePts.map((p) => p.y)));
    const lMax = Math.max(maxAbs(rawLoad.map((p) => p.x)), maxAbs(rawLoad.map((p) => p.y)));
    loadScale = lMax > 0 ? (0.8 * sMax) / lMax : 1;
  }
  const loadPts = rawLoad.map((p) => ({ ...p, x: p.x * loadScale, y: p.y * loadScale }));
  // The explanatory scores are correlations, so they never leave the unit circle and would sit
  // in a knot at the origin beside a score cloud several units wide. Stretch them to the
  // cloud's reach — 0.8 of it by convention, and user-settable because the right stretch
  // differs from one ordination figure to the next.
  const envReach = Math.max(0.05, Math.min(5, cfg.arrowScale ?? 0.8));
  let envScale = 1;
  if (envRawPts.length && scorePts.length) {
    const sMax = Math.max(maxAbs(scorePts.map((p) => p.x)), maxAbs(scorePts.map((p) => p.y)));
    const eMax = Math.max(maxAbs(envRawPts.map((p) => p.x)), maxAbs(envRawPts.map((p) => p.y)));
    envScale = eMax > 0 ? (envReach * sMax) / eMax : 1;
  }
  const envPts = envRawPts.map((p) => ({ ...p, x: p.x * envScale, y: p.y * envScale }));

  // ── Score-dot size = a third component, drawn as depth. The most
  // negative score on that component is the smallest dot (far), the most positive the
  // largest (near) — signed, so the two ends of the depth axis never draw alike.
  // -1 = off. The radii and the size legend come from `plot.bubble`, shared with the
  // bubble chart's editor.
  //
  // Components are orthogonal by construction, so on a score plot the size carries
  // information genuinely independent of the two positions: nothing is said twice, and it
  // is what separates two clusters that overlap in PC1–PC2. A biplot's arrows are the
  // variables projected onto the two plotted axes only, so a big dot there has no vector to
  // explain it; the user can still choose not to use the third dimension. Both score plot
  // and biplot auto-size by the first unplotted component; -1 is the off switch.
  const autoSizeIdx = kind === "pcascore" || kind === "pcabiplot" ? (Array.from({ length: ncomp }, (_, k) => k).find((k) => k !== xi && k !== yi) ?? -1) : -1;
  const sizeIdx = cfg.sizeComponent === undefined ? autoSizeIdx : Math.trunc(cfg.sizeComponent);
  const sizeScoreOf = (i: number): number | undefined => {
    const v = scores[i]?.[sizeIdx];
    return Number.isFinite(v) ? v : undefined;
  };
  const sizeVals: number[] = sizeIdx >= 0 && sizeIdx < ncomp
    ? scorePts.map((p) => sizeScoreOf(p.i)).filter((v): v is number => v !== undefined)
    : [];
  const sizeOn = sizeVals.length > 0;
  const dotMinR = Math.max(0.5, plot.bubble?.minRadius ?? 2);
  const dotMaxR = Math.max(dotMinR, plot.bubble?.maxRadius ?? 9);
  const sizeExt = sizeOn ? extent(sizeVals) : ([0, 1] as [number, number]);
  const dotRadius = (v: number): number => {
    if (sizeExt[1] === sizeExt[0]) return (dotMinR + dotMaxR) / 2;
    // Area-proportional, exactly as the bubble chart does it: equal score steps are
    // equal ink steps, so a dot twice the value is twice the ink, not four times.
    const t = (v - sizeExt[0]) / (sizeExt[1] - sizeExt[0]);
    return Math.sqrt(Math.max(0, dotMinR * dotMinR + t * (dotMaxR * dotMaxR - dotMinR * dotMinR)));
  };
  /** Per-mark radius override for case `i`; nothing when depth sizing is off. */
  const dotSizeOf = (i: number): { symbolSize?: number } => {
    if (!sizeOn) return {};
    const v = sizeScoreOf(i);
    return v === undefined ? {} : { symbolSize: dotRadius(v) };
  };
  const showSizeLegend = sizeOn && (plot.bubble?.showSizeLegend ?? true);
  const sizeLegendScale = Math.max(0.3, Math.min(5, plot.bubble?.sizeLegendScale ?? 1));
  const sizeRefItems: { radius: number; label: string }[] = (() => {
    if (!showSizeLegend) return [];
    const fmtSize = (v: number): string => String(Number(v.toFixed(Math.abs(v) >= 100 ? 0 : 2)));
    const [lo, hi] = sizeExt;
    const explicit = plot.bubble?.sizeLegendValues?.filter((v) => Number.isFinite(v));
    const vals = explicit && explicit.length ? [...explicit].sort((a, b) => b - a) : lo === hi ? [lo] : [hi, (lo + hi) / 2, lo];
    return vals.map((v) => ({ radius: Math.max(1, dotRadius(v) * sizeLegendScale), label: fmtSize(v) }));
  })();
  const sizeLegendMaxR = sizeRefItems.length ? Math.max(...sizeRefItems.map((i) => i.radius)) : 0;
  // A component the user picked that this analysis does not have is a silent no-op
  // otherwise — say so instead of drawing uniform dots and letting them wonder.
  if (showScores && sizeIdx >= 0 && !sizeOn) {
    warnings.push(sizeIdx >= ncomp ? `No ${`PC${sizeIdx + 1}`} in this analysis — dot size is off.` : "No scores on that component — dot size is off.");
  }

  const domX: number[] = [0];
  const domY: number[] = [0];
  for (const p of scorePts) { domX.push(p.x); domY.push(p.y); }
  for (const p of loadPts) { domX.push(p.x); domY.push(p.y); }
  // The species are data on these axes, so the scale has to hold them. Left out, a CA would
  // draw its species off the edge of the plot — the half of the picture the method exists for.
  for (const p of speciesPts) { domX.push(p.x); domY.push(p.y); }
  for (const p of envPts) { domX.push(p.x); domY.push(p.y); }
  if (domX.length === 1) { domX.push(-1, 1); domY.push(-1, 1); }

  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const xFmt = tickFormat(xSpec);
  const yFmt = tickFormat(ySpec);
  const xSpacing: TickSpacing = { majorStep: xSpec.majorStep, minorCount: xSpec.minorCount, breaks: xSpec.breaks };
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const xRev = xSpec.reversed ?? false;
  const yRev = ySpec.reversed ?? false;
  const wx = windowed(xSpec, buildScale("linear", extent(domX), [0, 1], gridDensity, false, xFmt).domain, options.xDomain);
  const wy = windowed(ySpec, buildScale("linear", extent(domY), [0, 1], gridDensity, false, yFmt).domain, options.yDomain);
  const manualX = wx.manual;
  const manualY = wy.manual;
  const xData = wx.data;
  const yData = wy.data;

  const pct = (k: number): string => (pca && Number.isFinite(pca.explained[k]) ? ` (${((pca.explained[k] ?? 0) * 100).toFixed(1)}%)` : "");
  const xLabel = xSpec.title ?? `${pca?.pcLabels?.[xi] ?? `PC${xi + 1}`}${pct(xi)}`;
  const yLabel = ySpec.title ?? `${pca?.pcLabels?.[yi] ?? `PC${yi + 1}`}${pct(yi)}`;

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);

  // Score points colour by group → a legend entry per group.
  const groupList = showScores && groups ? [...new Set(scorePts.map((p) => groups[p.i] ?? "—"))] : [];
  const rawLegend: LegendEntry[] = groupList.map((g, i) => ({ label: g, color: plot.seriesStyles?.[`pca-g${i}`]?.color ?? seriesColor(i, palette), select: { as: "series" as const, id: `pca-g${i}` } }));
  const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = ySpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (ySpec.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6)) + pad.l;
  const marginBottom = xSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + (xSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, xSpec.titleGap ?? 6)) + pad.b;
  // "PC3 (14.0%)", not bare "PC3" — the same `pct()` the axis titles carry. Without the share
  // the reader cannot tell whether the dot sizes are worth attending to at all.
  const sizeLegendTitle = plot.bubble?.sizeLegendTitle ?? `${pca?.pcLabels?.[sizeIdx] ?? `PC${sizeIdx + 1}`}${pct(sizeIdx)}`;
  // Reserve room on the right for the depth-size legend. Measure all three parts: the block
  // is as wide as the wider of (spheres + value labels) and its title, and the title usually
  // wins here — with the variance share, "PC3 (14.0%)" would run out under the group legend
  // with a fixed allowance.
  const sizeLegendWidth = showSizeLegend
    ? Math.max(
        sizeLegendMaxR * 2 + 8 + Math.max(0, ...sizeRefItems.map((i) => measure(i.label, fonts.legend.size))),
        measure(sizeLegendTitle, fonts.legend.size),
      )
    : 0;
  const sizeLegendWant = showSizeLegend ? 16 + sizeLegendWidth + 10 : 0;
  /**
   * A key that leaves no graph is not a key. On a narrow figure this column plus the group
   * legend would swallow the plot: a 360-wide score plot would keep 51 px of plot rect (14% of
   * the width), against 271 px (47%) at the 580 default. The dots stay sized either way — that
   * is the feature; the column is the explanation, and an explanation is what is dropped first.
   * Reported in a warning, never silently.
   */
  const MIN_PLOT_SHARE = 0.20;
  /**
   * And the whole stack, on a plot that has names to place. `resolveLegend` breaks long labels onto
   * more lines so the legend alone stays within about a third of the width; the dot-size key is a second
   * column in the same margin, and each can stay within its own limit while together they leave the
   * biplot too narrow for its variable names, so a name would be printed across another arrow. A biplot / triplot has arrows
   * to label, so its plot needs the room; when the two columns together would take more than
   * 45% of the width, the group legend moves inside (bottom-right, losing nothing — same rows,
   * same text) and the key keeps the margin. A score plot with no arrows is unaffected.
   */
  const hasArrowLabels = (showLoadings && loadPts.length > 0) || envPts.some((p) => !p.centroid) || (speciesAsArrows && speciesPts.length > 0);
  if (hasArrowLabels && leg.layout.position === "right" && leg.outsideRightWidth + sizeLegendWant > width * 0.45) {
    leg.layout = { ...leg.layout, position: "bottomright" };
    leg.outsideRightWidth = 0;
  }
  const marginRightBase = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const sizeLegendFits = sizeLegendWant > 0 && width - marginLeft - marginRightBase - sizeLegendWant >= width * MIN_PLOT_SHARE;
  const sizeLegendMargin = sizeLegendFits ? sizeLegendWant : 0;
  if (sizeLegendWant > 0 && !sizeLegendFits) {
    warnings.push("Not enough room for the dot-size key at this figure width — the dots are still sized, but the key is hidden. Widen the figure to bring it back.");
  }
  // …and push the group legend past it. Both are drawn from the plot's right edge, so
  // without this the group names would land on top of the size spheres and their labels.
  // The room is already in marginRight; this only says which column comes first.
  if (sizeLegendMargin) leg.layout = { ...leg.layout, outsidePad: sizeLegendMargin };
  const marginRight = marginRightBase + sizeLegendMargin;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xRangePca: [number, number] = xRev ? [plotW, 0] : [0, plotW];
  const yRangePca: [number, number] = yRev ? [0, plotH] : [plotH, 0];
  const xbRaw = buildScale("linear", xData, xRangePca, gridDensity, manualX, xFmt, xSpacing);
  const ybRaw = buildScale("linear", yData, yRangePca, gridDensity, manualY, yFmt, ySpacing);
  // 1:1 scale. An ordination map is read as distances, so this is on by default for these
  // kinds (KIND_HOUSE_DEFAULTS) rather than opt-in as it is on an ordinary scatter.
  const { xb, yb } = applyEqualAspect({
    on: plot.equalAspect === true,
    xType: "linear", yType: "linear", xb: xbRaw, yb: ybRaw,
    xRange: xRangePca, yRange: yRangePca,
    // `manualX`/`manualY` here already mean "hand-typed range OR zoom window" (`windowed`).
    xFixed: manualX, yFixed: manualY,
    gridDensity, xFmt, yFmt, xSpacing, ySpacing, warnings,
  });
  const px = (v: number): number => plotX + xb.scale(v);
  const py = (v: number): number => plotY + yb.scale(v);

  const series: SeriesScene[] = [];
  if (showScores && scorePts.length) {
    const dotSize = isBiplot ? 3 : 4.5;
    if (groupList.length) {
      groupList.forEach((g, gi) => {
        const id = `pca-g${gi}`;
        const style = effectiveMarkerStyle(plot, plot.seriesStyles?.[id]);
        const color = style?.color ?? seriesColor(gi, palette);
        const marks: MarkScene[] = scorePts.filter((p) => (groups![p.i] ?? "—") === g).map((p) => ({ rowId: `case-${p.i}`, rowNumber: p.i + 1, dx: p.x, dy: p.y, cx: px(p.x), cy: py(p.y), n: 1, label: g, ...dotSizeOf(p.i) }));
        series.push(markerSeries(id, g, style, color, "circle", dotSize, marks));
      });
    } else {
      const style = effectiveMarkerStyle(plot, plot.seriesStyles?.["pca-scores"]);
      const color = style?.color ?? seriesColor(0, palette);
      const marks: MarkScene[] = scorePts.map((p) => ({ rowId: `case-${p.i}`, rowNumber: p.i + 1, dx: p.x, dy: p.y, cx: px(p.x), cy: py(p.y), n: 1, ...dotSizeOf(p.i) }));
      series.push(markerSeries("pca-scores", "Scores", style, color, "circle", dotSize, marks));
    }
  }
  if (speciesPts.length && !speciesAsArrows) {
    // Their own family, so a click opens their own style row and the legend names them.
    const style = effectiveMarkerStyle(plot, plot.seriesStyles?.["pca-species"]);
    // Not a palette colour. The cases are coloured from the palette by group, so
    // `palette[1]` would put the response variables in the same hue as the second group. The
    // biplot's variable red is the established "this is a variable, not a case" colour here.
    const color = style?.color ?? "#b5342f";
    const marks: MarkScene[] = speciesPts.map((p) => ({ rowId: `species-${p.j}`, rowNumber: p.j + 1, dx: p.x, dy: p.y, cx: px(p.x), cy: py(p.y), n: 1, label: p.label }));
    series.push(markerSeries("pca-species", "Species", style, color, "cross", 4, marks));
  }
  const centroidPts = envPts.filter((p) => p.centroid);
  if (centroidPts.length) {
    // A factor level is a place: its own family, drawn as marks, never as an arrow.
    const style = effectiveMarkerStyle(plot, plot.seriesStyles?.["pca-env"]);
    const color = style?.color ?? "#2f6f4f";
    const marks: MarkScene[] = centroidPts.map((p) => ({ rowId: `env-${p.j}`, rowNumber: p.j + 1, dx: p.x, dy: p.y, cx: px(p.x), cy: py(p.y), n: 1, label: p.label }));
    series.push(markerSeries("pca-env", "Explanatory levels", style, color, "square", 5, marks));
  }
  if (showLoadings && !isBiplot && loadPts.length) {
    // Loadings-only plot: draw the variable points as a selectable series too.
    const style = effectiveMarkerStyle(plot, plot.seriesStyles?.["pca-loadings"]);
    const color = style?.color ?? seriesColor(scorePts.length ? 1 : 0, palette);
    const marks: MarkScene[] = loadPts.map((p, i) => ({ rowId: `var-${i}`, rowNumber: i + 1, dx: p.x, dy: p.y, cx: px(p.x), cy: py(p.y), n: 1, label: p.label }));
    series.push(markerSeries("pca-loadings", "Loadings", style, color, "circle", 4, marks));
  }

  // Per-group confidence/data ellipses on the score cloud: one
  // covariance ellipse per group, colour-matched to its markers. Reuses the shared
  // `buildEllipses` + the kind-agnostic `scene.ellipses` render path. Loading points
  // are excluded (an ellipse around loading arrows is meaningless).
  const scoreSeries = series.filter((s) => s.id === "pca-scores" || s.id.startsWith("pca-g"));
  const ellipses = plot.ellipse?.show ? buildEllipses(plot, scoreSeries) : [];

  const originCross = (): AnnotationScene[] => {
    const out: AnnotationScene[] = [];
    const x0 = px(0);
    const y0 = py(0);
    const v = resolveRefLine(plot, "pca-vzero", { color: "#c8c8cc", dash: "3 3", width: 1 });
    const h = resolveRefLine(plot, "pca-hzero", { color: "#c8c8cc", dash: "3 3", width: 1 });
    if (v.show && x0 >= plotX - 0.5 && x0 <= plotX + plotW + 0.5) out.push({ id: "pca-vzero", kind: "line", x1: x0, x2: x0, y1: plotY, y2: plotY + plotH, color: v.color, dash: v.dash, width: v.width });
    if (h.show && y0 >= plotY - 0.5 && y0 <= plotY + plotH + 0.5) out.push({ id: "pca-hzero", kind: "line", x1: plotX, x2: plotX + plotW, y1: y0, y2: y0, color: h.color, dash: h.dash, width: h.width });
    return out;
  };
  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: (v: number) => px(v), y: (v: number) => py(v), bracketX: (v: number) => px(v) },
    false,
  );
  annotations.unshift(...originCross());
  /**
   * The placement rule: a label may not sit on a data point, an arrow,
   * the legend, the axes, or another label. Only pushing labels apart from each other,
   * vertically, would leave names printed across arrows and beside dots they do not belong to.
   *
   * Everything the builder drew becomes an obstacle, and the plot rect is the boundary — so a
   * label cannot escape onto the axis either. A label the user has dragged (`labelPos`) is
   * never moved: their placement outranks the rule.
   */
  const declutterVariableLabels = (): void => {
    const movable = annotations
      .filter((a) => a.id.startsWith("pca-vlabel-") && !cfg.labelPos?.[a.id.slice("pca-vlabel-".length)])
      // Longest first: the widest label is the hardest to place, so give it first pick.
      .sort((a, b) => (b.label?.length ?? 0) - (a.label?.length ?? 0));
    if (movable.length === 0) return;
    const obstacles: LabelRect[] = [];
    // every drawn mark — the cases, the response points, the factor centroids
    for (const sSeries of series) {
      const r = Math.max(3, sSeries.symbolSize ?? 4) + 1;
      for (const m of sSeries.marks) obstacles.push(discObstacle(m.cx, m.cy, r));
    }
    // every arrow the builder drew (loadings, species-as-arrows, explanatory)
    for (const a of annotations) {
      if (a.kind === "arrow" && a.x1 != null && a.y1 != null && a.x2 != null && a.y2 != null) {
        obstacles.push(...segmentObstacles(a.x1, a.y1, a.x2, a.y2, Math.max(4, (a.width ?? 1) * 2)));
      }
    }
    // The origin cross-hairs are deliberately not obstacles here, unlike a volcano's
    // threshold guides. They are this plot's own zero axes — two faint dotted lines through the
    // middle — and the arrows all start on them, so blocking them would push every variable
    // label away from the one place it belongs: a biplot would warn that it is too crowded,
    // and a triplot label could be forced off the plot entirely.
    // the legend, when it sits inside the plot (an outside one is beyond the bounds already)
    const legendBox = insideLegendBox(leg.layout, leg.entries, plotX, plotY, plotW, plotH, fonts.legend.size, measure);
    if (legendBox) obstacles.push(legendBox);
    // An arrow's label carries the arrow's direction: its name belongs beyond the tip, where the
    // arrow points, not beside the head where it reads as naming whatever is there (e.g. the
    // name of one variable printed on another variable's arrow).
    const arrowOf = new Map<string, AnnotationScene>();
    for (const a of annotations) if (a.kind === "arrow" && a.id.startsWith("pca-arrow-")) arrowOf.set(a.id.slice("pca-arrow-".length), a);
    const placed = placeLabelsClear(
      movable.map((a) => {
        const arrow = arrowOf.get(a.id.slice("pca-vlabel-".length));
        const dir = arrow && arrow.x1 != null && arrow.x2 != null && arrow.y1 != null && arrow.y2 != null
          ? { dx: arrow.x2 - arrow.x1, dy: arrow.y2 - arrow.y1 }
          : undefined;
        return { id: a.id, text: a.label ?? "", anchorX: a.labelX ?? 0, anchorY: a.labelY ?? 0, ...(dir ? { dir } : {}) };
      }),
      { fontPx: fonts.legend.size, measure, bounds: { x1: plotX, y1: plotY, x2: plotX + plotW, y2: plotY + plotH }, obstacles },
    );
    let crowded = 0;
    /** Where each label's subject is — the point or arrow tip it names, for its leader. */
    const subjectOf = new Map<string, { x: number; y: number; r: number }>();
    for (const p of speciesPts) subjectOf.set(`pca-vlabel-s${p.j}`, { x: px(p.x), y: py(p.y), r: 5 });
    for (const p of envPts) subjectOf.set(`pca-vlabel-e${p.j}`, { x: px(p.x), y: py(p.y), r: p.centroid ? 6 : 2 });
    loadPts.forEach((p, i) => subjectOf.set(`pca-vlabel-${i}`, { x: px(p.x), y: py(p.y), r: 2 }));
    const leaders: AnnotationScene[] = [];
    for (const a of annotations) {
      const p = placed.get(a.id);
      if (!p) continue;
      a.labelX = p.x;
      a.labelY = p.y;
      a.labelAnchor = p.anchor;
      if (p.crowded) crowded++;
      // A leader when the label had to move far from what it names. Locked and undeletable, the
      // same contract the loading arrows carry: it is geometry, not an annotation the user made.
      const subj = subjectOf.get(a.id);
      if (!subj) continue;
      const lead = leaderFor(subj.x, subj.y, placedBox(p, a.label ?? "", fonts.legend.size, measure), subj.r, subj.r + fonts.legend.size * 2);
      if (lead) {
        leaders.push({
          // Not `pca-vlabel-…`: anything reading the label family by id prefix would count
          // the leader as a label, and guards would measure a line as if it were text.
          id: a.id.replace("pca-vlabel-", "pca-leader-"), kind: "segment", x1: lead.x1, y1: lead.y1, x2: lead.x2, y2: lead.y2,
          // Not the label's colour, and not solid: in the arrow's own green a leader from an
          // arrow tip to its name would read as a second arrow, making it unclear which arrow a
          // name belongs to. A hairline of neutral grey, dashed, reads as a leader.
          color: "#8b8f96", dash: "2 3", width: 0.7, locked: true, deletable: false,
        } as AnnotationScene);
      }
    }
    annotations.push(...leaders);
    // Say it rather than let a reader wonder: a forced placement is the one case where a
    // label can still touch something, and the user can move it themselves.
    if (crowded > 0) {
      warnings.push(`${crowded} label${crowded === 1 ? "" : "s"} could not be placed clear of the marks — the graph is crowded at this size. Widen the figure, or drag the label${crowded === 1 ? "" : "s"} where you want ${crowded === 1 ? "it" : "them"}.`);
    }
  };
  /**
   * Species labels. Same machinery as the loading labels — the same `labelPos` drag store and
   * the same `varLabelText` rename store — under keys prefixed "s", which no loading can
   * produce. One store, two families, no collision: `document.ts` reads `pca-vlabel-(s?\d+)`.
   * No arrow: a species point is a place, not a direction.
   */
  if (speciesPts.length) {
    const spColor = plot.seriesStyles?.["pca-species"]?.color ?? "#b5342f";
    speciesPts.forEach((p) => {
      const key = `s${p.j}`;
      const vpos = cfg.labelPos?.[key];
      const text = cfg.varLabelText?.[key] ?? p.label;
      const color = cfg.varLabelColors?.[key] ?? spColor;
      annotations.push({
        id: `pca-vlabel-${key}`, kind: "text", deletable: false, label: text,
        labelX: vpos ? plotX + vpos.x * plotW : px(p.x) + 4,
        labelY: vpos ? plotY + vpos.y * plotH : py(p.y) - 4,
        labelAnchor: "start", color, dash: null, width: 0, fontSize: fonts.legend.size,
        ...(fonts.legend.family ? { fontFamily: fonts.legend.family } : {}),
        ...(fonts.legend.weight >= 600 ? { bold: true } : {}),
        ...(fonts.legend.italic ? { italic: true } : {}),
      });
    });
  }
  if (speciesAsArrows && speciesPts.length) {
    const aw = Math.max(0.25, Math.min(8, cfg.arrowWidth ?? 1.4));
    const shared = plot.seriesStyles?.["pca-species"]?.color ?? "#b5342f";
    for (const p of speciesPts) {
      const key = `s${p.j}`;
      const color = cfg.arrowColors?.[key] ?? shared;
      annotations.push({ id: `pca-arrow-${key}`, kind: "arrow", x1: px(0), y1: py(0), x2: px(p.x), y2: py(p.y), color, dash: dashArray(cfg.arrowDash ?? "solid", aw), width: aw, arrowHead: cfg.arrowHead === false ? "none" : "end", locked: true, deletable: false });
    }
  }
  /**
   * Explanatory arrows (triplot). The same drawable as a loading arrow — arrow annotation +
   * text label, locked so its geometry can never be dragged away from the data — under "e"
   * keys in the same per-arrow colour / rename / drag stores, which no loading or species key
   * can collide with. Factor levels are excluded: they were drawn as centroids above.
   */
  if (envPts.length) {
    const aw = Math.max(0.25, Math.min(8, cfg.arrowWidth ?? 1.4));
    for (const p of envPts) {
      if (p.centroid) continue;
      const key = `e${p.j}`;
      const arrowColor = cfg.arrowColors?.[key] ?? "#2f6f4f";
      const labelColor = cfg.varLabelColors?.[key] ?? arrowColor;
      annotations.push({ id: `pca-arrow-${key}`, kind: "arrow", x1: px(0), y1: py(0), x2: px(p.x), y2: py(p.y), color: arrowColor, dash: dashArray(cfg.arrowDash ?? "solid", aw), width: aw, arrowHead: cfg.arrowHead === false ? "none" : "end", locked: true, deletable: false });
      const vpos = cfg.labelPos?.[key];
      const text = cfg.varLabelText?.[key] ?? p.label;
      const anchor: "start" | "end" = p.x >= 0 ? "start" : "end";
      annotations.push({
        id: `pca-vlabel-${key}`, kind: "text", deletable: false, label: text,
        labelX: vpos ? plotX + vpos.x * plotW : px(p.x) + (anchor === "start" ? 3 : -3),
        labelY: vpos ? plotY + vpos.y * plotH : py(p.y) - 3,
        labelAnchor: anchor, color: labelColor, dash: null, width: 0, fontSize: fonts.legend.size,
        ...(fonts.legend.family ? { fontFamily: fonts.legend.family } : {}),
        ...(fonts.legend.weight >= 600 ? { bold: true } : {}),
        ...(fonts.legend.italic ? { italic: true } : {}),
      });
    }
    // the centroid labels ride the same store, without an arrow
    for (const p of envPts) {
      if (!p.centroid) continue;
      const key = `e${p.j}`;
      const vpos = cfg.labelPos?.[key];
      annotations.push({
        id: `pca-vlabel-${key}`, kind: "text", deletable: false,
        label: cfg.varLabelText?.[key] ?? p.label,
        labelX: vpos ? plotX + vpos.x * plotW : px(p.x) + 5,
        labelY: vpos ? plotY + vpos.y * plotH : py(p.y) - 4,
        labelAnchor: "start", color: cfg.varLabelColors?.[key] ?? plot.seriesStyles?.["pca-env"]?.color ?? "#2f6f4f",
        dash: null, width: 0, fontSize: fonts.legend.size,
        ...(fonts.legend.family ? { fontFamily: fonts.legend.family } : {}),
      });
    }
  }
  // Loading arrows (from the origin) + variable labels — the loadings/biplot vectors.
  if (showLoadings) {
    // Loading arrow + label colour: honour a seriesStyles["pca-loadings"].color override for
    // both pcaload and biplot (a fixed #b5342f on the biplot would be reachable by no control);
    // #b5342f stays the biplot default. The variable labels also carry
    // the legend font family/weight/italic so a font control changes their typeface.
    const sharedColor = plot.seriesStyles?.["pca-loadings"]?.color ?? (isBiplot ? "#b5342f" : seriesColor(scorePts.length ? 1 : 0, palette));
    loadPts.forEach((p, i) => {
      // A per-vector colour override (click one arrow → pick a colour) wins over the shared
      // "Loadings colour"; it paints the arrow and its variable label, which are one unit.
      const arrowColor = cfg.arrowColors?.[String(i)] ?? sharedColor;
      // The label falls back to the arrow's colour, so by default the pair reads as one
      // unit — but `varLabelColors` can separate them, so an arrow and its name can have
      // different colours.
      const labelColor = cfg.varLabelColors?.[String(i)] ?? arrowColor;
      // `locked`: an arrow's position is the loading vector (data) — it must never be
      // draggable, so the renderer offers no move/resize/delete affordance for it.
      const aw = Math.max(0.25, Math.min(8, cfg.arrowWidth ?? 1.4));
      annotations.push({ id: `pca-arrow-${i}`, kind: "arrow", x1: px(0), y1: py(0), x2: px(p.x), y2: py(p.y), color: arrowColor, dash: dashArray(cfg.arrowDash ?? "solid", aw), width: aw, arrowHead: cfg.arrowHead === false ? "none" : "end", locked: true, deletable: false });
      // Honour a per-label drag override (fractional plot-rect coords) if the user has
      // repositioned this loading label; otherwise sit next to the arrow tip.
      const vpos = cfg.labelPos?.[String(i)];
      // A renamed loading label (presentation override) wins over the analysis varLabel.
      const vText = cfg.varLabelText?.[String(i)] ?? p.label;
      // Loading arrows terminate at the domain edge by construction, so a label hung off the
      // tip pointing outward can run into the margin and off the canvas. When it would
      // overflow, hang the label on the inside of the tip instead — it stays attached to its arrow and stays readable. A
      // user-dragged label (`vpos`) is left exactly where they put it.
      const vw = measure(vText, fonts.legend.size);
      const outward: "start" | "end" = p.x >= 0 ? "start" : "end";
      const tipX = px(p.x);
      const overflows = outward === "start" ? tipX + 3 + vw > width - 2 : tipX - 3 - vw < 2;
      const anchor: "start" | "end" = vpos || !overflows ? outward : outward === "start" ? "end" : "start";
      const labelX = vpos ? plotX + vpos.x * plotW : tipX + (anchor === "start" ? 3 : -3);
      annotations.push({ id: `pca-vlabel-${i}`, kind: "text", deletable: false, label: vText, labelX, labelY: vpos ? plotY + vpos.y * plotH : py(p.y) - 3, labelAnchor: anchor, color: labelColor, dash: null, width: 0, fontSize: fonts.legend.size, ...(fonts.legend.family ? { fontFamily: fonts.legend.family } : {}), ...(fonts.legend.weight >= 600 ? { bold: true } : {}), ...(fonts.legend.italic ? { italic: true } : {}) });
    });
    // Two near-parallel loadings put their arrow tips in nearly the same place, so their labels
    // land on each other. Nudge them apart vertically rather than hiding one — each names a
    // variable, and the eye follows the arrow to its label, so a line's offset stays
    // unambiguous. Labels the user has dragged (`labelPos`) are left exactly where they put them.
    declutterVariableLabels();
  }
  // Species points crowd each other exactly the way loading tips do, so they get the same
  // treatment — and it has to run whether or not this plot has loadings at all.
  if (speciesPts.length || envPts.length) declutterVariableLabels();

  const xAxis: AxisScene = {
    type: "linear", domain: xRev ? [xb.domain[1], xb.domain[0]] : xb.domain, range: [plotX, plotX + plotW],
    ticks: deOverlapX(xb.ticks.map((t) => ({ ...t, pos: plotX + t.pos })), measure, fonts.tick.size), title: xLabel, ...axisLine(xSpec),
  };
  const yAxis: AxisScene = {
    type: "linear", domain: yRev ? [yb.domain[1], yb.domain[0]] : yb.domain, range: [plotY + plotH, plotY],
    ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yLabel, ...axisLine(ySpec),
  };

  // Depth-size legend: what a big dot means. Reuses the bubble chart's legend block
  // (same scene field, same renderer, same editor), its spheres painted like the score
  // dots — the first score series, since every group shares one size scale.
  const ss = scoreSeries[0];
  const sizeLegend = sizeLegendFits
    ? {
        title: sizeLegendTitle,
        marker: {
          // Its shape too. A depth-sized score plot keeps round dots under a shape cycle (the
          // key is round), so this reads "circle" there; the field is
          // carried so the key can never disagree with the marks it keys.
          symbol: ss?.symbol ?? "circle",
          color: ss?.color ?? seriesColor(0, palette),
          symbolFill: ss?.symbolFill ?? "solid",
          symbolFillColor: ss?.symbolFillColor,
          symbolOutline: ss?.symbolOutline ?? ss?.color ?? seriesColor(0, palette),
          symbolOpacity: ss?.symbolOpacity ?? 1,
          borderWidth: ss?.borderWidth ?? 1.5,
        },
        ...(plot.colorbarOffset ? { offset: plot.colorbarOffset } : {}),
        items: sizeRefItems,
      }
    : undefined;

  return {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: xAxis, y: yAxis,
    auto: {
      x: options.xDomain != null ? buildScale("linear", wx.home, [0, 1], gridDensity, wx.homeManual, xFmt, xSpacing).domain : xb.domain,
      y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain,
    },
    // Both axes are principal components — continuous, and both windows are honoured above.
    zoomable: [{ visual: "x", key: "x" }, { visual: "y", key: "y" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    ...(sizeLegend ? { bubbleLegend: sizeLegend } : {}),
    ...(ellipses.length ? { ellipses } : {}),
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: xLabel, y: yLabel }, kind, fonts, warnings,
  };
}

/**
 * Scree plot: variance retained per principal component — a line + markers of
 * the eigenvalue (or % variance) against the component number, the classic "elbow"
 * for choosing how many PCs to keep, with an optional cumulative-variance overlay.
 * Reads `plot.pca`. Renders through the default line/marker path.
 */
function buildScreeScene(_table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const pca = plot.pca;
  const cfg = plot.pcaStyle ?? {};
  const ncomp = pca?.pcLabels?.length ?? 0;
  if (!pca || ncomp === 0) warnings.push("No PCA data to plot.");
  const metric = cfg.screeMetric ?? "percent";
  const vals = (metric === "eigenvalue" ? (pca?.eigenvalues ?? []) : (pca?.explained ?? []).map((v) => v * 100)).slice(0, ncomp);
  const cumulative = cfg.screeCumulative ?? false;
  let run = 0;
  const cum = vals.map((v) => (run += v));

  const xSpec: AxisSpec = plot.xAxis ?? {};
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const xFmt = tickFormat(xSpec);
  const yFmt = tickFormat(ySpec);
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yRev = ySpec.reversed ?? false;
  const yTop = Math.max(0, ...(cumulative ? cum : vals));
  const wy = windowed(ySpec, buildScale("linear", [0, yTop || 1], [0, 1], gridDensity, false, yFmt).domain, options.yDomain);
  const yData = wy.data;
  const manualY = wy.manual;
  const xData: [number, number] = [0.5, Math.max(1.5, ncomp + 0.5)];

  const yProbe = buildScale("linear", yData, [0, 1], gridDensity, manualY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.tick.size, measure, plot.yAxis);
  const yLabel = ySpec.title ?? (metric === "eigenvalue" ? "Eigenvalue" : "% variance explained");
  const xLabel = xSpec.title ?? "Component";

  const rawLegend: LegendEntry[] = cumulative
    ? [{ label: metric === "eigenvalue" ? "Eigenvalue" : "% variance", color: seriesColor(0, palette), select: { as: "series" as const, id: "scree" } }, { label: "Cumulative", color: seriesColor(1, palette), select: { as: "series" as const, id: "scree-cum" } }]
    : [];
  const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  const marginLeft = ySpec.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (ySpec.tickLabelGap ?? 8) + (textBand(fonts.yAxisTitle.size, ySpec.titleGap ?? 6)) + pad.l;
  const marginBottom = xSpec.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.tick.size + (xSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, xSpec.titleGap ?? 6)) + pad.b;
  const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const xb = buildScale("linear", xData, [0, plotW], gridDensity, true, xFmt);
  const yb = buildScale("linear", yData, yRev ? [0, plotH] : [plotH, 0], gridDensity, manualY, yFmt, ySpacing);
  const px = (v: number): number => plotX + xb.scale(v);
  const py = (v: number): number => plotY + yb.scale(v);

  const mkLine = (id: string, name: string, color: string, ys: number[], dash: string | null): SeriesScene => {
    const marks: MarkScene[] = ys.map((v, k) => ({ rowId: `${id}-${k}`, rowNumber: k + 1, dx: k + 1, dy: v, cx: px(k + 1), cy: py(v), n: 1, label: pca?.pcLabels?.[k] ?? `PC${k + 1}` }));
    const style = effectiveMarkerStyle(plot, plot.seriesStyles?.[id]);
    const c = style?.color ?? color;
    const lw = style?.lineWidth ?? 2;
    const connect = style?.connect ?? "straight";
    const linePath = connect === "none" ? "" : d3line<MarkScene>().x((m) => m.cx).y((m) => m.cy).curve(curveFor(connect, style?.lineTension ?? 0.5))(marks) ?? "";
    return {
      id, name, color: c,
      // Linked (default) → line follows the series colour; unlinked → its own.
      lineColor: style?.linkLineColor === false ? (style?.lineColor ?? c) : c,
      linePath, symbol: style?.symbol ?? "circle", symbolSize: style?.symbolSize ?? 4.5,
      ...resolveSymbol(style, c), borderWidth: style?.borderWidth ?? 1.5, lineWidth: lw,
      dash: style?.lineDash ? dashArray(style.lineDash, lw) : dash,
      errorCaps: false, errorDir: "both", ...seriesExtras(style, c, lw, 4.5, 1), marks,
    };
  };
  const series: SeriesScene[] = [mkLine("scree", metric === "eigenvalue" ? "Eigenvalue" : "% variance", seriesColor(0, palette), vals, null)];
  if (cumulative) series.push(mkLine("scree-cum", "Cumulative", seriesColor(1, palette), cum, dashArray("dashed", 2)));

  const xticks: AxisTick[] = vals.map((_v, k) => ({ value: k + 1, pos: px(k + 1), label: pca?.pcLabels?.[k] ?? `PC${k + 1}`, minor: false }));
  const annotations = buildAnnotations(
    plot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: (v: number) => px(v), y: (v: number) => py(v), bracketX: (v: number) => px(v) },
    false,
  );

  return {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: { type: "linear", domain: xb.domain, range: [plotX, plotX + plotW], ticks: deOverlapX(xticks, measure, fonts.tick.size), title: xLabel, ...axisLine(xSpec) },
    y: { type: "linear", domain: yRev ? [yb.domain[1], yb.domain[0]] : yb.domain, range: [plotY + plotH, plotY], ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yLabel, ...axisLine(ySpec) },
    auto: {
      x: xb.domain,
      y: options.yDomain != null ? buildScale("linear", wy.home, [0, 1], gridDensity, wy.homeManual, yFmt, ySpacing).domain : yb.domain,
    },
    // X only — the X axis counts components (1, 2, 3 …). Windowing it would show half a
    // component, which is not a view of anything.
    zoomable: [{ visual: "y", key: "y" }],
    series, legend: leg.entries, legendLayout: leg.layout, annotations,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: xLabel, y: yLabel }, kind: "scree", fonts, warnings,
  };
}

/** All ⊓ merge brackets of a hierarchical tree as one SVG path (pixel space). `heightPx`
 *  maps a merge distance to the value axis, `leafPx` a leaf-slot coordinate to the leaf
 *  axis. `nodeIds` restricts to a subset (colouring a cut cluster). Shared by the
 *  standalone dendrogram kind and the clustered heatmap's attached trees. */
function dendroBrackets(
  result: HClustResult,
  coords: number[],
  leafPx: (coord: number) => number,
  heightPx: (h: number) => number,
  horizontal: boolean,
  nodeIds: Iterable<number>,
): string {
  let d = "";
  for (const id of nodeIds) {
    const node = result.nodes[id]!;
    if (node.left === null) continue;
    const hy = heightPx(node.height);
    const lc = leafPx(coords[node.left]!);
    const rc = leafPx(coords[node.right!]!);
    const lh = heightPx(result.nodes[node.left]!.height);
    const rh = heightPx(result.nodes[node.right!]!.height);
    const f = (v: number): string => v.toFixed(2);
    d += horizontal
      ? `M${f(lh)},${f(lc)} L${f(hy)},${f(lc)} L${f(hy)},${f(rc)} L${f(rh)},${f(rc)} `
      : `M${f(lc)},${f(lh)} L${f(lc)},${f(hy)} L${f(rc)},${f(hy)} L${f(rc)},${f(rh)} `;
  }
  return d;
}

/**
 * Dendrogram: a hierarchical-clustering merge tree of the table's rows (each a
 * profile across the value columns) or columns. Leaves sit along the category axis with
 * their labels; merges draw as ⊓ brackets at their distance on the value axis. Optional
 * cut-cluster colouring. Renders through the default line path (a tree = one linePath).
 */
function buildDendrogramScene(table: DataTable, plot: Plot, options: BuildPlotSceneOptions): PlotScene {
  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  warnLogUnsupported(plot, "a dendrogram", warnings);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const heading = resolveHeading(plot);
  const gridDensity = plot.grid?.density ?? 6;

  const cfg = plot.dendrogram ?? {};
  const target = cfg.target ?? "rows";
  const metric: ClusterMetric = cfg.metric ?? "euclidean";
  const linkage: ClusterLinkage = cfg.linkage ?? "average";
  // Ward is only valid on Euclidean geometry; `hclust` forces it, so tell the user their
  // chosen metric was overridden rather than silently drawing a different tree than the menu says.
  if (linkage === "ward" && metric !== "euclidean")
    warnings.push("Ward linkage requires Euclidean distance — clustered on Euclidean, not the selected metric.");
  const horizontal = (cfg.orientation ?? "vertical") === "horizontal";

  const datasets = visibleDatasets(table, plot);
  const xCol = xColumn(table);
  const rows = table.rows;
  let data: number[][];
  let leafLabels: string[];
  if (target === "columns") {
    data = datasets.map((ds) => rows.map((r) => toNumber(r.cells[ds.id])));
    leafLabels = datasets.map((ds) => ds.name);
  } else {
    data = rows.map((r) => datasets.map((ds) => toNumber(r.cells[ds.id])));
    leafLabels = rows.map((r, i) => (xCol ? String(r.cells[xCol.id] ?? i + 1) : String(i + 1)));
  }
  const nLeaves = data.length;
  if (nLeaves < 2) warnings.push(`Dendrogram needs at least two ${target}.`);
  const result = hclust(data, metric, linkage);
  const coords = dendrogramCoords(result);
  const maxH = Math.max(1e-9, ...result.nodes.map((n) => n.height));

  const valSpec: AxisSpec = (horizontal ? plot.xAxis : plot.yAxis) ?? {};
  const catSpec: AxisSpec = (horizontal ? plot.yAxis : plot.xAxis) ?? {};
  const vFmt = tickFormat(valSpec);
  const vSpacing: TickSpacing = { majorStep: valSpec.majorStep, minorCount: valSpec.minorCount, breaks: valSpec.breaks };
  const vRev = valSpec.reversed ?? false;
  // Note: like the lollipop, the value spec follows the orientation, so the window key does too.
  // The other axis lists leaves — windowing it would show half a specimen.
  const wd = windowed(valSpec, buildScale("linear", [0, maxH * 1.02], [0, 1], gridDensity, false, vFmt).domain, horizontal ? options.xDomain : options.yDomain);
  const vData = wd.data;
  const manualV = wd.manual;
  const valTitle = valSpec.title ?? "Distance";
  const catTitle = catSpec.title ?? "";

  const leafLabelMax = Math.max(0, ...leafLabels.map((t) => measure(t, fonts.tick.size)));
  const vProbe = buildScale("linear", vData, [0, 1], gridDensity, manualV, vFmt, vSpacing);
  // The shared width rule, not a copy of it: custom tick labels get their room here too, and a turned
  // label its real reach. Never less than the flat label width.
  const vLabelW = yTickLabelsWidth(vProbe.ticks, fonts.tick.size, measure, valSpec);

  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
  let marginLeft: number;
  let marginBottom: number;
  // The leaf (category) axis reserves room for its own title too — otherwise an enlarged x/y-axis
  // title (e.g. "Gene") collides with the leaf labels. The value axis does the same.
  const catTitleBand = (size: number): number => (catTitle ? textBand(size, catSpec.titleGap ?? 6) : 0);
  if (horizontal) {
    marginLeft = catSpec.hidden
      ? pad.l + HIDDEN_AXIS_MARGIN
      : leafLabelMax + DEFAULTS.tickLen + (catSpec.tickLabelGap ?? 8) + 4 + catTitleBand(fonts.yAxisTitle.size) + pad.l;
    marginBottom = valSpec.hidden
      ? pad.b + HIDDEN_AXIS_MARGIN
      : fonts.tick.size + (valSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + textBand(fonts.xAxisTitle.size, valSpec.titleGap ?? 6) + pad.b;
  } else {
    marginLeft = valSpec.hidden
      ? pad.l + HIDDEN_AXIS_MARGIN
      : vLabelW + DEFAULTS.tickLen + (valSpec.tickLabelGap ?? 8) + textBand(fonts.yAxisTitle.size, valSpec.titleGap ?? 6) + pad.l;
    marginBottom = catSpec.hidden
      ? pad.b + HIDDEN_AXIS_MARGIN
      : fonts.tick.size + (catSpec.tickLabelGap ?? 6) + DEFAULTS.tickLen + 4 + catTitleBand(fonts.xAxisTitle.size) + pad.b;
  }
  const marginRight = DEFAULTS.marginRight + pad.r;
  const plotX = marginLeft;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const vb = horizontal
    ? buildScale("linear", vData, vRev ? [plotW, 0] : [0, plotW], gridDensity, manualV, vFmt, vSpacing)
    : buildScale("linear", vData, vRev ? [0, plotH] : [plotH, 0], gridDensity, manualV, vFmt, vSpacing);
  const heightPx = (h: number): number => (horizontal ? plotX : plotY) + vb.scale(h);
  const leafSpan = horizontal ? plotH : plotW;
  const leafBase = horizontal ? plotY : plotX;
  const leafPx = (coord: number): number => leafBase + ((coord + 0.5) / Math.max(1, nLeaves)) * leafSpan;

  const mkTree = (id: string, name: string, fallback: string, path: string): SeriesScene => {
    const style = plot.seriesStyles?.[id];
    const color = style?.color ?? fallback;
    const lw = style?.lineWidth ?? 1.5;
    return {
      id, name, color, linePath: path, symbol: "circle", symbolSize: 0,
      ...resolveSymbol(style, color), borderWidth: style?.borderWidth ?? 1.5, lineWidth: lw,
      dash: dashArray(style?.lineDash ?? "solid", lw), errorCaps: false, errorDir: "both",
      ...seriesExtras(style, color, lw, 0, 1), marks: [],
    };
  };
  const internalIds = result.nodes.filter((n) => n.left !== null).map((n) => n.id);
  const k = Math.max(0, Math.floor(cfg.colorClusters ?? 0));
  const series: SeriesScene[] = [];
  if (k >= 2 && k <= nLeaves) {
    const nodeColor = new Map<number, string>();
    cutClusters(result, k).forEach((rid, ci) => {
      for (const id of subtreeNodes(result, rid)) nodeColor.set(id, seriesColor(ci, palette));
    });
    const byColor = new Map<string, number[]>();
    const trunk = "#8a8f98";
    for (const id of internalIds) {
      const c = nodeColor.get(id) ?? trunk;
      let arr = byColor.get(c);
      if (!arr) { arr = []; byColor.set(c, arr); }
      arr.push(id);
    }
    let si = 0;
    for (const [c, ids] of byColor) series.push(mkTree(`dendro-${si++}`, "Cluster", c, dendroBrackets(result, coords, leafPx, heightPx, horizontal, ids)));
  } else {
    series.push(mkTree("dendro", "Tree", seriesColor(0, palette), dendroBrackets(result, coords, leafPx, heightPx, horizontal, internalIds)));
  }

  const leafTicks: AxisTick[] = result.order.map((leaf, i) => ({ value: i, pos: leafPx(coords[leaf]!), label: leafLabels[leaf] ?? String(leaf + 1), minor: false }));
  // Leaves stacked along Y shrink to their band, then thin (as on the paired dot chart), so dense
  // leaves (48 names, say) do not run into each other.
  const leafFit = horizontal ? fitStackedLabels(nLeaves, plotH / Math.max(1, nLeaves), fonts.yTick.size) : { font: fonts.yTick.size, keep: null as Set<number> | null };
  const leafTicksFit: AxisTick[] = leafFit.keep ? leafTicks.map((t, i) => (leafFit.keep!.has(i) ? t : { ...t, label: "", suppressedLabel: t.label })) : leafTicks;
  if (horizontal && (plot.yAxis?.tickFont?.size ?? plot.xAxis?.tickFont?.size) !== undefined && leafFit.font < fonts.yTick.size) {
    warnings.push(`Leaf labels are drawn at ${leafFit.font}px, not the ${fonts.yTick.size}px asked for: ${nLeaves} leaves leave no room. A taller figure will honour it.`);
  }
  const valTicks: AxisTick[] = vb.ticks.map((t) => ({ ...t, pos: (horizontal ? plotX : plotY) + t.pos }));
  const leafAxis: AxisScene = {
    type: "linear", band: true, domain: [-0.5, Math.max(0.5, nLeaves - 0.5)],
    range: horizontal ? [plotY + plotH, plotY] : [plotX, plotX + plotW],
    ticks: horizontal ? leafTicksFit : deOverlapX(leafTicks, measure, fonts.tick.size),
    title: catTitle, ...axisLine(catSpec),
  };
  const valAxis: AxisScene = {
    type: "linear", domain: vRev ? [vb.domain[1], vb.domain[0]] : vb.domain,
    range: horizontal ? [plotX, plotX + plotW] : [plotY + plotH, plotY],
    ticks: valTicks, title: valTitle, ...axisLine(valSpec),
  };
  /**
   * All three maps are real scales, not a pixel offset (`plot* + v`).
   *
   * A significance bracket's endpoints are 1-based category indices (the composer writes
   * `{from:1,to:2}`), so as on every other categorical builder `bracketX` resolves index → band
   * centre. Adding the raw number to the plot's left edge would collapse a bracket over the
   * first two leaves into a stub about a pixel wide near the edge, pointing at no leaf.
   *
   * `heightPx` is the distance-axis scale, so a bracket's height (and a reference line)
   * resolves through the same scale the tree itself is drawn with. And `transposed` follows the
   * builder's own `horizontal` flag — the category axis is Y on a horizontal dendrogram, which
   * a hard-coded `false` would get wrong.
   *
   * `warnings` is passed too, so a dropped annotation here is reported.
   */
  const leafToPx = (c: number): number | undefined =>
    c >= 1 && c <= leafTicks.length ? leafTicks[c - 1]!.pos : undefined;
  const valAnn = (v: number): number | undefined => (Number.isFinite(v) ? heightPx(v) : undefined);
  const annotations = buildAnnotations(
    plot, { x: plotX, y: plotY, width: plotW, height: plotH },
    horizontal
      ? { x: valAnn, y: valAnn, bracketX: leafToPx }
      : { x: null, y: valAnn, bracketX: leafToPx },
    horizontal,
    warnings,
  );

  return {
    width, height, plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    x: horizontal ? valAxis : leafAxis,
    y: horizontal ? leafAxis : valAxis,
    auto: (() => {
      const hv = (horizontal ? options.xDomain : options.yDomain) != null
        ? buildScale("linear", wd.home, [0, 1], gridDensity, wd.homeManual, vFmt, vSpacing).domain
        : vb.domain;
      const leaves: [number, number] = [-0.5, nLeaves - 0.5];
      return { x: horizontal ? hv : leaves, y: horizontal ? leaves : hv };
    })(),
    zoomable: [horizontal ? { visual: "x" as const, key: "x" as const } : { visual: "y" as const, key: "y" as const }],
    series, legend: [], legendLayout: NO_LEGEND, annotations,
    grid: { show: plot.grid?.show ?? false, color: plot.grid?.color ?? null, width: plot.grid?.width ?? 1, dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1), minor: plot.grid?.minor ?? false } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title, subtitle: heading.subtitle, axisLabels: { x: horizontal ? valTitle : catTitle, y: horizontal ? catTitle : valTitle }, kind: "dendrogram", fonts: leafFit.font < fonts.yTick.size ? { ...fonts, yTick: { ...fonts.yTick, size: leafFit.font } } : fonts, warnings,
  };
}

/** One outer cluster of a three-way grouped bar: its label + the x-span (within a band's
 *  inner width) its bars occupy, for drawing the group label centred under the cluster. */
export interface BarClusterSpan {
  label: string;
  x0: number;
  x1: number;
}
/** Result of laying out a three-way grouped bar's outer dataset-grouping within one band. */
export interface BarGroupingLayout {
  /** Per-dataset (by original index) x offset within the band's inner width [0, innerW]. */
  slotOffset: number[];
  /** Each bar's size along the category axis (shrunk to make room for inter-cluster gaps). */
  barSize: number;
  /** The clusters, in draw order, with their spans (for the group labels). */
  clusters: BarClusterSpan[];
}

/**
 * Three-way grouped bar geometry: given the datasets, an outer
 * dataset→group map, and the band's inner width, cluster the bars by group with a gap
 * between clusters. Returns `null` — so the caller keeps the ordinary even side-by-side
 * split, byte-identical — unless there is a real grouping: every dataset assigned, at least
 * 2 distinct groups, and fewer groups than datasets. Pure + exported for the geometry test.
 *
 * `gapFrac` is the share of the band's inner width spent on the (g − 1) inter-cluster gaps.
 */
export function barSeriesGroupLayout(
  datasets: ReadonlyArray<{ id: NodeId }>,
  groupMap: Record<NodeId, string> | undefined,
  innerW: number,
  gapFrac = 0.18,
): BarGroupingLayout | null {
  if (!groupMap) return null;
  const m = datasets.length;
  const labels = datasets.map((ds) => groupMap[ds.id]);
  if (m < 2 || labels.some((l) => l == null || l === "")) return null; // every series must be assigned
  const order: string[] = [];
  for (const l of labels) if (!order.includes(l!)) order.push(l!);
  const g = order.length;
  if (g < 2 || g >= m) return null; // need ≥2 clusters, each with ≥1 member (a real second factor)
  const totalGap = innerW * Math.min(0.5, Math.max(0, gapFrac));
  const gapW = totalGap / (g - 1);
  const barSize = (innerW - totalGap) / m;
  // Draw order: cluster by group (group members adjacent), groups in first-appearance order,
  // members in their original dataset order.
  const drawOrder = datasets.map((_, di) => di).sort((a, b) => (order.indexOf(labels[a]!) - order.indexOf(labels[b]!)) || (a - b));
  const slotOffset = new Array<number>(m).fill(0);
  const clusters: BarClusterSpan[] = order.map((label) => ({ label, x0: Infinity, x1: -Infinity }));
  drawOrder.forEach((di, s) => {
    const gi = order.indexOf(labels[di]!);
    const x = s * barSize + gi * gapW;
    slotOffset[di] = x;
    clusters[gi]!.x0 = Math.min(clusters[gi]!.x0, x);
    clusters[gi]!.x1 = Math.max(clusters[gi]!.x1, x + barSize);
  });
  return { slotOffset, barSize, clusters };
}

/**
 * Build a categorical (band-axis) bar chart. Categories are the table's rows (labelled by the X
 * cell); each dataset is a series of marks across the categories. Bars anchor at
 * the y=0 baseline; grouped = interleaved sub-bars per dataset, stacked = summed.
 * Reuses the dataset/replicate/error machinery (mean ± SD/SEM/CI…).
 */
function buildCategoricalScene(
  table: DataTable,
  plot: Plot,
  options: BuildPlotSceneOptions,
): PlotScene {
  const kind = plot.kind ?? "bar";
  if (kind === "histogram") return buildHistogramScene(table, plot, options);
  // Distribution charts (box/violin/scatter) summarise a dataset's pooled values
  // as one mark per dataset — a different category mapping than bars.
  if (kind === "box" || kind === "violin" || kind === "scatter" || kind === "raincloud" || kind === "floatingbar") {
    return buildDistributionScene(table, plot, options, kind);
  }
  if (kind === "beforeafter") return buildBeforeAfterScene(table, plot, options);
  if (kind === "estimation") return buildEstimationScene(table, plot, options);
  if (kind === "pie") return buildPieScene(table, plot, options);
  if (kind === "heatmap") return buildHeatmapScene(table, plot, options);
  if (kind === "corrmatrix") return buildCorrMatrixScene(table, plot, options);
  if (kind === "alluvial") return buildAlluvialScene(table, plot, options);
  if (kind === "network") return buildNetworkScene(table, plot, options);
  if (kind === "treemap") return buildTreemapScene(table, plot, options);
  if (kind === "sunburst") return buildSunburstScene(table, plot, options);
  if (kind === "chord") return buildChordScene(table, plot, options);
  if (kind === "oncoprint") return buildOncoprintScene(table, plot, options);
  if (kind === "radar") return buildRadarScene(table, plot, options);
  if (kind === "parallel") return buildParallelScene(table, plot, options);
  if (kind === "scatter3d") return buildScatter3DScene(table, plot, options);
  if (kind === "ridgeline") return buildRidgelineScene(table, plot, options);
  if (kind === "lollipop") return buildLollipopScene(table, plot, options);
  if (kind === "paireddot") return buildPairedDotScene(table, plot, options);
  if (kind === "forest") return buildForestScene(table, plot, options);
  if (kind === "funnel") return buildFunnelScene(table, plot, options);
  if (kind === "ternary") return buildTernaryScene(table, plot, options);
  if (kind === "rose") return buildRoseScene(table, plot, options);
  if (kind === "tracks") return buildTracksScene(table, plot, options);
  if (kind === "venn") return buildVennScene(table, plot, options);
  if (kind === "upset") return buildUpsetScene(table, plot, options);
  if (kind === "swimmer") return buildSwimmerScene(table, plot, options);
  if (kind === "blandaltman") return buildBlandAltmanScene(table, plot, options);
  if (kind === "pyramid") return buildPyramidScene(table, plot, options);
  if (kind === "pcascore" || kind === "pcaload" || kind === "pcabiplot" || kind === "triplot") return buildPcaScatterScene(table, plot, options, kind);
  if (kind === "scree") return buildScreeScene(table, plot, options);
  if (kind === "dendrogram") return buildDendrogramScene(table, plot, options);

  let width = options.width ?? DEFAULTS.width;
  let height = options.height ?? DEFAULTS.height;
  const palette = options.palette ?? OKABE_ITO;
  const measure = options.measure ?? estimateWidth;
  const warnings: string[] = [];
  // One ramp resolver per scene: built-in ramps, plus any `custom:<id>` gradient the caller's
  // registry supplies. A gradient that no longer exists falls back to viridis and reports
  // itself into `warnings` at resolve time (never a silent substitution).
  const ramps = makeRampResolver(options.gradients, warnings);

  const xCol = xColumn(table);
  const datasets = visibleDatasets(table, plot);
  const xLabel = xCol?.name ?? "X";
  // Simple Column (one grouping factor): each column is a group, so a bar chart draws one
  // bar per column with its replicates pooled — down the rows and across any subcolumns —
  // and the category axis reads the column names. Banded by row instead, a column bar would
  // draw one bar per replicate value, i.e. render as a grouped chart even for a
  // one-factor table. A `grouped` / `contingency` table
  // has a real second factor (the rows), so it keeps the row-as-category layout below. This
  // is the same per-column pooling box / violin / column-scatter already do.
  // …but only when the label (X) column is blank. A simple Column bar has no row categories —
  // the seed's lead column is empty and each column's rows are replicates. If the user filled
  // that column they mean the rows to be categories (a grouped-style bar across labelled rows),
  // so keep the row layout — this is what every labelled `column` table (and the histogram's
  // binned synth) relies on, and it limits this layout to the genuinely lead-less case.
  const xLabelsBlank =
    !xCol || table.rows.every((r) => { const v = r.cells[xCol.id]; return v == null || String(v).trim() === ""; });
  const colMode =
    kind === "bar" && table.kind === "column" && datasets.length > 0 && xLabelsBlank && !options.barRowsAreCategories;
  const layout = plot.barLayout ?? "grouped";
  // Stacked / overlay need a second grouping factor to stack along — a simple Column bar has
  // one bar per category, nothing to stack. Force grouped geometry and say why (no silent no-op).
  if (colMode && layout !== "grouped") {
    warnings.push("Stacked and overlaid layouts need a second grouping factor — a simple Column bar draws one bar per column. Use a Grouped table to stack or overlay.");
  }
  // "percent" (100%-stacked) = the stacked geometry over per-category normalised values —
  // one flag for the maths (pctBars), one for the shared stacked layout machinery.
  const pctBars = !colMode && layout === "percent";
  const stacked = !colMode && (layout === "stacked" || pctBars);
  // Overlay: all series share the centred full-width slot (baseline-anchored, back-to-
  // front). Opposite-sign series → diverging up/down bars. Full width like stacked.
  const overlay = !colMode && layout === "overlay";
  const horiz = (plot.barOrientation ?? "vertical") === "horizontal";

  const errorTypeFor = (ds: Dataset, hasSpread: boolean): ErrorBarType =>
    resolveErrorType(ds, plot.seriesStyles?.[ds.id]?.errorBars ?? defaultErrorType(ds, hasSpread));

  // Individual observations overlaid on bars. Note: default on: a bar alone
  // hides the distribution, which is why most journals now expect the individual points for
  // small n — showing them is the transparent starting point, hiding them the deliberate act.
  const barPointsOn = (plot.showBarPoints ?? true) && !stacked;

  // Categories and per-series values, in one of two layouts:
  //  • colMode  — one category per column; each column stays its own series but draws a
  //               single pooled bar in its own band (the "diagonal": series di is visible
  //               only in category di), so per-column colour / style / click-target survive.
  //  • default  — one category per row; each dataset is a series banded across the rows.
  let cats: { rowId: NodeId; rowNumber: number; label: string }[];
  let valsByDs: CatVal[][];
  let repsByDs: number[][][];

  if (colMode) {
    cats = datasets.map((ds, i) => ({ rowId: ds.id, rowNumber: i + 1, label: ds.name }));
    // Pool every value of a column (all rows × all replicate subcolumns) into one centre ± error.
    const pooled = datasets.map((ds) => {
      const summaryMode = isSummaryDataset(ds);
      const hasSpread = summaryMode || ds.replicates.length >= 2 || table.rows.length >= 2;
      const type = errorTypeFor(ds, hasSpread);
      warnUndrawableError(ds, type, summaryMode, warnings);
      if (summaryMode) {
        // A summary column (mean/SD entered directly) has no raw pool — read its first row.
        const ep = summaryPointForRow(ds, table.rows[0] ?? { id: "", cells: {} }, type);
        return { center: ep.center, low: ep.low, high: ep.high, hasError: ep.hasError, n: ep.n, raw: [] as number[] };
      }
      const raw = ds.replicates
        .flatMap((id) => table.rows.map((row) => toNumber(row.cells[id])))
        .filter((v) => Number.isFinite(v));
      const ep = errorPoint(summarize(raw), type, ERROR_CONF);
      return { center: ep.center, low: ep.low, high: ep.high, hasError: ep.hasError, n: ep.n, raw };
    });
    // Diagonal placement: series di is finite only in category di, so each column owns one
    // full-width bar in its own band. Off-diagonal cells stay non-finite (drawn as nothing).
    valsByDs = datasets.map((_ds, di) =>
      cats.map((_cat, ci) =>
        ci === di
          ? { center: pooled[di]!.center, low: pooled[di]!.low, high: pooled[di]!.high, hasError: pooled[di]!.hasError, n: pooled[di]!.n }
          : { center: NaN, low: NaN, high: NaN, hasError: false, n: 0 },
      ),
    );
    repsByDs = barPointsOn ? datasets.map((_ds, di) => cats.map((_cat, ci) => (ci === di ? pooled[di]!.raw : []))) : [];
  } else {
    // Categories = rows; label from the X cell (else the row number).
    cats = table.rows.map((row, i) => {
      const raw = xCol ? row.cells[xCol.id] : null;
      const label = raw == null || String(raw).trim() === "" ? String(i + 1) : String(raw);
      return { rowId: row.id, rowNumber: i + 1, label };
    });
    // value + error per dataset per category.
    valsByDs = datasets.map((ds) => {
      const summaryMode = isSummaryDataset(ds);
      const hasSpread = summaryMode || ds.replicates.length >= 2;
      const type = errorTypeFor(ds, hasSpread);
      warnUndrawableError(ds, type, summaryMode, warnings);
      return table.rows.map((row) => {
        let ep;
        if (summaryMode) {
          ep = summaryPointForRow(ds, row, type);
        } else {
          ep = errorPoint(summarize(ds.replicates.map((id) => toNumber(row.cells[id]))), type, ERROR_CONF);
        }
        // Stacked bars don't carry per-segment error bars.
        return { center: ep.center, low: ep.low, high: ep.high, hasError: ep.hasError && !stacked, n: ep.n };
      });
    });
    // Raw replicate values per dataset per category, for the "show all points" overlay — the
    // overlay needs the individual observations a summary dataset (mean/SD entered) lacks.
    repsByDs = barPointsOn
      ? datasets.map((ds) =>
          isSummaryDataset(ds)
            ? table.rows.map(() => [])
            : table.rows.map((row) => ds.replicates.map((id) => toNumber(row.cells[id])).filter((v) => Number.isFinite(v))),
        )
      : [];
  }

  // Waterfall sort (plot.barSort): reorder the categories by value — a single series by its
  // own value, grouped/stacked by the category total — before any geometry, so everything
  // downstream (marks, ticks, value labels, rowId-keyed per-bar styles) follows for free.
  // Bracket endpoints store pre-sort indices; `sortPos` remaps them at the bracket maps so a
  // bracket stays attached to its own categories. Three-way series groups refuse with a warning: their
  // clusters are contiguous category runs, and a value sort would tear them apart.
  // `sortPos[originalIndex] = drawn position`; null = no sort.
  let sortPos: number[] | null = null;
  const sortDir = (plot.kind ?? "xy") === "bar" ? plot.barSort ?? "none" : "none";
  if (sortDir !== "none" && cats.length > 1) {
    if (Object.keys(plot.barSeriesGroups ?? {}).length > 0) {
      warnings.push("Sort bars is ignored while series groups are set — sorting would tear the grouped clusters apart.");
    } else {
      const totals = cats.map((_c, ci) =>
        valsByDs.reduce((acc, vd) => {
          const v = vd[ci]!.center;
          return acc + (Number.isFinite(v) ? v : 0);
        }, 0),
      );
      const order = cats.map((_c, i) => i).sort((a, b) => (sortDir === "asc" ? totals[a]! - totals[b]! : totals[b]! - totals[a]!) || a - b);
      sortPos = new Array<number>(cats.length);
      order.forEach((orig, pos) => { sortPos![orig] = pos; });
      cats = order.map((i) => cats[i]!);
      valsByDs = valsByDs.map((vd) => order.map((i) => vd[i]!));
      if (repsByDs.length) repsByDs = repsByDs.map((rd) => order.map((i) => rd[i] ?? []));
    }
  }
  /** Bracket-map category index (1-based, pre-sort) → drawn 0-based position. */
  const catPos = (c: number): number => (sortPos ? sortPos[c - 1] ?? (c - 1) : c - 1);
  // 100%-stacked (barLayout "percent"): normalise each category's positive values to shares
  // of 100 — the relative-abundance bar. Runs after the sort (which orders by raw totals) and
  // before any geometry, so bars, value labels and the y domain all read the shares. A
  // negative value cannot claim a share of a whole, so it draws as 0 — out loud, never silently.
  if (pctBars) {
    let negClamped = 0;
    cats.forEach((_c, ci) => {
      let tot = 0;
      for (const vd of valsByDs) {
        const v = vd[ci]!.center;
        if (Number.isFinite(v)) {
          if (v > 0) tot += v;
          else if (v < 0) negClamped++;
        }
      }
      for (const vd of valsByDs) {
        const cell = vd[ci]!;
        if (!Number.isFinite(cell.center)) continue;
        cell.center = tot > 0 && cell.center > 0 ? (cell.center / tot) * 100 : 0;
      }
    });
    if (negClamped > 0) {
      warnings.push(`${negClamped} negative value(s) draw as 0 in a 100% stacked bar — a negative value cannot claim a share of the whole.`);
    }
  }
  // Ribbons (plot.barRibbons) need stacked segments with facing edges to join — grouped and
  // overlaid bars have neither, and one category has no gutter to span. Refused out loud.
  const ribbonsOn = plot.barRibbons === true && stacked && cats.length >= 2;
  if (plot.barRibbons === true && !stacked) {
    warnings.push("Ribbons connect stacked bars — switch Bars to Stacked or Stacked 100% to draw them.");
  } else if (plot.barRibbons === true && cats.length < 2) {
    warnings.push("Ribbons join a series' segments across categories — with one category there is nothing to connect.");
  }
  const ribbonOpacity = Math.max(0, Math.min(1, plot.barRibbonOpacity ?? 0.45));
  // Note: warn only when the overlay was asked for explicitly. The rule is that a control
  // which changes nothing must say why — but with the overlay on by default, that rule
  // would fire on every summary-entered or stacked bar chart in the project, warning about
  // a control the user never touched. A default must not warn repeatedly.
  if (plot.showBarPoints === true) {
    if (stacked) {
      warnings.push("Individual points are not drawn on stacked bars — each segment sits on the one below, so the points would not line up with it.");
    } else if (!repsByDs.some((ds) => ds.some((vals) => vals.length > 0))) {
      warnings.push("No individual points to show — this data is entered as summary values (mean/SD), not as replicates.");
    }
  }

  // Y domain — always includes the 0 baseline; bars autoscale to error reach.
  // A series on the second (Y2) axis scales to its own domain (built below), so it must not
  // stretch the main value axis as well: counting it would squash the other bars under the second
  // series' range, and a second axis for a different unit could not do its job. Both orientations —
  // a horizontal bar draws its second axis along the top. If every series is on Y2 the
  // main axis keeps them (it has nothing else to fit).
  const leftSkipsY2 = datasets.some((ds) => plot.seriesStyles?.[ds.id]?.axis === "y2")
    && datasets.some((ds) => plot.seriesStyles?.[ds.id]?.axis !== "y2");
  const countsOnLeft = (di: number): boolean => !leftSkipsY2 || plot.seriesStyles?.[datasets[di]!.id]?.axis !== "y2";
  const yValues: number[] = [0];
  if (stacked) {
    cats.forEach((_, ci) => {
      let pos = 0;
      let neg = 0;
      datasets.forEach((_, di) => {
        if (!countsOnLeft(di)) return;
        const v = valsByDs[di]![ci]!.center;
        if (Number.isFinite(v)) (v >= 0 ? (pos += v) : (neg += v));
      });
      yValues.push(pos, neg);
    });
  } else {
    valsByDs.forEach((vs, di) =>
      countsOnLeft(di) && vs.forEach((v) => {
        if (Number.isFinite(v.center)) yValues.push(v.center);
        if (v.hasError) {
          if (Number.isFinite(v.low)) yValues.push(v.low);
          if (Number.isFinite(v.high)) yValues.push(v.high);
        }
      }),
    );
  }
  // With series split across the two axes the planner's pooled data-unit heights mean nothing on
  // either — the brackets are placed from the drawn pixels instead (`releasePlannedHeights`).
  const annPlot = leftSkipsY2 ? releasePlannedHeights(plot) : plot;
  yValues.push(...significanceHeadroom(annPlot, yValues));
  // Values a caller-drawn overlay needs the axis to reach (the histogram's distribution-curve
  // peaks) — joined here, before nice(), so the ticks stay round and the curve stays inside.
  for (const v of options.extraYValues ?? []) if (Number.isFinite(v)) yValues.push(v);
  // Bars anchor at 0 → a log Y can't represent that; force linear.
  const ySpec: AxisSpec = plot.yAxis ?? {};
  const yFmt = tickFormat(ySpec);
  // `breaks` (axis cuts) must be threaded into the value scale here — every other builder
  // does. Without them the value scale is built plain, so a configured axis cut would
  // compress nothing and draw no break mark on bar charts.
  const ySpacing: TickSpacing = { majorStep: ySpec.majorStep, minorCount: ySpec.minorCount, breaks: ySpec.breaks };
  const yRev = ySpec.reversed ?? false;
  let yType: ScaleType = options.yScale ?? ySpec.scale ?? plot.yScale ?? "linear";
  if (isLog(yType)) {
    yType = "linear";
    warnings.push("Bar charts use a linear Y axis (anchored at 0).");
  }
  // Auto domain includes the 0 baseline; a manual range overrides it.
  const rawYDom = extent(yValues);
  const autoYDom: [number, number] = [Math.min(0, rawYDom[0]), Math.max(0, rawYDom[1])];
  const manualY = ySpec.min != null || ySpec.max != null;
  const yDom = options.yDomain ?? applyRange(ySpec, autoYDom);
  const exactY = options.yDomain != null || manualY;

  // --- horizontal bars: value axis on X, categories banded down Y ---------
  // --- the optional second value axis ---------------------------------------------------------
  // Decided before the orientation split: a vertical bar draws it down the right, a horizontal bar
  // along the top. A series pinned to axis "y2" (bars, or a plotAs line /
  // points / area overlay) scales to its own domain. Built only when at least one series is on y2.
  // Pareto (plot.paretoLine): a derived cumulative-% line over the bars on the second axis, in the
  // drawn category order (after any Sort bars). Vertical bars only — refused out loud below.
  const paretoOn = kind === "bar" && plot.paretoLine === true && !horiz;
  const y2Ids = new Set(datasets.filter((ds) => plot.seriesStyles?.[ds.id]?.axis === "y2").map((ds) => ds.id));
  // The Pareto line lives on the second axis too (its own 0–100 % scale), so it turns the axis on by itself.
  const hasY2 = y2Ids.size > 0 || paretoOn;
  const y2Spec: AxisSpec = plot.y2Axis ?? {};
  // One second axis, drawn linear. A third axis or a non-linear second axis cannot be drawn
  // here, and both are reachable without the Inspector (agent API, a preset, a saved file) — say so.
  for (const ds of datasets) {
    if (plot.seriesStyles?.[ds.id]?.axis === "y3") {
      warnings.push(`“${ds.name}” asks for a third value axis (Y3), but a bar chart draws one second axis (Y2) — it is plotted on the main axis. Use the second (Y2) axis instead.`);
    }
  }
  if (hasY2 && y2Spec.scale && y2Spec.scale !== "linear") {
    warnings.push(`A ${y2Spec.scale === "probit" ? "probability" : "log"} scale is not available on a bar chart's second (Y2) axis — it is drawn linear.`);
  }
  const y2Values: number[] = [];
  if (hasY2) {
    datasets.forEach((ds, di) => {
      if (!y2Ids.has(ds.id)) return;
      valsByDs[di]!.forEach((v) => {
        if (Number.isFinite(v.center)) y2Values.push(v.center);
        if (v.hasError) {
          if (Number.isFinite(v.low)) y2Values.push(v.low);
          if (Number.isFinite(v.high)) y2Values.push(v.high);
        }
      });
    });
  }
  // A Pareto line pins the second axis to the full 0–100 % (its readout is a share of the whole).
  if (paretoOn) y2Values.push(0, 100);
  // A series drawn as bars or an area on the second axis stands on value 0, exactly as on the main
  // axis — so the second axis must reach 0, or every bar hangs outside the plot over the category
  // names. A line or points series keeps a range fitted to its own values.
  if (datasets.some((ds) => y2Ids.has(ds.id) && ["bars", "area"].includes(plot.seriesStyles?.[ds.id]?.plotAs ?? "bars"))) y2Values.push(0);
  // No typed title: the one series on the second axis names it (as on the XY chart); the Pareto
  // line alone is "Cumulative %"; two or more series, none.
  const y2FallbackTitle = y2Ids.size === 1 ? (datasets.find((ds) => y2Ids.has(ds.id))?.name ?? "") : paretoOn && y2Ids.size === 0 ? "Cumulative %" : "";

  if (horiz) {
    // The Pareto line is drawn on vertical bars only — say so.
    if (kind === "bar" && plot.paretoLine === true) {
      warnings.push("The cumulative % (Pareto) line is drawn on vertical bars only — not on a horizontal bar chart. Flip the chart vertical to see it.");
    }
    const heading = resolveHeading(plot);
    // Transposed: the value axis is drawn on X (bottom) and the category band on Y
    // (left), so the title fonts follow their axis — bottom uses the value spec's
    // (yAxis) title font, left uses the category spec's (xAxis). Keeps the rendered
    // font in step with the data-routed title text / scale (see dataAxisOf).
    const fontsR = resolveFonts(plot);
    const fonts = { ...fontsR, xAxisTitle: fontsR.yAxisTitle, yAxisTitle: fontsR.xAxisTitle };
  const pad = plotPadOf(plot);
    const gridDensity = plot.grid?.density ?? 6;
    const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t;
    // The names are drawn with the Y tick font (the axis the Axis tab's "Category label font" writes), so they are
    // measured with it. Sized from the shared tick font (e.g. 13px) while a 30px per-axis size is drawn, a long
    // name would run far off the left of the figure.
    const catLabelW = Math.max(0, ...cats.map((c) => measure(c.label, fonts.yTick.size)), turnedYLabelsReach(cats.map((c) => c.label), fonts.yTick.size, measure, plot.xAxis?.tickRotation));
    const valTitle = ySpec.title ?? (datasets.length === 1 ? datasets[0]!.name : "");
    const catTitle = plot.xAxis?.title ?? xLabel;
    const rawLegend: LegendEntry[] = datasets.map((d, i) => ({
      label: d.name,
      color: plot.seriesStyles?.[d.id]?.color ?? seriesColor(i, palette),
      select: { as: "series" as const, id: d.id },
      // A bar row keys the bar — a fill block, not a stub+marker (see LegendEntry.swatch); a
      // composite line/points row keeps the stub+marker; an area row is a fill too, so it keeps the block.
      ...(kind === "bar" && !["line", "points"].includes(plot.seriesStyles?.[d.id]?.plotAs ?? "bars") ? { swatch: "bar" as const } : {}),
      // A series drawn as a line draws no markers (model.ts `plotAs`), so its key is the line alone, never a
      // marker beside a bare line.
      ...(kind === "bar" && plot.seriesStyles?.[d.id]?.plotAs === "line" ? { marker: false } : {}),
    }));
    const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);
    const marginLeft = plot.xAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : catLabelW + DEFAULTS.tickLen + 6 + (catTitle ? fonts.axisTitle.size + 6 : 4) + pad.l;
    // Value tick-labels / title sit on the bottom → their spacing comes from the
    // value spec (yAxis), where those edits are routed. The numbers are drawn with the X tick font, so
    // the band is sized from it (a shared font would give 30px numbers the room of 13px ones).
    const marginBottom = plot.yAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN
    : fonts.xTick.size + (plot.yAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + (textBand(fonts.xAxisTitle.size, plot.yAxis?.titleGap ?? 6)) + pad.b;
    // The second axis runs along the top here — its numbers and title take a
    // band above the plot, below any heading or top legend. Its title font is the value axis's.
    const y2Plan = hasY2
      ? planSecondAxis(y2Spec, y2Values, "linear", gridDensity, measure, { tick: fonts.y2Tick.size, title: (fonts.y2AxisTitle ?? fonts.xAxisTitle).size }, y2FallbackTitle, "top")
      : null;
    const y2Top = y2Plan?.margin ?? 0;
    const marginRight = DEFAULTS.marginRight + leg.outsideRightWidth + pad.r;
    const plotX = marginLeft;
    const plotY = DEFAULTS.marginTop + topPad + y2Top;
    // Honour explicit axis lengths (value axis = X width, category band = Y height)
    // exactly like the vertical bar / horizontal box paths, so panel-figure "Align X/Y-axes"
    // (which drives those lengths) aligns flipped bars too.
    width = effectiveWidth(plot, width, marginLeft, marginRight);
    height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad + y2Top, marginBottom);
    const plotW = Math.max(1, width - marginLeft - marginRight);
    const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - y2Top - marginBottom);

    const vb = buildScale(yType, yDom, yRev ? [plotW, 0] : [0, plotW], gridDensity, exactY, yFmt, ySpacing);
    const valDomainOut: [number, number] = yRev ? [vb.domain[1], vb.domain[0]] : vb.domain;
    // The natural "home" domain — the rest state ignoring any pan/zoom window. `auto` must
    // be this and not the windowed domain: the renderer soft-locks back to it,
    // and reads it to know whether the chart is zoomed.
    const homeVH: [number, number] = options.yDomain != null
      ? buildScale(yType, applyRange(ySpec, autoYDom), [0, 1], gridDensity, manualY, yFmt, ySpacing).domain
      : vb.domain;
    const autoVH: [number, number] = yRev ? [homeVH[1], homeVH[0]] : homeVH;
    const valPxMain = (v: number): number => plotX + vb.scale(v);
    const valPx = valPxMain;
    const baselineMain = valPxMain(0);
    // The top second axis: its own left-to-right scale over the same plot width.
    const y2Placed = y2Plan ? placeSecondAxis(y2Plan, { x: plotX, y: plotY, width: plotW, height: plotH }, (fonts.y2AxisTitle ?? fonts.xAxisTitle).size) : null;

    const nn = cats.length;
    const bandH = nn > 0 ? plotH / nn : plotH;
    // Stacked category labels shrink to their band, then thin (as on the paired dot chart): at the
    // requested size a dense figure would draw every label's descender on the next label's
    // ascender. Tall figures are
    // untouched: the fit acts only when the rows are too close.
    const catFit = fitStackedLabels(nn, bandH, fonts.yTick.size);
    if ((plot.xAxis?.tickFont?.size ?? plot.yAxis?.tickFont?.size) !== undefined && catFit.font < fonts.yTick.size) {
      warnings.push(
        `Category labels are drawn at ${catFit.font}px, not the ${fonts.yTick.size}px asked for: ${nn} rows leave no room. A taller figure, or fewer rows, will honour it.`,
      );
    }
    const innerH = bandH * Math.min(1, Math.max(0.1, plot.barWidth ?? 0.82));
    const m = Math.max(1, datasets.length);
    // Three-way grouping (mirror of the vertical path): cluster the datasets down the band.
    const hGrouping = stacked || overlay || colMode ? null : barSeriesGroupLayout(datasets, plot.barSeriesGroups, innerH);
    const barH = hGrouping ? hGrouping.barSize : (stacked || overlay || colMode ? innerH : innerH / m);
    if (hGrouping) warnings.push("Outer group labels are drawn on vertical bars; on a horizontal bar the clusters are spaced but not labelled.");
    // The bar-end value numbers are stacked down the chart one per bar, so they follow the same fit as the names — shrink to
    // the gap between neighbouring bars, thin past the readable floor (e.g. 45 rows × 3 series, bars 3 px apart, would
    // otherwise pile full-size numbers onto each other). A stacked / overlaid / single-column bar has one
    // number per row, and so does a single series: its numbers are a whole row apart, not a bar's thickness. A figure
    // with room keeps the full size. Only a series that keeps its bars draws these numbers: one drawn as dots, a line or
    // an area loses its bars (`compositeOverlay`) and its values ride on the dots as point labels, which their own placer
    // keeps apart - so they are not counted: a chart of dots alone keeps the size asked for (e.g. ranked dots). Beside
    // bars they shrink with the bar numbers: at full size, e.g., 45 dot numbers cannot all be placed clear.
    const drawsBarNumbers = (id: string): boolean => {
      const as = plot.seriesStyles?.[id]?.plotAs;
      return !(as === "line" || as === "points" || as === "area") || (stacked && as !== "line");
    };
    const barNumberSeries = datasets.filter((ds) => drawsBarNumbers(ds.id)).length;
    const oneLabelPerRow = stacked || overlay || colMode || barNumberSeries === 1;
    const valFit = plot.showValues && barNumberSeries > 0
      ? fitStackedLabels(nn * (oneLabelPerRow ? 1 : m), oneLabelPerRow ? bandH : barH, fonts.valueLabel.size)
      : { font: fonts.valueLabel.size, keep: null as Set<number> | null };
    if (plot.showValues && plot.fonts?.valueLabel?.size !== undefined && valFit.font < fonts.valueLabel.size) {
      warnings.push(`Bar values are drawn at ${valFit.font}px, not the ${fonts.valueLabel.size}px asked for: the bars are too close together. A taller figure, or fewer rows, will honour it.`);
    }

    const series: SeriesScene[] = datasets.map((ds, di) => {
      const style = plot.seriesStyles?.[ds.id];
      const color = style?.color ?? seriesColor(di, palette);
      // A series on the top second axis draws against it. These two shadow the main axis's `valPx` /
      // `baselineX` for the rest of this callback, so the bar / swarm / error code below is
      // unchanged — and like the vertical builder, a second-axis series is never stacked.
      const onY2 = !!y2Placed && y2Ids.has(ds.id);
      const valPx = onY2 ? y2Placed!.px : valPxMain;
      const baselineX = onY2 ? valPx(0) : baselineMain;
      const marks: MarkScene[] = [];
      cats.forEach((cat, ci) => {
        const v = valsByDs[di]![ci]!;
        if (!Number.isFinite(v.center)) {
          // colMode keeps one mark per category (aligned) so bracket / ink lookups that index
          // marks[categoryIndex] still land; an empty mark (no bar / points) draws nothing.
          if (colMode) marks.push({ rowId: cat.rowId, rowNumber: cat.rowNumber, dx: ci + 1, dy: NaN, cx: NaN, cy: NaN, n: 0, label: cat.label });
          return;
        }
        const bandTop = plotY + ci * bandH + (bandH - innerH) / 2;
        let barY: number;
        let leftEnd: number;
        let valEnd: number;
        let h: number;
        if (stacked && !onY2) {
          let base = 0;
          for (let k = 0; k < di; k++) {
            const pv = valsByDs[k]![ci]!.center;
            if (Number.isFinite(pv) && pv >= 0 === v.center >= 0) base += pv;
          }
          barY = bandTop;
          leftEnd = valPx(base);
          valEnd = valPx(base + v.center);
          h = innerH;
        } else if (overlay || stacked) {
          // every series shares the centred full-width slot (baseline-anchored →
          // opposite-sign series diverge left/right of the zero line).
          // A second-axis series on a stacked chart reaches here too: it is not stacked, and the
          // grouped offset below (`di * barH`, with barH = the whole slot when stacked) would push
          // it into another category's band — so it takes the whole slot as well.
          barY = bandTop;
          leftEnd = baselineX;
          valEnd = valPx(v.center);
          h = innerH;
        } else {
          barY = bandTop + (colMode ? 0 : hGrouping ? hGrouping.slotOffset[di]! : di * barH);
          leftEnd = baselineX;
          valEnd = valPx(v.center);
          h = barH;
        }
        const mark: MarkScene = {
          rowId: cat.rowId,
          rowNumber: cat.rowNumber,
          dx: ci + 1,
          dy: v.center,
          cx: valEnd,
          cy: barY + h / 2,
          n: v.n,
          label: cat.label,
          // A series' own width (`SeriesStyle.barWidth`): thinner, around the same centre line.
          bar: style?.barWidth !== undefined
            ? (() => { const t = h * Math.min(1, Math.max(0.1, style.barWidth)); return { x: Math.min(leftEnd, valEnd), y: barY + (h - t) / 2, w: Math.abs(valEnd - leftEnd), h: t }; })()
            : { x: Math.min(leftEnd, valEnd), y: barY, w: Math.abs(valEnd - leftEnd), h },
          // Thinned past the readable floor (see valFit): this bar's number is not drawn.
          ...(valFit.keep && !valFit.keep.has(oneLabelPerRow ? ci : ci * m + di) ? { valueText: "" } : {}),
        };
        // Horizontal bars: the value axis is X, so the swarm spreads down the bar's
        // thickness instead (swarmPoints' `horizontal` mode).
        if (barPointsOn || (style?.plotAs === "points" && !stacked)) {
          const vals = repsByDs[di]?.[ci] ?? [];
          if (vals.length) mark.points = swarmPoints(vals, barY + h / 2, (mark.bar?.h ?? h) / 2, valPx, yType, true, seriesPointSpread(plot, style));
        }
        if (v.hasError) {
          if (Number.isFinite(v.low)) mark.errLowCx = valPx(v.low);
          if (Number.isFinite(v.high)) mark.errHighCx = valPx(v.high);
          mark.errLow = v.low;
          mark.errHigh = v.high;
        }
        marks.push(mark);
      });
      paintGraduated(marks.map((mm, i) => ({ mark: mm, v: gradValue(style?.gradMap, mm, i) })), style, color, undefined, ramps);
      // Ribbons, transposed: adjacent categories are vertical neighbours here, so the band
      // runs from this bar's bottom edge down to the next bar's top edge (see the vertical
      // builder's ribbon block for the contract).
      let ribbonPath = "";
      if (ribbonsOn && !onY2) {
        const byCat = new Map(marks.filter((mm) => mm.bar).map((mm) => [mm.dx, mm.bar!]));
        const parts: string[] = [];
        for (let ci = 1; ci < nn; ci++) {
          const a = byCat.get(ci);
          const b = byCat.get(ci + 1);
          if (!a || !b) continue;
          parts.push(alluvialBandV(a.y + a.h, a.x, a.x + a.w, b.y, b.x, b.x + b.w));
        }
        ribbonPath = parts.join(" ");
      }
      // Composite (bars + line / points / area), transposed: the value axis is X, so the
      // overlay runs down the categories and the area fills from the value-0 X back to each
      // value — against the top second axis when the series sits on it (`valPx` / `baselineX` above).
      const { overlayLine, areaPath } = compositeOverlay(marks, style, ds.name, warnings, stacked, baselineX, true, { show: plot.showValues === true, decimals: plot.valueDecimals });
      return {
        id: ds.id,
        name: ds.name,
        color,
        linePath: "",
        overlayLine,
        ...(areaPath ? { areaPath } : {}),
        symbol: style?.symbol ?? "circle",
        symbolSize: style?.symbolSize ?? 4,
        ...(ribbonPath
          ? { bandPath: ribbonPath, bandOpacity: ribbonOpacity, bandColor: style?.bandColor ?? color }
          : {}),
        // Same point/bar separation as the vertical builder, so a horizontal bar's dots follow
        // the same colour precedence and take the bar's fill.
        ...resolveSymbol(pointStyleOf(style), pointBaseOf(style, color)),
        borderWidth: style?.borderWidth ?? 1.5,
        lineWidth: style?.lineWidth ?? 2,
        // A bar series drawn as a line (`plotAs`) takes its Pattern, so the line follows the Pattern row. Bars draw
        // no series line, so the dash touches nothing else.
        dash: dashArray(style?.lineDash ?? "solid", style?.lineWidth ?? 2),
        // The series' own value-label colour / size (a series drawn as points labels its dots through `showValues`);
        // passed on here, or the labels would be drawn in the series colour instead of their own.
        ...(style?.pointLabelColor ? { pointLabelColor: style.pointLabelColor } : {}),
        ...(style?.pointLabelSize !== undefined ? { pointLabelSize: style.pointLabelSize } : {}),
        errorCaps: style?.errorCaps ?? true,
        errorDir: style?.errorDir ?? "both",
        ...seriesExtras(style, color, style?.lineWidth ?? 2, style?.symbolSize ?? 4, 0.9),
        // Same de-coupling as the vertical builder above — the cap follows the bar's
        // thickness, not the size of the individual-points swarm drawn over it.
        ...(style?.errorCapWidth === undefined
          ? { errorCapWidth: Math.max(3, Math.min(14, barH * 0.4)) }
          : {}),
        symbolBorderWidth: style?.symbolBorderWidth ?? 1.5,
        marks,
      };
    });

    const yticks: AxisTick[] = cats.map((cat, ci) => ({
      value: ci + 1,
      pos: plotY + ci * bandH + bandH / 2,
      // A thinned label keeps its text on the tick: category grouping and identity run off it.
      label: catFit.keep && !catFit.keep.has(ci) ? "" : cat.label,
      ...(catFit.keep && !catFit.keep.has(ci) ? { suppressedLabel: cat.label } : {}),
      minor: false,
    }));
    const xticksV: AxisTick[] = vb.ticks.map((t) => ({ ...t, pos: plotX + t.pos }));

    // Annotations transposed: a value reference line is vertical (value on X);
    // brackets span categories along Y at a value-height on X.
    const valAnn = (v: number): number | undefined => (Number.isFinite(v) ? valPx(v) : undefined);
    const catY = (c: number): number | undefined =>
      c >= 1 && c <= nn ? plotY + catPos(c) * bandH + bandH / 2 : undefined;
    // Sub-bar centre inside a category (within-group bracket endpoint) — grouped layout
    // only: stacked/overlay bars share one slot, so there is no side-by-side position.
    const cellY = (c: number, s: number): number | undefined =>
      c >= 1 && c <= nn && s >= 1 && s <= m
        ? plotY + catPos(c) * bandH + (bandH - innerH) / 2 + (s - 1) * barH + barH / 2
        : undefined;
    // The farthest ink along the value axis (pixel x — larger is farther right) at a bracket
    // endpoint: bar end, error-bar tip, swarm point — see the vertical builder's `inkTop`.
    const inkFar = (c: number, s: number | undefined): number | undefined => {
      if (!(c >= 1 && c <= nn)) return undefined;
      const pick = s == null ? series : s >= 1 && s <= m ? [series[s - 1]!] : [];
      let best: number | undefined;
      for (const se of pick) {
        const mk = se.marks[catPos(c)];
        if (!mk) continue;
        const xs: number[] = [];
        if (mk.bar) xs.push(mk.bar.x + mk.bar.w);
        if (mk.errHighCx != null) xs.push(mk.errHighCx);
        if (mk.errLowCx != null) xs.push(mk.errLowCx);
        for (const pt of mk.points ?? []) xs.push(pt.cx + (se.symbolSize ?? 4));
        for (const x of xs) if (Number.isFinite(x) && (best === undefined || x > best)) best = x;
      }
      return best;
    };
    const annotations = buildAnnotations(
      annPlot,
      { x: plotX, y: plotY, width: plotW, height: plotH },
      { x: valAnn, y: valAnn, bracketX: catY, ...(stacked || overlay ? {} : { bracketCellX: cellY }), bracketTop: inkFar },
      true,
      warnings,
    );

    return {
      width,
      height,
      plot: { x: plotX, y: plotY, width: plotW, height: plotH },
      // Transposed: the value spec (yAxis) governs the X-drawn value axis and the
      // category spec (xAxis) the Y-drawn band — so flipped-graph edits land on the
      // axis the user sees (see dataAxisOf in the model).
      x: { type: yType, domain: valDomainOut, range: [plotX, plotX + plotW], ticks: xticksV, title: valTitle, ...axisLine(plot.yAxis), ...(vb.breakMarks?.length ? { breakMarks: vb.breakMarks.map((p) => plotX + p), breakStyle: ySpec.breakStyle ?? "slash", segments: (vb.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotX + vb.scale(s.from), p1: plotX + vb.scale(s.to) })) } : {}) },
      y: { type: "linear", band: true, domain: [0, Math.max(1, nn)], range: [plotY + plotH, plotY], ticks: yticks, title: catTitle, ...axisLine(plot.xAxis) },
      // The second value axis, drawn along the top (`side: "top"`) — present only with a series on it.
      ...(y2Placed ? { y2: y2Placed.axis } : {}),
      auto: { x: autoVH, y: [0, Math.max(1, nn)] },
      // Horizontal bars: values drawn along X, scale built from `options.yDomain` (the value
      // spec stays `plot.yAxis` when a bar chart is flipped — dataAxisOf).
      zoomable: [{ visual: "x", key: "y" }],
      series,
      legend: leg.entries,
      legendLayout: leg.layout,
      annotations,
      valueAxis: "x" as const,
      grid: {
        show: plot.grid?.show ?? true,
        color: plot.grid?.color ?? null,
        width: plot.grid?.width ?? 1,
        dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
        minor: plot.grid?.minor ?? false,
      } satisfies GridScene,
      axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
      title: heading.title,
      subtitle: heading.subtitle,
      axisLabels: { x: valTitle || "Value", y: catTitle },
      kind,
      fonts: {
        ...fonts,
        ...(catFit.font < fonts.yTick.size ? { yTick: { ...fonts.yTick, size: catFit.font } } : {}),
        ...(valFit.font < fonts.valueLabel.size ? { valueLabel: { ...fonts.valueLabel, size: valFit.font } } : {}),
      },
      barShape: plot.barShape ?? "square",
      barHorizontal: true,
      ...(kind === "bar" && plot.showValues
        ? { valueLabels: { show: true, decimals: plot.valueDecimals, dy: plot.valueLabelDy ?? 0, placement: plot.valuePlacement } }
        : {}),
      warnings,
    };
  }

  const gridDensity = plot.grid?.density ?? 6;
  const heading = resolveHeading(plot);
  const fonts = resolveFonts(plot);
  const pad = plotPadOf(plot);
  const yProbe = buildScale(yType, yDom, [0, 1], gridDensity, exactY, yFmt, ySpacing);
  const yLabelWidth = yTickLabelsWidth(yProbe.ticks, fonts.yTick.size, measure, plot.yAxis);
  const yLabel = ySpec.title ?? (datasets.length === 1 ? datasets[0]!.name : "");
  // Pareto: `paretoOn` is decided above the orientation split, with the rest of the second axis.
  const paretoColor = plot.paretoLineColor ?? "#c0392b";
  const rawLegend: LegendEntry[] = datasets.map((d, i) => ({
    label: d.name,
    color: plot.seriesStyles?.[d.id]?.color ?? seriesColor(i, palette),
    select: { as: "series" as const, id: d.id },
    // A bar row keys the bar — a fill block, not a stub+marker (see LegendEntry.swatch); a
    // composite line/points row keeps the stub+marker; an area row is a fill too, so it keeps the block.
    ...(kind === "bar" && !["line", "points"].includes(plot.seriesStyles?.[d.id]?.plotAs ?? "bars") ? { swatch: "bar" as const } : {}),
    // A series drawn as a line draws no markers (model.ts `plotAs`), so its key is the line alone, never a
    // marker beside a bare line.
    ...(kind === "bar" && plot.seriesStyles?.[d.id]?.plotAs === "line" ? { marker: false } : {}),
  }));
  // The Pareto line keys as a line-only row (no marker — the line draws none) that opens the
  // Chart-type block where it is toggled and recoloured.
  if (paretoOn) rawLegend.push({ label: "Cumulative %", color: paretoColor, marker: false, select: { as: "section", id: "Chart type" } });
  const leg = resolveLegend(plot, rawLegend, measure, fonts.legend.size, width);
  const legend = leg.entries;

  // The second axis — decided above the orientation split — runs down the right here. Sized now
  // (it joins the right-margin stack), placed once the plot rectangle exists.
  const y2Plan = hasY2
    ? planSecondAxis(y2Spec, y2Values, "linear", gridDensity, measure, { tick: fonts.y2Tick.size, title: (fonts.y2AxisTitle ?? fonts.yAxisTitle).size }, y2FallbackTitle, "right", width)
    : null;
  const y2Margin = y2Plan?.margin ?? 0;
  // The legend sits outside the Y2 axis (the right-margin stack): tell its layout how much the
  // axis takes, or the renderer parks the first row on the Y2 tick labels (a wide label such as
  // "100" shows it). The XY builder does the same.
  if (y2Margin > 0) leg.layout = { ...leg.layout, outsidePad: y2Margin };

  const marginLeft = plot.yAxis?.hidden
    ? pad.l + HIDDEN_AXIS_MARGIN
    : yLabelWidth + DEFAULTS.tickLen + (plot.yAxis?.tickLabelGap ?? 8) + (yLabel ? textBand(fonts.yAxisTitle.size, plot.yAxis?.titleGap ?? 6) : 4) + pad.l;
  // Three-way grouping active? (validity doesn't depend on innerW, so probe with 1.) Reserve a
  // second label row under the category ticks for the outer group names when it is.
  const vGroupingActive = !stacked && !overlay && !colMode && barSeriesGroupLayout(datasets, plot.barSeriesGroups, 1) !== null;
  const groupLabelReserve = vGroupingActive ? fonts.xTick.size + 5 : 0;
  const marginBottom = plot.xAxis?.hidden
    ? pad.b + HIDDEN_AXIS_MARGIN + groupLabelReserve
    : fonts.xTick.size + (plot.xAxis?.tickLabelGap ?? 6) + DEFAULTS.tickLen + groupLabelReserve + (textBand(fonts.xAxisTitle.size, plot.xAxis?.titleGap ?? 6)) + pad.b;
  // The last category label is centred on its band: half of it hangs past the plot's right
  // edge, and at a large tick font a long label (a histogram's "550–575", say) would run off
  // the canvas. Reserve
  // the part of that half-width the band and the standing margin do not already cover.
  const baseRight = DEFAULTS.marginRight + leg.outsideRightWidth + y2Margin + pad.r;
  const lastCat = cats.length ? cats[cats.length - 1]!.label : "";
  const band0 = Math.max(1, (width - marginLeft - baseRight) / Math.max(1, cats.length));
  const edgeLabelReserve = plot.xAxis?.hidden ? 0 : Math.max(0, measure(lastCat, fonts.xTick.size) / 2 - band0 / 2 - baseRight + 4);
  const marginRight = baseRight + edgeLabelReserve;
  const plotX = marginLeft;
  // Value labels stand above the bars, so the tallest bar's label needs a band of its own font
  // above the plot — without it an enlarged count label (e.g. on UpSet) meets the title.
  // Only when a series still draws a bar. On a bar chart drawn entirely as dots or
  // a line the numbers ride the dots, so this band would stay empty above the plot. Same rule as `applyPlotAs`: line,
  // points and area lose the bar, except on a stacked chart, where points and area are refused and stay bars.
  // Guard: dot-chart-band.test.ts (both directions).
  const anySeriesKeepsBar = datasets.some((ds) => {
    const as = plot.seriesStyles?.[ds.id]?.plotAs;
    return !(as === "line" || (!stacked && (as === "points" || as === "area")));
  });
  const valueLabelReserve = kind === "bar" && plot.showValues && anySeriesKeepsBar && (plot.valuePlacement ?? "above") === "above" ? fonts.valueLabel.size * TEXT_BAND + 2 : 0;
  const topPad = headingPad(heading, fonts.title.size, fonts.subtitle.size) + pad.t + valueLabelReserve;
  const plotY = DEFAULTS.marginTop + topPad;
  width = effectiveWidth(plot, width, marginLeft, marginRight);
  height = effectiveHeight(plot, height, DEFAULTS.marginTop + topPad, marginBottom);
  const plotW = Math.max(1, width - marginLeft - marginRight);
  const plotH = Math.max(1, height - DEFAULTS.marginTop - topPad - marginBottom);

  const yb = buildScale(yType, yDom, yRev ? [0, plotH] : [plotH, 0], gridDensity, exactY, yFmt, ySpacing);
  const yDomainOut: [number, number] = yRev ? [yb.domain[1], yb.domain[0]] : yb.domain;
    // The natural "home" domain — the rest state ignoring any pan/zoom window. `auto` must
  // be this and not the windowed domain: the renderer soft-locks back to it,
  // and reads it to know whether the chart is zoomed.
  const homeV: [number, number] = options.yDomain != null
    ? buildScale(yType, applyRange(ySpec, autoYDom), [0, 1], gridDensity, manualY, yFmt, ySpacing).domain
    : yb.domain;
  const autoV: [number, number] = yRev ? [homeV[1], homeV[0]] : homeV;
  const baselineY = plotY + yb.scale(0);
  // Secondary right-axis scale (same pixel range, its own domain) for the y2 series.
  const y2Placed = y2Plan ? placeSecondAxis(y2Plan, { x: plotX, y: plotY, width: plotW, height: plotH }, (fonts.y2AxisTitle ?? fonts.yAxisTitle).size) : null;

  const n = cats.length;
  const bandW = n > 0 ? plotW / n : plotW;
  const innerW = bandW * Math.min(1, Math.max(0.1, plot.barWidth ?? 0.82)); // category fill fraction
  const m = Math.max(1, datasets.length);
  // Three-way grouping: cluster the datasets by an outer group (null ⇒ ordinary even split).
  const vGrouping = stacked || overlay || colMode ? null : barSeriesGroupLayout(datasets, plot.barSeriesGroups, innerW);
  const barW = vGrouping ? vGrouping.barSize : (stacked || overlay || colMode ? innerW : innerW / m);

  const series: SeriesScene[] = datasets.map((ds, di) => {
    const style = plot.seriesStyles?.[ds.id];
    const color = style?.color ?? seriesColor(di, palette);
    // y2 series (a right-axis overlay line) scale to the secondary domain; everything
    // else keeps the left scale (identical output when there's no y2 series).
    const onY2 = !!y2Placed && y2Ids.has(ds.id);
    const scv = (val: number): number => (onY2 ? y2Placed!.px(val) : plotY + yb.scale(val));
    const marks: MarkScene[] = [];
    cats.forEach((cat, ci) => {
      const v = valsByDs[di]![ci]!;
      if (!Number.isFinite(v.center)) {
        if (colMode) marks.push({ rowId: cat.rowId, rowNumber: cat.rowNumber, dx: ci + 1, dy: NaN, cx: NaN, cy: NaN, n: 0, label: cat.label });
        return;
      }
      const bandLeft = plotX + ci * bandW + (bandW - innerW) / 2;
      let barX: number;
      let barTop: number;
      let barBottom: number;
      if (stacked && !onY2) {
        // stack on the same-sign running total within the category
        let base = 0;
        for (let k = 0; k < di; k++) {
          const pv = valsByDs[k]![ci]!.center;
          if (Number.isFinite(pv) && pv >= 0 === v.center >= 0) base += pv;
        }
        barX = bandLeft;
        barTop = plotY + yb.scale(base + v.center);
        barBottom = plotY + yb.scale(base);
      } else if (overlay || stacked) {
        // every series shares the centred full-width slot (so an overlaid line
        // series also passes through the band centre); baseline-anchored.
        // A second-axis series on a stacked chart reaches here too: it is not
        // stacked, and the grouped offset below (`di * barW`, with barW = the whole slot when stacked)
        // would shift it by whole slots. It takes the whole slot, like every other series here.
        barX = bandLeft;
        barTop = scv(v.center);
        barBottom = onY2 ? scv(0) : baselineY;
      } else {
        barX = bandLeft + (colMode ? 0 : vGrouping ? vGrouping.slotOffset[di]! : di * barW);
        barTop = scv(v.center);
        barBottom = onY2 ? scv(0) : baselineY;
      }
      const mark: MarkScene = {
        rowId: cat.rowId,
        rowNumber: cat.rowNumber,
        dx: ci + 1,
        dy: v.center,
        cx: barX + barW / 2,
        cy: barTop,
        n: v.n,
        label: cat.label,
        // A series' own width (`SeriesStyle.barWidth`, its share of its place): narrower, around the same centre.
        bar: style?.barWidth !== undefined
          ? (() => { const w = barW * Math.min(1, Math.max(0.1, style.barWidth)); return { x: barX + (barW - w) / 2, y: Math.min(barTop, barBottom), w, h: Math.abs(barBottom - barTop) }; })()
          : { x: barX, y: Math.min(barTop, barBottom), w: barW, h: Math.abs(barBottom - barTop) },
      };
      // Individual observations over the bar. Spread across the bar's own width so the
      // swarm reads as belonging to this bar in a grouped chart, and drawn alongside the
      // error bars rather than replacing them. A `plotAs:"points"` series is its swarm, so it
      // gets the dots even when the chart-wide "show points" is off.
      if (barPointsOn || (style?.plotAs === "points" && !stacked)) {
        const vals = repsByDs[di]?.[ci] ?? [];
        if (vals.length) mark.points = swarmPoints(vals, barX + barW / 2, (mark.bar?.w ?? barW) / 2, scv, yType, false, seriesPointSpread(plot, style));
      }
      if (v.hasError) {
        const lo = Number.isFinite(v.low) ? scv(v.low) : undefined;
        const hi = Number.isFinite(v.high) ? scv(v.high) : undefined;
        if (lo !== undefined) mark.errLowCy = lo;
        if (hi !== undefined) mark.errHighCy = hi;
        mark.errLow = v.low;
        mark.errHigh = v.high;
      }
      marks.push(mark);
    });
    // Value-graduated fill: shade each bar by its value/x/order (per dataset, across categories).
    paintGraduated(
      marks.map((m, i) => ({ mark: m, v: gradValue(style?.gradMap, m, i) })),
      style,
      color,
      undefined,
      ramps,
    );
    // Ribbons: join this series' stacked segment to its segment in the next drawn category
    // with a translucent band across the gutter — the alluvial-linked relative-abundance
    // look. Pure rendering of edges the bars already have; rides SeriesScene.bandPath.
    let ribbonPath = "";
    if (ribbonsOn && !onY2) {
      const byCat = new Map(marks.filter((mm) => mm.bar).map((mm) => [mm.dx, mm.bar!]));
      const parts: string[] = [];
      for (let ci = 1; ci < n; ci++) {
        const a = byCat.get(ci);
        const b = byCat.get(ci + 1);
        if (!a || !b) continue;
        parts.push(alluvialBand(a.x + a.w, a.y, a.y + a.h, b.x, b.y, b.y + b.h, false));
      }
      ribbonPath = parts.join(" ");
    }
    // Composite (bars + line / points / area): render this series over the bars instead of as
    // bars. Additive — bar series are untouched; a composite series drops its rects (mark.bar)
    // and emits: "line" → a connecting path through its category values; "points" → its
    // replicate swarm (or one marker at the mean on summary data); "area" → a closed fill from
    // its values down to the baseline plus the line along the top. Stacked/percent layouts
    // refuse points/area out loud (a segment has no centre value of its own).
    const { overlayLine, areaPath } = compositeOverlay(marks, style, ds.name, warnings, stacked, onY2 ? scv(0) : baselineY, false, { show: plot.showValues === true, decimals: plot.valueDecimals });
    return {
      id: ds.id,
      name: ds.name,
      color,
      linePath: "",
      overlayLine,
      ...(areaPath ? { areaPath } : {}),
      symbol: style?.symbol ?? "circle",
      symbolSize: style?.symbolSize ?? 4,
      /**
       * Base hue for the swarm points. "Match the bar" (`linkPointsToBar`) is on unless the
       * user unticks it, so by default this is the bar's fill colour — colour and two-tone
       * tint/shade move together and the dots read as part of the bar they sit on.
       *
       * Unlinked (`linkPointsToBar: false`) the precedence is:
       *   1. the point's own colour (`style.color`) — what "Data points ▸ Colour" writes;
       *   2. else the bar's fill colour, so recolouring a bar re-tints the dots with it
       *      instead of leaving an orange bar carrying grey dots;
       *   3. else the palette colour for this series.
       *
       * Caution: that order matters. Keyed on `color` alone, a bar recolour would leave the
       * dots behind. Keyed on `style?.fillColor ?? color`, the bar's fill would outrank the
       * point's own colour, so "Data points ▸ Colour" would silently do nothing on a bar that
       * has a fill set. `color` already falls back to the palette, so listing `style?.color`
       * first is what makes the point's own choice win once the two are unlinked.
       */
      ...resolveSymbol(pointStyleOf(style), pointBaseOf(style, color)),
      borderWidth: style?.borderWidth ?? 1.5,
      lineWidth: style?.lineWidth ?? 2,
      // A bar series drawn as a line takes its Pattern.
      dash: dashArray(style?.lineDash ?? "solid", style?.lineWidth ?? 2),
      // The series' own value-label colour / size - passed on so the labels keep their own colour.
      ...(style?.pointLabelColor ? { pointLabelColor: style.pointLabelColor } : {}),
      ...(style?.pointLabelSize !== undefined ? { pointLabelSize: style.pointLabelSize } : {}),
      errorCaps: style?.errorCaps ?? true,
      errorDir: style?.errorDir ?? "both",
      // Note: the error-bar cap width must not follow the marker size on a bar chart.
      // `seriesExtras` defaults it to `symbolSize * 0.9`, which is reasonable where the
      // marker is the series (a scatter: caps that scale with the dots read deliberate).
      // On a bar the marker is the individual-points swarm — an overlay with nothing to do
      // with the bar's error bars — so enlarging the data points would silently enlarge the
      // caps. Pinned to the geometry that actually owns them: a fraction of the bar's own
      // width, clamped so it stays visible on a crowded grouped chart and never overhangs
      // the bar. An explicit `errorCapWidth` still wins.
      ...seriesExtras(style, color, style?.lineWidth ?? 2, style?.symbolSize ?? 4, 0.9),
      ...(style?.errorCapWidth === undefined
        ? { errorCapWidth: Math.max(3, Math.min(14, barW * 0.4)) }
        : {}),
      // The swarm points get their own outline width: `borderWidth` above is the bar's
      // contour, and thickening a bar must not thicken every dot drawn on it.
      symbolBorderWidth: style?.symbolBorderWidth ?? 1.5,
      ...(ribbonPath
        ? { bandPath: ribbonPath, bandOpacity: ribbonOpacity, bandColor: style?.bandColor ?? color }
        : {}),
      marks,
    };
  });

  const xticks: AxisTick[] = cats.map((cat, ci) => ({
    value: ci + 1,
    pos: plotX + ci * bandW + bandW / 2,
    label: cat.label,
    minor: false,
  }));

  const catX = (c: number): number | undefined =>
    c >= 1 && c <= n ? plotX + catPos(c) * bandW + bandW / 2 : undefined;
  // Sub-bar centre inside a category (within-group bracket endpoint) — grouped layout
  // only: stacked/overlay bars share one slot, so there is no side-by-side position.
  const cellX = (c: number, s: number): number | undefined =>
    c >= 1 && c <= n && s >= 1 && s <= m
      ? plotX + catPos(c) * bandW + (bandW - innerW) / 2 + (s - 1) * barW + barW / 2
      : undefined;
  /**
   * The highest ink at a bracket endpoint (pixel y — smaller is higher): the bar's top, its
   * error-bar tip and any swarm point, over every visible series in the category (or one
   * sub-bar). Lets a bracket's legs reach down to their own bars (`significance.legs`).
   * Marks are looked up by category index in each series' marks (one mark per category).
   */
  const inkTop = (c: number, s: number | undefined): number | undefined => {
    if (!(c >= 1 && c <= n)) return undefined;
    const pick = s == null ? series : s >= 1 && s <= m ? [series[s - 1]!] : [];
    let best: number | undefined;
    for (const se of pick) {
      const mk = se.marks[catPos(c)];
      if (!mk) continue;
      const ys: number[] = [];
      if (mk.bar) ys.push(mk.bar.y);
      if (mk.errHighCy != null) ys.push(mk.errHighCy);
      if (mk.errLowCy != null) ys.push(mk.errLowCy);
      // A point is a disc, not its centre: clear its radius too (legs must not hit data points).
      for (const pt of mk.points ?? []) ys.push(pt.cy - (se.symbolSize ?? 4));
      for (const y of ys) if (Number.isFinite(y) && (best === undefined || y < best)) best = y;
    }
    return best;
  };
  const annotations = buildAnnotations(
    annPlot,
    { x: plotX, y: plotY, width: plotW, height: plotH },
    { x: null, y: (v) => (Number.isFinite(v) && (!isLog(yType) || v > 0) ? plotY + yb.scale(v) : undefined), bracketX: catX, ...(stacked || overlay ? {} : { bracketCellX: cellX }), bracketTop: inkTop },
    undefined,
    warnings,
  );

  // Secondary right axis (mirrors the left y): drawn when ≥1 series is pinned to it.
  const y2Axis: AxisScene | undefined = y2Placed?.axis;

  // Three-way outer group labels: one per cluster per category band, centred under the cluster's
  // bars, in the reserved row below the category tick labels.
  let vBarGroupLabels: { text: string; x: number; y: number; anchor: "start" | "middle" | "end" }[] | undefined;
  if (vGrouping) {
    const gy = plotY + plotH + DEFAULTS.tickLen + (plot.xAxis?.tickLabelGap ?? 6) + fonts.xTick.size + 4 + fonts.xTick.size * 0.5;
    vBarGroupLabels = [];
    cats.forEach((_, ci) => {
      const bandLeft = plotX + ci * bandW + (bandW - innerW) / 2;
      for (const cl of vGrouping.clusters) vBarGroupLabels!.push({ text: cl.label, x: bandLeft + (cl.x0 + cl.x1) / 2, y: gy, anchor: "middle" });
    });
  }

  // Pareto line: the running total of the category totals, as a % of the whole, in the drawn
  // order — one point per category at the first series' bar centre, on the Y2 (0–100 %) scale.
  // A readout of the bars (negative values count toward the total exactly as they are drawn).
  let paretoLine: ParetoLineScene | undefined;
  if (paretoOn && y2Placed) {
    const totals = cats.map((_c, ci) => valsByDs.reduce((acc, vd) => acc + (Number.isFinite(vd[ci]!.center) ? vd[ci]!.center : 0), 0));
    const grand = totals.reduce((a, b) => a + b, 0);
    const lead = series[0]?.marks ?? [];
    if (grand > 0 && lead.length > 0) {
      let running = 0;
      const points: ParetoLineScene["points"] = [];
      cats.forEach((cat, ci) => {
        running += totals[ci]!;
        const m = lead.find((mk) => mk.dx === ci + 1);
        if (!m || !Number.isFinite(m.cx)) return;
        const value = (running / grand) * 100;
        points.push({ cx: m.cx, cy: y2Placed.px(value), value, label: cat.label });
      });
      if (points.length >= 2) {
        const path = d3line<{ cx: number; cy: number }>().x((p) => p.cx).y((p) => p.cy)(points) ?? "";
        paretoLine = { path, color: paretoColor, width: 2, points };
      }
    } else {
      warnings.push("The cumulative % line needs a positive total to divide by — nothing to draw.");
    }
  }

  return {
    width,
    height,
    plot: { x: plotX, y: plotY, width: plotW, height: plotH },
    ...(paretoLine ? { paretoLine } : {}),
    x: { type: "linear", band: true, domain: [0, Math.max(1, n)], range: [plotX, plotX + plotW], ticks: deOverlapX(xticks, measure, fonts.tick.size), title: plot.xAxis?.title ?? xLabel, ...axisLine(plot.xAxis) },
    y: { type: yType, domain: yDomainOut, range: [plotY + plotH, plotY], ticks: yb.ticks.map((t) => ({ ...t, pos: plotY + t.pos })), title: yLabel, ...axisLine(plot.yAxis), ...(yb.breakMarks?.length ? { breakMarks: yb.breakMarks.map((p) => plotY + p), breakStyle: ySpec.breakStyle ?? "slash", segments: (yb.segments ?? []).map((s) => ({ from: s.from, to: s.to, p0: plotY + yb.scale(s.from), p1: plotY + yb.scale(s.to) })) } : {}) },
    ...(y2Axis ? { y2: y2Axis } : {}),
    auto: { x: [0, Math.max(1, n)], y: autoV },
    // Only the value axis (Y) has a numeric domain to window; X bands the categories.
    // Note: Y2 is not listed: nothing reads a second-axis override, so offering it would zoom
    // the primary scale and leave the right-hand series where they were.
    zoomable: [{ visual: "y", key: "y" }],
    series,
    legend,
    legendLayout: leg.layout,
    annotations,
    grid: {
      show: plot.grid?.show ?? true,
      color: plot.grid?.color ?? null,
      width: plot.grid?.width ?? 1,
      dash: dashArray(plot.grid?.dash ?? "solid", plot.grid?.width ?? 1),
      minor: plot.grid?.minor ?? false,
    } satisfies GridScene,
    axisStyle: { frame: plot.frame ?? "lshape", tickDir: plot.tickDir ?? "out", tickLen: plot.tickLen ?? 5 },
    title: heading.title,
    subtitle: heading.subtitle,
    axisLabels: { x: plot.xAxis?.title ?? xLabel, y: yLabel || "Value" },
    kind,
    fonts,
    barShape: plot.barShape ?? "square",
    ...(kind === "bar" ? { barsPerBand: stacked || overlay || colMode ? 1 : m } : {}),
    ...(vBarGroupLabels && vBarGroupLabels.length ? { barGroupLabels: vBarGroupLabels } : {}),
    ...(kind === "bar" && plot.showValues
      ? { valueLabels: { show: true, decimals: plot.valueDecimals, dy: plot.valueLabelDy ?? 0, placement: plot.valuePlacement } }
      : {}),
    warnings,
  };
}
